window.BibleBooks=window.BibleBooks||{};window.BibleBooks["PHP"]={"book":"PHP","editions":{"hin2017":[[1,1,"मसीह यीशु के दास पौलुस और तीमुथियुस की ओर से सब पवित्र लोगों के नाम, जो मसीह यीशु में होकर फिलिप्पी में रहते हैं, अध्यक्षों और सेवकों समेत,","masīha yīśu ke dāsa paulusa aura tīmuthiyusa kī ora se saba pavitra logoṃ ke nāma, jo masīha yīśu meṃ hokara philippī meṃ rahate haiṃ, adhyakṣoṃ aura sevakoṃ sameta,",null],[1,2,"हमारे पिता परमेश्वर और प्रभु यीशु मसीह की ओर से तुम्हें अनुग्रह और शान्ति मिलती रहे।","hamāre pitā parameśvara aura prabhu yīśu masīha kī ora se tumheṃ anugraha aura śānti milatī rahe.",null],[1,3,"मैं जब जब तुम्हें स्मरण करता हूँ, तब-तब अपने परमेश्वर का धन्यवाद करता हूँ,","maiṃ jaba jaba tumheṃ smaraṇa karatā hūm̐, taba-taba apane parameśvara kā dhanyavāda karatā hūm̐,",null],[1,4,"और जब कभी तुम सब के लिये विनती करता हूँ, तो सदा आनन्द के साथ विनती करता हूँ","aura jaba kabhī tuma saba ke liye vinatī karatā hūm̐, to sadā ānanda ke sātha vinatī karatā hūm̐",null],[1,5,"इसलिए कि तुम पहले दिन से लेकर आज तक सुसमाचार के फैलाने में मेरे सहभागी रहे हो।","isalie ki tuma pahale dina se lekara āja taka susamācāra ke phailāne meṃ mere sahabhāgī rahe ho.",null],[1,6,"मुझे इस बात का भरोसा है कि जिसने तुम में अच्छा काम आरम्भ किया है, वही उसे यीशु मसीह के दिन तक पूरा करेगा।","mujhe isa bāta kā bharosā hai ki jisane tuma meṃ acchā kāma ārambha kiyā hai, vahī use yīśu masīha ke dina taka pūrā karegā.",null],[1,7,"उचित है कि मैं तुम सब के लिये ऐसा ही विचार करूँ, क्योंकि तुम मेरे मन में आ बसे हो, और मेरी कैद में और सुसमाचार के लिये उत्तर और प्रमाण देने में तुम सब मेरे साथ अनुग्रह में सहभागी हो।","ucita hai ki maiṃ tuma saba ke liye aisā hī vicāra karūm̐, kyoṃki tuma mere mana meṃ ā base ho, aura merī kaida meṃ aura susamācāra ke liye uttara aura pramāṇa dene meṃ tuma saba mere sātha anugraha meṃ sahabhāgī ho.",null],[1,8,"इसमें परमेश्वर मेरा गवाह है कि मैं मसीह यीशु के समान प्रेम करके तुम सब की लालसा करता हूँ।","isameṃ parameśvara merā gavāha hai ki maiṃ masīha yīśu ke samāna prema karake tuma saba kī lālasā karatā hūm̐.",null],[1,9,"और मैं यह प्रार्थना करता हूँ, कि तुम्हारा प्रेम, ज्ञान और सब प्रकार के विवेक सहित और भी बढ़ता जाए,","aura maiṃ yaha prārthanā karatā hūm̐, ki tumhārā prema, jñāna aura saba prakāra ke viveka sahita aura bhī baṛhatā jāe,",null],[1,10,"यहाँ तक कि तुम उत्तम से उत्तम बातों को प्रिय जानो, और मसीह के दिन तक सच्चे बने रहो, और ठोकर न खाओ;","yahām̐ taka ki tuma uttama se uttama bātoṃ ko priya jāno, aura masīha ke dina taka sacce bane raho, aura ṭhokara na khāo;",null],[1,11,"और उस धार्मिकता के फल से जो यीशु मसीह के द्वारा होते हैं, भरपूर होते जाओ जिससे परमेश्वर की महिमा और स्तुति होती रहे। (यशा. 15:8)","aura usa dhārmikatā ke phala se jo yīśu masīha ke dvārā hote haiṃ, bharapūra hote jāo jisase parameśvara kī mahimā aura stuti hotī rahe. (yaśā. 15:8)",null],[1,12,"हे भाइयों, मैं चाहता हूँ, कि तुम यह जान लो कि मुझ पर जो बीता है, उससे सुसमाचार ही की उन्नति हुई है। (2 तीमु. 2:9)","he bhāiyoṃ, maiṃ cāhatā hūm̐, ki tuma yaha jāna lo ki mujha para jo bītā hai, usase susamācāra hī kī unnati huī hai. (2 tīmu. 2:9)",null],[1,13,"यहाँ तक कि कैसर के राजभवन की सारे सैन्य-दल और शेष सब लोगों में यह प्रगट हो गया है कि मैं मसीह के लिये कैद हूँ,","yahām̐ taka ki kaisara ke rājabhavana kī sāre sainya-dala aura śeṣa saba logoṃ meṃ yaha pragaṭa ho gayā hai ki maiṃ masīha ke liye kaida hūm̐,",null],[1,14,"और प्रभु में जो भाई हैं, उनमें से अधिकांश मेरे कैद होने के कारण, साहस बाँधकर, परमेश्वर का वचन बेधड़क सुनाने का और भी साहस करते हैं।","aura prabhu meṃ jo bhāī haiṃ, unameṃ se adhikāṃśa mere kaida hone ke kāraṇa, sāhasa bām̐dhakara, parameśvara kā vacana bedhaṛaka sunāne kā aura bhī sāhasa karate haiṃ.",null],[1,15,"कुछ तो डाह और झगड़े के कारण मसीह का प्रचार करते हैं और कुछ भली मनसा से। (फिलि. 2:3)","kucha to ḍāha aura jhagaṛe ke kāraṇa masīha kā pracāra karate haiṃ aura kucha bhalī manasā se. (phili. 2:3)",null],[1,16,"कई एक तो यह जानकर कि मैं सुसमाचार के लिये उत्तर देने को ठहराया गया हूँ प्रेम से प्रचार करते हैं।","kaī eka to yaha jānakara ki maiṃ susamācāra ke liye uttara dene ko ṭhaharāyā gayā hūm̐ prema se pracāra karate haiṃ.",null],[1,17,"और कई एक तो सिधाई से नहीं पर विरोध से मसीह की कथा सुनाते हैं, यह समझकर कि मेरी कैद में मेरे लिये क्लेश उत्पन्न करें।","aura kaī eka to sidhāī se nahīṃ para virodha se masīha kī kathā sunāte haiṃ, yaha samajhakara ki merī kaida meṃ mere liye kleśa utpanna kareṃ.",null],[1,18,"तो क्या हुआ? केवल यह, कि हर प्रकार से चाहे बहाने से, चाहे सच्चाई से, मसीह की कथा सुनाई जाती है, और मैं इससे आनन्दित हूँ, और आनन्दित रहूँगा भी।","to kyā huā? kevala yaha, ki hara prakāra se cāhe bahāne se, cāhe saccāī se, masīha kī kathā sunāī jātī hai, aura maiṃ isase ānandita hūm̐, aura ānandita rahūm̐gā bhī.",null],[1,19,"क्योंकि मैं जानता हूँ कि तुम्हारी विनती के द्वारा, और यीशु मसीह की आत्मा के दान के द्वारा, इसका प्रतिफल, मेरा उद्धार होगा। (रोम. 8:28)","kyoṃki maiṃ jānatā hūm̐ ki tumhārī vinatī ke dvārā, aura yīśu masīha kī ātmā ke dāna ke dvārā, isakā pratiphala, merā uddhāra hogā. (roma. 8:28)",null],[1,20,"मैं तो यही हार्दिक लालसा और आशा रखता हूँ कि मैं किसी बात में लज्जित न होऊँ, पर जैसे मेरे प्रबल साहस के कारण मसीह की बड़ाई मेरी देह के द्वारा सदा होती रही है, वैसा ही अब भी हो चाहे मैं जीवित रहूँ या मर जाऊँ।","maiṃ to yahī hārdika lālasā aura āśā rakhatā hūm̐ ki maiṃ kisī bāta meṃ lajjita na hoūm̐, para jaise mere prabala sāhasa ke kāraṇa masīha kī baṛāī merī deha ke dvārā sadā hotī rahī hai, vaisā hī aba bhī ho cāhe maiṃ jīvita rahūm̐ yā mara jāūm̐.",null],[1,21,"क्योंकि मेरे लिये जीवित रहना मसीह है, और मर जाना लाभ है।","kyoṃki mere liye jīvita rahanā masīha hai, aura mara jānā lābha hai.",null],[1,22,"पर यदि शरीर में जीवित रहना ही मेरे काम के लिये लाभदायक है तो मैं नहीं जानता कि किसको चुनूँ।","para yadi śarīra meṃ jīvita rahanā hī mere kāma ke liye lābhadāyaka hai to maiṃ nahīṃ jānatā ki kisako cunūm̐.",null],[1,23,"क्योंकि मैं दोनों के बीच असमंजस में हूँ; जी तो चाहता है कि देह-त्याग के मसीह के पास जा रहूँ, क्योंकि यह बहुत ही अच्छा है,","kyoṃki maiṃ donoṃ ke bīca asamaṃjasa meṃ hūm̐; jī to cāhatā hai ki deha-tyāga ke masīha ke pāsa jā rahūm̐, kyoṃki yaha bahuta hī acchā hai,",null],[1,24,"परन्तु शरीर में रहना तुम्हारे कारण और भी आवश्यक है।","parantu śarīra meṃ rahanā tumhāre kāraṇa aura bhī āvaśyaka hai.",null],[1,25,"और इसलिए कि मुझे इसका भरोसा है। अतः मैं जानता हूँ कि मैं जीवित रहूँगा, वरन् तुम सब के साथ रहूँगा, जिससे तुम विश्वास में दृढ़ होते जाओ और उसमें आनन्दित रहो;","aura isalie ki mujhe isakā bharosā hai. ataḥ maiṃ jānatā hūm̐ ki maiṃ jīvita rahūm̐gā, varan tuma saba ke sātha rahūm̐gā, jisase tuma viśvāsa meṃ dṛṛha hote jāo aura usameṃ ānandita raho;",null],[1,26,"और जो घमण्ड तुम मेरे विषय में करते हो, वह मेरे फिर तुम्हारे पास आने से मसीह यीशु में अधिक बढ़ जाए।","aura jo ghamaṇḍa tuma mere viṣaya meṃ karate ho, vaha mere phira tumhāre pāsa āne se masīha yīśu meṃ adhika baṛha jāe.",null],[1,27,"केवल इतना करो कि तुम्हारा चाल-चलन मसीह के सुसमाचार के योग्य हो कि चाहे मैं आकर तुम्हें देखूँ, चाहे न भी आऊँ, तुम्हारे विषय में यह सुनूँ कि तुम एक ही आत्मा में स्थिर हो, और एक चित्त होकर सुसमाचार के विश्वास के लिये परिश्रम करते रहते हो।","kevala itanā karo ki tumhārā cāla-calana masīha ke susamācāra ke yogya ho ki cāhe maiṃ ākara tumheṃ dekhūm̐, cāhe na bhī āūm̐, tumhāre viṣaya meṃ yaha sunūm̐ ki tuma eka hī ātmā meṃ sthira ho, aura eka citta hokara susamācāra ke viśvāsa ke liye pariśrama karate rahate ho.",null],[1,28,"और किसी बात में विरोधियों से भय नहीं खाते। यह उनके लिये विनाश का स्पष्ट चिन्ह है, परन्तु तुम्हारे लिये उद्धार का, और यह परमेश्वर की ओर से है।","aura kisī bāta meṃ virodhiyoṃ se bhaya nahīṃ khāte. yaha unake liye vināśa kā spaṣṭa cinha hai, parantu tumhāre liye uddhāra kā, aura yaha parameśvara kī ora se hai.",null],[1,29,"क्योंकि मसीह के कारण तुम पर यह अनुग्रह हुआ कि न केवल उस पर विश्वास करो पर उसके लिये दुःख भी उठाओ,","kyoṃki masīha ke kāraṇa tuma para yaha anugraha huā ki na kevala usa para viśvāsa karo para usake liye duḥkha bhī uṭhāo,",null],[1,30,"और तुम्हें वैसा ही परिश्रम करना है, जैसा तुम ने मुझे करते देखा है, और अब भी सुनते हो कि मैं वैसा ही करता हूँ।","aura tumheṃ vaisā hī pariśrama karanā hai, jaisā tuma ne mujhe karate dekhā hai, aura aba bhī sunate ho ki maiṃ vaisā hī karatā hūm̐.",null],[2,1,"अतः यदि मसीह में कुछ प्रोत्साहन और प्रेम से ढाढ़स और आत्मा की सहभागिता, और कुछ करुणा और दया हो,","ataḥ yadi masīha meṃ kucha protsāhana aura prema se ḍhāṛhasa aura ātmā kī sahabhāgitā, aura kucha karuṇā aura dayā ho,",null],[2,2,"तो मेरा यह आनन्द पूरा करो कि एक मन रहो और एक ही प्रेम, एक ही चित्त, और एक ही मनसा रखो।","to merā yaha ānanda pūrā karo ki eka mana raho aura eka hī prema, eka hī citta, aura eka hī manasā rakho.",null],[2,3,"स्वार्थ या मिथ्यागर्व के लिये कुछ न करो, पर दीनता से एक दूसरे को अपने से अच्छा समझो।","svārtha yā mithyāgarva ke liye kucha na karo, para dīnatā se eka dūsare ko apane se acchā samajho.",null],[2,4,"हर एक अपने ही हित की नहीं, वरन् दूसरों के हित की भी चिन्ता करे।","hara eka apane hī hita kī nahīṃ, varan dūsaroṃ ke hita kī bhī cintā kare.",null],[2,5,"जैसा मसीह यीशु का स्वभाव था वैसा ही तुम्हारा भी स्वभाव हो;","jaisā masīha yīśu kā svabhāva thā vaisā hī tumhārā bhī svabhāva ho;",null],[2,6,"जिसने परमेश्वर के स्वरूप में होकर भी परमेश्वर के तुल्य होने को अपने वश में रखने की वस्तु न समझा।","jisane parameśvara ke svarūpa meṃ hokara bhī parameśvara ke tulya hone ko apane vaśa meṃ rakhane kī vastu na samajhā.",null],[2,7,"वरन् अपने आपको ऐसा शून्य कर दिया, और दास का स्वरूप धारण किया, और मनुष्य की समानता में हो गया।","varan apane āpako aisā śūnya kara diyā, aura dāsa kā svarūpa dhāraṇa kiyā, aura manuṣya kī samānatā meṃ ho gayā.",null],[2,8,"और मनुष्य के रूप में प्रगट होकर अपने आपको दीन किया, और यहाँ तक आज्ञाकारी रहा कि मृत्यु, हाँ, क्रूस की मृत्यु भी सह ली।","aura manuṣya ke rūpa meṃ pragaṭa hokara apane āpako dīna kiyā, aura yahām̐ taka ājñākārī rahā ki mṛtyu, hām̐, krūsa kī mṛtyu bhī saha lī.",null],[2,9,"इस कारण परमेश्वर ने उसको अति महान भी किया, और उसको वह नाम दिया जो सब नामों में श्रेष्ठ है,","isa kāraṇa parameśvara ne usako ati mahāna bhī kiyā, aura usako vaha nāma diyā jo saba nāmoṃ meṃ śreṣṭha hai,",null],[2,10,"कि जो स्वर्ग में और पृथ्वी पर और जो पृथ्वी के नीचे है; वे सब यीशु के नाम पर घुटना टेकें ,","ki jo svarga meṃ aura pṛthvī para aura jo pṛthvī ke nīce hai; ve saba yīśu ke nāma para ghuṭanā ṭekeṃ ,",null],[2,11,"और परमेश्वर पिता की महिमा के लिये हर एक जीभ अंगीकार कर ले कि यीशु मसीह ही प्रभु है।","aura parameśvara pitā kī mahimā ke liye hara eka jībha aṃgīkāra kara le ki yīśu masīha hī prabhu hai.",null],[2,12,"इसलिए हे मेरे प्रियों, जिस प्रकार तुम सदा से आज्ञा मानते आए हो, वैसे ही अब भी न केवल मेरे साथ रहते हुए पर विशेष करके अब मेरे दूर रहने पर भी डरते और काँपते हुए अपने-अपने उद्धार का कार्य पूरा करते जाओ।","isalie he mere priyoṃ, jisa prakāra tuma sadā se ājñā mānate āe ho, vaise hī aba bhī na kevala mere sātha rahate hue para viśeṣa karake aba mere dūra rahane para bhī ḍarate aura kām̐pate hue apane-apane uddhāra kā kārya pūrā karate jāo.",null],[2,13,"क्योंकि परमेश्वर ही है, जिसने अपनी सुइच्छा निमित्त तुम्हारे मन में इच्छा और काम, दोनों बातों के करने का प्रभाव डाला है।","kyoṃki parameśvara hī hai, jisane apanī suicchā nimitta tumhāre mana meṃ icchā aura kāma, donoṃ bātoṃ ke karane kā prabhāva ḍālā hai.",null],[2,14,"सब काम बिना कुड़कुड़ाए और बिना विवाद के किया करो;","saba kāma binā kuṛakuṛāe aura binā vivāda ke kiyā karo;",null],[2,15,"ताकि तुम निर्दोष और निष्कपट होकर टेढ़े और विकृत लोगों के बीच परमेश्वर के निष्कलंक सन्तान बने रहो, जिनके बीच में तुम जीवन का वचन लिए हुए जगत में जलते दीपकों के समान दिखाई देते हो,","tāki tuma nirdoṣa aura niṣkapaṭa hokara ṭeṛhe aura vikṛta logoṃ ke bīca parameśvara ke niṣkalaṃka santāna bane raho, jinake bīca meṃ tuma jīvana kā vacana lie hue jagata meṃ jalate dīpakoṃ ke samāna dikhāī dete ho,",null],[2,16,"कि मसीह के दिन मुझे घमण्ड करने का कारण हो कि न मेरा दौड़ना और न मेरा परिश्रम करना व्यर्थ हुआ।","ki masīha ke dina mujhe ghamaṇḍa karane kā kāraṇa ho ki na merā dauṛanā aura na merā pariśrama karanā vyartha huā.",null],[2,17,"यदि मुझे तुम्हारे विश्वास के बलिदान और सेवा के साथ अपना लहू भी बहाना पड़े तो भी मैं आनन्दित हूँ, और तुम सब के साथ आनन्द करता हूँ।","yadi mujhe tumhāre viśvāsa ke balidāna aura sevā ke sātha apanā lahū bhī bahānā paṛe to bhī maiṃ ānandita hūm̐, aura tuma saba ke sātha ānanda karatā hūm̐.",null],[2,18,"वैसे ही तुम भी आनन्दित हो, और मेरे साथ आनन्द करो।","vaise hī tuma bhī ānandita ho, aura mere sātha ānanda karo.",null],[2,19,"मुझे प्रभु यीशु में आशा है कि मैं तीमुथियुस को तुम्हारे पास तुरन्त भेजूँगा, ताकि तुम्हारी दशा सुनकर मुझे शान्ति मिले।","mujhe prabhu yīśu meṃ āśā hai ki maiṃ tīmuthiyusa ko tumhāre pāsa turanta bhejūm̐gā, tāki tumhārī daśā sunakara mujhe śānti mile.",null],[2,20,"क्योंकि मेरे पास ऐसे स्वभाव का और कोई नहीं, जो शुद्ध मन से तुम्हारी चिन्ता करे।","kyoṃki mere pāsa aise svabhāva kā aura koī nahīṃ, jo śuddha mana se tumhārī cintā kare.",null],[2,21,"क्योंकि सब अपने स्वार्थ की खोज में रहते हैं, न कि यीशु मसीह की।","kyoṃki saba apane svārtha kī khoja meṃ rahate haiṃ, na ki yīśu masīha kī.",null],[2,22,"पर उसको तो तुम ने परखा और जान भी लिया है कि जैसा पुत्र पिता के साथ करता है, वैसा ही उसने सुसमाचार के फैलाने में मेरे साथ परिश्रम किया।","para usako to tuma ne parakhā aura jāna bhī liyā hai ki jaisā putra pitā ke sātha karatā hai, vaisā hī usane susamācāra ke phailāne meṃ mere sātha pariśrama kiyā.",null],[2,23,"इसलिए मुझे आशा है कि ज्यों ही मुझे जान पड़ेगा कि मेरी क्या दशा होगी, त्यों ही मैं उसे तुरन्त भेज दूँगा।","isalie mujhe āśā hai ki jyoṃ hī mujhe jāna paṛegā ki merī kyā daśā hogī, tyoṃ hī maiṃ use turanta bheja dūm̐gā.",null],[2,24,"और मुझे प्रभु में भरोसा है कि मैं आप भी शीघ्र आऊँगा।","aura mujhe prabhu meṃ bharosā hai ki maiṃ āpa bhī śīghra āūm̐gā.",null],[2,25,"पर मैंने इपफ्रुदीतुस को जो मेरा भाई, और सहकर्मी और संगी योद्धा और तुम्हारा दूत, और आवश्यक बातों में मेरी सेवा टहल करनेवाला है, तुम्हारे पास भेजना अवश्य समझा।","para maiṃne ipaphrudītusa ko jo merā bhāī, aura sahakarmī aura saṃgī yoddhā aura tumhārā dūta, aura āvaśyaka bātoṃ meṃ merī sevā ṭahala karanevālā hai, tumhāre pāsa bhejanā avaśya samajhā.",null],[2,26,"क्योंकि उसका मन तुम सब में लगा हुआ था, इस कारण वह व्याकुल रहता था क्योंकि तुम ने उसकी बीमारी का हाल सुना था।","kyoṃki usakā mana tuma saba meṃ lagā huā thā, isa kāraṇa vaha vyākula rahatā thā kyoṃki tuma ne usakī bīmārī kā hāla sunā thā.",null],[2,27,"और निश्चय वह बीमार तो हो गया था, यहाँ तक कि मरने पर था, परन्तु परमेश्वर ने उस पर दया की; और केवल उस पर ही नहीं, पर मुझ पर भी कि मुझे शोक पर शोक न हो।","aura niścaya vaha bīmāra to ho gayā thā, yahām̐ taka ki marane para thā, parantu parameśvara ne usa para dayā kī; aura kevala usa para hī nahīṃ, para mujha para bhī ki mujhe śoka para śoka na ho.",null],[2,28,"इसलिए मैंने उसे भेजने का और भी यत्न किया कि तुम उससे फिर भेंट करके आनन्दित हो जाओ और मेरा भी शोक घट जाए।","isalie maiṃne use bhejane kā aura bhī yatna kiyā ki tuma usase phira bheṃṭa karake ānandita ho jāo aura merā bhī śoka ghaṭa jāe.",null],[2,29,"इसलिए तुम प्रभु में उससे बहुत आनन्द के साथ भेंट करना, और ऐसों का आदर किया करना,","isalie tuma prabhu meṃ usase bahuta ānanda ke sātha bheṃṭa karanā, aura aisoṃ kā ādara kiyā karanā,",null],[2,30,"क्योंकि वह मसीह के काम के लिये अपने प्राणों पर जोखिम उठाकर मरने के निकट हो गया था, ताकि जो घटी तुम्हारी ओर से मेरी सेवा में हुई उसे पूरा करे।","kyoṃki vaha masīha ke kāma ke liye apane prāṇoṃ para jokhima uṭhākara marane ke nikaṭa ho gayā thā, tāki jo ghaṭī tumhārī ora se merī sevā meṃ huī use pūrā kare.",null],[3,1,"इसलिए हे मेरे भाइयों, प्रभु में आनन्दित रहो। वे ही बातें तुम को बार बार लिखने में मुझे तो कोई कष्ट नहीं होता, और इसमें तुम्हारी कुशलता है।","isalie he mere bhāiyoṃ, prabhu meṃ ānandita raho. ve hī bāteṃ tuma ko bāra bāra likhane meṃ mujhe to koī kaṣṭa nahīṃ hotā, aura isameṃ tumhārī kuśalatā hai.",null],[3,2,"कुत्तों से चौकस रहो, उन बुरे काम करनेवालों से चौकस रहो, उन काट-कूट करनेवालों से चौकस रहो। (2 कुरि. 11:13)","kuttoṃ se caukasa raho, una bure kāma karanevāloṃ se caukasa raho, una kāṭa-kūṭa karanevāloṃ se caukasa raho. (2 kuri. 11:13)",null],[3,3,"क्योंकि यथार्थ खतनावाले तो हम ही हैं जो परमेश्वर के आत्मा की अगुआई से उपासना करते हैं, और मसीह यीशु पर घमण्ड करते हैं और शरीर पर भरोसा नहीं रखते।","kyoṃki yathārtha khatanāvāle to hama hī haiṃ jo parameśvara ke ātmā kī aguāī se upāsanā karate haiṃ, aura masīha yīśu para ghamaṇḍa karate haiṃ aura śarīra para bharosā nahīṃ rakhate.",null],[3,4,"पर मैं तो शरीर पर भी भरोसा रख सकता हूँ। यदि किसी और को शरीर पर भरोसा रखने का विचार हो, तो मैं उससे भी बढ़कर रख सकता हूँ।","para maiṃ to śarīra para bhī bharosā rakha sakatā hūm̐. yadi kisī aura ko śarīra para bharosā rakhane kā vicāra ho, to maiṃ usase bhī baṛhakara rakha sakatā hūm̐.",null],[3,5,"आठवें दिन मेरा खतना हुआ, इस्राएल के वंश, और बिन्यामीन के गोत्र का हूँ; इब्रानियों का इब्रानी हूँ; व्यवस्था के विषय में यदि कहो तो फरीसी हूँ।","āṭhaveṃ dina merā khatanā huā, isrāela ke vaṃśa, aura binyāmīna ke gotra kā hūm̐; ibrāniyoṃ kā ibrānī hūm̐; vyavasthā ke viṣaya meṃ yadi kaho to pharīsī hūm̐.",null],[3,6,"उत्साह के विषय में यदि कहो तो कलीसिया का सतानेवाला; और व्यवस्था की धार्मिकता के विषय में यदि कहो तो निर्दोष था।","utsāha ke viṣaya meṃ yadi kaho to kalīsiyā kā satānevālā; aura vyavasthā kī dhārmikatā ke viṣaya meṃ yadi kaho to nirdoṣa thā.",null],[3,7,"परन्तु जो-जो बातें मेरे लाभ की थीं, उन्हीं को मैंने मसीह के कारण हानि समझ लिया है।","parantu jo-jo bāteṃ mere lābha kī thīṃ, unhīṃ ko maiṃne masīha ke kāraṇa hāni samajha liyā hai.",null],[3,8,"वरन् मैं अपने प्रभु मसीह यीशु की पहचान की उत्तमता के कारण सब बातों को हानि समझता हूँ। जिसके कारण मैंने सब वस्तुओं की हानि उठाई, और उन्हें कूड़ा समझता हूँ, ताकि मैं मसीह को प्राप्त करूँ।","varan maiṃ apane prabhu masīha yīśu kī pahacāna kī uttamatā ke kāraṇa saba bātoṃ ko hāni samajhatā hūm̐. jisake kāraṇa maiṃne saba vastuoṃ kī hāni uṭhāī, aura unheṃ kūṛā samajhatā hūm̐, tāki maiṃ masīha ko prāpta karūm̐.",null],[3,9,"और उसमें पाया जाऊँ; न कि अपनी उस धार्मिकता के साथ, जो व्यवस्था से है, वरन् उस धार्मिकता के साथ जो मसीह पर विश्वास करने के कारण है, और परमेश्वर की ओर से विश्वास करने पर मिलती है,","aura usameṃ pāyā jāūm̐; na ki apanī usa dhārmikatā ke sātha, jo vyavasthā se hai, varan usa dhārmikatā ke sātha jo masīha para viśvāsa karane ke kāraṇa hai, aura parameśvara kī ora se viśvāsa karane para milatī hai,",null],[3,10,"ताकि मैं उसको और उसके पुनरुत्थान की सामर्थ्य को, और उसके साथ दुःखों में सहभागी होने के मर्म को जानूँ, और उसकी मृत्यु की समानता को प्राप्त करूँ।","tāki maiṃ usako aura usake punarutthāna kī sāmarthya ko, aura usake sātha duḥkhoṃ meṃ sahabhāgī hone ke marma ko jānūm̐, aura usakī mṛtyu kī samānatā ko prāpta karūm̐.",null],[3,11,"ताकि मैं किसी भी रीति से मरे हुओं में से जी उठने के पद तक पहुँचूँ।","tāki maiṃ kisī bhī rīti se mare huoṃ meṃ se jī uṭhane ke pada taka pahum̐cūm̐.",null],[3,12,"यह मतलब नहीं कि मैं पा चुका हूँ, या सिद्ध हो चुका हूँ; पर उस पदार्थ को पकड़ने के लिये दौड़ा चला जाता हूँ, जिसके लिये मसीह यीशु ने मुझे पकड़ा था।","yaha matalaba nahīṃ ki maiṃ pā cukā hūm̐, yā siddha ho cukā hūm̐; para usa padārtha ko pakaṛane ke liye dauṛā calā jātā hūm̐, jisake liye masīha yīśu ne mujhe pakaṛā thā.",null],[3,13,"हे भाइयों, मेरी भावना यह नहीं कि मैं पकड़ चुका हूँ; परन्तु केवल यह एक काम करता हूँ, कि जो बातें पीछे रह गई हैं उनको भूलकर, आगे की बातों की ओर बढ़ता हुआ,","he bhāiyoṃ, merī bhāvanā yaha nahīṃ ki maiṃ pakaṛa cukā hūm̐; parantu kevala yaha eka kāma karatā hūm̐, ki jo bāteṃ pīche raha gaī haiṃ unako bhūlakara, āge kī bātoṃ kī ora baṛhatā huā,",null],[3,14,"निशाने की ओर दौड़ा चला जाता हूँ, ताकि वह इनाम पाऊँ, जिसके लिये परमेश्वर ने मुझे मसीह यीशु में ऊपर बुलाया है।","niśāne kī ora dauṛā calā jātā hūm̐, tāki vaha ināma pāūm̐, jisake liye parameśvara ne mujhe masīha yīśu meṃ ūpara bulāyā hai.",null],[3,15,"अतः हम में से जितने सिद्ध हैं, यही विचार रखें, और यदि किसी बात में तुम्हारा और ही विचार हो तो परमेश्वर उसे भी तुम पर प्रगट कर देगा।","ataḥ hama meṃ se jitane siddha haiṃ, yahī vicāra rakheṃ, aura yadi kisī bāta meṃ tumhārā aura hī vicāra ho to parameśvara use bhī tuma para pragaṭa kara degā.",null],[3,16,"इसलिए जहाँ तक हम पहुँचे हैं, उसी के अनुसार चलें।","isalie jahām̐ taka hama pahum̐ce haiṃ, usī ke anusāra caleṃ.",null],[3,17,"हे भाइयों, तुम सब मिलकर मेरी सी चाल चलो, और उन्हें पहचानों, जो इस रीति पर चलते हैं जिसका उदाहरण तुम हम में पाते हो।","he bhāiyoṃ, tuma saba milakara merī sī cāla calo, aura unheṃ pahacānoṃ, jo isa rīti para calate haiṃ jisakā udāharaṇa tuma hama meṃ pāte ho.",null],[3,18,"क्योंकि अनेक लोग ऐसी चाल चलते हैं, जिनकी चर्चा मैंने तुम से बार बार की है और अब भी रो-रोकर कहता हूँ, कि वे अपनी चाल-चलन से मसीह के क्रूस के बैरी हैं,","kyoṃki aneka loga aisī cāla calate haiṃ, jinakī carcā maiṃne tuma se bāra bāra kī hai aura aba bhī ro-rokara kahatā hūm̐, ki ve apanī cāla-calana se masīha ke krūsa ke bairī haiṃ,",null],[3,19,"उनका अन्त विनाश है, उनका ईश्वर पेट है, वे अपनी लज्जा की बातों पर घमण्ड करते हैं, और पृथ्वी की वस्तुओं पर मन लगाए रहते हैं।","unakā anta vināśa hai, unakā īśvara peṭa hai, ve apanī lajjā kī bātoṃ para ghamaṇḍa karate haiṃ, aura pṛthvī kī vastuoṃ para mana lagāe rahate haiṃ.",null],[3,20,"पर हमारा स्वदेश स्वर्ग में है; और हम एक उद्धारकर्ता प्रभु यीशु मसीह के वहाँ से आने की प्रतीक्षा करते हैं।","para hamārā svadeśa svarga meṃ hai; aura hama eka uddhārakartā prabhu yīśu masīha ke vahām̐ se āne kī pratīkṣā karate haiṃ.",null],[3,21,"वह अपनी शक्ति के उस प्रभाव के अनुसार जिसके द्वारा वह सब वस्तुओं को अपने वश में कर सकता है, हमारी दीन-हीन देह का रूप बदलकर, अपनी महिमा की देह के अनुकूल बना देगा।","vaha apanī śakti ke usa prabhāva ke anusāra jisake dvārā vaha saba vastuoṃ ko apane vaśa meṃ kara sakatā hai, hamārī dīna-hīna deha kā rūpa badalakara, apanī mahimā kī deha ke anukūla banā degā.",null],[4,1,"इसलिए हे मेरे प्रिय भाइयों, जिनमें मेरा जी लगा रहता है, जो मेरे आनन्द और मुकुट हो, हे प्रिय भाइयों, प्रभु में इसी प्रकार स्थिर रहो।","isalie he mere priya bhāiyoṃ, jinameṃ merā jī lagā rahatā hai, jo mere ānanda aura mukuṭa ho, he priya bhāiyoṃ, prabhu meṃ isī prakāra sthira raho.",null],[4,2,"मैं यूओदिया से निवेदन करता हूँ, और सुन्तुखे से भी, कि वे प्रभु में एक मन रहें।","maiṃ yūodiyā se nivedana karatā hūm̐, aura suntukhe se bhī, ki ve prabhu meṃ eka mana raheṃ.",null],[4,3,"हे सच्चे सहकर्मी, मैं तुझ से भी विनती करता हूँ, कि तू उन स्त्रियों की सहायता कर, क्योंकि उन्होंने मेरे साथ सुसमाचार फैलाने में, क्लेमेंस और मेरे अन्य सहकर्मियों समेत परिश्रम किया, जिनके नाम जीवन की पुस्तक में लिखे हुए हैं।","he sacce sahakarmī, maiṃ tujha se bhī vinatī karatā hūm̐, ki tū una striyoṃ kī sahāyatā kara, kyoṃki unhoṃne mere sātha susamācāra phailāne meṃ, klemeṃsa aura mere anya sahakarmiyoṃ sameta pariśrama kiyā, jinake nāma jīvana kī pustaka meṃ likhe hue haiṃ.",null],[4,4,"प्रभु में सदा आनन्दित रहो ; मैं फिर कहता हूँ, आनन्दित रहो।","prabhu meṃ sadā ānandita raho ; maiṃ phira kahatā hūm̐, ānandita raho.",null],[4,5,"तुम्हारी कोमलता सब मनुष्यों पर प्रगट हो। प्रभु निकट है।","tumhārī komalatā saba manuṣyoṃ para pragaṭa ho. prabhu nikaṭa hai.",null],[4,6,"किसी भी बात की चिन्ता मत करो; परन्तु हर एक बात में तुम्हारे निवेदन, प्रार्थना और विनती के द्वारा धन्यवाद के साथ परमेश्वर के सम्मुख उपस्थित किए जाएँ।","kisī bhī bāta kī cintā mata karo; parantu hara eka bāta meṃ tumhāre nivedana, prārthanā aura vinatī ke dvārā dhanyavāda ke sātha parameśvara ke sammukha upasthita kie jāem̐.",null],[4,7,"तब परमेश्वर की शान्ति, जो सारी समझ से बिलकुल परे है, तुम्हारे हृदय और तुम्हारे विचारों को मसीह यीशु में सुरक्षित रखेगी। (यशा. 26:3)","taba parameśvara kī śānti, jo sārī samajha se bilakula pare hai, tumhāre hṛdaya aura tumhāre vicāroṃ ko masīha yīśu meṃ surakṣita rakhegī. (yaśā. 26:3)",null],[4,8,"इसलिए, हे भाइयों, जो-जो बातें सत्य हैं, और जो-जो बातें आदरणीय हैं, और जो-जो बातें उचित हैं, और जो-जो बातें पवित्र हैं, और जो-जो बातें सुहावनी हैं, और जो-जो बातें मनभावनी हैं, अर्थात्, जो भी सद्गुण और प्रशंसा की बातें हैं, उन्हीं पर ध्यान लगाया करो।","isalie, he bhāiyoṃ, jo-jo bāteṃ satya haiṃ, aura jo-jo bāteṃ ādaraṇīya haiṃ, aura jo-jo bāteṃ ucita haiṃ, aura jo-jo bāteṃ pavitra haiṃ, aura jo-jo bāteṃ suhāvanī haiṃ, aura jo-jo bāteṃ manabhāvanī haiṃ, arthāt, jo bhī sadguṇa aura praśaṃsā kī bāteṃ haiṃ, unhīṃ para dhyāna lagāyā karo.",null],[4,9,"जो बातें तुम ने मुझसे सीखी, और ग्रहण की, और सुनी, और मुझ में देखीं, उन्हीं का पालन किया करो, तब परमेश्वर जो शान्ति का सोता है तुम्हारे साथ रहेगा।","jo bāteṃ tuma ne mujhase sīkhī, aura grahaṇa kī, aura sunī, aura mujha meṃ dekhīṃ, unhīṃ kā pālana kiyā karo, taba parameśvara jo śānti kā sotā hai tumhāre sātha rahegā.",null],[4,10,"मैं प्रभु में बहुत आनन्दित हूँ कि अब इतने दिनों के बाद तुम्हारा विचार मेरे विषय में फिर जागृत हुआ है; निश्चय तुम्हें आरम्भ में भी इसका विचार था, पर तुम्हें अवसर न मिला।","maiṃ prabhu meṃ bahuta ānandita hūm̐ ki aba itane dinoṃ ke bāda tumhārā vicāra mere viṣaya meṃ phira jāgṛta huā hai; niścaya tumheṃ ārambha meṃ bhī isakā vicāra thā, para tumheṃ avasara na milā.",null],[4,11,"यह नहीं कि मैं अपनी घटी के कारण यह कहता हूँ; क्योंकि मैंने यह सीखा है कि जिस दशा में हूँ, उसी में सन्तोष करूँ।","yaha nahīṃ ki maiṃ apanī ghaṭī ke kāraṇa yaha kahatā hūm̐; kyoṃki maiṃne yaha sīkhā hai ki jisa daśā meṃ hūm̐, usī meṃ santoṣa karūm̐.",null],[4,12,"मैं दीन होना भी जानता हूँ और बढ़ना भी जानता हूँ; हर एक बात और सब दशाओं में मैंने तृप्त होना, भूखा रहना, और बढ़ना-घटना सीखा है।","maiṃ dīna honā bhī jānatā hūm̐ aura baṛhanā bhī jānatā hūm̐; hara eka bāta aura saba daśāoṃ meṃ maiṃne tṛpta honā, bhūkhā rahanā, aura baṛhanā-ghaṭanā sīkhā hai.",null],[4,13,"जो मुझे सामर्थ्य देता है उसमें मैं सब कुछ कर सकता हूँ।","jo mujhe sāmarthya detā hai usameṃ maiṃ saba kucha kara sakatā hūm̐.",null],[4,14,"तो भी तुम ने भला किया कि मेरे क्लेश में मेरे सहभागी हुए।","to bhī tuma ne bhalā kiyā ki mere kleśa meṃ mere sahabhāgī hue.",null],[4,15,"हे फिलिप्पियों, तुम आप भी जानते हो कि सुसमाचार प्रचार के आरम्भ में जब मैंने मकिदुनिया से कूच किया तब तुम्हें छोड़ और किसी कलीसिया ने लेने-देने के विषय में मेरी सहायता नहीं की।","he philippiyoṃ, tuma āpa bhī jānate ho ki susamācāra pracāra ke ārambha meṃ jaba maiṃne makiduniyā se kūca kiyā taba tumheṃ choṛa aura kisī kalīsiyā ne lene-dene ke viṣaya meṃ merī sahāyatā nahīṃ kī.",null],[4,16,"इसी प्रकार जब मैं थिस्सलुनीके में था; तब भी तुम ने मेरी घटी पूरी करने के लिये एक बार क्या वरन् दो बार कुछ भेजा था।","isī prakāra jaba maiṃ thissalunīke meṃ thā; taba bhī tuma ne merī ghaṭī pūrī karane ke liye eka bāra kyā varan do bāra kucha bhejā thā.",null],[4,17,"यह नहीं कि मैं दान चाहता हूँ परन्तु मैं ऐसा फल चाहता हूँ, जो तुम्हारे लाभ के लिये बढ़ता जाए।","yaha nahīṃ ki maiṃ dāna cāhatā hūm̐ parantu maiṃ aisā phala cāhatā hūm̐, jo tumhāre lābha ke liye baṛhatā jāe.",null],[4,18,"मेरे पास सब कुछ है, वरन् बहुतायत से भी है; जो वस्तुएँ तुम ने इपफ्रुदीतुस के हाथ से भेजी थीं उन्हें पाकर मैं तृप्त हो गया हूँ, वह तो सुखदायक सुगन्ध और ग्रहण करने के योग्य बलिदान है, जो परमेश्वर को भाता है। (इब्रा. 13:16)","mere pāsa saba kucha hai, varan bahutāyata se bhī hai; jo vastuem̐ tuma ne ipaphrudītusa ke hātha se bhejī thīṃ unheṃ pākara maiṃ tṛpta ho gayā hūm̐, vaha to sukhadāyaka sugandha aura grahaṇa karane ke yogya balidāna hai, jo parameśvara ko bhātā hai. (ibrā. 13:16)",null],[4,19,"और मेरा परमेश्वर भी अपने उस धन के अनुसार जो महिमा सहित मसीह यीशु में है तुम्हारी हर एक घटी को पूरी करेगा।","aura merā parameśvara bhī apane usa dhana ke anusāra jo mahimā sahita masīha yīśu meṃ hai tumhārī hara eka ghaṭī ko pūrī karegā.",null],[4,20,"हमारे परमेश्वर और पिता की महिमा युगानुयुग होती रहे। आमीन।","hamāre parameśvara aura pitā kī mahimā yugānuyuga hotī rahe. āmīna.",null],[4,21,"हर एक पवित्र जन को जो यीशु मसीह में हैं नमस्कार कहो। जो भाई मेरे साथ हैं तुम्हें नमस्कार कहते हैं।","hara eka pavitra jana ko jo yīśu masīha meṃ haiṃ namaskāra kaho. jo bhāī mere sātha haiṃ tumheṃ namaskāra kahate haiṃ.",null],[4,22,"सब पवित्र लोग, विशेष करके जो कैसर के घराने के हैं तुम को नमस्कार कहते हैं।","saba pavitra loga, viśeṣa karake jo kaisara ke gharāne ke haiṃ tuma ko namaskāra kahate haiṃ.",null],[4,23,"हमारे प्रभु यीशु मसीह का अनुग्रह तुम्हारी आत्मा के साथ रहे।","hamāre prabhu yīśu masīha kā anugraha tumhārī ātmā ke sātha rahe.",null]],"pan":[[1,1,"ਮਸੀਹ ਯਿਸੂ ਦੇ ਦਾਸ ਪੌਲੁਸ ਅਤੇ ਤਿਮੋਥਿਉਸ, ਅੱਗੇ ਯੋਗ ਫ਼ਿਲਿੱਪੈ ਦੇ ਵਿੱਚ ਜਿੰਨੇ ਮਸੀਹ ਯਿਸੂ ਵਿੱਚ ਸੰਤ ਹਨ ਉਨ੍ਹਾਂ ਸਭਨਾਂ ਨੂੰ ਕਲੀਸਿਯਾ ਦੇ ਨਿਗਾਹਬਾਨਾਂ ਅਤੇ ਸੇਵਕਾਂ ਸਣੇ।","masīha yisū dē dāsa paulusa atē timōthiusa, aggē yōga filippai dē vicca jinnē masīha yisū vicca saṁta hana unhāṁ sabhanāṁ nūṁ kalīsiyā dē nigāhabānāṁ atē sēvakāṁ saṇē.",null],[1,2,"ਸਾਡੇ ਪਿਤਾ ਪਰਮੇਸ਼ੁਰ ਅਤੇ ਪ੍ਰਭੂ ਯਿਸੂ ਮਸੀਹ ਦੀ ਵੱਲੋਂ ਤੁਹਾਨੂੰ ਕਿਰਪਾ ਅਤੇ ਸ਼ਾਂਤੀ ਮਿਲਦੀ ਰਹੇ।","sāḍē pitā paramēśura atē prabhū yisū masīha dī vallōṁ tuhānūṁ kirapā atē śāṁtī miladī rahē.",null],[1,3,"ਮੈਂ ਜਦੋਂ ਤੁਹਾਨੂੰ ਯਾਦ ਕਰਦਾ ਹਾਂ ਤਦ ਆਪਣੇ ਪਰਮੇਸ਼ੁਰ ਦਾ ਧੰਨਵਾਦ ਕਰਦਾ ਹਾਂ।","maiṁ jadōṁ tuhānūṁ yāda karadā hāṁ tada āpaṇē paramēśura dā dhannavāda karadā hāṁ.",null],[1,4,"ਅਤੇ ਮੈਂ ਆਪਣੀ ਹਰੇਕ ਬੇਨਤੀ ਵਿੱਚ ਸਦਾ ਤੁਹਾਡੇ ਸਾਰਿਆਂ ਲਈ ਅਨੰਦ ਨਾਲ ਬੇਨਤੀ ਕਰਦਾ ਹਾਂ।","atē maiṁ āpaṇī harēka bēnatī vicca sadā tuhāḍē sāriāṁ laī anaṁda nāla bēnatī karadā hāṁ.",null],[1,5,"ਇਸ ਲਈ ਜੋ ਤੁਸੀਂ ਪਹਿਲੇ ਦਿਨ ਤੋਂ ਹੁਣ ਤੱਕ ਖੁਸ਼ਖਬਰੀ ਦੇ ਫੈਲਾਉਣ ਵਿੱਚ ਮੇਰੇ ਸਾਂਝੀ ਰਹੇ।","isa laī jō tusīṁ pahilē dina tōṁ huṇa takka khuśakhabarī dē phailāuṇa vicca mērē sāṁjhī rahē.",null],[1,6,"ਅਤੇ ਇਸ ਗੱਲ ਦੀ ਮੈਨੂੰ ਭਰੋਸਾ ਹੈ ਕਿ ਜਿਸ ਨੇ ਤੁਹਾਡੇ ਵਿੱਚ ਸ਼ੁਭ ਕੰਮ ਨੂੰ ਸ਼ੁਰੂ ਕੀਤਾ ਸੋ ਯਿਸੂ ਮਸੀਹ ਦੇ ਦਿਨ ਤੱਕ ਉਹ ਨੂੰ ਪੂਰਾ ਕਰੇਗਾ।","atē isa galla dī mainūṁ bharōsā hai ki jisa nē tuhāḍē vicca śubha kamma nūṁ śurū kītā sō yisū masīha dē dina takka uha nūṁ pūrā karēgā.",null],[1,7,"ਇਸ ਲਈ ਤੁਹਾਡੇ ਸਾਰਿਆਂ ਦੇ ਲਈ ਮੈਨੂੰ ਇਹ ਮੰਨਣਾ ਉੱਚਿਤ ਹੈ ਕਿਉਂ ਜੋ ਤੁਸੀਂ ਮੇਰੇ ਦਿਲ ਵਿੱਚ ਹੋ, ਇਸ ਲਈ ਜੋ ਮੇਰੇ ਬੰਧਨਾਂ ਵਿੱਚ, ਨਾਲੇ ਖੁਸ਼ਖਬਰੀ ਦੇ ਨਮਿੱਤ ਉੱਤਰ ਅਤੇ ਪਰਮਾਣ ਦੇਣ ਵਿੱਚ ਤੁਸੀਂ ਸਾਰੇ ਮੇਰੇ ਨਾਲ ਕਿਰਪਾ ਦੇ ਸਾਂਝੀ ਹੋ।","isa laī tuhāḍē sāriāṁ dē laī mainūṁ iha mannaṇā uccita hai kiuṁ jō tusīṁ mērē dila vicca hō, isa laī jō mērē baṁdhanāṁ vicca, nālē khuśakhabarī dē namitta uttara atē paramāṇa dēṇa vicca tusīṁ sārē mērē nāla kirapā dē sāṁjhī hō.",null],[1,8,"ਪਰਮੇਸ਼ੁਰ ਤਾਂ ਮੇਰਾ ਗਵਾਹ ਹੈ, ਜੋ ਮੈਂ ਮਸੀਹ ਯਿਸੂ ਜਿਹਾ ਪਿਆਰ ਕਰਕੇ ਤੁਸੀਂ ਸਭਨਾਂ ਨੂੰ ਕਿੰਨ੍ਹਾਂ ਹੀ ਲੋਚਦਾ ਹਾਂ।","paramēśura tāṁ mērā gavāha hai, jō maiṁ masīha yisū jihā piāra karakē tusīṁ sabhanāṁ nūṁ kinnhāṁ hī lōcadā hāṁ.",null],[1,9,"ਅਤੇ ਮੈਂ ਇਹ ਪ੍ਰਾਰਥਨਾ ਕਰਦਾ ਹਾਂ ਭਈ ਤੁਹਾਡਾ ਪਿਆਰ ਸਮਝ ਅਤੇ ਸਭ ਪਰਕਾਰ ਦੇ ਬਿਬੇਕ ਨਾਲ ਹੋਰ ਤੋਂ ਹੋਰ ਵਧਦਾ ਚੱਲਿਆ ਜਾਵੇ।","atē maiṁ iha prārathanā karadā hāṁ bhaī tuhāḍā piāra samajha atē sabha parakāra dē bibēka nāla hōra tōṁ hōra vadhadā calliā jāvē.",null],[1,10,"ਤੁਸੀਂ ਚੰਗੀ ਚੰਗੇਰੀਆਂ ਗੱਲਾਂ ਨੂੰ ਪਸੰਦ ਕਰੋ ਤਾਂ ਜੋ ਮਸੀਹ ਦੇ ਦਿਨ ਤੱਕ ਨਿਸ਼ਕਪਟ ਅਤੇ ਨਿਰਦੋਸ਼ ਰਹੋ।","tusīṁ caṁgī caṁgērīāṁ gallāṁ nūṁ pasaṁda karō tāṁ jō masīha dē dina takka niśakapaṭa atē niradōśa rahō.",null],[1,11,"ਅਤੇ ਧਾਰਮਿਕਤਾ ਦੇ ਫਲ ਨਾਲ ਜੋ ਯਿਸੂ ਮਸੀਹ ਦੇ ਵਸੀਲੇ ਕਰਕੇ ਹੁੰਦਾ ਹੈ, ਭਰਪੂਰ ਰਹੋ ਭਈ ਪਰਮੇਸ਼ੁਰ ਦੀ ਵਡਿਆਈ ਅਤੇ ਉਸਤਤ ਹੋਵੇ।","atē dhāramikatā dē phala nāla jō yisū masīha dē vasīlē karakē huṁdā hai, bharapūra rahō bhaī paramēśura dī vaḍiāī atē usatata hōvē.",null],[1,12,"ਹੇ ਭਰਾਵੋ, ਮੈਂ ਚਾਹੁੰਦਾ ਹਾਂ ਜੋ ਤੁਸੀਂ ਇਹ ਜਾਣੋ ਕਿ ਮੇਰੇ ਉੱਤੇ ਜੋ ਬੀਤਿਆ ਸੋ ਖੁਸ਼ਖਬਰੀ ਦੇ ਪ੍ਰਸਾਰ ਕਾਰਨ ਹੀ ਹੋਇਆ।","hē bharāvō, maiṁ cāhuṁdā hāṁ jō tusīṁ iha jāṇō ki mērē uttē jō bītiā sō khuśakhabarī dē prasāra kārana hī hōiā.",null],[1,13,"ਇਥੋਂ ਤੱਕ ਜੋ ਪਾਤਸ਼ਾਹ ਦੀ ਸਾਰੀ ਪਲਟਣ ਅਤੇ ਹੋਰ ਸਭਨਾਂ ਉੱਤੇ ਉਜਾਗਰ ਹੋਇਆ ਭਈ ਮੇਰੇ ਬੰਧਨ ਮਸੀਹ ਦੇ ਲਈ ਹਨ।","ithōṁ takka jō pātaśāha dī sārī palaṭaṇa atē hōra sabhanāṁ uttē ujāgara hōiā bhaī mērē baṁdhana masīha dē laī hana.",null],[1,14,"ਅਤੇ ਬਹੁਤੇ ਜੋ ਪ੍ਰਭੂ ਵਿੱਚ ਭਾਈ ਹਨ ਮੇਰੇ ਬੰਧਨਾਂ ਦੇ ਕਾਰਨ ਤਕੜੇ ਹੋ ਕੇ ਪਰਮੇਸ਼ੁਰ ਦਾ ਬਚਨ ਨਿਧੜਕ ਸੁਣਾਉਣ ਲਈ ਹੋਰ ਵੀ ਦਿਲੇਰ ਹੋ ਗਏ ਹਨ।","atē bahutē jō prabhū vicca bhāī hana mērē baṁdhanāṁ dē kārana takaṛē hō kē paramēśura dā bacana nidhaṛaka suṇāuṇa laī hōra vī dilēra hō gaē hana.",null],[1,15,"ਕਈ ਤਾਂ ਖਾਰ ਅਤੇ ਝਗੜੇ ਨਾਲ ਅਤੇ ਕਈ ਭਲੀ ਮਨਸ਼ਾ ਨਾਲ ਵੀ ਮਸੀਹ ਦਾ ਪਰਚਾਰ ਕਰਦੇ ਹਨ।","kaī tāṁ khāra atē jhagaṛē nāla atē kaī bhalī manaśā nāla vī masīha dā paracāra karadē hana.",null],[1,16,"ਇਹ ਤਾਂ ਪਿਆਰ ਨਾਲ ਕਰਦੇ ਹਨ ਇਹ ਜਾਣ ਕੇ ਭਈ ਮੈਂ ਖੁਸ਼ਖਬਰੀ ਲਈ ਉੱਤਰ ਦੇਣ ਨੂੰ ਥਾਪਿਆ ਹੋਇਆ ਹਾਂ।","iha tāṁ piāra nāla karadē hana iha jāṇa kē bhaī maiṁ khuśakhabarī laī uttara dēṇa nūṁ thāpiā hōiā hāṁ.",null],[1,17,"ਪਰ ਓਹ ਨਿਸ਼ਕਪਟਤਾ ਨਾਲ ਨਹੀਂ ਸਗੋਂ ਧੜੇ ਬਾਜ਼ੀ ਨਾਲ ਮਸੀਹ ਦਾ ਪਰਚਾਰ ਕਰਦੇ ਹਨ, ਇਹ ਸਮਝ ਕੇ ਭਈ ਮੇਰੀਆਂ ਬੰਧਨਾਂ ਵਿੱਚ ਮੈਨੂੰ ਹੋਰ ਵੀ ਕਲੇਸ਼ ਪੁਚਾਉਣ।","para ōha niśakapaṭatā nāla nahīṁ sagōṁ dhaṛē bāzī nāla masīha dā paracāra karadē hana, iha samajha kē bhaī mērīāṁ baṁdhanāṁ vicca mainūṁ hōra vī kalēśa pucāuṇa.",null],[1,18,"ਤਾਂ ਕੀ ਹੋਇਆ? ਭਾਵੇਂ ਬਹਾਨੇ ਭਾਵੇਂ ਸਚਿਆਈ ਨਾਲ ਹਰ ਤਰ੍ਹਾਂ ਮਸੀਹ ਦਾ ਪਰਚਾਰ ਹੁੰਦਾ ਹੈ ਅਤੇ ਮੈਂ ਇਸ ਕਾਰਨ ਖੁਸ਼ ਹਾਂ ਅਤੇ ਰਹਾਂਗਾ ਵੀ।","tāṁ kī hōiā? bhāvēṁ bahānē bhāvēṁ saciāī nāla hara tarhāṁ masīha dā paracāra huṁdā hai atē maiṁ isa kārana khuśa hāṁ atē rahāṁgā vī.",null],[1,19,"ਕਿਉਂ ਜੋ ਮੈਂ ਜਾਣਦਾ ਹਾਂ ਕਿ ਤੁਹਾਡੀ ਬੇਨਤੀ ਤੋਂ ਅਤੇ ਯਿਸੂ ਮਸੀਹ ਦੇ ਆਤਮਾ ਦੀ ਸਹਾਇਤਾ ਤੋਂ ਮੇਰਾ ਇਨਾਮ ਮੁਕਤੀ ਹੋਵੇਗਾ।","kiuṁ jō maiṁ jāṇadā hāṁ ki tuhāḍī bēnatī tōṁ atē yisū masīha dē ātamā dī sahāitā tōṁ mērā ināma mukatī hōvēgā.",null],[1,20,"ਮੇਰੀ ਵੱਡੀ ਤਾਂਘ ਅਤੇ ਆਸ ਦੇ ਅਨੁਸਾਰ ਕਿ ਮੈਂ ਕਿਸੇ ਗੱਲ ਵਿੱਚ ਸ਼ਰਮਿੰਦਾ ਨਹੀਂ ਹੋਵਾਂਗਾ, ਸਗੋਂ ਪੂਰੀ ਦਲੇਰੀ ਨਾਲ ਜਿਵੇਂ ਮੇਰੀ ਦੇਹ ਵਿੱਚ ਮਸੀਹ ਦੀ ਵਡਿਆਈ ਹੁੰਦੀ ਆਈ ਹੈ, ਹੁਣ ਉਵੇਂ ਹੀ ਹੁੰਦੀ ਰਹੇ, ਭਾਵੇਂ ਮੈਂ ਜਿਉਂਦਾ ਰਹਾ ਜਾਂ ਮਰ ਜਾਂਵਾਂ।","mērī vaḍḍī tāṁgha atē āsa dē anusāra ki maiṁ kisē galla vicca śaramiṁdā nahīṁ hōvāṁgā, sagōṁ pūrī dalērī nāla jivēṁ mērī dēha vicca masīha dī vaḍiāī huṁdī āī hai, huṇa uvēṁ hī huṁdī rahē, bhāvēṁ maiṁ jiuṁdā rahā jāṁ mara jāṁvāṁ.",null],[1,21,"ਕਿਉਂਕਿ ਜਿਉਣਾ ਮੇਰੇ ਲਈ ਮਸੀਹ ਹੈ ਅਤੇ ਮਰਨਾ ਲਾਭ ਹੈ।","kiuṁki jiuṇā mērē laī masīha hai atē maranā lābha hai.",null],[1,22,"ਪਰ ਜੇ ਸਰੀਰ ਵਿੱਚ ਜਿਉਂਦਾ ਰਹਿਣਾ, ਜੇ ਇਸ ਤੋਂ ਮੈਨੂੰ ਮਿਹਨਤ ਦਾ ਫਲ ਪ੍ਰਾਪਤ ਹੋਵੇ ਤਾਂ ਮੈਂ ਨਹੀਂ ਜਾਣਦਾ ਜੋ ਮੈਂ ਕਿਸਨੂੰ ਚੁਣਾਂ।","para jē sarīra vicca jiuṁdā rahiṇā, jē isa tōṁ mainūṁ mihanata dā phala prāpata hōvē tāṁ maiṁ nahīṁ jāṇadā jō maiṁ kisanūṁ cuṇāṁ.",null],[1,23,"ਪਰ ਮੈਂ ਦੋਹਾਂ ਦੇ ਵਿਚਾਲੇ ਫਸਿਆ ਹੋਇਆ ਹਾਂ। ਮੈਂ ਚਾਹੁੰਦਾ ਹਾਂ ਭਈ ਛੁਟਕਾਰਾ ਪਾਵਾਂ ਅਤੇ ਮਸੀਹ ਦੇ ਕੋਲ ਜਾ ਰਹਾਂ ਕਿਉਂ ਜੋ ਇਹ ਬਹੁਤ ਹੀ ਉੱਤਮ ਹੈ।","para maiṁ dōhāṁ dē vicālē phasiā hōiā hāṁ. maiṁ cāhuṁdā hāṁ bhaī chuṭakārā pāvāṁ atē masīha dē kōla jā rahāṁ kiuṁ jō iha bahuta hī uttama hai.",null],[1,24,"ਪਰ ਸਰੀਰ ਵਿੱਚ ਮੇਰਾ ਰਹਿਣਾ ਤੁਹਾਡੇ ਲਈ ਵਧੇਰੇ ਜ਼ਰੂਰੀ ਹੈ।","para sarīra vicca mērā rahiṇā tuhāḍē laī vadhērē zarūrī hai.",null],[1,25,"ਅਤੇ ਇਸ ਗੱਲ ਦੀ ਪਰਤੀਤ ਹੋਣ ਕਰਕੇ ਮੈਂ ਜਾਣਦਾ ਹਾਂ ਜੋ ਮੈਂ ਜਿਉਂਦਾ ਰਹਾਂਗਾ ਅਤੇ ਤੁਸੀਂ ਸਭਨਾਂ ਦੇ ਨਾਲ ਠਹਿਰਾਂਗਾ ਜਿਸ ਕਰਕੇ ਵਿਸ਼ਵਾਸ ਵਿੱਚ ਤੁਹਾਡੀ ਉਨੱਤੀ ਅਤੇ ਅਨੰਦ ਹੋਵੇ।","atē isa galla dī paratīta hōṇa karakē maiṁ jāṇadā hāṁ jō maiṁ jiuṁdā rahāṁgā atē tusīṁ sabhanāṁ dē nāla ṭhahirāṁgā jisa karakē viśavāsa vicca tuhāḍī unattī atē anaṁda hōvē.",null],[1,26,"ਤਾਂ ਜੋ ਮਸੀਹ ਯਿਸੂ ਵਿੱਚ ਤੁਹਾਡਾ ਅਭਮਾਨ ਜੋ ਮੇਰੇ ਉੱਤੇ ਹੈ, ਉਹ ਤੁਹਾਡੇ ਕੋਲ ਮੇਰੇ ਫੇਰ ਆਉਣ ਕਰਕੇ ਵੱਧ ਜਾਵੇ।","tāṁ jō masīha yisū vicca tuhāḍā abhamāna jō mērē uttē hai, uha tuhāḍē kōla mērē phēra āuṇa karakē vaddha jāvē.",null],[1,27,"ਸਿਰਫ਼ ਤੁਸੀਂ ਮਸੀਹ ਦੀ ਖੁਸ਼ਖਬਰੀ ਦੇ ਯੋਗ ਚਾਲ ਚੱਲੋ ਜੋ ਮੈਂ ਭਾਵੇਂ ਆਣ ਕੇ ਤੁਹਾਨੂੰ ਵੇਖਾਂ ਭਾਵੇਂ ਤੁਹਾਡੇ ਤੋਂ ਦੂਰ ਹੋਵਾਂ, ਪਰ ਤੁਹਾਡੇ ਬਾਰੇ ਇਹ ਸੁਣਾਂ ਕਿ ਤੁਸੀਂ ਇੱਕੋ ਆਤਮਾ ਵਿੱਚ ਦ੍ਰਿੜ੍ਹ ਅਤੇ ਇੱਕੋ ਮਨ ਹੋ ਕੇ ਖੁਸ਼ਖਬਰੀ ਦੇ ਵਿਸ਼ਵਾਸ ਲਈ ਮਿਹਨਤ ਕਰਦੇ ਹੋ।","sirafa tusīṁ masīha dī khuśakhabarī dē yōga cāla callō jō maiṁ bhāvēṁ āṇa kē tuhānūṁ vēkhāṁ bhāvēṁ tuhāḍē tōṁ dūra hōvāṁ, para tuhāḍē bārē iha suṇāṁ ki tusīṁ ikkō ātamā vicca driṛha atē ikkō mana hō kē khuśakhabarī dē viśavāsa laī mihanata karadē hō.",null],[1,28,"ਅਤੇ ਕਿਸੇ ਗੱਲ ਵਿੱਚ ਵਿਰੋਧੀਆਂ ਤੋਂ ਨਹੀਂ ਡਰਦੇ ਹੋ l ਜਿਹੜਾ ਉਹਨਾਂ ਲਈ ਨਾਸ ਦਾ ਪੱਕਾ ਨਿਸ਼ਾਨ ਹੈ, ਪਰ ਤੁਹਾਡੀ ਮੁਕਤੀ ਦਾ, ਅਤੇ ਇਹ ਪਰਮੇਸ਼ੁਰ ਦੀ ਵੱਲੋਂ ਹੈ।","atē kisē galla vicca virōdhīāṁ tōṁ nahīṁ ḍaradē hō l jihaṛā uhanāṁ laī nāsa dā pakkā niśāna hai, para tuhāḍī mukatī dā, atē iha paramēśura dī vallōṁ hai.",null],[1,29,"ਕਿਉਂ ਜੋ ਮਸੀਹ ਦੇ ਕਾਰਨ ਤੁਹਾਡੇ ਉੱਤੇ ਇਹ ਕਿਰਪਾ ਹੋਈ ਜੋ ਤੁਸੀਂ ਨਾ ਕੇਵਲ ਉਸ ਉੱਤੇ ਵਿਸ਼ਵਾਸ ਕਰੋ ਸਗੋਂ ਉਹ ਦੇ ਲਈ ਦੁੱਖ ਵੀ ਝੱਲੋ।","kiuṁ jō masīha dē kārana tuhāḍē uttē iha kirapā hōī jō tusīṁ nā kēvala usa uttē viśavāsa karō sagōṁ uha dē laī dukkha vī jhallō.",null],[1,30,"ਅਤੇ ਤੁਸੀਂ ਇਹੋ ਜਿਹਾ ਜਤਨ ਕਰੋ ਜੋ ਤੁਸੀਂ ਮੈਨੂੰ ਕਰਦਿਆਂ ਡਿੱਠਾ ਅਤੇ ਹੁਣ ਵੀ ਸੁਣਦੇ ਹੋ।","atē tusīṁ ihō jihā jatana karō jō tusīṁ mainūṁ karadiāṁ ḍiṭṭhā atē huṇa vī suṇadē hō.",null],[2,1,"ਸੋ ਜੇ ਮਸੀਹ ਵਿੱਚ ਕੁਝ ਦਿਲਾਸਾ, ਜੇ ਪਿਆਰ ਦੀ ਕੁਝ ਤਸੱਲੀ, ਜੇ ਆਤਮਾ ਦੀ ਕੁਝ ਸਾਂਝ, ਜੇ ਕੁਝ ਦਿਆਲਗੀ ਅਤੇ ਦਰਦਮੰਦੀ ਹੈ।","sō jē masīha vicca kujha dilāsā, jē piāra dī kujha tasallī, jē ātamā dī kujha sāṁjha, jē kujha diālagī atē daradamaṁdī hai.",null],[2,2,"ਤਾਂ ਮੇਰੇ ਅਨੰਦ ਨੂੰ ਪੂਰਾ ਕਰੋ ਕਿ ਤੁਸੀਂ ਇੱਕ ਮਨ ਹੋਵੋ, ਇੱਕੋ ਜਿਹਾ ਪਿਆਰ ਰੱਖੋ, ਇੱਕ ਚਿੱਤ, ਇੱਕ ਮੱਤ ਹੋਵੋ।","tāṁ mērē anaṁda nūṁ pūrā karō ki tusīṁ ikka mana hōvō, ikkō jihā piāra rakkhō, ikka citta, ikka matta hōvō.",null],[2,3,"ਧੜੇਬਾਜ਼ੀਆਂ ਅਥਵਾ ਫੋਕੇ ਘਮੰਡ ਨਾਲ ਕੁਝ ਨਾ ਕਰੋ ਸਗੋਂ ਤੁਸੀਂ ਅਧੀਨਗੀ ਨਾਲ ਇੱਕ ਦੂਏ ਨੂੰ ਆਪਣੇ ਆਪ ਤੋਂ ਉੱਤਮ ਜਾਣੋ।","dhaṛēbāzīāṁ athavā phōkē ghamaṁḍa nāla kujha nā karō sagōṁ tusīṁ adhīnagī nāla ikka dūē nūṁ āpaṇē āpa tōṁ uttama jāṇō.",null],[2,4,"ਤੁਹਾਡੇ ਵਿੱਚੋਂ ਹਰੇਕ ਆਪਣੇ ਹੀ ਹਾਲ ਉੱਤੇ ਨਹੀਂ ਸਗੋਂ ਹਰੇਕ ਦੂਜਿਆਂ ਦੇ ਹਾਲ ਉੱਤੇ ਵੀ ਨਿਗਾਹ ਕਰੇ।","tuhāḍē viccōṁ harēka āpaṇē hī hāla uttē nahīṁ sagōṁ harēka dūjiāṁ dē hāla uttē vī nigāha karē.",null],[2,5,"ਤੁਹਾਡਾ ਉਹੋ ਸੁਭਾਓ ਹੋਵੇ ਜੋ ਮਸੀਹ ਯਿਸੂ ਦਾ ਵੀ ਸੀ।","tuhāḍā uhō subhāō hōvē jō masīha yisū dā vī sī.",null],[2,6,"ਕਿ ਉਸ ਨੇ ਪਰਮੇਸ਼ੁਰ ਦੇ ਸਰੂਪ ਵਿੱਚ ਹੋ ਕੇ ਪਰਮੇਸ਼ੁਰ ਦੇ ਤੁੱਲ ਹੋਣਾ ਕਬਜ਼ੇ ਰੱਖਣ ਦੀ ਚੀਜ਼ ਨਾ ਜਾਣਿਆ।","ki usa nē paramēśura dē sarūpa vicca hō kē paramēśura dē tulla hōṇā kabazē rakkhaṇa dī cīza nā jāṇiā.",null],[2,7,"ਸਗੋਂ ਉਸ ਨੇ ਆਪਣੇ ਆਪ ਨੂੰ ਸੱਖਣਾ (ਜੋ ਕੁਝ ਉਸ ਕੋਲ ਸੀ, ਸਭ ਕੁਝ ਤਿਆਗ ਦਿੱਤਾ) ਕਰਕੇ ਦਾਸ ਦਾ ਰੂਪ ਧਾਰਿਆ ਅਤੇ ਮਨੁੱਖਾਂ ਦੀ ਸੂਰਤ ਵਿੱਚ ਜੰਮਿਆ।","sagōṁ usa nē āpaṇē āpa nūṁ sakkhaṇā (jō kujha usa kōla sī, sabha kujha tiāga dittā) karakē dāsa dā rūpa dhāriā atē manukkhāṁ dī sūrata vicca jammiā.",null],[2,8,"ਅਤੇ ਮਨੁੱਖ ਦੀ ਸ਼ਕਲ ਵਿੱਚ ਪਰਗਟ ਹੋ ਕੇ ਆਪਣੇ ਆਪ ਨੂੰ ਨੀਵਿਆਂ ਕੀਤਾ ਅਤੇ ਮੌਤ ਤੱਕ ਸਗੋਂ ਸਲੀਬ ਦੀ ਮੌਤ ਤੱਕ ਆਗਿਆਕਾਰ ਬਣਿਆ।","atē manukkha dī śakala vicca paragaṭa hō kē āpaṇē āpa nūṁ nīviāṁ kītā atē mauta takka sagōṁ salība dī mauta takka āgiākāra baṇiā.",null],[2,9,"ਇਸ ਕਾਰਨ ਪਰਮੇਸ਼ੁਰ ਨੇ ਵੀ ਉਸ ਨੂੰ ਅੱਤ ਉੱਚਿਆਂ ਕੀਤਾ ਅਤੇ ਉਸ ਨੂੰ ਉਹ ਨਾਮ ਦਿੱਤਾ ਜਿਹੜਾ ਸਭਨਾਂ ਨਾਮਾਂ ਤੋਂ ਉੱਤਮ ਹੈ।","isa kārana paramēśura nē vī usa nūṁ atta ucciāṁ kītā atē usa nūṁ uha nāma dittā jihaṛā sabhanāṁ nāmāṁ tōṁ uttama hai.",null],[2,10,"ਜੋ ਸਵਰਗ ਅਤੇ ਧਰਤੀ ਉੱਤੇ ਅਤੇ ਧਰਤੀ ਦੇ ਹੇਠਾਂ ਹਨ, ਯਿਸੂ ਦੇ ਨਾਮ ਵਿੱਚ ਹਰ ਗੋਡਾ ਨਿਵਾਇਆ ਜਾਵੇ।","jō savaraga atē dharatī uttē atē dharatī dē hēṭhāṁ hana, yisū dē nāma vicca hara gōḍā nivāiā jāvē.",null],[2,11,"ਅਤੇ ਹਰ ਜ਼ਬਾਨ ਪਰਮੇਸ਼ੁਰ ਪਿਤਾ ਦੀ ਵਡਿਆਈ ਲਈ ਮੰਨ ਲਵੇ ਜੋ ਯਿਸੂ ਮਸੀਹ ਪ੍ਰਭੂ ਹੈ।","atē hara zabāna paramēśura pitā dī vaḍiāī laī manna lavē jō yisū masīha prabhū hai.",null],[2,12,"ਇਸ ਲਈ, ਹੇ ਮੇਰੇ ਪਿਆਰਿਓ, ਜਿਵੇਂ ਤੁਸੀਂ ਸਦਾ ਆਗਿਆਕਾਰੀ ਕੀਤੀ, ਸਿਰਫ਼ ਮੇਰੇ ਹੁੰਦਿਆਂ ਨਹੀਂ ਸਗੋਂ ਹੁਣ ਬਹੁਤ ਵਧੀਕ ਮੇਰੇ ਦੂਰ ਹੁੰਦਿਆਂ ਤੁਸੀਂ ਡਰਦੇ ਅਤੇ ਕੰਬਦੇ ਹੋਏ ਆਪਣੀ ਮੁਕਤੀ ਦੇ ਕੰਮ ਨੂੰ ਪੂਰਾ ਕਰੋ।","isa laī, hē mērē piāriō, jivēṁ tusīṁ sadā āgiākārī kītī, sirafa mērē huṁdiāṁ nahīṁ sagōṁ huṇa bahuta vadhīka mērē dūra huṁdiāṁ tusīṁ ḍaradē atē kaṁbadē hōē āpaṇī mukatī dē kamma nūṁ pūrā karō.",null],[2,13,"ਕਿਉਂ ਜੋ ਪਰਮੇਸ਼ੁਰ ਹੀ ਹੈ ਜਿਹੜਾ ਤੁਹਾਡੇ ਵਿੱਚ ਮਨਸ਼ਾ ਤੇ ਅਮਲ ਦੋਹਾਂ ਨੂੰ ਆਪਣੇ ਨੇਕ ਇਰਾਦੇ ਨੂੰ ਪੂਰਾ ਕਰਨ ਲਈ ਪੈਦਾ ਕਰਦਾ ਹੈ।","kiuṁ jō paramēśura hī hai jihaṛā tuhāḍē vicca manaśā tē amala dōhāṁ nūṁ āpaṇē nēka irādē nūṁ pūrā karana laī paidā karadā hai.",null],[2,14,"ਤੁਸੀਂ ਸੱਭੇ ਕੰਮ ਬੁੜ-ਬੁੜ ਅਤੇ ਝਗੜੇ ਕਰਨ ਤੋਂ ਬਿਨ੍ਹਾਂ ਕਰੋ।","tusīṁ sabbhē kamma buṛa-buṛa atē jhagaṛē karana tōṁ binhāṁ karō.",null],[2,15,"ਤਾਂ ਜੋ ਤੁਸੀਂ ਨਿਰਦੋਸ਼ ਅਤੇ ਸਿੱਧੇ ਸਾਧੇ ਹੋ ਕੇ ਵਿੰਗੀ ਟੇਢੀ ਪੀੜ੍ਹੀ ਵਿੱਚ ਪਰਮੇਸ਼ੁਰ ਦੇ ਨਿਰਮਲ ਬਾਲਕ ਬਣੇ ਰਹੋ ਜਿੰਨ੍ਹਾ ਦੇ ਵਿੱਚ ਤੁਸੀਂ ਜੀਵਨ ਦਾ ਬਚਨ ਲੈ ਕੇ ਸੰਸਾਰ ਉੱਤੇ ਜੋਤਾਂ ਵਾਂਗੂੰ ਦਿਸਦੇ ਹੋ,","tāṁ jō tusīṁ niradōśa atē siddhē sādhē hō kē viṁgī ṭēḍhī pīṛhī vicca paramēśura dē niramala bālaka baṇē rahō jinnhā dē vicca tusīṁ jīvana dā bacana lai kē saṁsāra uttē jōtāṁ vāṁgūṁ disadē hō,",null],[2,16,"ਤਾਂ ਜੋ ਮਸੀਹ ਦੇ ਦਿਨ ਮੈਨੂੰ ਅਭਮਾਨ ਕਰਨ ਦਾ ਥਾਂ ਹੋਵੇ ਕਿ ਮੇਰੀ ਦੌੜ ਅਤੇ ਮੇਰੀ ਮਿਹਨਤ ਵਿਅਰਥ ਨਹੀਂ ਗਈ।","tāṁ jō masīha dē dina mainūṁ abhamāna karana dā thāṁ hōvē ki mērī dauṛa atē mērī mihanata viaratha nahīṁ gaī.",null],[2,17,"ਪਰ ਭਾਵੇਂ ਮੈਨੂੰ ਤੁਹਾਡੇ ਵਿਸ਼ਵਾਸ ਦੇ ਬਲੀਦਾਨ ਅਤੇ ਸੇਵਕਾਈ ਦੇ ਨਾਲ ਆਪਣਾ ਲਹੂ ਵੀ ਵਹਾਉਣਾ ਪਵੇ ਤਾਂ ਵੀ ਮੈਂ ਅਨੰਦ ਕਰਦਾ ਹਾਂ ਅਤੇ ਤੁਹਾਡੇ ਨਾਲ ਵੀ ਅਨੰਦ ਹਾਂ।","para bhāvēṁ mainūṁ tuhāḍē viśavāsa dē balīdāna atē sēvakāī dē nāla āpaṇā lahū vī vahāuṇā pavē tāṁ vī maiṁ anaṁda karadā hāṁ atē tuhāḍē nāla vī anaṁda hāṁ.",null],[2,18,"ਇਸੇ ਤਰ੍ਹਾਂ ਤੁਸੀਂ ਵੀ ਅਨੰਦ ਕਰੋ ਅਤੇ ਮੇਰੇ ਨਾਲ ਅਨੰਦ ਕਰੋ l","isē tarhāṁ tusīṁ vī anaṁda karō atē mērē nāla anaṁda karō l",null],[2,19,"ਪਰ ਮੈਨੂੰ ਪ੍ਰਭੂ ਯਿਸੂ ਉੱਤੇ ਇਹ ਆਸ ਹੈ ਜੋ ਤਿਮੋਥਿਉਸ ਨੂੰ ਛੇਤੀ ਤੁਹਾਡੇ ਕੋਲ ਭੇਜਾਂਗਾ ਜੋ ਤੁਹਾਡੀਆਂ ਬੀਤੀਆਂ ਸੁਣਨ ਤੋਂ ਮੇਰਾ ਮਨ ਵੀ ਸ਼ਾਂਤ ਹੋਵੇ।","para mainūṁ prabhū yisū uttē iha āsa hai jō timōthiusa nūṁ chētī tuhāḍē kōla bhējāṁgā jō tuhāḍīāṁ bītīāṁ suṇana tōṁ mērā mana vī śāṁta hōvē.",null],[2,20,"ਕਿਉਂਕਿ ਉਹ ਦੇ ਵਰਗਾ ਮੇਰੇ ਕੋਲ ਹੋਰ ਕੋਈ ਨਹੀਂ ਜੋ ਸੱਚੇ ਦਿਲ ਨਾਲ ਤੁਹਾਡੇ ਲਈ ਚਿੰਤਾ ਕਰੇ।","kiuṁki uha dē varagā mērē kōla hōra kōī nahīṁ jō saccē dila nāla tuhāḍē laī ciṁtā karē.",null],[2,21,"ਕਿਉਂ ਜੋ ਸਾਰੇ ਆਪੋ ਆਪਣੇ ਮਤਲਬ ਦੇ ਯਾਰ ਹਨ, ਨਾ ਕਿ ਯਿਸੂ ਮਸੀਹ ਦੇ।","kiuṁ jō sārē āpō āpaṇē matalaba dē yāra hana, nā ki yisū masīha dē.",null],[2,22,"ਪਰ ਉਹ ਦੀ ਖੂਬੀ ਤੁਸੀਂ ਜਾਣ ਚੁੱਕੇ ਹੋ ਭਈ ਜਿਵੇਂ ਪੁੱਤਰ ਪਿਉ ਦੀ ਸੇਵਾ ਕਰਦਾ ਹੈ ਤਿਵੇਂ ਉਸ ਨੇ ਮੇਰੇ ਨਾਲ ਖੁਸ਼ਖਬਰੀ ਦੀ ਸੇਵਾ ਕੀਤੀ।","para uha dī khūbī tusīṁ jāṇa cukkē hō bhaī jivēṁ puttara piu dī sēvā karadā hai tivēṁ usa nē mērē nāla khuśakhabarī dī sēvā kītī.",null],[2,23,"ਸੋ ਮੈਨੂੰ ਆਸ ਹੈ ਕਿ ਜਿਸ ਵੇਲੇ ਵੇਖ ਲਵਾਂ ਜੋ ਮੇਰਾ ਕੀ ਹਾਲ ਹੋਵੇਗਾ ਤਾਂ ਝੱਟ ਉਹ ਨੂੰ ਭੇਜ ਦਿਆਂ।","sō mainūṁ āsa hai ki jisa vēlē vēkha lavāṁ jō mērā kī hāla hōvēgā tāṁ jhaṭṭa uha nūṁ bhēja diāṁ.",null],[2,24,"ਪਰ ਮੈਨੂੰ ਪ੍ਰਭੂ ਉੱਤੇ ਪਰਤੀਤ ਹੈ ਜੋ ਆਪ ਵੀ ਛੇਤੀ ਆਵਾਂਗਾ।","para mainūṁ prabhū uttē paratīta hai jō āpa vī chētī āvāṁgā.",null],[2,25,"ਪਰ ਇਪਾਫ਼ਰੋਦੀਤੁਸ ਜੋ ਮੇਰਾ ਭਰਾ ਅਤੇ ਮੇਰਾ ਸਹਿਕਰਮੀ ਅਤੇ ਮੇਰੇ ਨਾਲ ਦਾ ਸਿਪਾਹੀ ਅਤੇ ਤੁਹਾਡਾ ਸੰਦੇਸੀ ਅਤੇ ਮੇਰੀ ਥੁੜ ਦਾ ਪੂਰਾ ਕਰਨ ਵਾਲਾ ਹੈ ਮੈਂ ਉਸ ਨੂੰ ਤੁਹਾਡੇ ਕੋਲ ਘੱਲਣਾ ਜ਼ਰੂਰੀ ਜਾਣਿਆ।","para ipāfarōdītusa jō mērā bharā atē mērā sahikaramī atē mērē nāla dā sipāhī atē tuhāḍā saṁdēsī atē mērī thuṛa dā pūrā karana vālā hai maiṁ usa nūṁ tuhāḍē kōla ghallaṇā zarūrī jāṇiā.",null],[2,26,"ਕਿਉਂ ਜੋ ਉਹ ਤੁਹਾਨੂੰ ਸਭਨਾਂ ਨੂੰ ਬਹੁਤ ਲੋਚਦਾ ਸੀ ਅਤੇ ਤੁਸੀਂ ਜੋ ਸੁਣਿਆ ਸੀ ਕਿ ਉਹ ਬਿਮਾਰ ਪਿਆ ਹੈ ਇਸ ਕਰਕੇ ਉਹ ਉਦਾਸ ਰਹਿੰਦਾ ਸੀ","kiuṁ jō uha tuhānūṁ sabhanāṁ nūṁ bahuta lōcadā sī atē tusīṁ jō suṇiā sī ki uha bimāra piā hai isa karakē uha udāsa rahiṁdā sī",null],[2,27,"ਅਤੇ ਉਹ ਤਾਂ ਸੱਚੀ ਮੁੱਚੀ ਬਿਮਾਰ ਸੀ ਸਗੋਂ ਮਰਨ ਵਾਲਾ ਹੋ ਗਿਆ ਸੀ ਪਰੰਤੂ ਪਰਮੇਸ਼ੁਰ ਨੇ ਉਸ ਉੱਤੇ ਦਯਾ ਕੀਤੀ ਅਤੇ ਸਿਰਫ਼ ਉਸੇ ਉੱਤੇ ਨਹੀਂ ਸਗੋਂ ਮੇਰੇ ਉੱਤੇ ਵੀ ਮਤੇ ਮੈਨੂੰ ਸੋਗ ਤੋਂ ਸੋਗ ਨਾ ਹੋਵੇ।","atē uha tāṁ saccī muccī bimāra sī sagōṁ marana vālā hō giā sī paraṁtū paramēśura nē usa uttē dayā kītī atē sirafa usē uttē nahīṁ sagōṁ mērē uttē vī matē mainūṁ sōga tōṁ sōga nā hōvē.",null],[2,28,"ਇਸ ਲਈ ਮੈਂ ਹੋਰ ਵੀ ਯਤਨ ਕਰਕੇ ਉਹ ਨੂੰ ਭੇਜਿਆ ਭਈ ਤੁਸੀਂ ਉਹ ਨੂੰ ਫੇਰ ਵੇਖ ਕੇ ਅਨੰਦ ਹੋਵੋ ਅਤੇ ਮੇਰਾ ਵੀ ਸੋਗ ਘੱਟ ਜਾਵੇ।","isa laī maiṁ hōra vī yatana karakē uha nūṁ bhējiā bhaī tusīṁ uha nūṁ phēra vēkha kē anaṁda hōvō atē mērā vī sōga ghaṭṭa jāvē.",null],[2,29,"ਸੋ ਤੁਸੀਂ ਉਹ ਨੂੰ ਪ੍ਰਭੂ ਵਿੱਚ ਪੂਰੇ ਅਨੰਦ ਨਾਲ ਕਬੂਲ ਕਰੋ ਅਤੇ ਅਜਿਹਿਆਂ ਦਾ ਆਦਰ ਕਰੋ।","sō tusīṁ uha nūṁ prabhū vicca pūrē anaṁda nāla kabūla karō atē ajihiāṁ dā ādara karō.",null],[2,30,"ਇਸ ਕਰਕੇ ਜੋ ਉਹ ਮਸੀਹ ਦੇ ਕੰਮ ਲਈ ਮੌਤ ਦੇ ਮੂੰਹ ਵਿੱਚ ਆਇਆ ਕਿਉਂ ਜੋ ਮੇਰੀ ਸੇਵਾ ਕਰਨ ਵਿੱਚ ਜੋ ਤੁਹਾਡੀ ਵੱਲੋਂ ਥੁੜ ਸੀ ਉਹ ਨੂੰ ਪੂਰਾ ਕਰਨ ਲਈ ਉਸ ਨੇ ਆਪਣੀ ਜਾਨ ਤਲੀ ਉੱਤੇ ਧਰੀ।","isa karakē jō uha masīha dē kamma laī mauta dē mūṁha vicca āiā kiuṁ jō mērī sēvā karana vicca jō tuhāḍī vallōṁ thuṛa sī uha nūṁ pūrā karana laī usa nē āpaṇī jāna talī uttē dharī.",null],[3,1,"ਮੁਕਦੀ ਗੱਲ, ਹੇ ਮੇਰੇ ਭਰਾਵੋ, ਪ੍ਰਭੂ ਵਿੱਚ ਅਨੰਦ ਰਹੋ। ਇਹ ਗੱਲਾਂ ਤੁਹਾਨੂੰ ਮੁੜ-ਮੁੜ ਲਿਖਣ ਤੋਂ ਮੈਂ ਤਾਂ ਨਹੀਂ ਅੱਕਦਾ ਅਤੇ ਇਹ ਤੁਹਾਡੇ ਲਈ ਬਚਾਓ ਦਾ ਕਾਰਨ ਹੈ।","mukadī galla, hē mērē bharāvō, prabhū vicca anaṁda rahō. iha gallāṁ tuhānūṁ muṛa-muṛa likhaṇa tōṁ maiṁ tāṁ nahīṁ akkadā atē iha tuhāḍē laī bacāō dā kārana hai.",null],[3,2,"ਕੁੱਤਿਆਂ ਤੋਂ ਸੁਚੇਤ ਰਹੋ। ਕੁਕਰਮੀਆਂ ਤੋਂ ਸੁਚੇਤ ਰਹੋ। ਸੁੰਨਤ ਕਰਨ ਵਾਲਿਆਂ ਤੋਂ ਸੁਚੇਤ ਰਹੋ।","kuttiāṁ tōṁ sucēta rahō. kukaramīāṁ tōṁ sucēta rahō. sunnata karana vāliāṁ tōṁ sucēta rahō.",null],[3,3,"ਕਿਉਂ ਜੋ ਸੁੰਨਤੀ ਤਾਂ ਅਸੀਂ ਹਾਂ ਜਿਹੜੇ ਪਰਮੇਸ਼ੁਰ ਦੇ ਆਤਮਾ ਨਾਲ ਭਜਨ ਕਰਦੇ ਹਾਂ ਅਤੇ ਮਸੀਹ ਯਿਸੂ ਦੇ ਉੱਤੇ ਅਭਮਾਨ ਕਰਦੇ ਹਾਂ ਅਤੇ ਸਰੀਰ ਦਾ ਆਸਰਾ ਨਹੀਂ ਰੱਖਦੇ।","kiuṁ jō sunnatī tāṁ asīṁ hāṁ jihaṛē paramēśura dē ātamā nāla bhajana karadē hāṁ atē masīha yisū dē uttē abhamāna karadē hāṁ atē sarīra dā āsarā nahīṁ rakkhadē.",null],[3,4,"ਭਾਵੇਂ ਮੈਂ ਸਰੀਰ ਦਾ ਵੀ ਆਸਰਾ ਰੱਖ ਸਕਦਾ। ਜੇ ਹੋਰ ਕੋਈ ਆਪਣੇ ਭਾਣੇ ਸਰੀਰ ਦਾ ਆਸਰਾ ਰੱਖ ਸਕਦਾ ਹੈ ਤਾਂ ਮੈਂ ਵਧੇਰੇ ਕਰ ਸਕਦਾ ਹਾਂ।","bhāvēṁ maiṁ sarīra dā vī āsarā rakkha sakadā. jē hōra kōī āpaṇē bhāṇē sarīra dā āsarā rakkha sakadā hai tāṁ maiṁ vadhērē kara sakadā hāṁ.",null],[3,5,"ਜਨਮ ਤੋਂ ਅੱਠਵੇਂ ਦਿਨ ਦਾ ਸੁੰਨਤ ਕੀਤਾ ਹੋਇਆ ਮੈਂ ਇਸਰਾਏਲ ਦੇ ਵੰਸ਼ ਅਤੇ ਬਿਨਯਾਮੀਨ ਦੇ ਗੋਤ ਵਿੱਚੋਂ ਅਤੇ ਇਬਰਾਨੀਆਂ ਦਾ ਇਬਰਾਨੀ ਹਾਂ। ਬਿਵਸਥਾ ਦੀ ਪੁੱਛੋ ਤਾਂ ਫ਼ਰੀਸੀ।","janama tōṁ aṭṭhavēṁ dina dā sunnata kītā hōiā maiṁ isarāēla dē vaṁśa atē binayāmīna dē gōta viccōṁ atē ibarānīāṁ dā ibarānī hāṁ. bivasathā dī pucchō tāṁ farīsī.",null],[3,6,"ਅਣਖ ਦੀ ਪੁੱਛੋਂ ਤਾਂ ਕਲੀਸਿਯਾ ਦਾ ਸਤਾਉਣ ਵਾਲਾ। ਬਿਵਸਥਾ ਦੀ ਧਾਰਮਿਕਤਾ ਦੀ ਪੁੱਛੋ ਤਾਂ ਨਿਰਦੋਸ਼।","aṇakha dī pucchōṁ tāṁ kalīsiyā dā satāuṇa vālā. bivasathā dī dhāramikatā dī pucchō tāṁ niradōśa.",null],[3,7,"ਪਰ ਜਿਹੜੀਆਂ ਗੱਲਾਂ ਮੇਰੇ ਲਾਭ ਦੀਆਂ ਸਨ ਮੈਂ ਉਨ੍ਹਾਂ ਨੂੰ ਮਸੀਹ ਦੇ ਕਾਰਨ ਹਾਨੀ ਦੀਆਂ ਸਮਝਿਆ।","para jihaṛīāṁ gallāṁ mērē lābha dīāṁ sana maiṁ unhāṁ nūṁ masīha dē kārana hānī dīāṁ samajhiā.",null],[3,8,"ਸਗੋਂ ਮਸੀਹ ਯਿਸੂ ਆਪਣੇ ਪ੍ਰਭੂ ਦੇ ਗਿਆਨ ਦੀ ਉੱਤਮਤਾਈ ਦੇ ਕਾਰਨ ਸਾਰਿਆਂ ਗੱਲਾਂ ਨੂੰ ਮੈਂ ਹਾਨੀ ਦੀਆਂ ਹੀ ਸਮਝਦਾ ਹਾਂ ਅਤੇ ਉਹ ਦੀ ਖਾਤਰ ਮੈਂ ਇੰਨ੍ਹਾਂ ਸਭਨਾਂ ਗੱਲਾਂ ਦੀ ਹਾਨ ਝੱਲੀ ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਕੂੜਾ ਸਮਝਦਾ ਹਾਂ ਜੋ ਮੈਂ ਮਸੀਹ ਨੂੰ ਪਾ ਲਵਾਂ।","sagōṁ masīha yisū āpaṇē prabhū dē giāna dī uttamatāī dē kārana sāriāṁ gallāṁ nūṁ maiṁ hānī dīāṁ hī samajhadā hāṁ atē uha dī khātara maiṁ innhāṁ sabhanāṁ gallāṁ dī hāna jhallī atē unhāṁ nūṁ kūṛā samajhadā hāṁ jō maiṁ masīha nūṁ pā lavāṁ.",null],[3,9,"ਅਤੇ ਮੈਂ ਉਸ ਵਿੱਚ ਪਾਇਆ ਜਾਂਵਾਂ, ਅਤੇ ਮੇਰੀ ਆਪਣੀ ਧਾਰਮਿਕਤਾ ਨਾਲ ਨਹੀਂ, ਜਿਹੜਾ ਬਿਵਸਥਾ ਤੋਂ ਹੁੰਦੀ ਹੈ, ਸਗੋਂ ਉਸ ਧਾਰਮਿਕਤਾ ਦੇ ਨਾਲ, ਜੋ ਮਸੀਹ ਉੱਤੇ ਵਿਸ਼ਵਾਸ ਕਰਨ ਤੋਂ ਪ੍ਰਾਪਤ ਹੁੰਦੀ ਹੈ, ਅਤੇ ਉਸ ਧਾਰਮਿਕਤਾ ਨਾਲ ਜੋ ਪਰਮੇਸ਼ੁਰ ਦੀ ਵੱਲੋਂ ਵਿਸ਼ਵਾਸ ਦੇ ਰਾਹੀਂ ਪ੍ਰਾਪਤ ਹੁੰਦੀ ਹੈ।","atē maiṁ usa vicca pāiā jāṁvāṁ, atē mērī āpaṇī dhāramikatā nāla nahīṁ, jihaṛā bivasathā tōṁ huṁdī hai, sagōṁ usa dhāramikatā dē nāla, jō masīha uttē viśavāsa karana tōṁ prāpata huṁdī hai, atē usa dhāramikatā nāla jō paramēśura dī vallōṁ viśavāsa dē rāhīṁ prāpata huṁdī hai.",null],[3,10,"ਤਾਂ ਜੋ ਮੈਂ ਉਹ ਨੂੰ ਅਤੇ ਉਹ ਦੇ ਜੀ ਉੱਠਣ ਦੀ ਸਮਰੱਥਾ ਨੂੰ ਅਤੇ ਉਹ ਦੇ ਦੁੱਖਾਂ ਦੀ ਸਾਂਝ ਨੂੰ ਜਾਣ ਲਵਾਂ ਅਤੇ ਉਹ ਦੀ ਮੌਤ ਦੇ ਸਰੂਪ ਨਾਲ ਮਿਲ ਜਾਂਵਾਂ।","tāṁ jō maiṁ uha nūṁ atē uha dē jī uṭṭhaṇa dī samaratthā nūṁ atē uha dē dukkhāṁ dī sāṁjha nūṁ jāṇa lavāṁ atē uha dī mauta dē sarūpa nāla mila jāṁvāṁ.",null],[3,11,"ਭਈ ਮੈਂ ਕਿਵੇਂ ਨਾ ਕਿਵੇਂ ਮੁਰਦਿਆਂ ਵਿੱਚੋਂ ਜੀ ਉੱਠਣ ਦੀ ਪਦਵੀ ਤੱਕ ਪਹੁੰਚ ਜਾਂਵਾਂ।","bhaī maiṁ kivēṁ nā kivēṁ muradiāṁ viccōṁ jī uṭṭhaṇa dī padavī takka pahuṁca jāṁvāṁ.",null],[3,12,"ਇਹ ਨਹੀਂ ਕੀ ਮੈਂ ਪਾ ਚੁੱਕਿਆ ਹਾਂ ਜਾਂ ਸਿੱਧ ਹੋ ਚੁੱਕਿਆ ਹਾਂ ਪਰ ਮੈਂ ਓਸ ਨਿਸ਼ਾਨੇ ਪਿੱਛੇ ਚੱਲਿਆ ਜਾਂਦਾ ਹਾਂ ਭਈ ਮੈਂ ਕਿਵੇਂ ਉਸ ਗੱਲ ਨੂੰ ਹੱਥ ਪਾ ਲਵਾਂ, ਜਿਹ ਦੇ ਲਈ ਮਸੀਹ ਯਿਸੂ ਨੇ ਮੈਨੂੰ ਵੀ ਹੱਥ ਪਾਇਆ ਸੀ।","iha nahīṁ kī maiṁ pā cukkiā hāṁ jāṁ siddha hō cukkiā hāṁ para maiṁ ōsa niśānē picchē calliā jāṁdā hāṁ bhaī maiṁ kivēṁ usa galla nūṁ hattha pā lavāṁ, jiha dē laī masīha yisū nē mainūṁ vī hattha pāiā sī.",null],[3,13,"ਹੇ ਭਰਾਵੋ ਮੈਂ ਆਪਣੇ ਲਈ ਇਹ ਨਹੀਂ ਸਮਝਦਾ ਜੋ ਮੈਂ ਅਜੇ ਹੱਥ ਪਾ ਲਿਆ ਹੈ ਪਰ ਐਨਾ ਹੈ ਜੋ ਮੈਂ ਪਿਛਲੀਆਂ ਗੱਲਾਂ ਨੂੰ ਭੁੱਲਾ ਕੇ ਅਤੇ ਉਨ੍ਹਾਂ ਗੱਲਾਂ ਲਈ ਜਿਹੜੀਆਂ ਅੱਗੇ ਹਨ ਅਗਾਹਾਂ ਵੱਧ ਕੇ,","hē bharāvō maiṁ āpaṇē laī iha nahīṁ samajhadā jō maiṁ ajē hattha pā liā hai para ainā hai jō maiṁ pichalīāṁ gallāṁ nūṁ bhullā kē atē unhāṁ gallāṁ laī jihaṛīāṁ aggē hana agāhāṁ vaddha kē,",null],[3,14,"ਨਿਸ਼ਾਨੇ ਵੱਲ ਦੌੜਿਆ ਜਾਂਦਾ ਹਾਂ ਭਈ ਉਸ ਉਪਰਲੇ ਸੱਦੇ ਦਾ ਇਨਾਮ ਲਵਾਂ ਜੋ ਪਰਮੇਸ਼ੁਰ ਦੀ ਵੱਲੋਂ ਮਸੀਹ ਯਿਸੂ ਵਿੱਚ ਹੈ।","niśānē valla dauṛiā jāṁdā hāṁ bhaī usa uparalē saddē dā ināma lavāṁ jō paramēśura dī vallōṁ masīha yisū vicca hai.",null],[3,15,"ਸੋ ਅਸੀਂ ਜਿੰਨੇ ਸਿਆਣੇ ਹਾਂ ਇਹੋ ਖ਼ਿਆਲ ਰੱਖੀਏ ਅਤੇ ਜੇ ਕਿਸੇ ਗੱਲ ਵਿੱਚ ਤੁਹਾਨੂੰ ਹੋਰ ਤਰ੍ਹਾਂ ਦਾ ਖ਼ਿਆਲ ਹੋਵੇ ਤਾਂ ਪਰਮੇਸ਼ੁਰ ਤੁਹਾਡੇ ਉੱਤੇ ਉਹ ਵੀ ਪਰਗਟ ਕਰ ਦੇਵੇਗਾ।","sō asīṁ jinnē siāṇē hāṁ ihō k͟hiāla rakkhīē atē jē kisē galla vicca tuhānūṁ hōra tarhāṁ dā k͟hiāla hōvē tāṁ paramēśura tuhāḍē uttē uha vī paragaṭa kara dēvēgā.",null],[3,16,"ਪਰ ਜਿੱਥੋਂ ਤੱਕ ਅਸੀਂ ਪਹੁੰਚੇ ਹਾਂ ਉਸੇ ਦੇ ਅਨੁਸਾਰ ਚੱਲੀਏ।","para jitthōṁ takka asīṁ pahuṁcē hāṁ usē dē anusāra callīē.",null],[3,17,"ਹੇ ਭਰਾਵੋ, ਤੁਸੀਂ ਰਲ ਕੇ ਮੇਰੀ ਰੀਸ ਕਰੋ ਅਤੇ ਉਨ੍ਹਾਂ ਵੱਲ ਧਿਆਨ ਰੱਖੋ ਜੋ ਇਹੋ ਜਿਹੀ ਚਾਲ ਚੱਲਦੇ ਹਨ ਜਿਵੇਂ ਅਸੀਂ ਤੁਹਾਡੇ ਲਈ ਨਮੂਨੇ ਹਾਂ।","hē bharāvō, tusīṁ rala kē mērī rīsa karō atē unhāṁ valla dhiāna rakkhō jō ihō jihī cāla calladē hana jivēṁ asīṁ tuhāḍē laī namūnē hāṁ.",null],[3,18,"ਕਿਉਂਕਿ ਬਹੁਤੇ ਅਜਿਹੇ ਚੱਲਣ ਵਾਲੇ ਹਨ ਜਿੰਨ੍ਹਾ ਦੀ ਗੱਲ ਕਈ ਵਾਰ ਮੈਂ ਤੁਹਾਡੇ ਨਾਲ ਕੀਤੀ ਹੈ ਅਤੇ ਹੁਣ ਵੀ ਹੰਝੂਆਂ ਨਾਲ ਆਖਦਾ ਹਾਂ ਜੋ ਓਹ ਮਸੀਹ ਦੀ ਸਲੀਬ ਦੇ ਵੈਰੀ ਹਨ।","kiuṁki bahutē ajihē callaṇa vālē hana jinnhā dī galla kaī vāra maiṁ tuhāḍē nāla kītī hai atē huṇa vī haṁjhūāṁ nāla ākhadā hāṁ jō ōha masīha dī salība dē vairī hana.",null],[3,19,"ਜਿਨ੍ਹਾਂ ਦਾ ਅੰਤ ਬਿਨਾਸ ਹੈ, ਜਿਹਨਾਂ ਦਾ ਈਸ਼ਵਰ ਢਿੱਡ ਹੈ, ਜਿਨ੍ਹਾਂ ਦਾ ਘਮੰਡ ਆਪਣੀ ਸ਼ਰਮ ਉੱਤੇ ਹੈ, ਜਿਨ੍ਹਾਂ ਦਾ ਮਨ ਪ੍ਰਿਥਵੀ ਦੀਆਂ ਵਸਤਾਂ ਉੱਤੇ ਲੱਗਿਆ ਹੋਇਆ ਹੈ।","jinhāṁ dā aṁta bināsa hai, jihanāṁ dā īśavara ḍhiḍḍa hai, jinhāṁ dā ghamaṁḍa āpaṇī śarama uttē hai, jinhāṁ dā mana prithavī dīāṁ vasatāṁ uttē laggiā hōiā hai.",null],[3,20,"ਕਿਉਂ ਜੋ ਅਸੀਂ ਸਵਰਗ ਦੀ ਪਰਜਾ ਹਾਂ ਜਿੱਥੋਂ ਅਸੀਂ ਇੱਕ ਮੁਕਤੀਦਾਤੇ ਅਰਥਾਤ ਪ੍ਰਭੂ ਯਿਸੂ ਮਸੀਹ ਦੀ ਉਡੀਕ ਵੀ ਕਰਦੇ ਹਾਂ।","kiuṁ jō asīṁ savaraga dī parajā hāṁ jitthōṁ asīṁ ikka mukatīdātē arathāta prabhū yisū masīha dī uḍīka vī karadē hāṁ.",null],[3,21,"ਜਿਹੜਾ ਆਪਣੀ ਸ਼ਕਤੀ ਦੇ ਅਨੁਸਾਰ ਜਿਹ ਦੇ ਨਾਲ ਉਹ ਸਭਨਾਂ ਵਸਤਾਂ ਨੂੰ ਆਪਣੇ ਵੱਸ ਵਿੱਚ ਕਰ ਸਕਦਾ ਹੈ ਸਾਡੇ ਨਿਮਾਣੇ ਸਰੀਰ ਨੂੰ ਬਦਲ ਕੇ ਆਪਣੇ ਤੇਜ ਦੇ ਸਰੀਰ ਦੀ ਤਰ੍ਹਾਂ ਬਣਾਵੇਗਾ।","jihaṛā āpaṇī śakatī dē anusāra jiha dē nāla uha sabhanāṁ vasatāṁ nūṁ āpaṇē vassa vicca kara sakadā hai sāḍē nimāṇē sarīra nūṁ badala kē āpaṇē tēja dē sarīra dī tarhāṁ baṇāvēgā.",null],[4,1,"ਹੇ ਮੇਰੇ ਪਿਆਰੇ ਭਰਾਵੋ, ਜਿੰਨ੍ਹਾ ਨੂੰ ਮੈਂ ਬਹੁਤ ਲੋਚਦਾ ਹਾਂ ਜੋ ਮੇਰਾ ਅਨੰਦ ਅਤੇ ਮੁਕਟ ਹੋ, ਤੁਸੀਂ ਇਸੇ ਤਰ੍ਹਾਂ ਹੇ ਪਿਆਰਿਓ, ਪ੍ਰਭੂ ਵਿੱਚ ਦ੍ਰਿੜ੍ਹ ਰਹੋ।","hē mērē piārē bharāvō, jinnhā nūṁ maiṁ bahuta lōcadā hāṁ jō mērā anaṁda atē mukaṭa hō, tusīṁ isē tarhāṁ hē piāriō, prabhū vicca driṛha rahō.",null],[4,2,"ਮੈਂ ਯੂਓਦਿਆ ਦੇ ਅੱਗੇ ਬੇਨਤੀ ਕਰਦਾ ਅਤੇ ਸੁੰਤੁਖੇ ਦੇ ਅੱਗੇ ਵੀ ਕਿ ਉਹ ਪ੍ਰਭੂ ਵਿੱਚ ਇੱਕ ਮਨ ਹੋਣ।","maiṁ yūōdiā dē aggē bēnatī karadā atē suṁtukhē dē aggē vī ki uha prabhū vicca ikka mana hōṇa.",null],[4,3,"ਹਾਂ, ਤੇਰੇ ਅੱਗੇ ਵੀ, ਹੇ ਸੱਚੇ ਸਹਿਕਰਮੀ, ਮੈਂ ਬੇਨਤੀ ਕਰਦਾ ਹਾਂ ਜੋ ਤੂੰ ਉਹਨਾਂ ਤੀਵੀਆਂ ਦੀ ਸਹਾਇਤਾ ਕਰ, ਜਿੰਨ੍ਹਾ ਨੇ ਕਲੇਮੰਸ ਅਤੇ ਹੋਰਨਾਂ ਸਹਿਕਰਮੀਆਂ ਸਣੇ ਖੁਸ਼ਖਬਰੀ ਦੀ ਸੇਵਾ ਵਿੱਚ ਮੇਰੇ ਨਾਲ ਯਤਨ ਕੀਤਾ ਸੀ, ਜਿਨ੍ਹਾਂ ਦੇ ਨਾਮ ਜੀਵਨ ਦੇ ਪੁਸਤਕ ਵਿੱਚ ਲਿਖੇ ਹੋਏ ਹਨ।","hāṁ, tērē aggē vī, hē saccē sahikaramī, maiṁ bēnatī karadā hāṁ jō tūṁ uhanāṁ tīvīāṁ dī sahāitā kara, jinnhā nē kalēmaṁsa atē hōranāṁ sahikaramīāṁ saṇē khuśakhabarī dī sēvā vicca mērē nāla yatana kītā sī, jinhāṁ dē nāma jīvana dē pusataka vicca likhē hōē hana.",null],[4,4,"ਪ੍ਰਭੂ ਵਿੱਚ ਸਦਾ ਅਨੰਦ ਕਰੋ। ਫੇਰ ਕਹਿੰਦਾ ਹਾਂ, ਅਨੰਦ ਕਰੋ।","prabhū vicca sadā anaṁda karō. phēra kahiṁdā hāṁ, anaṁda karō.",null],[4,5,"ਤੁਹਾਡਾ ਕੋਮਲਤਾ ਦਾ ਸੁਭਾਅ ਸਭਨਾਂ ਮਨੁੱਖਾਂ ਉੱਤੇ ਪਰਗਟ ਹੋਵੇ। ਪ੍ਰਭੂ ਨੇੜੇ ਹੈ।","tuhāḍā kōmalatā dā subhāa sabhanāṁ manukkhāṁ uttē paragaṭa hōvē. prabhū nēṛē hai.",null],[4,6,"ਕਿਸੇ ਗੱਲ ਦੀ ਚਿੰਤਾ ਨਾ ਕਰੋ ਸਗੋਂ ਹਰ ਗੱਲ ਵਿੱਚ ਤੁਹਾਡੀਆਂ ਅਰਦਾਸਾਂ ਪ੍ਰਾਰਥਨਾ ਅਤੇ ਬੇਨਤੀ ਨਾਲ ਧੰਨਵਾਦ ਸਣੇ ਪਰਮੇਸ਼ੁਰ ਦੇ ਅੱਗੇ ਕੀਤੀਆਂ ਜਾਣ।","kisē galla dī ciṁtā nā karō sagōṁ hara galla vicca tuhāḍīāṁ aradāsāṁ prārathanā atē bēnatī nāla dhannavāda saṇē paramēśura dē aggē kītīāṁ jāṇa.",null],[4,7,"ਅਤੇ ਪਰਮੇਸ਼ੁਰ ਦੀ ਸ਼ਾਂਤੀ ਜੋ ਸਾਰੀ ਸਮਝ ਤੋਂ ਪਰੇ ਹੈ ਮਸੀਹ ਯਿਸੂ ਵਿੱਚ ਤੁਹਾਡੀਆਂ ਮਨਾਂ ਅਤੇ ਸੋਚਾਂ ਦੀ ਰਾਖੀ ਕਰੇਗੀ।","atē paramēśura dī śāṁtī jō sārī samajha tōṁ parē hai masīha yisū vicca tuhāḍīāṁ manāṁ atē sōcāṁ dī rākhī karēgī.",null],[4,8,"ਮੁਕਦੀ ਗੱਲ, ਹੇ ਭਰਾਵੋ, ਜਿਹੜੀਆਂ ਗੱਲਾਂ ਸੱਚੀਆਂ ਹਨ, ਜਿਹੜੀਆਂ ਆਦਰਯੋਗ ਹਨ, ਜਿਹੜੀਆਂ ਜਥਾਰਥ ਹਨ, ਜਿਹੜੀਆਂ ਸ਼ੁੱਧ ਹਨ, ਜਿਹੜੀਆਂ ਸੁਹਾਉਣੀਆਂ ਹਨ, ਜਿਹੜੀਆਂ ਨੇਕਨਾਮੀ ਦੀਆਂ ਹਨ, ਜੇ ਕੁਝ ਗੁਣ ਹੈ ਅਤੇ ਜੇ ਕੁਝ ਸੋਭਾ ਹੈ ਤਾਂ ਇੰਨ੍ਹਾਂ ਗੱਲਾਂ ਦੀ ਵਿਚਾਰ ਕਰੋ।","mukadī galla, hē bharāvō, jihaṛīāṁ gallāṁ saccīāṁ hana, jihaṛīāṁ ādarayōga hana, jihaṛīāṁ jathāratha hana, jihaṛīāṁ śuddha hana, jihaṛīāṁ suhāuṇīāṁ hana, jihaṛīāṁ nēkanāmī dīāṁ hana, jē kujha guṇa hai atē jē kujha sōbhā hai tāṁ innhāṁ gallāṁ dī vicāra karō.",null],[4,9,"ਜੋ ਕੁਝ ਤੁਸੀਂ ਸਿੱਖਿਆ ਅਤੇ ਮੰਨ ਲਿਆ ਅਤੇ ਸੁਣਿਆ ਅਤੇ ਮੇਰੇ ਵਿੱਚ ਡਿੱਠਾ ਉਹੀ ਕਰੋ ਤਾਂ ਸ਼ਾਂਤੀ ਦਾਤਾ ਪਰਮੇਸ਼ੁਰ ਤੁਹਾਡੇ ਅੰਗ-ਸੰਗ ਹੋਵੇਗਾ।","jō kujha tusīṁ sikkhiā atē manna liā atē suṇiā atē mērē vicca ḍiṭṭhā uhī karō tāṁ śāṁtī dātā paramēśura tuhāḍē aṁga-saṁga hōvēgā.",null],[4,10,"ਪਰ ਮੈਂ ਪ੍ਰਭੂ ਵਿੱਚ ਇਸ ਗੱਲ ਤੋਂ ਬਹੁਤ ਅਨੰਦ ਹਾਂ ਜੋ ਹੁਣ ਐਨੇ ਚਿਰ ਪਿੱਛੋਂ ਤੁਸੀਂ ਮੁੜ ਮੇਰੀ ਚਿੰਤਾ ਕੀਤੀ। ਤੁਸੀਂ ਤਾਂ ਅੱਗੇ ਵੀ ਮੇਰੇ ਲਈ ਚਿੰਤਾ ਕੀਤੀ ਸੀ ਪਰ ਤੁਹਾਨੂੰ ਸਮਾਂ ਨਾ ਮਿਲਿਆ।","para maiṁ prabhū vicca isa galla tōṁ bahuta anaṁda hāṁ jō huṇa ainē cira picchōṁ tusīṁ muṛa mērī ciṁtā kītī. tusīṁ tāṁ aggē vī mērē laī ciṁtā kītī sī para tuhānūṁ samāṁ nā miliā.",null],[4,11,"ਇਹ ਨਹੀਂ ਜੋ ਮੈਂ ਤੰਗੀ ਦੇ ਕਾਰਨ ਆਖਦਾ ਹਾਂ ਕਿਉਂ ਜੋ ਮੈਂ ਇਹ ਸਿੱਖ ਲਿਆ ਹੈ ਭਈ ਜਿਸ ਹਾਲ ਵਿੱਚ ਹੋਵਾਂ ਓਸੇ ਵਿੱਚ ਸੰਤੋਖ ਰੱਖਾਂ।","iha nahīṁ jō maiṁ taṁgī dē kārana ākhadā hāṁ kiuṁ jō maiṁ iha sikkha liā hai bhaī jisa hāla vicca hōvāṁ ōsē vicca saṁtōkha rakkhāṁ.",null],[4,12,"ਮੈਂ ਘਟਣਾ ਜਾਣਦਾ ਹਾਂ, ਨਾਲੇ ਵੱਧਣਾ ਵੀ ਜਾਣਦਾ ਹਾਂ। ਹਰੇਕ ਗੱਲ ਵਿੱਚ, ਕੀ ਰੱਜਣਾ ਕੀ ਭੁੱਖਾ ਰਹਿਣਾ, ਕੀ ਵੱਧਣਾ ਕੀ ਥੁੜਨਾ, ਮੈਂ ਸਾਰੀਆਂ ਗੱਲਾਂ ਦਾ ਭੇਤ ਪਾਇਆ ਹੈ।","maiṁ ghaṭaṇā jāṇadā hāṁ, nālē vaddhaṇā vī jāṇadā hāṁ. harēka galla vicca, kī rajjaṇā kī bhukkhā rahiṇā, kī vaddhaṇā kī thuṛanā, maiṁ sārīāṁ gallāṁ dā bhēta pāiā hai.",null],[4,13,"ਉਹ ਦੇ ਵਿੱਚ ਜੋ ਮੈਨੂੰ ਬਲ ਦਿੰਦਾ ਹੈ ਮੈਂ ਸੱਭੋ ਕੁਝ ਕਰ ਸਕਦਾ ਹਾਂ।","uha dē vicca jō mainūṁ bala diṁdā hai maiṁ sabbhō kujha kara sakadā hāṁ.",null],[4,14,"ਤਾਂ ਵੀ ਤੁਸੀਂ ਭਲਾ ਕੀਤਾ ਜੋ ਇਸ ਬਿਪਤਾ ਵਿੱਚ ਮੇਰੇ ਸਾਂਝੀ ਹੋਏ।","tāṁ vī tusīṁ bhalā kītā jō isa bipatā vicca mērē sāṁjhī hōē.",null],[4,15,"ਹੇ ਫਿਲਿੱਪੀਓ, ਤੁਸੀਂ ਆਪ ਵੀ ਜਾਣਦੇ ਹੋ ਭਈ ਜਾਂ ਮੈਂ ਖੁਸ਼ਖਬਰੀ ਪਹਿਲਾਂ ਸੁਣਾਉਣ ਲੱਗਾ ਜਦ ਮੈਂ ਮਕਦੂਨਿਯਾ ਤੋਂ ਨਿੱਕਲ ਆਇਆ ਤਾਂ ਕਿਸੇ ਕਲੀਸਿਯਾ ਨੇ ਲੈਣ-ਦੇਣ ਦੀ ਗੱਲ ਵਿੱਚ ਮੇਰਾ ਸਾਥ ਨਾ ਦਿੱਤਾ ਪਰ ਕੇਵਲ ਤੁਸੀਂ","hē philippīō, tusīṁ āpa vī jāṇadē hō bhaī jāṁ maiṁ khuśakhabarī pahilāṁ suṇāuṇa laggā jada maiṁ makadūniyā tōṁ nikkala āiā tāṁ kisē kalīsiyā nē laiṇa-dēṇa dī galla vicca mērā sātha nā dittā para kēvala tusīṁ",null],[4,16,"ਕਿਉਂ ਜੋ ਥਸਲੁਨੀਕੇ ਵਿੱਚ ਵੀ ਤੁਸੀਂ ਮੇਰੀ ਲੋੜ ਪੂਰੀ ਕਰਨ ਲਈ ਇੱਕ ਵਾਰ ਨਹੀਂ ਸਗੋਂ ਕਈ ਵਾਰ ਕੁਝ ਭੇਜਿਆ।","kiuṁ jō thasalunīkē vicca vī tusīṁ mērī lōṛa pūrī karana laī ikka vāra nahīṁ sagōṁ kaī vāra kujha bhējiā.",null],[4,17,"ਇਹ ਨਹੀਂ ਜੋ ਮੈਂ ਦਾਨ ਚਾਹੁੰਦਾ ਹਾਂ ਪਰ ਮੈਂ ਉਹ ਫਲ ਚਾਹੁੰਦਾ ਹਾਂ ਜੋ ਤੁਹਾਡੇ ਲੇਖੇ ਵਿੱਚ ਵਧਦਾ ਜਾਂਦਾ ਹੈ।","iha nahīṁ jō maiṁ dāna cāhuṁdā hāṁ para maiṁ uha phala cāhuṁdā hāṁ jō tuhāḍē lēkhē vicca vadhadā jāṁdā hai.",null],[4,18,"ਅਤੇ ਮੈਨੂੰ ਸੱਭੋ ਕੁਝ ਮਿਲ ਗਿਆ ਹੈ, ਸਗੋਂ ਵਾਧੂ ਹੈ। ਮੈਂ ਭਰਪੂਰ ਹਾਂ ਕਿਉਂ ਜੇ ਮੈਨੂੰ ਤੁਹਾਡੇ ਭੇਜੇ ਹੋਏ ਪਦਾਰਥ ਇਪਾਫ਼ਰੋਦੀਤੁਸ ਦੇ ਹੱਥੋਂ ਮਿਲੇ ਜੋ ਸੁੱਖਦਾਇਕ ਸੁਗੰਧ ਅਤੇ ਇਹੋ ਜਿਹਾ ਪਰਵਾਨ ਬਲੀਦਾਨ ਹੈ ਜੋ ਪਰਮੇਸ਼ੁਰ ਨੂੰ ਭਾਉਂਦਾ ਹੈ।","atē mainūṁ sabbhō kujha mila giā hai, sagōṁ vādhū hai. maiṁ bharapūra hāṁ kiuṁ jē mainūṁ tuhāḍē bhējē hōē padāratha ipāfarōdītusa dē hatthōṁ milē jō sukkhadāika sugaṁdha atē ihō jihā paravāna balīdāna hai jō paramēśura nūṁ bhāuṁdā hai.",null],[4,19,"ਅਤੇ ਮੇਰਾ ਪਰਮੇਸ਼ੁਰ ਤੇਜ ਵਿੱਚ ਆਪਣੇ ਧਨ ਦੇ ਅਨੁਸਾਰ ਤੁਹਾਡੀ ਹਰੇਕ ਥੁੜ ਨੂੰ ਮਸੀਹ ਯਿਸੂ ਵਿੱਚ ਸੰਪੂਰਨ ਕਰੇਗਾ।","atē mērā paramēśura tēja vicca āpaṇē dhana dē anusāra tuhāḍī harēka thuṛa nūṁ masīha yisū vicca saṁpūrana karēgā.",null],[4,20,"ਹੁਣ ਸਾਡੇ ਪਰਮੇਸ਼ੁਰ ਅਤੇ ਪਿਤਾ ਦੀ ਵਡਿਆਈ ਜੁੱਗੋ-ਜੁੱਗ ਹੋਵੇ। ਆਮੀਨ।","huṇa sāḍē paramēśura atē pitā dī vaḍiāī juggō-jugga hōvē. āmīna.",null],[4,21,"ਮਸੀਹ ਯਿਸੂ ਵਿੱਚ ਹਰੇਕ ਸੰਤ ਨੂੰ ਸੁੱਖ-ਸਾਂਦ ਆਖਣਾ। ਮੇਰੇ ਨਾਲ ਜਿਹੜੇ ਭਾਈ ਹਨ ਤੁਹਾਨੂੰ ਸੁੱਖ-ਸਾਂਦ ਆਖਦੇ ਹਨ।","masīha yisū vicca harēka saṁta nūṁ sukkha-sāṁda ākhaṇā. mērē nāla jihaṛē bhāī hana tuhānūṁ sukkha-sāṁda ākhadē hana.",null],[4,22,"ਸਾਰੇ ਸੰਤ ਪਰ ਖ਼ਾਸ ਕਰਕੇ ਓਹ ਜੋ ਕੈਸਰ ਦੇ ਘਰ ਵਿੱਚੋਂ ਹਨ ਤੁਹਾਨੂੰ ਸੁੱਖ-ਸਾਂਦ ਆਖਦੇ ਹਨ।","sārē saṁta para k͟hāsa karakē ōha jō kaisara dē ghara viccōṁ hana tuhānūṁ sukkha-sāṁda ākhadē hana.",null],[4,23,"ਪ੍ਰਭੂ ਯਿਸੂ ਮਸੀਹ ਦੀ ਕਿਰਪਾ ਤੁਹਾਡੇ ਆਤਮਾ ਉੱਤੇ ਹੁੰਦੀ ਰਹੇ।","prabhū yisū masīha dī kirapā tuhāḍē ātamā uttē huṁdī rahē.",null]],"bgc":[[1,1,"या चिट्ठी पौलुस अर तीमुथियुस की ओड़ तै सै, जो यीशु मसीह के दास सै, मै पौलुस कलीसिया के सारे पवित्र माणसां, अगुवां, अर सेवकां के नाम जो प्रभु यीशु मसीह म्ह होकै फिलिप्पी नगर म्ह रहवै सै।","yā ciṭṭhī paulusa ara tīmuthiyusa kī ōṛa tai sai, jō yīśu masīha kē dāsa sai, mai paulusa kalīsiyā kē sārē pavitra māṇasāṁ, aguvāṁ, ara sēvakāṁ kē nāma jō prabhu yīśu masīha mha hōkai philippī nagara mha rahavai sai.",null],[1,2,"हम प्रार्थना करां सां के म्हारै पिता परमेसवर अर प्रभु यीशु मसीह की ओड़ तै थारे ताहीं अनुग्रह अर शान्ति मिल्दी रहवै।","hama prārthanā karāṁ sāṁ kē mhārai pitā paramēsavara ara prabhu yīśu masīha kī ōṛa tai thārē tāhīṁ anugraha ara śānti mildī rahavai.",null],[1,3,"मै जिब-जिब थमनै याद करुँ सूं, तब-तब अपणे परमेसवर का धन्यवाद करुँ सूं,","mai jiba-jiba thamanai yāda karum̐ sūṁ, taba-taba apaṇē paramēsavara kā dhanyavāda karum̐ sūṁ,",null],[1,4,"अर खुशी कै गैल अपणी हरेक प्रार्थना म्ह थारे सारया खात्तर हमेशा परमेसवर तै मदद की बिनती करुँ सूं।","ara khuśī kai gaila apaṇī harēka prārthanā mha thārē sārayā khāttara hamēśā paramēsavara tai madada kī binatī karum̐ sūṁ.",null],[1,5,"इस करकै के पैहले दिन तै जिब थमनै सुसमाचार पै बिश्वास करया, तब तै आज तक थम यीशु मसीह कै प्यार के बारें म्ह सुसमाचार फैलाण म्ह म्हारे साथ रह्ये सों।","isa karakai kē paihalē dina tai jiba thamanai susamācāra pai biśvāsa karayā, taba tai āja taka thama yīśu masīha kai pyāra kē bārēṁ mha susamācāra phailāṇa mha mhārē sātha rahyē sōṁ.",null],[1,6,"मन्नै इस बात का भरोस्सा सै, के परमेसवर जिसनै थारे म्ह आच्छा काम शरु करया सै, वोए उसनै जिब यीशु मसीह बोहड़ के आवैगा तब तक पूरा करैगा।","mannai isa bāta kā bharōssā sai, kē paramēsavara jisanai thārē mha ācchā kāma śaru karayā sai, vōē usanai jiba yīśu masīha bōhaṛa kē āvaigā taba taka pūrā karaigā.",null],[1,7,"सही सै ताके मै थारे सारया खात्तर इसाए विचार करुँ। क्यूँके थारे खात्तर मेरै मन म्ह खास जगहां सै, इब मै कैद म्ह सूं, अर सुसमाचार की सच्चाई नै साबित अर बचाव करण म्ह लागरया सूं, तो थम सब मेरै गैल परमेसवर के अनुग्रह म्ह साझीदार सों।","sahī sai tākē mai thārē sārayā khāttara isāē vicāra karum̐. kyūm̐kē thārē khāttara mērai mana mha khāsa jagahāṁ sai, iba mai kaida mha sūṁ, ara susamācāra kī saccāī nai sābita ara bacāva karaṇa mha lāgarayā sūṁ, tō thama saba mērai gaila paramēsavara kē anugraha mha sājhīdāra sōṁ.",null],[1,8,"इस म्ह परमेसवर मेरा गवाह सै, के मै मसीह यीशु की तरियां लगाव करकै, थारे सारया की मिलण की लालसा करुँ सूं।","isa mha paramēsavara mērā gavāha sai, kē mai masīha yīśu kī tariyāṁ lagāva karakai, thārē sārayā kī milaṇa kī lālasā karum̐ sūṁ.",null],[1,9,"मै या प्रार्थना करुँ सूं, कै थारा प्यार वास्तविक ज्ञान अर अन्तरात्मा म्ह और भी बढ़ता जावै।","mai yā prārthanā karum̐ sūṁ, kai thārā pyāra vāstavika jñāna ara antarātmā mha aura bhī baṛhatā jāvai.",null],[1,10,"ताके थम आच्छी तै आच्छी बात नै चुण सकों, अर मसीह कै बोहड़ण तक हरेक बुराई तै बचे रहों, अर ठोक्कर ना खाओ।","tākē thama ācchī tai ācchī bāta nai cuṇa sakōṁ, ara masīha kai bōhaṛaṇa taka harēka burāī tai bacē rahōṁ, ara ṭhōkkara nā khāō.",null],[1,11,"अर उस धार्मिकता के काम नै जो यीशु मसीह कै जरिये होवै सै, भरपूर होन्दे जाओ जिसतै परमेसवर की महिमा अर बड़ाई होंदी रहवै।","ara usa dhārmikatā kē kāma nai jō yīśu masīha kai jariyē hōvai sai, bharapūra hōndē jāō jisatai paramēsavara kī mahimā ara baṛāī hōṁdī rahavai.",null],[1,12,"हे बिश्वासी भाईयो, मै चाहूँ सूं के थम यो जाण ल्यो, के जो मेरै पै बित्या सै, उसतै भोत सारे माणसां नै सुसमाचार पै बिश्वास करया सै।","hē biśvāsī bhāīyō, mai cāhūm̐ sūṁ kē thama yō jāṇa lyō, kē jō mērai pai bityā sai, usatai bhōta sārē māṇasāṁ nai susamācāra pai biśvāsa karayā sai.",null],[1,13,"उरै ताहीं के महाराजा के राजभवन की सारी पलटन अर बाकी सारे माणस यो जाणगे सै, के मै कैद म्ह सूं, क्यूँके मै मसीह का दास सूं।","urai tāhīṁ kē mahārājā kē rājabhavana kī sārī palaṭana ara bākī sārē māṇasa yō jāṇagē sai, kē mai kaida mha sūṁ, kyūm̐kē mai masīha kā dāsa sūṁ.",null],[1,14,"अर प्रभु म्ह जो बिश्वासी भाई सै, उन म्ह तै घणखरे मेरै कैद होण कै कारण, साहस कै गैल परमेसवर का वचन बिना डरे सुणावै सै।","ara prabhu mha jō biśvāsī bhāī sai, una mha tai ghaṇakharē mērai kaida hōṇa kai kāraṇa, sāhasa kai gaila paramēsavara kā vacana binā ḍarē suṇāvai sai.",null],[1,15,"कुछ लोग तो जळण अर झगड़े कै कारण मसीह के सुसमाचार के बारें म्ह सुणावै सै, अर कई माणस भली इच्छा तै, ताके मेरे वचन फैलाण म्ह मदद कर सकै।","kucha lōga tō jaḷaṇa ara jhagaṛē kai kāraṇa masīha kē susamācāra kē bārēṁ mha suṇāvai sai, ara kaī māṇasa bhalī icchā tai, tākē mērē vacana phailāṇa mha madada kara sakai.",null],[1,16,"भली इच्छा तै प्रचार करण आळे प्यार तै प्रचार करै सै, क्यूँके वो जाणै सै, के मै सुसमाचार के बचाव कै खात्तर जेळ म्ह बन्द सूं।","bhalī icchā tai pracāra karaṇa āḷē pyāra tai pracāra karai sai, kyūm̐kē vō jāṇai sai, kē mai susamācāra kē bacāva kai khāttara jēḷa mha banda sūṁ.",null],[1,17,"कई माणस तो जळण अर बिरोध के कारण मसीह का प्रचार करै सै, यो सोचकै के मेरी कैद म्ह मेरै खात्तर और क्ळेश पैदा कर सकै।","kaī māṇasa tō jaḷaṇa ara birōdha kē kāraṇa masīha kā pracāra karai sai, yō sōcakai kē mērī kaida mha mērai khāttara aura kḷēśa paidā kara sakai.",null],[1,18,"तो के होया? सिर्फ यो के हर ढाळ तै, बुरी इच्छा तै चाहे सच्चाई तै, मसीह के वचन का प्रचार हरेक जगहां करया जाण लागरया सै, अर मै इसतै आनन्दित सूं अर आनन्दित रहूँगा भी।","tō kē hōyā? sirpha yō kē hara ḍhāḷa tai, burī icchā tai cāhē saccāī tai, masīha kē vacana kā pracāra harēka jagahāṁ karayā jāṇa lāgarayā sai, ara mai isatai ānandita sūṁ ara ānandita rahūm̐gā bhī.",null],[1,19,"क्यूँके मै जाणु सूं, के थारी बिनती कै जरिये, अर पवित्र आत्मा जो यीशु मसीह की ओड़ तै आया सै, इसका प्रतिफळ जो मेरे बिश्वास म्ह बणे रहण अर कैद तै लिकड़ण का कारण होगा।","kyūm̐kē mai jāṇu sūṁ, kē thārī binatī kai jariyē, ara pavitra ātmā jō yīśu masīha kī ōṛa tai āyā sai, isakā pratiphaḷa jō mērē biśvāsa mha baṇē rahaṇa ara kaida tai likaṛaṇa kā kāraṇa hōgā.",null],[1,20,"मै तो याए मन तै लालसा अर आस राक्खूँ सूं, के मै किसे बात म्ह शर्मिन्दा ना होऊँ, पर साहस कै साथ परमेसवर का वचन सुणा सकूँ, जिसा पैहले मन्नै सुण्या था, चाहे मै जिन्दा रहूँ या मरु, मसीह की बड़ाई मेरी देह के जरिये होन्दी रहवै।","mai tō yāē mana tai lālasā ara āsa rākkhūm̐ sūṁ, kē mai kisē bāta mha śarmindā nā hōūm̐, para sāhasa kai sātha paramēsavara kā vacana suṇā sakūm̐, jisā paihalē mannai suṇyā thā, cāhē mai jindā rahūm̐ yā maru, masīha kī baṛāī mērī dēha kē jariyē hōndī rahavai.",null],[1,21,"क्यूँके मेरै खात्तर जिन्दा रहणा मसीह सै, अर मर जाणा और भी आच्छा सै, क्यूँके मै मसीह कै धोरै चला जाऊँगा।","kyūm̐kē mērai khāttara jindā rahaṇā masīha sai, ara mara jāṇā aura bhī ācchā sai, kyūm̐kē mai masīha kai dhōrai calā jāūm̐gā.",null],[1,22,"पर जै देह तै जिन्दा रहणा ए परमेसवर के काम कै खात्तर फायदेमन्द सै, तो मै न्ही जाणदा के किसनै चुणु।","para jai dēha tai jindā rahaṇā ē paramēsavara kē kāma kai khāttara phāyadēmanda sai, tō mai nhī jāṇadā kē kisanai cuṇu.",null],[1,23,"क्यूँके मै उळझन म्ह सूं, के मै के करुँ, जी तो करै सै, के मै दुनिया छोड़कै मसीह कै धोरै चला जाऊँ, क्यूँके यो घणाए आच्छा सै,","kyūm̐kē mai uḷajhana mha sūṁ, kē mai kē karum̐, jī tō karai sai, kē mai duniyā chōṛakai masīha kai dhōrai calā jāūm̐, kyūm̐kē yō ghaṇāē ācchā sai,",null],[1,24,"पर देह म्ह रहणा थारे कारण और भी जरूरी सै, ताके मै थारी मदद कर सकूँ।","para dēha mha rahaṇā thārē kāraṇa aura bhī jarūrī sai, tākē mai thārī madada kara sakūm̐.",null],[1,25,"इस करकै के मन्नै इसका भरोस्सा सै। मै जाणु सूं के मै जिन्दा रहूँगा, बल्के सारा कै गेल्या रहूँगा, जिसतै थमनै बिश्वास म्ह मजबूत कर सकूँ, अर उस म्ह आनन्दित रहों।","isa karakai kē mannai isakā bharōssā sai. mai jāṇu sūṁ kē mai jindā rahūm̐gā, balkē sārā kai gēlyā rahūm̐gā, jisatai thamanai biśvāsa mha majabūta kara sakūm̐, ara usa mha ānandita rahōṁ.",null],[1,26,"जिब मै थारे धोरै बोहड़ के आऊँगा तो यीशु मसीह जो मेरे जरिये काम करण लागरया सै, उसपै थम गर्व कर सकों सों।","jiba mai thārē dhōrai bōhaṛa kē āūm̐gā tō yīśu masīha jō mērē jariyē kāma karaṇa lāgarayā sai, usapai thama garva kara sakōṁ sōṁ.",null],[1,27,"सिर्फ इतणा करो, के थारा चाल चलण मसीह कै सुसमाचार कै लायक हो जावै। चाहे मै आकै थमनै देक्खूँ, चाहे ना भी आऊँ, तोभी थारे बारें म्ह योए सुणु, कै थारा एक ए मकसद हो, अर एक मन होकै बिश्वास तै जो सुसमाचार तै आवै सै, उसकै खात्तर मेहनत करते रहों।","sirpha itaṇā karō, kē thārā cāla calaṇa masīha kai susamācāra kai lāyaka hō jāvai. cāhē mai ākai thamanai dēkkhūm̐, cāhē nā bhī āūm̐, tōbhī thārē bārēṁ mha yōē suṇu, kai thārā ēka ē makasada hō, ara ēka mana hōkai biśvāsa tai jō susamācāra tai āvai sai, usakai khāttara mēhanata karatē rahōṁ.",null],[1,28,"अर किसे बात म्ह बिरोधियाँ तै भय ना खाओ। उनकै खात्तर विनाश का, अर थारे खात्तर उद्धार का साफ सबूत सै, अर यो परमेसवर की ओड़ तै सै।","ara kisē bāta mha birōdhiyām̐ tai bhaya nā khāō. unakai khāttara vināśa kā, ara thārē khāttara uddhāra kā sāpha sabūta sai, ara yō paramēsavara kī ōṛa tai sai.",null],[1,29,"क्यूँके मसीह कै कारण थारे पै या अनुग्रह होया के ना केवल उसपै बिश्वास करो पर उसकै खात्तर दुख भी ठाओ,","kyūm̐kē masīha kai kāraṇa thārē pai yā anugraha hōyā kē nā kēvala usapai biśvāsa karō para usakai khāttara dukha bhī ṭhāō,",null],[1,30,"अर थमनै उसीए मेहनत परमेसवर कै खात्तर करणी सै, जिसी थमनै मेरै ताहीं पैहले फिलीपी नगर म्ह करते देख्या सै, अर इब भी सुणो सों के मै उसाए करुँ सूं।","ara thamanai usīē mēhanata paramēsavara kai khāttara karaṇī sai, jisī thamanai mērai tāhīṁ paihalē philīpī nagara mha karatē dēkhyā sai, ara iba bhī suṇō sōṁ kē mai usāē karum̐ sūṁ.",null],[2,1,"थम यीशु मसीह के कारण उत्साहित हो, अर जो उसका प्यार थारे खात्तर सै, वो थमनै शान्ति देवै सै, क्यूँके पवित्र आत्मा कै गैल थारी संगति सै, अर मसीह की करुणा अर दया थारे पै सै।","thama yīśu masīha kē kāraṇa utsāhita hō, ara jō usakā pyāra thārē khāttara sai, vō thamanai śānti dēvai sai, kyūm̐kē pavitra ātmā kai gaila thārī saṁgati sai, ara masīha kī karuṇā ara dayā thārē pai sai.",null],[2,2,"तो मेरा यो आनन्द पूरा करो के एक मन रहों, अर एके प्यार, एके चित्त, अर एके मनसा राक्खों।","tō mērā yō ānanda pūrā karō kē ēka mana rahōṁ, ara ēkē pyāra, ēkē citta, ara ēkē manasā rākkhōṁ.",null],[2,3,"मतलबीपण या झूठ्ठी बड़ाई कै खात्तर कुछ ना करो, पर दीनता तै एक-दुसरे नै अपणे तै घणा आदर मान द्यो।","matalabīpaṇa yā jhūṭhṭhī baṛāī kai khāttara kucha nā karō, para dīnatā tai ēka-dusarē nai apaṇē tai ghaṇā ādara māna dyō.",null],[2,4,"हरेक अपणे ए हित की न्ही, बल्के दुसरयां कै हित की भी चिंता करै।","harēka apaṇē ē hita kī nhī, balkē dusarayāṁ kai hita kī bhī ciṁtā karai.",null],[2,5,"जिसा मसीह यीशु का सुभाव था उसाए तेरा भी सुभाव हो।","jisā masīha yīśu kā subhāva thā usāē tērā bhī subhāva hō.",null],[2,6,"यीशु, परमेसवर कै समान होकै भी होकै भी परमेसवर कै बराबर होण नै अपणे बस म्ह राक्खण की चीज ना समझा।","yīśu, paramēsavara kai samāna hōkai bhī hōkai bhī paramēsavara kai barābara hōṇa nai apaṇē basa mha rākkhaṇa kī cīja nā samajhā.",null],[2,7,"बल्के अपणा सारा सुर्गीय हक छोड़ दिया, अर दास का रूप धारण करते होए माणस की समानता म्ह होग्या।","balkē apaṇā sārā surgīya haka chōṛa diyā, ara dāsa kā rūpa dhāraṇa karatē hōē māṇasa kī samānatā mha hōgyā.",null],[2,8,"अर माणस कै रूप म्ह जाहिर होकै अपणे-आपनै दीन करया, अर परमेसवर का आज्ञाकारी रहया अर याड़ै तक के अपराधियाँ की तरियां मौत, हाँ क्रूस की मौत भी सह ली।","ara māṇasa kai rūpa mha jāhira hōkai apaṇē-āpanai dīna karayā, ara paramēsavara kā ājñākārī rahayā ara yāṛai taka kē aparādhiyām̐ kī tariyāṁ mauta, hām̐ krūsa kī mauta bhī saha lī.",null],[2,9,"इस कारण परमेसवर नै उस ताहीं ऊँच्ची उपाधि दी, अर उसनै वो नाम दिया जो सारे नाम्मां म्ह ऊँच्चा सै,","isa kāraṇa paramēsavara nai usa tāhīṁ ūm̐ccī upādhi dī, ara usanai vō nāma diyā jō sārē nāmmāṁ mha ūm̐ccā sai,",null],[2,10,"के जो सुर्ग म्ह अर धरती पै धरती कै नीच्चै सै, वे सारी यीशु कै नाम की बड़ाई करै,","kē jō surga mha ara dharatī pai dharatī kai nīccai sai, vē sārī yīśu kai nāma kī baṛāī karai,",null],[2,11,"अर परमेसवर पिता की महिमा के खात्तर हरेक इन्सान मान ले के यीशु मसीह ए प्रभु सै।","ara paramēsavara pitā kī mahimā kē khāttara harēka insāna māna lē kē yīśu masīha ē prabhu sai.",null],[2,12,"इस करकै हे मेरै प्यारे बिश्वासी भाईयो, जिस ढाळ थम सदा तै हुकम मानते आये सों, उसाए इब भी ना सिर्फ मेरै गैल रहंदे होए, पर खास करकै इब मेरै दूर रहण पै, भी परमेसवर तै डरदे अर कापते होए अपणे उद्धार के काम नै पूरा करो।","isa karakai hē mērai pyārē biśvāsī bhāīyō, jisa ḍhāḷa thama sadā tai hukama mānatē āyē sōṁ, usāē iba bhī nā sirpha mērai gaila rahaṁdē hōē, para khāsa karakai iba mērai dūra rahaṇa pai, bhī paramēsavara tai ḍaradē ara kāpatē hōē apaṇē uddhāra kē kāma nai pūrā karō.",null],[2,13,"क्यूँके परमेसवर थारे म्ह काम करण लागरया सै, अर वोए थमनै अपणी इच्छा अर सामर्थ देवै सै, वो काम करो जो उसनै पसन्द सै।","kyūm̐kē paramēsavara thārē mha kāma karaṇa lāgarayā sai, ara vōē thamanai apaṇī icchā ara sāmartha dēvai sai, vō kāma karō jō usanai pasanda sai.",null],[2,14,"सारे काम बिना कुड़कड़ाए अर बिना विवाद कै करया करो,","sārē kāma binā kuṛakaṛāē ara binā vivāda kai karayā karō,",null],[2,15,"ताके थम परमेसवर की ऊलाद की तरियां इस दुनिया के बुरे अर मतलबी माणसां के बीच म्ह पवित्र अर बेदाग जीवन जी सकों। दुनिया के माणसां के बीच म्ह थम जीवन का वचन लिये होए, आसमान के तारां के समान चमकों।","tākē thama paramēsavara kī ūlāda kī tariyāṁ isa duniyā kē burē ara matalabī māṇasāṁ kē bīca mha pavitra ara bēdāga jīvana jī sakōṁ. duniyā kē māṇasāṁ kē bīca mha thama jīvana kā vacana liyē hōē, āsamāna kē tārāṁ kē samāna camakōṁ.",null],[2,16,"जिब मसीह बोहड़ै तो मन्नै गर्व करण का कारण हो, ताके मेरी कोशिश अर मेरी मेहनत करणा बेकार ना होवै।","jiba masīha bōhaṛai tō mannai garva karaṇa kā kāraṇa hō, tākē mērī kōśiśa ara mērī mēhanata karaṇā bēkāra nā hōvai.",null],[2,17,"जिब मन्नै थारे ताहीं वचन सुणाया, तो थमनै यीशु मसीह पै बिश्वास करया, अर अपणा जीवन भी सेवा खात्तर प्रभु ताहीं बलिदान दिया। इस करकै मै प्रभु खात्तर मर भी जाऊँ, तोभी थारे साथ खुश अर आनन्दित सूं।","jiba mannai thārē tāhīṁ vacana suṇāyā, tō thamanai yīśu masīha pai biśvāsa karayā, ara apaṇā jīvana bhī sēvā khāttara prabhu tāhīṁ balidāna diyā. isa karakai mai prabhu khāttara mara bhī jāūm̐, tōbhī thārē sātha khuśa ara ānandita sūṁ.",null],[2,18,"उस्से तरियां थम भी आनन्दित होओ, अर मेरै गैल आनन्द करो।","ussē tariyāṁ thama bhī ānandita hōō, ara mērai gaila ānanda karō.",null],[2,19,"मन्नै प्रभु यीशु मसीह म्ह आस सै, के मै तीमुथियुस नै थारे धोरै तावळा-ए भेजूगाँ, ताके थारे हाल नै जाणकै, मै उत्साहित होऊँ।","mannai prabhu yīśu masīha mha āsa sai, kē mai tīmuthiyusa nai thārē dhōrai tāvaḷā-ē bhējūgām̐, tākē thārē hāla nai jāṇakai, mai utsāhita hōūm̐.",null],[2,20,"क्यूँके मेरै धोरै तीमुथियुस के जिसा सुभाव आळा माणस और कोए न्ही सै जो शुद्ध मन तै थारी चिंता करै।","kyūm̐kē mērai dhōrai tīmuthiyusa kē jisā subhāva āḷā māṇasa aura kōē nhī sai jō śuddha mana tai thārī ciṁtā karai.",null],[2,21,"क्यूँके सारे अपणे स्वार्थ की खोज म्ह रहवै सै, परमेसवर के काम्मां खात्तर न्ही।","kyūm̐kē sārē apaṇē svārtha kī khōja mha rahavai sai, paramēsavara kē kāmmāṁ khāttara nhī.",null],[2,22,"पर थम जाणो सों, के तीमुथियुस तो बिश्वास लायक अर आच्छे सुभाव का सै, जिसा बेट्टा पिता कै गेल्या रहवै सै, उसाए उसनै सुसमाचार कै फैलाण म्ह मेरै गैल मेहनत करी।","para thama jāṇō sōṁ, kē tīmuthiyusa tō biśvāsa lāyaka ara ācchē subhāva kā sai, jisā bēṭṭā pitā kai gēlyā rahavai sai, usāē usanai susamācāra kai phailāṇa mha mērai gaila mēhanata karī.",null],[2,23,"इस करकै मन्नै आस सै, कै ज्यो ही मन्नै बेरा लाग्गैगा के मेरा के हाल होगा, त्यों ही मै उसनै तावळी सी भेज देऊँगाँ।","isa karakai mannai āsa sai, kai jyō hī mannai bērā lāggaigā kē mērā kē hāla hōgā, tyōṁ hī mai usanai tāvaḷī sī bhēja dēūm̐gām̐.",null],[2,24,"अर मन्नै प्रभु म्ह भरोस्सा सै, के मै आप भी तावळा आऊँगा।","ara mannai prabhu mha bharōssā sai, kē mai āpa bhī tāvaḷā āūm̐gā.",null],[2,25,"मन्नै इपफ्रुदीतुस नै थारे धोरै भेजणा जरूरी समझा, जो मेरा भाई अर सहकर्मी साथी योध्दा, अर जरूरतां म्ह मेरी मदद करण आळा थारी ओड़ तै भेज्जा गया दूत सै।","mannai ipaphrudītusa nai thārē dhōrai bhējaṇā jarūrī samajhā, jō mērā bhāī ara sahakarmī sāthī yōdhdā, ara jarūratāṁ mha mērī madada karaṇa āḷā thārī ōṛa tai bhējjā gayā dūta sai.",null],[2,26,"क्यूँके उसका मन थारे सारया म्ह लाग्या रह्या था, अर वो बेचैन रहवै था क्यूँके थमनै उसकी बीमारी का हाल सुण्या था।","kyūm̐kē usakā mana thārē sārayā mha lāgyā rahyā thā, ara vō bēcaina rahavai thā kyūm̐kē thamanai usakī bīmārī kā hāla suṇyā thā.",null],[2,27,"पक्का वो बीमार तो होग्या था, उरै ताहीं वो मरण पै था, पर परमेसवर नै उस ताहीं मरण न्ही दिया, अर सिर्फ उस्से पै न्ही पर मेरै पै भी दया करी, ताके मन्नै दुख पै दुख ना हो।","pakkā vō bīmāra tō hōgyā thā, urai tāhīṁ vō maraṇa pai thā, para paramēsavara nai usa tāhīṁ maraṇa nhī diyā, ara sirpha ussē pai nhī para mērai pai bhī dayā karī, tākē mannai dukha pai dukha nā hō.",null],[2,28,"इस करकै मन्नै उस ताहीं भेजण का और भी जत्न करया, के तू उसतै फेर मिलकै आनन्दित हो जा, अर मेरी भी चिन्ता घट जावै।","isa karakai mannai usa tāhīṁ bhējaṇa kā aura bhī jatna karayā, kē tū usatai phēra milakai ānandita hō jā, ara mērī bhī cintā ghaṭa jāvai.",null],[2,29,"इस करकै तू प्रभु म्ह उसतै घणे आनन्द कै गैल मिलये, अर इसा का आदर करया करिये।","isa karakai tū prabhu mha usatai ghaṇē ānanda kai gaila milayē, ara isā kā ādara karayā kariyē.",null],[2,30,"क्यूँके वो मसीह कै काम खात्तर अपणी जान जोखिम म्ह गेर कै मौत कै धोरै आ ग्या था। ताके वो मेरी मदद कर सकै जिस काम नै थम कर न्ही पाये, क्यूँके थम दूर थे।","kyūm̐kē vō masīha kai kāma khāttara apaṇī jāna jōkhima mha gēra kai mauta kai dhōrai ā gyā thā. tākē vō mērī madada kara sakai jisa kāma nai thama kara nhī pāyē, kyūm̐kē thama dūra thē.",null],[3,1,"इस करकै हे मेरै बिश्वासी भाईयो, प्रभु म्ह आनन्दित रहों। वेए बात थारे ताहीं बारबार लिखण म्ह मन्नै तो कोए दिक्कत कोनी होन्दी, पर ये बात थमनै इस्से झूठ्ठे शिक्षाकां तै बचाकै राक्खैगी।","isa karakai hē mērai biśvāsī bhāīyō, prabhu mha ānandita rahōṁ. vēē bāta thārē tāhīṁ bārabāra likhaṇa mha mannai tō kōē dikkata kōnī hōndī, para yē bāta thamanai issē jhūṭhṭhē śikṣākāṁ tai bacākai rākkhaigī.",null],[3,2,"उन बुरे माणसां तै चौक्कस रहों जो कुत्याँ कै समान सै, अर जो कहवै सै, के उद्धार पाण खात्तर खतना करणा जरूरी सै।","una burē māṇasāṁ tai caukkasa rahōṁ jō kutyām̐ kai samāna sai, ara jō kahavai sai, kē uddhāra pāṇa khāttara khatanā karaṇā jarūrī sai.",null],[3,3,"हम्मे परमेसवर के सच्चे लोग सां, जो पवित्र आत्मा की अगुवाई म्ह आराधना करा सां, अर मसीह यीशु पै घमण्ड करा सां, पर अपणे उन काम्मां के जरिये न्ही जो हम शरीर तै करा सां।","hammē paramēsavara kē saccē lōga sāṁ, jō pavitra ātmā kī aguvāī mha ārādhanā karā sāṁ, ara masīha yīśu pai ghamaṇḍa karā sāṁ, para apaṇē una kāmmāṁ kē jariyē nhī jō hama śarīra tai karā sāṁ.",null],[3,4,"पर मै तो शारीरिक काम्मां पै घमण्ड राक्ख सकू सूं। जै किसे और का शारीरिक काम्मां पै घमण्ड राक्खण का विचार हो, तो मै उसतै भी बढ़कै राक्ख सकू सूं।","para mai tō śārīrika kāmmāṁ pai ghamaṇḍa rākkha sakū sūṁ. jai kisē aura kā śārīrika kāmmāṁ pai ghamaṇḍa rākkhaṇa kā vicāra hō, tō mai usatai bhī baṛhakai rākkha sakū sūṁ.",null],[3,5,"परमेसवर के हुकम के मुताबिक जन्म के आठवे दिन मेरा खतना होया, मै जन्म तै इस्राएली अर बिन्‍यामीन कै गोत्र का सूं, मेरे माँ-बाप इब्रानी थे, इस करकै मै भी इब्रानी सूं, अर (मूसा नबी के) नियम-कायदा नै मानण के कारण मै फरीसी भी था।","paramēsavara kē hukama kē mutābika janma kē āṭhavē dina mērā khatanā hōyā, mai janma tai isrāēlī ara binyāmīna kai gōtra kā sūṁ, mērē mām̐-bāpa ibrānī thē, isa karakai mai bhī ibrānī sūṁ, ara (mūsā nabī kē) niyama-kāyadā nai mānaṇa kē kāraṇa mai pharīsī bhī thā.",null],[3,6,"उत्साह कै बारें म्ह जै कहो तो कलीसिया का सतावण आळा, अर सारे यहूदी नियम-कायदा नै मानण आळा था, इस करकै लोग मन्नै धर्मी मान्नै थे।","utsāha kai bārēṁ mha jai kahō tō kalīsiyā kā satāvaṇa āḷā, ara sārē yahūdī niyama-kāyadā nai mānaṇa āḷā thā, isa karakai lōga mannai dharmī mānnai thē.",null],[3,7,"पर जिन बात्तां नै मै लाभ की समझू था, उन ताहीं मन्नै मसीह यीशु कै कारण नुकसान समझ लिया सै।","para jina bāttāṁ nai mai lābha kī samajhū thā, una tāhīṁ mannai masīha yīśu kai kāraṇa nukasāna samajha liyā sai.",null],[3,8,"बल्के अपणे प्रभु मसीह यीशु नै आच्छी तरियां जाणण के महत्व कै आग्गै, मै बाक्की की सारी बात्तां नै बेकार समझू सूं। जिसकै कारण मन्नै उन सारी चिज्जां ताहीं छोड़ दिया सै, अर उननै कूड़ा समझू सूं। ताके मै मसीह नै आच्छी तरियां जाण सकू।","balkē apaṇē prabhu masīha yīśu nai ācchī tariyāṁ jāṇaṇa kē mahatva kai āggai, mai bākkī kī sārī bāttāṁ nai bēkāra samajhū sūṁ. jisakai kāraṇa mannai una sārī cijjāṁ tāhīṁ chōṛa diyā sai, ara unanai kūṛā samajhū sūṁ. tākē mai masīha nai ācchī tariyāṁ jāṇa sakū.",null],[3,9,"अर मै उसका कहलाऊँ, इब मेरी अपणी धार्मिकता वा कोनी जो नियम-कायदा के पुगाण तै आवै सै, बल्के मेरी धार्मिकता वा सै जो सिर्फ परमेसवर की ओड़ तै मसीह पै मेरे बिश्वास करण कै कारण आवै सै।","ara mai usakā kahalāūm̐, iba mērī apaṇī dhārmikatā vā kōnī jō niyama-kāyadā kē pugāṇa tai āvai sai, balkē mērī dhārmikatā vā sai jō sirpha paramēsavara kī ōṛa tai masīha pai mērē biśvāsa karaṇa kai kāraṇa āvai sai.",null],[3,10,"मै चाहूँ सूं, के मसीह नै जाण ल्यु। अर मै उसके पुनरुत्थान के सामर्थ्य नै अनुभव करुँ, अर उसकै गैल दुखां म्ह साझीदार हो कै मसीह की मृत्यु की समानता नै पा सकू।","mai cāhūm̐ sūṁ, kē masīha nai jāṇa lyu. ara mai usakē punarutthāna kē sāmarthya nai anubhava karum̐, ara usakai gaila dukhāṁ mha sājhīdāra hō kai masīha kī mr̥tyu kī samānatā nai pā sakū.",null],[3,11,"ताके मै भी मरे होए माणसां म्ह तै जी उठण आळा म्ह शामिल हो जाऊँ।","tākē mai bhī marē hōē māṇasāṁ mha tai jī uṭhaṇa āḷā mha śāmila hō jāūm̐.",null],[3,12,"इसका यो मतलब कोनी के मन्नै यो सारा काम करया सै, या मै सिध्द हो लिया सूं, मै आग्गै बढ़ण की कोशिश करते जाण लागरया सूं, ताके मन्नै वो मिल जावै, जिसकै खात्तर मसीह यीशु नै मेरै ताहीं चुण्या सै।","isakā yō matalaba kōnī kē mannai yō sārā kāma karayā sai, yā mai sidhda hō liyā sūṁ, mai āggai baṛhaṇa kī kōśiśa karatē jāṇa lāgarayā sūṁ, tākē mannai vō mila jāvai, jisakai khāttara masīha yīśu nai mērai tāhīṁ cuṇyā sai.",null],[3,13,"हे मेरे बिश्वासी भाईयो, मेरे विचार तै मै इस ताहीं इब तक पा न्ही सका सूं, पर हाँ, मै यो जरुर करण लागरया सूं, क्यूँके जो बात हो ली सै, मै उननै भूलकै जो आग्गै होण आळा सै उसकै खात्तर मेहनत करण लागरया सूं।","hē mērē biśvāsī bhāīyō, mērē vicāra tai mai isa tāhīṁ iba taka pā nhī sakā sūṁ, para hām̐, mai yō jarura karaṇa lāgarayā sūṁ, kyūm̐kē jō bāta hō lī sai, mai unanai bhūlakai jō āggai hōṇa āḷā sai usakai khāttara mēhanata karaṇa lāgarayā sūṁ.",null],[3,14,"मै निशान्ने की ओड़ भाज्या चाल्या ज्या सूं ताके वो ईनाम पाऊँ, अर वो ईनाम यो सै के परमेसवर मन्नै सुर्ग म्ह बुलाण लागरया सै क्यूँके मसीह यीशु मेरे खात्तर मरया।","mai niśānnē kī ōṛa bhājyā cālyā jyā sūṁ tākē vō īnāma pāūm̐, ara vō īnāma yō sai kē paramēsavara mannai surga mha bulāṇa lāgarayā sai kyūm̐kē masīha yīśu mērē khāttara marayā.",null],[3,15,"म्हारै म्ह तै जितने आत्मिक रूप तै सिध्द सै, जो इसा विचार राक्खै सै, अर जै किसे बात म्ह थारा ए विचार न्ही हो, तो परमेसवर उस ताहीं भी थारे पै जाहिर कर देगा।","mhārai mha tai jitanē ātmika rūpa tai sidhda sai, jō isā vicāra rākkhai sai, ara jai kisē bāta mha thārā ē vicāra nhī hō, tō paramēsavara usa tāhīṁ bhī thārē pai jāhira kara dēgā.",null],[3,16,"इस करकै हमनै सच के मुताबिक चालणा सै, जो परमेसवर नै म्हारे पै जाहिर करया।","isa karakai hamanai saca kē mutābika cālaṇā sai, jō paramēsavara nai mhārē pai jāhira karayā.",null],[3,17,"हे मेरे बिश्वासी भाईयो, थारा सुभाव मेरे जिसा हो, अर उन माणसां ताहीं पिच्छाणो, जिनका सुभाव मेरे जिसा सै, अर उनकी तरियां जिन्दगी जिओ।","hē mērē biśvāsī bhāīyō, thārā subhāva mērē jisā hō, ara una māṇasāṁ tāhīṁ picchāṇō, jinakā subhāva mērē jisā sai, ara unakī tariyāṁ jindagī jiō.",null],[3,18,"क्यूँके घणेए इसी चाल चाल्लै सै, जिनका जिक्र मन्नै थारे ताहीं बार-बार करया सै, अर इब भी रो-रोकै कहूँ सूं के उनका सुभाव यो दिखावै सै, के वे मसीह कै क्रूस पै मरण के सन्देस का बिरोध करै सै।","kyūm̐kē ghaṇēē isī cāla cāllai sai, jinakā jikra mannai thārē tāhīṁ bāra-bāra karayā sai, ara iba bhī rō-rōkai kahūm̐ sūṁ kē unakā subhāva yō dikhāvai sai, kē vē masīha kai krūsa pai maraṇa kē sandēsa kā birōdha karai sai.",null],[3,19,"उनका अंत विनाश सै, वो अपणी शारीरिक इच्छा नै ए पूरी करणा चाहवै सै, अर वे अपणी शर्म के काम जो वे करै सै, उनपै घमण्ड करै सै, अर दुनियावी चिज्जां के बारें म्ह सोचते रहवै सै।","unakā aṁta vināśa sai, vō apaṇī śārīrika icchā nai ē pūrī karaṇā cāhavai sai, ara vē apaṇī śarma kē kāma jō vē karai sai, unapai ghamaṇḍa karai sai, ara duniyāvī cijjāṁ kē bārēṁ mha sōcatē rahavai sai.",null],[3,20,"पर म्हारा देश सुर्ग म्ह सै, अर हम एक उद्धारकर्ता प्रभु यीशु मसीह के ओड़ै तै आण की बेसबरी तै बाट देखण लाग रहे सां।","para mhārā dēśa surga mha sai, ara hama ēka uddhārakartā prabhu yīśu masīha kē ōṛai tai āṇa kī bēsabarī tai bāṭa dēkhaṇa lāga rahē sāṁ.",null],[3,21,"वो अपणी शक्ति कै असर कै मुताबिक जिसकै जरिये वो सारी चिज्जां नै अपणे बस म्ह कर सकै सै, म्हारी दीन-हीन देह का रूप बदलकै, अपणी देह कै अनुकूल बणा देगा।","vō apaṇī śakti kai asara kai mutābika jisakai jariyē vō sārī cijjāṁ nai apaṇē basa mha kara sakai sai, mhārī dīna-hīna dēha kā rūpa badalakai, apaṇī dēha kai anukūla baṇā dēgā.",null],[4,1,"हे मेरे बिश्वासी भाईयो, मै थारे ताहीं भोत प्यार करुँ सूं, मन्नै थारे तै मिलण की बड़ी इच्छा सै। थम मेरा आनन्द अर मुकुट हो, मजबुत्ती तै बिश्वास करो, अर प्रभु के हुकम नै मानते रहों।","hē mērē biśvāsī bhāīyō, mai thārē tāhīṁ bhōta pyāra karum̐ sūṁ, mannai thārē tai milaṇa kī baṛī icchā sai. thama mērā ānanda ara mukuṭa hō, majabuttī tai biśvāsa karō, ara prabhu kē hukama nai mānatē rahōṁ.",null],[4,2,"मै यूओदिया नै भी समझाऊँ सूं, अर सुन्तुखे नै भी, के थम आप्पस म्ह एक-दुसरे तै बहस मत करो।","mai yūōdiyā nai bhī samajhāūm̐ sūṁ, ara suntukhē nai bhī, kē thama āppasa mha ēka-dusarē tai bahasa mata karō.",null],[4,3,"हे मेरे सच्चे सहकर्मी, मै तेरे तै भी बिनती करुँ सूं के तू उन बिरबानियाँ की लड़ाई बन्द करवाण म्ह मदद कर, क्यूँके उननै मेरै गैल सुसमाचार फैलाण म्ह, क्लेमेंस अर मेरै और सहकर्मियाँ गैल मेहनत करी, जिनके नाम जीवन की किताब म्ह लिखे होए सै।","hē mērē saccē sahakarmī, mai tērē tai bhī binatī karum̐ sūṁ kē tū una birabāniyām̐ kī laṛāī banda karavāṇa mha madada kara, kyūm̐kē unanai mērai gaila susamācāra phailāṇa mha, klēmēṁsa ara mērai aura sahakarmiyām̐ gaila mēhanata karī, jinakē nāma jīvana kī kitāba mha likhē hōē sai.",null],[4,4,"प्रभु म्ह सदा आनन्दित रहों, मै फेर कहूँ सूं, आनन्दित रहों।","prabhu mha sadā ānandita rahōṁ, mai phēra kahūm̐ sūṁ, ānandita rahōṁ.",null],[4,5,"थारी कोमलता सारे माणसां पै जाहिर हो। प्रभु का आणा लोवै सै,","thārī kōmalatā sārē māṇasāṁ pai jāhira hō. prabhu kā āṇā lōvai sai,",null],[4,6,"किसे भी बात की चिंता ना करो, पर हर हालात म्ह थारे निवेदन, प्रार्थना, बिनती अर धन्यवाद कै गैल परमेसवर कै आग्गै पेश करै जावै।","kisē bhī bāta kī ciṁtā nā karō, para hara hālāta mha thārē nivēdana, prārthanā, binatī ara dhanyavāda kai gaila paramēsavara kai āggai pēśa karai jāvai.",null],[4,7,"फेर परमेसवर की शान्ति, जो माणस की समझ तै परै सै, थारे मन अर विचारां नै मसीह यीशु म्ह सुरक्षित राक्खैगी।","phēra paramēsavara kī śānti, jō māṇasa kī samajha tai parai sai, thārē mana ara vicārāṁ nai masīha yīśu mha surakṣita rākkhaigī.",null],[4,8,"इस करकै हे बिश्वासी भाईयो, जो बात सच सै, जो बात आदरणीय, जो धर्मी सै, पवित्र सुहावनी अर जो-जो बात बड़ाई लायक सै, यानी जो भी सद्गुण अर प्रशंसा की बात सै उनपै ए मन लगाया करो।","isa karakai hē biśvāsī bhāīyō, jō bāta saca sai, jō bāta ādaraṇīya, jō dharmī sai, pavitra suhāvanī ara jō-jō bāta baṛāī lāyaka sai, yānī jō bhī sadguṇa ara praśaṁsā kī bāta sai unapai ē mana lagāyā karō.",null],[4,9,"जो बात थमनै मेरै तै सुणी, मेरे म्ह देक्खी, सीखी, अर पाई सै, उननै मान्या करो, फेर शान्ति का परमेसवर थारे गैल रह्वैगा।","jō bāta thamanai mērai tai suṇī, mērē mha dēkkhī, sīkhī, ara pāī sai, unanai mānyā karō, phēra śānti kā paramēsavara thārē gaila rahvaigā.",null],[4,10,"मै प्रभु मै घणा आनन्दित सूं के जिब इतने दिनां कै पाच्छै थारी चिंता मेरै बारें म्ह फेर जाग्गी सै, पक्का थारे शरुआत म्ह भी इसका विचार था, पर थमनै मौक्का न्ही मिला।","mai prabhu mai ghaṇā ānandita sūṁ kē jiba itanē dināṁ kai pācchai thārī ciṁtā mērai bārēṁ mha phēra jāggī sai, pakkā thārē śaruāta mha bhī isakā vicāra thā, para thamanai maukkā nhī milā.",null],[4,11,"क्यूँके मेरे धोरै वो कोनी जो मन्नै चाहिए, पर मन्नै यो सिख्या सै के मै जिन हालातां म्ह मै सूं, उस्से म्ह सब्र करुँ।","kyūm̐kē mērē dhōrai vō kōnī jō mannai cāhiē, para mannai yō sikhyā sai kē mai jina hālātāṁ mha mai sūṁ, ussē mha sabra karum̐.",null],[4,12,"मन्नै कंगाली अर भरपूरी म्ह रहणा सीख लिया सै, हरेक हालातां अर हरेक बात म्ह मन्नै तृप्त अर भूक्खा रहणा, बढ़णा अर घटणा सीख लिया सै।","mannai kaṁgālī ara bharapūrī mha rahaṇā sīkha liyā sai, harēka hālātāṁ ara harēka bāta mha mannai tr̥pta ara bhūkkhā rahaṇā, baṛhaṇā ara ghaṭaṇā sīkha liyā sai.",null],[4,13,"मसीह मन्नै सामर्थ देवै सै उस म्ह मै सब कुछ कर सकू सूं।","masīha mannai sāmartha dēvai sai usa mha mai saba kucha kara sakū sūṁ.",null],[4,14,"तोभी थमनै भला करया के मेरै क्ळेश म्ह मेरे साझीदार होए।","tōbhī thamanai bhalā karayā kē mērai kḷēśa mha mērē sājhīdāra hōē.",null],[4,15,"हे फिलिप्पी नगर के माणसों, थम आप भी जाणो सों के सुसमाचार कै शरुआत म्ह, जिब मै मकिदुनिया परदेस तै बिदा होया, जब थारे अलावा किसे कलीसिया के बिश्वासी नै लेण देण कै बारें म्ह मेरी मदद न्ही करी।","hē philippī nagara kē māṇasōṁ, thama āpa bhī jāṇō sōṁ kē susamācāra kai śaruāta mha, jiba mai makiduniyā paradēsa tai bidā hōyā, jaba thārē alāvā kisē kalīsiyā kē biśvāsī nai lēṇa dēṇa kai bārēṁ mha mērī madada nhī karī.",null],[4,16,"इसे ढाळ थिस्सलुनीके नगर म्ह मेरी जरूरतां नै पूरा करण म्ह थमनै दो बार रपिये भेजकै मेरी मदद करी।","isē ḍhāḷa thissalunīkē nagara mha mērī jarūratāṁ nai pūrā karaṇa mha thamanai dō bāra rapiyē bhējakai mērī madada karī.",null],[4,17,"मै यो न्ही लिखता, के मै दान चाहूँ सूं पर मै चाहूँ सूं के थारे दान के बदले थमनै आशीष मिलै।","mai yō nhī likhatā, kē mai dāna cāhūm̐ sūṁ para mai cāhūm̐ sūṁ kē thārē dāna kē badalē thamanai āśīṣa milai.",null],[4,18,"मेरै धोरै सब कुछ सै, बल्के भोत घणाए सै, जो चीज थमनै इपफ्रुदीतुस कै हाथ तै भेजी थी उननै पाकै मै तृप्त होग्या सूं, थारे दान तो मनमोहक सुगन्धित भेट की तरियां सै, अर उस बलिदान की तरियां सै, जो याजक परमेसवर नै चढ़ावै सै, अर वे उसनै भावै सै।","mērai dhōrai saba kucha sai, balkē bhōta ghaṇāē sai, jō cīja thamanai ipaphrudītusa kai hātha tai bhējī thī unanai pākai mai tr̥pta hōgyā sūṁ, thārē dāna tō manamōhaka sugandhita bhēṭa kī tariyāṁ sai, ara usa balidāna kī tariyāṁ sai, jō yājaka paramēsavara nai caṛhāvai sai, ara vē usanai bhāvai sai.",null],[4,19,"म्हारा पिता परमेसवर, अपणे अपार धन के मुताबिक जो महिमा समेत मसीह यीशु म्ह थारी हरेक जरूरत नै पूरी करैगा।","mhārā pitā paramēsavara, apaṇē apāra dhana kē mutābika jō mahimā samēta masīha yīśu mha thārī harēka jarūrata nai pūrī karaigā.",null],[4,20,"म्हारै परमेसवर अर पिता की बड़ाई युगानुयुग होंदी रहवै। आमीन।","mhārai paramēsavara ara pitā kī baṛāī yugānuyuga hōṁdī rahavai. āmīna.",null],[4,21,"यीशु मसीह म्ह सभी पवित्र माणसां नै, मेरी ओड़ तै नमस्कार कहो। जो बिश्वासी भाई मेरै गैल सै वे थारे ताहीं नमस्कार कहवै सै।","yīśu masīha mha sabhī pavitra māṇasāṁ nai, mērī ōṛa tai namaskāra kahō. jō biśvāsī bhāī mērai gaila sai vē thārē tāhīṁ namaskāra kahavai sai.",null],[4,22,"सारे पवित्र माणस, जो मेरे साथ सै, अर खास करकै वे माणस जो कैसर के घराने तै बिश्वासी बणे सै, थारे ताहीं नमस्कार कहवै सै।","sārē pavitra māṇasa, jō mērē sātha sai, ara khāsa karakai vē māṇasa jō kaisara kē gharānē tai biśvāsī baṇē sai, thārē tāhīṁ namaskāra kahavai sai.",null],[4,23,"म्हारै यीशु मसीह का अनुग्रह थारी आत्मा कै गैल रहवै।","mhārai yīśu masīha kā anugraha thārī ātmā kai gaila rahavai.",null]],"urd":[[1,1,"मसीह ईसा के बन्दों पौलुस और तीमुथियुस की तरफ़ से, फ़िलिप्पियों शहर के सब मुक़द्दसों के नाम जो मसीह ईसा में हैं; निगहबानों और ख़ादिमों समेत ख़त।","masīha īsā kē bandōṁ paulusa aura tīmuthiyusa kī tarafa sē, filippiyōṁ śahara kē saba muqaddasōṁ kē nāma jō masīha īsā mēṁ haiṁ; nigahabānōṁ aura k͟hādimōṁ samēta k͟hata.",null],[1,2,"हमारे बाप ख़ुदा और ख़ुदावन्द 'ईसा मसीह की तरफ़ से तुम्हें फ़ज़ल और इत्मीनान हासिल होता रहे।","hamārē bāpa k͟hudā aura k͟hudāvanda 'īsā masīha kī tarafa sē tumhēṁ fazala aura itmīnāna hāsila hōtā rahē.",null],[1,3,"मैं जब कभी तुम्हें याद करता हूँ, तो अपने ख़ुदा का शुक्र बजा लाता हूँ;","maiṁ jaba kabhī tumhēṁ yāda karatā hūm̐, tō apanē k͟hudā kā śukra bajā lātā hūm̐;",null],[1,4,"और हर एक दुआ में जो तुम्हारे लिए करता हूँ, हमेशा ख़ुशी के साथ तुम सब के लिए दरख़्वास्त करता हूँ।","aura hara ēka duā mēṁ jō tumhārē liē karatā hūm̐, hamēśā k͟huśī kē sātha tuma saba kē liē darak͟hvāsta karatā hūm̐.",null],[1,5,"इस लिए कि तुम पहले दिन से लेकर आज तक ख़ुशख़बरी के फैलाने में शरीक रहे हो।","isa liē ki tuma pahalē dina sē lēkara āja taka k͟huśak͟habarī kē phailānē mēṁ śarīka rahē hō.",null],[1,6,"और मुझे इस बात का भरोसा है कि जिस ने तुम में नेक काम शुरू किए है, वो उसे ईसा मसीह के आने तक पूरा कर देगा।","aura mujhē isa bāta kā bharōsā hai ki jisa nē tuma mēṁ nēka kāma śurū kiē hai, vō usē īsā masīha kē ānē taka pūrā kara dēgā.",null],[1,7,"चुनाँचे ज़रूरी है कि मैं तुम सब के बारे में ऐसा ही ख़याल करूँ, क्यूँकि तुम मेरे दिल में रहते हो, और क़ैद और ख़ुशख़बरी की जवाब दिही और सुबूत में तुम सब मेरे साथ फ़ज़ल में शरीक हो।","cunām̐cē zarūrī hai ki maiṁ tuma saba kē bārē mēṁ aisā hī k͟hayāla karūm̐, kyūm̐ki tuma mērē dila mēṁ rahatē hō, aura qaida aura k͟huśak͟habarī kī javāba dihī aura subūta mēṁ tuma saba mērē sātha fazala mēṁ śarīka hō.",null],[1,8,"ख़ुदा मेरा गवाह है कि मैं ईसा मसीह जैसी महब्बत करके तुम सब को चाहता हूँ।","k͟hudā mērā gavāha hai ki maiṁ īsā masīha jaisī mahabbata karakē tuma saba kō cāhatā hūm̐.",null],[1,9,"और ये दुआ करता हूँ कि तुम्हारी मुहब्बत 'इल्म और हर तरह की तमीज़ के साथ और भी ज़्यादा होती जाए,","aura yē duā karatā hūm̐ ki tumhārī muhabbata 'ilma aura hara taraha kī tamīza kē sātha aura bhī zyādā hōtī jāē,",null],[1,10,"ताकि 'अच्छी अच्छी बातों को पसन्द कर सको, और मसीह के दीन में पाक साफ़ दिल रहो, और ठोकर न खाओ;","tāki 'acchī acchī bātōṁ kō pasanda kara sakō, aura masīha kē dīna mēṁ pāka sāfa dila rahō, aura ṭhōkara na khāō;",null],[1,11,"और रास्तबाज़ी के फल से जो ईसा मसीह के ज़रिए से है, भरे रहो, ताकि ख़ुदा का जलाल ज़ाहिर हो और उसकी सिताइश की जाए।","aura rāstabāzī kē phala sē jō īsā masīha kē zariē sē hai, bharē rahō, tāki k͟hudā kā jalāla zāhira hō aura usakī sitāiśa kī jāē.",null],[1,12,"ए भाइयों! मैं चाहता हूँ कि तुम जान लो कि जो मुझ पर गुज़रा, वो ख़ुशख़बरी की तरक़्क़ी का ज़रिए हुआ।","ē bhāiyōṁ! maiṁ cāhatā hūm̐ ki tuma jāna lō ki jō mujha para guzarā, vō k͟huśak͟habarī kī taraqqī kā zariē huā.",null],[1,13,"यहाँ तक कि मैं क़ैसरी सिपाहियों की सारी पलटन और बाक़ी सब लोगों में मशहूर हो गया कि मैं मसीह के वास्ते क़ैद हूँ;","yahām̐ taka ki maiṁ qaisarī sipāhiyōṁ kī sārī palaṭana aura bāqī saba lōgōṁ mēṁ maśahūra hō gayā ki maiṁ masīha kē vāstē qaida hūm̐;",null],[1,14,"और जो ख़ुदावन्द में भाई हैं, उनमें अक्सर मेरे क़ैद होने के ज़रिए से दिलेर होकर बेख़ौफ़ ख़ुदा का कलाम सुनाने की ज़्यादा हिम्मत करते हैं।","aura jō k͟hudāvanda mēṁ bhāī haiṁ, unamēṁ aksara mērē qaida hōnē kē zariē sē dilēra hōkara bēk͟haufa k͟hudā kā kalāma sunānē kī zyādā himmata karatē haiṁ.",null],[1,15,"कुछ तो हसद और झगड़े की वजह से मसीह का ऐलान करते हैं और कुछ नेक निती से।","kucha tō hasada aura jhagaṛē kī vajaha sē masīha kā ailāna karatē haiṁ aura kucha nēka nitī sē.",null],[1,16,"एक तो मुहब्बत की वजह से मसीह का ऐलान करते हैं कि मैं ख़ुशख़बरी की जवाबदेही के वास्ते मुक़र्रर हूँ।","ēka tō muhabbata kī vajaha sē masīha kā ailāna karatē haiṁ ki maiṁ k͟huśak͟habarī kī javābadēhī kē vāstē muqarrara hūm̐.",null],[1,17,"अगर दूसरे तफ़्रक़े की वजह से न कि साफ़ दिली से, बल्कि इस ख़याल से कि मेरी क़ैद में मेरे लिए मुसीबत पैदा करें।","agara dūsarē tafraqē kī vajaha sē na ki sāfa dilī sē, balki isa k͟hayāla sē ki mērī qaida mēṁ mērē liē musībata paidā karēṁ.",null],[1,18,"पस क्या हुआ? सिर्फ़ ये की हर तरह से मसीह की मनादी होती है, चाहे बहाने से हो चाहे सच्चाई से, और इस से मैं ख़ुश हूँ और रहूँगा भी।","pasa kyā huā? sirfa yē kī hara taraha sē masīha kī manādī hōtī hai, cāhē bahānē sē hō cāhē saccāī sē, aura isa sē maiṁ k͟huśa hūm̐ aura rahūm̐gā bhī.",null],[1,19,"क्यूँकि मैं जानता हूँ कि तुम्हारी दु; आ और 'ईसा मसीह के रूह के इन'आम से इन का अन्जाम मेरी नजात होगा।","kyūm̐ki maiṁ jānatā hūm̐ ki tumhārī du; ā aura 'īsā masīha kē rūha kē ina'āma sē ina kā anjāma mērī najāta hōgā.",null],[1,20,"चुनाँचे मेरी दिली आरज़ू और उम्मीद यही है कि, मैं किसी बात में शर्मिन्दा न हूँ बल्कि मेरी कमाल दिलेरी के ज़रिए जिस तरह मसीह की ताज़ीम मेरे बदन की वजह से हमेशा होती रही है उसी तरह अब भी होगी, चाहे मैं ज़िंदा रहूँ चाहे मरूँ।","cunām̐cē mērī dilī ārazū aura ummīda yahī hai ki, maiṁ kisī bāta mēṁ śarmindā na hūm̐ balki mērī kamāla dilērī kē zariē jisa taraha masīha kī tāzīma mērē badana kī vajaha sē hamēśā hōtī rahī hai usī taraha aba bhī hōgī, cāhē maiṁ ziṁdā rahūm̐ cāhē marūm̐.",null],[1,21,"क्यूँकि ज़िंदा रहना मेरे लिए मसीह और मरना नफ़ा'।","kyūm̐ki ziṁdā rahanā mērē liē masīha aura maranā nafā'.",null],[1,22,"लेकिन अगर मेरा जिस्म में ज़िंदा रहना ही मेरे काम के लिए फ़ाइदा है, तो मैं नहीं जानता किसे पसन्द करूँ।","lēkina agara mērā jisma mēṁ ziṁdā rahanā hī mērē kāma kē liē fāidā hai, tō maiṁ nahīṁ jānatā kisē pasanda karūm̐.",null],[1,23,"मैं दोनों तरफ़ फँसा हुआ हूँ; मेरा जी तो ये चाहता है कि कूच करके मसीह के पास जा रहूँ, क्यूँकि ये बहुत ही बेहतर है;","maiṁ dōnōṁ tarafa pham̐sā huā hūm̐; mērā jī tō yē cāhatā hai ki kūca karakē masīha kē pāsa jā rahūm̐, kyūm̐ki yē bahuta hī bēhatara hai;",null],[1,24,"मगर जिस्म में रहना तुम्हारी ख़ातिर ज़्यादा ज़रूरी है।","magara jisma mēṁ rahanā tumhārī k͟hātira zyādā zarūrī hai.",null],[1,25,"और चूँकि मुझे इसका यक़ीन है इसलिए मैं जानता हूँ कि ज़िंदा रहूँगा, ताकि तुम ईमान में तरक़्क़ी करो और उस में ख़ुश रहो;","aura cūm̐ki mujhē isakā yaqīna hai isaliē maiṁ jānatā hūm̐ ki ziṁdā rahūm̐gā, tāki tuma īmāna mēṁ taraqqī karō aura usa mēṁ k͟huśa rahō;",null],[1,26,"और जो तुम्हें मुझ पर फ़ख़्र है वो मेरे फिर तुम्हारे पास आनेसे मसीह ईसा में ज़्यादा हो जाए","aura jō tumhēṁ mujha para fak͟hra hai vō mērē phira tumhārē pāsa ānēsē masīha īsā mēṁ zyādā hō jāē",null],[1,27,"सिर्फ़ ये करो कि मसीह में तुम्हारा चाल चलन मसीह के ख़ुशख़बरी के मुवाफ़िक़ रहे ताकि; चाहे मैं आऊँ और तुम्हें देखूँ चाहे न आऊँ, तुम्हारा हाल सुनूँ कि तुम एक रूह में क़ाईम हो, और ईन्जील के ईमान के लिए एक जान होकर कोशिश करते हो,","sirfa yē karō ki masīha mēṁ tumhārā cāla calana masīha kē k͟huśak͟habarī kē muvāfiqa rahē tāki; cāhē maiṁ āūm̐ aura tumhēṁ dēkhūm̐ cāhē na āūm̐, tumhārā hāla sunūm̐ ki tuma ēka rūha mēṁ qāīma hō, aura īnjīla kē īmāna kē liē ēka jāna hōkara kōśiśa karatē hō,",null],[1,28,"और किसी बात में मुख़ालिफ़ों से दहशत नहीं खाते। ये उनके लिए हलाकत का साफ़ निशान है; लेकिन तुम्हारी नजात का और ये ख़ुदा की तरफ़ से है।","aura kisī bāta mēṁ muk͟hālifōṁ sē dahaśata nahīṁ khātē. yē unakē liē halākata kā sāfa niśāna hai; lēkina tumhārī najāta kā aura yē k͟hudā kī tarafa sē hai.",null],[1,29,"क्यूँकि मसीह की ख़ातिर तुम पर ये फ़ज़ल हुआ कि न सिर्फ़ उस पर ईमान लाओ बल्कि उसकी ख़ातिर दुःख भी सहो;","kyūm̐ki masīha kī k͟hātira tuma para yē fazala huā ki na sirfa usa para īmāna lāō balki usakī k͟hātira duḥkha bhī sahō;",null],[1,30,"और तुम उसी तरह मेहनत करते रहो जिस तरह मुझे करते देखा था, और अब भी सुनते हो की मैं वैसा ही करता हूँ।","aura tuma usī taraha mēhanata karatē rahō jisa taraha mujhē karatē dēkhā thā, aura aba bhī sunatē hō kī maiṁ vaisā hī karatā hūm̐.",null],[2,1,"पर अगर कुछ तसल्ली मसीह में और मुहब्बत की दिलजम'ई और रूह की शराकत और रहमदिली और — दर्द मन्दी है,","para agara kucha tasallī masīha mēṁ aura muhabbata kī dilajama'ī aura rūha kī śarākata aura rahamadilī aura — darda mandī hai,",null],[2,2,"तो मेरी ख़ुशी पूरी करो कि एक दिल रहो, यक्साँ मुहब्बत रखो एक जान हो, एक ही ख़याल रख्खो।","tō mērī k͟huśī pūrī karō ki ēka dila rahō, yaksām̐ muhabbata rakhō ēka jāna hō, ēka hī k͟hayāla rakhkhō.",null],[2,3,"तफ़्रक़े और बेजा फ़ख़्र के बारे में कुछ न करो, बल्कि फ़रोतनी से एक दूसरे को अपने से बेहतर समझो।","tafraqē aura bējā fak͟hra kē bārē mēṁ kucha na karō, balki farōtanī sē ēka dūsarē kō apanē sē bēhatara samajhō.",null],[2,4,"हर एक अपने ही अहवाल पर नहीं, बल्कि हर एक दूसरों के अहवाल पर भी नज़र रख्खे।","hara ēka apanē hī ahavāla para nahīṁ, balki hara ēka dūsarōṁ kē ahavāla para bhī nazara rakhkhē.",null],[2,5,"वैसा ही मिज़ाज रखो जैसा मसीह ईसा का भी था;","vaisā hī mizāja rakhō jaisā masīha īsā kā bhī thā;",null],[2,6,"उसने अगरचे ख़ुदा की सूरत पर था, ख़ुदा के बराबर होने को क़ब्ज़े के रखने की चीज़ न समझा।","usanē agaracē k͟hudā kī sūrata para thā, k͟hudā kē barābara hōnē kō qabzē kē rakhanē kī cīza na samajhā.",null],[2,7,"बल्कि अपने आप को ख़ाली कर दिया और ख़ादिम की सूरत इख़्तियार की और इंसान ों के मुशाबह हो गया।","balki apanē āpa kō k͟hālī kara diyā aura k͟hādima kī sūrata ik͟htiyāra kī aura iṁsāna ōṁ kē muśābaha hō gayā.",null],[2,8,"और इंसानी सूरत में ज़ाहिर होकर अपने आप को पस्त कर दिया और यहाँ तक फ़रमाँबरदार रहा कि मौत बल्कि सलीबी मौत गंवारा की।","aura iṁsānī sūrata mēṁ zāhira hōkara apanē āpa kō pasta kara diyā aura yahām̐ taka faramām̐baradāra rahā ki mauta balki salībī mauta gaṁvārā kī.",null],[2,9,"इसी वास्ते ख़ुदा ने भी उसे बहुत सर बुलन्द किया और उसे वो नाम बख़्शा जो सब नामों से आ'ला है","isī vāstē k͟hudā nē bhī usē bahuta sara bulanda kiyā aura usē vō nāma bak͟hśā jō saba nāmōṁ sē ā'lā hai",null],[2,10,"ताकि 'ईसा के नाम पर हर एक घुटना झुके; चाहे आसमानियों का हो चाहे ज़मीनियों का, चाहे उनका जो ज़मीन के नीचे हैं।","tāki 'īsā kē nāma para hara ēka ghuṭanā jhukē; cāhē āsamāniyōṁ kā hō cāhē zamīniyōṁ kā, cāhē unakā jō zamīna kē nīcē haiṁ.",null],[2,11,"और ख़ुदा बाप के जलाल के लिए हर एक ज़बान इक़रार करे कि 'ईसा मसीह ख़ुदावन्द है।","aura k͟hudā bāpa kē jalāla kē liē hara ēka zabāna iqarāra karē ki 'īsā masīha k͟hudāvanda hai.",null],[2,12,"पस ए मेरे अज़ीज़ो जिस तरह तुम हमेशा से फ़रमाबरदारी करते आए हो उसी तरह न सिर्फ़ मेरी हाज़िरी में, बल्कि इससे बहुत ज़्यादा मेरी ग़ैर हाज़िरी में डरते और काँपते हुए अपनी नजात का काम किए जाओ;","pasa ē mērē azīzō jisa taraha tuma hamēśā sē faramābaradārī karatē āē hō usī taraha na sirfa mērī hāzirī mēṁ, balki isasē bahuta zyādā mērī ġaira hāzirī mēṁ ḍaratē aura kām̐patē huē apanī najāta kā kāma kiē jāō;",null],[2,13,"क्यूँकि जो तुम में नियत और 'अमल दोनों को, अपने नेक इरादे को अन्जाम देने के लिए पैदा करता वो ख़ुदा है।","kyūm̐ki jō tuma mēṁ niyata aura 'amala dōnōṁ kō, apanē nēka irādē kō anjāma dēnē kē liē paidā karatā vō k͟hudā hai.",null],[2,14,"सब काम शिकायत और तकरार बग़ैर किया करो,","saba kāma śikāyata aura takarāra baġaira kiyā karō,",null],[2,15,"ताकि तुम बे ऐब और भोले हो कर टेढ़े और कजरौ लोगों में ख़ुदा के बेनुक़्स फ़र्ज़न्द बने रहो जिनके बीच दुनिया में तुम चराग़ों की तरह दिखाई देते हो,","tāki tuma bē aiba aura bhōlē hō kara ṭēṛhē aura kajarau lōgōṁ mēṁ k͟hudā kē bēnuqsa farzanda banē rahō jinakē bīca duniyā mēṁ tuma carāġōṁ kī taraha dikhāī dētē hō,",null],[2,16,"और ज़िन्दगी का कलाम पेश करते हो; ताकि मसीह के वापस आने के दिन मुझे तुम पर फ़ख़्र हो कि न मेरी दौड़ — धूप बे फ़ाइदा हुई, न मेरी मेहनत अकारत गई।","aura zindagī kā kalāma pēśa karatē hō; tāki masīha kē vāpasa ānē kē dina mujhē tuma para fak͟hra hō ki na mērī dauṛa — dhūpa bē fāidā huī, na mērī mēhanata akārata gaī.",null],[2,17,"और अगर मुझे तुम्हारे ईमान की क़ुर्बानी और ख़िदमत के साथ अपना ख़ून भी बहाना पड़े, तो भी ख़ुश हूँ और तुम सब के साथ ख़ुशी करता हूँ।","aura agara mujhē tumhārē īmāna kī qurbānī aura k͟hidamata kē sātha apanā k͟hūna bhī bahānā paṛē, tō bhī k͟huśa hūm̐ aura tuma saba kē sātha k͟huśī karatā hūm̐.",null],[2,18,"तुम भी इसी तरह ख़ुश हो और मेरे साथ ख़ुशी करो।","tuma bhī isī taraha k͟huśa hō aura mērē sātha k͟huśī karō.",null],[2,19,"मुझे ख़ुदावन्द' ईसा में ख़ुशी है उम्मीद है कि तीमुथियुस को तुम्हारे पास जल्द भेजूँगा, ताकि तुम्हारा अहवाल दरयाफ़्त करके मेरी भी ख़ातिर जमा हो।","mujhē k͟hudāvanda' īsā mēṁ k͟huśī hai ummīda hai ki tīmuthiyusa kō tumhārē pāsa jalda bhējūm̐gā, tāki tumhārā ahavāla darayāfta karakē mērī bhī k͟hātira jamā hō.",null],[2,20,"क्यूँकि कोई ऐसा हम ख़याल मेरे पास नहीं, जो साफ़ दिली से तुम्हारे लिए फ़िक्रमन्द हो।","kyūm̐ki kōī aisā hama k͟hayāla mērē pāsa nahīṁ, jō sāfa dilī sē tumhārē liē fikramanda hō.",null],[2,21,"सब अपनी अपनी बातों के फ़िक्र में हैं, न कि ईसा मसीह की।","saba apanī apanī bātōṁ kē fikra mēṁ haiṁ, na ki īsā masīha kī.",null],[2,22,"लेकिन तुम उसकी पुख़्तगी से वाक़िफ़ हो कि जैसा बेटा बाप की ख़िदमत करता है, वैसे ही उसने मेरे साथ ख़ुशख़बरी फैलाने में ख़िदमत की।","lēkina tuma usakī puk͟htagī sē vāqifa hō ki jaisā bēṭā bāpa kī k͟hidamata karatā hai, vaisē hī usanē mērē sātha k͟huśak͟habarī phailānē mēṁ k͟hidamata kī.",null],[2,23,"पस मैं उम्मीद करता हूँ कि जब अपने हाल का अन्जाम मालूम कर लूँगा तो उसे फ़ौरन भेज दूँगा।","pasa maiṁ ummīda karatā hūm̐ ki jaba apanē hāla kā anjāma mālūma kara lūm̐gā tō usē faurana bhēja dūm̐gā.",null],[2,24,"और मुझे ख़ुदावन्द पर भरोसा है कि मैं आप भी जल्द आऊँगा।","aura mujhē k͟hudāvanda para bharōsā hai ki maiṁ āpa bhī jalda āūm̐gā.",null],[2,25,"लेकिन मैं ने ईपफ़्रूदीतुस को तुम्हारे पास भेजना ज़रूरी समझा। वो मेरा भाई, और हम ख़िदमत, और मसीह क़ा सिपाही, और तुम्हारा क़ासिद, और मेरी हाजत रफ़ा'करने के लिए ख़ादिम है।","lēkina maiṁ nē īpafrūdītusa kō tumhārē pāsa bhējanā zarūrī samajhā. vō mērā bhāī, aura hama k͟hidamata, aura masīha qā sipāhī, aura tumhārā qāsida, aura mērī hājata rafā'karanē kē liē k͟hādima hai.",null],[2,26,"क्यूँकि वो तुम सब को बहुत चाहता था, और इस वास्ते बे क़रार रहता था कि तूने उसकी बीमारी का हाल सुना था।","kyūm̐ki vō tuma saba kō bahuta cāhatā thā, aura isa vāstē bē qarāra rahatā thā ki tūnē usakī bīmārī kā hāla sunā thā.",null],[2,27,"बेशक वो बीमारी से मरने को था, मगर ख़ुदा ने उस पर रहम किया, सिर्फ़ उस ही पर नहीं बल्कि मुझ पर भी ताकि मुझे ग़म पर ग़म न हो।","bēśaka vō bīmārī sē maranē kō thā, magara k͟hudā nē usa para rahama kiyā, sirfa usa hī para nahīṁ balki mujha para bhī tāki mujhē ġama para ġama na hō.",null],[2,28,"इसी लिए मुझे उसके भेजने का और भी ज़्यादा ख़याल हुआ कि तुम भी उसकी मुलाक़ात से फिर ख़ुश हो जाओ, और मेरा भी ग़म घट जाए।","isī liē mujhē usakē bhējanē kā aura bhī zyādā k͟hayāla huā ki tuma bhī usakī mulāqāta sē phira k͟huśa hō jāō, aura mērā bhī ġama ghaṭa jāē.",null],[2,29,"पस तुम उससे ख़ुदावन्द में कमाल ख़ुशी के साथ मिलना, और ऐसे शख़्सों की' इज़्ज़त किया करो,","pasa tuma usasē k͟hudāvanda mēṁ kamāla k͟huśī kē sātha milanā, aura aisē śak͟hsōṁ kī' izzata kiyā karō,",null],[2,30,"इसलिए कि वो मसीह के काम की ख़ातिर मरने के क़रीब हो गया था, और उसने जान लगा दी ताकि जो कमी तुम्हारी तरफ़ से मेरी ख़िदमत में हुई उसे पूरा करे।","isaliē ki vō masīha kē kāma kī k͟hātira maranē kē qarība hō gayā thā, aura usanē jāna lagā dī tāki jō kamī tumhārī tarafa sē mērī k͟hidamata mēṁ huī usē pūrā karē.",null],[3,1,"ग़रज़ मेरे भाइयों! ख़ुदावन्द में ख़ुश रहो। तुम्हें एक ही बात बार — बार लिखने में मुझे तो कोई दिक़्क़त नहीं, और तुम्हारी इस में हिफ़ाज़त है।","ġaraza mērē bhāiyōṁ! k͟hudāvanda mēṁ k͟huśa rahō. tumhēṁ ēka hī bāta bāra — bāra likhanē mēṁ mujhē tō kōī diqqata nahīṁ, aura tumhārī isa mēṁ hifāzata hai.",null],[3,2,"कुत्तों से ख़बरदार रहो, बदकारों से ख़बरदार रहो कटवाने वालों से ख़बरदार रहो।","kuttōṁ sē k͟habaradāra rahō, badakārōṁ sē k͟habaradāra rahō kaṭavānē vālōṁ sē k͟habaradāra rahō.",null],[3,3,"क्यूँकि मख़्तून तो हम हैं जो ख़ुदा की रूह की हिदायत से ख़ुदा की इबादत करते हैं, और मसीह पर फ़ख़्र करते हैं, और जिस्म का भरोसा नहीं करते।","kyūm̐ki mak͟htūna tō hama haiṁ jō k͟hudā kī rūha kī hidāyata sē k͟hudā kī ibādata karatē haiṁ, aura masīha para fak͟hra karatē haiṁ, aura jisma kā bharōsā nahīṁ karatē.",null],[3,4,"अगर्चे मैं तो जिस्म का भी भरोसा कर सकता हूँ। अगर किसी और को जिस्म पर भरोसा करने का ख़याल हो, तो मैं उससे भी ज़्यादा कर सकता हूँ।","agarcē maiṁ tō jisma kā bhī bharōsā kara sakatā hūm̐. agara kisī aura kō jisma para bharōsā karanē kā k͟hayāla hō, tō maiṁ usasē bhī zyādā kara sakatā hūm̐.",null],[3,5,"आठवें दिन मेरा ख़तना हुआ, इस्राईल की क़ौम और बिनयामीन के क़बीले का हूँ, इबरानियो, का इब्रानी और शरी'अत के ऐ'तिबार से फ़रीसी हूँ","āṭhavēṁ dina mērā k͟hatanā huā, isrāīla kī qauma aura binayāmīna kē qabīlē kā hūm̐, ibarāniyō, kā ibrānī aura śarī'ata kē ai'tibāra sē farīsī hūm̐",null],[3,6,"जोश के एतबार से कलीसिया का, सतानेवाला, शरी'अत की रास्तबाज़ी के ऐतबार से बे 'ऐब था,","jōśa kē ētabāra sē kalīsiyā kā, satānēvālā, śarī'ata kī rāstabāzī kē aitabāra sē bē 'aiba thā,",null],[3,7,"लेकिन जितनी चीज़ें मेरे नफ़े' की थी उन्हीं को मैंने मसीह की ख़ातिर नुक़्सान समझ लिया है।","lēkina jitanī cīzēṁ mērē nafē' kī thī unhīṁ kō maiṁnē masīha kī k͟hātira nuqsāna samajha liyā hai.",null],[3,8,"बल्कि मैंने अपने ख़ुदावन्द मसीह 'ईसा की पहचान की बड़ी ख़ूबी की वजह से सब चीज़ों का नुक़्सान उठाया और उनको कूड़ा समझता हूँ ताकि मसीह को हासिल करूँ","balki maiṁnē apanē k͟hudāvanda masīha 'īsā kī pahacāna kī baṛī k͟hūbī kī vajaha sē saba cīzōṁ kā nuqsāna uṭhāyā aura unakō kūṛā samajhatā hūm̐ tāki masīha kō hāsila karūm̐",null],[3,9,"और उस में पाया जाऊँ, न अपनी उस रास्तबाज़ी के साथ जो शरी'अत की तरफ़ से है, बल्कि उस रास्तबाज़ी के साथ जो मसीह पर ईमान लाने की वजह से है और ख़ुदा की तरफ़ से ईमान पर मिलती है;","aura usa mēṁ pāyā jāūm̐, na apanī usa rāstabāzī kē sātha jō śarī'ata kī tarafa sē hai, balki usa rāstabāzī kē sātha jō masīha para īmāna lānē kī vajaha sē hai aura k͟hudā kī tarafa sē īmāna para milatī hai;",null],[3,10,"और मैं उसको और उसके जी उठने की क़ुदरत को, और उसके साथ दुखों में शरीक होने को मा'लूम करूँ, और उसकी मौत से मुशाबहत पैदा करूँ","aura maiṁ usakō aura usakē jī uṭhanē kī qudarata kō, aura usakē sātha dukhōṁ mēṁ śarīka hōnē kō mā'lūma karūm̐, aura usakī mauta sē muśābahata paidā karūm̐",null],[3,11,"ताकि किसी तरह मुर्दों में से जी उठने के दर्जे तक पहुचूं।","tāki kisī taraha murdōṁ mēṁ sē jī uṭhanē kē darjē taka pahucūṁ.",null],[3,12,"अगर्चे ये नहीं कि मैं पा चुका या कामिल हो चुका हूँ, बल्कि उस चीज़ को पकड़ने को दौड़ा हुआ जाता हूँ जिसके लिए मसीह ईसा 'ने मुझे पकड़ा था।","agarcē yē nahīṁ ki maiṁ pā cukā yā kāmila hō cukā hūm̐, balki usa cīza kō pakaṛanē kō dauṛā huā jātā hūm̐ jisakē liē masīha īsā 'nē mujhē pakaṛā thā.",null],[3,13,"ऐ भाइयों! मेरा ये गुमान नहीं कि पकड़ चुका हूँ; बल्कि सिर्फ़ ये करता हूँ कि जो चीज़ें पीछे रह गई उनको भूल कर, आगे की चीज़ों की तरफ़ बढ़ा हुआ।","ai bhāiyōṁ! mērā yē gumāna nahīṁ ki pakaṛa cukā hūm̐; balki sirfa yē karatā hūm̐ ki jō cīzēṁ pīchē raha gaī unakō bhūla kara, āgē kī cīzōṁ kī tarafa baṛhā huā.",null],[3,14,"निशाने की तरफ़ दौड़ा हुआ जाता हूँ, ताकि उस इनाम को हासिल करूँ जिसके लिए ख़ुदा ने मुझे मसीह ईसा में ऊपर बुलाया है।","niśānē kī tarafa dauṛā huā jātā hūm̐, tāki usa ināma kō hāsila karūm̐ jisakē liē k͟hudā nē mujhē masīha īsā mēṁ ūpara bulāyā hai.",null],[3,15,"पस हम में से जितने कामिल हैं यही ख़याल रखें, और अगर किसी बात में तुम्हारा और तरह का ख़याल हो तो ख़ुदा उस बात को तुम पर भी ज़ाहिर कर देगा।","pasa hama mēṁ sē jitanē kāmila haiṁ yahī k͟hayāla rakhēṁ, aura agara kisī bāta mēṁ tumhārā aura taraha kā k͟hayāla hō tō k͟hudā usa bāta kō tuma para bhī zāhira kara dēgā.",null],[3,16,"बहरहाल जहाँ तक हम पहूँचे हैं उसी के मुताबिक़ चलें।","baharahāla jahām̐ taka hama pahūm̐cē haiṁ usī kē mutābiqa calēṁ.",null],[3,17,"ऐ भाइयों! तुम सब मिलकर मेरी तरह बनो, और उन लोगों की पहचान रखो जो इस तरह चलते हैं जिसका नमूना तुम हम में पाते हो;","ai bhāiyōṁ! tuma saba milakara mērī taraha banō, aura una lōgōṁ kī pahacāna rakhō jō isa taraha calatē haiṁ jisakā namūnā tuma hama mēṁ pātē hō;",null],[3,18,"क्यूँकि बहुत सारे ऐसे हैं जिसका ज़िक्र मैंने तुम से बराबर किया है, और अब भी रो रो कर कहता हूँ कि वो अपने चाल — चलन से मसीह की सलीब के दुश्मन हैं।","kyūm̐ki bahuta sārē aisē haiṁ jisakā zikra maiṁnē tuma sē barābara kiyā hai, aura aba bhī rō rō kara kahatā hūm̐ ki vō apanē cāla — calana sē masīha kī salība kē duśmana haiṁ.",null],[3,19,"उनका अन्जाम हलाकत है, उनका ख़ुदा पेट है, वो अपनी शर्म की बातों पर फ़ख़्र करते हैं और दुनिया की चीज़ों के ख़याल में रहते हैं।","unakā anjāma halākata hai, unakā k͟hudā pēṭa hai, vō apanī śarma kī bātōṁ para fak͟hra karatē haiṁ aura duniyā kī cīzōṁ kē k͟hayāla mēṁ rahatē haiṁ.",null],[3,20,"मगर हमारा वतन असमान पर है हम एक मुन्जी यानी ख़ुदावन्द 'ईसा मसीह के वहाँ से आने के इन्तिज़ार में हैं।","magara hamārā vatana asamāna para hai hama ēka munjī yānī k͟hudāvanda 'īsā masīha kē vahām̐ sē ānē kē intizāra mēṁ haiṁ.",null],[3,21,"वो अपनी उस ताक़त की तासीर के मुवाफ़िक़, जिससे सब चीज़ें अपने ताबे'कर सकता है, हमारी पस्त हाली के बदन की शक्ल बदल कर अपने जलाल के बदन की सूरत बनाएगा।","vō apanī usa tāqata kī tāsīra kē muvāfiqa, jisasē saba cīzēṁ apanē tābē'kara sakatā hai, hamārī pasta hālī kē badana kī śakla badala kara apanē jalāla kē badana kī sūrata banāēgā.",null],[4,1,"इस वास्ते ऐ मेरे प्यारे भाइयों! जिनका मैं मुश्ताक़ हूँ जो मेरी ख़ुशी और ताज हो। ऐ प्यारो! ख़ुदावन्द में इसी तरह क़ाईम रहो।","isa vāstē ai mērē pyārē bhāiyōṁ! jinakā maiṁ muśtāqa hūm̐ jō mērī k͟huśī aura tāja hō. ai pyārō! k͟hudāvanda mēṁ isī taraha qāīma rahō.",null],[4,2,"मैं यहुदिया को भी नसीहत करता हूँ और सुनतुखे को भी कि वो ख़ुदावन्द में एक दिल रहे।","maiṁ yahudiyā kō bhī nasīhata karatā hūm̐ aura sunatukhē kō bhī ki vō k͟hudāvanda mēṁ ēka dila rahē.",null],[4,3,"और ऐ सच्चे हमख़िदमत, तुझ से भी दरख़्वास्त करता हूँ कि तू उन 'औरतों की मदद कर, क्यूँकि उन्होंने ख़ुशख़बरी फैलाने में क्लेमेंस और मेरे बाक़ी उन हम ख़िदमतों समेत मेहनत की, जिनके नाम किताब — ए — हयात में दर्ज हैं।","aura ai saccē hamak͟hidamata, tujha sē bhī darak͟hvāsta karatā hūm̐ ki tū una 'auratōṁ kī madada kara, kyūm̐ki unhōṁnē k͟huśak͟habarī phailānē mēṁ klēmēṁsa aura mērē bāqī una hama k͟hidamatōṁ samēta mēhanata kī, jinakē nāma kitāba — ē — hayāta mēṁ darja haiṁ.",null],[4,4,"ख़ुदावन्द में हर वक़्त ख़ुश रहो; मैं फिर कहता हूँ कि ख़ुश रहो।","k͟hudāvanda mēṁ hara vaqta k͟huśa rahō; maiṁ phira kahatā hūm̐ ki k͟huśa rahō.",null],[4,5,"तुम्हारी नर्म मिज़ाजी सब आदमियों पर ज़ाहिर हो, ख़ुदावन्द क़रीब है।","tumhārī narma mizājī saba ādamiyōṁ para zāhira hō, k͟hudāvanda qarība hai.",null],[4,6,"किसी बात की फ़िक्र न करो, बल्कि हर एक बात में तुम्हारी दरख़्वास्तें दुआ और मिन्नत के वसीले से शुक्रगुज़ारी के साथ ख़ुदा के सामने पेश की जाएँ।","kisī bāta kī fikra na karō, balki hara ēka bāta mēṁ tumhārī darak͟hvāstēṁ duā aura minnata kē vasīlē sē śukraguzārī kē sātha k͟hudā kē sāmanē pēśa kī jāēm̐.",null],[4,7,"तो ख़ुदा का इत्मीनान जो समझ से बिल्कुल बाहर है, वो तुम्हारे दिलो और ख़यालों को मसीह 'ईसा में महफ़ूज़ रखेगा।","tō k͟hudā kā itmīnāna jō samajha sē bilkula bāhara hai, vō tumhārē dilō aura k͟hayālōṁ kō masīha 'īsā mēṁ mahafūza rakhēgā.",null],[4,8,"ग़रज़ ऐ भाइयों! जितनी बातें सच हैं, और जितनी बातें शराफ़त की हैं, और जितनी बातें वाजिब हैं, और जितनी बातें पाक हैं, और जितनी बातें पसन्दीदा हैं, और जितनी बातें दिलकश हैं; ग़रज़ जो नेकी और ता 'रीफ़ की बातें हैं, उन पर ग़ौर किया करो।","ġaraza ai bhāiyōṁ! jitanī bātēṁ saca haiṁ, aura jitanī bātēṁ śarāfata kī haiṁ, aura jitanī bātēṁ vājiba haiṁ, aura jitanī bātēṁ pāka haiṁ, aura jitanī bātēṁ pasandīdā haiṁ, aura jitanī bātēṁ dilakaśa haiṁ; ġaraza jō nēkī aura tā 'rīfa kī bātēṁ haiṁ, una para ġaura kiyā karō.",null],[4,9,"जो बातें तुमने मुझ से सीखीं, और हासिल की, और सुनीं, और मुझ में देखीं, उन पर अमल किया करो, तो ख़ुदा जो इत्मीनान का चश्मा है तुम्हारे साथ रहेगा।","jō bātēṁ tumanē mujha sē sīkhīṁ, aura hāsila kī, aura sunīṁ, aura mujha mēṁ dēkhīṁ, una para amala kiyā karō, tō k͟hudā jō itmīnāna kā caśmā hai tumhārē sātha rahēgā.",null],[4,10,"मैं ख़ुदावन्द में बहुत ख़ुश हूँ कि अब इतनी मुद्दत के बाद तुम्हारा ख़याल मेरे लिए सरसब्ज़ हुआ; बेशक तुम्हें पहले भी इसका ख़याल था, मगर मौक़ा न मिला।","maiṁ k͟hudāvanda mēṁ bahuta k͟huśa hūm̐ ki aba itanī muddata kē bāda tumhārā k͟hayāla mērē liē sarasabza huā; bēśaka tumhēṁ pahalē bhī isakā k͟hayāla thā, magara mauqā na milā.",null],[4,11,"ये नहीं कि मैं मोहताजी के लिहाज़ से कहता हूँ; क्यूँकि मैंने ये सीखा है कि जिस हालत में हूँ उसी पर राज़ी रहूँ","yē nahīṁ ki maiṁ mōhatājī kē lihāza sē kahatā hūm̐; kyūm̐ki maiṁnē yē sīkhā hai ki jisa hālata mēṁ hūm̐ usī para rāzī rahūm̐",null],[4,12,"मैं पस्त होना भी जनता हूँ और बढ़ना भी जनता हूँ; हर एक बात और सब हालतों में मैंने सेर होना, भूखा रहना और बढ़ना घटना सीखा है।","maiṁ pasta hōnā bhī janatā hūm̐ aura baṛhanā bhī janatā hūm̐; hara ēka bāta aura saba hālatōṁ mēṁ maiṁnē sēra hōnā, bhūkhā rahanā aura baṛhanā ghaṭanā sīkhā hai.",null],[4,13,"जो मुझे ताक़त बख़्शता है, उसमें मैं सब कुछ कर सकता हूँ।","jō mujhē tāqata bak͟hśatā hai, usamēṁ maiṁ saba kucha kara sakatā hūm̐.",null],[4,14,"तो भी तुम ने अच्छा किया जो मेरी मुसीबतों में शरीक हुए।","tō bhī tuma nē acchā kiyā jō mērī musībatōṁ mēṁ śarīka huē.",null],[4,15,"और ऐ फिलिप्प्यों! तुम ख़ुद भी जानते हो कि ख़ुशख़बरी के शुरू में, जब मैं मकिदुनिया से रवाना हुआ तो तुम्हारे सिवा किसी कलीसिया ने लेने — देने में मेरी मदद न की।","aura ai philippyōṁ! tuma k͟huda bhī jānatē hō ki k͟huśak͟habarī kē śurū mēṁ, jaba maiṁ makiduniyā sē ravānā huā tō tumhārē sivā kisī kalīsiyā nē lēnē — dēnē mēṁ mērī madada na kī.",null],[4,16,"चुनाँचे थिस्सलुनीकियों में भी मेरी एहतियाज रफ़ा' करने के लिए तुमने एक दफ़ा' नहीं, बल्कि दो दफ़ा' कुछ भेजा था।","cunām̐cē thissalunīkiyōṁ mēṁ bhī mērī ēhatiyāja rafā' karanē kē liē tumanē ēka dafā' nahīṁ, balki dō dafā' kucha bhējā thā.",null],[4,17,"ये नहीं कि मैं ईनाम चाहता हूँ बल्कि ऐसा फल चाहता हूँ जो तुम्हारे हिसाब से ज़्यादा हो जाए","yē nahīṁ ki maiṁ īnāma cāhatā hūm̐ balki aisā phala cāhatā hūm̐ jō tumhārē hisāba sē zyādā hō jāē",null],[4,18,"मेरे पास सब कुछ है, बल्कि बहुतायत से है; तुम्हारी भेजी हुई चीज़ों इप्फ़्र्दितुस के हाथ से लेकर मैं आसूदा हो गया हूँ, वो ख़ुशबू और मक़बूल क़ुर्बानी हैं जो ख़ुदा को पसन्दीदा है।","mērē pāsa saba kucha hai, balki bahutāyata sē hai; tumhārī bhējī huī cīzōṁ ipfrditusa kē hātha sē lēkara maiṁ āsūdā hō gayā hūm̐, vō k͟huśabū aura maqabūla qurbānī haiṁ jō k͟hudā kō pasandīdā hai.",null],[4,19,"मेरा ख़ुदा अपनी दौलत के मुवाफ़िक़ जलाल से मसीह 'ईसा में तुम्हारी हर एक कमी रफ़ा' करेगा।","mērā k͟hudā apanī daulata kē muvāfiqa jalāla sē masīha 'īsā mēṁ tumhārī hara ēka kamī rafā' karēgā.",null],[4,20,"हमारे ख़ुदा और बाप की हमेशा से हमेशा तक बड़ाई होती रहे आमीन","hamārē k͟hudā aura bāpa kī hamēśā sē hamēśā taka baṛāī hōtī rahē āmīna",null],[4,21,"हर एक मुक़द्दस से जो मसीह ईसा में है सलाम कहो। जो भाई मेरे साथ हैं तुम्हें सलाम कहते है।","hara ēka muqaddasa sē jō masīha īsā mēṁ hai salāma kahō. jō bhāī mērē sātha haiṁ tumhēṁ salāma kahatē hai.",null],[4,22,"सब मुक़द्दस खुसूसन, क़ैसर के घर वाले तुम्हें सलाम कहते हैं।","saba muqaddasa khusūsana, qaisara kē ghara vālē tumhēṁ salāma kahatē haiṁ.",null],[4,23,"ख़ुदावन्द ईसा मसीह का फ़ज़ल तुम्हारी रूह के साथ रहे।","k͟hudāvanda īsā masīha kā fazala tumhārī rūha kē sātha rahē.",null]],"dgo":[[1,1,"मसीह यीशु दे दास पोलुस अते तीमुथियुस थमा, सारें पवित्र लोकें दे नां जेके मसीह यीशु च ओइयै फिलिप्पी च रोंह्दे न, मालकैं अते सेवकैं सनै ।","masīha yīśu dē dāsa pōlusa atē tīmuthiyusa thamā, sārēṁ pavitra lōkēṁ dē nāṁ jēkē masīha yīśu ca ōiyai philippī ca rōṁhdē na, mālakaiṁ atē sēvakaiṁ sanai .",null],[1,2,"साहडे प्यो परमात्मा अते प्रभु यीशु मसीह थमा तुसें क्रपा अते शान्ति मिलदी रवै ।","sāhaḍē pyō paramātmā atē prabhu yīśu masīha thamā tusēṁ krapā atē śānti miladī ravai .",null],[1,3,"आऊ जेस जेस ले तुसें याद करना ऐं, उसलै उसलै अपने परमात्मा दा सुकर करना ऐ;","āū jēsa jēsa lē tusēṁ yāda karanā aiṁ, usalai usalai apanē paramātmā dā sukara karanā ai;",null],[1,4,"अते जेस लै कदें थआड़े सारें अस अते बिनती करना ऐ, अते हमेशा खुशी कन्ने बिनती करना ऐ।|","atē jēsa lai kadēṁ thaāṛē sārēṁ asa atē binatī karanā ai, atē hamēśā khuśī kannē binatī karanā ai.|",null],[1,5,"इसे अस अते के तुस पैले धयारे थमा लेइयै अज्ज तकर सनेया गी फलाने अस अते मेरे शामल रे ओ ।","isē asa atē kē tusa pailē dhayārē thamā lēiyai ajja takara sanēyā gī phalānē asa atē mērē śāmala rē ō .",null],[1,6,"मीकी इस गल्ल दा परोसा ऐ जेस ने थआड़े च छैल कम्म शुरू कित्ता ऐ, उए उसे यीशु मसीह दे धयारे तकर पूरा करग ।","mīkī isa galla dā parōsā ai jēsa nē thaāṛē ca chaila kamma śurū kittā ai, uē usē yīśu masīha dē dhayārē takara pūrā karaga .",null],[1,7,"ठीक ऐ के आऊ थआड़े सारे अस अते इय्ये गै बचार करां, कीहके तुस मेरे मने च आई बसे ओ, अते मेरी कैद च अते सनेया अस अते जवाब अते प्रमाण देने च तुस सारे मेरे कन्ने क्रपा च शामल ओ ।","ṭhīka ai kē āū thaāṛē sārē asa atē iyyē gai bacāra karāṁ, kīhakē tusa mērē manē ca āī basē ō, atē mērī kaida ca atē sanēyā asa atē javāba atē pramāṇa dēnē ca tusa sārē mērē kannē krapā ca śāmala ō .",null],[1,8,"इस च परमात्मा मेरा गुआह ऐ के आऊ मसीह यीशु जेई प्रीती करियै थुआढी सारें दी मीद करना ऐ ।","isa ca paramātmā mērā guāha ai kē āū masīha yīśu jēī prītī kariyai thuāḍhī sārēṁ dī mīda karanā ai .",null],[1,9,"आऊ ए प्रार्थना करना ऐ के थुआढे लाड अक्ल अते सारे चाल्ली दे विके क कन्ने अते भी बद्दा जा,","āū ē prārthanā karanā ai kē thuāḍhē lāḍa akla atē sārē cāllī dē vikē ka kannē atē bhī baddā jā,",null],[1,10,"इत्थें तकर के तुस शेअल थमा उत्तम गल्लें गी प्यारा जानो, अते मसीह दे धयारे तकर सच्चे बने रवो, अते ठेडे ना खाओ;","itthēṁ takara kē tusa śēala thamā uttama gallēṁ gī pyārā jānō, atē masīha dē dhayārē takara saccē banē ravō, atē ṭhēḍē nā khāō;",null],[1,11,"अते उस्स तार्मिकता दे फल कन्ने जेके यीशु मसीह दे रहें ओंदे न, परपूर ओंदे जाओ जेस कन्ने परमात्मा दी महिमा अते स्तुति ओंदी रबे ।","atē ussa tārmikatā dē phala kannē jēkē yīśu masīha dē rahēṁ ōṁdē na, parapūra ōṁdē jāō jēsa kannē paramātmā dī mahimā atē stuti ōṁdī rabē .",null],[1,12,"ए भ्राओं, आऊ चाना ऐ के तुस ए जानी लेओ के मेरे उप्पर जो बिता ऐ, उस्स कन्ने सनेया दी बढ़ोतरी ओई ऐ ।","ē bhrāōṁ, āū cānā ai kē tusa ē jānī lēō kē mērē uppara jō bitā ai, ussa kannē sanēyā dī baṛhōtarī ōī ai .",null],[1,13,"इत्थें तकर के कैसर दे राजभवन दी सारी पलटन अते बाकी सारें लोकें च ए परकट ओया ऐ के आऊ मसीह अस अते कैद ऐं;","itthēṁ takara kē kaisara dē rājabhavana dī sārī palaṭana atē bākī sārēṁ lōkēṁ ca ē parakaṭa ōyā ai kē āū masīha asa atē kaida aiṁ;",null],[1,14,"अते प्रभु च जेके प्रा न, उंदे बिचा जनेतर मेरे कैद होने दे कारन, बगैर झक्क दे परमात्मा दा बचन बे धड़क सनाने दा अते भी हिम्मत करनेयां न ।","atē prabhu ca jēkē prā na, uṁdē bicā janētara mērē kaida hōnē dē kārana, bagaira jhakka dē paramātmā dā bacana bē dhaṛaka sanānē dā atē bhī himmata karanēyāṁ na .",null],[1,15,"किश अते ईरखा कन्ने अते किश लड़ाई दे कारन मसीह दा पाशन करदे न अते किश पली मरजी कन्ने ।","kiśa atē īrakhā kannē atē kiśa laṛāī dē kārana masīha dā pāśana karadē na atē kiśa palī marajī kannē .",null],[1,16,"केई इक अते ए जानियै के आऊ सनेया अस अते जवाब देने अस अते ठहराए दा ऐं, लाड कन्ने पाशन करदे न ।","kēī ika atē ē jāniyai kē āū sanēyā asa atē javāba dēnē asa atē ṭhaharāē dā aiṁ, lāḍa kannē pāśana karadē na .",null],[1,17,"अते केई इक अते सिद्धाई कन्ने नेई लेकन बिरोध कन्ने मसीह दी कथा सनांदे न, ए सोंचियै के मेरी कैद च मेरे अस अते क्लेश पैदा करन ।","atē kēī ika atē siddhāī kannē nēī lēkana birōdha kannē masīha dī kathā sanāṁdē na, ē sōṁciyai kē mērī kaida ca mērē asa atē klēśa paidā karana .",null],[1,18,"अते के ओया ? सिर्फ ए के अर चाल्ली कन्ने, चाएं बाने कन्ने चाएं सच्चाई कन्ने, मसीह दी कथा सनाई जांदी ऐ, अते आऊ इस कन्ने खुशी ीत ऐं अते खुशी ीत रोह्गा भी ।","atē kē ōyā ? sirpha ē kē ara cāllī kannē, cāēṁ bānē kannē cāēṁ saccāī kannē, masīha dī kathā sanāī jāṁdī ai, atē āū isa kannē khuśī īta aiṁ atē khuśī īta rōhgā bhī .",null],[1,19,"कीहके आऊ जानना ऐ के थुआढी बिनती दे रहें, अते यीशु मसीह दी आत्मा दे दान दे रहें, इस दा हरफल मेरा उद्धार ओग ।","kīhakē āū jānanā ai kē thuāḍhī binatī dē rahēṁ, atē yīśu masīha dī ātmā dē dāna dē rahēṁ, isa dā haraphala mērā uddhāra ōga .",null],[1,20,"आऊ अते इय्ये हार्दिक मीद अते अस रखना ऐ के आऊ कूसे भी गल्ल च ठीठ नेई उआं, लेकन जिय्यां मेरे प्रबल साहस दे कारन मसीह दी बड़ाई मेरे जीद दे रहें हमेशा ओंदी रेई ऐ, उय्यां गै हूंन भी ओए, चाए आऊ ज़िंदा रवां जां मरी जां ।","āū atē iyyē hārdika mīda atē asa rakhanā ai kē āū kūsē bhī galla ca ṭhīṭha nēī uāṁ, lēkana jiyyāṁ mērē prabala sāhasa dē kārana masīha dī baṛāī mērē jīda dē rahēṁ hamēśā ōṁdī rēī ai, uyyāṁ gai hūṁna bhī ōē, cāē āū ziṁdā ravāṁ jāṁ marī jāṁ .",null],[1,21,"कीहके मेरे अस अते ज़िंदा रोह्ना मसीह ऐ, अते मरी जाना फायदा ऐ ।","kīhakē mērē asa atē ziṁdā rōhnā masīha ai, atē marī jānā phāyadā ai .",null],[1,22,"लेकन जे जीद च ज़िंदा रोह्ना मेरे कम्म अस अते फायदे मंद ऐ अते आऊ नेई जानना के कुसी चुनां ।","lēkana jē jīda ca ziṁdā rōhnā mērē kamma asa atē phāyadē maṁda ai atē āū nēī jānanā kē kusī cunāṁ .",null],[1,23,"कीहके आऊ दोनीं दे बिच खलके पासे लटके दा ऐं; जी अते चांदा ऐ के केछ करियै मसीह दे कोल जाई रवां कीहके ए मता गै छैल ऐ,","kīhakē āū dōnīṁ dē bica khalakē pāsē laṭakē dā aiṁ; jī atē cāṁdā ai kē kēcha kariyai masīha dē kōla jāī ravāṁ kīhakē ē matā gai chaila ai,",null],[1,24,"लेकन जीद च रोह्ना थआड़े कारन अते भी जरुरी ऐ ।","lēkana jīda ca rōhnā thaāṛē kārana atē bhī jarurī ai .",null],[1,25,"इसे अस अते के मीकी इस दा परोसा ऐ इस अस अते आऊ जानना ऐ के आऊ ज़िंदा रोह्गा, बरना थआड़े सबनी दे कन्ने रोह्गा जेस कन्ने तुस सारे परोसा बिच पक्का ओंदे जाओ अते उस्स च खोश ओंदे जाओ;","isē asa atē kē mīkī isa dā parōsā ai isa asa atē āū jānanā ai kē āū ziṁdā rōhgā, baranā thaāṛē sabanī dē kannē rōhgā jēsa kannē tusa sārē parōsā bica pakkā ōṁdē jāō atē ussa ca khōśa ōṁdē jāō;",null],[1,26,"अते जेहडा घमंड तुस मेरे बारे च करदे ओ, ओह मेरे पी थआड़े कोल आने कन्ने मसीह यीशु च अते भी मता बदी जा ।","atē jēhaḍā ghamaṁḍa tusa mērē bārē ca karadē ō, ōha mērē pī thaāṛē kōla ānē kannē masīha yīśu ca atē bhī matā badī jā .",null],[1,27,"सिर्फ इयां करो के थुआढे चालचालन मसीह दे सनेया दे जोगा ओए के चाएं आऊ तुसें आईयै दिखां, चाएं ना भी आं, थआड़े बारे च इय्ये सुनां के तुस इक गै आत्मा च टिके दे ओ, अते इक मन होइयै सनेया दे परोसा अस अते मेनत करदे रोंह्दे ओ,","sirpha iyāṁ karō kē thuāḍhē cālacālana masīha dē sanēyā dē jōgā ōē kē cāēṁ āū tusēṁ āīyai dikhāṁ, cāēṁ nā bhī āṁ, thaāṛē bārē ca iyyē sunāṁ kē tusa ika gai ātmā ca ṭikē dē ō, atē ika mana hōiyai sanēyā dē parōsā asa atē mēnata karadē rōṁhdē ō,",null],[1,28,"अते कूसे गल्ल च बिरोधियें थमा नेई डरदे । ए उंदे अस अते विनाश दी साफ़ नशानी ऐ, लेकन थआड़े अस अते उद्धार दा अते ए परमात्मा दी बखी दा ऐ ।","atē kūsē galla ca birōdhiyēṁ thamā nēī ḍaradē . ē uṁdē asa atē vināśa dī sāfa naśānī ai, lēkana thaāṛē asa atē uddhāra dā atē ē paramātmā dī bakhī dā ai .",null],[1,29,"कीहके मसीह दे कारन थआड़े उप्पर ए क्रपा ओया के ना सिर्फ ओहदे उप्पर परोसा करो लेकन उस्स अस अते दुःख भी चुको;","kīhakē masīha dē kārana thaāṛē uppara ē krapā ōyā kē nā sirpha ōhadē uppara parōsā karō lēkana ussa asa atē duḥkha bhī cukō;",null],[1,30,"अते तुसें उय्यां गै मेनत करनी ऐ, जिय्यां तुसैं मीकी करदे दिखया ऐ, अते हूंन भी सुनदे ओ के आऊ उय्यां गै करना ऐ ।","atē tusēṁ uyyāṁ gai mēnata karanī ai, jiyyāṁ tusaiṁ mīkī karadē dikhayā ai, atē hūṁna bhī sunadē ō kē āū uyyāṁ gai karanā ai .",null],[2,1,"इस अस अते मसीह च किश शान्ति, अते लाड कन्ने ढ़ारस, अते आत्मा दी सहपासेिता, अते किश करुणा अते दया ऐ,","isa asa atē masīha ca kiśa śānti, atē lāḍa kannē ṛhārasa, atē ātmā dī sahapāsēitā, atē kiśa karuṇā atē dayā ai,",null],[2,2,"अते मेरा ए आनद पूरा करो के इक मन रवो, अते इक गै लाड, इक गै चित्त, इक गै बचार रखो ।","atē mērā ē ānada pūrā karō kē ika mana ravō, atē ika gai lāḍa, ika gai citta, ika gai bacāra rakhō .",null],[2,3,"बिरोध जां झूठी बड़ाई अस अते किश नी करो, लेकन दीनता कन्ने इक दुए गी अपने थमा छैल समझो ।","birōdha jāṁ jhūṭhī baṛāī asa atē kiśa nī karō, lēkana dīnatā kannē ika duē gī apanē thamā chaila samajhō .",null],[2,4,"अर इक अपने गै फायदे दी नेई, बरना दुएं दे फायदे दी भी चिंता करै ।","ara ika apanē gai phāyadē dī nēī, baranā duēṁ dē phāyadē dī bhī ciṁtā karai .",null],[2,5,"जिय्यां मसीह यीशु दा सभाव हा इय्यां गै थुआढे भी सभाव ओए;","jiyyāṁ masīha yīśu dā sabhāva hā iyyāṁ gai thuāḍhē bhī sabhāva ōē;",null],[2,6,"जेस ने परमात्मा दे स्वरूप च ओंदे ओई भी परमात्मा दे तुल ओने गी अपने वस च रखने दी चीज नेई समझया ।","jēsa nē paramātmā dē svarūpa ca ōṁdē ōī bhī paramātmā dē tula ōnē gī apanē vasa ca rakhanē dī cīja nēī samajhayā .",null],[2,7,"बरना अपने आप गी ऐसा जीरो करी दिता, अते दास दा स्वरूप धारण कित्ता, अते मनुक्ख दी लेखाता च ओई गया ।","baranā apanē āpa gī aisā jīrō karī ditā, atē dāsa dā svarūpa dhāraṇa kittā, atē manukkha dī lēkhātā ca ōī gayā .",null],[2,8,"अते मनुक्ख दे रूप च परकट ओइयै अपने आप गी दीन करी दिता, अते इत्थें तकर उक्म कारी रेया के मोत, आं, सुल्ली दी मोत भी सेई लेई ।","atē manukkha dē rūpa ca parakaṭa ōiyai apanē āpa gī dīna karī ditā, atē itthēṁ takara ukma kārī rēyā kē mōta, āṁ, sullī dī mōta bhī sēī lēī .",null],[2,9,"इस कारन परमात्मा ने उसे अती बढ़ा भी कित्ता, अते उसे ओह नां दिता जेहडा सारें नां च ख़ास ऐ,","isa kārana paramātmā nē usē atī baṛhā bhī kittā, atē usē ōha nāṁ ditā jēhaḍā sārēṁ nāṁ ca k͟hāsa ai,",null],[2,10,"के जेके सुर्ग च अते तरती उप्पर अते तरती दे थले न, ओह सारे यीशु दे नां कन्ने घुटने टेकन;","kē jēkē surga ca atē taratī uppara atē taratī dē thalē na, ōha sārē yīśu dē nāṁ kannē ghuṭanē ṭēkana;",null],[2,11,"अते प्यो परमात्मा दी महिमा अस अते अर इक जीभ अंगीकार करै के यीशु मसीह गै प्रभु ऐ ।","atē pyō paramātmā dī mahimā asa atē ara ika jībha aṁgīkāra karai kē yīśu masīha gai prabhu ai .",null],[2,12,"इसे अस अते ए मेरे प्यारो, जेस चाल्ली तुस हमेशा थमा उक्म मनदे आए ओ, उय्यां गै हूंन भी ना सिर्फ मेरे कन्ने रोंह्दे ओई लेकन ख़ास करियै हूंन मेरे दूर रोह्ने उप्पर भी डरदे अते कंवदे ओई अपने अपने उद्धार दा कम्म पूरा करदे जाओ,","isē asa atē ē mērē pyārō, jēsa cāllī tusa hamēśā thamā ukma manadē āē ō, uyyāṁ gai hūṁna bhī nā sirpha mērē kannē rōṁhdē ōī lēkana k͟hāsa kariyai hūṁna mērē dūra rōhnē uppara bhī ḍaradē atē kaṁvadē ōī apanē apanē uddhāra dā kamma pūrā karadē jāō,",null],[2,13,"कीहके परमात्मा गै ऐ जेस ने अपनी सुमरजी निमित्त थआड़े मने च मरजी अते कम्म, दमै गल्लां करने दा प्रभाव पाएदा ऐ ।","kīhakē paramātmā gai ai jēsa nē apanī sumarajī nimitta thaāṛē manē ca marajī atē kamma, damai gallāṁ karanē dā prabhāva pāēdā ai .",null],[2,14,"सारे कम्म बगैर कुड़कुड़ाऐ अते बगैर तकरार दे करा करो,","sārē kamma bagaira kuṛakuṛāai atē bagaira takarāra dē karā karō,",null],[2,15,"तां जे तुस निर्कसुर अते भोले ओइयै टेड़े अते हठीले लोकें दे बिच परमात्मा दी निष्कलंक संतान बने रवो, जींदे बिच तुस जीवन दा बचन लेई यै संसार च जलदे दियें दे लेखा दिखदे ओ ।","tāṁ jē tusa nirkasura atē bhōlē ōiyai ṭēṛē atē haṭhīlē lōkēṁ dē bica paramātmā dī niṣkalaṁka saṁtāna banē ravō, jīṁdē bica tusa jīvana dā bacana lēī yai saṁsāra ca jaladē diyēṁ dē lēkhā dikhadē ō .",null],[2,16,"के मसीह दे धयारे मीकी घमंड करने दा कारन ओए के ना मेरा दोड़ना अते ना मेरी मेनत करना बेकार ओई ।","kē masīha dē dhayārē mīkī ghamaṁḍa karanē dā kārana ōē kē nā mērā dōṛanā atē nā mērī mēnata karanā bēkāra ōī .",null],[2,17,"जे मीकी थुआढी परोसा रूपी बलिदान अते सेवा दे कन्ने अपना खून भी रूड़ाना पके, तां भी आऊ खोश ऐं अते थआड़े सबनी दे कन्ने खुशी करना ऐ ।","jē mīkī thuāḍhī parōsā rūpī balidāna atē sēvā dē kannē apanā khūna bhī rūṛānā pakē, tāṁ bhī āū khōśa aiṁ atē thaāṛē sabanī dē kannē khuśī karanā ai .",null],[2,18,"उय्यां गै तुस भी खोश उओ अते मेरे कन्ने खुशी करो ।","uyyāṁ gai tusa bhī khōśa uō atē mērē kannē khuśī karō .",null],[2,19,"मीकी प्रभु यीशु च अस ऐ के आऊ तीमुथियुस गी थआड़े कोल फोरन भेजगा, तां जे थुआढी दशा सुनीयै मीकी शान्ति मिलै ।","mīkī prabhu yīśu ca asa ai kē āū tīmuthiyusa gī thaāṛē kōla phōrana bhējagā, tāṁ jē thuāḍhī daśā sunīyai mīkī śānti milai .",null],[2,20,"कीहके मेरे कोल ऐसा सभाव दा कोई नेईयै जेहडा साफ़ मन कन्ने थुआढी चिंता करे ।","kīhakē mērē kōla aisā sabhāva dā kōī nēīyai jēhaḍā sāfa mana kannē thuāḍhī ciṁtā karē .",null],[2,21,"कीहके सारे अपने स्वार्थ दी खोज च रोंह्दे न, ना के यीशु मसीह दी ।","kīhakē sārē apanē svārtha dī khōja ca rōṁhdē na, nā kē yīśu masīha dī .",null],[2,22,"लेकन उसे अते तुसैं परखया अते जानी भी लेता ऐ के जिय्यां जाकत प्यो दे कन्ने करदा ऐ, उय्यां गै उस्स ने सनेया गी फलाने अस अते मेरे कन्ने मेनत किती ।","lēkana usē atē tusaiṁ parakhayā atē jānī bhī lētā ai kē jiyyāṁ jākata pyō dē kannē karadā ai, uyyāṁ gai ussa nē sanēyā gī phalānē asa atē mērē kannē mēnata kitī .",null],[2,23,"इसे आअते मीकी अस ऐ के जिय्यां गै मीकी जानी पोह्ग के मेरी के दशा ओग, उय्यां गै आऊ उसे फोरन भेजी देगा ।","isē āatē mīkī asa ai kē jiyyāṁ gai mīkī jānī pōhga kē mērī kē daśā ōga, uyyāṁ gai āū usē phōrana bhējī dēgā .",null],[2,24,"अते मीकी प्रभु च परोसा ऐ के आऊ अप्पुं भी जल्दी ओगा ।","atē mīkī prabhu ca parōsā ai kē āū appuṁ bhī jaldī ōgā .",null],[2,25,"लेकन आऊ इपफ्रूदीतुस गी जेहडा मेरा प्रा अते सहकर्मी अते संगी जोद्धा अते थुआढे दूत, अते जरूरत गल्लें च मेरी सेवा करने आला ऐ, थआड़े कोल पेजना जरुरी समझया ।","lēkana āū ipaphrūdītusa gī jēhaḍā mērā prā atē sahakarmī atē saṁgī jōddhā atē thuāḍhē dūta, atē jarūrata gallēṁ ca mērī sēvā karanē ālā ai, thaāṛē kōla pējanā jarurī samajhayā .",null],[2,26,"कीहके उस्स दा मन थआड़े सबनीं च लगे दा हा,, इसे कारन ओह व्याकुल रोंह्दा हा कीहके तुसैं उस्स दी बमारी दा आल सुने दा हा ।","kīhakē ussa dā mana thaāṛē sabanīṁ ca lagē dā hā,, isē kārana ōha vyākula rōṁhdā hā kīhakē tusaiṁ ussa dī bamārī dā āla sunē dā hā .",null],[2,27,"जरुरी गै ओह बमार अते ओई गेदा हा इत्थें तकर के मरने उप्पर हा, लेकन परमात्मा ने ओदे उप्पर दया किती, अते सिर्फ ओहदे उप्पर गै नेई लेक मेरे उप्पर भी के मीकी शोक उप्पर शोक ना ओए ।","jarurī gai ōha bamāra atē ōī gēdā hā itthēṁ takara kē maranē uppara hā, lēkana paramātmā nē ōdē uppara dayā kitī, atē sirpha ōhadē uppara gai nēī lēka mērē uppara bhī kē mīkī śōka uppara śōka nā ōē .",null],[2,28,"इसे अस अते आऊ उसे भेजने दी अते भी कोशिश किती के तुस उस्स कन्ने पी मुलाक़ात करियै खोश ओई जाओ अते मेरा भी शोक घटी जाए ।","isē asa atē āū usē bhējanē dī atē bhī kōśiśa kitī kē tusa ussa kannē pī mulāqāta kariyai khōśa ōī jāō atē mērā bhī śōka ghaṭī jāē .",null],[2,29,"इसे अस अते तुस प्रभु च उस्स कन्ने मअते खुशी कन्ने मुलाक़ात करयो, अते ए जें दा आदर करयो,","isē asa atē tusa prabhu ca ussa kannē maatē khuśī kannē mulāqāta karayō, atē ē jēṁ dā ādara karayō,",null],[2,30,"कीहके ओह मसीह दे कम्म अस अते अपने प्राणें उप्पर जोखिम उठाइयै मोत दे कोल आई गया हा तां जे जेकी घटी थुआढी तरफ़ा मेरी सेवा च ओई उसे पूरा करे ।","kīhakē ōha masīha dē kamma asa atē apanē prāṇēṁ uppara jōkhima uṭhāiyai mōta dē kōla āī gayā hā tāṁ jē jēkī ghaṭī thuāḍhī tarafā mērī sēvā ca ōī usē pūrā karē .",null],[3,1,"इसे अस अते ए मेरे भ्राओं, प्रभु च खोश रवो । ओहे गल्लां तुसें बार बार लिखने च मीकी अते कोई दुःख नेई ओंदा,अते इस च थुआढी कुशलता ऐ,","isē asa atē ē mērē bhrāōṁ, prabhu ca khōśa ravō . ōhē gallāṁ tusēṁ bāra bāra likhanē ca mīkī atē kōī duḥkha nēī ōṁdā,atē isa ca thuāḍhī kuśalatā ai,",null],[3,2,"कुत्तां थमा चोकस रवो, उन बुरे कम्म करने आलें थमा चोकस रवो, उन काट कूट करने आलें थमा चोकस रवो ।","kuttāṁ thamā cōkasa ravō, una burē kamma karanē ālēṁ thamā cōkasa ravō, una kāṭa kūṭa karanē ālēṁ thamā cōkasa ravō .",null],[3,3,"कीहके खतना आले अते अस गै ऐन जेके परमात्मा दी आत्मा दी अगुआई कन्ने उपासना करदे न, अते जीद उप्पर परोसा नेई रखदे न ।","kīhakē khatanā ālē atē asa gai aina jēkē paramātmā dī ātmā dī aguāī kannē upāsanā karadē na, atē jīda uppara parōsā nēī rakhadē na .",null],[3,4,"लेकन आऊ अते जीद उप्पर भी परोसा रखी सकना ऐ । जे कुसे अते गी जीद उप्पर परोसा रखने दा बचार उए, अते अते आऊ उस्स थमा भी बद रखी सकना ऐ ।","lēkana āū atē jīda uppara bhī parōsā rakhī sakanā ai . jē kusē atē gī jīda uppara parōsā rakhanē dā bacāra uē, atē atē āū ussa thamā bhī bada rakhī sakanā ai .",null],[3,5,"अठबें धयारे मेरा खतना ओया, इस्राएल दे वंश, अते बिन्यामीन अते गोत्र दा ऐं; इब्रानियें दा इब्रानी ऐं; व्यवस्था दे बारे च जे आखो अते फरीसी ऐं ।","aṭhabēṁ dhayārē mērā khatanā ōyā, isrāēla dē vaṁśa, atē binyāmīna atē gōtra dā aiṁ; ibrāniyēṁ dā ibrānī aiṁ; vyavasthā dē bārē ca jē ākhō atē pharīsī aiṁ .",null],[3,6,"उत्साह दे बारे च आखो अते कलीसिया दा सताने आला; अते व्यवस्था दी तार्मिकता दे बारे च जे आखो अते निर्कसुर हा ।","utsāha dē bārē ca ākhō atē kalīsiyā dā satānē ālā; atē vyavasthā dī tārmikatā dē bārē ca jē ākhō atē nirkasura hā .",null],[3,7,"लेकन जेकी जेकी गल्लां मेरे फायदे दी हियां, उन्हें गै आऊ मसीह दे कारन नुकसान समझी लेता ऐ ।","lēkana jēkī jēkī gallāṁ mērē phāyadē dī hiyāṁ, unhēṁ gai āū masīha dē kārana nukasāna samajhī lētā ai .",null],[3,8,"बरना आऊ अपने प्रभु मसीह यीशु दी पन्शान दी उत्तमता दे कारन सारियें गल्लें गी नुकसान समझना ऐ । जेस दे कन्ने आऊ सारियें चीजें दा नुकसान चुकया, अते उन्हें कूड़ा समझना ऐ, जेस कन्ने आऊ मसीह गी अस ल करां ।","baranā āū apanē prabhu masīha yīśu dī panśāna dī uttamatā dē kārana sāriyēṁ gallēṁ gī nukasāna samajhanā ai . jēsa dē kannē āū sāriyēṁ cījēṁ dā nukasāna cukayā, atē unhēṁ kūṛā samajhanā ai, jēsa kannē āū masīha gī asa la karāṁ .",null],[3,9,"अते उस्स च पाया जां; ना के अपनी उस्स तार्मिकता दे कन्ने, जेकी वयवस्था थमा ऐ, बरना उस्स तार्मिकता दे कन्ने जेकी मसीह उप्पर परोसा करने दे कारन ऐ अते परमात्मा दे तरफा परोसा करने कन्ने मिलदी ऐ ।","atē ussa ca pāyā jāṁ; nā kē apanī ussa tārmikatā dē kannē, jēkī vayavasthā thamā ai, baranā ussa tārmikatā dē kannē jēkī masīha uppara parōsā karanē dē kārana ai atē paramātmā dē taraphā parōsā karanē kannē miladī ai .",null],[3,10,"तां जे आऊ उसे अते उस्स दी मरने दे उप्पर जय पाने दी शक्ति गी, अते ओहदे कन्ने दुखें च शामल ओने दे मर्म गी जानां, अते उस्स दी मोत दी लेखाता गी प्राप्त करां ।","tāṁ jē āū usē atē ussa dī maranē dē uppara jaya pānē dī śakti gī, atē ōhadē kannē dukhēṁ ca śāmala ōnē dē marma gī jānāṁ, atē ussa dī mōta dī lēkhātā gī prāpta karāṁ .",null],[3,11,"के आऊ कूसे भी रिती कन्ने मरें दे बिचा जिंदे ओने दे पद तकर पुज्जी सकां ।","kē āū kūsē bhī ritī kannē marēṁ dē bicā jiṁdē ōnē dē pada takara pujjī sakāṁ .",null],[3,12,"ए मतलब नेई के आऊ पाई चुके दा ऐं, जां सिद्ध ओई चुके दा ऐं; लेकन उस्स चीज गी पकड़ने अस अते दोड़दे चाली आना ऐ, जेस अस अते मसीह यीशु ने मीकी पकड़या हा ।","ē matalaba nēī kē āū pāī cukē dā aiṁ, jāṁ siddha ōī cukē dā aiṁ; lēkana ussa cīja gī pakaṛanē asa atē dōṛadē cālī ānā ai, jēsa asa atē masīha yīśu nē mīkī pakaṛayā hā .",null],[3,13,"ए भ्राओं, मेरी भावना ऐ नेईयैं के आऊ पकड़ी चुके दा ऐं; लेकन सिर्फ ए इक कम्म करना ऐं के जेकी यां गल्लां पीछें रेई गेदियां न उन्हें पुलीयै, अग्गें दी गल्लें आली बखी बददा,","ē bhrāōṁ, mērī bhāvanā ai nēīyaiṁ kē āū pakaṛī cukē dā aiṁ; lēkana sirpha ē ika kamma karanā aiṁ kē jēkī yāṁ gallāṁ pīchēṁ rēī gēdiyāṁ na unhēṁ pulīyai, aggēṁ dī gallēṁ ālī bakhī badadā,",null],[3,14,"नशाने आली बखी दोड़दा चाली जाना ऐ, तां जे ओह नाम पां जेस अस अते परमात्मा ने मीकी मसीह यीशु च उप्पर बलाया ऐ ।","naśānē ālī bakhī dōṛadā cālī jānā ai, tāṁ jē ōha nāma pāṁ jēsa asa atē paramātmā nē mīkī masīha yīśu ca uppara balāyā ai .",null],[3,15,"साहडे बिचा जिनने सिद्ध न, इए बचार रखन, अते जे कुसे गल्ल च थुआढे अते गै बचार ओए अते परमात्मा उसे भी थआड़े उप्पर परकट करी देग ।","sāhaḍē bicā jinanē siddha na, iē bacāra rakhana, atē jē kusē galla ca thuāḍhē atē gai bacāra ōē atē paramātmā usē bhī thaāṛē uppara parakaṭa karī dēga .",null],[3,16,"इसे अस अते जित्थें तकर अस पुज्जे दे न, उसे दे लेखा चालचे ।","isē asa atē jitthēṁ takara asa pujjē dē na, usē dē lēkhā cālacē .",null],[3,17,"ए भ्राओं, तुस सारे मिलियै मेरी जेई चाल चालो, अते उन्हें पन्शान रखो जेके इस रिती उप्पर चालदे न जेस दा उदाअर ण तुस साहडे च पांदे न;","ē bhrāōṁ, tusa sārē miliyai mērī jēī cāla cālō, atē unhēṁ panśāna rakhō jēkē isa ritī uppara cāladē na jēsa dā udāara ṇa tusa sāhaḍē ca pāṁdē na;",null],[3,18,"कीहके मअते सारे ऐसी चाल चालदे न, जेस दी चर्चा आऊ थआड़े कन्ने बार बार किती ऐ, अते हूंन भी रोई रोईयै आखना ऐ के ओह अपनी चाल चालन थमा मसीह दे सुल्ली दे बैरी न ।","kīhakē maatē sārē aisī cāla cāladē na, jēsa dī carcā āū thaāṛē kannē bāra bāra kitī ai, atē hūṁna bhī rōī rōīyai ākhanā ai kē ōha apanī cāla cālana thamā masīha dē sullī dē bairī na .",null],[3,19,"उंदा अंत विनाश ऐ, उंदा ईश्वर टिड्ड ऐ, ओह अपनी बेश्ती दी गल्लें उप्पर घमंड करदे न अते तरती दी चीजें उप्पर मन लाइ रखदे न ।","uṁdā aṁta vināśa ai, uṁdā īśvara ṭiḍḍa ai, ōha apanī bēśtī dī gallēṁ uppara ghamaṁḍa karadē na atē taratī dī cījēṁ uppara mana lāi rakhadē na .",null],[3,20,"लेकन साहड़ा स्वदेश सुर्ग ऐ; अते अस इक उद्धारकर्ता प्रभु यीशु मसीह दे उत्थुंआं आने दा इंतज़ार करा करनेयां न ।","lēkana sāhaṛā svadēśa surga ai; atē asa ika uddhārakartā prabhu yīśu masīha dē utthuṁāṁ ānē dā iṁtazāra karā karanēyāṁ na .",null],[3,21,"ओह अपनी शक्ति दे उस्स प्रभाव दे लेखा जेस दे रहें ओह सारीं चीजें गी अपने वस च करी सकदा ऐ, साहडे दीन हेन जीद दा रूप बदलीयै, अपनी महिमा दी देह दे अनुकूल बनाई देग ।","ōha apanī śakti dē ussa prabhāva dē lēkhā jēsa dē rahēṁ ōha sārīṁ cījēṁ gī apanē vasa ca karī sakadā ai, sāhaḍē dīna hēna jīda dā rūpa badalīyai, apanī mahimā dī dēha dē anukūla banāī dēga .",null],[4,1,"इसे अस अते ए मेरे प्यारे भ्राओं, जींदे च मेरा मन लगा रोंह्दा ऐ, जेहडा मेरा आनद दे मुकुट उए, ए प्यारे भ्राओं, प्रभु च इसे चाल्ली टिके रवो ।","isē asa atē ē mērē pyārē bhrāōṁ, jīṁdē ca mērā mana lagā rōṁhdā ai, jēhaḍā mērā ānada dē mukuṭa uē, ē pyārē bhrāōṁ, prabhu ca isē cāllī ṭikē ravō .",null],[4,2,"आऊ यूओदिया गी भी समझाना ऐ अते सुन्तुखे गी भी, के ओह प्रभु च इक मन रोंह्न ।","āū yūōdiyā gī bhī samajhānā ai atē suntukhē gī bhī, kē ōha prabhu ca ika mana rōṁhna .",null],[4,3,"ए सच्चे सहकर्मी, आऊ अतेरे कन्ने बिनती करना ऐ के तू उन स्त्रियें दी मदद कर, कीहके उन्हैं मेरे कन्ने सनेया फलाने अस अते, क्लेमेंस अते मेरे बाकी सहकर्मियें दे सने मेनत किती, जिंदे नां जीवन दी कताब कग लिखे गेदे न ।","ē saccē sahakarmī, āū atērē kannē binatī karanā ai kē tū una striyēṁ dī madada kara, kīhakē unhaiṁ mērē kannē sanēyā phalānē asa atē, klēmēṁsa atē mērē bākī sahakarmiyēṁ dē sanē mēnata kitī, jiṁdē nāṁ jīvana dī katāba kaga likhē gēdē na .",null],[4,4,"प्रभु च हमेशा खोश रवो; आऊ पी आखना ऐ, खोश रवो ।","prabhu ca hamēśā khōśa ravō; āū pī ākhanā ai, khōśa ravō .",null],[4,5,"थुआढी कोमलता सारें मनुक्खें उप्पर परकट ओए । प्रभु कोल ऐ ।","thuāḍhī kōmalatā sārēṁ manukkhēṁ uppara parakaṭa ōē . prabhu kōla ai .",null],[4,6,"कूसे भी गल्ले दी चिंता नेई करो; लेकन अर इक गल्ल च थआड़े नके दन, प्रार्थना, अते बिनती दे रहें तान्बाद दे कन्ने परमात्मा दे कोल आजर कीअते जांन ।","kūsē bhī gallē dī ciṁtā nēī karō; lēkana ara ika galla ca thaāṛē nakē dana, prārthanā, atē binatī dē rahēṁ tānbāda dē kannē paramātmā dē kōla ājara kīatē jāṁna .",null],[4,7,"उस बेले परमात्मा दी शान्ति, जेकी सारी समझ थमा परे ऐ, थआड़े दिल अते बचारें गी मसीह यीशु च सलामत रखग ।","usa bēlē paramātmā dī śānti, jēkī sārī samajha thamā parē ai, thaāṛē dila atē bacārēṁ gī masīha yīśu ca salāmata rakhaga .",null],[4,8,"इसे अस अते ए भ्राओं, जेकी जेकी यां गल्लां सच न, अते जेकी यां जेकी यां गल्लां आदर दे जोग न, अते जेकी यां जेकी यां गल्लां ठिक न, अते जेकी यां जेकी यां गल्लां पवित्र न, अते जेकी यां जेकी यां गल्लां सुहावनी न, अते जेकी यां जेकी यां गल्लां मने गी भाने आलियां न, मतलब जेकी यां भी सद्गुण अते प्रशंसा दी गल्लां न उंदे उप्पर त्यान लाया करो ।","isē asa atē ē bhrāōṁ, jēkī jēkī yāṁ gallāṁ saca na, atē jēkī yāṁ jēkī yāṁ gallāṁ ādara dē jōga na, atē jēkī yāṁ jēkī yāṁ gallāṁ ṭhika na, atē jēkī yāṁ jēkī yāṁ gallāṁ pavitra na, atē jēkī yāṁ jēkī yāṁ gallāṁ suhāvanī na, atē jēkī yāṁ jēkī yāṁ gallāṁ manē gī bhānē āliyāṁ na, matalaba jēkī yāṁ bhī sadguṇa atē praśaṁsā dī gallāṁ na uṁdē uppara tyāna lāyā karō .",null],[4,9,"जेकी यां गल्लां तुसैं मेरे थमा सिखियां, अते ग्रहण कितियां, अते सुनियां, अते मेरे बिच दिखियां, उंदा गै पालन करा करो, उस बेले परमात्मा जेहडा शान्ति दा सोता ऐ थआड़े कन्ने रोह्ग ।","jēkī yāṁ gallāṁ tusaiṁ mērē thamā sikhiyāṁ, atē grahaṇa kitiyāṁ, atē suniyāṁ, atē mērē bica dikhiyāṁ, uṁdā gai pālana karā karō, usa bēlē paramātmā jēhaḍā śānti dā sōtā ai thaāṛē kannē rōhga .",null],[4,10,"आऊ प्रभु च मता खोश ऐं के हूंन इन्ने धयारें थमा बाद थुआढी चिंता मेरे बारे च पी जागृत ओई ऐ; पक्का तुसें शुरू च भी इस दा बचार हा, लेकन तुसें समां नेई मिलया ।","āū prabhu ca matā khōśa aiṁ kē hūṁna innē dhayārēṁ thamā bāda thuāḍhī ciṁtā mērē bārē ca pī jāgr̥ta ōī ai; pakkā tusēṁ śurū ca bhī isa dā bacāra hā, lēkana tusēṁ samāṁ nēī milayā .",null],[4,11,"ए नेई के आऊ अपनी घटी दे कारन ए आखना ऐ; कीहके आऊ ए सीखे दा ऐ के जेस देश च ऐं; उसे च संदोख करां ।","ē nēī kē āū apanī ghaṭī dē kārana ē ākhanā ai; kīhakē āū ē sīkhē dā ai kē jēsa dēśa ca aiṁ; usē ca saṁdōkha karāṁ .",null],[4,12,"आऊ दीन ओना भी जानना ऐं; अर इक गल्ल अते सारियें दशें च आऊ रजना, भुक्खा रोह्ना, अते बदना अते घटना सीखे दा ऐ ।","āū dīna ōnā bhī jānanā aiṁ; ara ika galla atē sāriyēṁ daśēṁ ca āū rajanā, bhukkhā rōhnā, atē badanā atē ghaṭanā sīkhē dā ai .",null],[4,13,"जेहडा मीकी शक्ति दिंदा ऐ उस्स च आऊ सारा किश करी सकना ऐ ।","jēhaḍā mīkī śakti diṁdā ai ussa ca āū sārā kiśa karī sakanā ai .",null],[4,14,"तां भी तुसैं पला कित्ता के मेरे क्लेश च मेरे शामल ओए ।","tāṁ bhī tusaiṁ palā kittā kē mērē klēśa ca mērē śāmala ōē .",null],[4,15,"ए फिलिप्पियो, तुस अप्पुं भी जानदे ओ के सनेया दी शुरुआत च, जेस लै आऊ मकिदुनिया थमा विदा ओया, उस बेले तुसें शोड़ीयै अते कूसे झोंड ने लेने देने दे बारे च मेरी मदद नेई किती ।","ē philippiyō, tusa appuṁ bhī jānadē ō kē sanēyā dī śuruāta ca, jēsa lai āū makiduniyā thamā vidā ōyā, usa bēlē tusēṁ śōṛīyai atē kūsē jhōṁḍa nē lēnē dēnē dē bārē ca mērī madada nēī kitī .",null],[4,16,"इसे चाल्ली जेस ले आऊ थिस्स्लुनिके च हा, तां भी तुसैं मेरी घटी पुरी करने अस अते इक बारी के बरना दो बारी किश भेजया हा ।","isē cāllī jēsa lē āū thisslunikē ca hā, tāṁ bhī tusaiṁ mērī ghaṭī purī karanē asa atē ika bārī kē baranā dō bārī kiśa bhējayā hā .",null],[4,17,"ए नेई के आऊ दान चाना ऐ लेकन आऊ ऐसा फल चाना ऐ जेहडा थआड़े फायदे अस अते बद्दा जा ।","ē nēī kē āū dāna cānā ai lēkana āū aisā phala cānā ai jēhaḍā thaāṛē phāyadē asa atē baddā jā .",null],[4,18,"मेरे कोल सारा किश ऐ, बरना बडीायत कन्ने भी ऐ, जेकी यां चीजां तुसैं इपफ्रुदीतुस दे हत्थे कन्ने भेजी हियां उन्हें पाइयै आऊ रजी गया ऐं ओह अते सुखदायक सुगंध, ग्रहण करने दे जोग बलिदान ऐ, जेहडा परमात्मा गी भांदा ऐ ।","mērē kōla sārā kiśa ai, baranā baḍīāyata kannē bhī ai, jēkī yāṁ cījāṁ tusaiṁ ipaphrudītusa dē hatthē kannē bhējī hiyāṁ unhēṁ pāiyai āū rajī gayā aiṁ ōha atē sukhadāyaka sugaṁdha, grahaṇa karanē dē jōga balidāna ai, jēhaḍā paramātmā gī bhāṁdā ai .",null],[4,19,"मेरा परमात्मा भी उस्स तन दे लेखा जेकी महिमा स्तुति मसीह यीशु च ऐ, थुआढी अर इक घटी गी पूरी करग ।","mērā paramātmā bhī ussa tana dē lēkhā jēkī mahimā stuti masīha yīśu ca ai, thuāḍhī ara ika ghaṭī gī pūrī karaga .",null],[4,20,"साहडे परमात्मा अते प्यो दी महिमा युग -युग ओंदी रबे । आमीन ।","sāhaḍē paramātmā atē pyō dī mahimā yuga -yuga ōṁdī rabē . āmīna .",null],[4,21,"अर इक पवित्र जन गी, जेहडा यीशु मसीह च ऐ नमस्कार आखो । जेके प्रा मेरे कन्ने न, तुसें नमस्कार आखदे न ।","ara ika pavitra jana gī, jēhaḍā yīśu masīha ca ai namaskāra ākhō . jēkē prā mērē kannē na, tusēṁ namaskāra ākhadē na .",null],[4,22,"सारे पवित्र लोग, ख़ास करियै जेके कैसर दे कराने दे न, तुसें गी नमस्कार आखदे न ।","sārē pavitra lōga, k͟hāsa kariyai jēkē kaisara dē karānē dē na, tusēṁ gī namaskāra ākhadē na .",null],[4,23,"साहडे प्रभु यीशु मसीह दा क्रपा थुआढी आत्मा दे कन्ने रबे ।","sāhaḍē prabhu yīśu masīha dā krapā thuāḍhī ātmā dē kannē rabē .",null]],"xnr":[[1,1,"मसीह यीशु दे दास पौलुस कने तीमुथियुसे दे पास्से ते, सारे पवित्र लोकां दे नां जेह्ड़े मसीह यीशु च होई नैं फिलिप्पी च रैंह्दे हन, अधिकारियां कने सेवकां सौगी ।","masīha yīśu dē dāsa paulusa kanē tīmuthiyusē dē pāssē tē, sārē pavitra lōkāṁ dē nāṁ jēhṛē masīha yīśu ca hōī naiṁ philippī ca raiṁhdē hana, adhikāriyāṁ kanē sēvakāṁ saugī .",null],[1,2,"अहां दे पिता परमात्में कने प्रभु यीशु मसीह दे पास्से ते तुहां जो अनुग्रह कने शांति मिलदी रैंह् ।","ahāṁ dē pitā paramātmēṁ kanē prabhu yīśu masīha dē pāssē tē tuhāṁ jō anugraha kanē śāṁti miladī raiṁh .",null],[1,3,"मैं जाह्लू जाह्लू तुहां जो याद करदा, ताह्लू ताह्लू अपणे परमात्में दा धन्यावाद करदा;","maiṁ jāhlū jāhlū tuhāṁ jō yāda karadā, tāhlū tāhlū apaṇē paramātmēṁ dā dhanyāvāda karadā;",null],[1,4,"कने जाह्लू कदी मैं तुहां सारेयां तांई विणती करदा, तां सदा खुशिया नैं विणती करदा ।","kanē jāhlū kadī maiṁ tuhāṁ sārēyāṁ tāṁī viṇatī karadā, tāṁ sadā khuśiyā naiṁ viṇatī karadā .",null],[1,5,"इसतांई कि तुहां पैहले दिन ते लैई नैं अज्जे तिकर सुसमाचार फैलाणे च मेरे सेहभागी रैह् हन ।","isatāṁī ki tuhāṁ paihalē dina tē laiī naiṁ ajjē tikara susamācāra phailāṇē ca mērē sēhabhāgī raih hana .",null],[1,6,"मिन्जो इसा गल्ला दा भरोसा ऐ कि जिन्हीं तुहां च खरा कम्म शुरू कित्ता ऐ, सैई तिस कम्मे जो यीशु मसीह दे दिन तक पूरा करगा ।","minjō isā gallā dā bharōsā ai ki jinhīṁ tuhāṁ ca kharā kamma śurū kittā ai, saiī tisa kammē jō yīśu masīha dē dina taka pūrā karagā .",null],[1,7,"ठीक ऐ कि मैं तुहां सारेयां तांई ऐदेया ई वचार करें, क्जोकि तुहां मेरे मने च बसेयो हन, कने मेरिया कैदा च कने सुसमाचारे तांई जबाब कने प्रमाण दैणे च तुहां सारे मिन्जो सौगी अनुग्रह च साझी हन ।","ṭhīka ai ki maiṁ tuhāṁ sārēyāṁ tāṁī aidēyā ī vacāra karēṁ, kjōki tuhāṁ mērē manē ca basēyō hana, kanē mēriyā kaidā ca kanē susamācārē tāṁī jabāba kanē pramāṇa daiṇē ca tuhāṁ sārē minjō saugī anugraha ca sājhī hana .",null],[1,8,"इस च परमात्मां मेरा गवाह ऐ कि मैं मसीह यीशु दी वसुआस करी नैं तुहां सारेयां दी लालसा करदा ।","isa ca paramātmāṁ mērā gavāha ai ki maiṁ masīha yīśu dī vasuāsa karī naiṁ tuhāṁ sārēyāṁ dī lālasā karadā .",null],[1,9,"मैं एह प्रार्थना करदा कि तुहां दा प्यारे दा ज्ञान कने सब तरांह दे विवेके सौगी होर भी बधदा जां,","maiṁ ēha prārthanā karadā ki tuhāṁ dā pyārē dā jñāna kanē saba tarāṁha dē vivēkē saugī hōra bhī badhadā jāṁ,",null],[1,10,"ऐत्थू तिकर कि तुहां म्हान ते म्हान गल्लां जो प्यारियां जाणां, कने मसीह दे दिन तक सच्चे बणी रैह्आ, कने ठोकर मत खा;","aitthū tikara ki tuhāṁ mhāna tē mhāna gallāṁ jō pyāriyāṁ jāṇāṁ, kanē masīha dē dina taka saccē baṇī raihā, kanē ṭhōkara mata khā;",null],[1,11,"कने तिसा धार्मिकता दे फळे नैं जेह्ड़ा यीशु मसीह दिया बजाह ते हुंदा ऐ, भरपूर होंदे जा जिसते परमात्में दी महिमा कने स्तुति होंदी रैंह् ।","kanē tisā dhārmikatā dē phaḷē naiṁ jēhṛā yīśu masīha diyā bajāha tē huṁdā ai, bharapūra hōṁdē jā jisatē paramātmēṁ dī mahimā kanē stuti hōṁdī raiṁh .",null],[1,12,"हे भाऊओ, मैं चाहंदा कि तुहां एह जाणी लैआ कि मिन्जो पर जेह्ड़ा बितेया ऐ, तिस ते सुसमाचारे दी ई बढ़दी होई ऐ ।","hē bhāūō, maiṁ cāhaṁdā ki tuhāṁ ēha jāṇī laiā ki minjō para jēhṛā bitēyā ai, tisa tē susamācārē dī ī baṛhadī hōī ai .",null],[1,13,"ऐत्थू तिकर कि कैसर दे राजभवने दी सारिया पलटना च कने बाकि सारे लोकां च एह प्रकट होई गैआ ऐ कि मैं मसीह तांई कैद ऐ ;","aitthū tikara ki kaisara dē rājabhavanē dī sāriyā palaṭanā ca kanē bāki sārē lōkāṁ ca ēha prakaṭa hōī gaiā ai ki maiṁ masīha tāṁī kaida ai ;",null],[1,14,"कने प्रभु च जेह्ड़े भाऊ हन, तिन्हां च अधिकांश मेरे कैद होणे दी बजाह नैं, दिल रखी नैं परमात्में दा वचन वसुआस करी नैं सणांणे दी होर भी हिम्मत करदे हन ।","kanē prabhu ca jēhṛē bhāū hana, tinhāṁ ca adhikāṁśa mērē kaida hōṇē dī bajāha naiṁ, dila rakhī naiṁ paramātmēṁ dā vacana vasuāsa karī naiṁ saṇāṁṇē dī hōra bhī himmata karadē hana .",null],[1,15,"कुच्छ तां डाह कने झगड़े दिया बजाह ते मसीह दा प्रचार करदे हन कने कुच्छ खरिया इच्छा नैं ।","kuccha tāṁ ḍāha kanē jhagaṛē diyā bajāha tē masīha dā pracāra karadē hana kanē kuccha khariyā icchā naiṁ .",null],[1,16,"कुच्छना च तां एह जाणी करी कि मैं सुसमाचार तांई जबाब दैणे जो ठेहराया गैआ, प्यारे नैं प्रचार करदे हन ।","kucchanā ca tāṁ ēha jāṇī karī ki maiṁ susamācāra tāṁī jabāba daiṇē jō ṭhēharāyā gaiā, pyārē naiṁ pracāra karadē hana .",null],[1,17,"कने कुच्छना तां सीधाईया नैं नी अपर विरोध नैं मसीह दी काहणी सणादे हन , एह सोची नैं कि मेरिया कैदा च मिन्जो तांई क्लेश पैदा करें ।","kanē kucchanā tāṁ sīdhāīyā naiṁ nī apara virōdha naiṁ masīha dī kāhaṇī saṇādē hana , ēha sōcī naiṁ ki mēriyā kaidā ca minjō tāṁī klēśa paidā karēṁ .",null],[1,18,"तां क्या होया? सिर्फ एह कि हर तरांह ते, चाहे भाने नैं चाहे सचाईया नैं, मसीह दी काहणी सणाई जांदी ऐ, कने मैं इसते खुश ऐ कने खुश रैंह्गा भी ।","tāṁ kyā hōyā? sirpha ēha ki hara tarāṁha tē, cāhē bhānē naiṁ cāhē sacāīyā naiṁ, masīha dī kāhaṇī saṇāī jāṁdī ai, kanē maiṁ isatē khuśa ai kanē khuśa raiṁhgā bhī .",null],[1,19,"क्जोकि मै जाणदा ऐ कि तुहां दिया विणतिया दिया बजाह ते, कने यीशु मसीह दिया आत्मां दे दाने दिया बजह ते, इसदा फळ मेरा उद्धार हुंगा ।","kjōki mai jāṇadā ai ki tuhāṁ diyā viṇatiyā diyā bajāha tē, kanē yīśu masīha diyā ātmāṁ dē dānē diyā bajaha tē, isadā phaḷa mērā uddhāra huṁgā .",null],[1,20,"मैं तां ऐही हार्दिक लालसा कने आशा रखदा कि मैं कुसा भी गल्ला ते शर्मिंदा ना होयें, अपर जिआं मैं पूरिया हिम्मता दिया बजाह ते मसीह दी बड़ाई मेरे शरीरे दिया बजाह ते सदा होंदी रैई ऐ, तिआं ई हुण भी होयें,","maiṁ tāṁ aihī hārdika lālasā kanē āśā rakhadā ki maiṁ kusā bhī gallā tē śarmiṁdā nā hōyēṁ, apara jiāṁ maiṁ pūriyā himmatā diyā bajāha tē masīha dī baṛāī mērē śarīrē diyā bajāha tē sadā hōṁdī raiī ai, tiāṁ ī huṇa bhī hōyēṁ,",null],[1,21,"क्जोकि मिन्जो तांई जिंदा रैहणां मसीह ऐ, कने मरी जाणां फायदा ऐ ।","kjōki minjō tāṁī jiṁdā raihaṇāṁ masīha ai, kanē marī jāṇāṁ phāyadā ai .",null],[1,22,"अपर जे शरीरे च जिंदा रैहणां ई मेरे कम्मे तांई फायदेमंद ऐ तां मैं नी जाणदा कि कुस जो चुणैं ।","apara jē śarīrē ca jiṁdā raihaṇāṁ ī mērē kammē tāṁī phāyadēmaṁda ai tāṁ maiṁ nī jāṇadā ki kusa jō cuṇaiṁ .",null],[1,23,"क्जोकि मैं दूनी दे बीच अधर च लटकेया ऐ; जी तां चाहंदा ऐ कि कूच करी नैं मसीह अल्ल जाई रैंह्, क्जोकि एह बड़ा खरा ऐ,","kjōki maiṁ dūnī dē bīca adhara ca laṭakēyā ai; jī tāṁ cāhaṁdā ai ki kūca karī naiṁ masīha alla jāī raiṁh, kjōki ēha baṛā kharā ai,",null],[1,24,"अपर शरीरे च रैहणां तुहां दिया बजाह ते होर भी जरूरी ऐ ।","apara śarīrē ca raihaṇāṁ tuhāṁ diyā bajāha tē hōra bhī jarūrī ai .",null],[1,25,"इसतांई कि मिन्जो इसदा भरोसा ऐ, कने मैं जाणदा कि मैं जिंदा रैंह्गा, अपर तुहां सारेयां दे सौगी रैंह्गा जिसते तुहां वसुआसे च पक्के होंदे जा कने तिस च खुश रैह्आ;","isatāṁī ki minjō isadā bharōsā ai, kanē maiṁ jāṇadā ki maiṁ jiṁdā raiṁhgā, apara tuhāṁ sārēyāṁ dē saugī raiṁhgā jisatē tuhāṁ vasuāsē ca pakkē hōṁdē jā kanē tisa ca khuśa raihā;",null],[1,26,"कने जेह्ड़ा कमंड तुहां मेरे बारे च करदे हन, सैह मिन्जो भिरी तुहां अल्ल ओणे नैं मसीह यीशु च जादा बधी जां ।","kanē jēhṛā kamaṁḍa tuhāṁ mērē bārē ca karadē hana, saiha minjō bhirī tuhāṁ alla ōṇē naiṁ masīha yīśu ca jādā badhī jāṁ .",null],[1,27,"सिर्फ इतणां करा कि तुहां दा चाल चलण मसीह दे सुसमाचारे जोग्गा होयें कि चां मैं आई नैं तुहां जो दिखें, चां ना भी ओयें, तुहां दे बारे च ऐही सुणैं कि तुहां इक्को ई आत्मां च पक्के हन, कने इक्क मन होई नैं सुसमाचार दे वसुआसे तांई मेहणत करदे रैंह्दे हन ,","sirpha itaṇāṁ karā ki tuhāṁ dā cāla calaṇa masīha dē susamācārē jōggā hōyēṁ ki cāṁ maiṁ āī naiṁ tuhāṁ jō dikhēṁ, cāṁ nā bhī ōyēṁ, tuhāṁ dē bārē ca aihī suṇaiṁ ki tuhāṁ ikkō ī ātmāṁ ca pakkē hana, kanē ikka mana hōī naiṁ susamācāra dē vasuāsē tāṁī mēhaṇata karadē raiṁhdē hana ,",null],[1,28,"कने कुसा गल्ला च विरोधियां ते डर नी खांदे । एह तिन्हां तांई विनाश स्पष्ट नशाण ऐ, अपर तुहां तांई उद्धारे दा कने एह परमात्में दे पास्से ते ऐ ।","kanē kusā gallā ca virōdhiyāṁ tē ḍara nī khāṁdē . ēha tinhāṁ tāṁī vināśa spaṣṭa naśāṇa ai, apara tuhāṁ tāṁī uddhārē dā kanē ēha paramātmēṁ dē pāssē tē ai .",null],[1,29,"क्जोकि मसीह दिया बजाह ते तुहां पर एह अनुग्रह होया कि ना सिर्फ तिस पर वसुआस करा अपर तिस तांई दुख भी उठा;","kjōki masīha diyā bajāha tē tuhāṁ para ēha anugraha hōyā ki nā sirpha tisa para vasuāsa karā apara tisa tāṁī dukha bhī uṭhā;",null],[1,30,"कने तुहां तिआं ई मेहन त करणी ऐ, जिआं तुहां मिन्जो करदे दिख्या ऐ, कने हुण भी सुणदे हन कि मैं तिआं ई करदा ऐ ।","kanē tuhāṁ tiāṁ ī mēhana ta karaṇī ai, jiāṁ tuhāṁ minjō karadē dikhyā ai, kanē huṇa bhī suṇadē hana ki maiṁ tiāṁ ī karadā ai .",null],[2,1,"कने जे मसीह च कुच्छ शांति, कने प्यार ते हौंसला, कने आत्मां दी सेहभागिता, कने कुच्छ करूणा कने दया ऐ ,","kanē jē masīha ca kuccha śāṁti, kanē pyāra tē hauṁsalā, kanē ātmāṁ dī sēhabhāgitā, kanē kuccha karūṇā kanē dayā ai ,",null],[2,2,"तां मेरी एह खुशी पूरी करा कि इक्क मन रैह्आ, कने इक्क ई प्यार इक्क ई चित, कने इक्क ई मणसा रखा ।~","tāṁ mērī ēha khuśī pūrī karā ki ikka mana raihā, kanē ikka ī pyāra ikka ī cita, kanē ikka ī maṇasā rakhā .~",null],[2,3,"विरोध या झूठी बड़ाईया तांई कुच्छ मत करा, अपर दीनता नैं इक्की दूये जो अपणे ते अच्छा समझा ।","virōdha yā jhūṭhī baṛāīyā tāṁī kuccha mata karā, apara dīnatā naiṁ ikkī dūyē jō apaṇē tē acchā samajhā .",null],[2,4,"हर इक्क अपणे ई हित दी नी, अपर दूयेयां दे हित दी भी चिंता करें ।","hara ikka apaṇē ī hita dī nī, apara dūyēyāṁ dē hita dī bhī ciṁtā karēṁ .",null],[2,5,"जिआं मसीह यीशु दा सभाव था तिआं ई तुहां दा भी सभाव होयें;","jiāṁ masīha yīśu dā sabhāva thā tiāṁ ī tuhāṁ dā bhī sabhāva hōyēṁ;",null],[2,6,"जिन्हीं परमात्में दे रुपे च होई नैं भी परमात्में दे तुल्य होणे जो अपने वशे च रखणे दी चीज्ज मत समझा ।","jinhīṁ paramātmēṁ dē rupē ca hōī naiṁ bhī paramātmēṁ dē tulya hōṇē jō apanē vaśē ca rakhaṇē dī cījja mata samajhā .",null],[2,7,"अपर अपणे आप्पे जो देहया जीरो करी दित्ता, कने दासे दा रूप धारण कित्ता, कने माणु दी समाणता च होई गैआ ।","apara apaṇē āppē jō dēhayā jīrō karī dittā, kanē dāsē dā rūpa dhāraṇa kittā, kanē māṇu dī samāṇatā ca hōī gaiā .",null],[2,8,"कने माणु दे रूपे च प्रकट होई नैं अपणे आप्पे जो दीन कित्ता, कने ऐत्थू तिकर आज्ञाकारी रैह्आ कि मौत हाँ, सूलिया दी मौत भी झेली लैई ।","kanē māṇu dē rūpē ca prakaṭa hōī naiṁ apaṇē āppē jō dīna kittā, kanē aitthū tikara ājñākārī raihā ki mauta hām̐, sūliyā dī mauta bhī jhēlī laiī .",null],[2,9,"इसा बजाह ते परमात्में तिस जो अति म्हान भी कित्ता, कने तिस जो सैह नां दित्ता जेह्ड़ा सारे नां च श्रेष्ठ ऐ ,","isā bajāha tē paramātmēṁ tisa jō ati mhāna bhī kittā, kanē tisa jō saiha nāṁ dittā jēhṛā sārē nāṁ ca śrēṣṭha ai ,",null],[2,10,"कि जेह्ड़ा सुअर्ग च कने धरतिया पर कने धरतिया थलै ऐ, सैह सारे यीशु दे नां पर गोडे टेकन;","ki jēhṛā suarga ca kanē dharatiyā para kanē dharatiyā thalai ai, saiha sārē yīśu dē nāṁ para gōḍē ṭēkana;",null],[2,11,"कने परमात्में पिता दी महिमा तांई हर इक्क जीभ अंगीकार करी लें कि यीशु मसीह ई प्रभु ऐ ।","kanē paramātmēṁ pitā dī mahimā tāṁī hara ikka jībha aṁgīkāra karī lēṁ ki yīśu masīha ī prabhu ai .",null],[2,12,"इसतांई हे मेरे प्यारेयो, जिस तरांह तुहां सदा ते हुक्म मनदे आयेयो हन, तिआं ई हुण भी ना सिर्फ मिन्जो सौगी रैंह्दे होये अपर खास करी नैं हुण मेरे दूर रैहणे पर भी डरदे कने कमदे होये, अपणे अपणे उद्धारे दा कम्म पूरा करदे जा;","isatāṁī hē mērē pyārēyō, jisa tarāṁha tuhāṁ sadā tē hukma manadē āyēyō hana, tiāṁ ī huṇa bhī nā sirpha minjō saugī raiṁhdē hōyē apara khāsa karī naiṁ huṇa mērē dūra raihaṇē para bhī ḍaradē kanē kamadē hōyē, apaṇē apaṇē uddhārē dā kamma pūrā karadē jā;",null],[2,13,"क्क्जोकि परमात्मां ई ऐ जिन्हीं अपणी इच्छा दे मताबक तुहां दे मने च इच्छा कने कम्म, दूनी गल्लां दा तिस पर असर करणे दा जोर पाया ऐ ।","kkjōki paramātmāṁ ī ai jinhīṁ apaṇī icchā dē matābaka tuhāṁ dē manē ca icchā kanē kamma, dūnī gallāṁ dā tisa para asara karaṇē dā jōra pāyā ai .",null],[2,14,"सारा कम्म बगैर कुड़कुड़ाये कने बगैर झगड़े दे करा करा,","sārā kamma bagaira kuṛakuṛāyē kanē bagaira jhagaṛē dē karā karā,",null],[2,15,"तांकि तुहां बेकसूर कने भोले होई नैं टेढे कने हठीले लोकां दे बीच परमात्में दे निष्कलंक औलाद बणी रैह्आ, जिन्हां बीच तुहां जिन्दगिया दा वचन लैई करी संसारे च जळदे दिय्यां साइआं दुस्सा दे हन ।","tāṁki tuhāṁ bēkasūra kanē bhōlē hōī naiṁ ṭēḍhē kanē haṭhīlē lōkāṁ dē bīca paramātmēṁ dē niṣkalaṁka aulāda baṇī raihā, jinhāṁ bīca tuhāṁ jindagiyā dā vacana laiī karī saṁsārē ca jaḷadē diyyāṁ sāiāṁ dussā dē hana .",null],[2,16,"कि मसीह दे दिन मिन्जो कमंड करणे दी बजाह हो कि मेरा दौड़णा कने ना मेरी मेहणत करणी बेकार होई ।","ki masīha dē dina minjō kamaṁḍa karaṇē dī bajāha hō ki mērā dauṛaṇā kanē nā mērī mēhaṇata karaṇī bēkāra hōī .",null],[2,17,"जे मिन्जो तुहां वसुआस रूपी बलिदान कने सेवा सौगी अपणां खून बहाणां भी पौयें, तमी मैं खुश ऐ कने तुहां सबना सौगी खुशी मनांदा ऐ ।","jē minjō tuhāṁ vasuāsa rūpī balidāna kanē sēvā saugī apaṇāṁ khūna bahāṇāṁ bhī pauyēṁ, tamī maiṁ khuśa ai kanē tuhāṁ sabanā saugī khuśī manāṁdā ai .",null],[2,18,"तिआं ई तुहां भी खुश होआ कने मिन्जो सौगी खुशी मणा ।","tiāṁ ī tuhāṁ bhī khuśa hōā kanē minjō saugī khuśī maṇā .",null],[2,19,"मिन्जो प्रभु च आशा ऐ कि मैं तीमुथियुस जो तुहां अल्ल तौळी घल्लगा, तांकि तुहां दी हालत सुणी नैं मिन्जो शांति मिले ।","minjō prabhu ca āśā ai ki maiṁ tīmuthiyusa jō tuhāṁ alla tauḷī ghallagā, tāṁki tuhāṁ dī hālata suṇī naiṁ minjō śāṁti milē .",null],[2,20,"क्जोकि मिन्जो अल्ल देहय सभावे दा कोई नी जेह्ड़ा शुद्ध मने नैं तुहां दी चिंता करें ।","kjōki minjō alla dēhaya sabhāvē dā kōī nī jēhṛā śuddha manē naiṁ tuhāṁ dī ciṁtā karēṁ .",null],[2,21,"क्जोकि सारे अपणे सवार्थे दी तोपा च रैंह्दे हन, ना कि यीशु मसीह दी ।","kjōki sārē apaṇē savārthē dī tōpā ca raiṁhdē hana, nā ki yīśu masīha dī .",null],[2,22,"अपर तिसियो तां तुहां परखेया कने जाणी भी लैआ ऐ कि जिआं पुतर बुड़े सौगी करदा ऐ , तिआं ई तिन्हीं सुसमाचार फैलाणे च मिन्जो सौगी मेहणत कित्ती ।","apara tisiyō tāṁ tuhāṁ parakhēyā kanē jāṇī bhī laiā ai ki jiāṁ putara buṛē saugī karadā ai , tiāṁ ī tinhīṁ susamācāra phailāṇē ca minjō saugī mēhaṇata kittī .",null],[2,23,"इसतांई मिन्जो आशा ऐ कि जिआं ई मिन्जो पता लगी जांगा कि मेरी क्या हालत होंगी, तिआं ई मैं तिसियो ताह्लू ई घल्ली दिंगा ।","isatāṁī minjō āśā ai ki jiāṁ ī minjō patā lagī jāṁgā ki mērī kyā hālata hōṁgī, tiāṁ ī maiṁ tisiyō tāhlū ī ghallī diṁgā .",null],[2,24,"कने मिन्जो प्रभु च भरोसा ऐ कि मैं अप्पु भी तौळी ओंगा ।","kanē minjō prabhu ca bharōsā ai ki maiṁ appu bhī tauḷī ōṁgā .",null],[2,25,"अपर मैं इपफ्रुदीतुस जो जेह्ड़ा मेरा भाऊ कने सेहकर्मी कने संगी योद्धा कने तुहां दा दूत, कने जरूरी गल्लां च मेरी सेवा टहल करणे आळा ऐ , तुहां अल्ल घल्लणां जरूरी समझेया ।","apara maiṁ ipaphrudītusa jō jēhṛā mērā bhāū kanē sēhakarmī kanē saṁgī yōddhā kanē tuhāṁ dā dūta, kanē jarūrī gallāṁ ca mērī sēvā ṭahala karaṇē āḷā ai , tuhāṁ alla ghallaṇāṁ jarūrī samajhēyā .",null],[2,26,"क्जोकि तिसदा मन तुहां सारेयां च लगेया था, इसा बजाह ते सैह व्याकुल रैंह्दा था क्जोकि तुहां तिसदिया बमारिया दा हाल सुणेया था ।","kjōki tisadā mana tuhāṁ sārēyāṁ ca lagēyā thā, isā bajāha tē saiha vyākula raiṁhdā thā kjōki tuhāṁ tisadiyā bamāriyā dā hāla suṇēyā thā .",null],[2,27,"पक्का ई सैह बमार तां होई गैआ था ऐत्थू तिकर कि मरणे पर था, अपर परमात्में तिस पर दया कित्ती, कने सिर्फ तिस पर नी अपर मिन्जो पर भी कि मिन्जो शोक पर शोक ना होयें ।","pakkā ī saiha bamāra tāṁ hōī gaiā thā aitthū tikara ki maraṇē para thā, apara paramātmēṁ tisa para dayā kittī, kanē sirpha tisa para nī apara minjō para bhī ki minjō śōka para śōka nā hōyēṁ .",null],[2,28,"इसतांई मैं तिसियो घल्लणे दा होर भी प्रयास कित्ता कि तुहां तिस नैं मिली नैं खुश होई जा कने मेरा भी शोक घटी जाये ।","isatāṁī maiṁ tisiyō ghallaṇē dā hōra bhī prayāsa kittā ki tuhāṁ tisa naiṁ milī naiṁ khuśa hōī jā kanē mērā bhī śōka ghaṭī jāyē .",null],[2,29,"इसतांई तुहां प्रभु च तिस नैं बड़िया खुशिया सौगी मिलणां , कने ऐदेयां दा आदर करा करणां,","isatāṁī tuhāṁ prabhu ca tisa naiṁ baṛiyā khuśiyā saugī milaṇāṁ , kanē aidēyāṁ dā ādara karā karaṇāṁ,",null],[2,30,"क्जोकि सैह मसीह दे कम्मे तांई अपणियां जान्नी जो खतरे च पाई नैं मौता नैड़े आई गैआ था तांकि जेह्ड़ी घटी तुहां दे पास्से ते मेरी सेवा च होई तिसायो पूरा करें ।","kjōki saiha masīha dē kammē tāṁī apaṇiyāṁ jānnī jō khatarē ca pāī naiṁ mautā naiṛē āī gaiā thā tāṁki jēhṛī ghaṭī tuhāṁ dē pāssē tē mērī sēvā ca hōī tisāyō pūrā karēṁ .",null],[3,1,"इसतांई हे मेरे भाऊओ, प्रभु च खुश रैह्आ । सैई गल्लां तुहां जो बार बार लिखणे च मिन्जो तां कोई तकलीफ नी होंदी, कने इस च तुहां सुरक्षित हन ।","isatāṁī hē mērē bhāūō, prabhu ca khuśa raihā . saiī gallāṁ tuhāṁ jō bāra bāra likhaṇē ca minjō tāṁ kōī takalīpha nī hōṁdī, kanē isa ca tuhāṁ surakṣita hana .",null],[3,2,"कुतेयां ते चुकनै रैह्आ, कने बुरे कम्म करणेआळेयां ते सावधाण रैह्आ, कने काट कूट करणेआळेयां ते चौकस रैह्आ ।","kutēyāṁ tē cukanai raihā, kanē burē kamma karaṇēāḷēyāṁ tē sāvadhāṇa raihā, kanē kāṭa kūṭa karaṇēāḷēyāṁ tē caukasa raihā .",null],[3,3,"क्जोकि खतणांआळे तां अहां ई हन जेह्ड़े परमात्में दी आत्मां दी अगुआई ते भक्ति करदे हन, कने मसीह यीशु पर कमंड करदे हन, कने शरीर पर भरोसा नी रखदे ।","kjōki khataṇāṁāḷē tāṁ ahāṁ ī hana jēhṛē paramātmēṁ dī ātmāṁ dī aguāī tē bhakti karadē hana, kanē masīha yīśu para kamaṁḍa karadē hana, kanē śarīra para bharōsā nī rakhadē .",null],[3,4,"अपर मैं तां शरीर पर भी भरोसा रखी सकदा । जे कुसी होर जो शरीरे पर भरोसा रखणे दा वचार होयें, तां मैं तिस ते भी बधी करी रखी सकदा ।","apara maiṁ tāṁ śarīra para bhī bharōsā rakhī sakadā . jē kusī hōra jō śarīrē para bharōsā rakhaṇē dā vacāra hōyēṁ, tāṁ maiṁ tisa tē bhī badhī karī rakhī sakadā .",null],[3,5,"अठमे दिने मेरा खतणां होया, इस्राएल दे वंश कने बिन्यामीन दे गोत्रे दा ऐ; इब्रानियां दा इब्रानी; व्यवस्था दे बारे च जे ग्लान तां फरीसी ।","aṭhamē dinē mērā khataṇāṁ hōyā, isrāēla dē vaṁśa kanē binyāmīna dē gōtrē dā ai; ibrāniyāṁ dā ibrānī; vyavasthā dē bārē ca jē glāna tāṁ pharīsī .",null],[3,6,"जोशे दे बारे च जे ग्लान तां कलेसिया जो सताणेआळा; कने व्यवस्था दी धार्मिकता दे बारे च जे ग्लान तां बेकसूर था ।","jōśē dē bārē ca jē glāna tāṁ kalēsiyā jō satāṇēāḷā; kanē vyavasthā dī dhārmikatā dē bārē ca jē glāna tāṁ bēkasūra thā .",null],[3,7,"अपर जेह्ड़ियां जेह्ड़ियां गल्लां मेरे फायदे दियां थियां, तिन्हां ई जो मैं मसीह दिया बजाह ते नकसान समझी लैआ ऐ ।","apara jēhṛiyāṁ jēhṛiyāṁ gallāṁ mērē phāyadē diyāṁ thiyāṁ, tinhāṁ ī jō maiṁ masīha diyā bajāha tē nakasāna samajhī laiā ai .",null],[3,8,"जे मैं अपणे प्रभु मसीह यीशु दी पैहचाणा दी उतमता दिया बजाह ते मैं सारियां गल्लां जो नकसान समझदा । जिसदिया बजाह ते मैं सारियां चीज्जां दी नकसान उठाया, कने तिन्हां जो कूड़ा समझदा, जिसते मैं मसीह जो हासल करें,","jē maiṁ apaṇē prabhu masīha yīśu dī paihacāṇā dī utamatā diyā bajāha tē maiṁ sāriyāṁ gallāṁ jō nakasāna samajhadā . jisadiyā bajāha tē maiṁ sāriyāṁ cījjāṁ dī nakasāna uṭhāyā, kanē tinhāṁ jō kūṛā samajhadā, jisatē maiṁ masīha jō hāsala karēṁ,",null],[3,9,"कने तिस च पाया जां; ना कि अपणी तिसा धार्मिकता दे सौगी, जेह्ड़ा व्यवस्था ते ऐ, जे तिसा धार्मिकता दे सौगी जेह्ड़ा मसीह पर वसुआस करणे दी बजाह ऐ कने परमात्में दे पास्से ते वसुआस करणे पर मिलदी ऐ ,","kanē tisa ca pāyā jāṁ; nā ki apaṇī tisā dhārmikatā dē saugī, jēhṛā vyavasthā tē ai, jē tisā dhārmikatā dē saugī jēhṛā masīha para vasuāsa karaṇē dī bajāha ai kanē paramātmēṁ dē pāssē tē vasuāsa karaṇē para miladī ai ,",null],[3,10,"तांकि मैं तिस जो कने तिसदिया मौता पर जय पाणे दी सामर्था जो, कने तिस दे सौगी दुखां च साझी होणे दे मर्म जो जाणन, कने तिसदिया मौता दी समाणता जो हासल करन,","tāṁki maiṁ tisa jō kanē tisadiyā mautā para jaya pāṇē dī sāmarthā jō, kanē tisa dē saugī dukhāṁ ca sājhī hōṇē dē marma jō jāṇana, kanē tisadiyā mautā dī samāṇatā jō hāsala karana,",null],[3,11,"कि मैं कुसा भी रीतिया नैं मरेयां च जिंदे होणे दे पद तक पुज्जें ।","ki maiṁ kusā bhī rītiyā naiṁ marēyāṁ ca jiṁdē hōṇē dē pada taka pujjēṁ .",null],[3,12,"एह मतलब नी कि मैं पाई चुकेया ऐ, या सिद्ध होई चुकेया ऐ; अपर तिस पदार्थ जो पकड़णे तांई दौड़दा चली जांदा, जिस तांई मसीह यीशुयें मिन्जो पकड़ेया था,","ēha matalaba nī ki maiṁ pāī cukēyā ai, yā siddha hōī cukēyā ai; apara tisa padārtha jō pakaṛaṇē tāṁī dauṛadā calī jāṁdā, jisa tāṁī masīha yīśuyēṁ minjō pakaṛēyā thā,",null],[3,13,"हे भाऊओ, मेरी भावणां एह नी कि मैं पकड़ी चुकेया; अपर सिर्फ इक्क इक्क कम्म करदा कि जेह्ड़ियां गल्लां पचांह् रैई गैइआं हन तिन्हां जो भूली करी, गांह दियां गल्लां दे पास्से बधदा होया,","hē bhāūō, mērī bhāvaṇāṁ ēha nī ki maiṁ pakaṛī cukēyā; apara sirpha ikka ikka kamma karadā ki jēhṛiyāṁ gallāṁ pacāṁh raiī gaiiāṁ hana tinhāṁ jō bhūlī karī, gāṁha diyāṁ gallāṁ dē pāssē badhadā hōyā,",null],[3,14,"नशाने दे पास्से दौड़दा चली जांदा, तांकि सैह इनाम पां जिस तांई परमात्में मिन्जो मसीह यीशु च उपर सदेया ऐ ।","naśānē dē pāssē dauṛadā calī jāṁdā, tāṁki saiha ināma pāṁ jisa tāṁī paramātmēṁ minjō masīha yīśu ca upara sadēyā ai .",null],[3,15,"अहां च जितणे सिद्ध हन, ऐही वचार रखन, कने जे कुसा गल्ला च तुहां दे पास्सें ई वचार होयें तां परमात्में तिसियो भी तुहां पर प्रकट करी दिंगा ।","ahāṁ ca jitaṇē siddha hana, aihī vacāra rakhana, kanē jē kusā gallā ca tuhāṁ dē pāssēṁ ī vacāra hōyēṁ tāṁ paramātmēṁ tisiyō bhī tuhāṁ para prakaṭa karī diṁgā .",null],[3,16,"इसतांई जित्थू तिकर अहां पुज्जे हन, तिस दे मताबक चलन ।","isatāṁī jitthū tikara ahāṁ pujjē hana, tisa dē matābaka calana .",null],[3,17,"हे भाऊओ, तुहां सारे मिली नैं मेरे साइआं चाल चला, कने तिन्हां पैहचाण रखा जेह्ड़ा इसा रीतिया पर चलदे ऐ जिसदा उदारहण तुहां अहां च पांदे हन;","hē bhāūō, tuhāṁ sārē milī naiṁ mērē sāiāṁ cāla calā, kanē tinhāṁ paihacāṇa rakhā jēhṛā isā rītiyā para caladē ai jisadā udārahaṇa tuhāṁ ahāṁ ca pāṁdē hana;",null],[3,18,"क्जोकि मतिआं ऐदेईयां चालां चलदे हन, जिन्हां दी चर्चा मैं तुहां नैं बार बार कित्ती ऐ, कने अल्ली भी रोई रोई करी ग्लांदा कि सैह अपणी चाल चलण नैं मसीह दी सूलिया दे बैरी हन ।","kjōki matiāṁ aidēīyāṁ cālāṁ caladē hana, jinhāṁ dī carcā maiṁ tuhāṁ naiṁ bāra bāra kittī ai, kanē allī bhī rōī rōī karī glāṁdā ki saiha apaṇī cāla calaṇa naiṁ masīha dī sūliyā dē bairī hana .",null],[3,19,"तिन्हां दा अंत विणाश ऐ, तिन्हां दा ईश्वर पेट ऐ, सैह अपणी लज्जा दी गल्लां पर कमंड करदे हन, कने धरतिया दी चीज्जां पर मन लगाई रखदे हन ।","tinhāṁ dā aṁta viṇāśa ai, tinhāṁ dā īśvara pēṭa ai, saiha apaṇī lajjā dī gallāṁ para kamaṁḍa karadē hana, kanē dharatiyā dī cījjāṁ para mana lagāī rakhadē hana .",null],[3,20,"अपर अहां दा स्वदेश सुअर्गे पर ऐ; कने अहां इक्क उद्धारकर्ता प्रभु यीशु मसीह दे औत्थू ते ओणे दा इंतजार करदे हन ।","apara ahāṁ dā svadēśa suargē para ai; kanē ahāṁ ikka uddhārakartā prabhu yīśu masīha dē autthū tē ōṇē dā iṁtajāra karadē hana .",null],[3,21,"सैह अपणियां ताकता दे तिस प्रभावे दे मताबक जिसदिया बजाह ते सैह सारियां चीज्जां जो अपणे वशे च करी सकदा ऐ, अहां दे दीन हीन शरीरे दा रूप बदली नैं, अपणी महिमा दे शरीरे दे अनुकूल बणांंई दिंगा ।","saiha apaṇiyāṁ tākatā dē tisa prabhāvē dē matābaka jisadiyā bajāha tē saiha sāriyāṁ cījjāṁ jō apaṇē vaśē ca karī sakadā ai, ahāṁ dē dīna hīna śarīrē dā rūpa badalī naiṁ, apaṇī mahimā dē śarīrē dē anukūla baṇāṁṁī diṁgā .",null],[4,1,"इसतांई हे मेरे प्यारे भाऊओ, जिन्हां च मेरा जी लगेया रैंह्दा ऐ, जेह्ड़ी मेरी खुशी कने मुकुट होयें, हे प्यारे भाऊओ, प्रभु च इस तरांह पक्के रैह्आ ।","isatāṁī hē mērē pyārē bhāūō, jinhāṁ ca mērā jī lagēyā raiṁhdā ai, jēhṛī mērī khuśī kanē mukuṭa hōyēṁ, hē pyārē bhāūō, prabhu ca isa tarāṁha pakkē raihā .",null],[4,2,"मैं यूओदिया जो भी समझदा कने सुन्तुखे जो भी, कि सैह प्रभु च इक्क मन रैह्न ।","maiṁ yūōdiyā jō bhī samajhadā kanē suntukhē jō bhī, ki saiha prabhu ca ikka mana raihna .",null],[4,3,"हे सच्चे सेहकर्मी, मैं तिज्जो नैं भी विणती करदा कि तू तिन्हां जणांसां दी मदद कर, क्जोकि तिन्हां मिन्जो सौगी सुसमाचार फैल़ाणे च, क्लेमेंस कने मेरे होरनी सेहकर्मियां समेत मेहणत कित्ती, जिन्हां दे नां जिन्दगिया दी कताबां च लिख्यो हन ।","hē saccē sēhakarmī, maiṁ tijjō naiṁ bhī viṇatī karadā ki tū tinhāṁ jaṇāṁsāṁ dī madada kara, kjōki tinhāṁ minjō saugī susamācāra phail̈āṇē ca, klēmēṁsa kanē mērē hōranī sēhakarmiyāṁ samēta mēhaṇata kittī, jinhāṁ dē nāṁ jindagiyā dī katābāṁ ca likhyō hana .",null],[4,4,"प्रभु च सदा खुश रैह्आ; मैं भिरी ग्लांदा, खुश रैह्आ ।","prabhu ca sadā khuśa raihā; maiṁ bhirī glāṁdā, khuśa raihā .",null],[4,5,"तुहां दी कोमलता सारे माणुआं पर प्रकट होयें । प्रभु नैड़ें ऐ ।","tuhāṁ dī kōmalatā sārē māṇuāṁ para prakaṭa hōyēṁ . prabhu naiṛēṁ ai .",null],[4,6,"कुसा भी गल्ला दी चिंता मत करा; अपर हर इक्की गल्ला च तुहां दे निवेदण, प्रार्थना कने विणतिया दिया बजाह ते धन्यावाद सौगी परमात्में सामणे हाजर कित्ते जान ।","kusā bhī gallā dī ciṁtā mata karā; apara hara ikkī gallā ca tuhāṁ dē nivēdaṇa, prārthanā kanē viṇatiyā diyā bajāha tē dhanyāvāda saugī paramātmēṁ sāmaṇē hājara kittē jāna .",null],[4,7,"ताह्लू परमात्में दी शांति, जेह्ड़ी सारिया समझा ते परांह ऐ, तुहां दे दिलां कने वचारां जो मसीह यीशु च सुरक्षित रखगी ।","tāhlū paramātmēṁ dī śāṁti, jēhṛī sāriyā samajhā tē parāṁha ai, tuhāṁ dē dilāṁ kanē vacārāṁ jō masīha yīśu ca surakṣita rakhagī .",null],[4,8,"इसतांई हे भाऊओ, जेह्ड़ियां जेह्ड़ियां गल्लां सच हन, कने जेह्ड़ियां जेह्ड़ियां गल्लां आदरणीय हन, कने जेह्ड़ियां जेह्ड़ियां गल्लां ठीक हन, कने जेह्ड़ियां जेह्ड़ियां गल्लां पवित्र हन, कने जेह्ड़ियां जेह्ड़ियां गल्लां सुहावणियां हन, कने जेह्ड़ियां जेह्ड़ियां मनभावणियां हन, मतलब जेह्ड़ियां भी सद्गुण कने तरीफां दी गल्लां हन तिन्हां पर ध्यान लग्गा करा ।","isatāṁī hē bhāūō, jēhṛiyāṁ jēhṛiyāṁ gallāṁ saca hana, kanē jēhṛiyāṁ jēhṛiyāṁ gallāṁ ādaraṇīya hana, kanē jēhṛiyāṁ jēhṛiyāṁ gallāṁ ṭhīka hana, kanē jēhṛiyāṁ jēhṛiyāṁ gallāṁ pavitra hana, kanē jēhṛiyāṁ jēhṛiyāṁ gallāṁ suhāvaṇiyāṁ hana, kanē jēhṛiyāṁ jēhṛiyāṁ manabhāvaṇiyāṁ hana, matalaba jēhṛiyāṁ bhī sadguṇa kanē tarīphāṁ dī gallāṁ hana tinhāṁ para dhyāna laggā karā .",null],[4,9,"जेह्ड़ियां गल्लां तुहां मिन्जो ते सिखियां, कने स्वकार कित्तियां, कने सुणियां कने मिन्जो च दिखियां, तिन्हां ई दा पालन करा करा, ताह्लू परमात्में जेह्ड़ा शांति दा सोंता ऐ, तुहां सौगी रैंह्गा ।","jēhṛiyāṁ gallāṁ tuhāṁ minjō tē sikhiyāṁ, kanē svakāra kittiyāṁ, kanē suṇiyāṁ kanē minjō ca dikhiyāṁ, tinhāṁ ī dā pālana karā karā, tāhlū paramātmēṁ jēhṛā śāṁti dā sōṁtā ai, tuhāṁ saugī raiṁhgā .",null],[4,10,"मैं प्रभु च बड़ा खुश ऐ कि हुण इतणेयां दिनां दे बाद तुहां दी चिंता मेरे बारे च भिरी जागृत होई ऐ, पक्का तुहां जो शुरू च भी इस दा वचार था, अपर तुहां जो मौका ना मिलेया ।","maiṁ prabhu ca baṛā khuśa ai ki huṇa itaṇēyāṁ dināṁ dē bāda tuhāṁ dī ciṁtā mērē bārē ca bhirī jāgr̥ta hōī ai, pakkā tuhāṁ jō śurū ca bhī isa dā vacāra thā, apara tuhāṁ jō maukā nā milēyā .",null],[4,11,"एह नी कि मैं अपणियां कमियां दिया बजाह ते एह ग्लांदा ऐ; क्जोकि मैं एह सिखया ऐ कि जिसा हालता च मैं ऐ; तिसा च संतोष करें ।","ēha nī ki maiṁ apaṇiyāṁ kamiyāṁ diyā bajāha tē ēha glāṁdā ai; kjōki maiṁ ēha sikhayā ai ki jisā hālatā ca maiṁ ai; tisā ca saṁtōṣa karēṁ .",null],[4,12,"मैं दीन होणां भी जाणदा ऐ कने बढ़णां भी जाणदा ऐ; हर इक्क गल्ल कने सारी हालतां च मैं मगन होणां भूखा रैहणां, कने बढ़णा घटणां सिखेया ऐ ।","maiṁ dīna hōṇāṁ bhī jāṇadā ai kanē baṛhaṇāṁ bhī jāṇadā ai; hara ikka galla kanē sārī hālatāṁ ca maiṁ magana hōṇāṁ bhūkhā raihaṇāṁ, kanē baṛhaṇā ghaṭaṇāṁ sikhēyā ai .",null],[4,13,"जेह्ड़ा मिन्जो सामर्थ दिंदा ऐ तिस च मैं सारा कुच्छ करी सकदा ।","jēhṛā minjō sāmartha diṁdā ai tisa ca maiṁ sārā kuccha karī sakadā .",null],[4,14,"तमी तुहां नैं खरा कित्ता कि मेरे क्लेशे च मेरे साझी होये ।","tamī tuhāṁ naiṁ kharā kittā ki mērē klēśē ca mērē sājhī hōyē .",null],[4,15,"हे फिलिप्पियों, तुहां अप्पु भी जाणदे हन कि सुसमाचार प्रचार दे शुरू च जाह्लू मैं मकिदुनिया ते विदा होया, तुहां जो छड्डी होर कुसा मंडलियां नैं लैणे दैणे दे बारे च मेरी मदद नी कित्ती ।","hē philippiyōṁ, tuhāṁ appu bhī jāṇadē hana ki susamācāra pracāra dē śurū ca jāhlū maiṁ makiduniyā tē vidā hōyā, tuhāṁ jō chaḍḍī hōra kusā maṁḍaliyāṁ naiṁ laiṇē daiṇē dē bārē ca mērī madada nī kittī .",null],[4,16,"इस तरांह जाह्लू मैं थिस्सलुनीके च था, ताह्लू भी तुहां मेरी कमी पूरी करणे तांई इक्क बरी क्या अपर दो बरी कुच्छ घल्लया था ।","isa tarāṁha jāhlū maiṁ thissalunīkē ca thā, tāhlū bhī tuhāṁ mērī kamī pūrī karaṇē tāṁī ikka barī kyā apara dō barī kuccha ghallayā thā .",null],[4,17,"एह नी कि मैं दान चाहंदा अपर मैं ऐदेया फल चाहंदा जेह्ड़ा तुहां दे फायदे तांई बढ़दा जाये ।","ēha nī ki maiṁ dāna cāhaṁdā apara maiṁ aidēyā phala cāhaṁdā jēhṛā tuhāṁ dē phāyadē tāṁī baṛhadā jāyē .",null],[4,18,"मिन्जो अल्ल सब कुच्छ ऐ, अपर मता सारा ऐ; जेह्ड़ियां चीज्जां तुहां इपफ्रदीतुस दे हत्थे ते घल्लियां थियां तिन्हां जो पाई नैं मैं मगन होई गैआ, सैह तां सुखदायक मुश्क, स्वकार करणे जोग्गा बलिदान ऐ, जेह्ड़ा परमात्में जो भांदा ऐ ।","minjō alla saba kuccha ai, apara matā sārā ai; jēhṛiyāṁ cījjāṁ tuhāṁ ipaphradītusa dē hatthē tē ghalliyāṁ thiyāṁ tinhāṁ jō pāī naiṁ maiṁ magana hōī gaiā, saiha tāṁ sukhadāyaka muśka, svakāra karaṇē jōggā balidāna ai, jēhṛā paramātmēṁ jō bhāṁdā ai .",null],[4,19,"मेरा परमात्मां भी अपणे तिस धने दे मताबक जेह्ड़ा महिमा सौगी मसीह यीशु च ऐ, तुहां दी हर इक्क कमी पूरी करगा ।","mērā paramātmāṁ bhī apaṇē tisa dhanē dē matābaka jēhṛā mahimā saugī masīha yīśu ca ai, tuhāṁ dī hara ikka kamī pūrī karagā .",null],[4,20,"अहां दे परमात्में कने पिता दी महिमा जुगा जुग होंदी रैंह् । आमीन ।","ahāṁ dē paramātmēṁ kanē pitā dī mahimā jugā juga hōṁdī raiṁh . āmīna .",null],[4,21,"हर इक्क पवित्र जण जो, जेह्ड़ा यीशु मसीह च ऐ, नमस्कार ग्ला । जेह्ड़े भाऊ मिन्जो सौगी हन, तुहां जो नमस्कार ग्लांदे हन ।","hara ikka pavitra jaṇa jō, jēhṛā yīśu masīha ca ai, namaskāra glā . jēhṛē bhāū minjō saugī hana, tuhāṁ jō namaskāra glāṁdē hana .",null],[4,22,"सारे पवित्र लोक, खास करी नैं जेह्ड़े कैसरे दे परवारे दे हन, तुहां जो नमस्कार ग्लांदे हन ।","sārē pavitra lōka, khāsa karī naiṁ jēhṛē kaisarē dē paravārē dē hana, tuhāṁ jō namaskāra glāṁdē hana .",null],[4,23,"अहां दे प्रभु यीशु मसीह दा अनुग्रह तुहां दिया आत्मां सौगी रैंह् ।","ahāṁ dē prabhu yīśu masīha dā anugraha tuhāṁ diyā ātmāṁ saugī raiṁh .",null]],"kfs":[[1,1,"यीशु मसीह रे सेवक पौलुस कने तिमुथियुस रिया तरफा ते यीशु मसीह च फिलिप्पी रे रैहणे औल़े सारे पवित्र लोकां रे नौं सै जे तित्थी अध्यक्षां कने कलीसिया रे सेवकां सौगी रैयां ये:","yīśu masīha rē sēvaka paulusa kanē timuthiyusa riyā taraphā tē yīśu masīha ca philippī rē raihaṇē aul̈ē sārē pavitra lōkāṁ rē nauṁ sai jē titthī adhyakṣāṁ kanē kalīsiyā rē sēvakāṁ saugī raiyāṁ yē:",null],[1,2,"अहांरे पिता परमेशर कने अहांरे प्रभु यीशु मसीह रिया तरफा ते तुहांजो अनुग्रह कने शान्ति मिलो।","ahāṁrē pitā paramēśara kanē ahāṁrē prabhu yīśu masīha riyā taraphā tē tuhāṁjō anugraha kanē śānti milō.",null],[1,3,"हऊँ ताहली-ताहली जे तुहांजो याद करां, ताहली ताहली परमेशरा रा धन्यवाद करां।","haūm̐ tāhalī-tāhalī jē tuhāṁjō yāda karāṁ, tāhalī tāhalī paramēśarā rā dhanyavāda karāṁ.",null],[1,4,"अपणिया हर प्रार्थना च हऊँ हमेशा खुशिया ने तुहांरे खातर प्रार्थना करां।","apaṇiyā hara prārthanā ca haūm̐ hamēśā khuśiyā nē tuhāṁrē khātara prārthanā karāṁ.",null],[1,5,"कांभई पैहले ई दिना ते अज्जा तक तुहें खुशखबरिया रे प्रचारा च मेरा सहयोग देन्दे रैये।","kāṁbhaī paihalē ī dinā tē ajjā taka tuhēṁ khuśakhabariyā rē pracārā ca mērā sahayōga dēndē raiyē.",null],[1,6,"मिन्जो इसा गल्ला रा पूरा भरोसा भई सै परमेशर तिने जे तुहांरे बिच येढ़ा बधिया काम्म शुरु कित्या, सैई तिस्सो तिस दिना तक बणाई रखगा, ताहली जे मसीह यीशु फेरी भीं आईने तिस्सो पूरा करगा।","minjō isā gallā rā pūrā bharōsā bhaī sai paramēśara tinē jē tuhāṁrē bica yēṛhā badhiyā kāmma śuru kityā, saiī tissō tisa dinā taka baṇāī rakhagā, tāhalī jē masīha yīśu phērī bhīṁ āīnē tissō pūrā karagā.",null],[1,7,"तुहां सारयां रे बारे च मेरा ये सोचणा ठीक इ हाया, कांभई तुहें सारे मेरे मना च बसीरे, कने न सिर्फ तिस वगत ताहली जे हऊँ जेल्ला च ओ, बल्कि तिस वगत बी ताहली जे हऊँ खुशखबरिया रिया सच्चाईया री हिफाज़त करदे हुये, तिस रिया प्रतिष्ठा च लगीरा था, तुहें सारे इस खास अधिकारा च मेरे सौगी अनुग्रह च भागीदार रैये।","tuhāṁ sārayāṁ rē bārē ca mērā yē sōcaṇā ṭhīka i hāyā, kāṁbhaī tuhēṁ sārē mērē manā ca basīrē, kanē na sirpha tisa vagata tāhalī jē haūm̐ jēllā ca ō, balki tisa vagata bī tāhalī jē haūm̐ khuśakhabariyā riyā saccāīyā rī hiphāzata karadē huyē, tisa riyā pratiṣṭhā ca lagīrā thā, tuhēṁ sārē isa khāsa adhikārā ca mērē saugī anugraha ca bhāgīdāra raiyē.",null],[1,8,"इस च परमेशर मेरा गवाह भई हऊँ मसीह यीशुये साई प्रेम-भौआ ने तुहां सारयां रे खातर व्याकुल रेआं।","isa ca paramēśara mērā gavāha bhaī haūm̐ masīha yīśuyē sāī prēma-bhauā nē tuhāṁ sārayāṁ rē khātara vyākula rēāṁ.",null],[1,9,"हऊँ येई प्रार्थना करदा रैयां भई तुहांरा प्यार, कने सुध-बुध हर तरह रे ज्ञाना सौगी हमेशा बधदी रौ।","haūm̐ yēī prārthanā karadā raiyāṁ bhaī tuhāṁrā pyāra, kanē sudha-budha hara taraha rē jñānā saugī hamēśā badhadī rau.",null],[1,10,"एथी तक भई तुहें उत्तम ते उत्तम गल्लां जो प्रिय जाणीने, कने मसीह रे दिना तक सच्चे बणीने रौआ, कने ठोकर नीं खावा;","ēthī taka bhaī tuhēṁ uttama tē uttama gallāṁ jō priya jāṇīnē, kanē masīha rē dinā taka saccē baṇīnē rauā, kanē ṭhōkara nīṁ khāvā;",null],[1,11,"यीशु मसीह री करुणा जो पाईने तुहें अति उत्तम काम्म करा, कने तिसच बधदे रौआ तिसते जे परमेशरा री महिमा कने स्तुती होन्दी रौ।","yīśu masīha rī karuṇā jō pāīnē tuhēṁ ati uttama kāmma karā, kanē tisaca badhadē rauā tisatē jē paramēśarā rī mahimā kanē stutī hōndī rau.",null],[1,12,"हे भाईयो, हऊँ चाँह भई तुहें ये जाणी लो भई माह पर सै जे बीती, तिसते खुश-खबरी कई गुणा फैलदी गई।","hē bhāīyō, haūm̐ cām̐ha bhaī tuhēṁ yē jāṇī lō bhaī māha para sai jē bītī, tisatē khuśa-khabarī kaī guṇā phailadī gaī.",null],[1,13,"येत्थी तक भई कैसरा रे राजमैहला री सारी पलटन कने बाकि सारे लोकां च ये परगट हुईया भई हऊँ मसीह रे कारण ई बन्दी बणाया गया;","yētthī taka bhaī kaisarā rē rājamaihalā rī sārī palaṭana kanē bāki sārē lōkāṁ ca yē paragaṭa huīyā bhaī haūm̐ masīha rē kāraṇa ī bandī baṇāyā gayā;",null],[1,14,"कने प्रभु च सै जे भाई ये, तिन्हां चते जादातर भाईयां जो मेरे कैद हुणे रिया वजह ने बड़ा जोश आया, कने जादा ते जादा जोशा ने परमेशरा रा वचन निधड़क हुईने सुणाई रां ये।","kanē prabhu ca sai jē bhāī yē, tinhāṁ catē jādātara bhāīyāṁ jō mērē kaida huṇē riyā vajaha nē baṛā jōśa āyā, kanē jādā tē jādā jōśā nē paramēśarā rā vacana nidhaṛaka huīnē suṇāī rāṁ yē.",null],[1,15,"ये सच्च आ भई तिन्हां चते कुछ हिरख कने बैर-बरोधा रे कारण मसीह रा प्रचार करां ये कने कई लोक अच्छी भावना ते प्रेरित हुईने मसीह रा प्रचार करां ये।","yē sacca ā bhaī tinhāṁ catē kucha hirakha kanē baira-barōdhā rē kāraṇa masīha rā pracāra karāṁ yē kanē kaī lōka acchī bhāvanā tē prērita huīnē masīha rā pracāra karāṁ yē.",null],[1,16,"ये लोक प्यारा रे कारण येढ़ा करां ये कांभई ये जाणां ये भई परमेशरे खुश खबरिया रा बचाव करने रे खातर ई मिन्जो इत्थी रखीरा।","yē lōka pyārā rē kāraṇa yēṛhā karāṁ yē kāṁbhaī yē jāṇāṁ yē bhaī paramēśarē khuśa khabariyā rā bacāva karanē rē khātara ī minjō itthī rakhīrā.",null],[1,17,"पर कुछ होर लोक त सच्चाईया ने नीं, बल्कि स्वार्था ने भरीरी इच्छां ते मसीह रा प्रचार करां ये कांभई ये सोच्चां ये भई इसते सै जेला च मेरे खातर दुख पैदा करी सक्कां ये।","para kucha hōra lōka ta saccāīyā nē nīṁ, balki svārthā nē bharīrī icchāṁ tē masīha rā pracāra karāṁ yē kāṁbhaī yē sōccāṁ yē bhaī isatē sai jēlā ca mērē khātara dukha paidā karī sakkāṁ yē.",null],[1,18,"पर इसते कोई फर्क नीं पौन्दा, जरुरी त ये आ भई इक्की ढंगा ने या दूज्जे ढंगा ने, चाहे बुरा मकशद हो, चाहे भला प्रचार त मसीह रा ई हुआं कने इसते मिन्जो खुशी मिलां ई कने खुशी मिलदी ई रैहणी।","para isatē kōī pharka nīṁ paundā, jarurī ta yē ā bhaī ikkī ḍhaṁgā nē yā dūjjē ḍhaṁgā nē, cāhē burā makaśada hō, cāhē bhalā pracāra ta masīha rā ī huāṁ kanē isatē minjō khuśī milāṁ ī kanē khuśī miladī ī raihaṇī.",null],[1,19,"कांभई हऊँ जाणां भई तुहां रियां प्रार्थनां रे जरिये कने तिसा सहायता ते, सै जे यीशु मसीह रिया आत्मा रे दाना ते मिलां ई, इसरा फल़ मेरा उद्धार हुणा।","kāṁbhaī haūm̐ jāṇāṁ bhaī tuhāṁ riyāṁ prārthanāṁ rē jariyē kanē tisā sahāyatā tē, sai jē yīśu masīha riyā ātmā rē dānā tē milāṁ ī, isarā phal̈a mērā uddhāra huṇā.",null],[1,20,"मेरी ये बड्डी इच्छा कने आस येई हाई कने मिन्जो इसरा विश्वास आ भई मांह किसी बी गल्ला ते निराश नीं हुणा बल्कि पूरे हौसले ने तियां जे मेरे शरीरा ते मसीह री महिमा हमेशा हुन्दी रैई, तियां ई अग्गे बी हुन्दी रैहणी; चाहे हऊँ जीऊं या मरी जाऊं।","mērī yē baḍḍī icchā kanē āsa yēī hāī kanē minjō isarā viśvāsa ā bhaī māṁha kisī bī gallā tē nirāśa nīṁ huṇā balki pūrē hausalē nē tiyāṁ jē mērē śarīrā tē masīha rī mahimā hamēśā hundī raiī, tiyāṁ ī aggē bī hundī raihaṇī; cāhē haūm̐ jīūṁ yā marī jāūṁ.",null],[1,21,"कांभई मेरे खातर जिन्दा रैहणा मसीह आ, कने मरने रा मतलब लाभ आ।","kāṁbhaī mērē khātara jindā raihaṇā masīha ā, kanē maranē rā matalaba lābha ā.",null],[1,22,"पर जे हऊँ अपणे इस शरीरा तेई जिन्दा रऊँ, तां इसरा मतलब ये हुणा भई हऊँ अपणे कर्मा रे फल़ा रा मजा लेऊं; तां हऊँ नीं जाणदा भई किसजो चुणुं।","para jē haūm̐ apaṇē isa śarīrā tēī jindā raūm̐, tāṁ isarā matalaba yē huṇā bhaī haūm̐ apaṇē karmā rē phal̈ā rā majā lēūṁ; tāṁ haūm̐ nīṁ jāṇadā bhaī kisajō cuṇuṁ.",null],[1,23,"कांभई मिन्जो दूईं रे बिच चुनाव करने च कठिनाई हुई करां ई। हऊँ अपणिया जिन्दगिया ते विदा हुईने मसीह ले जाणा चाँह, कांभई सै बहुत ई अच्छा हुणा।","kāṁbhaī minjō dūīṁ rē bica cunāva karanē ca kaṭhināī huī karāṁ ī. haūm̐ apaṇiyā jindagiyā tē vidā huīnē masīha lē jāṇā cām̐ha, kāṁbhaī sai bahuta ī acchā huṇā.",null],[1,24,"पर शरीरा सौगी मेरा इत्थी रैहणा तुहांरे खातर होर बी जरुरी आ।","para śarīrā saugī mērā itthī raihaṇā tuhāṁrē khātara hōra bī jarurī ā.",null],[1,25,"इस खातर भई मिन्जो इसरा भरोसा हाया भई मांह इत्थी रैहणा कने तुहां सारयां री आत्मिक उन्नति कने विश्वासा ते पैदा हुणे औलिया खुशिया रे खातर तुहांने सौगी रैहन्दे ई रैहणा;","isa khātara bhaī minjō isarā bharōsā hāyā bhaī māṁha itthī raihaṇā kanē tuhāṁ sārayāṁ rī ātmika unnati kanē viśvāsā tē paidā huṇē auliyā khuśiyā rē khātara tuhāṁnē saugī raihandē ī raihaṇā;",null],[1,26,"कने सै जे गर्व तुहें मेरे बारे च करां ये, सै मेरे भीं तुहांले औणे ते मसीह यीशुये ते होर जादा बधी जाओ।","kanē sai jē garva tuhēṁ mērē bārē ca karāṁ yē, sai mērē bhīṁ tuhāṁlē auṇē tē masīha yīśuyē tē hōra jādā badhī jāō.",null],[1,27,"सिर्फ इतणा करा भई तुहांरा चाल-चलन मसीह रिया खुशखबरिया रे लायक हो भई चाहे हऊँ तुहांजो आईने देखूँ, चाहे तुहांते दूर रऊँ, तुहांरे बारे च येई सुणुं भई तुहें इक्की आत्मा च मजबूतिया ने टिक्कीरे, कने इक मन हुईने खुशखबरिया ते पैदा हुईरे विश्वासा रे खातर इक जुट रैईने मेहणत करी करां ये,","sirpha itaṇā karā bhaī tuhāṁrā cāla-calana masīha riyā khuśakhabariyā rē lāyaka hō bhaī cāhē haūm̐ tuhāṁjō āīnē dēkhūm̐, cāhē tuhāṁtē dūra raūm̐, tuhāṁrē bārē ca yēī suṇuṁ bhaī tuhēṁ ikkī ātmā ca majabūtiyā nē ṭikkīrē, kanē ika mana huīnē khuśakhabariyā tē paidā huīrē viśvāsā rē khātara ika juṭa raiīnē mēhaṇata karī karāṁ yē,",null],[1,28,"कने हऊँ ये बी सुणना चाँह भई तुहें अपणे दुश्मणां ते कियां बी नीं डरदे, तुहांरा ये हौंसला तिन्हांरे खातमे रा सबूत आ, कने येई सबूत आ तुहां रिया मुक्तिया रा कने परमेशरा रिया तरफा ते येढ़ा ई कित्या जाणा।","kanē haūm̐ yē bī suṇanā cām̐ha bhaī tuhēṁ apaṇē duśmaṇāṁ tē kiyāṁ bī nīṁ ḍaradē, tuhāṁrā yē hauṁsalā tinhāṁrē khātamē rā sabūta ā, kanē yēī sabūta ā tuhāṁ riyā muktiyā rā kanē paramēśarā riyā taraphā tē yēṛhā ī kityā jāṇā.",null],[1,29,"कांभई मसीह रिया तरफा ते तुहांजो न सिर्फ विश्वास करने रा पर तिसरे खातर मुसीबतां झेलणे रा बी खास अधिकार दित्तिरा;","kāṁbhaī masīha riyā taraphā tē tuhāṁjō na sirpha viśvāsa karanē rā para tisarē khātara musībatāṁ jhēlaṇē rā bī khāsa adhikāra dittirā;",null],[1,30,"तुहें जाणां ये भई तुसें तिसा ई मेहणता च जुटीरे तिसा च जे हऊँ जुटीरा था, तियां जे भई तुहें सुणां ये अज्जा तक हऊँ तिसच ई लगीरा।","tuhēṁ jāṇāṁ yē bhaī tusēṁ tisā ī mēhaṇatā ca juṭīrē tisā ca jē haūm̐ juṭīrā thā, tiyāṁ jē bhaī tuhēṁ suṇāṁ yē ajjā taka haūm̐ tisaca ī lagīrā.",null],[2,1,"फेरी तुहां लोकां जो जे मसीह च कोई उत्साह, कने प्यारा ते पैदा हुईरी कोई शान्ति हाई, जे आत्मा च कोई भागीदारी कने स्नेह री कोई भावना कने सहानुभूति हाई,","phērī tuhāṁ lōkāṁ jō jē masīha ca kōī utsāha, kanē pyārā tē paidā huīrī kōī śānti hāī, jē ātmā ca kōī bhāgīdārī kanē snēha rī kōī bhāvanā kanē sahānubhūti hāī,",null],[2,2,"तां मेरी ये खुशी पूरी करा भई इक मन रौआ, इक जेआ प्यार करा, आत्मा च एका रखा, कने इक जेआ ई लक्ष्य रखा।","tāṁ mērī yē khuśī pūrī karā bhaī ika mana rauā, ika jēā pyāra karā, ātmā ca ēkā rakhā, kanē ika jēā ī lakṣya rakhā.",null],[2,3,"हिरख कने घमण्डा ने कुछ बी मता करदे, बल्कि नम्र बणा कने दूज्जयां जो अप्पूँ ते खरा समझा।","hirakha kanē ghamaṇḍā nē kucha bī matā karadē, balki namra baṇā kanē dūjjayāṁ jō appūm̐ tē kharā samajhā.",null],[2,4,"तुहां चते हर इक्की जो चाहिये भई सिर्फ अपणा ई नीं, बल्कि दूज्जेयां रे हितां रा बी ध्यान रखो।","tuhāṁ catē hara ikkī jō cāhiyē bhaī sirpha apaṇā ī nīṁ, balki dūjjēyāṁ rē hitāṁ rā bī dhyāna rakhō.",null],[2,5,"तेढ़ा जे यीशु मसीह रा स्वाभाव था तुहांरा स्वाभाव बी तेढ़ा ई होणा चाहिन्दा;","tēṛhā jē yīśu masīha rā svābhāva thā tuhāṁrā svābhāva bī tēṛhā ī hōṇā cāhindā;",null],[2,6,"सै जे अपणे रुपा च साक्षात परमेशर था, पर तिने परमेशरा रे बराबर होणे जो अपणे बशा च रखणे री कोई चीज नीं समझया।","sai jē apaṇē rupā ca sākṣāta paramēśara thā, para tinē paramēśarā rē barābara hōṇē jō apaṇē baśā ca rakhaṇē rī kōī cīja nīṁ samajhayā.",null],[2,7,"बल्कि तिने त अपणा सब कुछ त्याग करीने इक सेवका रा रुप ग्रहण करील्या कने माह्णुआं रे बराबर बणिया, कने ताहली जे सै अपणे बाहरले रुपा च माह्णुआं साई बणिया।","balki tinē ta apaṇā saba kucha tyāga karīnē ika sēvakā rā rupa grahaṇa karīlyā kanē māhṇuāṁ rē barābara baṇiyā, kanē tāhalī jē sai apaṇē bāharalē rupā ca māhṇuāṁ sāī baṇiyā.",null],[2,8,"तां तिने अप्पूँ जो दीन करील्या कने इतणा आज्ञाकारी बणिया भई अपणे प्राण तक देईते कने क्रूसा री मौत बी सैई ली।","tāṁ tinē appūm̐ jō dīna karīlyā kanē itaṇā ājñākārī baṇiyā bhaī apaṇē prāṇa taka dēītē kanē krūsā rī mauta bī saiī lī.",null],[2,9,"इस खातर परमेशरे बी तिस्सो उच्चिया ते उच्चिया जगह पर बठाऴया कने तिस्सो सै नौं दित्या सै जे सारे नौंवां ते ऊपर आ।","isa khātara paramēśarē bī tissō ucciyā tē ucciyā jagaha para baṭhāḻayā kanē tissō sai nauṁ dityā sai jē sārē nauṁvāṁ tē ūpara ā.",null],[2,10,"ताकि सब कोई ताहली जे यीशुये रे नौंवा जो लेन्दे हुये सुणो, तां सै घुटने रे भार झुक्की जाओ, चाहे सै स्वर्गा रे हो, चाहे जमीना परा रे हो, चाहे जमीना रे थल्ले रे हो।","tāki saba kōī tāhalī jē yīśuyē rē nauṁvā jō lēndē huyē suṇō, tāṁ sai ghuṭanē rē bhāra jhukkī jāō, cāhē sai svargā rē hō, cāhē jamīnā parā rē hō, cāhē jamīnā rē thallē rē hō.",null],[2,11,"कने हर इक जीभ पिता परेशरा री महिमा रे खातर स्वीकार करे भई यीशु मसीह ई प्रभु आ।”","kanē hara ika jībha pitā parēśarā rī mahimā rē khātara svīkāra karē bhaī yīśu masīha ī prabhu ā.”",null],[2,12,"इस खातर मेरे प्यारयो, तुहें मेरे हुक्मां रा तियां जे तिस वगत पालन करी करां थे ताहली जे हऊँ तुहां कने था, हुण ताहली जे भई हऊँ तुहां कने नीं आ तां तुहें होर जादा लगना ने तिन्हांरा पालन करा। परमेशरा रे प्रति सारे आदर भावा ने अपणे उद्धारा जो पूरा करने रे खातर तुहें लोक काम्म करदे जावा।","isa khātara mērē pyārayō, tuhēṁ mērē hukmāṁ rā tiyāṁ jē tisa vagata pālana karī karāṁ thē tāhalī jē haūm̐ tuhāṁ kanē thā, huṇa tāhalī jē bhaī haūm̐ tuhāṁ kanē nīṁ ā tāṁ tuhēṁ hōra jādā laganā nē tinhāṁrā pālana karā. paramēśarā rē prati sārē ādara bhāvā nē apaṇē uddhārā jō pūrā karanē rē khātara tuhēṁ lōka kāmma karadē jāvā.",null],[2,13,"कांभई सै परमेशर ई हाया सै जे तिन्हां कम्मां री इच्छा कने तिन्हांजो पूरा करने रा काम्म, सै जे परमेशरा जो खरे लगां ये, तुहांच पैदा करां।","kāṁbhaī sai paramēśara ī hāyā sai jē tinhāṁ kammāṁ rī icchā kanē tinhāṁjō pūrā karanē rā kāmma, sai jē paramēśarā jō kharē lagāṁ yē, tuhāṁca paidā karāṁ.",null],[2,14,"बिणा कोई शकैत या लड़ाई झगड़ा कित्ते सारे काम्म करदे रौआ।","biṇā kōī śakaita yā laṛāī jhagaṛā kittē sārē kāmma karadē rauā.",null],[2,15,"ताकि तुहें भोले-भाले कने पवित्र बणी जाओ, कने इस टेडे-मेडे कने अड़ियल लोकां रे बिच परमेशरा रे निर्दोष पुत्र बणी जावा, तिन्हांरे बिच तुहें जिन्दगिया रा वचन लेईने संसारा च बऴदे दीपकां साई दिस्सया करां ये*","tāki tuhēṁ bhōlē-bhālē kanē pavitra baṇī jāō, kanē isa ṭēḍē-mēḍē kanē aṛiyala lōkāṁ rē bica paramēśarā rē nirdōṣa putra baṇī jāvā, tinhāṁrē bica tuhēṁ jindagiyā rā vacana lēīnē saṁsārā ca baḻadē dīpakāṁ sāī dissayā karāṁ yē*",null],[2,16,"भई ताहली जे तुहें तिन्हांजो जिन्दगी देणे औऴी खुशखबरी सुणवा यें, तां तुहें येढ़ा ई करदे रौआ ताकि मसीह रे फेरी भीं ते वापिस औणे रे दिन, हऊँ ये देखीने भई मेरिया जिन्दगिया री दौड़-धूप बेकार नीं गई, तुहां पर गर्व करी सक्कूँ।","bhaī tāhalī jē tuhēṁ tinhāṁjō jindagī dēṇē auḻī khuśakhabarī suṇavā yēṁ, tāṁ tuhēṁ yēṛhā ī karadē rauā tāki masīha rē phērī bhīṁ tē vāpisa auṇē rē dina, haūm̐ yē dēkhīnē bhaī mēriyā jindagiyā rī dauṛa-dhūpa bēkāra nīṁ gaī, tuhāṁ para garva karī sakkūm̐.",null],[2,17,"जे मिन्जो तुहांरे विश्वास रुपी बलिदाना कने सेवा सौगी अपणा खून बी बहाणे पौ तां बी मिन्जो खुशी हुणी, कने तुहां सब्बीं सौगी मौज करां।","jē minjō tuhāṁrē viśvāsa rupī balidānā kanē sēvā saugī apaṇā khūna bī bahāṇē pau tāṁ bī minjō khuśī huṇī, kanē tuhāṁ sabbīṁ saugī mauja karāṁ.",null],[2,18,"इयां ई तुहें बी खुश रौआ कने मेरे सौगी मौज करा।","iyāṁ ī tuhēṁ bī khuśa rauā kanē mērē saugī mauja karā.",null],[2,19,"प्रभु यीशुये रिया सहायता ने मिन्जो तीमुथियुस जो तुहांले जल्द भेजणे री इच्छा ई ताकि तुहांरेआं समाचारां ते मेरा हौंसला बी दुगणा हुई जाओ।","prabhu yīśuyē riyā sahāyatā nē minjō tīmuthiyusa jō tuhāṁlē jalda bhējaṇē rī icchā ī tāki tuhāṁrēāṁ samācārāṁ tē mērā hauṁsalā bī dugaṇā huī jāō.",null],[2,20,"कांभई कोई दूज्जा येढ़ा आदमी नीं आ तिसरी भावनां जे मेरे साई हो कने सै जे तुहांरे कल्याण रे खातर सच्चे मना ने चिन्ता करदा हो।","kāṁbhaī kōī dūjjā yēṛhā ādamī nīṁ ā tisarī bhāvanāṁ jē mērē sāī hō kanē sai jē tuhāṁrē kalyāṇa rē khātara saccē manā nē cintā karadā hō.",null],[2,21,"कांभई होर सारे अपणे-अपणे कम्मां च लगीरे, यीशु मसीह रे कम्मां च कोई नीं लगीरा।","kāṁbhaī hōra sārē apaṇē-apaṇē kammāṁ ca lagīrē, yīśu masīha rē kammāṁ ca kōī nīṁ lagīrā.",null],[2,22,"तुहें तिसरे चरित्रा जो जाणां ये भई खुश खबरिया रे प्रचारा च मेरे सौगी तिने तियां ई सेवा कित्तिरी, तियां जे इक वेटा अपणे पिते सौगी करां।","tuhēṁ tisarē caritrā jō jāṇāṁ yē bhaī khuśa khabariyā rē pracārā ca mērē saugī tinē tiyāṁ ī sēvā kittirī, tiyāṁ jē ika vēṭā apaṇē pitē saugī karāṁ.",null],[2,23,"इस खातर तियां जे ये पता चलगा भई मेरने क्या कुछ हुई करां, हऊँ तिस्सो तुहांले भेज्जी देणे री उम्मीद रखां।","isa khātara tiyāṁ jē yē patā calagā bhaī mēranē kyā kucha huī karāṁ, haūm̐ tissō tuhāṁlē bhējjī dēṇē rī ummīda rakhāṁ.",null],[2,24,"कने मेरा विश्वास आ भई प्रभुये रिया सहायता ने मांह बी छोड़चा ने औणा।","kanē mērā viśvāsa ā bhaī prabhuyē riyā sahāyatā nē māṁha bī chōṛacā nē auṇā.",null],[2,25,"हऊँ ये जरुरी समझां भई इपफ्रदीतुस जो तुहांले भेज्जूँ सै जे मेरे भाईये सौगी काम्म करने औऴा, कने साथ देणे औऴा बीर आ, कने मिन्‍जो जरुरत पौणे पर मेरी सहायता करने रे खातर तुहांरा दूत आ।","haūm̐ yē jarurī samajhāṁ bhaī ipaphradītusa jō tuhāṁlē bhējjūm̐ sai jē mērē bhāīyē saugī kāmma karanē auḻā, kanē sātha dēṇē auḻā bīra ā, kanē minjō jarurata pauṇē para mērī sahāyatā karanē rē khātara tuhāṁrā dūta ā.",null],[2,26,"कांभई तिसरा मन तुहां सब्बीं च लगीरा था, इस कारण सै ब्याकुल रैयां था, कांभई तुहें तिस रिया बिमारिया रा हाल सुणया था।","kāṁbhaī tisarā mana tuhāṁ sabbīṁ ca lagīrā thā, isa kāraṇa sai byākula raiyāṁ thā, kāṁbhaī tuhēṁ tisa riyā bimāriyā rā hāla suṇayā thā.",null],[2,27,"हाँ, सै बीमार त था, कने सै बी इतणा भई तियां जे मरने ई औऴा था, पर परमेशरे तिस पर अनुग्रह कित्या न सिर्फ तिस पर बल्कि माह पर बी ताकि मिन्जो दुखा पर दुख नीं मिलो।","hām̐, sai bīmāra ta thā, kanē sai bī itaṇā bhaī tiyāṁ jē maranē ī auḻā thā, para paramēśarē tisa para anugraha kityā na sirpha tisa para balki māha para bī tāki minjō dukhā para dukha nīṁ milō.",null],[2,28,"इस खातर मैं तिस्सो भेज्जणे री होर बी जादा कोशत कित्ति भई ताहली जे तुहें तिसजो देक्खो तां इक बार भीं खुश हुई जाओ कने मेरा दुख घटि जाओ।","isa khātara maiṁ tissō bhējjaṇē rī hōra bī jādā kōśata kitti bhaī tāhalī jē tuhēṁ tisajō dēkkhō tāṁ ika bāra bhīṁ khuśa huī jāō kanē mērā dukha ghaṭi jāō.",null],[2,29,"इस खातर तुहें प्रभु च तिसरा बड़िया खुशिया ने स्वागत करा कने येढ़े लोकां रा बड़ा आदर करदे रौआ।","isa khātara tuhēṁ prabhu ca tisarā baṛiyā khuśiyā nē svāgata karā kanē yēṛhē lōkāṁ rā baṛā ādara karadē rauā.",null],[2,30,"कांभई मसीह रे कम्मां खातर सै तकरीबन मरीगरा था ताकि तुहांरे जरिये कित्ति रिया मेरिया सेवा च सै कमी जे रैई गरी थी, तिस्सो सै पूरा करी दो, इसरे खातर तिने अपणे प्राणां री बाजी लगाईती।","kāṁbhaī masīha rē kammāṁ khātara sai takarībana marīgarā thā tāki tuhāṁrē jariyē kitti riyā mēriyā sēvā ca sai kamī jē raiī garī thī, tissō sai pūrā karī dō, isarē khātara tinē apaṇē prāṇāṁ rī bājī lagāītī.",null],[3,1,"इस खातर मेरे भाईयो, प्रभु च मौज मनान्दे रौआ। तुहांजो भीं बार-बार तिन्हां ई गल्लां जो लिखदे रैहणे ते मिन्जो कोई दुख नीं हुन्दा कने तुहांरे खातर त ये सुरक्षित ई हाया।","isa khātara mērē bhāīyō, prabhu ca mauja manāndē rauā. tuhāṁjō bhīṁ bāra-bāra tinhāṁ ī gallāṁ jō likhadē raihaṇē tē minjō kōī dukha nīṁ hundā kanē tuhāṁrē khātara ta yē surakṣita ī hāyā.",null],[3,2,"इन्हां कुत्तयां ते साबधान रौआ, सै जे बुरयां कम्मां च लगीरे रैं। तिन्हां बुरयां कम्मां जो करने औल़यां ते साबधान रौआ।","inhāṁ kuttayāṁ tē sābadhāna rauā, sai jē burayāṁ kammāṁ ca lagīrē raiṁ. tinhāṁ burayāṁ kammāṁ jō karanē aul̈ayāṁ tē sābadhāna rauā.",null],[3,3,"कांभई सच्चे खतने औऴे माह्णु त अहें सै जे अपणी उपासना जो परमेशरा रिया आत्मा रे जरिये अर्पित करां ये, कने मसीह यीशुये पर गर्व करां ये, कने शरीरा पर भरोसा नीं रखदे।","kāṁbhaī saccē khatanē auḻē māhṇu ta ahēṁ sai jē apaṇī upāsanā jō paramēśarā riyā ātmā rē jariyē arpita karāṁ yē, kanē masīha yīśuyē para garva karāṁ yē, kanē śarīrā para bharōsā nīṁ rakhadē.",null],[3,4,"पर हऊँ त शरीरा पर बी भरोसा करी सक्कां। पर जे कोई होर इयां सोच्चे तां हऊँ तिसते बी बधीने रक्खी सक्कां।","para haūm̐ ta śarīrā para bī bharōsā karī sakkāṁ. para jē kōī hōra iyāṁ sōccē tāṁ haūm̐ tisatē bī badhīnē rakkhī sakkāṁ.",null],[3,5,"ताहली जे हऊँ अट्ठां दिनां रा था, मेरा खतना करीत्या था। हऊँ इस्राएली आ, हऊँ बैंजमिन रे गोता रा; हऊँ इब्रानी माता-पिता ते पैदा हुईरा इक इब्रानी आ; तित्थी तक जे व्यवस्था रे विधाना तक मेरी पहुँचा रा स्वाल आ, हऊँ इक फरीसी आ।","tāhalī jē haūm̐ aṭṭhāṁ dināṁ rā thā, mērā khatanā karītyā thā. haūm̐ isrāēlī ā, haūm̐ baiṁjamina rē gōtā rā; haūm̐ ibrānī mātā-pitā tē paidā huīrā ika ibrānī ā; titthī taka jē vyavasthā rē vidhānā taka mērī pahum̐cā rā svāla ā, haūm̐ ika pharīsī ā.",null],[3,6,"तित्थी तक जे मेरिया निष्ठा रा स्वाल आ, हऊँ कलीसिया जो बड़ा सताणे औऴा था, तित्थी तक जे धार्मिकता रा स्वाल आ, तिस्सो जे व्यवस्था रा विधान सखां, हऊँ निर्दोष था।","titthī taka jē mēriyā niṣṭhā rā svāla ā, haūm̐ kalīsiyā jō baṛā satāṇē auḻā thā, titthī taka jē dhārmikatā rā svāla ā, tissō jē vyavasthā rā vidhāna sakhāṁ, haūm̐ nirdōṣa thā.",null],[3,7,"पर ताहली सै जे मेरा फायदा था, आज्ज तिसजो ई मसीह रे खातर हऊँ अपणा नुक्सान समझां था।","para tāhalī sai jē mērā phāyadā thā, ājja tisajō ī masīha rē khātara haūm̐ apaṇā nuksāna samajhāṁ thā.",null],[3,8,"इसते बी बड्डी गल्ल येई भई हऊँ अपणे प्रभु यीशुये रे ज्ञाना री श्रेष्ठता रे कारण आज्ज तक सबी किछी जो कूड़ा समझां था। तिसरे ई खातर मैं सबी किजिरा त्याग करीत्या, कने हऊँ सबी किजि जो नफरता री चीजां समझणे लगया ताकि मसीह जो पाई सक्कूँ।","isatē bī baḍḍī galla yēī bhaī haūm̐ apaṇē prabhu yīśuyē rē jñānā rī śrēṣṭhatā rē kāraṇa ājja taka sabī kichī jō kūṛā samajhāṁ thā. tisarē ī khātara maiṁ sabī kijirā tyāga karītyā, kanē haūm̐ sabī kiji jō napharatā rī cījāṁ samajhaṇē lagayā tāki masīha jō pāī sakkūm̐.",null],[3,9,"कने तिसच पाया जाई सक्कूँ; मेरिया तिसा धार्मिकता रे कारण नीं सै जे व्यवस्था रे विधाना पर टिक्कीरी थी, बल्कि तिसा धार्मिकता रे कारण सै जे मसीह च विश्वास रे कारण ई, कने परमेशरा रिया तरफा ते विश्वास करने पर मिलां ई;","kanē tisaca pāyā jāī sakkūm̐; mēriyā tisā dhārmikatā rē kāraṇa nīṁ sai jē vyavasthā rē vidhānā para ṭikkīrī thī, balki tisā dhārmikatā rē kāraṇa sai jē masīha ca viśvāsa rē kāraṇa ī, kanē paramēśarā riyā taraphā tē viśvāsa karanē para milāṁ ī;",null],[3,10,"हऊँ मसीह जो जाणना चाँह कने तिसा शक्तिया रा अनुभव करना चाँह तिसते जे सै मरने ते बाद दोबारा जिन्दा होणा हुया था। हऊँ तिसरे दुक्खां रा बी हिस्सेदार होणा चाँह, कने तिस ई रुपा जो पाणा चाँह तिस्सो जे तिने अपणिया मौती रे जरिये पाया था।","haūm̐ masīha jō jāṇanā cām̐ha kanē tisā śaktiyā rā anubhava karanā cām̐ha tisatē jē sai maranē tē bāda dōbārā jindā hōṇā huyā thā. haūm̐ tisarē dukkhāṁ rā bī hissēdāra hōṇā cām̐ha, kanē tisa ī rupā jō pāṇā cām̐ha tissō jē tinē apaṇiyā mautī rē jariyē pāyā thā.",null],[3,11,"इसा आसा ने भई हऊँ बी इस तरीके ने मुईरेआं च ते उट्ठीने दूज्जी बार भीं ते जिन्दगिया जो पाई सक्कूँ।","isā āsā nē bhaī haūm̐ bī isa tarīkē nē muīrēāṁ ca tē uṭṭhīnē dūjjī bāra bhīṁ tē jindagiyā jō pāī sakkūm̐.",null],[3,12,"येढ़ा नीं आ भई हऊँ अपणी उपलब्धि पाई चुक्कया या हऊँ पूरा ई सिद्ध बणी चुक्कीरा। पर हऊँ तिसा उपलब्धिया जो पाणे रे खातर लगातार कोशिश करीरां तिसरे खातर मसीह यीशुये हऊँ बन्धक बणाया था।","yēṛhā nīṁ ā bhaī haūm̐ apaṇī upalabdhi pāī cukkayā yā haūm̐ pūrā ī siddha baṇī cukkīrā. para haūm̐ tisā upalabdhiyā jō pāṇē rē khātara lagātāra kōśiśa karīrāṁ tisarē khātara masīha yīśuyē haūm̐ bandhaka baṇāyā thā.",null],[3,13,"मेरे भाईयो, हऊँ ये नीं सोचदा भई हऊँ तिसजो पाई चुक्कीरा, पर गल्ल येई भई बीति रियां गल्लां जो भुल्लीने, सै जे मेरे सामणे आ, तिस लक्ष्य तक पुजणे रे खातर हऊँ संघर्ष करदा रैयां।","mērē bhāīyō, haūm̐ yē nīṁ sōcadā bhaī haūm̐ tisajō pāī cukkīrā, para galla yēī bhaī bīti riyāṁ gallāṁ jō bhullīnē, sai jē mērē sāmaṇē ā, tisa lakṣya taka pujaṇē rē khātara haūm̐ saṁgharṣa karadā raiyāṁ.",null],[3,14,"हऊँ तिस लक्ष्य रे खातर लगातार कोशिश करदा रैआं भई हऊँ अपणे तिस इनामा जो पाई सक्कूँ, तिस्सो जे मसीह यीशुये च पाने खातर परमेशरे अहांजो उपर सद्दया।","haūm̐ tisa lakṣya rē khātara lagātāra kōśiśa karadā raiāṁ bhaī haūm̐ apaṇē tisa ināmā jō pāī sakkūm̐, tissō jē masīha yīśuyē ca pānē khātara paramēśarē ahāṁjō upara saddayā.",null],[3,15,"ताकि तिन्हां लोकां रा, सै जे अहां चते सिद्ध पुरुष बणी चुक्कीरे, येई विचार रखो, पर जे तुहें किसी गल्ला जो किसी होर तरीके ने सोच्चां यें, तां परमेशरा तिस्सो बी तुहां पर परगट करना।","tāki tinhāṁ lōkāṁ rā, sai jē ahāṁ catē siddha puruṣa baṇī cukkīrē, yēī vicāra rakhō, para jē tuhēṁ kisī gallā jō kisī hōra tarīkē nē sōccāṁ yēṁ, tāṁ paramēśarā tissō bī tuhāṁ para paragaṭa karanā.",null],[3,16,"तिसा सच्चाईया तक जे अहें पुज्जी चुक्कीरे, अहांजो तिस पर चलदे रैहणा चाहिन्दा।","tisā saccāīyā taka jē ahēṁ pujjī cukkīrē, ahāṁjō tisa para caladē raihaṇā cāhindā.",null],[3,17,"हे भाईयो, तुहें सारे मिलीने मेरे पिछे चला, सै उदाहरण जे अहें तुहांरे सामणे रखीरा, तिसरे मुताबिक सै जे जीआं ये, तिन्हां पर ध्यान देवा।","hē bhāīyō, tuhēṁ sārē milīnē mērē pichē calā, sai udāharaṇa jē ahēṁ tuhāṁrē sāmaṇē rakhīrā, tisarē mutābika sai jē jīāṁ yē, tinhāṁ para dhyāna dēvā.",null],[3,18,"कांभई येढ़े बी मते सारे लोक ये सै जे मसीह रे क्रूसा ते नफरत करदे हुये जीं ये (मैं तुहांजो कई बार दस्सया कने हुण बी हऊँ ये बिलखी-बिलखी ने बोली रां)","kāṁbhaī yēṛhē bī matē sārē lōka yē sai jē masīha rē krūsā tē napharata karadē huyē jīṁ yē (maiṁ tuhāṁjō kaī bāra dassayā kanē huṇa bī haūm̐ yē bilakhī-bilakhī nē bōlī rāṁ)",null],[3,19,"तिन्हांरा नाश तिन्हारी नीयत ई, तिन्हांरा पेट ई तिन्हांरा ईश्वर आ, कने तिस पर जे तिन्हांजो शर्म औणी चाहिन्दी, तिस पर सै गर्व करां ये। तिन्हांजो सिर्फ संसारिक चीजां री चिन्ता ई।","tinhāṁrā nāśa tinhārī nīyata ī, tinhāṁrā pēṭa ī tinhāṁrā īśvara ā, kanē tisa para jē tinhāṁjō śarma auṇī cāhindī, tisa para sai garva karāṁ yē. tinhāṁjō sirpha saṁsārika cījāṁ rī cintā ī.",null],[3,20,"पर अहांरी जन्मभूमि त स्वर्गा ची, तित्थीते ई अहें अपणे मुक्तीदाता प्रभु यीशु मसीह रे औणे री बाट देखी रांये।","para ahāṁrī janmabhūmi ta svargā cī, titthītē ī ahēṁ apaṇē muktīdātā prabhu yīśu masīha rē auṇē rī bāṭa dēkhī rāṁyē.",null],[3,21,"अपणी तिसा शक्तिया रे जरिये तिसाते जे सारियां चीजां जो सै अपणे बशा च करी लेआं, अपणे कमजोर शरीरा जो बदलीने अपणे दिव्य शरीरा साई बणाई देणा।","apaṇī tisā śaktiyā rē jariyē tisātē jē sāriyāṁ cījāṁ jō sai apaṇē baśā ca karī lēāṁ, apaṇē kamajōra śarīrā jō badalīnē apaṇē divya śarīrā sāī baṇāī dēṇā.",null],[4,1,"इस खातर हे मेरे भाईयो, तुहें मेरी खुशी ये, मेरा गौरव ये, तुहांजो तियां जे मैं दस्सया, प्रभु च तुहें तियां ई मजबूत बणीने रौआ।","isa khātara hē mērē bhāīyō, tuhēṁ mērī khuśī yē, mērā gaurava yē, tuhāṁjō tiyāṁ jē maiṁ dassayā, prabhu ca tuhēṁ tiyāṁ ī majabūta baṇīnē rauā.",null],[4,2,"हऊँ यूओदिआ जो बी कने सुन्तुखे जो बी समझां, भई सै प्रभु च इक मन हुईने रौओ।","haūm̐ yūōdiā jō bī kanē suntukhē jō bī samajhāṁ, bhaī sai prabhu ca ika mana huīnē rauō.",null],[4,3,"मेरे सच्चे साथी तुहांने बी मेरी विनती भई इन्हां जनानां री मदद करयां, ये क्लेमेंस कने मेरे दूज्जे साथियां समेत खुशखबरी फैलाणे च मेरे सौगी जुटी रियां रैईयां, इन्हांरे नौं जिन्दगिया री कताबा च लिखिरे।","mērē saccē sāthī tuhāṁnē bī mērī vinatī bhaī inhāṁ janānāṁ rī madada karayāṁ, yē klēmēṁsa kanē mērē dūjjē sāthiyāṁ samēta khuśakhabarī phailāṇē ca mērē saugī juṭī riyāṁ raiīyāṁ, inhāṁrē nauṁ jindagiyā rī katābā ca likhirē.",null],[4,4,"प्रभु च हमेशा मौज करदे रौआ; हऊँ फेरी भीं बोलां, मौज करा।","prabhu ca hamēśā mauja karadē rauā; haūm̐ phērī bhīṁ bōlāṁ, mauja karā.",null],[4,5,"तुहांरी सहनशील आत्मा रा ज्ञान सारयां लोकां च हो, प्रभु नेड़े ई हाया।","tuhāṁrī sahanaśīla ātmā rā jñāna sārayāṁ lōkāṁ ca hō, prabhu nēṛē ī hāyā.",null],[4,6,"किसी बी गल्ला री चिन्ता मता करदे; पर हर इक गल्ला च धन्यवादा सौगी प्रार्थना कने विनतिया ने अपणी हाजरी परमेशरा रे सामणे रखदे जावा।","kisī bī gallā rī cintā matā karadē; para hara ika gallā ca dhanyavādā saugī prārthanā kanē vinatiyā nē apaṇī hājarī paramēśarā rē sāmaṇē rakhadē jāvā.",null],[4,7,"इसते परमेशरा रिया तरफा ते मिलणे औऴी शान्ति, सै जे समझा ते परे ई तुहांरे मना जो कने तुहांरे विचारां जो मसीह यीशुये च सुरक्षित बणाईने रखगी।","isatē paramēśarā riyā taraphā tē milaṇē auḻī śānti, sai jē samajhā tē parē ī tuhāṁrē manā jō kanē tuhāṁrē vicārāṁ jō masīha yīśuyē ca surakṣita baṇāīnē rakhagī.",null],[4,8,"इस खातर हे भाईयो, तिन्हां गल्लां रा ध्यान करा सै जे सच्चिआं ईयां, कने सै गल्लां जे आदर रे लायक ईयां, कने सै जे ठीक ईयां, कने सै जे पवित्र ईयां, सै जे खुशी देणे औऴियां ई, सै जे सराहना रे लायक ईयां, यनिके कोई बी होर गुण या प्रशंसा री गल्लां ईयां तिन्हां पर ध्यान लगाया करा।","isa khātara hē bhāīyō, tinhāṁ gallāṁ rā dhyāna karā sai jē sacciāṁ īyāṁ, kanē sai gallāṁ jē ādara rē lāyaka īyāṁ, kanē sai jē ṭhīka īyāṁ, kanē sai jē pavitra īyāṁ, sai jē khuśī dēṇē auḻiyāṁ ī, sai jē sarāhanā rē lāyaka īyāṁ, yanikē kōī bī hōra guṇa yā praśaṁsā rī gallāṁ īyāṁ tinhāṁ para dhyāna lagāyā karā.",null],[4,9,"सै गल्लां जे तुहें माह्ते सिखियां, पाईयां या सुणियां या तिसजो करदे हुये मिन्जो देक्खया, तिन्हां गल्लां रा पालन करदे रैया करा, तां परमेशरा रिया शान्तिया रा सोता तुहांरे सौगी रैहणा।","sai gallāṁ jē tuhēṁ māhtē sikhiyāṁ, pāīyāṁ yā suṇiyāṁ yā tisajō karadē huyē minjō dēkkhayā, tinhāṁ gallāṁ rā pālana karadē raiyā karā, tāṁ paramēśarā riyā śāntiyā rā sōtā tuhāṁrē saugī raihaṇā.",null],[4,10,"तुहें पक्का मेरिया भलाईया रे खातर सोच्चां थे पर तुहांजो तिस्सो दस्सणे रा मौका नीं मिल़या था, पर हुण आखिरकार तुहांच मेरे बारे च भीं ते चिन्ता जागी ई, इसते हऊँ प्रभु च बड़ा भरी खुश हुया।","tuhēṁ pakkā mēriyā bhalāīyā rē khātara sōccāṁ thē para tuhāṁjō tissō dassaṇē rā maukā nīṁ mil̈ayā thā, para huṇa ākhirakāra tuhāṁca mērē bārē ca bhīṁ tē cintā jāgī ī, isatē haūm̐ prabhu ca baṛā bharī khuśa huyā.",null],[4,11,"किसी जरुरता रिया वजह ने हऊँ ये नीं बोली करां, काँभई हऊँ चाहे केढ़िया बी हालता च रहूँ; मैं तिसच ई सन्तोख करना सिक्खी लरा।","kisī jaruratā riyā vajaha nē haūm̐ yē nīṁ bōlī karāṁ, kām̐bhaī haūm̐ cāhē kēṛhiyā bī hālatā ca rahūm̐; maiṁ tisaca ī santōkha karanā sikkhī larā.",null],[4,12,"हऊँ दीन होणा बी जाणां कने बधणा बी जाणां; हर इक गल्ला कने हर इक हालातां च हऊँ तृप्त होणा, भूक्खा रैहणा, कने बधणा-घटणा सिखां।","haūm̐ dīna hōṇā bī jāṇāṁ kanē badhaṇā bī jāṇāṁ; hara ika gallā kanē hara ika hālātāṁ ca haūm̐ tr̥pta hōṇā, bhūkkhā raihaṇā, kanē badhaṇā-ghaṭaṇā sikhāṁ.",null],[4,13,"सै जे मिन्जो शक्ति देआं, तिसरे जरिये हऊँ सारयां हालातां रा सामणा करी सक्कां।","sai jē minjō śakti dēāṁ, tisarē jariyē haūm̐ sārayāṁ hālātāṁ rā sāmaṇā karī sakkāṁ.",null],[4,14,"किछ बी हो तुहें मेरे दुक्खां च मेरा हात्थ बटाईने खरा ई कित्या।","kicha bī hō tuhēṁ mērē dukkhāṁ ca mērā hāttha baṭāīnē kharā ī kityā.",null],[4,15,"हे फिलिप्पियो, तुहें त जाणां यें खुशखबरिया रे प्रचारा रे तिन्हां शुरु रे दिनां च ताहली जे मैं मकिदुनिया छड्डया था, तां लेणे-देणे रे बारे च सिर्फ तुहां रिया कलीसिया जो छड्डीने किसी होर कलीसिये मेरा हात्थ नीं बटाया था।","hē philippiyō, tuhēṁ ta jāṇāṁ yēṁ khuśakhabariyā rē pracārā rē tinhāṁ śuru rē dināṁ ca tāhalī jē maiṁ makiduniyā chaḍḍayā thā, tāṁ lēṇē-dēṇē rē bārē ca sirpha tuhāṁ riyā kalīsiyā jō chaḍḍīnē kisī hōra kalīsiyē mērā hāttha nīṁ baṭāyā thā.",null],[4,16,"ताहली जे हऊँ थिस्सलुनिके च था, मेरी जरुरतां पूरी करने रे खातर तुहें बार-बार मेरी मदद कित्ति।","tāhalī jē haūm̐ thissalunikē ca thā, mērī jaruratāṁ pūrī karanē rē khātara tuhēṁ bāra-bāra mērī madada kitti.",null],[4,17,"येढ़ा नीं आ भई हऊँ उपहारां रा इच्छुक आ, बल्कि हऊँ त येह चाँह भई तुहांरे खाते च फायदा जुड़दा ई जाओ।","yēṛhā nīṁ ā bhaī haūm̐ upahārāṁ rā icchuka ā, balki haūm̐ ta yēha cām̐ha bhaī tuhāṁrē khātē ca phāyadā juṛadā ī jāō.",null],[4,18,"तुहें इपफ्रुदिस रे हत्था सै उपहार सै जे सुख देणे औऴी खुशबु भेंटा रे रुपा च मेरले भेज्जी, सै इक येढ़ा स्वीकार करने लायक बलिदान आ, तिसते जे परमेशर खुश हुआं। इन्हां उपहारां रे कारण मेरले जरुरता ते कई मान जादा हुईगरा, मिन्जो मता दित्तिरा, बल्कि तिसते बी जादा दित्तिरा।","tuhēṁ ipaphrudisa rē hatthā sai upahāra sai jē sukha dēṇē auḻī khuśabu bhēṁṭā rē rupā ca mēralē bhējjī, sai ika yēṛhā svīkāra karanē lāyaka balidāna ā, tisatē jē paramēśara khuśa huāṁ. inhāṁ upahārāṁ rē kāraṇa mēralē jaruratā tē kaī māna jādā huīgarā, minjō matā dittirā, balki tisatē bī jādā dittirā.",null],[4,19,"मेरा परमेशर बी अपणे तिस धना रे अनुशार सै जे महिमा समेत मसीह यीशु चा, तुहांरी सारी जरुरतां जो पूरी करगा।","mērā paramēśara bī apaṇē tisa dhanā rē anuśāra sai jē mahimā samēta masīha yīśu cā, tuhāṁrī sārī jaruratāṁ jō pūrī karagā.",null],[4,20,"अहांरे परमेशर कने पिते री महिमा युगां-युगां तक हुन्दी रौ। आमीन।","ahāṁrē paramēśara kanē pitē rī mahimā yugāṁ-yugāṁ taka hundī rau. āmīna.",null],[4,21,"यीशु मसीह रे हरेक पवित्र माह्णुये जो नमस्कार बोला। सै जे भाई मेरने आ, तुहांजो नमस्कार बोलां ये।","yīśu masīha rē harēka pavitra māhṇuyē jō namaskāra bōlā. sai jē bhāī mēranē ā, tuhāṁjō namaskāra bōlāṁ yē.",null],[4,22,"सारे पवित्र लोक, खास करीने सै जे कैसर रे घराने रे, तुहांजो नमस्कार बोलां ये।","sārē pavitra lōka, khāsa karīnē sai jē kaisara rē gharānē rē, tuhāṁjō namaskāra bōlāṁ yē.",null],[4,23,"तुहां चते हर इक्की पर अहांरे प्रभु यीशु मसीह रा अनुग्रह तुहां रिया आत्मा सौगी रौये।","tuhāṁ catē hara ikkī para ahāṁrē prabhu yīśu masīha rā anugraha tuhāṁ riyā ātmā saugī rauyē.",null]],"mjl":[[1,1,"मसीह यीसू रे दास पौलुस होर तिमिथिउसा री तरफा ले, जो मसीह यीसू मन्झ तिन्हा सभ पवित्र लोका रे नांऊ, जो बिशप होर दासा समेत फिलिप्पी मन्झ रैंहयांं ऐं,","masīha yīsū rē dāsa paulusa hōra timithiusā rī taraphā lē, jō masīha yīsū manjha tinhā sabha pavitra lōkā rē nāṁū, jō biśapa hōra dāsā samēta philippī manjha raiṁhayāṁṁ aiṁ,",null],[1,2,"आस्सा रे पिता परमेसर होर प्रभु यीसू मसीह री तरफा ले तुस्सा जो दया होर सांति मिल्दी रहे l","āssā rē pitā paramēsara hōra prabhu yīsū masīha rī taraphā lē tussā jō dayā hōra sāṁti mildī rahē l",null],[1,3,"हांऊ जेबे-जेबे तुस्सा जो याद करहा, तेबे-तेबे हांऊ आपणे परमेसर रा धन्याबाद करहा l","hāṁū jēbē-jēbē tussā jō yāda karahā, tēbē-tēbē hāṁū āpaṇē paramēsara rā dhanyābāda karahā l",null],[1,4,"होर जेबे केबे हांऊ तुस्सा सभी रे कठे अरज करहा, ता हमेसा खुसी साउगी अरज करहा l","hōra jēbē kēbē hāṁū tussā sabhī rē kaṭhē araja karahā, tā hamēsā khusī sāugī araja karahā l",null],[1,5,"इधी कठे, कि तुस्से पैहले ध्याड़े ले लई किन्हें आजा तक सुसमाचार रे फ्ल्हाणे मन्झ मेरे भागीदार रही रे l","idhī kaṭhē, ki tussē paihalē dhyāṛē lē laī kinhēṁ ājā taka susamācāra rē phlhāṇē manjha mērē bhāgīdāra rahī rē l",null],[1,6,"होर मुंजो एस गल्ला रा भरोसा आ, कि जिने तुस्सा मन्झ खरा काम सुहरू कितिरा, तेस ई से काम यीसू मसीह रे ध्याड़े तक पूरा करणा l","hōra muṁjō ēsa gallā rā bharōsā ā, ki jinē tussā manjha kharā kāma suharū kitirā, tēsa ī sē kāma yīsū masīha rē dhyāṛē taka pūrā karaṇā l",null],[1,7,"तुस्सा सभी रे बारे मन्झ मेरा एहड़ा सोचना ठीक ई हाया; क्यूंकि तुस्से सभ मेरे मना मन्झ बस्सी रे, होर ना सिर्फ तेबे ई जेबे जे हांऊ जेहला मन्झ आ, बल्कि तेबे भी जेबे हांऊ सुसमाचारा री सच्चाई री रक्षा करदे हुए, होर तेता रा सबूत देणे मन्झ तुस्से सभ दया मन्झ मेरे साउगी भागिदार ऐ l","tussā sabhī rē bārē manjha mērā ēhaṛā sōcanā ṭhīka ī hāyā; kyūṁki tussē sabha mērē manā manjha bassī rē, hōra nā sirpha tēbē ī jēbē jē hāṁū jēhalā manjha ā, balki tēbē bhī jēbē hāṁū susamācārā rī saccāī rī rakṣā karadē huē, hōra tētā rā sabūta dēṇē manjha tussē sabha dayā manjha mērē sāugī bhāgidāra ai l",null],[1,8,"क्यूंकि परमेसर मेरा गुआह आ; कि हांऊ मसीह यीसू रे प्यारा साहीं तुस्सा सभी जो कितना चाहां l","kyūṁki paramēsara mērā guāha ā; ki hāṁū masīha yīsū rē pyārā sāhīṁ tussā sabhī jō kitanā cāhāṁ l",null],[1,9,"होर हांऊ ये प्रार्थना करहा, कि तुस्सा रा प्यार, ज्ञान होर सभ किस्मा रे विवेका समेत होर ज्यादा भी बढ़दे जाए l","hōra hāṁū yē prārthanā karahā, ki tussā rā pyāra, jñāna hōra sabha kismā rē vivēkā samēta hōra jyādā bhī baṛhadē jāē l",null],[1,10,"एथी तक कि तुस्से खरी ले खरी गल्ला जो, अपनाई लऊआ होर मसीह रे ध्याड़े तक सच्चे; होर निर्दोष बणी किन्हें रैहया l","ēthī taka ki tussē kharī lē kharī gallā jō, apanāī laūā hōra masīha rē dhyāṛē taka saccē; hōra nirdōṣa baṇī kinhēṁ raihayā l",null],[1,11,"होर तेस धार्मिकता रे फला ले जो यीसू मसीह रे ज्रीए मिल्हा; भरपूर हुंदे जाऊआ जेस ले परमेसरा री म्हीमा होर स्तुति हुन्दी रहे l","hōra tēsa dhārmikatā rē phalā lē jō yīsū masīha rē jrīē milhā; bharapūra huṁdē jāūā jēsa lē paramēsarā rī mhīmā hōra stuti hundī rahē l",null],[1,12,"हे भाईयो, हांऊ चाहां, कि तुस्से ये जाणी लो, कि जो कुछ मेरे पर बीतिरा, तेस ले सुसमाचारा री बढ़ौतरी हुई l","hē bhāīyō, hāṁū cāhāṁ, ki tussē yē jāṇī lō, ki jō kucha mērē para bītirā, tēsa lē susamācārā rī baṛhautarī huī l",null],[1,13,"एथी तक कि कैसरा रे राजभवना री सारी पलटन होर बाकी लोका मन्झ ये प्रगट हुई गया, कि हांऊ मसीह रे कठे कैदा मन्झ आ l","ēthī taka ki kaisarā rē rājabhavanā rī sārī palaṭana hōra bākī lōkā manjha yē pragaṭa huī gayā, ki hāṁū masīha rē kaṭhē kaidā manjha ā l",null],[1,14,"होर प्रभु मन्झ जो भाई ऐ, तिन्हा मंझा ले बौहत मेरे कैद हुणे री वजहा ले, हिम्मत बान्ही किन्हें, परमेसरा रा वचन निधड़क सुनाणे रा होर भी ज्यादा हिम्मत करहा ऐ l","hōra prabhu manjha jō bhāī ai, tinhā maṁjhā lē bauhata mērē kaida huṇē rī vajahā lē, himmata bānhī kinhēṁ, paramēsarā rā vacana nidhaṛaka sunāṇē rā hōra bhī jyādā himmata karahā ai l",null],[1,15,"कितने ता हीर्ख होर झगड़े री वजहा ले मसीह रा प्रचार करहा ऐ होर कुछ खरी इच्छा ले करहा ऐ l","kitanē tā hīrkha hōra jhagaṛē rī vajahā lē masīha rā pracāra karahā ai hōra kucha kharī icchā lē karahā ai l",null],[1,16,"स्यों जे प्यारा किन्हें प्रचार करहा ऐ, जाणहांं ऐं कि मुंजो सुसमाचारा रा बचाव करणे रे कठे नियुक्त कितिरा l","syōṁ jē pyārā kinhēṁ pracāra karahā ai, jāṇahāṁṁ aiṁ ki muṁjō susamācārā rā bacāva karaṇē rē kaṭhē niyukta kitirā l",null],[1,17,"होर कई लोक ता खरे इरादे ले नी, पर आपणे मतलबा रे कठे मसीह रा प्रचार करहा ऐ, कि कैदखाने मन्झ मेरे कठे संकट पैदा हो l","hōra kaī lōka tā kharē irādē lē nī, para āpaṇē matalabā rē kaṭhē masīha rā pracāra karahā ai, ki kaidakhānē manjha mērē kaṭhē saṁkaṭa paidā hō l",null],[1,18,"तेबे क्या हुआ? सिर्फ ये हुआ, कि हर तरहा ले चाहे भाने किन्हें, चाहे सच्चाई किन्हें, मसीह रा प्रचार हुहां, होर एता ले मुंजो खुसी मिल्हा ई, होर खुसी मिल्दी ई रैहणी l","tēbē kyā huā? sirpha yē huā, ki hara tarahā lē cāhē bhānē kinhēṁ, cāhē saccāī kinhēṁ, masīha rā pracāra huhāṁ, hōra ētā lē muṁjō khusī milhā ī, hōra khusī mildī ī raihaṇī l",null],[1,19,"क्यूंकि हांऊ ये जाणहां, कि तुस्सा री प्रार्थना होर यीसू मसीह री आत्मा री सहायता ले एस कैदखाने रा फल मेरी रिहाई हूणीं l","kyūṁki hāṁū yē jāṇahāṁ, ki tussā rī prārthanā hōra yīsū masīha rī ātmā rī sahāyatā lē ēsa kaidakhānē rā phala mērī rihāī hūṇīṁ l",null],[1,20,"मेरे दिला री आस होर इच्छा ता ये ई, कि केसी गल्ला मन्झ हांऊ सर्मिन्दा नी होऊं, पर मेरी पुरी हिम्मता री वजहा ले मसीह री म्हीमा मेरे सरीरा मन्झ हमेसा हुन्दी रैहे, तिहां ई एबे भी हो, चाहें हांऊ जीऊन्दा रहूं या मरी जाऊं l","mērē dilā rī āsa hōra icchā tā yē ī, ki kēsī gallā manjha hāṁū sarmindā nī hōūṁ, para mērī purī himmatā rī vajahā lē masīha rī mhīmā mērē sarīrā manjha hamēsā hundī raihē, tihāṁ ī ēbē bhī hō, cāhēṁ hāṁū jīūndā rahūṁ yā marī jāūṁ l",null],[1,21,"क्यूंकि मेरे कठे जीऊन्दा रैहणां मसीह आ, होर मरी जाणा फायदा आ l","kyūṁki mērē kaṭhē jīūndā raihaṇāṁ masīha ā, hōra marī jāṇā phāyadā ā l",null],[1,22,"पर अगर सरीरा मन्झ जीऊन्दा रैहणां ई मेरे कामा रे कठे फायदा आ, होर हांऊ नी जाणदा, कि क्या चुणाव करूं l","para agara sarīrā manjha jīūndā raihaṇāṁ ī mērē kāmā rē kaṭhē phāyadā ā, hōra hāṁū nī jāṇadā, ki kyā cuṇāva karūṁ l",null],[1,23,"क्यूंकि हांऊ दुंहींं रे बीचा मन्झ लटकीरा; इच्छा ता ये करहा ई कि हांऊ निकळी किन्हें मसीह वाले चली जाऊं, क्यूंकि ये खरा हूणां l","kyūṁki hāṁū duṁhīṁṁ rē bīcā manjha laṭakīrā; icchā tā yē karahā ī ki hāṁū nikaḷī kinhēṁ masīha vālē calī jāūṁ, kyūṁki yē kharā hūṇāṁ l",null],[1,24,"पर तुस्सा रे कठे एस सरीरा मन्झ रैहणां होर भी ज्यादा जरूरी आ l","para tussā rē kaṭhē ēsa sarīrā manjha raihaṇāṁ hōra bhī jyādā jarūrī ā l",null],[1,25,"होर इधी कठे कि मुंजो एस गल्ला रा भरोसा आ, हांऊ जाणहां कि मां जीऊन्दा रैहणां, बल्कि तुस्सा सभी साउगी रैहणां, ताकि तुस्से प्रभु मन्झ मजबूत हुंदे जाओ होर तेस मन्झ खुस रहो l","hōra idhī kaṭhē ki muṁjō ēsa gallā rā bharōsā ā, hāṁū jāṇahāṁ ki māṁ jīūndā raihaṇāṁ, balki tussā sabhī sāugī raihaṇāṁ, tāki tussē prabhu manjha majabūta huṁdē jāō hōra tēsa manjha khusa rahō l",null],[1,26,"होर जो घमण्ड तुस्से मरे बारे मन्झ करहा ऐ, से मेरे तुस्सा वाले दबारा वाप्स आऊणे ले मसीह मन्झ होर ज्यादा बढ़ी जाए l","hōra jō ghamaṇḍa tussē marē bārē manjha karahā ai, sē mērē tussā vālē dabārā vāpsa āūṇē lē masīha manjha hōra jyādā baṛhī jāē l",null],[1,27,"बस इतना करेया कि तुस्सा रा चाल चलन मसीह रे सुसमाचारा रे लायक हुई सके, कि चाहे हांऊ आई किन्हें तुस्सा जो देखूं, चाहे नी भी आऊं, तुस्सा रे बारे मन्झ ये सुणूं, कि तुस्से एक ई आत्मा मन्झ पक्के हो, होर एक मन हुई किन्हें सुसमाचारा रे विस्वासा रे कठे बड़ी मैहनत करहा ऐ l","basa itanā karēyā ki tussā rā cāla calana masīha rē susamācārā rē lāyaka huī sakē, ki cāhē hāṁū āī kinhēṁ tussā jō dēkhūṁ, cāhē nī bhī āūṁ, tussā rē bārē manjha yē suṇūṁ, ki tussē ēka ī ātmā manjha pakkē hō, hōra ēka mana huī kinhēṁ susamācārā rē visvāsā rē kaṭhē baṛī maihanata karahā ai l",null],[1,28,"होर केसी गल्ला मन्झ वरोधीया ले नी डरदे; ये तिन्हा रे कठे ता विनासा रा होर तुस्सा रे कठे उद्धारा रा बिल्कुल साफ चिन्ह आ; होर ये परमेसरा री तरफा ले आ l","hōra kēsī gallā manjha varōdhīyā lē nī ḍaradē; yē tinhā rē kaṭhē tā vināsā rā hōra tussā rē kaṭhē uddhārā rā bilkula sāpha cinha ā; hōra yē paramēsarā rī taraphā lē ā l",null],[1,29,"क्यूंकि मसीह री वजहा ले तुस्सा पर ये दया हुई कि ना सिर्फ तेस पर विस्वास करा पर तेसरे कठे दुःख भी उठाऊआ l","kyūṁki masīha rī vajahā lē tussā para yē dayā huī ki nā sirpha tēsa para visvāsa karā para tēsarē kaṭhē duḥkha bhī uṭhāūā l",null],[1,30,"होर तुस्से भी तेहड़ी ई मैहनत करदे रहुआ, जिहां तुस्से मुंजो करदे देखिरा, होर एबे भी सुणहां ऐं, कि तेहड़ा हल्ली भी करेया करहा l","hōra tussē bhī tēhaṛī ī maihanata karadē rahuā, jihāṁ tussē muṁjō karadē dēkhirā, hōra ēbē bhī suṇahāṁ aiṁ, ki tēhaṛā hallī bhī karēyā karahā l",null],[2,1,"फेरी तुस्सा लोका मन्झ, अगर मन्झ मसीह मन्झ कुछ प्रोत्साहन आ, होर कुछ प्यारा री सांत्वना ई, होर कुछ आत्मा री भागीदारी ई, होर कुछ करुणा होर दया ई l","phērī tussā lōkā manjha, agara manjha masīha manjha kucha prōtsāhana ā, hōra kucha pyārā rī sāṁtvanā ī, hōra kucha ātmā rī bhāgīdārī ī, hōra kucha karuṇā hōra dayā ī l",null],[2,2,"तुस्से मेरी ये खुसी पूरी करा ताकि तुस्से एक मन बणी किन्हें रहो; होर एक ई प्यार, एक ई भावना, होर एक ई नजरिया रखा l","tussē mērī yē khusī pūrī karā tāki tussē ēka mana baṇī kinhēṁ rahō; hōra ēka ī pyāra, ēka ī bhāvanā, hōra ēka ī najariyā rakhā l",null],[2,3,"आपणे मतलबा रे कठे या झूठी साना रे कठे कुछ नी करा पर दीन हुई किन्हें, एक दूजे जो आपणे ले खरा समझा l","āpaṇē matalabā rē kaṭhē yā jhūṭhī sānā rē kaṭhē kucha nī karā para dīna huī kinhēṁ, ēka dūjē jō āpaṇē lē kharā samajhā l",null],[2,4,"तुस्सा मंझा ले हर एकी जो चहिए कि से सिर्फ आपणी भलाई रे कठे नी, पर दूजे री भलाई रा भी ख्याल रखे l","tussā maṁjhā lē hara ēkī jō cahiē ki sē sirpha āpaṇī bhalāī rē kaṭhē nī, para dūjē rī bhalāī rā bhī khyāla rakhē l",null],[2,5,"जेहड़ा मसीह यीसू रा स्वभाव था, तेहड़ा ई तुस्सा रा स्वभाव भी हो l","jēhaṛā masīha yīsū rā svabhāva thā, tēhaṛā ī tussā rā svabhāva bhī hō l",null],[2,6,"जिने जे परमेसरा रे रूपा मन्झ हुई किन्हें भी साक्षात परमेसरा री समानता जो आपणे बसा मन्झ रखणे री चीज नी समझी l","jinē jē paramēsarā rē rūpā manjha huī kinhēṁ bhī sākṣāta paramēsarā rī samānatā jō āpaṇē basā manjha rakhaṇē rī cīja nī samajhī l",null],[2,7,"बल्कि आपणे आपा जो एहड़ा खाली करी दितेया, होर दासा रा रूप धारण कितेया, होर माहणुं री समानता मन्झ हुई गया l","balki āpaṇē āpā jō ēhaṛā khālī karī ditēyā, hōra dāsā rā rūpa dhāraṇa kitēyā, hōra māhaṇuṁ rī samānatā manjha huī gayā l",null],[2,8,"होर माहणुं रे रूपा मन्झ प्रगट हुई किन्हें आपणे आपा जो दीन कितेया, होर एथी तक हुक्म मन्नेया, कि मौत, हां, क्रूसा री मौत भी सही ली l","hōra māhaṇuṁ rē rūpā manjha pragaṭa huī kinhēṁ āpaṇē āpā jō dīna kitēyā, hōra ēthī taka hukma mannēyā, ki mauta, hāṁ, krūsā rī mauta bhī sahī lī l",null],[2,9,"एस वजहा ले परमेसरे तेस जो बौहत म्हान भी कितेया, होर तेस जो से नांऊ दितेया जो सभ नांऊआंं ले ऊपर आ l","ēsa vajahā lē paramēsarē tēsa jō bauhata mhāna bhī kitēyā, hōra tēsa jō sē nāṁū ditēyā jō sabha nāṁūāṁṁ lē ūpara ā l",null],[2,10,"कि जो स्वर्गा मन्झ होर धरती पर होर जो धरती रे हेठ ऐ; स्यों सभ यीसू रे नांऊआंं पर घुटना टेके l","ki jō svargā manjha hōra dharatī para hōra jō dharatī rē hēṭha ai; syōṁ sabha yīsū rē nāṁūāṁṁ para ghuṭanā ṭēkē l",null],[2,11,"होर परमेसर पिता री म्हीमा रे कठे हर एक जीभ मनी ले कि यीसू मसीह ई प्रभु आ l","hōra paramēsara pitā rī mhīmā rē kaṭhē hara ēka jībha manī lē ki yīsū masīha ī prabhu ā l",null],[2,12,"इधी कठे हे मेरे प्यारेओ, जिहां तुस्से हमेसा ले हुक्म मन्नदे आईरे, तिहां ई एबे भी ना सिर्फ मेरे साउगी रैहन्दे हुए, पर खास करी किन्हें एबे मेरे दूर रैहणे पर भी डरदे होर काम्दे हुए आपणे-आपणे उद्धारा रा काम पूरा करदे जाऊआ l","idhī kaṭhē hē mērē pyārēō, jihāṁ tussē hamēsā lē hukma mannadē āīrē, tihāṁ ī ēbē bhī nā sirpha mērē sāugī raihandē huē, para khāsa karī kinhēṁ ēbē mērē dūra raihaṇē para bhī ḍaradē hōra kāmdē huē āpaṇē-āpaṇē uddhārā rā kāma pūrā karadē jāūā l",null],[2,13,"क्यूंकि ये परमेसर आ, जो तिन्हा कामा री इच्छा होर तिन्हा जो पूरा करणे रा कर्म, जो परमेसरा जो खरे लग्हा, तुस्सा मन्झ पैदा करहा l","kyūṁki yē paramēsara ā, jō tinhā kāmā rī icchā hōra tinhā jō pūrā karaṇē rā karma, jō paramēsarā jō kharē lag_hā, tussā manjha paidā karahā l",null],[2,14,"सब काम बगैर कुड़कुड़ाए होर बगैर बैहसा ले करा l","saba kāma bagaira kuṛakuṛāē hōra bagaira baihasā lē karā l",null],[2,15,"ताकि तुस्से निर्दोष होर भोले हुई किन्हें टेढ़े होर ढीठ लोका रे बीचा मन्झ परमेसरा रे निष्कलंक बणी किन्हें रहुआ, जिन्हा रे बीचा मन्झ तुस्से जिन्दगी रा वचन लई किन्हें संसारा मन्झ भख्हिरे दीये साहीं सुझ्हा ऐ l","tāki tussē nirdōṣa hōra bhōlē huī kinhēṁ ṭēṛhē hōra ḍhīṭha lōkā rē bīcā manjha paramēsarā rē niṣkalaṁka baṇī kinhēṁ rahuā, jinhā rē bīcā manjha tussē jindagī rā vacana laī kinhēṁ saṁsārā manjha bhakhhirē dīyē sāhīṁ sujhhā ai l",null],[2,16,"जिन्दगी रे वचना जो मजबूती किन्हें पकड़ी रखा ताकि मसीह रे ध्याड़े मुंजो एस गल्ला रा घमण्ड हो, कि मेरी जिन्दगी री भाग दोड़ होर मेरी मैहनत बेकार नी हुई l","jindagī rē vacanā jō majabūtī kinhēṁ pakaṛī rakhā tāki masīha rē dhyāṛē muṁjō ēsa gallā rā ghamaṇḍa hō, ki mērī jindagī rī bhāga dōṛa hōra mērī maihanata bēkāra nī huī l",null],[2,17,"होर अगर मुंजो तुस्सा रे विस्वासा रे बलिदान होर सेउआ रे साउगी खून बहाणा पये, तेबे भी हांऊ खुस आ, होर तुस्सा सभी साउगी खुसी मणाहां l","hōra agara muṁjō tussā rē visvāsā rē balidāna hōra sēuā rē sāugī khūna bahāṇā payē, tēbē bhī hāṁū khusa ā, hōra tussā sabhī sāugī khusī maṇāhāṁ l",null],[2,18,"तिहां ई तुस्से भी खुस हो, होर मेरे साउगी खुसी मणाऊआ l","tihāṁ ī tussē bhī khusa hō, hōra mērē sāugī khusī maṇāūā l",null],[2,19,"मुंजो प्रभु यीसू मन्झ आस ई, कि मां तिमिथिउसा जो झटपट तुस्सा वाले भेजी देणा, ताकि तुस्सा रा हाल सुणी किन्हें मुंजो चैन मिली सके l","muṁjō prabhu yīsū manjha āsa ī, ki māṁ timithiusā jō jhaṭapaṭa tussā vālē bhējī dēṇā, tāki tussā rā hāla suṇī kinhēṁ muṁjō caina milī sakē l",null],[2,20,"क्यूंकि मेरे वाले एहड़े स्वभावा रा कोई आदमी नी हाया, जो खरे मना ले तुस्सा री फिकर करे l","kyūṁki mērē vālē ēhaṛē svabhāvā rā kōī ādamī nī hāyā, jō kharē manā lē tussā rī phikara karē l",null],[2,21,"क्यूंकि सभ आपणे मतलबा री टोळा मन्झ रैहां ऐं ना कि यीसू मसीह री l","kyūṁki sabha āpaṇē matalabā rī ṭōḷā manjha raihāṁ aiṁ nā ki yīsū masīha rī l",null],[2,22,"पर तेस जो ता तुस्से परखी लया होर जाणी भी लया, कि जेहड़ा म्ह्ठा बाबा साउगी करहा, तिहां ई तिने सुसमाचारा रे फ्ल्हाणे मन्झ मेरे साउगी मैहनत किती l","para tēsa jō tā tussē parakhī layā hōra jāṇī bhī layā, ki jēhaṛā mhṭhā bābā sāugī karahā, tihāṁ ī tinē susamācārā rē phlhāṇē manjha mērē sāugī maihanata kitī l",null],[2,23,"इधी कठे मुंजो आस ई, कि जीहां ई मुंजो पता चलणा कि मेरी क्या हालत हूणीं, तिहां ई मां से जल्दी भेजी देणा l","idhī kaṭhē muṁjō āsa ī, ki jīhāṁ ī muṁjō patā calaṇā ki mērī kyā hālata hūṇīṁ, tihāṁ ī māṁ sē jaldī bhējī dēṇā l",null],[2,24,"होर मुंजो प्रभु मन्झ भरोसा आ, कि मां आपु भी जल्दी आई जाणा l","hōra muṁjō prabhu manjha bharōsā ā, ki māṁ āpu bhī jaldī āī jāṇā l",null],[2,25,"पर मैं इपफ्रदीतुसा जो, जो मेरा भाई, होर साउगी काम करणे वाळा, होर संगी योद्धा होर तुस्सा रा दूत, होर जरूरी गल्ला मन्झ मेरी सेउआ टैहल करणे वाळा आ, तुस्सा वाले भेजणा जरुरी समझ्या l","para maiṁ ipaphradītusā jō, jō mērā bhāī, hōra sāugī kāma karaṇē vāḷā, hōra saṁgī yōddhā hōra tussā rā dūta, hōra jarūrī gallā manjha mērī sēuā ṭaihala karaṇē vāḷā ā, tussā vālē bhējaṇā jarurī samajhyā l",null],[2,26,"क्यूंकि तेसरा मन तुस्सा सभी किन्हें लगी गईरा था, एता री वजहा ले से बेचैन रैंहयांं था, क्यूंकि तुस्से तेसरी बमारी रा हाल सुणेया था l","kyūṁki tēsarā mana tussā sabhī kinhēṁ lagī gaīrā thā, ētā rī vajahā lē sē bēcaina raiṁhayāṁṁ thā, kyūṁki tussē tēsarī bamārī rā hāla suṇēyā thā l",null],[2,27,"होर ये गल ता पक्की थी कि से बमार हुई गईरा था, एथी तक कि से मरणे वाळा ई था, पर परमेसरे तेस पर दया किती; होर सिर्फ तेस पर ई नईं पर मुंजो पर भी, कि मेरे ऊपर दुःखा पर दुःख नी हो l","hōra yē gala tā pakkī thī ki sē bamāra huī gaīrā thā, ēthī taka ki sē maraṇē vāḷā ī thā, para paramēsarē tēsa para dayā kitī; hōra sirpha tēsa para ī naīṁ para muṁjō para bhī, ki mērē ūpara duḥkhā para duḥkha nī hō l",null],[2,28,"इधी कठे मैं तेस जो भेजणे रा होर भी जतन कितेया, कि तुस्से तेस ले द्बारा मुलाकात करी किन्हें खुस हुई जाओ होर मेरा दुःख घटी जाए l","idhī kaṭhē maiṁ tēsa jō bhējaṇē rā hōra bhī jatana kitēyā, ki tussē tēsa lē dbārā mulākāta karī kinhēṁ khusa huī jāō hōra mērā duḥkha ghaṭī jāē l",null],[2,29,"इधी कठे तुस्से प्रभु मन्झ तेस ले बौहत खुसी साउगी मिलणा, होर एहड़े री इज्जत करदे रैहणां l","idhī kaṭhē tussē prabhu manjha tēsa lē bauhata khusī sāugī milaṇā, hōra ēhaṛē rī ijjata karadē raihaṇāṁ l",null],[2,30,"क्यूंकि से ई मसीह रे कामा रे कठे आपणे प्राणा जो खतरे मन्झ पाई किन्हें मौता रे नेडे पूजी गईरा था, ताकि जो घटी कमी तुस्सा री तरफा ले मेरी सेउआ मन्झ हुई, तेस जो से पूरी करी दे l","kyūṁki sē ī masīha rē kāmā rē kaṭhē āpaṇē prāṇā jō khatarē manjha pāī kinhēṁ mautā rē nēḍē pūjī gaīrā thā, tāki jō ghaṭī kamī tussā rī taraphā lē mērī sēuā manjha huī, tēsa jō sē pūrī karī dē l",null],[3,1,"इधी कठे मेरे भाईयो, प्रभु मन्झ खुस रहुआ; तुस्सा जो बार-बार स्यों गल्ला लिख्दे रैहणे ले मुंजो कोई कष्ट नी हुंदा, क्यूंकि एता मन्झ तुस्सा री सुरक्षा ई l","idhī kaṭhē mērē bhāīyō, prabhu manjha khusa rahuā; tussā jō bāra-bāra syōṁ gallā likhdē raihaṇē lē muṁjō kōī kaṣṭa nī huṁdā, kyūṁki ētā manjha tussā rī surakṣā ī l",null],[3,2,"कुत्ते ले सावधान रहा, तिन्हा बुरे काम करणे वाळे ले सावधान रहुआ, होर झूठे खतना वाळे ले सावधान रहुआ l","kuttē lē sāvadhāna rahā, tinhā burē kāma karaṇē vāḷē lē sāvadhāna rahuā, hōra jhūṭhē khatanā vāḷē lē sāvadhāna rahuā l",null],[3,3,"क्यूंकि खतना वाळे ता आस्से ई हाए, जो परमेसरा री अगुवाई ले आराधना करहा ऐ, होर मसीह यीसू पर घमण्ड करहा ऐ, होर सरीरा पर भरोसा नी रख्दे l","kyūṁki khatanā vāḷē tā āssē ī hāē, jō paramēsarā rī aguvāī lē ārādhanā karahā ai, hōra masīha yīsū para ghamaṇḍa karahā ai, hōra sarīrā para bharōsā nī rakhdē l",null],[3,4,"पर हांऊ ता सरीरा पर भरोसा रख्ही सक्हा, अगर केसी होरी जो सरीरा पर भरोसा रखणे रा विचार हाया, ता हांऊ तेस ले भी बढ़ी किन्हें रख्ही सक्हा l","para hāṁū tā sarīrā para bharōsā rakhhī sak_hā, agara kēsī hōrī jō sarīrā para bharōsā rakhaṇē rā vicāra hāyā, tā hāṁū tēsa lē bhī baṛhī kinhēṁ rakhhī sak_hā l",null],[3,5,"आठुए ध्याड़े मेरा खतना हुआ, इस्राएला रे बंस, होर बिन्यामिना रे गोत्रा रा आ; इब्रानिया रा इब्रानी आ; व्यवस्था रे बारे मन्झ अगर बोल्या जाए ता हांऊ फरीसी आ l","āṭhuē dhyāṛē mērā khatanā huā, isrāēlā rē baṁsa, hōra binyāminā rē gōtrā rā ā; ibrāniyā rā ibrānī ā; vyavasthā rē bārē manjha agara bōlyā jāē tā hāṁū pharīsī ā l",null],[3,6,"जेथी तक मेरी निष्ठा रा सुआल आ, ता हांऊ कलीसिया जो सताणे वाळा; होर व्यवस्था री धार्मिकता रे बारे मन्झ अगर बोल्या जाए, ता हांऊ निर्दोष आ l","jēthī taka mērī niṣṭhā rā suāla ā, tā hāṁū kalīsiyā jō satāṇē vāḷā; hōra vyavasthā rī dhārmikatā rē bārē manjha agara bōlyā jāē, tā hāṁū nirdōṣa ā l",null],[3,7,"पर जो-जो गल्ला मेरे फायदे री थी, तिन्हा चीजा जो मैं मसीह री वजहा ले नुकसान सम्झ्हा l","para jō-jō gallā mērē phāyadē rī thī, tinhā cījā jō maiṁ masīha rī vajahā lē nukasāna samjhhā l",null],[3,8,"बल्कि हांऊ आपणे प्रभु मसीह यीसू री पैहचाणा री खरेपना री वजहा ले सभ चीजा जो नुकसान सम्झहा; जेसरी वजहा ले सभ चीजा रा नुकसान उठाया, होर तिन्हा चीजा जो हांऊ कूड़ा सम्झहा, जेस ले हांऊ मसीह जो पाई सकूं l","balki hāṁū āpaṇē prabhu masīha yīsū rī paihacāṇā rī kharēpanā rī vajahā lē sabha cījā jō nukasāna samjhahā; jēsarī vajahā lē sabha cījā rā nukasāna uṭhāyā, hōra tinhā cījā jō hāṁū kūṛā samjhahā, jēsa lē hāṁū masīha jō pāī sakūṁ l",null],[3,9,"होर तेस मन्झ पाया जाऊं; ना कि आपणी तेस धार्मिकता री वजहा ले नी, जो व्यवस्था रे विधाना पर टिकिरी थी, बल्कि तेस धार्मिकता री वजहा ले जो मसीह पर विस्वास करणे री वजहा ले, होर परमेसरा री तरफा ले विस्वास करणे पर मिल्हा ई l","hōra tēsa manjha pāyā jāūṁ; nā ki āpaṇī tēsa dhārmikatā rī vajahā lē nī, jō vyavasthā rē vidhānā para ṭikirī thī, balki tēsa dhārmikatā rī vajahā lē jō masīha para visvāsa karaṇē rī vajahā lē, hōra paramēsarā rī taraphā lē visvāsa karaṇē para milhā ī l",null],[3,10,"होर हांऊ तेस जो होर तेसरे मौता पर जीत पाणे री सामर्था जो, होर तेस साउगी दुःखा मन्झ भागी दार हुणे रे भेदा जो जाणु, होर तेस री मौता री समानता जो पाई लूँ l","hōra hāṁū tēsa jō hōra tēsarē mautā para jīta pāṇē rī sāmarthā jō, hōra tēsa sāugī duḥkhā manjha bhāgī dāra huṇē rē bhēdā jō jāṇu, hōra tēsa rī mautā rī samānatā jō pāī lūm̐ l",null],[3,11,"ताकि हांऊ केसी भी तरीके ले मरीरे मंझा ले जी उठी किन्हें पुनरुत्थाना जो पाई सकूं l","tāki hāṁū kēsī bhī tarīkē lē marīrē maṁjhā lē jī uṭhī kinhēṁ punarutthānā jō pāī sakūṁ l",null],[3,12,"ये मतलब नी आ, कि हांऊ पाई चुकिरा; या सिद्ध हुई चुकिरा, पर तेस चीजा जो पकड़ने रे कठे दोड़ लगाया करहा, जेसरे कठे मसीह यीसूए हांऊ पकड़ी रा था l","yē matalaba nī ā, ki hāṁū pāī cukirā; yā siddha huī cukirā, para tēsa cījā jō pakaṛanē rē kaṭhē dōṛa lagāyā karahā, jēsarē kaṭhē masīha yīsūē hāṁū pakaṛī rā thā l",null],[3,13,"हे भाईयो, मेरी इच्छा ये नी हाई कि हांऊ पकड़ी चुकिरा; पर सिर्फ एक काम करहा जो कि जो चीजा पीछे रही गईरी, तिन्हा जो भूली किन्हें, अगे बखा जो बढ़दा जाऊं l","hē bhāīyō, mērī icchā yē nī hāī ki hāṁū pakaṛī cukirā; para sirpha ēka kāma karahā jō ki jō cījā pīchē rahī gaīrī, tinhā jō bhūlī kinhēṁ, agē bakhā jō baṛhadā jāūṁ l",null],[3,14,"हांऊ निशाने री तरफ दोड़ेया करहा, ताकि से इनाम पाऊं, जेसरे कठे परमेसरे मुंजो मसीह यीसू मन्झ ऊपर सादिरा l","hāṁū niśānē rī tarapha dōṛēyā karahā, tāki sē ināma pāūṁ, jēsarē kaṭhē paramēsarē muṁjō masīha yīsū manjha ūpara sādirā l",null],[3,15,"इधी कठे आस्से जितने पक्के हुई गईरे, ये सोच रखा, होर अगर केसी गल्ला मन्झ तुस्सा री लग जे सोच ई, ता परमेसरा से भी तुस्सा पर जाहिर करी देणी l","idhī kaṭhē āssē jitanē pakkē huī gaīrē, yē sōca rakhā, hōra agara kēsī gallā manjha tussā rī laga jē sōca ī, tā paramēsarā sē bhī tussā para jāhira karī dēṇī l",null],[3,16,"इधी कठे जेथी तक आस्से पूजी गईरे, तेता रे मुताबक चला l","idhī kaṭhē jēthī taka āssē pūjī gaīrē, tētā rē mutābaka calā l",null],[3,17,"हे भाईयो, तुस्से सभ मिली किन्हें मेरे साहीं चाल चला, होर तिन्हा जो पैहचाणी रखा, जो एस तरीके पर चल्हा ऐ, जेसरा उद्हारण तुस्से आस्सा मन्झ पाहें l","hē bhāīyō, tussē sabha milī kinhēṁ mērē sāhīṁ cāla calā, hōra tinhā jō paihacāṇī rakhā, jō ēsa tarīkē para calhā ai, jēsarā ud_hāraṇa tussē āssā manjha pāhēṁ l",null],[3,18,"क्यूंकि बौहत लोक एहड़ी चाल चल्हा ऐ, जिन्हा रे बारे मन्झ मैं तुस्सा जो बार-बार बोलिरा होर एबे भी रोई-रोई किन्हें बोल्हा, कि स्यों आपणे चाल चलना ले मसीह रे क्रूसा रे बैरी ऐ l","kyūṁki bauhata lōka ēhaṛī cāla calhā ai, jinhā rē bārē manjha maiṁ tussā jō bāra-bāra bōlirā hōra ēbē bhī rōī-rōī kinhēṁ bōlhā, ki syōṁ āpaṇē cāla calanā lē masīha rē krūsā rē bairī ai l",null],[3,19,"तिन्हा रा अंत विनास कारी आ, तिन्हा रा ईश्वर पेट आ, स्यों आपणी सरमा री गल्ला पर घमण्ड करहा ऐ, होर धरती री चीजा पर मन ल्गाहें l","tinhā rā aṁta vināsa kārī ā, tinhā rā īśvara pēṭa ā, syōṁ āpaṇī saramā rī gallā para ghamaṇḍa karahā ai, hōra dharatī rī cījā para mana lgāhēṁ l",null],[3,20,"पर आस्सा रा आपणा देस स्वर्गा मन्झा आ; होर तेथी ले आस्से आपणे उद्धारकर्ता प्रभु यीसू मसीह रे आऊणे रा इंतजार करेया करहा ऐ l","para āssā rā āpaṇā dēsa svargā manjhā ā; hōra tēthī lē āssē āpaṇē uddhārakartā prabhu yīsū masīha rē āūṇē rā iṁtajāra karēyā karahā ai l",null],[3,21,"से आपणी सक्ति रे तेस असरा रे मुताबक जेसरे ज्रीए से सभ चीजा जो आपणे बसा मन्झ करी सक्हा, होर तेस आस्सा रे कमजोर सरीरा जो बदली किन्हें, आपणे दिव्या सरीरा साहीं बणाई देणा l","sē āpaṇī sakti rē tēsa asarā rē mutābaka jēsarē jrīē sē sabha cījā jō āpaṇē basā manjha karī sak_hā, hōra tēsa āssā rē kamajōra sarīrā jō badalī kinhēṁ, āpaṇē divyā sarīrā sāhīṁ baṇāī dēṇā l",null],[4,1,"इधी कठे हे मेरे प्यारे भाईयो, तुस्से, जो मेरी खुसी होर मेरे ताज ऐ, तुस्सा जो देखणे रा मेरा जी करहा, हे प्यारे भाईयो, प्रभु मन्झ इसी तरहा मजबूत रहा l","idhī kaṭhē hē mērē pyārē bhāīyō, tussē, jō mērī khusī hōra mērē tāja ai, tussā jō dēkhaṇē rā mērā jī karahā, hē pyārē bhāīyō, prabhu manjha isī tarahā majabūta rahā l",null],[4,2,"हांऊ युआदिया होर संतुखे दुंहींं ले अरज करहा कि स्यों प्रभु मन्झ एक मन रहे l","hāṁū yuādiyā hōra saṁtukhē duṁhīṁṁ lē araja karahā ki syōṁ prabhu manjha ēka mana rahē l",null],[4,3,"होर हे सच्चे, सहकर्मी हांऊ तेरे ले ये अरज करहा, कि तू तिन्हा जनानिया री मदद कर, क्यूंकि तिन्हें मेरे साउगी सुसमाचार बढ़ाणे मन्झ, क्लेमेन्स होर मेरे दूजे तिन्हा सहकर्मी समेत मैहनत कीती, जिन्हा रे नांऊ जिन्दगी री क्ताबा मन्झ लिखिरे l","hōra hē saccē, sahakarmī hāṁū tērē lē yē araja karahā, ki tū tinhā janāniyā rī madada kara, kyūṁki tinhēṁ mērē sāugī susamācāra baṛhāṇē manjha, klēmēnsa hōra mērē dūjē tinhā sahakarmī samēta maihanata kītī, jinhā rē nāṁū jindagī rī ktābā manjha likhirē l",null],[4,4,"प्रभु मन्झ हमेसा खुस रहुआ; हांऊ द्बारा बोल्हा, खुस रहुआ l","prabhu manjha hamēsā khusa rahuā; hāṁū dbārā bōlhā, khusa rahuā l",null],[4,5,"तुस्सा री कोमलता सभ माहणुंआं पर प्रगट हो; प्रभु नेडे आ l","tussā rī kōmalatā sabha māhaṇuṁāṁ para pragaṭa hō; prabhu nēḍē ā l",null],[4,6,"केसी भी गल्ला री फिकर नी करा; पर हर एक गल्ला मन्झ आपणी विनती, अरज होर याचना रे ज्रीए धन्याबादा समेत परमेसरा रे साम्हणें रख्दे जाऊआ l","kēsī bhī gallā rī phikara nī karā; para hara ēka gallā manjha āpaṇī vinatī, araja hōra yācanā rē jrīē dhanyābādā samēta paramēsarā rē sāmhaṇēṁ rakhdē jāūā l",null],[4,7,"तेबे परमेसरा री सांति, जो समझा ले बाहर ई, तुस्सा रे दिल होर तुस्सा रे विचारा जो मसीह यीसू मन्झ सुरक्षित रखणी l","tēbē paramēsarā rī sāṁti, jō samajhā lē bāhara ī, tussā rē dila hōra tussā rē vicārā jō masīha yīsū manjha surakṣita rakhaṇī l",null],[4,8,"इधी कठे हे भाईयो, जो-जो गल्ला सच्ची ई, जो-जो गल्ला आदरा रे लायक, होर जो-जो गल्ला ठीक ई, होर जो-जो गल्ला पवित्र ई, होर जो-जो गल्ला सुहावनी ई, होर जो-जो गल्ला मनभावनी ई, इधी कठे, जो-जो सद्गुण होर स्तुति री गल्ला ई, तिन्हा पर ध्यान ल्गाया करा l","idhī kaṭhē hē bhāīyō, jō-jō gallā saccī ī, jō-jō gallā ādarā rē lāyaka, hōra jō-jō gallā ṭhīka ī, hōra jō-jō gallā pavitra ī, hōra jō-jō gallā suhāvanī ī, hōra jō-jō gallā manabhāvanī ī, idhī kaṭhē, jō-jō sadguṇa hōra stuti rī gallā ī, tinhā para dhyāna lgāyā karā l",null],[4,9,"जो गल्ला तुस्से मेरे ले सीखी, होर मन्नी, होर सुणी, होर मेरे मन्झ देखी, तिन्हा रा पालन करा, तेबे परमेसरा जो सांति रा सोता आ, तुस्सा साउगी रैहणां l","jō gallā tussē mērē lē sīkhī, hōra mannī, hōra suṇī, hōra mērē manjha dēkhī, tinhā rā pālana karā, tēbē paramēsarā jō sāṁti rā sōtā ā, tussā sāugī raihaṇāṁ l",null],[4,10,"हांऊ प्रभु मन्झ बौहत खुस आ, कि एबे इतने ध्याड़े ले बाद तुस्सा रा विचार मेरे बारे मन्झ द्बारा जागी गईरा; पक्का तुस्सा जो सुहरू मन्झ भी एता रा विचार था, पर तुस्सा जो मौका नी मिलेया l","hāṁū prabhu manjha bauhata khusa ā, ki ēbē itanē dhyāṛē lē bāda tussā rā vicāra mērē bārē manjha dbārā jāgī gaīrā; pakkā tussā jō suharū manjha bhī ētā rā vicāra thā, para tussā jō maukā nī milēyā l",null],[4,11,"ये हांऊ आपणी कमी घटी री वजहा ले नी बोल्या करदा; क्यूंकि मैं ये सिखिरा कि जेस हालता मन्झ हांऊ हाया, तेता मन्झ ई हांऊ संतोष करूं l","yē hāṁū āpaṇī kamī ghaṭī rī vajahā lē nī bōlyā karadā; kyūṁki maiṁ yē sikhirā ki jēsa hālatā manjha hāṁū hāyā, tētā manjha ī hāṁū saṁtōṣa karūṁ l",null],[4,12,"हांऊ कमी घटी मन्झ रैहणांं भी जाणहांं होर बढ़ती मन्झ रैहणां भी जाणहां; मैं हर एक गल्ला मन्झ होर हर दसा मन्झ रजणा होर भूखा रैहणां, होर बढ़ना घटना सीखी लईरा l","hāṁū kamī ghaṭī manjha raihaṇāṁṁ bhī jāṇahāṁṁ hōra baṛhatī manjha raihaṇāṁ bhī jāṇahāṁ; maiṁ hara ēka gallā manjha hōra hara dasā manjha rajaṇā hōra bhūkhā raihaṇāṁ, hōra baṛhanā ghaṭanā sīkhī laīrā l",null],[4,13,"जो मुंजो सक्ति देहां तेता मन्झ हांऊ सभ कुछ करी सक्हा l","jō muṁjō sakti dēhāṁ tētā manjha hāṁū sabha kucha karī sak_hā l",null],[4,14,"तेबे भी तैं भला कितेया, कि तुस्से मेरे दुःखा मन्झ मेरे भागीदार बणे l","tēbē bhī taiṁ bhalā kitēyā, ki tussē mērē duḥkhā manjha mērē bhāgīdāra baṇē l",null],[4,15,"होर हे फिलिप्पयो, तुस्से आपु भी जाणहां ऐं, कि सुसमाचारा रे सुरुआता मन्झ जेबे हांऊ मकीदुनिया ले चली गया, ता तेबे तुस्सा जो छाडी किन्हें केसी होरी मण्डलिये लैण देणा रे बारे मन्झ मेरी मदद नी किती l","hōra hē philippayō, tussē āpu bhī jāṇahāṁ aiṁ, ki susamācārā rē suruātā manjha jēbē hāṁū makīduniyā lē calī gayā, tā tēbē tussā jō chāḍī kinhēṁ kēsī hōrī maṇḍaliyē laiṇa dēṇā rē bārē manjha mērī madada nī kitī l",null],[4,16,"जेबे हांऊ थिस्सलुनिके मन्झ था, तेबे भी तुस्से मेरी जरूरत पूरी करणे रे कठे एक बार बल्कि बार-बार दान भेजे l","jēbē hāṁū thissalunikē manjha thā, tēbē bhī tussē mērī jarūrata pūrī karaṇē rē kaṭhē ēka bāra balki bāra-bāra dāna bhējē l",null],[4,17,"ये गल नी ई कि हांऊ दान चाहां, पर हांऊ एहड़ा फल चाहां, जो तुस्सा रे फायदे रे कठे बढ़दा जाए l","yē gala nī ī ki hāṁū dāna cāhāṁ, para hāṁū ēhaṛā phala cāhāṁ, jō tussā rē phāyadē rē kaṭhē baṛhadā jāē l",null],[4,18,"मेरे वाले सभ कुछ हाया, बल्कि जरूरता ले भी ज्यादा आ; जो चीजा तुस्से इपफ्रुदितुसा रे हाथा ले भेजिरी थी, तिन्हा जो पाई किन्हें हांऊ रजी गईरा, से ता मना जो मोहणे वाळी खुसबू होर ग्रैहण करणे लायक बलिदान आ, जो परमेसरा जो खरा लघ्हा l","mērē vālē sabha kucha hāyā, balki jarūratā lē bhī jyādā ā; jō cījā tussē ipaphruditusā rē hāthā lē bhējirī thī, tinhā jō pāī kinhēṁ hāṁū rajī gaīrā, sē tā manā jō mōhaṇē vāḷī khusabū hōra graihaṇa karaṇē lāyaka balidāna ā, jō paramēsarā jō kharā laghhā l",null],[4,19,"होर मेरे परमेसरा भी आपणे तेस धना रे मुताबक जो महिमा समेत मसीह यीसू मन्झ ई, तुस्सा री हर एक कमी घटी पूरी करी देणी l","hōra mērē paramēsarā bhī āpaṇē tēsa dhanā rē mutābaka jō mahimā samēta masīha yīsū manjha ī, tussā rī hara ēka kamī ghaṭī pūrī karī dēṇī l",null],[4,20,"आस्सा रे परमेसर होर पिता री जै-जै कार जुग-जुग हुन्दी रहे l आमीन l","āssā rē paramēsara hōra pitā rī jai-jai kāra juga-juga hundī rahē l āmīna l",null],[4,21,"हर एक संत जो यीसू मसीह मन्झ ऐ, नमस्कार l जो भाई मेरे साउगी ऐ, तुस्सा जो नमस्कार बोल्हा ऐ l","hara ēka saṁta jō yīsū masīha manjha ai, namaskāra l jō bhāī mērē sāugī ai, tussā jō namaskāra bōlhā ai l",null],[4,22,"सभ संत लोक, खास करी किन्हें जो कैसरा रे घराने रे ऐ, तुस्सा जो नमस्कार बोल्हा ऐ l","sabha saṁta lōka, khāsa karī kinhēṁ jō kaisarā rē gharānē rē ai, tussā jō namaskāra bōlhā ai l",null],[4,23,"आस्सा रे प्रभु यीसू मसीह री दया तुस्सा री आत्मा साउगी रहे l","āssā rē prabhu yīsū masīha rī dayā tussā rī ātmā sāugī rahē l",null]],"bfz":[[1,1,"ये चिट्ठी यीशु मसीह रे दास पौलुस और तीमुथियुसो री तरफा ते ए। आँऊ ये चिट्ठी फिलिप्पी नगरो रे रणे वाल़े परमेशरो रे सारे पवित्र लोक, अध्यक्ष और सेवका खे लिखणे लगी रा जो यीशु मसीह रे ए।","yē ciṭṭhī yīśu masīha rē dāsa paulusa aura tīmuthiyusō rī taraphā tē ē. ām̐ū yē ciṭṭhī philippī nagarō rē raṇē vāl̈ē paramēśarō rē sārē pavitra lōka, adhyakṣa aura sēvakā khē likhaṇē lagī rā jō yīśu masīha rē ē.",null],[1,2,"म्हारे पिता परमेशर और प्रभु यीशु मसीह री तरफा ते तुसा खे कृपा और शान्ति मिलदी रओ।","mhārē pitā paramēśara aura prabhu yīśu masīha rī taraphā tē tusā khē kr̥pā aura śānti miladī raō.",null],[1,3,"आऊँ जेबे-जेबे तुसा खे याद करूँआ, तेबे-तेबे आपणे परमेशरो रा धन्यवाद करूँआ।","āūm̐ jēbē-jēbē tusā khē yāda karūm̐ā, tēbē-tēbē āpaṇē paramēśarō rā dhanyavāda karūm̐ā.",null],[1,4,"और जेबे कदी तुसा सबी खे प्रार्थना करूँआ, तो सदा खुशिया साथे बिनती करूँआ।","aura jēbē kadī tusā sabī khē prārthanā karūm̐ā, tō sadā khuśiyā sāthē binatī karūm̐ā.",null],[1,5,"कऊँकि तुसे पईले दिनो ते लयी कि आजो तक प्रभु यीशुए रे सुसमाचारो खे फैलाणे खे मेरे सहभागी रई रे।","kaūm̐ki tusē paīlē dinō tē layī ki ājō taka prabhu yīśuē rē susamācārō khē phailāṇē khē mērē sahabhāgī raī rē.",null],[1,6,"और माखे एते गल्ला रा विश्वास ए कि परमेशरे जिने तुसा रे खरा काम शुरू करी राखेया, तेस ई से काम जेबे यीशु मसीह फेर वापस आऊणा तेस दिनो तक पूरा करना।","aura mākhē ētē gallā rā viśvāsa ē ki paramēśarē jinē tusā rē kharā kāma śurū karī rākhēyā, tēsa ī sē kāma jēbē yīśu masīha phēra vāpasa āūṇā tēsa dinō taka pūrā karanā.",null],[1,7,"ये खरा ए कि आऊँ तुसा सबी खे एड़ा ई बिचार करुँ, कऊँकि आऊँ तुसा ते बऊत प्यार करूँआ और जेबे आँऊ जेला रे ए और सुसमाचारो री रक्षा खे और इजी खे सच साबित करने रे तुसे सब मां साथे कृपा रे शामिल ए।","yē kharā ē ki āūm̐ tusā sabī khē ēṛā ī bicāra karum̐, kaūm̐ki āūm̐ tusā tē baūta pyāra karūm̐ā aura jēbē ām̐ū jēlā rē ē aura susamācārō rī rakṣā khē aura ijī khē saca sābita karanē rē tusē saba māṁ sāthē kr̥pā rē śāmila ē.",null],[1,8,"इदे परमेशर मेरा गवा ए कि जिंयाँ यीशु मसीह तुसा ते प्यार करोआ सच्ची आँऊ बी तिंयाँ ई तिना जेड़ा तुसा सबी ते प्यार करूँआ।","idē paramēśara mērā gavā ē ki jiṁyām̐ yīśu masīha tusā tē pyāra karōā saccī ām̐ū bī tiṁyām̐ ī tinā jēṛā tusā sabī tē pyāra karūm̐ā.",null],[1,9,"और आऊँ ये प्रार्थना करूँआ कि तुसा रा एकी दूजे ते प्यार, ज्ञान और पूरिया समजा साथे ओर बी बड़दा जाओ।","aura āūm̐ yē prārthanā karūm̐ā ki tusā rā ēkī dūjē tē pyāra, jñāna aura pūriyā samajā sāthē ōra bī baṛadā jāō.",null],[1,10,"तेबेई तुसे इना गल्ला खे परखणे रे जोगे ऊई जाओ कि कुण जी गल्ल करने खे खरी ए और मसीह रे फेर वापस आऊणे रे दिनो तक पवित्र और निष्कलंक बणे रे रओ।","tēbēī tusē inā gallā khē parakhaṇē rē jōgē ūī jāō ki kuṇa jī galla karanē khē kharī ē aura masīha rē phēra vāpasa āūṇē rē dinō taka pavitra aura niṣkalaṁka baṇē rē raō.",null],[1,11,"और यीशु मसीह रे जरिए पैदा ऊणे वाल़े धार्मिकता रे कामा ते आपू खे परी लओ, जेते कि परमेशरो री महिमा और स्तुति ऊँदी रओ।","aura yīśu masīha rē jariē paidā ūṇē vāl̈ē dhārmikatā rē kāmā tē āpū khē parī laō, jētē ki paramēśarō rī mahimā aura stuti ūm̐dī raō.",null],[1,12,"ओ प्यारे साथी विश्वासियो! आऊँ चाऊँआ कि तुसे ये जाणी लो कि मां पाँदे जो बीती रा, तिजी री बजअ ते बऊत सारे लोके सुसमाचारो पाँदे विश्वास कित्तेया।","ō pyārē sāthī viśvāsiyō! āūm̐ cāūm̐ā ki tusē yē jāṇī lō ki māṁ pām̐dē jō bītī rā, tijī rī bajaa tē baūta sārē lōkē susamācārō pām̐dē viśvāsa kittēyā.",null],[1,13,"एथो तक कि कैसर राजे रे राज्य री सारी पल़टण और बाकि बचे रे सारे लोका सामणे ये आईगा रा कि आऊँ मसीह री खातर जेला रे कैद ए।","ēthō taka ki kaisara rājē rē rājya rī sārī pal̈aṭaṇa aura bāki bacē rē sārē lōkā sāmaṇē yē āīgā rā ki āūm̐ masīha rī khātara jēlā rē kaida ē.",null],[1,14,"और प्रभुए रे जो पाई ए, तिना बीचा ते बऊत जणे मेरे जेला रे कैद ऊणे री बजअ ते, मजबूत विश्वासो साथे, परमेशरो रा वचन नशंग सुनाणे री ओर बी इम्मत करोए।","aura prabhuē rē jō pāī ē, tinā bīcā tē baūta jaṇē mērē jēlā rē kaida ūṇē rī bajaa tē, majabūta viśvāsō sāthē, paramēśarō rā vacana naśaṁga sunāṇē rī ōra bī immata karōē.",null],[1,15,"ये सच ये कि कुछ लोक जल़न और चगड़े री बजअ ते मसीह रे सुसमाचारो रा प्रचार करोए और कुछ खरे इरादे ते।","yē saca yē ki kucha lōka jal̈ana aura cagaṛē rī bajaa tē masīha rē susamācārō rā pracāra karōē aura kucha kharē irādē tē.",null],[1,16,"ये एड़े लोक जो मसीह रे सुसमाचारो रा प्रचार अच्छे इरादे और प्यारो ते करोए। सेयो जाणोए कि आँऊ यीशु मसीह रे सुसमाचारो रा जबाब देणे खे जेला रे कैद ए","yē ēṛē lōka jō masīha rē susamācārō rā pracāra acchē irādē aura pyārō tē karōē. sēyō jāṇōē ki ām̐ū yīśu masīha rē susamācārō rā jabāba dēṇē khē jēlā rē kaida ē",null],[1,17,"पर ये चगड़ा करने वाल़े लोक जो सच्चाईया ते नि पर आपणे मतलबो खे मसीह रा सुसमाचार सुणाओए, ये सोचोए की कि जेबे आँऊ जेला रे कैद ए, माखे ओर जादा क्ल़ेश पैदा करो।","para yē cagaṛā karanē vāl̈ē lōka jō saccāīyā tē ni para āpaṇē matalabō khē masīha rā susamācāra suṇāōē, yē sōcōē kī ki jēbē ām̐ū jēlā rē kaida ē, mākhē ōra jādā kl̈ēśa paidā karō.",null],[1,18,"तो क्या ऊआ? बस ये कि हर किंयाँ चाए बुरिया बजअ ते, चाए सच्चाईया ते मसीह रा सुसमाचार सुणाया जाओआ। आऊँ इजी ते खुश ए और खुश ऊँदा रणा बी।","tō kyā ūā? basa yē ki hara kiṁyām̐ cāē buriyā bajaa tē, cāē saccāīyā tē masīha rā susamācāra suṇāyā jāōā. āūm̐ ijī tē khuśa ē aura khuśa ūm̐dā raṇā bī.",null],[1,19,"कऊँकि आऊँ जाणूंआ कि तुसा री प्रार्थना रे जरिए और यीशु मसीह री तरफा ते पेजी री पवित्र आत्मा री मतादा रे जरिए, इजी रा ईनाम, माखे अच्छा ई ऊणा।","kaūm̐ki āūm̐ jāṇūṁā ki tusā rī prārthanā rē jariē aura yīśu masīha rī taraphā tē pējī rī pavitra ātmā rī matādā rē jariē, ijī rā īnāma, mākhē acchā ī ūṇā.",null],[1,20,"आऊँ तो दिलो ते येई इच्छा और उम्मीद राखूँआ कि आऊँ किजी बी गल्ला रे शर्मिंदा नि ओऊँ, पर जेड़ी मेरी बड़ी इम्मता री बजअ ते, मसीह री तारीफ मेरे शरीरो रे जरिए सदा ऊँदी रओई, तेड़ा ई एबे बी ओ, चाए आऊँ जिऊँदा रऊँ या मरी जाऊँ।","āūm̐ tō dilō tē yēī icchā aura ummīda rākhūm̐ā ki āūm̐ kijī bī gallā rē śarmiṁdā ni ōūm̐, para jēṛī mērī baṛī immatā rī bajaa tē, masīha rī tārīpha mērē śarīrō rē jariē sadā ūm̐dī raōī, tēṛā ī ēbē bī ō, cāē āūm̐ jiūm̐dā raūm̐ yā marī jāūm̐.",null],[1,21,"कऊँकि जे आँऊ जिऊँ तो सिर्फ मसीह री खातर, और जेबे आँऊ मरूँ तो से माखे बऊत ई अच्छा ऊणा कऊँकि आँऊ मरने ते बाद बी मसीह साथे रणा।","kaūm̐ki jē ām̐ū jiūm̐ tō sirpha masīha rī khātara, aura jēbē ām̐ū marūm̐ tō sē mākhē baūta ī acchā ūṇā kaūm̐ki ām̐ū maranē tē bāda bī masīha sāthē raṇā.",null],[1,22,"पर जे शरीरो रे जिऊँदा रणा ई मेरे कामो खे फायदेमंद ए, तो आऊँ नि जाणदा कि केसखे चुणुँ?","para jē śarīrō rē jiūm̐dā raṇā ī mērē kāmō khē phāyadēmaṁda ē, tō āūm̐ ni jāṇadā ki kēsakhē cuṇum̐?",null],[1,23,"कऊँकि इना दुँईं बीचा ते केसी एकी खे चुणना माखे बऊत ई कठण ए। जिऊ तो चाओआ कि मरी की मसीह गे जाई की रऊँ, कऊँकि ये माखे बऊत ई अच्छा ए।","kaūm̐ki inā dum̐īṁ bīcā tē kēsī ēkī khē cuṇanā mākhē baūta ī kaṭhaṇa ē. jiū tō cāōā ki marī kī masīha gē jāī kī raūm̐, kaūm̐ki yē mākhē baūta ī acchā ē.",null],[1,24,"पर शरीरो रे रणा ओर बी जरूरी ए कऊँकि तुसा खे मेरी मतादा री जरूरत ए।","para śarīrō rē raṇā ōra bī jarūrī ē kaūm̐ki tusā khē mērī matādā rī jarūrata ē.",null],[1,25,"इजी खे कि माखे इजी रा विश्वास (भरोसा) ए कि आऊँ जिऊँदा रणा, बल्कि तुसा सबी साथे रणा, जेते की आँऊ तुसा खे विश्वासो रे मजबूत करने और तिदे खुश रणे रे तुसा री मताद करूँगा।","ijī khē ki mākhē ijī rā viśvāsa (bharōsā) ē ki āūm̐ jiūm̐dā raṇā, balki tusā sabī sāthē raṇā, jētē kī ām̐ū tusā khē viśvāsō rē majabūta karanē aura tidē khuśa raṇē rē tusā rī matāda karūm̐gā.",null],[1,26,"जो कमण्ड तुसे मेरे बारे रे करोए, से मेरा तुसा गे जेला ते फेर वापस आऊणे ते, यीशु मसीह रे ओर जादा बड़ी जाओ।","jō kamaṇḍa tusē mērē bārē rē karōē, sē mērā tusā gē jēlā tē phēra vāpasa āūṇē tē, yīśu masīha rē ōra jādā baṛī jāō.",null],[1,27,"बस इतणा करो कि तुसा रा चाल-चलण मसीह रे सुसमाचारो जोगा ओ, तेबे चाए आऊँ आईकि तुसा खे देखूँ, चाए ना बी आऊँ, बस तुसा रे बारे रे ये सुणूँ कि तुसे एक ई इरादे रे मजबूत रओ और एक मन ऊई कि सुसमाचारो रे विश्वासो खे मईणत करदे रओए।","basa itaṇā karō ki tusā rā cāla-calaṇa masīha rē susamācārō jōgā ō, tēbē cāē āūm̐ āīki tusā khē dēkhūm̐, cāē nā bī āūm̐, basa tusā rē bārē rē yē suṇūm̐ ki tusē ēka ī irādē rē majabūta raō aura ēka mana ūī ki susamācārō rē viśvāsō khē maīṇata karadē raōē.",null],[1,28,"केसी बी गल्ला रे बिरोदिया ते डरदे नि, तुसा री इम्मत तिना खे नाशो रा साफ चिह्न् ए, पर तुसा खे उद्धारो रा और ये परमेशरो री तरफा ते ए।","kēsī bī gallā rē birōdiyā tē ḍaradē ni, tusā rī immata tinā khē nāśō rā sāpha cihn ē, para tusā khē uddhārō rā aura yē paramēśarō rī taraphā tē ē.",null],[1,29,"कऊँकि मसीह री बजअ ते तुसा पाँदे ये कृपा ऊई कि ना बस तेस पाँदे ई विश्वास करो, पर तेसरिया तंईं दु:ख बी सईन करो,","kaūm̐ki masīha rī bajaa tē tusā pām̐dē yē kr̥pā ūī ki nā basa tēsa pām̐dē ī viśvāsa karō, para tēsariyā taṁīṁ du:kha bī saīna karō,",null],[1,30,"और तुसा खे तेड़ा ई दुःख सईन करना ए, जेड़ा तुसे आऊँ सईन करदे देखी राखेया, जेबे आँऊ तुसा साथे फिलिप्पी नगरो रे था और एबे बी सुणोए कि दुःख सईन करूँआ।","aura tusā khē tēṛā ī duḥkha saīna karanā ē, jēṛā tusē āūm̐ saīna karadē dēkhī rākhēyā, jēbē ām̐ū tusā sāthē philippī nagarō rē thā aura ēbē bī suṇōē ki duḥkha saīna karūm̐ā.",null],[2,1,"तेबेई जे तुसा लोका बीचे मसीह रे कुछ बी औंसला, प्यारो रे जरिए पैदा इम्मत, आत्मा री सहभागिता और कुछ करूणा और दया ए,","tēbēī jē tusā lōkā bīcē masīha rē kucha bī auṁsalā, pyārō rē jariē paidā immata, ātmā rī sahabhāgitā aura kucha karūṇā aura dayā ē,",null],[2,2,"तो मेरी ये खुशी पूरी करो कि एकी दूजे ते सहमत रओ और एक जेड़ा प्यार राखो, एकी दूजे ते मेलजोल राखो और एक ई इच्छा राखो।","tō mērī yē khuśī pūrī karō ki ēkī dūjē tē sahamata raō aura ēka jēṛā pyāra rākhō, ēkī dūjē tē mēlajōla rākhō aura ēka ī icchā rākhō.",null],[2,3,"आपणे फाईदे या कमण्डो ते कुछ नि करो, पर दीनता ते एकी-दूजे रा आपू ते जादा त्यान राखो।","āpaṇē phāīdē yā kamaṇḍō tē kucha ni karō, para dīnatā tē ēkī-dūjē rā āpū tē jādā tyāna rākhō.",null],[2,4,"हर एक आपणे ई पलाईया री नि, बल्कि दूजे री पलाईया री बी चिन्ता करेया करो।","hara ēka āpaṇē ī palāīyā rī ni, balki dūjē rī palāīyā rī bī cintā karēyā karō.",null],[2,5,"जेड़ा यीशु मसीह रा सबाओ था, तिंयाँ ई तुसा रा सबाओ बी एकी-दूजे साथे ऊणा चाइयो।","jēṛā yīśu masīha rā sabāō thā, tiṁyām̐ ī tusā rā sabāō bī ēkī-dūjē sāthē ūṇā cāiyō.",null],[2,6,"हालाँकि मसीह सच्ची परमेशर था तेबे बी तिने लोक एसा गल्ला खे मजबूर नि कित्ते कि सेयो तेस साथे परमेशरो जेड़ा बर्ताव करो,","hālām̐ki masīha saccī paramēśara thā tēbē bī tinē lōka ēsā gallā khē majabūra ni kittē ki sēyō tēsa sāthē paramēśarō jēṛā bartāva karō,",null],[2,7,"बल्कि आपणे आपू खे एड़ा शून्य करी ता और दासो जेड़ा बणीगा और मांणूए जेड़ा ऊईगा।","balki āpaṇē āpū khē ēṛā śūnya karī tā aura dāsō jēṛā baṇīgā aura māṁṇūē jēṛā ūīgā.",null],[2,8,"और मांणूए रे रूपो रे आयी की आपू खे दीन कित्तेया और से आपणी मौता तक आज्ञाकारी रया, एथो तक कि तिने क्रूसो पाँदे दर्दनाक मौत बी सईन करी ली।","aura māṁṇūē rē rūpō rē āyī kī āpū khē dīna kittēyā aura sē āpaṇī mautā taka ājñākārī rayā, ēthō taka ki tinē krūsō pām̐dē dardanāka mauta bī saīna karī lī.",null],[2,9,"इजी बजअ ते परमेशरे तेसखे सबी ते ऊच्ची पदवी दित्ती और तेसखे से नाओं दित्तेया, जो सबी नाओं ते बड़ा ए।","ijī bajaa tē paramēśarē tēsakhē sabī tē ūccī padavī dittī aura tēsakhē sē nāōṁ dittēyā, jō sabī nāōṁ tē baṛā ē.",null],[2,10,"ताकि जो स्वर्गो रे ए और तरतिया रे ए और तरतिया ते थाले ए, सेयो सारे यीशुए रे नाओं खे तेसखे आदर देणे खे जानूआ रे पाअरे बैठो।","tāki jō svargō rē ē aura taratiyā rē ē aura taratiyā tē thālē ē, sēyō sārē yīśuē rē nāōṁ khē tēsakhē ādara dēṇē khē jānūā rē pāarē baiṭhō.",null],[2,11,"और पिता परमेशरो री महिमा खे हर माणूं आपणे मुंए ये मानी लओ कि यीशु मसीह ई प्रभु ए।","aura pitā paramēśarō rī mahimā khē hara māṇūṁ āpaṇē muṁē yē mānī laō ki yīśu masīha ī prabhu ē.",null],[2,12,"तो ओ प्यारे साथी विश्वासियो! जिंयाँ तुसे सदा ते आज्ञा मानदे आयी रे, तिंयाँ ई एबे बी, ना बस मां साथे रंदे ऊए, पर खास करी की एबे मेरे दूर रंदे ऊए बी डरदे और थरथरांदे ऊए लगातार अच्छे काम करो जो तुसा रे उद्धारो ते आओए।","tō ō pyārē sāthī viśvāsiyō! jiṁyām̐ tusē sadā tē ājñā mānadē āyī rē, tiṁyām̐ ī ēbē bī, nā basa māṁ sāthē raṁdē ūē, para khāsa karī kī ēbē mērē dūra raṁdē ūē bī ḍaradē aura tharatharāṁdē ūē lagātāra acchē kāma karō jō tusā rē uddhārō tē āōē.",null],[2,13,"कऊँकि ये परमेशर ईए, जो आपणी पवित्र आत्मा रे जरिए तुसा रे मनो रे तेसरी खरी इच्छा और खरे काम करने री इम्मत देओआ।","kaūm̐ki yē paramēśara īē, jō āpaṇī pavitra ātmā rē jariē tusā rē manō rē tēsarī kharī icchā aura kharē kāma karanē rī immata dēōā.",null],[2,14,"सारे काम बिना कुड़कुड़ाए और बिना बईसा ते करेया करो।","sārē kāma binā kuṛakuṛāē aura binā baīsā tē karēyā karō.",null],[2,15,"ताकि तुसे निर्दोष और पोल़े ऊई की टेडे और टीठ लोका बीचे परमेशरो री निष्कलंक ल्वाद बणे रे रओ, जिना बीचे तुसे जीवनो रा वचन लयी की दुनिया रे सर्गो रे चमकीले तारेया जेड़े दिशोए।","tāki tusē nirdōṣa aura pōl̈ē ūī kī ṭēḍē aura ṭīṭha lōkā bīcē paramēśarō rī niṣkalaṁka lvāda baṇē rē raō, jinā bīcē tusē jīvanō rā vacana layī kī duniyā rē sargō rē camakīlē tārēyā jēṛē diśōē.",null],[2,16,"ताकि मसीह रे वापस आऊणे रे दिने माखे कमण्ड करने री बजअ ओ कि ना मेरी दौड़-तूप और ना ई मेरी कड़ी मईणत करना बेकार ऊआ।","tāki masīha rē vāpasa āūṇē rē dinē mākhē kamaṇḍa karanē rī bajaa ō ki nā mērī dauṛa-tūpa aura nā ī mērī kaṛī maīṇata karanā bēkāra ūā.",null],[2,17,"तुसा रा मसीह रे विश्वास और तुसा री सेवा परमेशरो खे चढ़ाई री बल़िया जेड़े ए। जे सेयो माखे मारी बी देओ तेबे बी आऊँ खुश ए और तुसा सबी साथे खुशी मनाऊँआ।","tusā rā masīha rē viśvāsa aura tusā rī sēvā paramēśarō khē caṛhāī rī bal̈iyā jēṛē ē. jē sēyō mākhē mārī bī dēō tēbē bī āūm̐ khuśa ē aura tusā sabī sāthē khuśī manāūm̐ā.",null],[2,18,"तिंयाँ ईं तुसे बी खुश ओ और मां साथे खुशी मनाओ।","tiṁyām̐ īṁ tusē bī khuśa ō aura māṁ sāthē khuśī manāō.",null],[2,19,"माखे प्रभु यीशुए रे उम्मीद ए कि मां तीमुथियुस तुसा गे चट ई पेजणा ताकि तुसा रा आल सुणी की मेरा औंसला बड़ो।","mākhē prabhu yīśuē rē ummīda ē ki māṁ tīmuthiyusa tusā gē caṭa ī pējaṇā tāki tusā rā āla suṇī kī mērā auṁsalā baṛō.",null],[2,20,"कऊँकि मांगे एड़े सबाओ रा कोई निए जो साफ मनो ते तुसा री चिन्ता करो।","kaūm̐ki māṁgē ēṛē sabāō rā kōī niē jō sāpha manō tē tusā rī cintā karō.",null],[2,21,"कऊँकि सब आपणे स्वार्थ निकाल़ने री खोजा रे रओए, ना कि यीशु मसीह री।","kaūm̐ki saba āpaṇē svārtha nikāl̈anē rī khōjā rē raōē, nā ki yīśu masīha rī.",null],[2,22,"पर तुसे तो तीमुथियुसो री योग्यता खे जाणोए कि जेड़ा पाऊ पिते साथे करोआ, तेड़ा ई तिने एस सुसमाचारो खे फैलाणे दे, मां साथे कड़ी मईणत कित्ती।","para tusē tō tīmuthiyusō rī yōgyatā khē jāṇōē ki jēṛā pāū pitē sāthē karōā, tēṛā ī tinē ēsa susamācārō khē phailāṇē dē, māṁ sāthē kaṛī maīṇata kittī.",null],[2,23,"तो माखे उम्मीद ए कि जिंयाँ ई माखे पता लगणा कि मेरी क्या दशा ऊणी, तिंयाँ ई मां से फटाफट पेजी देणा।","tō mākhē ummīda ē ki jiṁyām̐ ī mākhē patā lagaṇā ki mērī kyā daśā ūṇī, tiṁyām̐ ī māṁ sē phaṭāphaṭa pējī dēṇā.",null],[2,24,"और माखे प्रभुए पाँदे विश्वास ए कि मां आपू बी चट आऊणा।","aura mākhē prabhuē pām̐dē viśvāsa ē ki māṁ āpū bī caṭa āūṇā.",null],[2,25,"पर मैं इपफ्रुदीतुसो खे तुसा गे वापस पेजणा जरूरी समजेया। ये मेरा पाई और मेरा सहकर्मी और मां साथे संगी सिपाई और तुसा रा संदेश पऊँछाणे वाल़ा और जरूरी गल्ला रे मेरी सेवा करने वाल़ा ए।","para maiṁ ipaphrudītusō khē tusā gē vāpasa pējaṇā jarūrī samajēyā. yē mērā pāī aura mērā sahakarmī aura māṁ sāthē saṁgī sipāī aura tusā rā saṁdēśa paūm̐chāṇē vāl̈ā aura jarūrī gallā rē mērī sēvā karanē vāl̈ā ē.",null],[2,26,"कऊँकि तेसरा मन तुसा सबी रे लगी रा था, और से बेचैन रओ था, कऊँकि तुसे तेसरी बमारिया रा आल सुणेया था।","kaūm̐ki tēsarā mana tusā sabī rē lagī rā thā, aura sē bēcaina raō thā, kaūm̐ki tusē tēsarī bamāriyā rā āla suṇēyā thā.",null],[2,27,"पक्का से तो बमार ऊईगा था, एथो तक कि मरने वाल़ा था। पर परमेशरे तेस पाँदे दया कित्ती और बस तेस ई पाँदे नि, पर मां पाँदे बी कित्ती ताकि माखे दु:खो पाँदे दु:ख नि ओ।","pakkā sē tō bamāra ūīgā thā, ēthō taka ki maranē vāl̈ā thā. para paramēśarē tēsa pām̐dē dayā kittī aura basa tēsa ī pām̐dē ni, para māṁ pām̐dē bī kittī tāki mākhē du:khō pām̐dē du:kha ni ō.",null],[2,28,"इजी री खातर मैं तेसखे पेजणे री ओर बी कोशिश कित्ती ताकि तुसे तेस साथे फेर प्रभुए रे मिली कि खुश ऊई जाओ और मेरी चिन्ता बी कम ऊई जाओ।","ijī rī khātara maiṁ tēsakhē pējaṇē rī ōra bī kōśiśa kittī tāki tusē tēsa sāthē phēra prabhuē rē milī ki khuśa ūī jāō aura mērī cintā bī kama ūī jāō.",null],[2,29,"इजी री खातर तुसे प्रभुए रे, तेस साथे बऊत खुशिया ते मिलेओ और एड़ेया री आओ-बैठ करेया करनी।","ijī rī khātara tusē prabhuē rē, tēsa sāthē baūta khuśiyā tē milēō aura ēṛēyā rī āō-baiṭha karēyā karanī.",null],[2,30,"कऊँकि सेई मसीह रे कामो खे आपणे प्राणो खे मुसीबता रे पाई की मरने जोगा ऊईगा था, ताकि जो कमी तुसा री तरफा ते मेरी सेवा रे ऊई, तिजी खे पूरी करो।","kaūm̐ki sēī masīha rē kāmō khē āpaṇē prāṇō khē musībatā rē pāī kī maranē jōgā ūīgā thā, tāki jō kamī tusā rī taraphā tē mērī sēvā rē ūī, tijī khē pūrī karō.",null],[3,1,"इजी री खातर ओ प्यारे साथी विश्वासियो, प्रभुए रे खुश रओ! सेयो ई गल्ला बार-बार लिखणे रे माखे कोई कष्ट नि ऊँदा पर ये गल्ला तुसा खे चूठिया शिक्षा ते बचाओईया।","ijī rī khātara ō pyārē sāthī viśvāsiyō, prabhuē rē khuśa raō! sēyō ī gallā bāra-bāra likhaṇē rē mākhē kōī kaṣṭa ni ūm̐dā para yē gallā tusā khē cūṭhiyā śikṣā tē bacāōīyā.",null],[3,2,"तिना लोका ते चौकस रओ जो तुसा खे जंगल़ी कुत्तेया जेड़े खतरनाक ए, बुरा काम करने वाल़े ए और ये बोलोए कि उद्धार पाणे खे खतना जरूरी ए।","tinā lōkā tē caukasa raō jō tusā khē jaṁgal̈ī kuttēyā jēṛē khataranāka ē, burā kāma karanē vāl̈ē ē aura yē bōlōē ki uddhāra pāṇē khē khatanā jarūrī ē.",null],[3,3,"कऊँकि परमेशरो रे सच्चे लोक आसे ईए। जो परमेशरो री पवित्र आत्मा री अगुवाईया ते भक्ति करोए और मसीह यीशुए रे कमण्ड करोए और शरीरो रे कामा पाँदे परोसा नि राखदे।","kaūm̐ki paramēśarō rē saccē lōka āsē īē. jō paramēśarō rī pavitra ātmā rī aguvāīyā tē bhakti karōē aura masīha yīśuē rē kamaṇḍa karōē aura śarīrō rē kāmā pām̐dē parōsā ni rākhadē.",null],[3,4,"जे केसी ओरी खे शरीरो रे कामा पाँदे परोसा राखी की त्वाल़िया देणे रा बिचार ओ, तो जे आँऊ चाऊँ तो शरीरो रे कामा पाँदे बी परोसा राखी की आँऊ बी तिना ते जादा त्वाल़िया देई सकूँआ।","jē kēsī ōrī khē śarīrō rē kāmā pām̐dē parōsā rākhī kī tvāl̈iyā dēṇē rā bicāra ō, tō jē ām̐ū cāūm̐ tō śarīrō rē kāmā pām̐dē bī parōsā rākhī kī ām̐ū bī tinā tē jādā tvāl̈iyā dēī sakūm̐ā.",null],[3,5,"जिंयाँ परमेशरे आज्ञा दित्ती तिंयाँ ई आठुए दिने मेरा खतना ऊआ, आऊँ इस्राएलो रे वंशो रा और बिन्यामीनो रे गोत्रो राए; आँऊ पक्का इब्रानी ए और मेरे बुजुर्ग बी पक्के इब्रानी थे। मूसे रे बिधानो खे मानणे रे बारे रे जे बोलो तो आँऊ फरीसी ए।","jiṁyām̐ paramēśarē ājñā dittī tiṁyām̐ ī āṭhuē dinē mērā khatanā ūā, āūm̐ isrāēlō rē vaṁśō rā aura binyāmīnō rē gōtrō rāē; ām̐ū pakkā ibrānī ē aura mērē bujurga bī pakkē ibrānī thē. mūsē rē bidhānō khē mānaṇē rē bārē rē jē bōlō tō ām̐ū pharīsī ē.",null],[3,6,"इम्मता रे बारे रे जे बोलो तो, मण्डल़िया खे सताणे वाल़ा और यहूदी बिधानो खे मानणे रे बारे रे जे कोई बोलो तो, आँऊ तर्मी माणूं था। कऊँकि मैं तेसा बिधानो खे मानणे रा पालन कित्तेया।","immatā rē bārē rē jē bōlō tō, maṇḍal̈iyā khē satāṇē vāl̈ā aura yahūdī bidhānō khē mānaṇē rē bārē rē jē kōī bōlō tō, ām̐ū tarmī māṇūṁ thā. kaūm̐ki maiṁ tēsā bidhānō khē mānaṇē rā pālana kittēyā.",null],[3,7,"पर जो-जो गल्ला मैं सोचिया कि सेयो मेरे लाबो री थिया, एबे सेई मैं मसीह खे ओर बी जादा जाणने खे बेकार समजी लईया।","para jō-jō gallā maiṁ sōciyā ki sēyō mērē lābō rī thiyā, ēbē sēī maiṁ masīha khē ōra bī jādā jāṇanē khē bēkāra samajī laīyā.",null],[3,8,"इजी ते बी जादा बढ़ी की आँऊ आपणे प्रभु यीशु मसीह खे जाणने री जरूरता रे सामणे सारी गल्ला खे बेकार समजूँआ, जेतेरी बजअ ते मैं सारी चीजा रा नुकशाण उठाया और तिना खे कूड़ा समजूँआ; जेते कि आऊँ मसीह खे जाणी सकूँ।","ijī tē bī jādā baṛhī kī ām̐ū āpaṇē prabhu yīśu masīha khē jāṇanē rī jarūratā rē sāmaṇē sārī gallā khē bēkāra samajūm̐ā, jētērī bajaa tē maiṁ sārī cījā rā nukaśāṇa uṭhāyā aura tinā khē kūṛā samajūm̐ā; jētē ki āūm̐ masīha khē jāṇī sakūm̐.",null],[3,9,"ताकि आँऊ तेस साथे एकता रे जी सकूँ, ना कि आपणी तेसा धार्मिकता साथे, जो मूसे रा बिधानो ते ए, बल्कि तेसा धार्मिकता साथे, जो मसीह पाँदे विश्वास करने री बजअ ते ए और परमेशरो री तरफा ते विश्वास करने ते माखे मिलोई।","tāki ām̐ū tēsa sāthē ēkatā rē jī sakūm̐, nā ki āpaṇī tēsā dhārmikatā sāthē, jō mūsē rā bidhānō tē ē, balki tēsā dhārmikatā sāthē, jō masīha pām̐dē viśvāsa karanē rī bajaa tē ē aura paramēśarō rī taraphā tē viśvāsa karanē tē mākhē milōī.",null],[3,10,"आऊँ ये चाऊँआ कि मसीह खे जाणी लऊँ। तेसरे फेर जिऊँदे ऊणे री सामर्था खे महसूस करूँ, और तिना साथे दु:खो रे सहभागी ऊई की मौता रे तिना जेड़ा बणी जाऊँ।","āūm̐ yē cāūm̐ā ki masīha khē jāṇī laūm̐. tēsarē phēra jiūm̐dē ūṇē rī sāmarthā khē mahasūsa karūm̐, aura tinā sāthē du:khō rē sahabhāgī ūī kī mautā rē tinā jēṛā baṇī jāūm̐.",null],[3,11,"ताकि आऊँ किंयाँ बी मरे ऊए रे बीचा ते फेर जिऊँदे ऊणे रे पदो तक पऊँछी सकूँ।","tāki āūm̐ kiṁyām̐ bī marē ūē rē bīcā tē phēra jiūm̐dē ūṇē rē padō taka paūm̐chī sakūm̐.",null],[3,12,"ये मतलब नि कि आऊँ इना सबी चीजा खे पईले तेई पायी चुकी रा या सिद्ध ऊई चुकी रा। पर आँऊ तेसा चीजा खे पाणे री खातर दौड़ी की आगे बढ़दा चली जाणे लगी रा कि आँऊ सिद्ध ऊई जाऊँ। जेतेखे यीशु मसीहे आऊँ चुणेया था।","yē matalaba ni ki āūm̐ inā sabī cījā khē paīlē tēī pāyī cukī rā yā siddha ūī cukī rā. para ām̐ū tēsā cījā khē pāṇē rī khātara dauṛī kī āgē baṛhadā calī jāṇē lagī rā ki ām̐ū siddha ūī jāūm̐. jētēkhē yīśu masīhē āūm̐ cuṇēyā thā.",null],[3,13,"ओ साथी विश्वासियो! मेरा मानणा ये निए कि आऊँ तिजी खे पायी चुकी रा। पर बस ये एक काम करूँआ कि जो गल्ला बीती चुकी रिया, तिना खे पूली की आगे री तरफा खे बड़दा जाऊँआ।","ō sāthī viśvāsiyō! mērā mānaṇā yē niē ki āūm̐ tijī khē pāyī cukī rā. para basa yē ēka kāma karūm̐ā ki jō gallā bītī cukī riyā, tinā khē pūlī kī āgē rī taraphā khē baṛadā jāūm̐ā.",null],[3,14,"आँऊ नशाणे री तरफा खे दौड़दा जाऊँआ, ताकि आँऊ स्वर्गो रे बुलाए जाणे रा ईनाम पाई सकूँ। जेतेरी खातर परमेशरे आऊँ यीशु मसीह रे जरिए स्वर्गो दे बुलाई राखेया।","ām̐ū naśāṇē rī taraphā khē dauṛadā jāūm̐ā, tāki ām̐ū svargō rē bulāē jāṇē rā īnāma pāī sakūm̐. jētērī khātara paramēśarē āūm̐ yīśu masīha rē jariē svargō dē bulāī rākhēyā.",null],[3,15,"तो आसा बीचा ते जितणे विश्वासो रे मजबूत ए, येई सोच राखो और जे केसी गल्ला रे तुसा री ओर ई सोच ओ, तो, परमेशरे तुसा खे से बी बताई देणा।","tō āsā bīcā tē jitaṇē viśvāsō rē majabūta ē, yēī sōca rākhō aura jē kēsī gallā rē tusā rī ōra ī sōca ō, tō, paramēśarē tusā khē sē bī batāī dēṇā.",null],[3,16,"तेबेई आसा खे तेसा सच्चाईया रे मुताबिक चलणा चाईयो जो परमेशरे आसा खे पईले तेई देई राखी।","tēbēī āsā khē tēsā saccāīyā rē mutābika calaṇā cāīyō jō paramēśarē āsā khē paīlē tēī dēī rākhī.",null],[3,17,"ओ साथी विश्वासियो! तुसे सब मिली की मेरी जी चाल चलो और तिना लोका खे बी जो मेरी जेड़ी चाल चलोए पछयाणो और तिना जेड़ी चाल चलो।","ō sāthī viśvāsiyō! tusē saba milī kī mērī jī cāla calō aura tinā lōkā khē bī jō mērī jēṛī cāla calōē pachayāṇō aura tinā jēṛī cāla calō.",null],[3,18,"कऊँकि बऊत बुरी चाल चलोए, जेतेरे बारे आऊँ तुसा खे बार-बार बताई चुकी रा और एबे बी रोयी-रोयी की बोलूँआ कि सेयो आपणे चाल-चलणो ते मसीह रे क्रूसो रे बैरी ए।","kaūm̐ki baūta burī cāla calōē, jētērē bārē āūm̐ tusā khē bāra-bāra batāī cukī rā aura ēbē bī rōyī-rōyī kī bōlūm̐ā ki sēyō āpaṇē cāla-calaṇō tē masīha rē krūsō rē bairī ē.",null],[3,19,"तिना रा अंत नाश ए। तिना रा ईश्वर तिना री शारीरिक जरूरत ए, सेयो आपणी शर्मा री गल्ला पाँदे कमण्ड करोए। तिना रा मन तरतिया री चीजा पाँदे लगे रा रओआ।","tinā rā aṁta nāśa ē. tinā rā īśvara tinā rī śārīrika jarūrata ē, sēyō āpaṇī śarmā rī gallā pām̐dē kamaṇḍa karōē. tinā rā mana taratiyā rī cījā pām̐dē lagē rā raōā.",null],[3,20,"पर म्हारा आपणा देश स्वर्गो रे ए और आसे एक उद्धारकर्ता प्रभु यीशु मसीह रे तेथा ते वापस आऊणे री बाट देखणे लगी रे।","para mhārā āpaṇā dēśa svargō rē ē aura āsē ēka uddhārakartā prabhu yīśu masīha rē tēthā tē vāpasa āūṇē rī bāṭa dēkhaṇē lagī rē.",null],[3,21,"से आपणी शक्तिया रे तेस असरो रे मुताबिक जेतेरे जरिए से सारिया चीजा खे आपणे वशो रे करी सकोआ। से म्हारे दीन-हीन शरीरो रा रूप बदली की, आपणी महिमा रे शरीरो रे मुताबिक बणाई देणा।","sē āpaṇī śaktiyā rē tēsa asarō rē mutābika jētērē jariē sē sāriyā cījā khē āpaṇē vaśō rē karī sakōā. sē mhārē dīna-hīna śarīrō rā rūpa badalī kī, āpaṇī mahimā rē śarīrō rē mutābika baṇāī dēṇā.",null],[4,1,"ओ प्यारे साथी विश्वासियो! आँऊ तुसा सबी ते प्यार करूँआ और तुसा लोका ते मिलणे री बड़ी इच्छा राखूँआ। प्रभुए रे विश्वासो जोगे और स्थिर बणे रे रओ जेड़ा मैं तुसा खे बताई राखेया। तुसे सब मेरी खुशी और ईनाम ए।","ō pyārē sāthī viśvāsiyō! ām̐ū tusā sabī tē pyāra karūm̐ā aura tusā lōkā tē milaṇē rī baṛī icchā rākhūm̐ā. prabhuē rē viśvāsō jōgē aura sthira baṇē rē raō jēṛā maiṁ tusā khē batāī rākhēyā. tusē saba mērī khuśī aura īnāma ē.",null],[4,2,"आऊँ यूओदिया ते बिनती करूँआ और सुन्तुखे ते बी बिनती करूँआ कि सेयो प्रभुए रे एक मन ऊई कि रओ।","āūm̐ yūōdiyā tē binatī karūm̐ā aura suntukhē tē bī binatī karūm̐ā ki sēyō prabhuē rē ēka mana ūī ki raō.",null],[4,3,"ओ सच्चे सहकर्मी! आऊँ तांते बिनती करूँआ कि तूँ इना जवाणसा री मेल-मिलाप करने रे मताद कर, कऊँकि इने मां साथे सुसमाचार फैलाणे दे, क्लेमेंस और मेरे ओर साथे काम करने वाल़ेया समेत मईणत कित्ती, जिना सबी रे नाओं जीवनो री कताबा रे लिखी राखे।","ō saccē sahakarmī! āūm̐ tāṁtē binatī karūm̐ā ki tūm̐ inā javāṇasā rī mēla-milāpa karanē rē matāda kara, kaūm̐ki inē māṁ sāthē susamācāra phailāṇē dē, klēmēṁsa aura mērē ōra sāthē kāma karanē vāl̈ēyā samēta maīṇata kittī, jinā sabī rē nāōṁ jīvanō rī katābā rē likhī rākhē.",null],[4,4,"प्रभुए रे सदा खुश रओ, आऊँ फेर बोलूँआ कि खुश रओ।","prabhuē rē sadā khuśa raō, āūm̐ phēra bōlūm̐ā ki khuśa raō.",null],[4,5,"तुसा री नरमाई सबी लोका सामणे प्रकट ओ। प्रभुए रा वापस आऊणा नेड़े ए।","tusā rī naramāī sabī lōkā sāmaṇē prakaṭa ō. prabhuē rā vāpasa āūṇā nēṛē ē.",null],[4,6,"केसी बी गल्ला री चिन्ता नि करो। पर हर एकी परिस्थितिया रे तुसा री अर्ज, प्रार्थना और बिनतिया रे जरिए, धन्यवादो साथे परमेशरो सामणे ल्याए जाओ।","kēsī bī gallā rī cintā ni karō. para hara ēkī paristhitiyā rē tusā rī arja, prārthanā aura binatiyā rē jariē, dhanyavādō sāthē paramēśarō sāmaṇē lyāē jāō.",null],[4,7,"तेबे परमेशरो तुसा खे शान्ति देणी। ये शान्ति माणूंआ री समजा ते बिल्कुल बारे ए। एसा तुसा रे दिल और तुसा रे सोच-बिचार मसीह यीशुए रे सयी-सलामत राखणे।","tēbē paramēśarō tusā khē śānti dēṇī. yē śānti māṇūṁā rī samajā tē bilkula bārē ē. ēsā tusā rē dila aura tusā rē sōca-bicāra masīha yīśuē rē sayī-salāmata rākhaṇē.",null],[4,8,"आखरी रे ओ साथी विश्वासियो! तुसे आपणा त्यान तिना गल्ला पाँदे लगाओ जो-जो गल्ला सच ए, आदरणीय ए, खरिया ए, पवित्र ए, सुन्दर ए और मनो खे खरिया लगणे वाल़िया ए। तिना ई गल्ला रे बारे रे सोचो जो उत्तम और तारीफा जोगिया ए।","ākharī rē ō sāthī viśvāsiyō! tusē āpaṇā tyāna tinā gallā pām̐dē lagāō jō-jō gallā saca ē, ādaraṇīya ē, khariyā ē, pavitra ē, sundara ē aura manō khē khariyā lagaṇē vāl̈iyā ē. tinā ī gallā rē bārē rē sōcō jō uttama aura tārīphā jōgiyā ē.",null],[4,9,"जो गल्ला मैं तुसा खे सिखाई राखिया और तुसे मांते सुणिया और सिखिया और सेयो मानिया, और जो माखे करदे ऊए देखोए, तिना ई गल्ला खे मानेया करो। तेबे परमेशर, जो शान्तिया री सुबल़ ए तुसा लोका साथे रणा।","jō gallā maiṁ tusā khē sikhāī rākhiyā aura tusē māṁtē suṇiyā aura sikhiyā aura sēyō māniyā, aura jō mākhē karadē ūē dēkhōē, tinā ī gallā khē mānēyā karō. tēbē paramēśara, jō śāntiyā rī subal̈a ē tusā lōkā sāthē raṇā.",null],[4,10,"आऊँ प्रभुए रे बऊत खुश ए कऊँकि एबे इतणे दिनो ते बाद फेर तुसे मेरी चिन्ता मेरी मताद करने खे कित्ती। पक्का तुसा खे शुरूओ रे बी इजी गल्ला री चिन्ता थी, पर तुसा खे मेरी मताद करने रा मौका नि मिलेया।","āūm̐ prabhuē rē baūta khuśa ē kaūm̐ki ēbē itaṇē dinō tē bāda phēra tusē mērī cintā mērī matāda karanē khē kittī. pakkā tusā khē śurūō rē bī ijī gallā rī cintā thī, para tusā khē mērī matāda karanē rā maukā ni milēyā.",null],[4,11,"ये नि कि आऊँ आपणी कमिया री बजअ ते ये बोलणे लगी रा, कऊँकि मैं ये सिखी राखेया कि जेते दशा रे आए, तिदे ई तसल्ली राखूँ।","yē ni ki āūm̐ āpaṇī kamiyā rī bajaa tē yē bōlaṇē lagī rā, kaūm̐ki maiṁ yē sikhī rākhēyā ki jētē daśā rē āē, tidē ī tasallī rākhūm̐.",null],[4,12,"मैं गरीबी और भरपूरी दूँईं दशा रे रणा सीखी ला रा। हर एकी गल्ला रे और सबी दशा रे मैं रजे रे ऊणा या पूखा रणा और बढ़ना-कटणा सीखी ला रा।","maiṁ garībī aura bharapūrī dūm̐īṁ daśā rē raṇā sīkhī lā rā. hara ēkī gallā rē aura sabī daśā rē maiṁ rajē rē ūṇā yā pūkhā raṇā aura baṛhanā-kaṭaṇā sīkhī lā rā.",null],[4,13,"मसीह रे जरिए जो माखे सामर्थ देओआ तिदे आऊँ सब कुछ करी सकूँआ।","masīha rē jariē jō mākhē sāmartha dēōā tidē āūm̐ saba kucha karī sakūm̐ā.",null],[4,14,"फेर बी तुसे मेरे बुरे बखतो रे मेरी मताद करी की बऊत खरा काम कित्तेया।","phēra bī tusē mērē burē bakhatō rē mērī matāda karī kī baūta kharā kāma kittēyā.",null],[4,15,"ओ फिलिप्पिया रे लोको! तुसे आपू बी जाणोए कि सुसमाचार प्रचारो री शुरूआता दे, जेबे आऊँ मकिदुनिया प्रदेशो ते चली पड़ेया, तेबे तुसा खे छाडी की ओरी किने बी मण्डल़िए लणे-देणे रे बारे रे मेरी मताद नि कित्ती।","ō philippiyā rē lōkō! tusē āpū bī jāṇōē ki susamācāra pracārō rī śurūātā dē, jēbē āūm̐ makiduniyā pradēśō tē calī paṛēyā, tēbē tusā khē chāḍī kī ōrī kinē bī maṇḍal̈iē laṇē-dēṇē rē bārē rē mērī matāda ni kittī.",null],[4,16,"ईंयां ई जेबे आऊँ थिस्सलुनीके रे था, तेबे बी तुसे मेरी जरूरत पूरी करने खे, एकी बारिया ते बी जादा मताद पेजी।","īṁyāṁ ī jēbē āūm̐ thissalunīkē rē thā, tēbē bī tusē mērī jarūrata pūrī karanē khē, ēkī bāriyā tē bī jādā matāda pējī.",null],[4,17,"आँऊ ये इजी खे नि बोलदा कि माखे पैसेया री कुछ मताद चाईयो, पर ये कि तुसे से आशीष पाओ जो परमेशरो री तरफा ते दान देणे ते आओई।","ām̐ū yē ijī khē ni bōladā ki mākhē paisēyā rī kucha matāda cāīyō, para yē ki tusē sē āśīṣa pāō jō paramēśarō rī taraphā tē dāna dēṇē tē āōī.",null],[4,18,"मांगे सब कुछ ए, बल्कि बऊत जादा बी ए, जो चीजा तुसे इपफ्रुदीतुसो रे आथो रे पेजिया थिया, तिना खे पाई की आऊँ रज्जी गा रा। से तो सुख देणे वाल़ी खुशबू जेड़ी और मानणे जोगा बलिदान ए, जो परमेशरो खे अच्छा लगोआ।","māṁgē saba kucha ē, balki baūta jādā bī ē, jō cījā tusē ipaphrudītusō rē āthō rē pējiyā thiyā, tinā khē pāī kī āūm̐ rajjī gā rā. sē tō sukha dēṇē vāl̈ī khuśabū jēṛī aura mānaṇē jōgā balidāna ē, jō paramēśarō khē acchā lagōā.",null],[4,19,"आँऊ प्रार्थना करूँआ कि परमेशर बी आपणे तेस धनो रे मुताबिक, जो महिमा समेत यीशु मसीह रे ए, तुसा री सारी जरूरता खे पूरी करो।","ām̐ū prārthanā karūm̐ā ki paramēśara bī āpaṇē tēsa dhanō rē mutābika, jō mahimā samēta yīśu masīha rē ē, tusā rī sārī jarūratā khē pūrī karō.",null],[4,20,"म्हारे परमेशर और पिते री महिमा जुगो-जुगो तक ऊँदी रओ। आमीन्","mhārē paramēśara aura pitē rī mahimā jugō-jugō taka ūm̐dī raō. āmīn",null],[4,21,"यीशु मसीह रे परमेशरो रे सब पवित्र लोका खे मेरी तरफा ते नमस्कार बोलो। जो विश्वासी पाई मां साथे ए, सेयो तुसा खे नमस्कार बोलोए।","yīśu masīha rē paramēśarō rē saba pavitra lōkā khē mērī taraphā tē namaskāra bōlō. jō viśvāsī pāī māṁ sāthē ē, sēyō tusā khē namaskāra bōlōē.",null],[4,22,"सब परमेशरो रे पवित्र लोक जो एती ए, खास करी की जो महाराजा कैसरो रे कराने रे विश्वासी ए, तुसा खे नमस्कार बोलोए।","saba paramēśarō rē pavitra lōka jō ētī ē, khāsa karī kī jō mahārājā kaisarō rē karānē rē viśvāsī ē, tusā khē namaskāra bōlōē.",null],[4,23,"म्हारे प्रभु यीशु मसीह री कृपा तुसा सबी साथे सदा ऊँदी रओ। आमीन्।","mhārē prabhu yīśu masīha rī kr̥pā tusā sabī sāthē sadā ūm̐dī raō. āmīn.",null]],"bhd":[[1,1,"अवं पौलुस, त कने तीमुथियुस, यीशु मसीहेरे दास आम। इश्शे तरफां सेब्भी पवित्र लोकां केरां नंव्वां, ज़ैना मसीह यीशु मां भोइतां फिलिप्पी नगरे मां रातन, रखवालन ते सेवकन समेत,","avaṁ paulusa, ta kanē tīmuthiyusa, yīśu masīhērē dāsa āma. iśśē taraphāṁ sēbbhī pavitra lōkāṁ kērāṁ naṁvvāṁ, zainā masīha yīśu māṁ bhōitāṁ philippī nagarē māṁ rātana, rakhavālana tē sēvakana samēta,",null],[1,2,"इश्शे बाजी परमेशर ते प्रभु यीशु मसीहे करां तुसन अनुग्रह ते शान्ति मैलती राए।","iśśē bājī paramēśara tē prabhu yīśu masīhē karāṁ tusana anugraha tē śānti mailatī rāē.",null],[1,3,"अवं ज़ैखन-ज़ैखन तुसन याद केरताईं, तैखन-तैखन अपने परमेशरेरू शुक्र केरताईं।","avaṁ zaikhana-zaikhana tusana yāda kēratāīṁ, taikhana-taikhana apanē paramēśarērū śukra kēratāīṁ.",null],[1,4,"ते ज़ैखन भी तुश्शे सेब्भी केरे लेइ बिनती केरताईं, ते हमेशा आनन्दे सेइं प्रार्थना केरताईं।","tē zaikhana bhī tuśśē sēbbhī kērē lēi binatī kēratāīṁ, tē hamēśā ānandē sēiṁ prārthanā kēratāīṁ.",null],[1,5,"किजोकि तुस पेइले दिहैड़े करां अज़ तगर यीशु मसीहेरी खुशखबरी फैलाने मां मीं सेइं साथी शामिल रावरेथ।","kijōki tusa pēilē dihaiṛē karāṁ aza tagara yīśu masīhērī khuśakhabarī phailānē māṁ mīṁ sēiṁ sāthī śāmila rāvarētha.",null],[1,6,"ते मीं इस गल्लरो भरोसोए, कि परमेशरे तुसन मां रोड़े कम्मेरी शुरुआत कियोरीए, तैए तैस कम्मे यीशु मसीहेरे वापस एजनेरे दिहाड़े तगर पूरू केरेलो।","tē mīṁ isa gallarō bharōsōē, ki paramēśarē tusana māṁ rōṛē kammērī śuruāta kiyōrīē, taiē taisa kammē yīśu masīhērē vāpasa ējanērē dihāṛē tagara pūrū kērēlō.",null],[1,7,"इन जेइज़े, कि अवं तुसन सेब्भी केरे लेइ एरू सोची, किजोकि तुस मेरे मने मां बस्सोरेथ, ते मेरे कैदे मां खुशखेबरारे लेइ जुवाब ते सबूत देने मां तुस सब मीं सेइं साथी अनुग्रहे मां मीं साथिथ,","ina jēizē, ki avaṁ tusana sēbbhī kērē lēi ērū sōcī, kijōki tusa mērē manē māṁ bassōrētha, tē mērē kaidē māṁ khuśakhēbarārē lēi juvāba tē sabūta dēnē māṁ tusa saba mīṁ sēiṁ sāthī anugrahē māṁ mīṁ sāthitha,",null],[1,8,"इस मां परमेशर मेरो गवाहे, कि अवं यीशु मसीहेरो ज़ेरो प्यार केरतां तुश्शे सेब्भी केरू लालच़ केरताईं।","isa māṁ paramēśara mērō gavāhē, ki avaṁ yīśu masīhērō zērō pyāra kēratāṁ tuśśē sēbbhī kērū lālac̈a kēratāīṁ.",null],[1,9,"ते अवं ई प्रार्थना केरताईं, कि तुश्शो प्यार ज्ञान ते सेब्भी किसमेरो ज़मीर सेइं होरे भी बद्धते गाथ।","tē avaṁ ī prārthanā kēratāīṁ, ki tuśśō pyāra jñāna tē sēbbhī kisamērō zamīra sēiṁ hōrē bhī baddhatē gātha.",null],[1,10,"इड़ी तगर तुस रोड़ी करां रोड़ी गल्लां ट्लाऐरी बुझ़ा, ते मसीहेरे दिहाड़े तगर सच़्च़े बनोरे राथ; ते ठोकर न खाथ।","iṛī tagara tusa rōṛī karāṁ rōṛī gallāṁ ṭlāairī bujḧā, tē masīhērē dihāṛē tagara sac̈c̈ē banōrē rātha; tē ṭhōkara na khātha.",null],[1,11,"ते तैस धार्मिकतारे फले सेइं ज़ै यीशु मसीहेरे ज़िरिये भोते, भेरोते गाथ ज़ैस सेइं परमेशरेरी महिमा ते बड़याई भोती राए।","tē taisa dhārmikatārē phalē sēiṁ zai yīśu masīhērē ziriyē bhōtē, bhērōtē gātha zaisa sēiṁ paramēśarērī mahimā tē baṛayāī bhōtī rāē.",null],[1,12,"हे ढ्लाव ते बेइनव, अवं सच़ ज़ोताईं, कि तुस इन ज़ाना, कि मीं पुड़ ज़ै बीतोरीए, तैस सेइं खुशखेबरारी बड़ोतरी भी भोइ।","hē ḍhlāva tē bēinava, avaṁ sac̈a zōtāīṁ, ki tusa ina zānā, ki mīṁ puṛa zai bītōrīē, taisa sēiṁ khuśakhēbarārī baṛōtarī bhī bhōi.",null],[1,13,"इड़ी तगर कि महाराज़ेरी सारी फौज ते बाकी सारे लोकन मां इन बांदू भोव कि अवं मसीहेरे लेइ कैद मां आई।","iṛī tagara ki mahārāzērī sārī phauja tē bākī sārē lōkana māṁ ina bāṁdū bhōva ki avaṁ masīhērē lēi kaida māṁ āī.",null],[1,14,"ते प्रभु यीशु मां ज़ैना ढ्ला आन, तैन मरां बड़े मेरे कैद भोनेरे वजाई सेइं आन, तैना हिम्मत केरतां परमेशरेरो वचन बेधड़क भोइतां ते दिलेरी सेइं शुनानेरी कोशिश केरतन।","tē prabhu yīśu māṁ zainā ḍhlā āna, taina marāṁ baṛē mērē kaida bhōnērē vajāī sēiṁ āna, tainā himmata kēratāṁ paramēśarērō vacana bēdhaṛaka bhōitāṁ tē dilērī sēiṁ śunānērī kōśiśa kēratana.",null],[1,15,"किछ लोक त जलन ते लड़ैई सेइं मसीहेरो प्रचार केरतन ते किछ लोक सच़्च़े दिले सेइं।","kicha lōka ta jalana tē laṛaiī sēiṁ masīhērō pracāra kēratana tē kicha lōka sac̈c̈ē dilē sēiṁ.",null],[1,16,"किछ त इन सेमझ़तां कि अवं खुशखेबरारे लेइ जुवाब देनेरे लेइ ठेरावरोई प्यारे सेइं प्रचार केरताईं।","kicha ta ina sēmajḧatāṁ ki avaṁ khuśakhēbarārē lēi juvāba dēnērē lēi ṭhērāvarōī pyārē sēiṁ pracāra kēratāīṁ.",null],[1,17,"पन तैना होरे लोक साफ दिले सेइं नईं पन जलनी सेइं मसीहेरो प्रचार केरतन, इन सेमझ़तां कि मेरे कैद मां मेरे लेइ मुसीबत बधान।","pana tainā hōrē lōka sāpha dilē sēiṁ naīṁ pana jalanī sēiṁ masīhērō pracāra kēratana, ina sēmajḧatāṁ ki mērē kaida māṁ mērē lēi musībata badhāna.",null],[1,18,"त कुन भोव? सिर्फ इन, कि हर बत्तां चाए बुरे खियाले सेइं, चाए सच़ैई सेइं, मसीहेरे बारे मां खुशखबरी प्रचार भोतीए, ते अवं इस सेइं खुश आईं, ते खुश भी रेइलो।","ta kuna bhōva? sirpha ina, ki hara battāṁ cāē burē khiyālē sēiṁ, cāē sac̈aiī sēiṁ, masīhērē bārē māṁ khuśakhabarī pracāra bhōtīē, tē avaṁ isa sēiṁ khuśa āīṁ, tē khuśa bhī rēilō.",null],[1,19,"किजोकि अवं ज़ानताईं, कि तुश्शी प्रार्थनाई सेइं, ते यीशु मसीहेरी आत्मारे दाने सेइं इसेरो नितीजो मेरी मुक्ति भोली।","kijōki avaṁ zānatāīṁ, ki tuśśī prārthanāī sēiṁ, tē yīśu masīhērī ātmārē dānē sēiṁ isērō nitījō mērī mukti bhōlī.",null],[1,20,"अवं त दिले सेइं इन चाताईं, ते ई उमीद रखताई, कि अवं कोन्ची गल्ली मां न छिथोई, बल्के ज़ेन्च़रे मेरी बड़ी दिलेरी सेइं मसीहेरी बड़याई मेरे जिसमे सेइं भोती राई, तेन्च़रे हुना भी भोए चाए अवं ज़ींतो रेइ या मेर्री।","avaṁ ta dilē sēiṁ ina cātāīṁ, tē ī umīda rakhatāī, ki avaṁ kōncī gallī māṁ na chithōī, balkē zēnc̈arē mērī baṛī dilērī sēiṁ masīhērī baṛayāī mērē jisamē sēiṁ bhōtī rāī, tēnc̈arē hunā bhī bhōē cāē avaṁ zīṁtō rēi yā mērrī.",null],[1,21,"किजोकि मेरे लेइ ज़ींतू रानू मसीहे, ते मरनू फैइदोए।","kijōki mērē lēi zīṁtū rānū masīhē, tē maranū phaiidōē.",null],[1,22,"पन अगर जिसमे मां ज़ींतू रानू मेरे कम्मेरे लेइ फैइदेमंदे त अवं न ज़ैनी, कि केस च़ुनी।","pana agara jisamē māṁ zīṁtū rānū mērē kammērē lēi phaiidēmaṁdē ta avaṁ na zainī, ki kēsa c̈unī.",null],[1,23,"किजोकि मीं दुइयां केरे मझ़ाटे च़ुने मां मुशकिल भोने लोरीए। अवं मरनू चाताईं ताके स्वर्गे मां मसीह साथी रेइ बेटि, किजोकि इन बड़ू ज़रूरीए।","kijōki mīṁ duiyāṁ kērē majḧāṭē c̈unē māṁ muśakila bhōnē lōrīē. avaṁ maranū cātāīṁ tākē svargē māṁ masīha sāthī rēi bēṭi, kijōki ina baṛū zarūrīē.",null],[1,24,"पन तुश्शी मद्दत केरनेरे लेइ मेरू ज़ींतू रानू बड़ू ज़रूरीए।","pana tuśśī maddata kēranērē lēi mērū zīṁtū rānū baṛū zarūrīē.",null],[1,25,"एल्हेरेलेइ कि मीं इलहेरो भरोसोए ते अवं ज़ानताईं कि अवं ज़ींतो रानोई, बल्के तुसन सेब्भन सेइं साथी रानोई ज़ैस सेइं अवं तुश्शी मद्दत केरि, कि विश्वासे मां मज़बूत भोथ, ते इस मां खुश राथ।","ēlhērēlēi ki mīṁ ilahērō bharōsōē tē avaṁ zānatāīṁ ki avaṁ zīṁtō rānōī, balkē tusana sēbbhana sēiṁ sāthī rānōī zaisa sēiṁ avaṁ tuśśī maddata kēri, ki viśvāsē māṁ mazabūta bhōtha, tē isa māṁ khuśa rātha.",null],[1,26,"ज़ैखन अवं तुसन कां दुबारां एज्जी, तुसन कां जादे वजा भोली यीशु मसीह पुड़ घमण्ड केरनेरी एल्हेरेलेइ ज़ैन किछ तै मेरे ज़िरिये केरने लोरोए।","zaikhana avaṁ tusana kāṁ dubārāṁ ējjī, tusana kāṁ jādē vajā bhōlī yīśu masīha puṛa ghamaṇḍa kēranērī ēlhērēlēi zaina kicha tai mērē ziriyē kēranē lōrōē.",null],[1,27,"सिर्रफ एत्रू केरा कि तुश्शो चालचलन मसीहेरे खुशखेबरारे काबल भोए। चाए अवं तुसन एइतां हेरी, चाए न एज्जी, तुश्शे बारे मां इन शुनी, कि तुस अक मन भोइतां बनोरे रातथ, ते अकोट्ठे भोइतां खुशखेबरारे विश्वासेरे लेइ मेहनत केरते रातथ।","sirrapha ētrū kērā ki tuśśō cālacalana masīhērē khuśakhēbarārē kābala bhōē. cāē avaṁ tusana ēitāṁ hērī, cāē na ējjī, tuśśē bārē māṁ ina śunī, ki tusa aka mana bhōitāṁ banōrē rātatha, tē akōṭṭhē bhōitāṁ khuśakhēbarārē viśvāsērē lēi mēhanata kēratē rātatha.",null],[1,28,"ते कोन्ची गल्ली मां खलाफत केरनेबालन करां न डराथ। ई तैन केरे लेइ बरबाद भोनेरो साफ निशाने, पन तुश्शे लेइ मुक्तरो, ते इन परमेशरेरे तरफां आए।","tē kōncī gallī māṁ khalāphata kēranēbālana karāṁ na ḍarātha. ī taina kērē lēi barabāda bhōnērō sāpha niśānē, pana tuśśē lēi muktarō, tē ina paramēśarērē taraphāṁ āē.",null],[1,29,"किजोकि मसीहेरे वजाई सेइं तुसन पुड़ ई अनुग्रह भोव कि न सिर्फ तैस पुड़ विश्वास केरा पन तैसेरेलेइ दुःख भी झ़ैल्लां।","kijōki masīhērē vajāī sēiṁ tusana puṛa ī anugraha bhōva ki na sirpha taisa puṛa viśvāsa kērā pana taisērēlēi duḥkha bhī jḧaillāṁ.",null],[1,30,"ते तुसन तेन्च़रे मुसीबत केरनीए, ज़ेन्च़रे तुसेईं मीं करां केरते लोरीए, ते हुना भी शुन्तन, कि अवं तेन्च़रे केरताईं।","tē tusana tēnc̈arē musībata kēranīē, zēnc̈arē tusēīṁ mīṁ karāṁ kēratē lōrīē, tē hunā bhī śuntana, ki avaṁ tēnc̈arē kēratāīṁ.",null],[2,1,"अगर मसीह मां किछ तसल्ली ते प्यारे सेइं हिम्मत ते आत्मारी मौजूदगी, ते किछ दर्द ते दयाए।","agara masīha māṁ kicha tasallī tē pyārē sēiṁ himmata tē ātmārī maujūdagī, tē kicha darda tē dayāē.",null],[2,2,"ते मेरो ई आनन्द पूरो केरा कि अक्के मन राथ ते अक्के प्यार, ते अक्के खियाल, ते अक्के सोच रखा।","tē mērō ī ānanda pūrō kērā ki akkē mana rātha tē akkē pyāra, tē akkē khiyāla, tē akkē sōca rakhā.",null],[2,3,"खुदगरज़ या झूठी बड़यैयरे लेइ किछ न केरा पन नर्म भोइतां एक्की होरि एप्पू करां रोड़ो समझ़ा।","khudagaraza yā jhūṭhī baṛayaiyarē lēi kicha na kērā pana narma bhōitāṁ ēkkī hōri ēppū karāṁ rōṛō samajḧā.",null],[2,4,"तुसन मरां हर कोई सिर्फ अपने भलैइयरे लेइ न सोचे, बल्के होरि केरि भलैइयरे लेइ भी सोचे।","tusana marāṁ hara kōī sirpha apanē bhalaiiyarē lēi na sōcē, balkē hōri kēri bhalaiiyarē lēi bhī sōcē.",null],[2,5,"ज़ेन्च़रे यीशु मसीहेरो सुभाव थियो तेन्च़रे तुश्शो भी भोए।","zēnc̈arē yīśu masīhērō subhāva thiyō tēnc̈arē tuśśō bhī bhōē.",null],[2,6,"ज़ैने परमेशरेरे बराबर भोइतां भी परमेशरेरे बराबर भोने अपने कब्ज़े मां रखनेरी चीज़ न समझ़ू।","zainē paramēśarērē barābara bhōitāṁ bhī paramēśarērē barābara bhōnē apanē kabzē māṁ rakhanērī cīza na samajḧū.",null],[2,7,"बल्के अपनो आप खाली केरो, ते गुलामेरू रूप धारण केरू, ते मैन्हु केरे ज़ेरो बनो।","balkē apanō āpa khālī kērō, tē gulāmērū rūpa dhāraṇa kērū, tē mainhu kērē zērō banō.",null],[2,8,"ते मैनेरे रूपे मां बांदो केरतां दीन केरो, ते इड़ी तगर हुक्म मन्ने बालो राव, कि मौत, हाँ, क्रूसेरे मौत भी झ़ैल्ली।","tē mainērē rūpē māṁ bāṁdō kēratāṁ dīna kērō, tē iṛī tagara hukma mannē bālō rāva, ki mauta, hām̐, krūsērē mauta bhī jḧaillī.",null],[2,9,"एल्हेरेलेइ परमेशरे तै बड़ो महान भी केरो, ते तैस तैन नवं दित्तू ज़ैन सेब्भी नंव्वन करां बड्डूए।","ēlhērēlēi paramēśarē tai baṛō mahāna bhī kērō, tē taisa taina navaṁ dittū zaina sēbbhī naṁvvana karāṁ baḍḍūē.",null],[2,10,"कि स्वर्गे मां ते धेरती पुड़ ते धेरतलरे बुने; तैना सब यीशुएरे नंव्वे पुड़ ज़ैधूए टेकन।","ki svargē māṁ tē dhēratī puṛa tē dhēratalarē bunē; tainā saba yīśuērē naṁvvē puṛa zaidhūē ṭēkana.",null],[2,11,"ते बाजी परमेशरेरी महिमारे लेइ हर अक ज़िभ मन्ने कि यीशु मसीह प्रभुए।","tē bājī paramēśarērī mahimārē lēi hara aka zibha mannē ki yīśu masīha prabhuē.",null],[2,12,"ते हे मेरे ट्लारव, ज़ेन्च़रे तुस सदा हुक्म मन्ते ओरेथ, तेन्च़रे हुना भी न सिर्फ मीं सेइं साथी रेइतां पन खास केरतां ज़ैखन अवं दूर भोताईं फिरी भी डरते राथ ते थरकते अपने मुक्तरू कम पूरू केरते गाथ।","tē hē mērē ṭlārava, zēnc̈arē tusa sadā hukma mantē ōrētha, tēnc̈arē hunā bhī na sirpha mīṁ sēiṁ sāthī rēitāṁ pana khāsa kēratāṁ zaikhana avaṁ dūra bhōtāīṁ phirī bhī ḍaratē rātha tē tharakatē apanē muktarū kama pūrū kēratē gātha.",null],[2,13,"किजोकि परमेशर ज़ै तुसन मां कम केरते, ते तुसन इच्छा ते शक्ति तैन केरनेरे लेइ देते, ज़ैस सेइं तै खुश भोते।","kijōki paramēśara zai tusana māṁ kama kēratē, tē tusana icchā tē śakti taina kēranērē lēi dētē, zaisa sēiṁ tai khuśa bhōtē.",null],[2,14,"त सब कम्मां बगैर शकैइतां ते बगैर बेंसी सेइं केरा।","ta saba kammāṁ bagaira śakaiitāṁ tē bagaira bēṁsī sēiṁ kērā.",null],[2,15,"ताके तुस बेइलज़ाम ते शरीफ भोइतां टारे ते ढीठ लोकन मां परमेशरेरे बेइलज़ाम बच्चे बना, ज़ैन मां तुस ज़िन्दगरो वचन घिन्तां दुनियाई मां बलते दीयां केरे ज़ेरे लेइहोते रातथ,","tākē tusa bēilazāma tē śarīpha bhōitāṁ ṭārē tē ḍhīṭha lōkana māṁ paramēśarērē bēilazāma baccē banā, zaina māṁ tusa zindagarō vacana ghintāṁ duniyāī māṁ balatē dīyāṁ kērē zērē lēihōtē rātatha,",null],[2,16,"कि मसीहेरे वापस एजनेरे दिहाड़े घमण्ड केरनेरी वजा भोए, कि न मेरी दौड़-धूप ते न मेरी मेहनत बेकार भोए।","ki masīhērē vāpasa ējanērē dihāṛē ghamaṇḍa kēranērī vajā bhōē, ki na mērī dauṛa-dhūpa tē na mērī mēhanata bēkāra bhōē.",null],[2,17,"अगर मीं तुश्शे विश्वासेरे बलिदाने या सेवारे लेइ अपनो खून भी बगानो पे, त फिरी भी अवं खुश आईं, ते तुसन सेब्भी साथी खुश आईं।","agara mīṁ tuśśē viśvāsērē balidānē yā sēvārē lēi apanō khūna bhī bagānō pē, ta phirī bhī avaṁ khuśa āīṁ, tē tusana sēbbhī sāthī khuśa āīṁ.",null],[2,18,"तेन्च़रे तुस भी खुश भोथ, ते मीं साथी आनन्द केरा।","tēnc̈arē tusa bhī khuśa bhōtha, tē mīṁ sāthī ānanda kērā.",null],[2,19,"मीं प्रभु यीशु मां उमीदे, कि अवं तीमुथियुसे तुसन कां जल्दी भेज़ेलो, ताके तुश्शो हाल शुन्तां मीं शान्ति मैल्ले।","mīṁ prabhu yīśu māṁ umīdē, ki avaṁ tīmuthiyusē tusana kāṁ jaldī bhēzēlō, tākē tuśśō hāla śuntāṁ mīṁ śānti maillē.",null],[2,20,"किजोकि मीं कां एरे ज़ेरे सुभावेरो कोई नईं, ज़ै साफ दिले सेइं तुश्शी फिक्र केरे।","kijōki mīṁ kāṁ ērē zērē subhāvērō kōī naīṁ, zai sāpha dilē sēiṁ tuśśī phikra kērē.",null],[2,21,"किजोकि सब अपने फैइदो तोपतन, न कि यीशु मसीहे।","kijōki saba apanē phaiidō tōpatana, na ki yīśu masīhē.",null],[2,22,"पन तुसेईं तै परखो ते पिशानो भी, कि ज़ेन्च़रे मट्ठू बाजी साथी केरते, तेन्च़रे तैनी मीं सेइं साथी खुशखबरी फैलाने मां मीं सेइं साथी मेहनत केरि।","pana tusēīṁ tai parakhō tē piśānō bhī, ki zēnc̈arē maṭṭhū bājī sāthī kēratē, tēnc̈arē tainī mīṁ sēiṁ sāthī khuśakhabarī phailānē māṁ mīṁ sēiṁ sāthī mēhanata kēri.",null],[2,23,"ते मीं उमीदे, कि ज़ैखन मीं पतो च़लेलो कि मेरी कुन हालत भोली, तैखन अवं तैस लूशी भेज़ेलो।","tē mīṁ umīdē, ki zaikhana mīṁ patō c̈alēlō ki mērī kuna hālata bhōlī, taikhana avaṁ taisa lūśī bhēzēlō.",null],[2,24,"ते मीं प्रभु मां भरोसोए, कि अवं एप्पू भी जल्दी एज्जेलो।","tē mīṁ prabhu māṁ bharōsōē, ki avaṁ ēppū bhī jaldī ējjēlō.",null],[2,25,"पन मीं इपफ्रुदीतुस ज़ै मेरो ढ्लाए, ते मद्दतगार, ते साथी योधो ते तुश्शो दूते, ते ज़रूरी गल्लन मां मेरी सेवा टेल केरनेबालोए, तुसन कां भेज़नो ज़रूरी समझ़ो।","pana mīṁ ipaphrudītusa zai mērō ḍhlāē, tē maddatagāra, tē sāthī yōdhō tē tuśśō dūtē, tē zarūrī gallana māṁ mērī sēvā ṭēla kēranēbālōē, tusana kāṁ bhēzanō zarūrī samajḧō.",null],[2,26,"किजोकि तैसेरो मन तुसन सेब्भन मां लग्गोरो थियो। एल्हेरेलेइ बे चैन रातो थियो किजोकि तुसेईं तैसेरे बिमैरारो हाल शुनोरो थियो।","kijōki taisērō mana tusana sēbbhana māṁ laggōrō thiyō. ēlhērēlēi bē caina rātō thiyō kijōki tusēīṁ taisērē bimairārō hāla śunōrō thiyō.",null],[2,27,"ते तै सच़्च़े बिमार त भोरो थियो, इड़ी तगर कि मरने पुड़ थियो, परमेशरे तैस पुड़ दया की; ते सिर्फ तैस्से पुड़ नईं, पन मीं पुड़ भी, कि मीं दुःखे पुड़ दुख न भोए।","tē tai sac̈c̈ē bimāra ta bhōrō thiyō, iṛī tagara ki maranē puṛa thiyō, paramēśarē taisa puṛa dayā kī; tē sirpha taissē puṛa naīṁ, pana mīṁ puṛa bhī, ki mīṁ duḥkhē puṛa dukha na bhōē.",null],[2,28,"एल्हेरेलेइ अवं तैस भेज़नेरी होरि भी कोशिश केरि, तुस फिरी तैस सेइं मिलतां खुश भोइयथ ते मेरो भी दुःख घटे।","ēlhērēlēi avaṁ taisa bhēzanērī hōri bhī kōśiśa kēri, tusa phirī taisa sēiṁ milatāṁ khuśa bhōiyatha tē mērō bhī duḥkha ghaṭē.",null],[2,29,"एल्हेरेलेइ तुस प्रभु मां बड़े आनन्दे सेइं तैस सेइं मुलाकात केरा, ते एरे ज़ेरे लोकां केरि आदर केरा।","ēlhērēlēi tusa prabhu māṁ baṛē ānandē sēiṁ taisa sēiṁ mulākāta kērā, tē ērē zērē lōkāṁ kēri ādara kērā.",null],[2,30,"किजोकि तैए मसीहेरे कम्मेरे लेइ अपनि जान खतरे मां छ़ेडतां मौतरे नेड़ो पुज़ोरो थियो, ताके ज़ै घाटो तुश्शे तरफां मेरी सेवा मां भोव, तैस तै पूरो केरे।","kijōki taiē masīhērē kammērē lēi apani jāna khatarē māṁ cḧēḍatāṁ mautarē nēṛō puzōrō thiyō, tākē zai ghāṭō tuśśē taraphāṁ mērī sēvā māṁ bhōva, taisa tai pūrō kērē.",null],[3,1,"हे मेरे ढ्लाव ते बेइनव, प्रभु मां आनन्दित राथ, तैना गल्लां तुसन बार-बार लिखने मां मीं त कोई कष्ट न भोए, ते इस मां तुश्शी सलामतीए।","hē mērē ḍhlāva tē bēinava, prabhu māṁ ānandita rātha, tainā gallāṁ tusana bāra-bāra likhanē māṁ mīṁ ta kōī kaṣṭa na bhōē, tē isa māṁ tuśśī salāmatīē.",null],[3,2,"तैन बुरां कम्मां केरनेबाले लोकन करां हुशार राथ, ज़ैना खुवार कुतरां केरे ज़ेरे खाने बालां आन।","taina burāṁ kammāṁ kēranēbālē lōkana karāṁ huśāra rātha, zainā khuvāra kutarāṁ kērē zērē khānē bālāṁ āna.",null],[3,3,"किजोकि खतने बाले त असां आम ज़ैना परमेशरेरे आत्मारे च़लाने सेइं च़लतम ते आराधना केरतम ते मसीह यीशु पुड़ घमण्ड केरतम ते जिसमे पुड़ भरोसो न रखम।","kijōki khatanē bālē ta asāṁ āma zainā paramēśarērē ātmārē c̈alānē sēiṁ c̈alatama tē ārādhanā kēratama tē masīha yīśu puṛa ghamaṇḍa kēratama tē jisamē puṛa bharōsō na rakhama.",null],[3,4,"पन अवं त जिसमे पुड़ भरोसो रेख्खी बटताईं अगर कोन्ची होरि जिसमे पुड़ भरोसो रखनेरो वचार भोए, त अवं तैस करां भी जादे रेख्खी बटताईं।","pana avaṁ ta jisamē puṛa bharōsō rēkhkhī baṭatāīṁ agara kōncī hōri jisamē puṛa bharōsō rakhanērō vacāra bhōē, ta avaṁ taisa karāṁ bhī jādē rēkhkhī baṭatāīṁ.",null],[3,5,"अठोवं दिहाड़े मेरो खतनो भोव, इस्राएल केरे कुटमे ते बिन्यामीनेरे गोत्रे मरां आई; इबरैनी केरो इब्रानी; कानूनेरे बारे मां अगर कोई ज़ोए त फरीसी।","aṭhōvaṁ dihāṛē mērō khatanō bhōva, isrāēla kērē kuṭamē tē binyāmīnērē gōtrē marāṁ āī; ibarainī kērō ibrānī; kānūnērē bārē māṁ agara kōī zōē ta pharīsī.",null],[3,6,"जोशेरे बारे मां अगर कोई ज़ोए त कलीसियाई सताने बालो; ते अगर कानूनेरे धार्मिकतारे बारे मां कोई ज़ोए त बेइलज़ाम।","jōśērē bārē māṁ agara kōī zōē ta kalīsiyāī satānē bālō; tē agara kānūnērē dhārmikatārē bārē māṁ kōī zōē ta bēilazāma.",null],[3,7,"पन ज़ैना-ज़ैना गल्लां मेरे फैइदेरी थी तैना मीं मसीहेरे खातर नुकसान सैमझ़ोरिन।","pana zainā-zainā gallāṁ mērē phaiidērī thī tainā mīṁ masīhērē khātara nukasāna saimajḧōrina.",null],[3,8,"बल्के मीं अपने प्रभु यीशु मसीहेरे पिशानारी बड़यैयरे वजाई सेइं अवं सब गल्लां नुकसान समझ़ताईं, ज़ेसेरे वजाई सेइं मीं बेड़ि चीज़ां केरो नुकसान उठाव, ते तैन कूड़ो समझ़ताईं, ज़ैस सेइं अवं मसीह हासिल केरि।","balkē mīṁ apanē prabhu yīśu masīhērē piśānārī baṛayaiyarē vajāī sēiṁ avaṁ saba gallāṁ nukasāna samajḧatāīṁ, zēsērē vajāī sēiṁ mīṁ bēṛi cīzāṁ kērō nukasāna uṭhāva, tē taina kūṛō samajḧatāīṁ, zaisa sēiṁ avaṁ masīha hāsila kēri.",null],[3,9,"ते तैस मां भोइ, न कि एपनी तैस धार्मिता सेइं, ज़ै मूसेरे कानूने सेइं ए, बल्के तैस धार्मिकता सेइं ज़ै परमेशरेरे तरफां मसीह पुड़ विश्वास केरने सेइं भोतीए।","tē taisa māṁ bhōi, na ki ēpanī taisa dhārmitā sēiṁ, zai mūsērē kānūnē sēiṁ ē, balkē taisa dhārmikatā sēiṁ zai paramēśarērē taraphāṁ masīha puṛa viśvāsa kēranē sēiṁ bhōtīē.",null],[3,10,"ते अवं तैस ते तैसेरे ज़ींती भोनेरी शक्ति, ते तैस साथी दुखन मां शामिल भोईं, ते तैसेरी मौतरी बराबरी हासिल केरि।","tē avaṁ taisa tē taisērē zīṁtī bhōnērī śakti, tē taisa sāthī dukhana māṁ śāmila bhōīṁ, tē taisērī mautarī barābarī hāsila kēri.",null],[3,11,"ताके अवं कोन्ची रीति सेइं मुड़दन मरां ज़ींते भोनेरे पदे तगर पुज़ी।","tākē avaṁ kōncī rīti sēiṁ muṛadana marāṁ zīṁtē bhōnērē padē tagara puzī.",null],[3,12,"ई मतलब नईं, कि मीं हासिल केरू, या अवं सिद्ध भोइ जेव, पन तैस चीज़ी हासिल केरनेरे लेइ दौड़ने लोरोईं, ज़ेसेरे लेइ मसीह यीशुए अवं ट्लावरो थियो।","ī matalaba naīṁ, ki mīṁ hāsila kērū, yā avaṁ siddha bhōi jēva, pana taisa cīzī hāsila kēranērē lēi dauṛanē lōrōīṁ, zēsērē lēi masīha yīśuē avaṁ ṭlāvarō thiyō.",null],[3,13,"हे ढ्लाव ते बेइनव, मेरू इन गुमान नईं कि मीं ट्लाव, पन सिर्फ अक कम केरताईं, कि ज़ैना गल्लां पत्रोवं रेइ तैन बिसरतां, अग्री गल्लां केरे पासे गाताईं।","hē ḍhlāva tē bēinava, mērū ina gumāna naīṁ ki mīṁ ṭlāva, pana sirpha aka kama kēratāīṁ, ki zainā gallāṁ patrōvaṁ rēi taina bisaratāṁ, agrī gallāṁ kērē pāsē gātāīṁ.",null],[3,14,"निशानेरे पासे दौड़तो च़लताईं, ताके मीं तैन इनाम मैल्ले, ज़ेसेरे लेइ परमेशरे अवं मसीह यीशु मां बा कुजेवरोईं।","niśānērē pāsē dauṛatō c̈alatāīṁ, tākē mīṁ taina ināma maillē, zēsērē lēi paramēśarē avaṁ masīha yīśu māṁ bā kujēvarōīṁ.",null],[3,15,"असन मरां ज़ेत्रे सिद्धन, ईए विचार रखा, ते अगर कोन्ची गल्ली मां तुश्शो होरो खियाल भोए त परमेशर तैस भी तुसन पुड़ बांदो केरेलो।","asana marāṁ zētrē siddhana, īē vicāra rakhā, tē agara kōncī gallī māṁ tuśśō hōrō khiyāla bhōē ta paramēśara taisa bhī tusana puṛa bāṁdō kērēlō.",null],[3,16,"एल्हेरेलेइ ज़ैड़ी तगर पुज़ोरेम, तैसेरे मुताबिक च़लम।","ēlhērēlēi zaiṛī tagara puzōrēma, taisērē mutābika c̈alama.",null],[3,17,"हे ढ्लाव ते बेइनव, तुस सब मिलतां मेरी ज़ेरि चाल च़ला, ते तैन केरि पिशान रखा, ज़ैना इस रीति पुड़ च़लतन ज़ेसेरी मिसाल तुस असन मां हेरतथ।","hē ḍhlāva tē bēinava, tusa saba milatāṁ mērī zēri cāla c̈alā, tē taina kēri piśāna rakhā, zainā isa rīti puṛa c̈alatana zēsērī misāla tusa asana māṁ hēratatha.",null],[3,18,"किजोकि बड़े एरी चाल च़लतन, ज़ैन केरि चर्चा मीं तुसन सेइं बार-बार की ते अज़ भी लेरां देइ-देइ ज़ोताईं, कि तैना अपने चालचलन सेइं मसीहेरे क्रूसेरे बैरिन।","kijōki baṛē ērī cāla c̈alatana, zaina kēri carcā mīṁ tusana sēiṁ bāra-bāra kī tē aza bhī lērāṁ dēi-dēi zōtāīṁ, ki tainā apanē cālacalana sēiṁ masīhērē krūsērē bairina.",null],[3,19,"तैन केरो अन्त विनाशे, तैन केरो ईश्वर पेटे, तैना एपनी शरमरी गल्लन पुड़ घमण्ड केरतन, ज़मीनारी गल्लन पुड़ मन लातन।","taina kērō anta vināśē, taina kērō īśvara pēṭē, tainā ēpanī śaramarī gallana puṛa ghamaṇḍa kēratana, zamīnārī gallana puṛa mana lātana.",null],[3,20,"पन इश्शो मुलख स्वर्गे, ते अस एक्की मुक्ति देनेबाले प्रभु यीशु मसीह स्वर्गेरां बलगने लोरेम।","pana iśśō mulakha svargē, tē asa ēkkī mukti dēnēbālē prabhu yīśu masīha svargērāṁ balaganē lōrēma.",null],[3,21,"तैए एपनी शेक्ति सेइं तैस अस्सेरे मुताबिक तैना सब चीज़न अपने वशे मां केरि बटते, इश्शे कमज़ोर जिसमेरू रूप बेदलतां, अपने महिमारो जिसमेरे मुताबिक बनालो।","taiē ēpanī śēkti sēiṁ taisa assērē mutābika tainā saba cīzana apanē vaśē māṁ kēri baṭatē, iśśē kamazōra jisamērū rūpa bēdalatāṁ, apanē mahimārō jisamērē mutābika banālō.",null],[4,1,"एल्हेरेलेइ हे मेरे ट्लारे ढ्लाव ते बेइनव अवं तुसन सेइं प्यार केरताईं, ज़ैन मां मेरो दिल लग्गोरो रहते ज़ै मेरो आनन्द ते ताज भोए, हे ट्लारे ढ्लाव ते बेइनव, प्रभु मां एन्च़रे मज़बूत राथ।","ēlhērēlēi hē mērē ṭlārē ḍhlāva tē bēinava avaṁ tusana sēiṁ pyāra kēratāīṁ, zaina māṁ mērō dila laggōrō rahatē zai mērō ānanda tē tāja bhōē, hē ṭlārē ḍhlāva tē bēinava, prabhu māṁ ēnc̈arē mazabūta rātha.",null],[4,2,"अवं यूओदियारे छंदे केरताईं, ते सुन्तुखेरे भी, कि तैना प्रभु मां अक मन रान।","avaṁ yūōdiyārē chaṁdē kēratāīṁ, tē suntukhērē bhī, ki tainā prabhu māṁ aka mana rāna.",null],[4,3,"ते हे सच़्च़े मद्दतगार अवं तीं कां भी बिनती केरताईं, कि तू तैन कुआन्शां केरि मद्दत केर, किजोकि तैनेईं मीं सेइं साथी खुशखबरी फैलाने मां, क्लेमेंस ते मेरे तैन मद्दत केरनेबालन समेत मेहनत की, ज़ैन करां नंव्वां ज़िन्दगरे किताबी मां लिखोरन।","tē hē sac̈c̈ē maddatagāra avaṁ tīṁ kāṁ bhī binatī kēratāīṁ, ki tū taina kuānśāṁ kēri maddata kēra, kijōki tainēīṁ mīṁ sēiṁ sāthī khuśakhabarī phailānē māṁ, klēmēṁsa tē mērē taina maddata kēranēbālana samēta mēhanata kī, zaina karāṁ naṁvvāṁ zindagarē kitābī māṁ likhōrana.",null],[4,4,"प्रभु मां सदा आनन्दित राथ; अवं फिरी ज़ोताईं, आनन्दित राथ।","prabhu māṁ sadā ānandita rātha; avaṁ phirī zōtāīṁ, ānandita rātha.",null],[4,5,"तुश्शी नरमी सेब्भी मैनन् पुड़ बांदी भोए, प्रभु नेड़ोए।","tuśśī naramī sēbbhī mainan puṛa bāṁdī bhōē, prabhu nēṛōē.",null],[4,6,"कोन्ची भी गल्लारी फिक्र न केरा, पन हर एक्की गल्ली मां तुश्शी दरखुवास, प्रार्थना बिनती सेइं शुक्रे साथी परमेशरे कां हाज़र भोन।","kōncī bhī gallārī phikra na kērā, pana hara ēkkī gallī māṁ tuśśī darakhuvāsa, prārthanā binatī sēiṁ śukrē sāthī paramēśarē kāṁ hāzara bhōna.",null],[4,7,"तैखन परमेशरेरी शान्ति, ज़ै समझ़ी करां बिलकुल बेइरे, तुश्शे दिलन ते तुश्शे खियालन मसीह यीशु मां बिलकुल मैफूज़ रखेली।","taikhana paramēśarērī śānti, zai samajḧī karāṁ bilakula bēirē, tuśśē dilana tē tuśśē khiyālana masīha yīśu māṁ bilakula maiphūza rakhēlī.",null],[4,8,"आखरी मां, हे मेरे ढ्लाव ते बेइनव, ज़ैना-ज़ैना गल्लां सच़्च़ीन, ते ज़ैना-ज़ैना आदरारे काबलन, ते ज़ैना-ज़ैना गल्लां पवित्ररन, ते ज़ैना-ज़ैना गल्लां रोड़िन, ते ज़ैना-ज़ैना गल्लां मने रोड़ी लेगतिन, ते ज़ैना-ज़ैना गुण ते ज़ैना-ज़ैना गल्लां तरीफेरी, तैन पुड़ धयान केरा।","ākharī māṁ, hē mērē ḍhlāva tē bēinava, zainā-zainā gallāṁ sac̈c̈īna, tē zainā-zainā ādarārē kābalana, tē zainā-zainā gallāṁ pavitrarana, tē zainā-zainā gallāṁ rōṛina, tē zainā-zainā gallāṁ manē rōṛī lēgatina, tē zainā-zainā guṇa tē zainā-zainā gallāṁ tarīphērī, taina puṛa dhayāna kērā.",null],[4,9,"ज़ैना गल्लां तुसेईं मीं करां शिखी, ते कबूल की, ते शुनी ते मीं हेरी, तैन केरो हुक्म मन्ना तैखन परमेशर ज़ै शान्ति देनेबालोए तुसन साथी भोलो।","zainā gallāṁ tusēīṁ mīṁ karāṁ śikhī, tē kabūla kī, tē śunī tē mīṁ hērī, taina kērō hukma mannā taikhana paramēśara zai śānti dēnēbālōē tusana sāthī bhōlō.",null],[4,10,"अवं प्रभु मां बड़ो खुश आईं कि हुनी एत्रे दिहाड़न पत्ती तुसन मेरे बारे मां फिरी खियाल भोव; याकीन्न तुश्शे शुरुआती मां इस एरो खियाल थियो, पन तुसन मौको न मैल्लो।","avaṁ prabhu māṁ baṛō khuśa āīṁ ki hunī ētrē dihāṛana pattī tusana mērē bārē māṁ phirī khiyāla bhōva; yākīnna tuśśē śuruātī māṁ isa ērō khiyāla thiyō, pana tusana maukō na maillō.",null],[4,11,"इन नईं कि अवं अपनि कम्मेरे वजाई सेइं ज़ोताईं; किजोकि मीं इन्ने शिखोरूए कि ज़ैस हालती मां आई, तैस्से मां राज़ी भोईं।","ina naīṁ ki avaṁ apani kammērē vajāī sēiṁ zōtāīṁ; kijōki mīṁ innē śikhōrūē ki zaisa hālatī māṁ āī, taissē māṁ rāzī bhōīṁ.",null],[4,12,"अवं निकड़ू भोनू भी ज़ानताईं ते बड्डू भोनू भी ज़ानताईं, ते मीं हर एक्की गल्ली ते सेब्भी हालतन मां रज़नू, ढ्लुखुनू ते बधनू घटनू शिखोरूए।","avaṁ nikaṛū bhōnū bhī zānatāīṁ tē baḍḍū bhōnū bhī zānatāīṁ, tē mīṁ hara ēkkī gallī tē sēbbhī hālatana māṁ razanū, ḍhlukhunū tē badhanū ghaṭanū śikhōrūē.",null],[4,13,"ज़ै मीं ताकत देते तैस मां अवं सब किछ केरि बटताईं।","zai mīṁ tākata dētē taisa māṁ avaṁ saba kicha kēri baṭatāīṁ.",null],[4,14,"फिरी भी तुसेईं रोड़ू कियूं, कि मेरे दुखे मां मीं साथी भोए।","phirī bhī tusēīṁ rōṛū kiyūṁ, ki mērē dukhē māṁ mīṁ sāthī bhōē.",null],[4,15,"ते हे फिलिप्पियों, तुस एप्पू भी ज़ानतथ, कि खुशखबरी प्रचारेरे शुरुआती मां ज़ैखन अवं मकिदुनिया अग्रोवं जेव, तैखन मीं तुस शारे ते कोन्ची होरि मेनडलारे लोकेईं लेने देनेरे बारे मां मद्दत न की।","tē hē philippiyōṁ, tusa ēppū bhī zānatatha, ki khuśakhabarī pracārērē śuruātī māṁ zaikhana avaṁ makiduniyā agrōvaṁ jēva, taikhana mīṁ tusa śārē tē kōncī hōri mēnaḍalārē lōkēīṁ lēnē dēnērē bārē māṁ maddata na kī.",null],[4,16,"एन्च़रे ज़ैखन अवं थिस्सलुनीके नगरे मां थियो; तैखन भी तुसेईं मेरी घटी पूरी केरनेरे लेइ एक्की बार नईं बल्के काई बार किछ भेज़ेरू थियूं।","ēnc̈arē zaikhana avaṁ thissalunīkē nagarē māṁ thiyō; taikhana bhī tusēīṁ mērī ghaṭī pūrī kēranērē lēi ēkkī bāra naīṁ balkē kāī bāra kicha bhēzērū thiyūṁ.",null],[4,17,"इन नईं कि अवं दान चाताईं पन अवं एरो फल चाताईं, ज़ै तुश्शे फैइदेरे लेइ बड़तो गाए।","ina naīṁ ki avaṁ dāna cātāīṁ pana avaṁ ērō phala cātāīṁ, zai tuśśē phaiidērē lēi baṛatō gāē.",null],[4,18,"मीं कां सब किछे, बल्के बड़ू जादे, ज़ैन तुसेईं इपफ्रुदीतुसेरे हथ्थे भेज़ोरू थियूं, तैन मेलतां रज़ोरोई, तैन त खुशबू ते कबूल केरनेरे काबल बलिदाने, ज़ैन परमेशरे पसंदे।","mīṁ kāṁ saba kichē, balkē baṛū jādē, zaina tusēīṁ ipaphrudītusērē haththē bhēzōrū thiyūṁ, taina mēlatāṁ razōrōī, taina ta khuśabū tē kabūla kēranērē kābala balidānē, zaina paramēśarē pasaṁdē.",null],[4,19,"ते मेरो परमेशर भी अपने तैस धनेरे मुताबिक ज़ैन महिमा सेइं यीशु मसीह मांए, तुश्शी हर अक ज़रूरत पूरी केरेलो।","tē mērō paramēśara bhī apanē taisa dhanērē mutābika zaina mahimā sēiṁ yīśu masīha māṁē, tuśśī hara aka zarūrata pūrī kērēlō.",null],[4,20,"इश्शो परमेशर ते बाजी एरी महिमा हमेशा भोती राए। आमीन।","iśśō paramēśara tē bājī ērī mahimā hamēśā bhōtī rāē. āmīna.",null],[4,21,"हर अक पवित्र मैन्हु ज़ै यीशु मसीह मांए तैस जो नमस्कार ज़ोथ। ज़ै ढ्ला मीं साथीए तुसन नमस्कार ज़ोते।","hara aka pavitra mainhu zai yīśu masīha māṁē taisa jō namaskāra zōtha. zai ḍhlā mīṁ sāthīē tusana namaskāra zōtē.",null],[4,22,"सब पवित्र लोकन, खास केरतां ज़ैना महाराज़ेरे घरानेरेन तुसन नमस्कार ज़ोतन।","saba pavitra lōkana, khāsa kēratāṁ zainā mahārāzērē gharānērēna tusana namaskāra zōtana.",null],[4,23,"इश्शे प्रभु यीशु मसीहेरो अनुग्रह तुश्शी आत्माई सेइं साथी राए।","iśśē prabhu yīśu masīhērō anugraha tuśśī ātmāī sēiṁ sāthī rāē.",null]],"fin-kr1938":[[1,1,"Paavali ja Timoteus, Kristuksen Jeesuksen palvelijat, kaikille pyhille Kristuksessa Jeesuksessa, jotka ovat Filippissä, sekä myös seurakunnan kaitsijoille ja seurakuntapalvelijoille.","Paavali ja Timoteus, Kristuksen Jeesuksen palvelijat, kaikille pyhille Kristuksessa Jeesuksessa, jotka ovat Filippissä, sekä myös seurakunnan kaitsijoille ja seurakuntapalvelijoille.",null],[1,2,"Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!","Armo teille ja rauha Jumalalta, meidän Isältämme, ja Herralta Jeesukselta Kristukselta!",null],[1,3,"Minä kiitän Jumalaani, niin usein kuin teitä muistan,","Minä kiitän Jumalaani, niin usein kuin teitä muistan,",null],[1,4,"aina kaikissa rukouksissani ilolla rukoillen teidän kaikkien puolesta,","aina kaikissa rukouksissani ilolla rukoillen teidän kaikkien puolesta,",null],[1,5,"kiitän siitä, että olette olleet osallisia evankeliumiin ensi päivästä alkaen tähän päivään saakka,","kiitän siitä, että olette olleet osallisia evankeliumiin ensi päivästä alkaen tähän päivään saakka,",null],[1,6,"varmasti luottaen siihen, että hän, joka on alkanut teissä hyvän työn, on sen täyttävä Kristuksen Jeesuksen päivään saakka.","varmasti luottaen siihen, että hän, joka on alkanut teissä hyvän työn, on sen täyttävä Kristuksen Jeesuksen päivään saakka.",null],[1,7,"Ja oikein onkin, että minä näin ajattelen teitä kaikkia, koska te olette minun sydämessäni, te, jotka sekä ollessani kahleissa että evankeliumia puolustaessani ja vahvistaessani olette kaikki minun kanssani armosta osalliset.","Ja oikein onkin, että minä näin ajattelen teitä kaikkia, koska te olette minun sydämessäni, te, jotka sekä ollessani kahleissa että evankeliumia puolustaessani ja vahvistaessani olette kaikki minun kanssani armosta osalliset.",null],[1,8,"Sillä Jumala on minun todistajani, kuinka minä teitä kaikkia ikävöitsen Kristuksen Jeesuksen sydämellisellä rakkaudella.","Sillä Jumala on minun todistajani, kuinka minä teitä kaikkia ikävöitsen Kristuksen Jeesuksen sydämellisellä rakkaudella.",null],[1,9,"Ja sitä minä rukoilen, että teidän rakkautenne tulisi yhä runsaammaksi tiedossa ja kaikessa käsittämisessä,","Ja sitä minä rukoilen, että teidän rakkautenne tulisi yhä runsaammaksi tiedossa ja kaikessa käsittämisessä,",null],[1,10,"voidaksenne tutkia, mikä paras on, että te Kristuksen päivään saakka olisitte puhtaat ettekä kenellekään loukkaukseksi,","voidaksenne tutkia, mikä paras on, että te Kristuksen päivään saakka olisitte puhtaat ettekä kenellekään loukkaukseksi,",null],[1,11,"täynnä vanhurskauden hedelmää, jonka Jeesus Kristus saa aikaan, Jumalan kunniaksi ja ylistykseksi.","täynnä vanhurskauden hedelmää, jonka Jeesus Kristus saa aikaan, Jumalan kunniaksi ja ylistykseksi.",null],[1,12,"Mutta minä tahdon, että te, veljet, tietäisitte, että se, mitä minulle on tapahtunut, on koitunutkin evankeliumin menestykseksi,","Mutta minä tahdon, että te, veljet, tietäisitte, että se, mitä minulle on tapahtunut, on koitunutkin evankeliumin menestykseksi,",null],[1,13,"niin että koko henkivartioston ja kaikkien muiden tietoon on tullut, että minä olen kahleissa Kristuksen tähden,","niin että koko henkivartioston ja kaikkien muiden tietoon on tullut, että minä olen kahleissa Kristuksen tähden,",null],[1,14,"ja että useimmat veljistä, saaden Herrassa uskallusta minun kahleistani, yhä enemmän rohkenevat pelkäämättä puhua Jumalan sanaa.","ja että useimmat veljistä, saaden Herrassa uskallusta minun kahleistani, yhä enemmän rohkenevat pelkäämättä puhua Jumalan sanaa.",null],[1,15,"Muutamat tosin julistavat Kristusta kateudestakin ja riidan halusta, mutta toiset hyvässä tarkoituksessa:","Muutamat tosin julistavat Kristusta kateudestakin ja riidan halusta, mutta toiset hyvässä tarkoituksessa:",null],[1,16,"nämä tekevät sitä rakkaudesta, koska tietävät, että minut on pantu evankeliumia puolustamaan,","nämä tekevät sitä rakkaudesta, koska tietävät, että minut on pantu evankeliumia puolustamaan,",null],[1,17,"nuo toiset taas julistavat Kristusta itsekkyydestä, epäpuhtaalla mielellä, luullen tuottavansa minulle murhetta kahleissani.","nuo toiset taas julistavat Kristusta itsekkyydestä, epäpuhtaalla mielellä, luullen tuottavansa minulle murhetta kahleissani.",null],[1,18,"Vaan mitäpä tuosta, kunhan Kristusta vain tavalla tai toisella julistetaan, joko näön vuoksi tai totuudessa! Ja siitä minä iloitsen, ja olen vastakin iloitseva.","Vaan mitäpä tuosta, kunhan Kristusta vain tavalla tai toisella julistetaan, joko näön vuoksi tai totuudessa! Ja siitä minä iloitsen, ja olen vastakin iloitseva.",null],[1,19,"Sillä minä tiedän, että tämä on päättyvä minulle pelastukseksi teidän rukoustenne kautta ja Jeesuksen Kristuksen Hengen avulla,","Sillä minä tiedän, että tämä on päättyvä minulle pelastukseksi teidän rukoustenne kautta ja Jeesuksen Kristuksen Hengen avulla,",null],[1,20,"minun hartaan odotukseni ja toivoni mukaan, etten ole missään häpeään joutuva, vaan että Kristus nytkin, niinkuin aina, on tuleva ylistetyksi minun ruumiissani kaikella rohkeudella, joko elämän tai kuoleman kautta.","minun hartaan odotukseni ja toivoni mukaan, etten ole missään häpeään joutuva, vaan että Kristus nytkin, niinkuin aina, on tuleva ylistetyksi minun ruumiissani kaikella rohkeudella, joko elämän tai kuoleman kautta.",null],[1,21,"Sillä elämä on minulle Kristus, ja kuolema on voitto.","Sillä elämä on minulle Kristus, ja kuolema on voitto.",null],[1,22,"Mutta jos minun on eläminen täällä lihassa, niin siitä koituu hedelmää työlleni, ja silloin en tiedä, minkä valitsisin.","Mutta jos minun on eläminen täällä lihassa, niin siitä koituu hedelmää työlleni, ja silloin en tiedä, minkä valitsisin.",null],[1,23,"Ahtaalla minä olen näiden kahden välissä: halu minulla on täältä eritä ja olla Kristuksen kanssa, sillä se olisi monin verroin parempi;","Ahtaalla minä olen näiden kahden välissä: halu minulla on täältä eritä ja olla Kristuksen kanssa, sillä se olisi monin verroin parempi;",null],[1,24,"mutta teidän tähtenne on lihassa viipymiseni tarpeellisempi.","mutta teidän tähtenne on lihassa viipymiseni tarpeellisempi.",null],[1,25,"Ja kun olen tästä varma, niin minä tiedän jääväni eloon ja viipyväni kaikkien teidän luonanne teidän edistymiseksenne ja iloksenne uskossa,","Ja kun olen tästä varma, niin minä tiedän jääväni eloon ja viipyväni kaikkien teidän luonanne teidän edistymiseksenne ja iloksenne uskossa,",null],[1,26,"että teidän kerskaamisenne minusta olisi yhä runsaampi Kristuksessa Jeesuksessa, kun minä taas tulen teidän tykönne.","että teidän kerskaamisenne minusta olisi yhä runsaampi Kristuksessa Jeesuksessa, kun minä taas tulen teidän tykönne.",null],[1,27,"Käyttäytykää vain Kristuksen evankeliumin arvon mukaisesti, että minä, tulinpa sitten teidän tykönne ja näin teidät tai olin tulematta, saan kuulla teistä, että te pysytte samassa hengessä ja yksimielisinä taistelette minun kanssani evankeliumin uskon puolesta,","Käyttäytykää vain Kristuksen evankeliumin arvon mukaisesti, että minä, tulinpa sitten teidän tykönne ja näin teidät tai olin tulematta, saan kuulla teistä, että te pysytte samassa hengessä ja yksimielisinä taistelette minun kanssani evankeliumin uskon puolesta,",null],[1,28,"vastustajia missään kohden säikähtämättä; ja se on heille kadotuksen, mutta teille pelastuksen merkki, merkki Jumalalta.","vastustajia missään kohden säikähtämättä; ja se on heille kadotuksen, mutta teille pelastuksen merkki, merkki Jumalalta.",null],[1,29,"Sillä teidän on suotu, Kristuksen tähden, ei ainoastaan uskoa häneen, vaan myös kärsiä hänen tähtensä,","Sillä teidän on suotu, Kristuksen tähden, ei ainoastaan uskoa häneen, vaan myös kärsiä hänen tähtensä,",null],[1,30,"teidän, joilla on sama taistelu, mitä näitte ja nyt kuulette minun taistelevan.","teidän, joilla on sama taistelu, mitä näitte ja nyt kuulette minun taistelevan.",null],[2,1,"Jos siis on jotakin kehoitusta Kristuksessa, jos jotakin rakkauden lohdutusta, jos jotakin Hengen yhteyttä, jos jotakin sydämellisyyttä ja laupeutta,","Jos siis on jotakin kehoitusta Kristuksessa, jos jotakin rakkauden lohdutusta, jos jotakin Hengen yhteyttä, jos jotakin sydämellisyyttä ja laupeutta,",null],[2,2,"niin tehkää minun iloni täydelliseksi siten, että olette samaa mieltä, että teillä on sama rakkaus, että olette sopuisat ja yksimieliset","niin tehkää minun iloni täydelliseksi siten, että olette samaa mieltä, että teillä on sama rakkaus, että olette sopuisat ja yksimieliset",null],[2,3,"ettekä tee mitään itsekkyydestä tai turhan kunnian pyynnöstä, vaan että nöyryydessä pidätte toista parempana kuin itseänne","ettekä tee mitään itsekkyydestä tai turhan kunnian pyynnöstä, vaan että nöyryydessä pidätte toista parempana kuin itseänne",null],[2,4,"ja että katsotte kukin, ette vain omaanne, vaan toistenkin parasta.","ja että katsotte kukin, ette vain omaanne, vaan toistenkin parasta.",null],[2,5,"Olkoon teillä se mieli, joka myös Kristuksella Jeesuksella oli,","Olkoon teillä se mieli, joka myös Kristuksella Jeesuksella oli,",null],[2,6,"joka ei, vaikka hänellä olikin Jumalan muoto, katsonut saaliiksensa olla Jumalan kaltainen,","joka ei, vaikka hänellä olikin Jumalan muoto, katsonut saaliiksensa olla Jumalan kaltainen,",null],[2,7,"vaan tyhjensi itsensä ja otti orjan muodon, tuli ihmisten kaltaiseksi, ja hänet havaittiin olennaltaan sellaiseksi kuin ihminen;","vaan tyhjensi itsensä ja otti orjan muodon, tuli ihmisten kaltaiseksi, ja hänet havaittiin olennaltaan sellaiseksi kuin ihminen;",null],[2,8,"hän nöyryytti itsensä ja oli kuuliainen kuolemaan asti, hamaan ristin kuolemaan asti.","hän nöyryytti itsensä ja oli kuuliainen kuolemaan asti, hamaan ristin kuolemaan asti.",null],[2,9,"Sentähden onkin Jumala hänet korkealle korottanut ja antanut hänelle nimen, kaikkia muita nimiä korkeamman,","Sentähden onkin Jumala hänet korkealle korottanut ja antanut hänelle nimen, kaikkia muita nimiä korkeamman,",null],[2,10,"niin että kaikkien polvien pitää Jeesuksen nimeen notkistuman, sekä niitten, jotka taivaissa ovat, että niitten, jotka maan päällä ovat, ja niitten, jotka maan alla ovat,","niin että kaikkien polvien pitää Jeesuksen nimeen notkistuman, sekä niitten, jotka taivaissa ovat, että niitten, jotka maan päällä ovat, ja niitten, jotka maan alla ovat,",null],[2,11,"ja jokaisen kielen pitää tunnustaman Isän Jumalan kunniaksi, että Jeesus Kristus on Herra.","ja jokaisen kielen pitää tunnustaman Isän Jumalan kunniaksi, että Jeesus Kristus on Herra.",null],[2,12,"Siis, rakkaani, samoin kuin aina olette olleet kuuliaiset, niin ahkeroikaa, ei ainoastaan niinkuin silloin, kun minä olin teidän tykönänne, vaan paljoa enemmän nyt, kun olen poissa, pelolla ja vavistuksella, että pelastuisitte;","Siis, rakkaani, samoin kuin aina olette olleet kuuliaiset, niin ahkeroikaa, ei ainoastaan niinkuin silloin, kun minä olin teidän tykönänne, vaan paljoa enemmän nyt, kun olen poissa, pelolla ja vavistuksella, että pelastuisitte;",null],[2,13,"sillä Jumala on se, joka teissä vaikuttaa sekä tahtomisen että tekemisen, että hänen hyvä tahtonsa tapahtuisi.","sillä Jumala on se, joka teissä vaikuttaa sekä tahtomisen että tekemisen, että hänen hyvä tahtonsa tapahtuisi.",null],[2,14,"Tehkää kaikki nurisematta ja epäröimättä,","Tehkää kaikki nurisematta ja epäröimättä,",null],[2,15,"että olisitte moitteettomat ja puhtaat, olisitte tahrattomat Jumalan lapset kieron ja nurjan sukukunnan keskellä, joiden joukossa te loistatte niinkuin tähdet maailmassa,","että olisitte moitteettomat ja puhtaat, olisitte tahrattomat Jumalan lapset kieron ja nurjan sukukunnan keskellä, joiden joukossa te loistatte niinkuin tähdet maailmassa,",null],[2,16,"tarjolla pitäessänne elämän sanaa, ollen minulle kerskaukseksi Kristuksen päivänä siitä, etten ole turhaan juossut enkä turhaan vaivaa nähnyt.","tarjolla pitäessänne elämän sanaa, ollen minulle kerskaukseksi Kristuksen päivänä siitä, etten ole turhaan juossut enkä turhaan vaivaa nähnyt.",null],[2,17,"Vaan jos minut uhrataankin tehdessäni teidän uskonne uhri-ja palvelustoimitusta, niin minä kuitenkin iloitsen, ja iloitsen kaikkien teidän kanssanne;","Vaan jos minut uhrataankin tehdessäni teidän uskonne uhri-ja palvelustoimitusta, niin minä kuitenkin iloitsen, ja iloitsen kaikkien teidän kanssanne;",null],[2,18,"samoin iloitkaa tekin, ja iloitkaa minun kanssani!","samoin iloitkaa tekin, ja iloitkaa minun kanssani!",null],[2,19,"Toivon Herrassa Jeesuksessa pian voivani lähettää Timoteuksen teidän tykönne, että minäkin tulisin rohkaistuksi, saatuani tietää, kuinka teidän on.","Toivon Herrassa Jeesuksessa pian voivani lähettää Timoteuksen teidän tykönne, että minäkin tulisin rohkaistuksi, saatuani tietää, kuinka teidän on.",null],[2,20,"Sillä minulla ei ole ketään samanmielistä, joka vilpittömästi huolehtisi teidän tilastanne;","Sillä minulla ei ole ketään samanmielistä, joka vilpittömästi huolehtisi teidän tilastanne;",null],[2,21,"sillä kaikki he etsivät omaansa eivätkä sitä, mikä Kristuksen Jeesuksen on.","sillä kaikki he etsivät omaansa eivätkä sitä, mikä Kristuksen Jeesuksen on.",null],[2,22,"Mutta hänen koetellun mielensä te tunnette, että hän, niinkuin poika isäänsä, on minua palvellut evankeliumin työssä.","Mutta hänen koetellun mielensä te tunnette, että hän, niinkuin poika isäänsä, on minua palvellut evankeliumin työssä.",null],[2,23,"Hänet minä siis toivon voivani lähettää heti, kun olen saanut nähdä, miten minun käy.","Hänet minä siis toivon voivani lähettää heti, kun olen saanut nähdä, miten minun käy.",null],[2,24,"Ja minä luotan Herrassa siihen, että itsekin pian olen tuleva.","Ja minä luotan Herrassa siihen, että itsekin pian olen tuleva.",null],[2,25,"Katson kuitenkin välttämättömäksi palauttaa luoksenne veljeni, työkumppanini ja taistelutoverini Epafrodituksen, teidän lähettinne ja auttajan minun tarpeissani.","Katson kuitenkin välttämättömäksi palauttaa luoksenne veljeni, työkumppanini ja taistelutoverini Epafrodituksen, teidän lähettinne ja auttajan minun tarpeissani.",null],[2,26,"Sillä hän ikävöi teitä kaikkia ja on kovin levoton siitä, että olitte kuulleet hänen sairastavan.","Sillä hän ikävöi teitä kaikkia ja on kovin levoton siitä, että olitte kuulleet hänen sairastavan.",null],[2,27,"Ja hän olikin sairaana, kuoleman kielissä; mutta Jumala armahti häntä, eikä ainoastaan häntä, vaan myös minua, etten saisi murhetta murheen päälle.","Ja hän olikin sairaana, kuoleman kielissä; mutta Jumala armahti häntä, eikä ainoastaan häntä, vaan myös minua, etten saisi murhetta murheen päälle.",null],[2,28,"Lähetän hänet sentähden kiiruimmiten, että te hänet nähdessänne taas iloitsisitte ja minäkin olisin murheettomampi.","Lähetän hänet sentähden kiiruimmiten, että te hänet nähdessänne taas iloitsisitte ja minäkin olisin murheettomampi.",null],[2,29,"Ottakaa siis hänet vastaan Herrassa kaikella ilolla, ja pitäkää semmoisia kunniassa;","Ottakaa siis hänet vastaan Herrassa kaikella ilolla, ja pitäkää semmoisia kunniassa;",null],[2,30,"sillä Kristuksen työn tähden hän joutui aivan kuoleman partaalle, kun pani henkensä alttiiksi tehdäkseen minulle sen palveluksen, mitä te ette voineet tehdä.","sillä Kristuksen työn tähden hän joutui aivan kuoleman partaalle, kun pani henkensä alttiiksi tehdäkseen minulle sen palveluksen, mitä te ette voineet tehdä.",null],[3,1,"Sitten vielä, veljeni, iloitkaa Herrassa! Samoista asioista teille kirjoittaminen ei minua kyllästytä, ja teille se on turvaksi.","Sitten vielä, veljeni, iloitkaa Herrassa! Samoista asioista teille kirjoittaminen ei minua kyllästytä, ja teille se on turvaksi.",null],[3,2,"Kavahtakaa noita koiria, kavahtakaa noita pahoja työntekijöitä, kavahtakaa noita pilalleleikattuja.","Kavahtakaa noita koiria, kavahtakaa noita pahoja työntekijöitä, kavahtakaa noita pilalleleikattuja.",null],[3,3,"Sillä oikeita ympärileikattuja olemme me, jotka Jumalan Hengessä palvelemme Jumalaa ja kerskaamme Kristuksessa Jeesuksessa, emmekä luota lihaan,","Sillä oikeita ympärileikattuja olemme me, jotka Jumalan Hengessä palvelemme Jumalaa ja kerskaamme Kristuksessa Jeesuksessa, emmekä luota lihaan,",null],[3,4,"vaikka minulla on, mihin luottaa lihassakin. Jos kuka muu luulee voivansa luottaa lihaan, niin voin vielä enemmän minä,","vaikka minulla on, mihin luottaa lihassakin. Jos kuka muu luulee voivansa luottaa lihaan, niin voin vielä enemmän minä,",null],[3,5,"joka olen ympärileikattu kahdeksanpäiväisenä ja olen Israelin kansaa, Benjaminin sukukuntaa, hebrealainen hebrealaisista syntynyt, ollut lakiin nähden fariseus,","joka olen ympärileikattu kahdeksanpäiväisenä ja olen Israelin kansaa, Benjaminin sukukuntaa, hebrealainen hebrealaisista syntynyt, ollut lakiin nähden fariseus,",null],[3,6,"intoon nähden seurakunnan vainooja, lain vanhurskauteen nähden nuhteeton.","intoon nähden seurakunnan vainooja, lain vanhurskauteen nähden nuhteeton.",null],[3,7,"Mutta mikä minulle oli voitto, sen minä olen Kristuksen tähden lukenut tappioksi.","Mutta mikä minulle oli voitto, sen minä olen Kristuksen tähden lukenut tappioksi.",null],[3,8,"Niinpä minä todella luen kaikki tappioksi tuon ylen kalliin, Kristuksen Jeesuksen, minun Herrani, tuntemisen rinnalla, sillä hänen tähtensä minä olen menettänyt kaikki ja pidän sen roskana-että voittaisin omakseni Kristuksen","Niinpä minä todella luen kaikki tappioksi tuon ylen kalliin, Kristuksen Jeesuksen, minun Herrani, tuntemisen rinnalla, sillä hänen tähtensä minä olen menettänyt kaikki ja pidän sen roskana-että voittaisin omakseni Kristuksen",null],[3,9,"ja minun havaittaisiin olevan hänessä ja omistavan, ei omaa vanhurskautta, sitä, joka laista tulee, vaan sen, joka tulee Kristuksen uskon kautta, sen vanhurskauden, joka tulee Jumalasta uskon perusteella;","ja minun havaittaisiin olevan hänessä ja omistavan, ei omaa vanhurskautta, sitä, joka laista tulee, vaan sen, joka tulee Kristuksen uskon kautta, sen vanhurskauden, joka tulee Jumalasta uskon perusteella;",null],[3,10,"tunteakseni hänet ja hänen ylösnousemisensa voiman ja hänen kärsimyksiensä osallisuuden, tullessani hänen kaltaisekseen samankaltaisen kuoleman kautta,","tunteakseni hänet ja hänen ylösnousemisensa voiman ja hänen kärsimyksiensä osallisuuden, tullessani hänen kaltaisekseen samankaltaisen kuoleman kautta,",null],[3,11,"jos minä ehkä pääsen ylösnousemiseen kuolleista.","jos minä ehkä pääsen ylösnousemiseen kuolleista.",null],[3,12,"Ei niin, että jo olisin sen saavuttanut tai että jo olisin tullut täydelliseksi, vaan minä riennän sitä kohti, että minä sen omakseni voittaisin, koskapa Kristus Jeesus on voittanut minut.","Ei niin, että jo olisin sen saavuttanut tai että jo olisin tullut täydelliseksi, vaan minä riennän sitä kohti, että minä sen omakseni voittaisin, koskapa Kristus Jeesus on voittanut minut.",null],[3,13,"Veljet, minä en vielä katso sitä voittaneeni; mutta yhden minä teen: unhottaen sen, mikä on takana, ja kurottautuen sitä kohti, mikä on edessäpäin,","Veljet, minä en vielä katso sitä voittaneeni; mutta yhden minä teen: unhottaen sen, mikä on takana, ja kurottautuen sitä kohti, mikä on edessäpäin,",null],[3,14,"minä riennän kohti päämäärää, voittopalkintoa, johon Jumala on minut taivaallisella kutsumisella kutsunut Kristuksessa Jeesuksessa.","minä riennän kohti päämäärää, voittopalkintoa, johon Jumala on minut taivaallisella kutsumisella kutsunut Kristuksessa Jeesuksessa.",null],[3,15,"Olkoon siis meillä, niin monta kuin meitä on täydellistä, tämä mieli; ja jos teillä jossakin kohden on toinen mieli, niin Jumala on siinäkin teille ilmoittava, kuinka asia on.","Olkoon siis meillä, niin monta kuin meitä on täydellistä, tämä mieli; ja jos teillä jossakin kohden on toinen mieli, niin Jumala on siinäkin teille ilmoittava, kuinka asia on.",null],[3,16,"Kunhan vain, mihin saakka olemme ehtineetkin, vaellamme samaa tietä!","Kunhan vain, mihin saakka olemme ehtineetkin, vaellamme samaa tietä!",null],[3,17,"Olkaa minun seuraajiani, veljet, ja katselkaa niitä, jotka näin vaeltavat, niinkuin me olemme teille esikuvana.","Olkaa minun seuraajiani, veljet, ja katselkaa niitä, jotka näin vaeltavat, niinkuin me olemme teille esikuvana.",null],[3,18,"Sillä monet, joista usein olen sen teille sanonut ja nyt aivan itkien sanon, vaeltavat Kristuksen ristin vihollisina;","Sillä monet, joista usein olen sen teille sanonut ja nyt aivan itkien sanon, vaeltavat Kristuksen ristin vihollisina;",null],[3,19,"heidän loppunsa on kadotus, vatsa on heidän jumalansa, heidän kunnianaan on heidän häpeänsä, ja maallisiin on heidän mielensä.","heidän loppunsa on kadotus, vatsa on heidän jumalansa, heidän kunnianaan on heidän häpeänsä, ja maallisiin on heidän mielensä.",null],[3,20,"Mutta meillä on yhdyskuntamme taivaissa, ja sieltä me myös odotamme Herraa Jeesusta Kristusta Vapahtajaksi,","Mutta meillä on yhdyskuntamme taivaissa, ja sieltä me myös odotamme Herraa Jeesusta Kristusta Vapahtajaksi,",null],[3,21,"joka on muuttava meidän alennustilamme ruumiin kirkkautensa ruumiin kaltaiseksi sillä voimallaan, jolla hän myös voi tehdä kaikki itsellensä alamaiseksi.","joka on muuttava meidän alennustilamme ruumiin kirkkautensa ruumiin kaltaiseksi sillä voimallaan, jolla hän myös voi tehdä kaikki itsellensä alamaiseksi.",null],[4,1,"Sentähden, rakkaat ja ikävöidyt veljeni, te minun iloni ja kruununi, seisokaa näin Herrassa lujina, rakkaat!","Sentähden, rakkaat ja ikävöidyt veljeni, te minun iloni ja kruununi, seisokaa näin Herrassa lujina, rakkaat!",null],[4,2,"Euodiaa minä kehoitan ja Syntykeä minä kehoitan olemaan yksimielisiä Herrassa.","Euodiaa minä kehoitan ja Syntykeä minä kehoitan olemaan yksimielisiä Herrassa.",null],[4,3,"Myös sinua, sinä minun oikea Synsygukseni, minä pyydän: ole näille vaimoille avullinen, sillä he ovat taistelleet minun kanssani evankeliumin hyväksi, yhdessä sekä Klemensin että muiden työtoverieni kanssa, joiden nimet ovat elämän kirjassa.","Myös sinua, sinä minun oikea Synsygukseni, minä pyydän: ole näille vaimoille avullinen, sillä he ovat taistelleet minun kanssani evankeliumin hyväksi, yhdessä sekä Klemensin että muiden työtoverieni kanssa, joiden nimet ovat elämän kirjassa.",null],[4,4,"Iloitkaa aina Herrassa! Vieläkin minä sanon: iloitkaa!","Iloitkaa aina Herrassa! Vieläkin minä sanon: iloitkaa!",null],[4,5,"Tulkoon teidän lempeytenne kaikkien ihmisten tietoon. Herra on lähellä.","Tulkoon teidän lempeytenne kaikkien ihmisten tietoon. Herra on lähellä.",null],[4,6,"Älkää mistään murehtiko, vaan kaikessa saattakaa pyyntönne rukouksella ja anomisella kiitoksen kanssa Jumalalle tiettäväksi,","Älkää mistään murehtiko, vaan kaikessa saattakaa pyyntönne rukouksella ja anomisella kiitoksen kanssa Jumalalle tiettäväksi,",null],[4,7,"ja Jumalan rauha, joka on kaikkea ymmärrystä ylempi, on varjeleva teidän sydämenne ja ajatuksenne Kristuksessa Jeesuksessa.","ja Jumalan rauha, joka on kaikkea ymmärrystä ylempi, on varjeleva teidän sydämenne ja ajatuksenne Kristuksessa Jeesuksessa.",null],[4,8,"Ja vielä, veljet, kaikki, mikä on totta, mikä kunnioitettavaa, mikä oikeaa, mikä puhdasta, mikä rakastettavaa, mikä hyvältä kuuluvaa, jos on jokin avu ja jos on jotakin kiitettävää, sitä ajatelkaa;","Ja vielä, veljet, kaikki, mikä on totta, mikä kunnioitettavaa, mikä oikeaa, mikä puhdasta, mikä rakastettavaa, mikä hyvältä kuuluvaa, jos on jokin avu ja jos on jotakin kiitettävää, sitä ajatelkaa;",null],[4,9,"mitä myös olette oppineet ja saaneet ja minulta kuulleet ja minussa nähneet, sitä tehkää, niin rauhan Jumala on oleva teidän kanssanne.","mitä myös olette oppineet ja saaneet ja minulta kuulleet ja minussa nähneet, sitä tehkää, niin rauhan Jumala on oleva teidän kanssanne.",null],[4,10,"Minä ihastuin suuresti Herrassa, että te jo vihdoinkin olitte elpyneet pitämään minusta huolta, johon teillä ennenkin oli ollut halua, vaikka ei tilaisuutta.","Minä ihastuin suuresti Herrassa, että te jo vihdoinkin olitte elpyneet pitämään minusta huolta, johon teillä ennenkin oli ollut halua, vaikka ei tilaisuutta.",null],[4,11,"Ei niin, että minä puutteen vuoksi tätä sanon; sillä minä olen oppinut oloihini tyytymään.","Ei niin, että minä puutteen vuoksi tätä sanon; sillä minä olen oppinut oloihini tyytymään.",null],[4,12,"Osaan elää niukkuudessa, osaan myös elää runsaudessa; kaikkeen ja kaikenlaisiin oloihin minä olen tottunut; sekä olemaan ravittuna että näkemään nälkää, elämään sekä runsaudessa että puutteessa.","Osaan elää niukkuudessa, osaan myös elää runsaudessa; kaikkeen ja kaikenlaisiin oloihin minä olen tottunut; sekä olemaan ravittuna että näkemään nälkää, elämään sekä runsaudessa että puutteessa.",null],[4,13,"Kaikki minä voin hänessä, joka minua vahvistaa.","Kaikki minä voin hänessä, joka minua vahvistaa.",null],[4,14,"Kuitenkin teitte hyvin, kun otitte osaa minun ahdinkooni.","Kuitenkin teitte hyvin, kun otitte osaa minun ahdinkooni.",null],[4,15,"Tiedättehän tekin, filippiläiset, että evankeliumin alkuaikoina, kun lähdin Makedoniasta, ei mikään muu seurakunta kuin te yksin käynyt minun kanssani tiliyhteyteen annetusta ja vastaanotetusta.","Tiedättehän tekin, filippiläiset, että evankeliumin alkuaikoina, kun lähdin Makedoniasta, ei mikään muu seurakunta kuin te yksin käynyt minun kanssani tiliyhteyteen annetusta ja vastaanotetusta.",null],[4,16,"Sillä Tessalonikaankin te minulle kerran, jopa kahdesti, lähetitte, mitä tarvitsin.","Sillä Tessalonikaankin te minulle kerran, jopa kahdesti, lähetitte, mitä tarvitsin.",null],[4,17,"Ei niin, että haluaisin lahjaa, vaan minä haluan teidän hyväksenne karttuvaa hedelmää.","Ei niin, että haluaisin lahjaa, vaan minä haluan teidän hyväksenne karttuvaa hedelmää.",null],[4,18,"Olen nyt saanut kaikkea, jopa ylenpalttisesti; minulla on yllinkyllin, saatuani Epafroditukselta teidän lähetyksenne, joka on \"suloinen tuoksu\", otollinen, Jumalalle mieluinen uhri.","Olen nyt saanut kaikkea, jopa ylenpalttisesti; minulla on yllinkyllin, saatuani Epafroditukselta teidän lähetyksenne, joka on \"suloinen tuoksu\", otollinen, Jumalalle mieluinen uhri.",null],[4,19,"Mutta minun Jumalani on rikkautensa mukaisesti täyttävä kaikki teidän tarpeenne kirkkaudessa, Kristuksessa Jeesuksessa.","Mutta minun Jumalani on rikkautensa mukaisesti täyttävä kaikki teidän tarpeenne kirkkaudessa, Kristuksessa Jeesuksessa.",null],[4,20,"Mutta meidän Jumalallemme ja Isällemme kunnia aina ja iankaikkisesti! Amen.","Mutta meidän Jumalallemme ja Isällemme kunnia aina ja iankaikkisesti! Amen.",null],[4,21,"Tervehdys jokaiselle pyhälle Kristuksessa Jeesuksessa. Tervehdyksen lähettävät teille minun kanssani olevat veljet.","Tervehdys jokaiselle pyhälle Kristuksessa Jeesuksessa. Tervehdyksen lähettävät teille minun kanssani olevat veljet.",null],[4,22,"Tervehdyksen lähettävät teille kaikki pyhät, mutta varsinkin ne, jotka ovat keisarin huoneväkeä.","Tervehdyksen lähettävät teille kaikki pyhät, mutta varsinkin ne, jotka ovat keisarin huoneväkeä.",null],[4,23,"Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa.","Herran Jeesuksen Kristuksen armo olkoon teidän henkenne kanssa.",null]],"engwebp":[[1,1,"Paul and Timothy, servants of Jesus Christ, to all the saints in Christ Jesus who are at Philippi, with the overseers and servants:","Paul and Timothy, servants of Jesus Christ, to all the saints in Christ Jesus who are at Philippi, with the overseers and servants:",null],[1,2,"Grace to you and peace from God our Father and the Lord Jesus Christ.","Grace to you and peace from God our Father and the Lord Jesus Christ.",null],[1,3,"I thank my God whenever I remember you,","I thank my God whenever I remember you,",null],[1,4,"always in every request of mine on behalf of you all, making my requests with joy,","always in every request of mine on behalf of you all, making my requests with joy,",null],[1,5,"for your partnership in furtherance of the Good News from the first day until now;","for your partnership in furtherance of the Good News from the first day until now;",null],[1,6,"being confident of this very thing, that he who began a good work in you will complete it until the day of Jesus Christ.","being confident of this very thing, that he who began a good work in you will complete it until the day of Jesus Christ.",null],[1,7,"It is even right for me to think this way on behalf of all of you, because I have you in my heart, because both in my bonds and in the defense and confirmation of the Good News, you all are partakers with me of grace.","It is even right for me to think this way on behalf of all of you, because I have you in my heart, because both in my bonds and in the defense and confirmation of the Good News, you all are partakers with me of grace.",null],[1,8,"For God is my witness, how I long after all of you in the tender mercies of Christ Jesus.","For God is my witness, how I long after all of you in the tender mercies of Christ Jesus.",null],[1,9,"This I pray, that your love may abound yet more and more in knowledge and all discernment,","This I pray, that your love may abound yet more and more in knowledge and all discernment,",null],[1,10,"so that you may approve the things that are excellent, that you may be sincere and without offense to the day of Christ,","so that you may approve the things that are excellent, that you may be sincere and without offense to the day of Christ,",null],[1,11,"being filled with the fruits of righteousness which are through Jesus Christ, to the glory and praise of God.","being filled with the fruits of righteousness which are through Jesus Christ, to the glory and praise of God.",null],[1,12,"Now I desire to have you know, brothers, that the things which happened to me have turned out rather to the progress of the Good News,","Now I desire to have you know, brothers, that the things which happened to me have turned out rather to the progress of the Good News,",null],[1,13,"so that it became evident to the whole palace guard, and to all the rest, that my bonds are in Christ,","so that it became evident to the whole palace guard, and to all the rest, that my bonds are in Christ,",null],[1,14,"and that most of the brothers in the Lord, being confident through my bonds, are more abundantly bold to speak the word of God without fear.","and that most of the brothers in the Lord, being confident through my bonds, are more abundantly bold to speak the word of God without fear.",null],[1,15,"Some indeed preach Christ even out of envy and strife, and some also out of good will.","Some indeed preach Christ even out of envy and strife, and some also out of good will.",null],[1,16,"The former insincerely preach Christ from selfish ambition, thinking that they add affliction to my chains;","The former insincerely preach Christ from selfish ambition, thinking that they add affliction to my chains;",null],[1,17,"but the latter out of love, knowing that I am appointed for the defense of the Good News.","but the latter out of love, knowing that I am appointed for the defense of the Good News.",null],[1,18,"What does it matter? Only that in every way, whether in pretense or in truth, Christ is proclaimed. I rejoice in this, yes, and will rejoice.","What does it matter? Only that in every way, whether in pretense or in truth, Christ is proclaimed. I rejoice in this, yes, and will rejoice.",null],[1,19,"For I know that this will turn out to my salvation through your prayers and the supply of the Spirit of Jesus Christ,","For I know that this will turn out to my salvation through your prayers and the supply of the Spirit of Jesus Christ,",null],[1,20,"according to my earnest expectation and hope, that I will in no way be disappointed, but with all boldness, as always, now also Christ will be magnified in my body, whether by life or by death.","according to my earnest expectation and hope, that I will in no way be disappointed, but with all boldness, as always, now also Christ will be magnified in my body, whether by life or by death.",null],[1,21,"For to me to live is Christ, and to die is gain.","For to me to live is Christ, and to die is gain.",null],[1,22,"But if I live on in the flesh, this will bring fruit from my work; yet I don’t know what I will choose.","But if I live on in the flesh, this will bring fruit from my work; yet I don’t know what I will choose.",null],[1,23,"But I am hard pressed between the two, having the desire to depart and be with Christ, which is far better.","But I am hard pressed between the two, having the desire to depart and be with Christ, which is far better.",null],[1,24,"Yet to remain in the flesh is more needful for your sake.","Yet to remain in the flesh is more needful for your sake.",null],[1,25,"Having this confidence, I know that I will remain, yes, and remain with you all for your progress and joy in the faith,","Having this confidence, I know that I will remain, yes, and remain with you all for your progress and joy in the faith,",null],[1,26,"that your boasting may abound in Christ Jesus in me through my presence with you again.","that your boasting may abound in Christ Jesus in me through my presence with you again.",null],[1,27,"Only let your way of life be worthy of the Good News of Christ, that whether I come and see you or am absent, I may hear of your state, that you stand firm in one spirit, with one soul striving for the faith of the Good News;","Only let your way of life be worthy of the Good News of Christ, that whether I come and see you or am absent, I may hear of your state, that you stand firm in one spirit, with one soul striving for the faith of the Good News;",null],[1,28,"and in nothing frightened by the adversaries, which is for them a proof of destruction, but to you of salvation, and that from God.","and in nothing frightened by the adversaries, which is for them a proof of destruction, but to you of salvation, and that from God.",null],[1,29,"Because it has been granted to you on behalf of Christ, not only to believe in him, but also to suffer on his behalf,","Because it has been granted to you on behalf of Christ, not only to believe in him, but also to suffer on his behalf,",null],[1,30,"having the same conflict which you saw in me and now hear is in me.","having the same conflict which you saw in me and now hear is in me.",null],[2,1,"If therefore there is any exhortation in Christ, if any consolation of love, if any fellowship of the Spirit, if any tender mercies and compassion,","If therefore there is any exhortation in Christ, if any consolation of love, if any fellowship of the Spirit, if any tender mercies and compassion,",null],[2,2,"make my joy full by being like-minded, having the same love, being of one accord, of one mind;","make my joy full by being like-minded, having the same love, being of one accord, of one mind;",null],[2,3,"doing nothing through rivalry or through conceit, but in humility, each counting others better than himself;","doing nothing through rivalry or through conceit, but in humility, each counting others better than himself;",null],[2,4,"each of you not just looking to his own things, but each of you also to the things of others.","each of you not just looking to his own things, but each of you also to the things of others.",null],[2,5,"Have this in your mind, which was also in Christ Jesus,","Have this in your mind, which was also in Christ Jesus,",null],[2,6,"who, existing in the form of God, didn’t consider equality with God a thing to be grasped,","who, existing in the form of God, didn’t consider equality with God a thing to be grasped,",null],[2,7,"but emptied himself, taking the form of a servant, being made in the likeness of men.","but emptied himself, taking the form of a servant, being made in the likeness of men.",null],[2,8,"And being found in human form, he humbled himself, becoming obedient to the point of death, yes, the death of the cross.","And being found in human form, he humbled himself, becoming obedient to the point of death, yes, the death of the cross.",null],[2,9,"Therefore God also highly exalted him, and gave to him the name which is above every name,","Therefore God also highly exalted him, and gave to him the name which is above every name,",null],[2,10,"that at the name of Jesus every knee should bow, of those in heaven, those on earth, and those under the earth,","that at the name of Jesus every knee should bow, of those in heaven, those on earth, and those under the earth,",null],[2,11,"and that every tongue should confess that Jesus Christ is Lord, to the glory of God the Father.","and that every tongue should confess that Jesus Christ is Lord, to the glory of God the Father.",null],[2,12,"So then, my beloved, even as you have always obeyed, not only in my presence, but now much more in my absence, work out your own salvation with fear and trembling.","So then, my beloved, even as you have always obeyed, not only in my presence, but now much more in my absence, work out your own salvation with fear and trembling.",null],[2,13,"For it is God who works in you both to will and to work for his good pleasure.","For it is God who works in you both to will and to work for his good pleasure.",null],[2,14,"Do all things without complaining and arguing,","Do all things without complaining and arguing,",null],[2,15,"that you may become blameless and harmless, children of God without defect in the middle of a crooked and perverse generation, among whom you are seen as lights in the world,","that you may become blameless and harmless, children of God without defect in the middle of a crooked and perverse generation, among whom you are seen as lights in the world,",null],[2,16,"holding up the word of life, that I may have something to boast in the day of Christ that I didn’t run in vain nor labor in vain.","holding up the word of life, that I may have something to boast in the day of Christ that I didn’t run in vain nor labor in vain.",null],[2,17,"Yes, and if I am poured out on the sacrifice and service of your faith, I am glad and rejoice with you all.","Yes, and if I am poured out on the sacrifice and service of your faith, I am glad and rejoice with you all.",null],[2,18,"In the same way, you also should be glad and rejoice with me.","In the same way, you also should be glad and rejoice with me.",null],[2,19,"But I hope in the Lord Jesus to send Timothy to you soon, that I also may be cheered up when I know how you are doing.","But I hope in the Lord Jesus to send Timothy to you soon, that I also may be cheered up when I know how you are doing.",null],[2,20,"For I have no one else like-minded, who will truly care about you.","For I have no one else like-minded, who will truly care about you.",null],[2,21,"For they all seek their own, not the things of Jesus Christ.","For they all seek their own, not the things of Jesus Christ.",null],[2,22,"But you know that he has proved himself. As a child serves a father, so he served with me in furtherance of the Good News.","But you know that he has proved himself. As a child serves a father, so he served with me in furtherance of the Good News.",null],[2,23,"Therefore I hope to send him at once, as soon as I see how it will go with me.","Therefore I hope to send him at once, as soon as I see how it will go with me.",null],[2,24,"But I trust in the Lord that I myself also will come shortly.","But I trust in the Lord that I myself also will come shortly.",null],[2,25,"But I thought it necessary to send to you Epaphroditus, my brother, fellow worker, fellow soldier, and your apostle and servant of my need,","But I thought it necessary to send to you Epaphroditus, my brother, fellow worker, fellow soldier, and your apostle and servant of my need,",null],[2,26,"since he longed for you all, and was very troubled because you had heard that he was sick.","since he longed for you all, and was very troubled because you had heard that he was sick.",null],[2,27,"For indeed he was sick nearly to death, but God had mercy on him, and not on him only, but on me also, that I might not have sorrow on sorrow.","For indeed he was sick nearly to death, but God had mercy on him, and not on him only, but on me also, that I might not have sorrow on sorrow.",null],[2,28,"I have sent him therefore the more diligently, that when you see him again, you may rejoice, and that I may be the less sorrowful.","I have sent him therefore the more diligently, that when you see him again, you may rejoice, and that I may be the less sorrowful.",null],[2,29,"Receive him therefore in the Lord with all joy, and hold such people in honor,","Receive him therefore in the Lord with all joy, and hold such people in honor,",null],[2,30,"because for the work of Christ he came near to death, risking his life to supply that which was lacking in your service toward me.","because for the work of Christ he came near to death, risking his life to supply that which was lacking in your service toward me.",null],[3,1,"Finally, my brothers, rejoice in the Lord! To write the same things to you, to me indeed is not tiresome, but for you it is safe.","Finally, my brothers, rejoice in the Lord! To write the same things to you, to me indeed is not tiresome, but for you it is safe.",null],[3,2,"Beware of the dogs; beware of the evil workers; beware of the false circumcision.","Beware of the dogs; beware of the evil workers; beware of the false circumcision.",null],[3,3,"For we are the circumcision, who worship God in the Spirit, and rejoice in Christ Jesus, and have no confidence in the flesh;","For we are the circumcision, who worship God in the Spirit, and rejoice in Christ Jesus, and have no confidence in the flesh;",null],[3,4,"though I myself might have confidence even in the flesh. If any other man thinks that he has confidence in the flesh, I yet more:","though I myself might have confidence even in the flesh. If any other man thinks that he has confidence in the flesh, I yet more:",null],[3,5,"circumcised the eighth day, of the stock of Israel, of the tribe of Benjamin, a Hebrew of Hebrews; concerning the law, a Pharisee;","circumcised the eighth day, of the stock of Israel, of the tribe of Benjamin, a Hebrew of Hebrews; concerning the law, a Pharisee;",null],[3,6,"concerning zeal, persecuting the assembly; concerning the righteousness which is in the law, found blameless.","concerning zeal, persecuting the assembly; concerning the righteousness which is in the law, found blameless.",null],[3,7,"However, I consider those things that were gain to me as a loss for Christ.","However, I consider those things that were gain to me as a loss for Christ.",null],[3,8,"Yes most certainly, and I count all things to be a loss for the excellency of the knowledge of Christ Jesus, my Lord, for whom I suffered the loss of all things, and count them nothing but refuse, that I may gain Christ","Yes most certainly, and I count all things to be a loss for the excellency of the knowledge of Christ Jesus, my Lord, for whom I suffered the loss of all things, and count them nothing but refuse, that I may gain Christ",null],[3,9,"and be found in him, not having a righteousness of my own, that which is of the law, but that which is through faith in Christ, the righteousness which is from God by faith,","and be found in him, not having a righteousness of my own, that which is of the law, but that which is through faith in Christ, the righteousness which is from God by faith,",null],[3,10,"that I may know him and the power of his resurrection, and the fellowship of his sufferings, becoming conformed to his death,","that I may know him and the power of his resurrection, and the fellowship of his sufferings, becoming conformed to his death,",null],[3,11,"if by any means I may attain to the resurrection from the dead.","if by any means I may attain to the resurrection from the dead.",null],[3,12,"Not that I have already obtained, or am already made perfect; but I press on, that I may take hold of that for which also I was taken hold of by Christ Jesus.","Not that I have already obtained, or am already made perfect; but I press on, that I may take hold of that for which also I was taken hold of by Christ Jesus.",null],[3,13,"Brothers, I don’t regard myself as yet having taken hold, but one thing I do: forgetting the things which are behind and stretching forward to the things which are before,","Brothers, I don’t regard myself as yet having taken hold, but one thing I do: forgetting the things which are behind and stretching forward to the things which are before,",null],[3,14,"I press on toward the goal for the prize of the high calling of God in Christ Jesus.","I press on toward the goal for the prize of the high calling of God in Christ Jesus.",null],[3,15,"Let us therefore, as many as are perfect, think this way. If in anything you think otherwise, God will also reveal that to you.","Let us therefore, as many as are perfect, think this way. If in anything you think otherwise, God will also reveal that to you.",null],[3,16,"Nevertheless, to the extent that we have already attained, let’s walk by the same rule. Let’s be of the same mind.","Nevertheless, to the extent that we have already attained, let’s walk by the same rule. Let’s be of the same mind.",null],[3,17,"Brothers, be imitators together of me, and note those who walk this way, even as you have us for an example.","Brothers, be imitators together of me, and note those who walk this way, even as you have us for an example.",null],[3,18,"For many walk, of whom I told you often, and now tell you even weeping, as the enemies of the cross of Christ,","For many walk, of whom I told you often, and now tell you even weeping, as the enemies of the cross of Christ,",null],[3,19,"whose end is destruction, whose god is the belly, and whose glory is in their shame, who think about earthly things.","whose end is destruction, whose god is the belly, and whose glory is in their shame, who think about earthly things.",null],[3,20,"For our citizenship is in heaven, from where we also wait for a Savior, the Lord Jesus Christ,","For our citizenship is in heaven, from where we also wait for a Savior, the Lord Jesus Christ,",null],[3,21,"who will change the body of our humiliation to be conformed to the body of his glory, according to the working by which he is able even to subject all things to himself.","who will change the body of our humiliation to be conformed to the body of his glory, according to the working by which he is able even to subject all things to himself.",null],[4,1,"Therefore, my brothers, beloved and longed for, my joy and crown, stand firm in the Lord in this way, my beloved.","Therefore, my brothers, beloved and longed for, my joy and crown, stand firm in the Lord in this way, my beloved.",null],[4,2,"I exhort Euodia, and I exhort Syntyche, to think the same way in the Lord.","I exhort Euodia, and I exhort Syntyche, to think the same way in the Lord.",null],[4,3,"Yes, I beg you also, true partner, help these women, for they labored with me in the Good News with Clement also, and the rest of my fellow workers, whose names are in the book of life.","Yes, I beg you also, true partner, help these women, for they labored with me in the Good News with Clement also, and the rest of my fellow workers, whose names are in the book of life.",null],[4,4,"Rejoice in the Lord always! Again I will say, “Rejoice!”","Rejoice in the Lord always! Again I will say, “Rejoice!”",null],[4,5,"Let your gentleness be known to all men. The Lord is at hand.","Let your gentleness be known to all men. The Lord is at hand.",null],[4,6,"In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God.","In nothing be anxious, but in everything, by prayer and petition with thanksgiving, let your requests be made known to God.",null],[4,7,"And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.","And the peace of God, which surpasses all understanding, will guard your hearts and your thoughts in Christ Jesus.",null],[4,8,"Finally, brothers, whatever things are true, whatever things are honorable, whatever things are just, whatever things are pure, whatever things are lovely, whatever things are of good report: if there is any virtue and if there is anything worthy of praise, think about these things.","Finally, brothers, whatever things are true, whatever things are honorable, whatever things are just, whatever things are pure, whatever things are lovely, whatever things are of good report: if there is any virtue and if there is anything worthy of praise, think about these things.",null],[4,9,"Do the things which you learned, received, heard, and saw in me, and the God of peace will be with you.","Do the things which you learned, received, heard, and saw in me, and the God of peace will be with you.",null],[4,10,"But I rejoice in the Lord greatly that now at length you have revived your thought for me; in which you did indeed take thought, but you lacked opportunity.","But I rejoice in the Lord greatly that now at length you have revived your thought for me; in which you did indeed take thought, but you lacked opportunity.",null],[4,11,"Not that I speak because of lack, for I have learned in whatever state I am, to be content in it.","Not that I speak because of lack, for I have learned in whatever state I am, to be content in it.",null],[4,12,"I know how to be humbled, and I also know how to abound. In any and all circumstances I have learned the secret both to be filled and to be hungry, both to abound and to be in need.","I know how to be humbled, and I also know how to abound. In any and all circumstances I have learned the secret both to be filled and to be hungry, both to abound and to be in need.",null],[4,13,"I can do all things through Christ who strengthens me.","I can do all things through Christ who strengthens me.",null],[4,14,"However you did well that you shared in my affliction.","However you did well that you shared in my affliction.",null],[4,15,"You yourselves also know, you Philippians, that in the beginning of the Good News, when I departed from Macedonia, no assembly shared with me in the matter of giving and receiving but you only.","You yourselves also know, you Philippians, that in the beginning of the Good News, when I departed from Macedonia, no assembly shared with me in the matter of giving and receiving but you only.",null],[4,16,"For even in Thessalonica you sent once and again to my need.","For even in Thessalonica you sent once and again to my need.",null],[4,17,"Not that I seek for the gift, but I seek for the fruit that increases to your account.","Not that I seek for the gift, but I seek for the fruit that increases to your account.",null],[4,18,"But I have all things and abound. I am filled, having received from Epaphroditus the things that came from you, a sweet-smelling fragrance, an acceptable and well-pleasing sacrifice to God.","But I have all things and abound. I am filled, having received from Epaphroditus the things that came from you, a sweet-smelling fragrance, an acceptable and well-pleasing sacrifice to God.",null],[4,19,"My God will supply every need of yours according to his riches in glory in Christ Jesus.","My God will supply every need of yours according to his riches in glory in Christ Jesus.",null],[4,20,"Now to our God and Father be the glory forever and ever! Amen.","Now to our God and Father be the glory forever and ever! Amen.",null],[4,21,"Greet every saint in Christ Jesus. The brothers who are with me greet you.","Greet every saint in Christ Jesus. The brothers who are with me greet you.",null],[4,22,"All the saints greet you, especially those who are of Caesar’s household.","All the saints greet you, especially those who are of Caesar’s household.",null],[4,23,"The grace of the Lord Jesus Christ be with you all. Amen.","The grace of the Lord Jesus Christ be with you all. Amen.",null]],"benirv":[[1,1,"পৌল ও তীমথিয়, খ্রীষ্ট যীশুর দাস, খ্রীষ্ট যীশুতে যত পবিত্র লোক ফিলিপীতে আছেন, তাঁদের এবং, পালকদের পরিচারকদের ও খ্রীষ্টে পবিত্র জনেদের কাছে।","paula ō tīmathiẏa, khrīṣṭa yīśura dāsa, khrīṣṭa yīśutē yata pabitra lōka philipītē āchēna, tām̐dēra ēbaṁ, pālakadēra paricārakadēra ō khrīṣṭē pabitra janēdēra kāchē.",null],[1,2,"আমাদের পিতা ঈশ্বরও প্রভু যীশু খ্রীষ্ট থেকে অনুগ্রহ ও শান্তি তোমাদের প্রতি আসুক।","āmādēra pitā īśbaraō prabhu yīśu khrīṣṭa thēkē anugraha ō śānti tōmādēra prati āsuka.",null],[1,3,"তোমাদের কথা মনে করে আমি ঈশ্বরকে ধন্যবাদ দিই,","tōmādēra kathā manē karē āmi īśbarakē dhanyabāda dii,",null],[1,4,"সবদিন আমি তোমাদের জন্য প্রার্থনা করি, এটাই হল সবদিন এক আনন্দের প্রার্থনা;","sabadina āmi tōmādēra janya prārthanā kari, ēṭāi hala sabadina ēka ānandēra prārthanā;",null],[1,5,"আমি প্রথম দিন থেকে আজ পর্যন্ত সুসমাচারের পক্ষে তোমাদের সহভাগীতায় আছি।","āmi prathama dina thēkē āja paryanta susamācārēra pakṣē tōmādēra sahabhāgītāẏa āchi.",null],[1,6,"এতে আমার দৃঢ় বিশ্বাস এই যে, তোমাদের মধ্যে যিনি ভালো কাজ শুরু করেছেন, তিনি যীশু খ্রীষ্টের আসবার দিন পর্যন্ত তা সম্পূর্ণ করবেন।","ētē āmāra dr̥ṛha biśbāsa ēi yē, tōmādēra madhyē yini bhālō kāja śuru karēchēna, tini yīśu khrīṣṭēra āsabāra dina paryanta tā sampūrṇa karabēna.",null],[1,7,"আর তোমাদের সবার বিষয়ে আমার এই চিন্তা করাই উচিত; কারণ আমি তোমাদেরকে মনের মধ্যে রাখি; কারণ আমার কারাগারে থাকা এবং সুসমাচারের পক্ষে ও সততা সম্বন্ধে তোমরা সবাই আমার সাথে অনুগ্রহের সহভাগী হয়েছ।","āra tōmādēra sabāra biṣaẏē āmāra ēi cintā karāi ucita; kāraṇa āmi tōmādērakē manēra madhyē rākhi; kāraṇa āmāra kārāgārē thākā ēbaṁ susamācārēra pakṣē ō satatā sambandhē tōmarā sabāi āmāra sāthē anugrahēra sahabhāgī haẏēcha.",null],[1,8,"ঈশ্বর আমার সাক্ষী যে, খ্রীষ্ট যীশুর ভালবাসায় আমার হৃদয় তোমাদের সবার জন্য কেমন আকাঙ্ক্ষী।","īśbara āmāra sākṣī yē, khrīṣṭa yīśura bhālabāsāẏa āmāra hr̥daẏa tōmādēra sabāra janya kēmana ākāṅkṣī.",null],[1,9,"আর আমি এই প্রার্থনা করি যেন, তোমাদের ভালবাসা যেন সব রকম ও সম্পূর্ণ বিচার বুদ্ধিতে আরো আরো বৃদ্ধি পায়;","āra āmi ēi prārthanā kari yēna, tōmādēra bhālabāsā yēna saba rakama ō sampūrṇa bicāra buddhitē ārō ārō br̥ddhi pāẏa;",null],[1,10,"এই ভাবে তোমরা যেন, যা যা বিভিন্ন ধরনের, তা পরীক্ষা করে চিনতে পার, খ্রীষ্টের দিন পর্যন্ত যেন তোমরা শুদ্ধ ও নির্দোষ থাক,","ēi bhābē tōmarā yēna, yā yā bibhinna dharanēra, tā parīkṣā karē cinatē pāra, khrīṣṭēra dina paryanta yēna tōmarā śuddha ō nirdōṣa thāka,",null],[1,11,"যেন সেই ধার্মিকতার সেই ফলে পূর্ণ হও, যা যীশু খ্রীষ্টের মাধ্যমে পাওয়া যায়, এই ভাবে যেন ঈশ্বরের গৌরব ও প্রশংসা হয়।","yēna sēi dhārmikatāra sēi phalē pūrṇa haō, yā yīśu khrīṣṭēra mādhyamē pāōẏā yāẏa, ēi bhābē yēna īśbarēra gauraba ō praśaṁsā haẏa.",null],[1,12,"এখন হে ভাইয়েরা, আমার ইচ্ছা এই যে, তোমরা জান, আমার সম্বন্ধে যা যা ঘটেছে, তার মাধ্যমে সুসমাচারের প্রচারের কাজ এগিয়ে গেছে;","ēkhana hē bhāiẏērā, āmāra icchā ēi yē, tōmarā jāna, āmāra sambandhē yā yā ghaṭēchē, tāra mādhyamē susamācārēra pracārēra kāja ēgiẏē gēchē;",null],[1,13,"বিশেষভাবে সব প্রাসাদ রক্ষীবাহিনী এবং অন্য সবাই জানে যে আমি খ্রীষ্ট বিশ্বাসী বলে কারাগারে রয়েছি;","biśēṣabhābē saba prāsāda rakṣībāhinī ēbaṁ anya sabāi jānē yē āmi khrīṣṭa biśbāsī balē kārāgārē raẏēchi;",null],[1,14,"এবং প্রভুতে বিশ্বাসী অনেক ভাই আমার কারাবাসের কারণে দৃঢ়বিশ্বাসী হয়ে নির্ভয়ে ঈশ্বরের বাক্য বলতে অধিক সাহসী হয়েছে।","ēbaṁ prabhutē biśbāsī anēka bhāi āmāra kārābāsēra kāraṇē dr̥ṛhabiśbāsī haẏē nirbhaẏē īśbarēra bākya balatē adhika sāhasī haẏēchē.",null],[1,15,"কেউ কেউ ঈর্ষা এবং বিবাদের মনোভাবের সঙ্গে, আর কেউ কেউ ভালো ইচ্ছার সঙ্গে খ্রীষ্টকে প্রচার করছে।","kēu kēu īrṣā ēbaṁ bibādēra manōbhābēra saṅgē, āra kēu kēu bhālō icchāra saṅgē khrīṣṭakē pracāra karachē.",null],[1,16,"এই লোকেদের মনে ভালবাসা আছে বলেই তারা খ্রীষ্টের বিষয়ে প্রচার করছে, কারণ জানে যে, আমি সুসমাচারের পক্ষে সমর্থন করতে নিযুক্ত রয়েছি।","ēi lōkēdēra manē bhālabāsā āchē balēi tārā khrīṣṭēra biṣaẏē pracāra karachē, kāraṇa jānē yē, āmi susamācārēra pakṣē samarthana karatē niyukta raẏēchi.",null],[1,17,"কিন্তু ওরা স্বার্থপরভাবে এবং অপবিত্রভাবে খ্রীষ্টকে প্রচার করছে, তারা মনে করছে যে আমার কারাবাস আরো কষ্টকর করবে।","kintu ōrā sbārthaparabhābē ēbaṁ apabitrabhābē khrīṣṭakē pracāra karachē, tārā manē karachē yē āmāra kārābāsa ārō kaṣṭakara karabē.",null],[1,18,"তবে কি? উভয় ক্ষেত্রেই, কিনা ভণ্ডামিতে অথবা সত্যভাবে, যে কোনো ভাবে হোক, খ্রীষ্ট প্রচারিত হচ্ছেন; আর এতেই আমি আনন্দ করছি, হ্যাঁ, আমি আনন্দ করব।","tabē ki? ubhaẏa kṣētrēi, kinā bhaṇḍāmitē athabā satyabhābē, yē kōnō bhābē hōka, khrīṣṭa pracārita hacchēna; āra ētēi āmi ānanda karachi, hyām̐, āmi ānanda karaba.",null],[1,19,"কারণ আমি জানি, তোমাদের প্রার্থনা এবং যীশু খ্রীষ্টের আত্মার যোগদানের মাধ্যমে এটা আমার পরিত্রানের স্বপক্ষে হবে।","kāraṇa āmi jāni, tōmādēra prārthanā ēbaṁ yīśu khrīṣṭēra ātmāra yōgadānēra mādhyamē ēṭā āmāra paritrānēra sbapakṣē habē.",null],[1,20,"এই ভাবে আমার ঐকান্তিক প্রতীক্ষা ও প্রত্যাশা এই যে, আমি কোনোভাবে লজ্জিত হব না, কিন্তু সম্পূর্ণ সাহসের সঙ্গে, যেমন সবদিন তেমনি এখনও, খ্রীষ্ট জীবনের মাধ্যমে হোক, কি মৃত্যুর মাধ্যমে হোক, আমার মধ্য দিয়ে খ্রীষ্ট শরীরে মহিমান্বিত হবেন।","ēi bhābē āmāra aikāntika pratīkṣā ō pratyāśā ēi yē, āmi kōnōbhābē lajjita haba nā, kintu sampūrṇa sāhasēra saṅgē, yēmana sabadina tēmani ēkhanaō, khrīṣṭa jībanēra mādhyamē hōka, ki mr̥tyura mādhyamē hōka, āmāra madhya diẏē khrīṣṭa śarīrē mahimānbita habēna.",null],[1,21,"কারণ আমার পক্ষে জীবন হল খ্রীষ্ট এবং মরণ হল লাভ।","kāraṇa āmāra pakṣē jībana hala khrīṣṭa ēbaṁ maraṇa hala lābha.",null],[1,22,"কিন্তু শরীরে যে জীবন, তাই যদি আমার কাজের ফল হয়, তবে কোনটা আমি বেছে নেব, তা জানি না।","kintu śarīrē yē jībana, tāi yadi āmāra kājēra phala haẏa, tabē kōnaṭā āmi bēchē nēba, tā jāni nā.",null],[1,23,"অথচ আমি দোটানায় পড়েছি; আমার ইচ্ছা এই যে, মারা গিয়ে খ্রীষ্টের সঙ্গে থাকি, কারণ তা অনেক ভালো","athaca āmi dōṭānāẏa paṛēchi; āmāra icchā ēi yē, mārā giẏē khrīṣṭēra saṅgē thāki, kāraṇa tā anēka bhālō",null],[1,24,"কিন্তু শরীরে বেঁচে থাকা তোমাদের জন্য বেশি দরকার।","kintu śarīrē bēm̐cē thākā tōmādēra janya bēśi darakāra.",null],[1,25,"আর এই দৃঢ় বিশ্বাস আছে বলে আমি জানি যে থাকবো, এমনকি, বিশ্বাসে তোমাদের উন্নতি ও আনন্দের জন্য তোমাদের সবার কাছে থাকব,","āra ēi dr̥ṛha biśbāsa āchē balē āmi jāni yē thākabō, ēmanaki, biśbāsē tōmādēra unnati ō ānandēra janya tōmādēra sabāra kāchē thākaba,",null],[1,26,"যেন তোমাদের কাছে আমার আবার আসার মাধ্যমে খ্রীষ্ট যীশুতে তোমাদের আমাকে নিয়ে আনন্দ উপচে পড়ে।","yēna tōmādēra kāchē āmāra ābāra āsāra mādhyamē khrīṣṭa yīśutē tōmādēra āmākē niẏē ānanda upacē paṛē.",null],[1,27,"কেবল, খ্রীষ্টের সুসমাচারের যোগ্যভাবে তাঁর প্রজাদের মতো আচরণ কর; তাহলে আমি এসে তোমাদের দেখি, কি অনুপস্থিত থাকি, আমি যেন তোমাদের বিষয়ে শুনতে পাই যে, তোমরা এক আত্মাতে দৃঢ় আছ, এক প্রাণে সুসমাচারের বিশ্বাসের পক্ষে কঠোর সংগ্রাম করছ;","kēbala, khrīṣṭēra susamācārēra yōgyabhābē tām̐ra prajādēra matō ācaraṇa kara; tāhalē āmi ēsē tōmādēra dēkhi, ki anupasthita thāki, āmi yēna tōmādēra biṣaẏē śunatē pāi yē, tōmarā ēka ātmātē dr̥ṛha ācha, ēka prāṇē susamācārēra biśbāsēra pakṣē kaṭhōra saṁgrāma karacha;",null],[1,28,"এবং কোনো বিষয়ে বিপক্ষদের দ্বারা ভীত হচ্ছে না; এতেই প্রমাণ হবে তা ওদের বিনাশের জন্য, কিন্তু তোমাদের পরিত্রানের প্রমাণ, আর এটি ঈশ্বর থেকেই আসে।","ēbaṁ kōnō biṣaẏē bipakṣadēra dbārā bhīta hacchē nā; ētēi pramāṇa habē tā ōdēra bināśēra janya, kintu tōmādēra paritrānēra pramāṇa, āra ēṭi īśbara thēkēi āsē.",null],[1,29,"যেহেতু তোমাদের খ্রীষ্টের জন্য এই আশীর্বাদ দেওয়া হয়েছে, যেন কেবল তাঁতে বিশ্বাস কর, তা নয়, কিন্তু তাঁর জন্য দুঃখভোগও কর;","yēhētu tōmādēra khrīṣṭēra janya ēi āśīrbāda dēōẏā haẏēchē, yēna kēbala tām̐tē biśbāsa kara, tā naẏa, kintu tām̐ra janya duḥkhabhōgaō kara;",null],[1,30,"কারণ আমার মধ্যে যেরূপ দেখেছ এবং এখনও সেই সম্মন্ধে যা শুনেছ, সেইরূপ সংগ্রাম তোমাদেরও হচ্ছে।","kāraṇa āmāra madhyē yērūpa dēkhēcha ēbaṁ ēkhanaō sēi sammandhē yā śunēcha, sēirūpa saṁgrāma tōmādēraō hacchē.",null],[2,1,"অতএব খ্রীষ্টে যদি কোনো উত্সাহ, যদি কোনো ভালবাসার সান্ত্বনা, যদি কোনো পবিত্র আত্মার সহভাগীতা, যদি কোনো দয়া ও করুণা হৃদয়ে থাকে,","ataēba khrīṣṭē yadi kōnō utsāha, yadi kōnō bhālabāsāra sāntbanā, yadi kōnō pabitra ātmāra sahabhāgītā, yadi kōnō daẏā ō karuṇā hr̥daẏē thākē,",null],[2,2,"তবে তোমরা আমার আনন্দ পূর্ণ কর একমন, এক ভালবাসা, এক প্রাণ, এক ভাববিশিষ্ট হও।","tabē tōmarā āmāra ānanda pūrṇa kara ēkamana, ēka bhālabāsā, ēka prāṇa, ēka bhābabiśiṣṭa haō.",null],[2,3,"প্রতিযোগিতার কিংবা স্বার্থপরতার বশে কিছুই কর না, কিন্তু শান্তভাবে প্রত্যেক জন নিজের থেকে অন্যকে শ্রেষ্ঠ বলে মনে কর;","pratiyōgitāra kiṁbā sbārthaparatāra baśē kichui kara nā, kintu śāntabhābē pratyēka jana nijēra thēkē anyakē śrēṣṭha balē manē kara;",null],[2,4,"এবং প্রত্যেক জন নিজের বিষয়ে না, কিন্তু পরের বিষয়েও লক্ষ্য রাখ।","ēbaṁ pratyēka jana nijēra biṣaẏē nā, kintu parēra biṣaẏēō lakṣya rākha.",null],[2,5,"খ্রীষ্ট যীশুতে যে ভাব ছিল, তা তোমাদের মনের মধ্যেও হোক।","khrīṣṭa yīśutē yē bhāba chila, tā tōmādēra manēra madhyēō hōka.",null],[2,6,"ঈশ্বরের স্বরূপবিশিষ্ট থাকতেও তিনি ঈশ্বরের সাথে সমান ইচ্ছা মনে করলেন না,","īśbarēra sbarūpabiśiṣṭa thākatēō tini īśbarēra sāthē samāna icchā manē karalēna nā,",null],[2,7,"কিন্তু নিজেকে শূন্য করলেন, তিনি দাসের মত হলেন, মানুষের মত হয়ে জন্ম নিলেন;","kintu nijēkē śūnya karalēna, tini dāsēra mata halēna, mānuṣēra mata haẏē janma nilēna;",null],[2,8,"এবং তিনি মানুষের মত হয়ে নিজেকে অবনত করলেন; মৃত্যু পর্যন্ত, এমনকি, ক্রুশীয় মৃত্যু পর্যন্ত আজ্ঞাবহ হলেন।","ēbaṁ tini mānuṣēra mata haẏē nijēkē abanata karalēna; mr̥tyu paryanta, ēmanaki, kruśīẏa mr̥tyu paryanta ājñābaha halēna.",null],[2,9,"এই কারণ ঈশ্বর তাঁকে অত্যন্ত উচ্চমর্যাদা সম্পন্ন করলেন এবং তাঁকে সেই নাম দান করলেন, যা প্রত্যেক নামের থেকে শ্রেষ্ঠ;","ēi kāraṇa īśbara tām̐kē atyanta uccamaryādā sampanna karalēna ēbaṁ tām̐kē sēi nāma dāna karalēna, yā pratyēka nāmēra thēkē śrēṣṭha;",null],[2,10,"যেন যীশুর নামে স্বর্গ এবং মর্ত্ত্য ও পাতালনিবাসীদের “প্রত্যেক হাঁটু নত হয়,","yēna yīśura nāmē sbarga ēbaṁ marttya ō pātālanibāsīdēra “pratyēka hām̐ṭu nata haẏa,",null],[2,11,"এবং প্রত্যেক জিভ যেন স্বীকার করে” যে, যীশু খ্রীষ্টই প্রভু, এই ভাবে পিতা ঈশ্বর যেন মহিমান্বিত হন।","ēbaṁ pratyēka jibha yēna sbīkāra karē” yē, yīśu khrīṣṭa:i prabhu, ēi bhābē pitā īśbara yēna mahimānbita hana.",null],[2,12,"অতএব, হে আমার প্রিয়তমেরা, তোমরা সবদিন যেমন আজ্ঞা পালন করে আসছ, তেমনি আমার সামনে যেমন কেবল সেই রকম না, কিন্তু এখন আরও বেশিভাবে আমার অনুপস্থিতিতে, সভয়ে ও সম্মানের সঙ্গে নিজের নিজের পরিত্রান সম্পন্ন কর।","ataēba, hē āmāra priẏatamērā, tōmarā sabadina yēmana ājñā pālana karē āsacha, tēmani āmāra sāmanē yēmana kēbala sēi rakama nā, kintu ēkhana āraō bēśibhābē āmāra anupasthititē, sabhaẏē ō sammānēra saṅgē nijēra nijēra paritrāna sampanna kara.",null],[2,13,"কারণ ঈশ্বরই নিজের সন্তুষ্টির জন্য তোমাদের হৃদয়ে ইচ্ছা ও কাজ উভয়ের সাধনকারী।","kāraṇa īśbara:i nijēra santuṣṭira janya tōmādēra hr̥daẏē icchā ō kāja ubhaẏēra sādhanakārī.",null],[2,14,"তোমরা অভিযোগ ও তর্ক ছাড়া সব কাজ কর,","tōmarā abhiyōga ō tarka chāṛā saba kāja kara,",null],[2,15,"যেন তোমরা অনিন্দনীয় ও এই দিনের র সেই অসরল ও চরিত্রহীন প্রজন্মের মধ্যে ঈশ্বরের নিষ্কলঙ্ক সন্তান হও, যাদের মধ্যে তোমরা জগতে উজ্জ্বল নক্ষত্রের প্রকাশ পাচ্ছো,","yēna tōmarā anindanīẏa ō ēi dinēra ra sēi asarala ō caritrahīna prajanmēra madhyē īśbarēra niṣkalaṅka santāna haō, yādēra madhyē tōmarā jagatē ujjbala nakṣatrēra prakāśa pācchō,",null],[2,16,"জীবনের বাক্য ধরে রয়েছো; এতে খ্রীষ্টের পুনরাগমনের দিনের আমি এই গর্ব করার কারণ পাব যে, আমি বৃথা দৌড়াইনি, বৃথা পরিশ্রমও করিনি।","jībanēra bākya dharē raẏēchō; ētē khrīṣṭēra punarāgamanēra dinēra āmi ēi garba karāra kāraṇa pāba yē, āmi br̥thā dauṛāini, br̥thā pariśramaō karini.",null],[2,17,"কিন্তু তোমাদের বিশ্বাসের আত্মাহুতিতে ও সেবায় যদি আমি উত্সর্গের জন্য সেচিতও হই তবে আমি আরাধনা করছি, আর তোমাদের সবার সঙ্গে আনন্দ করছি।","kintu tōmādēra biśbāsēra ātmāhutitē ō sēbāẏa yadi āmi utsargēra janya sēcitaō ha:i tabē āmi ārādhanā karachi, āra tōmādēra sabāra saṅgē ānanda karachi.",null],[2,18,"সেইভাবে তোমরাও আনন্দ কর, আর আমার সঙ্গে আনন্দ কর।","sēibhābē tōmarāō ānanda kara, āra āmāra saṅgē ānanda kara.",null],[2,19,"আমি প্রভু যীশুতে প্রত্যাশা করছি যে, তীমথিয়কে খুব তাড়াতাড়ি তোমাদের কাছে পাঠাব, যেন তোমাদের অবস্থা জেনে আমিও উত্সাহিত হই।","āmi prabhu yīśutē pratyāśā karachi yē, tīmathiẏakē khuba tāṛātāṛi tōmādēra kāchē pāṭhāba, yēna tōmādēra abasthā jēnē āmiō utsāhita ha:i.",null],[2,20,"কারণ আমার কাছে তীমথির মত কোনো প্রাণ নেই যে, সত্যিই তোমাদের বিষয়ে চিন্তা করবে।","kāraṇa āmāra kāchē tīmathira mata kōnō prāṇa nēi yē, satyii tōmādēra biṣaẏē cintā karabē.",null],[2,21,"কারণ ওরা সবাই যীশু খ্রীষ্টের বিষয় নয়, কিন্তু নিজের নিজের বিষয়ে চেষ্টা করে।","kāraṇa ōrā sabāi yīśu khrīṣṭēra biṣaẏa naẏa, kintu nijēra nijēra biṣaẏē cēṣṭā karē.",null],[2,22,"কিন্তু তোমরা এঁর পক্ষে এই প্রমাণ জানো যে, বাবার সাথে সন্তান যেমন, আমার সাথে ইনি তেমনি সুসমাচার বিস্তারের জন্য দায়িত্ব পালন করেছেন।","kintu tōmarā ēm̐ra pakṣē ēi pramāṇa jānō yē, bābāra sāthē santāna yēmana, āmāra sāthē ini tēmani susamācāra bistārēra janya dāẏitba pālana karēchēna.",null],[2,23,"অতএব আশাকরি, আমার কি ঘটে, তা জানতে পারলেই তাঁকে তোমাদের কাছে পাঠিয়ে দেব।","ataēba āśākari, āmāra ki ghaṭē, tā jānatē pāralēi tām̐kē tōmādēra kāchē pāṭhiẏē dēba.",null],[2,24,"আর প্রভুতে আমার দৃঢ় বিশ্বাস এই যে, আমি নিজেও তাড়াতাড়ি আসব।","āra prabhutē āmāra dr̥ṛha biśbāsa ēi yē, āmi nijēō tāṛātāṛi āsaba.",null],[2,25,"কিন্তু আমার ভাই, সহকর্মী ও সহসেনা এবং তোমাদের প্রেরিত ও আমার প্রয়োজনীয় উপকারী সেবক ইপাফ্রাদীত তোমাদের কাছে পাঠিয়ে দেওয়া প্রয়োজন বলে আমার আবশ্যক মনে হল।","kintu āmāra bhāi, sahakarmī ō sahasēnā ēbaṁ tōmādēra prērita ō āmāra praẏōjanīẏa upakārī sēbaka ipāphrādīta tōmādēra kāchē pāṭhiẏē dēōẏā praẏōjana balē āmāra ābaśyaka manē hala.",null],[2,26,"কারণ তিনি তোমাদের সবাইকে দেখবার জন্য আকাঙ্ক্ষী ছিলেন এবং তোমরা তাঁর অসুস্থতার সংবাদ শুনেছ বলে তিনি ব্যাকুল হয়েছিলেন।","kāraṇa tini tōmādēra sabāikē dēkhabāra janya ākāṅkṣī chilēna ēbaṁ tōmarā tām̐ra asusthatāra saṁbāda śunēcha balē tini byākula haẏēchilēna.",null],[2,27,"আর সত্যিই তিনি অসুস্থতায় মারা যাওয়ার মত হয়েছিলেন; কিন্তু ঈশ্বর তাঁর ওপর দয়া করেছেন, আর কেবল তাঁর ওপর না, আমার ওপরও দয়া করেছেন, যেন দুঃখের উপর দুঃখ আমার না হয়।","āra satyii tini asusthatāẏa mārā yāōẏāra mata haẏēchilēna; kintu īśbara tām̐ra ōpara daẏā karēchēna, āra kēbala tām̐ra ōpara nā, āmāra ōparaō daẏā karēchēna, yēna duḥkhēra upara duḥkha āmāra nā haẏa.",null],[2,28,"এই জন্য আমি আগ্রহের সঙ্গে তাঁকে পাঠালাম, যেন তোমরা তাঁকে দেখে পুনর্বার আনন্দ কর, আমারও দুঃখের লাঘব হয়।","ēi janya āmi āgrahēra saṅgē tām̐kē pāṭhālāma, yēna tōmarā tām̐kē dēkhē punarbāra ānanda kara, āmāraō duḥkhēra lāghaba haẏa.",null],[2,29,"অতএব তোমরা তাঁকে প্রভুতে সম্পূর্ণ আনন্দের সঙ্গে গ্রহণ করো এবং এই ধরনের লোকদের সম্মান করো;","ataēba tōmarā tām̐kē prabhutē sampūrṇa ānandēra saṅgē grahaṇa karō ēbaṁ ēi dharanēra lōkadēra sammāna karō;",null],[2,30,"কারণ খ্রীষ্টের কাজের জন্য তিনি মৃত্যুমুখে উপস্থিত হয়েছিলেন, ফলে আমার সেবায় তোমাদের ত্রুটি পূরনের জন্য তিনি জীবনের ঝুঁকিও নিয়েছিলেন।","kāraṇa khrīṣṭēra kājēra janya tini mr̥tyumukhē upasthita haẏēchilēna, phalē āmāra sēbāẏa tōmādēra truṭi pūranēra janya tini jībanēra jhum̐kiō niẏēchilēna.",null],[3,1,"শেষ কথা এই, হে আমার ভাইয়েরা, প্রভুতে আনন্দ কর। তোমাদেরকে একই কথা বারবার লিখতে আমি ক্লান্ত হই না, আর তা তোমাদের রক্ষার জন্য।","śēṣa kathā ēi, hē āmāra bhāiẏērā, prabhutē ānanda kara. tōmādērakē ēka:i kathā bārabāra likhatē āmi klānta ha:i nā, āra tā tōmādēra rakṣāra janya.",null],[3,2,"সেই কুকুরদের থেকে সাবধান, সেই মন্দ কাজ করে যারা তাদের কাছ থেকে সাবধান, যারা দেহের কোনো অংশকে কাটা-ছেঁড়া করে সেই লোকদের থেকে সাবধান।","sēi kukuradēra thēkē sābadhāna, sēi manda kāja karē yārā tādēra kācha thēkē sābadhāna, yārā dēhēra kōnō aṁśakē kāṭā-chēm̐ṛā karē sēi lōkadēra thēkē sābadhāna.",null],[3,3,"আমরাই তো প্রকৃত ছিন্নত্বক লোক, আমরা যারা ঈশ্বরের আত্মাতে আরাধনা করি এবং খ্রীষ্ট যীশুতে গর্ব করি, দেহের উপর নির্ভর করি না।","āmarāi tō prakr̥ta chinnatbaka lōka, āmarā yārā īśbarēra ātmātē ārādhanā kari ēbaṁ khrīṣṭa yīśutē garba kari, dēhēra upara nirbhara kari nā.",null],[3,4,"যদি তাই হতো তবে আমি আমার দেহে দৃঢ়ভাবে নির্ভর করতে পারতাম। যদি অন্য কেউ মনে করে যে, সে তার দেহের উপর নির্ভর করতে পারে, তবে আমি আরো বেশি নির্ভর করতে পারি।","yadi tāi hatō tabē āmi āmāra dēhē dr̥ṛhabhābē nirbhara karatē pāratāma. yadi anya kēu manē karē yē, sē tāra dēhēra upara nirbhara karatē pārē, tabē āmi ārō bēśi nirbhara karatē pāri.",null],[3,5,"আমি আটদিনের র দিন ত্বকছেদ প্রাপ্ত হয়েছি, ইস্রায়েল-জাতীয় বিন্যামীন বংশের, খাঁটি ইব্রীয়, ব্যবস্থার সম্বন্ধে ফরীশী,","āmi āṭadinēra ra dina tbakachēda prāpta haẏēchi, isrāẏēla-jātīẏa binyāmīna baṁśēra, khām̐ṭi ibrīẏa, byabasthāra sambandhē pharīśī,",null],[3,6,"উদ্যোগ সম্বন্ধে মণ্ডলীর তাড়নাকারী ছিলাম, ব্যবস্থার নিয়ম কানুন পালনে নিখুঁত ছিলাম।","udyōga sambandhē maṇḍalīra tāṛanākārī chilāma, byabasthāra niẏama kānuna pālanē nikhum̐ta chilāma.",null],[3,7,"কিন্তু যা আমার লাভ ছিল সে সমস্ত খ্রীষ্টের জন্য ক্ষতি বলে মনে করি।","kintu yā āmāra lābha chila sē samasta khrīṣṭēra janya kṣati balē manē kari.",null],[3,8,"আসলে, আমার প্রভু খ্রীষ্ট যীশুর যে জ্ঞান তা সব থেকে শ্রেষ্ঠ, তার জন্য আমি সব কিছুই এখন ক্ষতি বলে মনে করছি; তাঁর জন্য সব কিছুর ক্ষতি সহ্য করেছি এবং তা আবর্জনা (মল) মনে করে ত্যাগ করেছি,","āsalē, āmāra prabhu khrīṣṭa yīśura yē jñāna tā saba thēkē śrēṣṭha, tāra janya āmi saba kichui ēkhana kṣati balē manē karachi; tām̐ra janya saba kichura kṣati sahya karēchi ēbaṁ tā ābarjanā (mala) manē karē tyāga karēchi,",null],[3,9,"যেন খ্রীষ্টকে লাভ করি এবং তাঁতেই যেন আমাকে দেখতে পাওয়া যায়; আমার নিজের ধার্ম্মিকতা, যা ব্যবস্থা থেকে পাওয়া, তা যেন আমার না হয়, কিন্তু যে ধার্ম্মিকতা খ্রীষ্টে বিশ্বাসের মাধ্যমে হয়, বিশ্বাসমূলক যে ধার্ম্মিকতা ঈশ্বর থেকে পাওয়া যায়, তাই যেন আমার হয়;","yēna khrīṣṭakē lābha kari ēbaṁ tām̐tēi yēna āmākē dēkhatē pāōẏā yāẏa; āmāra nijēra dhārmmikatā, yā byabasthā thēkē pāōẏā, tā yēna āmāra nā haẏa, kintu yē dhārmmikatā khrīṣṭē biśbāsēra mādhyamē haẏa, biśbāsamūlaka yē dhārmmikatā īśbara thēkē pāōẏā yāẏa, tāi yēna āmāra haẏa;",null],[3,10,"যেন আমি তাঁকে ও তিনি যে জীবিত হয়েছেন বা পুনরুত্থিত হয়েছেন, সেই শক্তিতে এবং তাঁর দুঃখভোগের সহভাগীতা জানতে পারি, এই ভাবে যেন তাঁর মৃত্যুর মতো আমিও মৃত্যুবরণ করতে পারি;","yēna āmi tām̐kē ō tini yē jībita haẏēchēna bā punarutthita haẏēchēna, sēi śaktitē ēbaṁ tām̐ra duḥkhabhōgēra sahabhāgītā jānatē pāri, ēi bhābē yēna tām̐ra mr̥tyura matō āmiō mr̥tyubaraṇa karatē pāri;",null],[3,11,"আর তারই মধ্যে থেকে যেন মৃতদের মধ্য থেকে জীবিত হওয়ার অভিজ্ঞতা লাভ করতে পারি।","āra tāra:i madhyē thēkē yēna mr̥tadēra madhya thēkē jībita haōẏāra abhijñatā lābha karatē pāri.",null],[3,12,"আমি যে এখনই এসব জিনিস পেয়েছি, কিংবা পূর্ণতা লাভ করেছি, তা নয়; কিন্তু যার জন্য খ্রীষ্ট যীশু আমাকে উদ্ধার করেছেন (বা তার নিজের বলে দাবী করেছেন) এবং তা ধরার জন্য আমি দৌড়াচ্ছি।","āmi yē ēkhana:i ēsaba jinisa pēẏēchi, kiṁbā pūrṇatā lābha karēchi, tā naẏa; kintu yāra janya khrīṣṭa yīśu āmākē uddhāra karēchēna (bā tāra nijēra balē dābī karēchēna) ēbaṁ tā dharāra janya āmi dauṛācchi.",null],[3,13,"ভাইয়েরা, আমি যে তা ধরতে পেরেছি, নিজের বিষয়ে এমন চিন্তা করি না; কিন্তু একটি কাজ করি, পিছনের সমস্ত বিষয়গুলি ভুলে গিয়ে সামনের বিষয়গুলির জন্য আগ্রহের সঙ্গে ছুটে চলেছি,","bhāiẏērā, āmi yē tā dharatē pērēchi, nijēra biṣaẏē ēmana cintā kari nā; kintu ēkaṭi kāja kari, pichanēra samasta biṣaẏaguli bhulē giẏē sāmanēra biṣaẏagulira janya āgrahēra saṅgē chuṭē calēchi,",null],[3,14,"লক্ষ্যের দিকে দৌড়াতে দৌড়াতে আমি খ্রীষ্ট যীশুতে ঈশ্বরের যে ডাক যা তিনি পুরষ্কার পাওয়ার জন্য স্বর্গে ডেকেছেন তার জন্য যত্ন করছি।","lakṣyēra dikē dauṛātē dauṛātē āmi khrīṣṭa yīśutē īśbarēra yē ḍāka yā tini puraṣkāra pāōẏāra janya sbargē ḍēkēchēna tāra janya yatna karachi.",null],[3,15,"অতএব এস, আমরা যতজন পরিপক্ক, সবাই এই বিষয়ে ভাবি; আর যদি কোন বিষয়ে তোমাদের মনে অন্যভাবে চিন্তা করে থাক, তবে ঈশ্বর তোমাদের কাছে তাও প্রকাশ করবেন।","ataēba ēsa, āmarā yatajana paripakka, sabāi ēi biṣaẏē bhābi; āra yadi kōna biṣaẏē tōmādēra manē anyabhābē cintā karē thāka, tabē īśbara tōmādēra kāchē tāō prakāśa karabēna.",null],[3,16,"তাই যাইহোক না কেন, আমরা যে পর্যন্ত পৌছিয়েছি, যেন সেই একই ধারায় চলি।","tāi yāihōka nā kēna, āmarā yē paryanta pauchiẏēchi, yēna sēi ēka:i dhārāẏa cali.",null],[3,17,"ভাইয়েরা, তোমরা সবাই আমার মতো হও এবং আমরা যেমন তোমাদের আদর্শ, তেমনি আমাদের আচরণ মতো যারা চলে, তাদের দিকে দৃষ্টি রাখ।","bhāiẏērā, tōmarā sabāi āmāra matō haō ēbaṁ āmarā yēmana tōmādēra ādarśa, tēmani āmādēra ācaraṇa matō yārā calē, tādēra dikē dr̥ṣṭi rākha.",null],[3,18,"কারণ অনেকে এমন ভাবে চলছে, যাদের বিষয়ে তোমাদেরকে বার বার বলেছি এবং এখনও চোখের জলের সঙ্গে বলছি, তারা খ্রীষ্টের ক্রুশের শত্রু;","kāraṇa anēkē ēmana bhābē calachē, yādēra biṣaẏē tōmādērakē bāra bāra balēchi ēbaṁ ēkhanaō cōkhēra jalēra saṅgē balachi, tārā khrīṣṭēra kruśēra śatru;",null],[3,19,"তাদের পরিণাম বিনাশ; পেটই তাদের দেবতা এবং লজ্জাতেই তাদের গৌরব; তারা জাগতিক বিষয় ভাবে।","tādēra pariṇāma bināśa; pēṭa:i tādēra dēbatā ēbaṁ lajjātēi tādēra gauraba; tārā jāgatika biṣaẏa bhābē.",null],[3,20,"কারণ আমরা স্বর্গপুরীর প্রজা; আর সেখান থেকে আমরা উদ্ধারকর্তার, প্রভু যীশু খ্রীষ্টের, ফিরে আসার প্রতীক্ষা করছি;","kāraṇa āmarā sbargapurīra prajā; āra sēkhāna thēkē āmarā uddhārakartāra, prabhu yīśu khrīṣṭēra, phirē āsāra pratīkṣā karachi;",null],[3,21,"তিনি আমাদের ক্ষয়িষ্ণু দেহকে পরিবর্তন করে তাঁর মহিমার দেহের মতো করবেন, যে শক্তির মাধ্যমে তিনি সমস্ত কিছু তাঁর বশীভূত করতে পারেন, তারই গুণে করবেন।","tini āmādēra kṣaẏiṣṇu dēhakē paribartana karē tām̐ra mahimāra dēhēra matō karabēna, yē śaktira mādhyamē tini samasta kichu tām̐ra baśībhūta karatē pārēna, tāra:i guṇē karabēna.",null],[4,1,"অতএব, হে আমার ভাইয়েরা, প্রিয়তমেরা ও আকাঙ্খার পাত্রেরা, আমার আনন্দ ও মুকুট, প্রিয়তমেরা, তোমরা এই ভাবে প্রভুর প্রেমে স্থির থাক।","ataēba, hē āmāra bhāiẏērā, priẏatamērā ō ākāṅkhāra pātrērā, āmāra ānanda ō mukuṭa, priẏatamērā, tōmarā ēi bhābē prabhura prēmē sthira thāka.",null],[4,2,"আমি ইবদিয়াকে অনুরোধ করে ও সন্তূখীকে অনুরোধ করে বলছি যে, “তোমরা প্রভুর প্রেমে একই বিষয় ভাব।”","āmi ibadiẏākē anurōdha karē ō santūkhīkē anurōdha karē balachi yē, “tōmarā prabhura prēmē ēka:i biṣaẏa bhāba.”",null],[4,3,"আবার, আমার প্রকৃত সত্য সহকর্মী যে তুমি, তোমাকেও অনুরোধ করছি, তুমি এই মহিলাদের সাহায্য কর, কারণ তাঁরা সুসমাচারে আমার সঙ্গে পরিশ্রম করেছিলেন, ক্লীমেন্ত এবং আমার আরো অন্য সহকর্মীদের সঙ্গেও তা করেছিলেন, তাঁদের নাম জীবন পুস্তকে লেখা আছে।","ābāra, āmāra prakr̥ta satya sahakarmī yē tumi, tōmākēō anurōdha karachi, tumi ēi mahilādēra sāhāyya kara, kāraṇa tām̐rā susamācārē āmāra saṅgē pariśrama karēchilēna, klīmēnta ēbaṁ āmāra ārō anya sahakarmīdēra saṅgēō tā karēchilēna, tām̐dēra nāma jībana pustakē lēkhā āchē.",null],[4,4,"তোমরা প্রভুতে সর্বদা আনন্দ কর; আমি আবার বলছি, আনন্দ কর।","tōmarā prabhutē sarbadā ānanda kara; āmi ābāra balachi, ānanda kara.",null],[4,5,"তোমাদের নম্রতা যেন সবাই দেখতে পায়। প্রভু শীঘ্রই আসছেন।","tōmādēra namratā yēna sabāi dēkhatē pāẏa. prabhu śīghra:i āsachēna.",null],[4,6,"কোন বিষয়ে চিন্তা কোরো না, কিন্তু সব বিষয় প্রার্থনা, বিনতি এবং ধন্যবাদের সঙ্গে তোমাদের সমস্ত প্রয়োজন ঈশ্বরকে জানাও।","kōna biṣaẏē cintā kōrō nā, kintu saba biṣaẏa prārthanā, binati ēbaṁ dhanyabādēra saṅgē tōmādēra samasta praẏōjana īśbarakē jānāō.",null],[4,7,"তাতে ঈশ্বরের যে শান্তি যা সমস্ত চিন্তার বাইরে, তা তোমাদের হৃদয় ও মন খ্রীষ্ট যীশুতে রক্ষা করবে।","tātē īśbarēra yē śānti yā samasta cintāra bāirē, tā tōmādēra hr̥daẏa ō mana khrīṣṭa yīśutē rakṣā karabē.",null],[4,8,"অবশেষে, ভাইয়েরা, যা কিছু সত্য, যা কিছু সম্মানীয়, যা কিছু ন্যায্য, যা কিছু খাঁটি, যা কিছু সুন্দর, যা কিছু প্রশংসার বিষয়, যে কোন ভালবাসা ও যে কোন শুদ্ধ বিষয় হোক, সেই সমস্ত আলোচনা কর।","abaśēṣē, bhāiẏērā, yā kichu satya, yā kichu sammānīẏa, yā kichu nyāyya, yā kichu khām̐ṭi, yā kichu sundara, yā kichu praśaṁsāra biṣaẏa, yē kōna bhālabāsā ō yē kōna śuddha biṣaẏa hōka, sēi samasta ālōcanā kara.",null],[4,9,"তোমরা আমার কাছে যা যা শিখেছ, গ্রহণ করেছ, শুনেছ ও দেখেছ, সেই সমস্ত কর; তাতে শান্তির ঈশ্বর তোমাদের সঙ্গে সঙ্গে থাকবেন।","tōmarā āmāra kāchē yā yā śikhēcha, grahaṇa karēcha, śunēcha ō dēkhēcha, sēi samasta kara; tātē śāntira īśbara tōmādēra saṅgē saṅgē thākabēna.",null],[4,10,"কিন্তু আমি প্রভুতে বড়ই আনন্দিত হলাম যে, অবশেষে তোমরা আমার জন্য ভাবার নতুন উদ্দীপনা পেয়েছ; এই বিষয়ে তোমরা চিন্তা করছিলে, কিন্তু সুযোগ পাও নি।","kintu āmi prabhutē baṛa:i ānandita halāma yē, abaśēṣē tōmarā āmāra janya bhābāra natuna uddīpanā pēẏēcha; ēi biṣaẏē tōmarā cintā karachilē, kintu suyōga pāō ni.",null],[4,11,"এই কথা আমি অভাব সম্বন্ধে বলছি না, কারণ আমি যে অবস্থায় থাকি, তাতেই সন্তুষ্ট থাকতে শিখেছি।","ēi kathā āmi abhāba sambandhē balachi nā, kāraṇa āmi yē abasthāẏa thāki, tātēi santuṣṭa thākatē śikhēchi.",null],[4,12,"আমি অবনত হতে জানি, প্রাচুর্য্য ভোগ করতেও জানি; সব জায়গায় ও সব বিষয়ে আমি সন্তুষ্ট থাকতে এবং খিদে সহ্য করতে, প্রাচুর্য্য কি অভাব সহ্য করতে আমি শিখেছি।","āmi abanata hatē jāni, prācuryya bhōga karatēō jāni; saba jāẏagāẏa ō saba biṣaẏē āmi santuṣṭa thākatē ēbaṁ khidē sahya karatē, prācuryya ki abhāba sahya karatē āmi śikhēchi.",null],[4,13,"যিনি আমাকে শক্তি দেন, তাঁর মাধ্যমে আমি সবই করতে পারি।","yini āmākē śakti dēna, tām̐ra mādhyamē āmi saba:i karatē pāri.",null],[4,14,"তবুও তোমরা আমার কষ্টের দিন দানে সহভাগী হয়ে ভালই করেছ।","tabuō tōmarā āmāra kaṣṭēra dina dānē sahabhāgī haẏē bhāla:i karēcha.",null],[4,15,"আর, তোমরা ফিলিপীয়েরা, জান যে, সুসমাচার প্রচারের শুরুতে, যখন আমি মাকিদনিয়া থেকে চলে গিয়েছিলাম, তখন কোন মণ্ডলী দানের বিষয়ে আমার সহভাগী হয়নি, শুধু তোমরাই হয়েছিলে।","āra, tōmarā philipīẏērā, jāna yē, susamācāra pracārēra śurutē, yakhana āmi mākidaniẏā thēkē calē giẏēchilāma, takhana kōna maṇḍalī dānēra biṣaẏē āmāra sahabhāgī haẏani, śudhu tōmarāi haẏēchilē.",null],[4,16,"এমনকি থিষলনীকীতেও তোমরা একবার, বরং দুই বার আমার প্রয়োজনীয় উপকার পাঠিয়েছিলে।","ēmanaki thiṣalanīkītēō tōmarā ēkabāra, baraṁ dui bāra āmāra praẏōjanīẏa upakāra pāṭhiẏēchilē.",null],[4,17,"আমি উপহার পাওয়ার জন্য চেষ্টা করছি না, কিন্তু সেই ফলের চেষ্টা করছি, যা তোমাদের জন্য খুবই লাভজনক হবে।","āmi upahāra pāōẏāra janya cēṣṭā karachi nā, kintu sēi phalēra cēṣṭā karachi, yā tōmādēra janya khuba:i lābhajanaka habē.",null],[4,18,"আমার সব কিছুই আছে, বরং উপচিয়ে পড়ছে; আমি তোমাদের কাছ থেকে ইপাফ্রদীতের হাতে যা কিছু পেয়েছি তাতে পরিপূর্ণ হয়েছি, যা সুগন্ধিযুক্ত এবং গ্রহণযোগ্য বলি যা ঈশ্বরকে প্রসন্ন করে।","āmāra saba kichui āchē, baraṁ upaciẏē paṛachē; āmi tōmādēra kācha thēkē ipāphradītēra hātē yā kichu pēẏēchi tātē paripūrṇa haẏēchi, yā sugandhiyukta ēbaṁ grahaṇayōgya bali yā īśbarakē prasanna karē.",null],[4,19,"আর আমার ঈশ্বর গৌরবে তাঁর ধনসম্পদ অনুযায়ী খ্রীষ্ট যীশুতে তোমাদের সমস্ত প্রয়োজন পূরণ করবেন।","āra āmāra īśbara gaurabē tām̐ra dhanasampada anuyāẏī khrīṣṭa yīśutē tōmādēra samasta praẏōjana pūraṇa karabēna.",null],[4,20,"আমাদের ঈশ্বরও পিতার মহিমা সব দিনের র জন্য যুগে যুগে হোক। আমেন।","āmādēra īśbaraō pitāra mahimā saba dinēra ra janya yugē yugē hōka. āmēna.",null],[4,21,"তোমরা খ্রীষ্ট যীশুতে প্রত্যেক পবিত্র লোককে আমার শুভেচ্ছা জানিও। আমার সঙ্গী ভাইয়েরা তোমাদেরকে শুভেচ্ছা জানাচ্ছেন।","tōmarā khrīṣṭa yīśutē pratyēka pabitra lōkakē āmāra śubhēcchā jāniō. āmāra saṅgī bhāiẏērā tōmādērakē śubhēcchā jānācchēna.",null],[4,22,"সমস্ত পবিত্র লোক, বিশেষ করে যাঁরা কৈসরের বাড়ির লোক, তাঁরাও তোমাদেরকে শুভেচ্ছা জানাচ্ছেন।","samasta pabitra lōka, biśēṣa karē yām̐rā kaisarēra bāṛira lōka, tām̐rāō tōmādērakē śubhēcchā jānācchēna.",null],[4,23,"প্রভু যীশু খ্রীষ্টের অনুগ্রহ তোমাদের আত্মার সহবর্ত্তী হোক।","prabhu yīśu khrīṣṭēra anugraha tōmādēra ātmāra sahabarttī hōka.",null]],"bfz-mahasui":[[1,1,"मसीह यीशु रौ सेवक पौलुस और तीमुथियुसा री तौरफा कु, सारै पवित्र लोगु रै नावां दी ज़ो मसीह यीशु दी विश्वास कौरणै वाल़ै फिलिप्पीऊ दी रौआ ई, अध्यक्षों और सेवकों समेत।","masīha yīśu rau sēvaka paulusa aura tīmuthiyusā rī tauraphā ku, sārai pavitra lōgu rai nāvāṁ dī zō masīha yīśu dī viśvāsa kauraṇai vāl̈ai philippīū dī rauā ī, adhyakṣōṁ aura sēvakōṁ samēta.",null],[1,2,"आमारै बाब परमेश्वर और प्रभु यीशु मसीह री तौरफा कु तुमुलै बौड़ी दया और शांती मिलदी रौआ।","āmārai bāba paramēśvara aura prabhu yīśu masīha rī tauraphā ku tumulai bauṛī dayā aura śāṁtī miladī rauā.",null],[1,3,"हाऊं ज़ेबी-ज़ेबी तुमु याद कौराऊ, तैबै आपणै परमेश्वरा रौ धन्यावाद कौराऊ; तेबी-तेबी आपणै परमेश्वरा रौ धन्यावाद कौराउ।","hāūṁ zēbī-zēbī tumu yāda kaurāū, taibai āpaṇai paramēśvarā rau dhanyāvāda kaurāū; tēbī-tēbī āpaṇai paramēśvarā rau dhanyāvāda kaurāu.",null],[1,4,"और ज़ेबी केबी तुमु सौबीलै औरज़ कौराउ; ता सौदा खुशी आइलै औरज़ कौराउ।","aura zēbī kēbī tumu saubīlai auraza kaurāu; tā saudā khuśī āilai auraza kaurāu.",null],[1,5,"एथीलै कि तुमै पैहलै दिना कु आज़ा झ़ाऊं खुशी रौ संदेश फैलाउणे दी मुं आइलै रौऐ ई।","ēthīlai ki tumai paihalai dinā ku āzā jḧāūṁ khuśī rau saṁdēśa phailāuṇē dī muṁ āilai rauai ī.",null],[1,6,"मुंकै इऊं बुशु रौ विश्वास आ कि ज़ुणीऐ तुमु मांझ़िऐ आच़्छ़ौ काम कियौ सा, सेऊई तेस यीशु मसीह रै दिना झ़ाऊं पुरौ कौरा।","muṁkai iūṁ buśu rau viśvāsa ā ki zuṇīai tumu māṁjḧiai āc̈cḧau kāma kiyau sā, sēūī tēsa yīśu masīha rai dinā jḧāūṁ purau kaurā.",null],[1,7,"एऊ ठीक आ कि हाऊं तुमु सौबीलै इणी ई बिचार कौरु, कैलैकि तुमै मैरै ज़ीवा दी बौसी ऐरै ई, और मैरै ज़ेला दी और खुशी रौ संदेशालै ज़वाब और प्रमाण दैणै दी तुमै सौबी मुं आइलै शांती दी साथाई","ēū ṭhīka ā ki hāūṁ tumu saubīlai iṇī ī bicāra kauru, kailaiki tumai mairai zīvā dī bausī airai ī, aura mairai zēlā dī aura khuśī rau saṁdēśālai zavāba aura pramāṇa daiṇai dī tumai saubī muṁ āilai śāṁtī dī sāthāī",null],[1,8,"ऐथ दी परमेश्वर मैरौ गवाह आ कि हाऊं यीशु ज़िणौ प्यार कौरीऔ तुमु सौबी री लालसा कौराउ।","aitha dī paramēśvara mairau gavāha ā ki hāūṁ yīśu ziṇau pyāra kaurīau tumu saubī rī lālasā kaurāu.",null],[1,9,"हाऊं इणी प्राथना कौराउ कि तुमारौ प्यारा रौ ज्ञान और सारै रौंगा री हिम्मता कौरी औज़ौ भी बौड़दै थाकौ लागी,","hāūṁ iṇī prāthanā kaurāu ki tumārau pyārā rau jñāna aura sārai rauṁgā rī himmatā kaurī auzau bhī bauṛadai thākau lāgī,",null],[1,10,"इदरा झ़ाऊं कि तुमै आच़्छ़ै कु आच़्छ़ी बुशै प्यारी ज़ाणौ, और मसीहा रै दिना झ़ाऊं सौच़्च़ै बौणी रौऔ, और ठेस नाईं खाऔ;","idarā jḧāūṁ ki tumai āc̈cḧai ku āc̈cḧī buśai pyārī zāṇau, aura masīhā rai dinā jḧāūṁ sauc̈c̈ai bauṇī rauau, aura ṭhēsa nāīṁ khāau;",null],[1,11,"और तेस धौर्मी रै कामा रै फल़ा कु ज़ो यीशु मसीह रै ज़रीयै हुआ सा, बौड़दै रौऔ ज़ासकु परमेश्वरा री महीमा और स्तुति औन्दी रौआ।","aura tēsa dhaurmī rai kāmā rai phal̈ā ku zō yīśu masīha rai zarīyai huā sā, bauṛadai rauau zāsaku paramēśvarā rī mahīmā aura stuti aundī rauā.",null],[1,12,"ओ भाईउओ, हाऊं च़ाह ऊ कि तुमै इणौ ज़ाणौ कि मुं माथै ज़ो बितौ सा, तेसकु खुशी रै संदेशा री उन्नती हुई आ।","ō bhāīuō, hāūṁ c̈āha ū ki tumai iṇau zāṇau ki muṁ māthai zō bitau sā, tēsaku khuśī rai saṁdēśā rī unnatī huī ā.",null],[1,13,"इदरा झ़ाऊं कि कैसरा रै मैहला री सारी फौज़ और बौच़ै औन्दै सारै लोगु दी इणौ परगट हुई गौ कि हाऊं मसीह कालै कैदा दी ऊ;","idarā jḧāūṁ ki kaisarā rai maihalā rī sārī phauza aura bauc̈ai aundai sārai lōgu dī iṇau paragaṭa huī gau ki hāūṁ masīha kālai kaidā dī ū;",null],[1,14,"और प्रभु दी ज़ो भाई आ, तिऊं मांझ़िउ कु भौरी ज़ौणै मैरै ज़ेला दी हुणा रै कारण, विश्वास बानियौ परमेश्वरा रौ वचन बिणा डौरियौ शुणाउंणा लै औज़ौ भी हिम्मत कौरा आ।","aura prabhu dī zō bhāī ā, tiūṁ māṁjḧiu ku bhaurī zauṇai mairai zēlā dī huṇā rai kāraṇa, viśvāsa bāniyau paramēśvarā rau vacana biṇā ḍauriyau śuṇāuṁṇā lai auzau bhī himmata kaurā ā.",null],[1,15,"कुछ़ ता डाह और लड़ाई रै कारण मसीहा रौ परच़ार कौराई और कुछ़ आच़्छ़ी इच्छ़ा कु।","kucḧa tā ḍāha aura laṛāī rai kāraṇa masīhā rau parac̈āra kaurāī aura kucḧa āc̈cḧī iccḧā ku.",null],[1,16,"कोई एक ता इणौ ज़ाणाई कि हाऊं खुशी रौ संदेशा लै ज़वाब दैणा लै चाणौ औन्दौ आ, प्यारा कौरी परच़ार कौरा सा।","kōī ēka tā iṇau zāṇāī ki hāūṁ khuśī rau saṁdēśā lai zavāba daiṇā lai cāṇau aundau ā, pyārā kaurī parac̈āra kaurā sā.",null],[1,17,"और कई एक ता सौच़ाई कु नाईं पर बिरोधा कु मसीह री काआणी शुणाउवाई, इणौ सुंचीऔ कि मैरै ज़ेला दी मुं कालै दु:ख पैदौ कौरा।","aura kaī ēka tā sauc̈āī ku nāīṁ para birōdhā ku masīha rī kāāṇī śuṇāuvāī, iṇau suṁcīau ki mairai zēlā dī muṁ kālai du:kha paidau kaurā.",null],[1,18,"ता का हुऔ? सिरफ इणौ कि सौबी रौंगा कु, च़ाऐ बहाना कु च़ाऐ सौच़्च़ाई कु, मसीहा री काआणी शुणावा ई, और हाऊं ऐथकु भौरी खुश ऊ और भौरी खुश रौऊ भी।","tā kā huau? sirapha iṇau ki saubī rauṁgā ku, c̈āai bahānā ku c̈āai sauc̈c̈āī ku, masīhā rī kāāṇī śuṇāvā ī, aura hāūṁ aithaku bhaurī khuśa ū aura bhaurī khuśa rauū bhī.",null],[1,19,"कैलैकि हाऊं ज़ाणाऊ कि तुमारै औरज़ा रै ज़रीयै, और यीशु मसीह री आत्मा रै दाना रै ज़रीयै, एथरौ इनाम मैरौ छ़ुटकारौ हुआ आ।","kailaiki hāūṁ zāṇāū ki tumārai aurazā rai zarīyai, aura yīśu masīha rī ātmā rai dānā rai zarīyai, ētharau ināma mairau cḧuṭakārau huā ā.",null],[1,20,"हाऊं ता भौरी औरज़ और आश छ़ाड़ाऊ कि हाऊं केज़ी बुशु दी बेइज्ज़त ना औऊ, पर ज़िणै मैरै शक्ती रै हिम्मता रै कारण मसीह री बौड़ाई मैरै शरीरा रै ज़रीयै सौदा औन्दै रौई आ, तीणी ई आबै भी हुआ, च़ाऐ हाऊं ज़ीऊंदौ रौऊ या मौरु लौ।","hāūṁ tā bhaurī auraza aura āśa cḧāṛāū ki hāūṁ kēzī buśu dī bēijzata nā auū, para ziṇai mairai śaktī rai himmatā rai kāraṇa masīha rī bauṛāī mairai śarīrā rai zarīyai saudā aundai rauī ā, tīṇī ī ābai bhī huā, c̈āai hāūṁ zīūṁdau rauū yā mauru lau.",null],[1,21,"कैलैकि मैरौ ज़ीऊंदौ रौइणौ मसीह आ, और मौरणौ लाभ आ।","kailaiki mairau zīūṁdau rauiṇau masīha ā, aura mauraṇau lābha ā.",null],[1,22,"पर अगर शरीरा दी ज़ीऊंदौ रौइंणौ ई मैरै कामा लै ठीक आ ता हाऊं नाईं ज़ाणदौ कि कास छ़ांटु।","para agara śarīrā dī zīūṁdau rauiṁṇau ī mairai kāmā lai ṭhīka ā tā hāūṁ nāīṁ zāṇadau ki kāsa cḧāṁṭu.",null],[1,23,"कैलैकि हाऊं दुई रै बिच़ा दी लौटकौ औन्दौ ऊ; ज़ीऊ ता च़ाह ई कि डेइयौ मसीह काऐ रौऊ, कैलैकि एऊ भौरी आच़्छ़ौ आ,","kailaiki hāūṁ duī rai bic̈ā dī lauṭakau aundau ū; zīū tā c̈āha ī ki ḍēiyau masīha kāai rauū, kailaiki ēū bhaurī āc̈cḧau ā,",null],[1,24,"पर शरीरा दी रौइंणौ तुमारै कारण औज़ौ भी ज़रुरी आ।","para śarīrā dī rauiṁṇau tumārai kāraṇa auzau bhī zarurī ā.",null],[1,25,"एथीलै कि मैरौ एथरौ भरौसौ आ तैबै हाऊं ज़ाणाऊ कि हाऊं ज़ीऊंदौ रौऊ, पर तुमु सौबी आइलै रौऊ ज़ेथकु तुमै विश्वासा दी मज़बूत औन्दै रौऔ और तेथा दी खुश रौऔ;","ēthīlai ki mairau ētharau bharausau ā taibai hāūṁ zāṇāū ki hāūṁ zīūṁdau rauū, para tumu saubī āilai rauū zēthaku tumai viśvāsā dī mazabūta aundai rauau aura tēthā dī khuśa rauau;",null],[1,26,"और ज़ो घमण्ड तुमै मैरै बारै दी कौरा ई। सेऊ मैरै तौइंऐ तुमु काऐ आशणै कु मसीह यीशु दी भौरी बौड़दै रौऔ।","aura zō ghamaṇḍa tumai mairai bārai dī kaurā ī. sēū mairai tauiṁai tumu kāai āśaṇai ku masīha yīśu dī bhaurī bauṛadai rauau.",null],[1,27,"सिरफ एती कौरौ कि तुमारौ चाल-चलन मसीह रै खुशी रै संदेशा ज़िणौ हुआ कि च़ाऐ हाऊं आशियौ तुमु देखू, च़ाऐ नाईं भी आशू, तुमारै बारै दी हाऊं इणौ शुणु कि तुमै एक ई आत्मा दी बौणी रौऔ, और कौठै हुइयौ खुशी रै संदेशा रै विश्वासा लै मैहनत कौरदै रौआ ई,","sirapha ētī kaurau ki tumārau cāla-calana masīha rai khuśī rai saṁdēśā ziṇau huā ki c̈āai hāūṁ āśiyau tumu dēkhū, c̈āai nāīṁ bhī āśū, tumārai bārai dī hāūṁ iṇau śuṇu ki tumai ēka ī ātmā dī bauṇī rauau, aura kauṭhai huiyau khuśī rai saṁdēśā rai viśvāsā lai maihanata kauradai rauā ī,",null],[1,28,"और कैज़ी भी बुशु दी बिरोधीऊ कु डौरदै नाईं। इणौ तिऊं कालै विनाशा री साफ निशाणी आ, पर तुमु कालै उद्धारा रौ और इणौ परमेश्वरा री तौरफा कु आ।","aura kaizī bhī buśu dī birōdhīū ku ḍauradai nāīṁ. iṇau tiūṁ kālai vināśā rī sāpha niśāṇī ā, para tumu kālai uddhārā rau aura iṇau paramēśvarā rī tauraphā ku ā.",null],[1,29,"कैलैकि मसीह रै कारण तुमु माथै इणी बौड़ी दया हुई कि ना सिरफ तेस माथै विश्वास कौरौ पर तेस लै दु:ख भी उठाऔ;","kailaiki masīha rai kāraṇa tumu māthai iṇī bauṛī dayā huī ki nā sirapha tēsa māthai viśvāsa kaurau para tēsa lai du:kha bhī uṭhāau;",null],[1,30,"और तुमुऐ तिणी ई मैहनत कौरणी आ, ज़िणी तुमुऐ हाऊं कौरदै देखौ ऊ, और आबै भी शुणाई कि हाऊं तिणी ई कौराऊ।","aura tumuai tiṇī ī maihanata kauraṇī ā, ziṇī tumuai hāūṁ kauradai dēkhau ū, aura ābai bhī śuṇāī ki hāūṁ tiṇī ī kaurāū.",null],[2,1,"तैबै अगर मसीह दी कुछ़ शान्ति, और प्यारा कु हिम्मत, आत्मा रौ साथ, और कुछ़ करुणा और दया आ,","taibai agara masīha dī kucḧa śānti, aura pyārā ku himmata, ātmā rau sātha, aura kucḧa karuṇā aura dayā ā,",null],[2,2,"ता मेरी एज़ी खुशी पूरी कौरौ कि एक मन छ़ाड़ौ, और एक ई प्यार, एक ई विश्वास, और एक ई इच़्छ़ा छ़ाड़ौ।","tā mērī ēzī khuśī pūrī kaurau ki ēka mana cḧāṛau, aura ēka ī pyāra, ēka ī viśvāsa, aura ēka ī ic̈cḧā cḧāṛau.",null],[2,3,"विरोध या झ़ुठी बौड़ाई लै कुछ़ ना कौरौ, पर छ़ोटौ रौइयौ एकी दुज़ै आपु कु आच़्छ़ै सौमझ़ौ।","virōdha yā jḧuṭhī bauṛāī lai kucḧa nā kaurau, para cḧōṭau rauiyau ēkī duzai āpu ku āc̈cḧai saumajḧau.",null],[2,4,"हर एक आपणै ही हौका री नाईं, पर दुज़ैऊ रै हौका री भी फिकर कौरौ।","hara ēka āpaṇai hī haukā rī nāīṁ, para duzaiū rai haukā rī bhī phikara kaurau.",null],[2,5,"ज़िणौ मसीह यीशु रौ स्वभाव थौ तिणी ई तुमारौ भी स्वभाव हुआ;","ziṇau masīha yīśu rau svabhāva thau tiṇī ī tumārau bhī svabhāva huā;",null],[2,6,"ज़ुणीऐ परमेश्वरा रै रुपा दी हुइयौ भी परमेश्वरा रै ज़िणै हौणा लै आपणै बौशा दी छ़ाड़नै री च़ीज़ नाईं सौमझ़ी।","zuṇīai paramēśvarā rai rupā dī huiyau bhī paramēśvarā rai ziṇai hauṇā lai āpaṇai bauśā dī cḧāṛanai rī c̈īza nāīṁ saumajḧī.",null],[2,7,"पर आपू लै तिणीऐ कुछ़ भी नाईं सौमझ़ौ, और सेवका रौ रुप धारण कियौ, और आदमी रै ज़िणौ हुई गौ।","para āpū lai tiṇīai kucḧa bhī nāīṁ saumajḧau, aura sēvakā rau rupa dhāraṇa kiyau, aura ādamī rai ziṇau huī gau.",null],[2,8,"और आदमी रै रुपा दी परगट हुइयौ आपु छ़ोटौ बौणौ,","aura ādamī rai rupā dī paragaṭa huiyau āpu cḧōṭau bauṇau,",null],[2,9,"एज़ै कारण परमेश्वरै सेऊ भौरी महान भी कियौ, और तेसलै सेऊ नाऊं दैऔ ज़ो सौबी कु बौड़ौ आ,","ēzai kāraṇa paramēśvarai sēū bhaurī mahāna bhī kiyau, aura tēsalai sēū nāūṁ daiau zō saubī ku bauṛau ā,",null],[2,10,"कि ज़ो सौरगा दी और धौतरी माथै और धौतरी भितै आ, सै सौबी यीशु रै नावां दी घुंडै टेका;","ki zō sauragā dī aura dhautarī māthai aura dhautarī bhitai ā, sai saubī yīśu rai nāvāṁ dī ghuṁḍai ṭēkā;",null],[2,11,"और परमेश्वर बाबा री महिमा लै हर एक ज़ीभ अंगीकर कौरा ली कि यीशु मसीह ई प्रभु सा।","aura paramēśvara bābā rī mahimā lai hara ēka zībha aṁgīkara kaurā lī ki yīśu masīha ī prabhu sā.",null],[2,12,"एथीलै ओ मैरै प्यारेऊऔ, ज़िणै तुमै सौदा ओउलै हुकम मानीऔ आशै ई, तिणी ई आबै भी ना सिरफ मुं आइलै रौइंदी बारै पर खास कौरिऐ आबै मैरै दूर रौइयौ भी डौरियौ और कांबीऔ आपणै-आपणै उद्धारा रौ काम पूरौ कौरदै रौऔ।","ēthīlai ō mairai pyārēūau, ziṇai tumai saudā ōulai hukama mānīau āśai ī, tiṇī ī ābai bhī nā sirapha muṁ āilai rauiṁdī bārai para khāsa kauriai ābai mairai dūra rauiyau bhī ḍauriyau aura kāṁbīau āpaṇai-āpaṇai uddhārā rau kāma pūrau kauradai rauau.",null],[2,13,"कैलैकि परमेश्वर ई आ ज़ुणिऐ आपणी इच़्छ़ा कौरीऐ तुमारै ज़ीवा दी इच़्छा और काम, दुइआ बुशै रै कौरनै रौ असर पाऔ आ।","kailaiki paramēśvara ī ā zuṇiai āpaṇī ic̈cḧā kaurīai tumārai zīvā dī ic̈chā aura kāma, duiā buśai rai kauranai rau asara pāau ā.",null],[2,14,"सौबी काम बिण कुड़कुड़ाइऔ और बिण झ़ौगड़िऔ किया कौरौ,","saubī kāma biṇa kuṛakuṛāiau aura biṇa jḧaugaṛiau kiyā kaurau,",null],[2,15,"ताकि तुमै निर्दोश और भौल़ै हुइयौ टेढ़ै और भौरी ढ़ीलै लोगु मांझ़ीऐ परमेश्वरा रै बिणा कलंका री संतान बौणी रौऔ, ज़ास मांझ़िऐ तुमै जीवना रौ वचन निंइयौ संसारा दी ज़ौल़ै औन्दै दियै ज़िणै दिशा ई","tāki tumai nirdōśa aura bhaul̈ai huiyau ṭēṛhai aura bhaurī ṛhīlai lōgu māṁjḧīai paramēśvarā rai biṇā kalaṁkā rī saṁtāna bauṇī rauau, zāsa māṁjḧiai tumai jīvanā rau vacana niṁiyau saṁsārā dī zaul̈ai aundai diyai ziṇai diśā ī",null],[2,16,"कि मसीह रै दिना दी मुंकै घमण्ड कौरनै रौ कारन हुआ कि ना मैरौ आंडणौ और ना मेरी मैहनत कौरणी खराब हुई।","ki masīha rai dinā dī muṁkai ghamaṇḍa kauranai rau kārana huā ki nā mairau āṁḍaṇau aura nā mērī maihanata kauraṇī kharāba huī.",null],[2,17,"अगर मुं तुमारै विश्वासा रै बलिदान और सेवा आइलै आपणौ लोऊ भी बहाउणौ पौड़ालौ, तैबै भी हाऊं खुश ऊ और तुमु सौबी आइलै खुशी मौनावा ऊ।","agara muṁ tumārai viśvāsā rai balidāna aura sēvā āilai āpaṇau lōū bhī bahāuṇau pauṛālau, taibai bhī hāūṁ khuśa ū aura tumu saubī āilai khuśī maunāvā ū.",null],[2,18,"तिणी ई तुमै भी खुश रौऔ और मुं आइलै खुशी कौरौ।","tiṇī ī tumai bhī khuśa rauau aura muṁ āilai khuśī kaurau.",null],[2,19,"मुकै प्रभु यीशु दी आश आ कि हाऊं तीमुथियुस तुमु काऐ ज़ल्दी ई भेज़ाऊ, ताकि तुमुरी हालत शुणियौ मुकै शान्ति मिला।","mukai prabhu yīśu dī āśa ā ki hāūṁ tīmuthiyusa tumu kāai zaldī ī bhēzāū, tāki tumurī hālata śuṇiyau mukai śānti milā.",null],[2,20,"कैलैकि मुं काऐ इणौ ढ़ौंगारौ कोई नाईं ज़ो साफ मौना कौरी तुमारी फिकर कौरा।","kailaiki muṁ kāai iṇau ṛhauṁgārau kōī nāīṁ zō sāpha maunā kaurī tumārī phikara kaurā.",null],[2,21,"कैलैकि सौबी आपणै मतलब ई लोड़ाई, ना कि यीशु मसीह।","kailaiki saubī āpaṇai matalaba ī lōṛāī, nā ki yīśu masīha.",null],[2,22,"पर सेऊ ता तुमुऐ पौरखौ और ज़ाणी भी गौ आ कि ज़िणौ छ़ोहरु बाबा आइलै कौरा सा, तिणी ई तिणीऐ खुशी रौ संदेश फैलाउणै दी मुं आइलै मैहनत की ई।","para sēū tā tumuai paurakhau aura zāṇī bhī gau ā ki ziṇau cḧōharu bābā āilai kaurā sā, tiṇī ī tiṇīai khuśī rau saṁdēśa phailāuṇai dī muṁ āilai maihanata kī ī.",null],[2,23,"एथीलै मुंकै आश आ कि ज़िणी ई मुंकै पौतौ लागा लौ कि मेरी का हालत हुआ आ, तिणी ई हाऊं तेस ख़रकच़ार भेज़ाऊ।","ēthīlai muṁkai āśa ā ki ziṇī ī muṁkai pautau lāgā lau ki mērī kā hālata huā ā, tiṇī ī hāūṁ tēsa k͟harakac̈āra bhēzāū.",null],[2,24,"और मैरौ प्रभु दी भरोसो आ कि हाऊं आपू ई शीगरी आशाऊ।","aura mairau prabhu dī bharōsō ā ki hāūṁ āpū ī śīgarī āśāū.",null],[2,25,"पर मुइंऐ इपफ्रुदीतुसा लै ज़ो मैरौ भाई और मुं आइलै कामा कौरणै वाल़ौ और मुं आइलै योद्धा और तुमारौ दूत, और ज़ुरुरी बुशै दी मेरी सेवा टहल कौरणै वाल़ौ आ, तुमु काऐ भेज़णौ ज़रुरी सौमझ़ौ।","para muiṁai ipaphrudītusā lai zō mairau bhāī aura muṁ āilai kāmā kauraṇai vāl̈au aura muṁ āilai yōddhā aura tumārau dūta, aura zururī buśai dī mērī sēvā ṭahala kauraṇai vāl̈au ā, tumu kāai bhēzaṇau zarurī saumajḧau.",null],[2,26,"कैलैकि तेसरौ ज़ीऊ तुमु सौबी दी लागौ औन्दौ थौ, एज़ै कारण सेऊ घभरांदै रौआ थौ कैलैकि तुमुऐ तेसरी बिमारी री हालत शुणी थी।","kailaiki tēsarau zīū tumu saubī dī lāgau aundau thau, ēzai kāraṇa sēū ghabharāṁdai rauā thau kailaiki tumuai tēsarī bimārī rī hālata śuṇī thī.",null],[2,27,"सेऊ ज़रुरी ई बिमार ता हुई गौ थौ इदरा झ़ाऊं कि मौरणै वाल़ौ थौ, पर परमेश्वरै तेस माथै दया की, और सिरफ तेस ई माथै नाईं पर मुं माथै भी कि मुंकै शोका माथै शोक ना च़ाईं हुऔ।","sēū zarurī ī bimāra tā huī gau thau idarā jḧāūṁ ki mauraṇai vāl̈au thau, para paramēśvarai tēsa māthai dayā kī, aura sirapha tēsa ī māthai nāīṁ para muṁ māthai bhī ki muṁkai śōkā māthai śōka nā c̈āīṁ huau.",null],[2,28,"एथीलै मुंइऐ तेस भेज़णा लै भौरी कोशीष की ई कि तुमै तेसकै मिलीयौ खुशी कौरौ और मैरौ भी शोक कम हुआ।","ēthīlai muṁiai tēsa bhēzaṇā lai bhaurī kōśīṣa kī ī ki tumai tēsakai milīyau khuśī kaurau aura mairau bhī śōka kama huā.",null],[2,29,"एथीलै तुमै प्रभु दी तेसकै भौरी खुशी आइलै मिलीयौ, और इणै री इज़्ज़त कौरनी,","ēthīlai tumai prabhu dī tēsakai bhaurī khuśī āilai milīyau, aura iṇai rī izzata kauranī,",null],[2,30,"कैलैकि सेऊ ई मसीह रै कामा लै आपणै प्राणा माथै कष्टा कौरियौ मौरणै वाल़ौ थौ, ताकि ज़ेथरी कामी तुमुरी तौरफा कु मेरी सेवा दी हुई तेस पूरी कौरै।","kailaiki sēū ī masīha rai kāmā lai āpaṇai prāṇā māthai kaṣṭā kauriyau mauraṇai vāl̈au thau, tāki zētharī kāmī tumurī tauraphā ku mērī sēvā dī huī tēsa pūrī kaurai.",null],[3,1,"एथीलै ओ मैरै भाईओ, प्रभु दी खुश रौऔ। सेई बुशै तुमुलै घौड़ी-घौड़िऐ लिखणै दी मुंदी ता कोई कौष्ट नाईं औन्दौ, और एथदी तुमारी खुशी आ,","ēthīlai ō mairai bhāīō, prabhu dī khuśa rauau. sēī buśai tumulai ghauṛī-ghauṛiai likhaṇai dī muṁdī tā kōī kauṣṭa nāīṁ aundau, aura ēthadī tumārī khuśī ā,",null],[3,2,"कुकुरा कु बौच़ी रौऔ, तिऊं बुरै काम कौरणै वाल़ैऊ कु बौच़ी रौऔ, तिऊं काटणै कूटणा वाल़ेऊ कु बौच़ी रौऔ।","kukurā ku bauc̈ī rauau, tiūṁ burai kāma kauraṇai vāl̈aiū ku bauc̈ī rauau, tiūṁ kāṭaṇai kūṭaṇā vāl̈ēū ku bauc̈ī rauau.",null],[3,3,"कैलैकि खतनावाल़ै ता आमै ई ज़ो परमेश्वरा रै आत्मा री तौरफा कु बौड़ाई कौरी ई, और मसीह यीशु माथै घमण्ड कौरी ई, और शरीरा माथै भरोसो नाईं छ़ाड़दै।","kailaiki khatanāvāl̈ai tā āmai ī zō paramēśvarā rai ātmā rī tauraphā ku bauṛāī kaurī ī, aura masīha yīśu māthai ghamaṇḍa kaurī ī, aura śarīrā māthai bharōsō nāīṁ cḧāṛadai.",null],[3,4,"पर हाऊं ता शरीरा माथै भी भरोसो कौरी बौल़ा ऊ। अगर कासी ओरी रौ शरीरा माथै भरोसो छ़ाड़नै रौ बिच़ार आ, ता हाऊं तेसकु भी बौड़ियौ छ़ाड़ी बौल़ाऊ।","para hāūṁ tā śarīrā māthai bhī bharōsō kaurī baul̈ā ū. agara kāsī ōrī rau śarīrā māthai bharōsō cḧāṛanai rau bic̈āra ā, tā hāūṁ tēsaku bhī bauṛiyau cḧāṛī baul̈āū.",null],[3,5,"आठुऐ दिनै मैरौ खतनौ हुऔ, इस्राएला रै वंश, और बिन्यामीना रै गौत्रा रौ ऊ; इब्रानिऊ रौ इब्रानी ऊ; कानूना रै बारै दी अगर बोलौ ता फरीसी ऊ।","āṭhuai dinai mairau khatanau huau, isrāēlā rai vaṁśa, aura binyāmīnā rai gautrā rau ū; ibrāniū rau ibrānī ū; kānūnā rai bārai dī agara bōlau tā pharīsī ū.",null],[3,6,"खुशी रै बारै दी अगर बोलौ ता धार्मिक खुंबल़ी रौ सताउणै वाल़ौ; और कानूना री धौर्मा रै कामा रै बारै दी अगर बोलौ ता निर्दोष थौ।","khuśī rai bārai dī agara bōlau tā dhārmika khuṁbal̈ī rau satāuṇai vāl̈au; aura kānūnā rī dhaurmā rai kāmā rai bārai dī agara bōlau tā nirdōṣa thau.",null],[3,7,"पर ज़ो-ज़ो बुशै मैरै लाभा री थी, सेई मुइंऐ मसीह रै कारण हानि सौमझ़ी गो ई।","para zō-zō buśai mairai lābhā rī thī, sēī muiṁai masīha rai kāraṇa hāni saumajḧī gō ī.",null],[3,8,"पर हाऊं आपणै प्रभु मसीह यीशु री पराणनै री अच़्छ़ाई रै कारन सौबी बुशै हानि सौमझ़ा ऊ। ज़ासरै कारण मुइंऐ सौबी च़ीज़ु री हानि उठाई, और तिऊं कूड़ौ सौमझ़ा ऊ; ज़ेथ कौरी मुकै मसीह मिला।","para hāūṁ āpaṇai prabhu masīha yīśu rī parāṇanai rī ac̈cḧāī rai kārana saubī buśai hāni saumajḧā ū. zāsarai kāraṇa muiṁai saubī c̈īzu rī hāni uṭhāī, aura tiūṁ kūṛau saumajḧā ū; zētha kaurī mukai masīha milā.",null],[3,9,"और तेसी दी रौऊ; ना कि आपणै तेस धौर्मा रै कामा आइलै, ज़ो कानूना कु आ, पर तेस धौर्मा रै कामा आइलै ज़ो मसीह माथै विश्वास कौरनै रै कारण आ और परमेश्वरा री तौरफा कु विश्वास कौरणै माथै मिलाई।;","aura tēsī dī rauū; nā ki āpaṇai tēsa dhaurmā rai kāmā āilai, zō kānūnā ku ā, para tēsa dhaurmā rai kāmā āilai zō masīha māthai viśvāsa kauranai rai kāraṇa ā aura paramēśvarā rī tauraphā ku viśvāsa kauraṇai māthai milāī.;",null],[3,10,"ताकि हाऊं तेस और तेसरै मौउता माथै ज़ीतणै री शौक्ती लै, और तेस आइलै दु:खा दी साथी रौइंणै रै मर्म ज़ाणू, और तेसरी मौरणै री समानता पाई बौल़ु।","tāki hāūṁ tēsa aura tēsarai mauutā māthai zītaṇai rī śauktī lai, aura tēsa āilai du:khā dī sāthī rauiṁṇai rai marma zāṇū, aura tēsarī mauraṇai rī samānatā pāī baul̈u.",null],[3,11,"कि हाऊं केज़ी भी रीति कु मौरै औन्दै माझ़ीऊ कु ज़ीऊंदै हुणै री ज़ागहा झ़ाऊं पौउंच़ु।","ki hāūṁ kēzī bhī rīti ku maurai aundai mājḧīū ku zīūṁdai huṇai rī zāgahā jḧāūṁ pauuṁc̈u.",null],[3,12,"इणौ मतलब नाईं आ कि मुइंऐ पाई गौ आ, या सिद्ध हुई ऐरौ ऊ; पर तिऐं च़ीज़ पाकुड़ना लै फेट मारदै थाकाऊ लागी; ज़ेथलै मसीह यीशुऐ हाऊं पाकड़ौ थौ।","iṇau matalaba nāīṁ ā ki muiṁai pāī gau ā, yā siddha huī airau ū; para tiaiṁ c̈īza pākuṛanā lai phēṭa māradai thākāū lāgī; zēthalai masīha yīśuai hāūṁ pākaṛau thau.",null],[3,13,"ओ भाईओ, मेरी इच़्छ़ा इयै नाईं आ कि मुइंऐ पाकड़ी ऐरौ आ; पर सिरफ इयै एक काम कौरा ऊ कि ज़ो बुशै छ़ुटी गोई तिऊं बिसरीयौ, औगांऊ री बुशु री तौरफा दी बौड़ीऔ,","ō bhāīō, mērī ic̈cḧā iyai nāīṁ ā ki muiṁai pākaṛī airau ā; para sirapha iyai ēka kāma kaurā ū ki zō buśai cḧuṭī gōī tiūṁ bisarīyau, augāṁū rī buśu rī tauraphā dī bauṛīau,",null],[3,14,"निशाणा री तौरफा दी दौड़दै रौऊ; ताकि तेस इनाम निऊं ज़ेथ लै परमेश्वरै हाऊं मसीह यीशु दी उपरै औटाऔ ऊ।","niśāṇā rī tauraphā dī dauṛadai rauū; tāki tēsa ināma niūṁ zētha lai paramēśvarai hāūṁ masīha yīśu dī uparai auṭāau ū.",null],[3,15,"आमु मांझ़ीऐ ज़ेती सिद्ध ई, इणै बिच़ार छ़ाड़ा, और अगर केज़ी बुशा दी तुमारौ ओर ई बिच़ार हुऔ ता परमेश्वर तेस भी तुमु माथै परगट कौराई।","āmu māṁjḧīai zētī siddha ī, iṇai bic̈āra cḧāṛā, aura agara kēzī buśā dī tumārau ōra ī bic̈āra huau tā paramēśvara tēsa bhī tumu māthai paragaṭa kaurāī.",null],[3,16,"एथीलै आमै ज़ीदरा झ़ाऊं पौउंच़ै ई, तेसी ज़िणै आण्डौ।","ēthīlai āmai zīdarā jḧāūṁ pauuṁc̈ai ī, tēsī ziṇai āṇḍau.",null],[3,17,"ओ भाईओ, तुमै सौबी मिलियौ मुं ज़ीणी च़ाल च़ालौ, और तिऊं पराणी छ़ाड़ौ ज़ो इणै रीति माथै आण्डाई ज़ासरौ औनैणौ तुमै आमुं दी पा ई;","ō bhāīō, tumai saubī miliyau muṁ zīṇī c̈āla c̈ālau, aura tiūṁ parāṇī cḧāṛau zō iṇai rīti māthai āṇḍāī zāsarau aunaiṇau tumai āmuṁ dī pā ī;",null],[3,18,"कैलैकि भौरी इणी च़ाल च़ाला ई, ज़ेथरै बारै दी मुंइऐ तुमुकै घौड़ी-घौड़ीऐ बोलौ आ, और आबै भी लेरी-लेरियौ बोलाऊ कि सै आपणी च़ाल-च़लणा कु मसीह रै क्रूसा रै दुष्मन ई।","kailaiki bhaurī iṇī c̈āla c̈ālā ī, zētharai bārai dī muṁiai tumukai ghauṛī-ghauṛīai bōlau ā, aura ābai bhī lērī-lēriyau bōlāū ki sai āpaṇī c̈āla-c̈alaṇā ku masīha rai krūsā rai duṣmana ī.",null],[3,19,"तिऊंरौ अन्त विनाश आ, तिउंरौ ईश्वर पेट आ, सै आपणी गान्दी बुशु माथै घमण्ड कौराई और संसारा री च़ीज़ेऊ माथै ज़ीऊ लाई छ़ाड़ाई।","tiūṁrau anta vināśa ā, tiuṁrau īśvara pēṭa ā, sai āpaṇī gāndī buśu māthai ghamaṇḍa kaurāī aura saṁsārā rī c̈īzēū māthai zīū lāī cḧāṛāī.",null],[3,20,"पर आमारौ रौउणै रौ देश सौरगा दी आ; और आमै एक छ़ुटकारै देणै वाल़ै प्रभु यीशु मसीह रै तिदरा कु आशणै री बाट लागै औन्दै च़ाणदै।","para āmārau rauuṇai rau dēśa sauragā dī ā; aura āmai ēka cḧuṭakārai dēṇai vāl̈ai prabhu yīśu masīha rai tidarā ku āśaṇai rī bāṭa lāgai aundai c̈āṇadai.",null],[3,21,"सेऊ आपणी शक्ति रै तेस प्रभाव रै अनुसार ज़ासरै ज़रीयै सेऊ सौबी च़ीज़ेऊ आपणै वशा दी कौरी सौका आ, आमारी दीन-हीन शरीर रौ रुप बौदलियौ, आपणै महिमा रै शरीरा ज़िणौ च़ाणाई।","sēū āpaṇī śakti rai tēsa prabhāva rai anusāra zāsarai zarīyai sēū saubī c̈īzēū āpaṇai vaśā dī kaurī saukā ā, āmārī dīna-hīna śarīra rau rupa baudaliyau, āpaṇai mahimā rai śarīrā ziṇau c̈āṇāī.",null],[4,1,"एथीलै ओ मैरै आच़्छ़ै भाईउओ, ज़ेथदी मैरौ ज़ीऊ लागी रौआ सा, ज़ो मेरी खुशी और ताज़ ई, ओ आच़्छ़ै भाईउओ, प्रभु दी इणी कौरी मज़बूत रौऔ।","ēthīlai ō mairai āc̈cḧai bhāīuō, zēthadī mairau zīū lāgī rauā sā, zō mērī khuśī aura tāza ī, ō āc̈cḧai bhāīuō, prabhu dī iṇī kaurī mazabūta rauau.",null],[4,2,"हाऊं यूओदिया लै भी सौमझ़ावा ऊ और सुन्तुखे लै भी सौमझ़ावाऊ, कि सै प्रभु दी एक ज़ीऊ छ़ाड़िऔ बौणी रौऔ।","hāūṁ yūōdiyā lai bhī saumajḧāvā ū aura suntukhē lai bhī saumajḧāvāū, ki sai prabhu dī ēka zīū cḧāṛiau bauṇī rauau.",null],[4,3,"ओ सौच़्च़ै साथी, हाऊं ताउंकै भी औरज़ कौराऊ कि तू तिऊं छ़ेउड़ी री मज़द कौर, कैलैकि तिउंऐ मुं आइलै खुशी रौ संदेश फैलाऊणा दी, क्लेमेंस और मैरै दुज़ै गौश्टणु आइलै मैहनत की ई आ, ज़ासरै नाऊं जिवना री किताबी दी लिखौ औन्दौ आ।","ō sauc̈c̈ai sāthī, hāūṁ tāuṁkai bhī auraza kaurāū ki tū tiūṁ cḧēuṛī rī mazada kaura, kailaiki tiuṁai muṁ āilai khuśī rau saṁdēśa phailāūṇā dī, klēmēṁsa aura mairai duzai gauśṭaṇu āilai maihanata kī ī ā, zāsarai nāūṁ jivanā rī kitābī dī likhau aundau ā.",null],[4,4,"प्रभु दी सौदा खुश रौऔ; हाऊं तुमुलै तौइंऐ बोला ऊ, खुश रौऔ।","prabhu dī saudā khuśa rauau; hāūṁ tumulai tauiṁai bōlā ū, khuśa rauau.",null],[4,5,"तुमारी अच्छाई सौबी आदमीऊ माथै परगट हुआ। प्रभु नज़दीक आ।","tumārī acchāī saubī ādamīū māthai paragaṭa huā. prabhu nazadīka ā.",null],[4,6,"केज़ी भी बुशु री फिकर नाईं कौरौ; पर हर एक बुशु दी तुमारै निवेदन, प्राथना और औरज़ा रै ज़रीयै धन्यावादा आइलै परमेश्वरा काऐ देईया ई।","kēzī bhī buśu rī phikara nāīṁ kaurau; para hara ēka buśu dī tumārai nivēdana, prāthanā aura aurazā rai zarīyai dhanyāvādā āilai paramēśvarā kāai dēīyā ī.",null],[4,7,"तैबै परमेश्वरा री शान्ति, ज़ो सारी सौमझ़ा कु पोरु आ, तुमुरौ ज़ीऊ और तुमुरौ बिच़ार मसीह यीशु दी बौच़ाई छ़ाड़ाई।","taibai paramēśvarā rī śānti, zō sārī saumajḧā ku pōru ā, tumurau zīū aura tumurau bic̈āra masīha yīśu dī bauc̈āī cḧāṛāī.",null],[4,8,"एथीलै ओ भाईउओ, ज़ो ज़ो बुशै सौच़्च़ी ई, और ज़ो ज़ो बुशै इज़्ज़त कौरणै वाल़ी ई, और ज़ो ज़ो बुशै ठीक ई, और ज़ो ज़ो बुशै पवित्र ई, और ज़ो ज़ो बुशै आच़्छ़ी ई, और ज़ो ज़ो बुशै ज़ीवा दी लागा ई, मतलब ज़ो भी सौदगुण और बौड़ाई री बुशै ई तिऊं माथै ध्यान लाई छ़ाड़ौ।","ēthīlai ō bhāīuō, zō zō buśai sauc̈c̈ī ī, aura zō zō buśai izzata kauraṇai vāl̈ī ī, aura zō zō buśai ṭhīka ī, aura zō zō buśai pavitra ī, aura zō zō buśai āc̈cḧī ī, aura zō zō buśai zīvā dī lāgā ī, matalaba zō bhī saudaguṇa aura bauṛāī rī buśai ī tiūṁ māthai dhyāna lāī cḧāṛau.",null],[4,9,"ज़ो बुशै तुमुऐ मुकु शीखी, और मानी, और शुणी, और मुंदी देखी ई, तिऊंरौ पालन कौरौ, तैबै परमेश्वर ज़ो शान्ति रौ राज़ौ आ तुमु आइलै रौआ आ।","zō buśai tumuai muku śīkhī, aura mānī, aura śuṇī, aura muṁdī dēkhī ī, tiūṁrau pālana kaurau, taibai paramēśvara zō śānti rau rāzau ā tumu āilai rauā ā.",null],[4,10,"हाऊं प्रभु दी भौरी खुश ऊ कि आबै एती दिना बासिऐ तुमारी फिकर मैरै बारै दी औज़ौ जागृत हुई आ; ज़ुरुरी तुमुकै शुरु दी भी ऐथरौ बिच़ार थौ, पर तुमुकै एथैरौ मौकौ नाईं मिलौ।","hāūṁ prabhu dī bhaurī khuśa ū ki ābai ētī dinā bāsiai tumārī phikara mairai bārai dī auzau jāgr̥ta huī ā; zururī tumukai śuru dī bhī aitharau bic̈āra thau, para tumukai ēthairau maukau nāīṁ milau.",null],[4,11,"इणौ नाईं कि हाऊं आपणै ज़रुरता रै कारण इणौ बोला ऊ; कैलैकि मुंईऐ इणौ शीखौ आ कि ज़ैज़ै हालता दी ई; तेसी दी खुशी कौरु।","iṇau nāīṁ ki hāūṁ āpaṇai zaruratā rai kāraṇa iṇau bōlā ū; kailaiki muṁīai iṇau śīkhau ā ki zaizai hālatā dī ī; tēsī dī khuśī kauru.",null],[4,12,"हाऊं छ़ोटौ हुणौ भी ज़ाणाऊ और भौड़नौ भी ज़ाणाऊ; हर एक बूश और सौबी हालती दी मुंइऐ ढौटणौ, भुखौ रौउणौ, और बौड़नौ-घौटणौ शीखौ आ।","hāūṁ cḧōṭau huṇau bhī zāṇāū aura bhauṛanau bhī zāṇāū; hara ēka būśa aura saubī hālatī dī muṁiai ḍhauṭaṇau, bhukhau rauuṇau, aura bauṛanau-ghauṭaṇau śīkhau ā.",null],[4,13,"ज़ो मुंदी शक्ति दिआ सा तेसदी हाऊं सारौ कुछ़ कौरी सौका ऊ।","zō muṁdī śakti diā sā tēsadī hāūṁ sārau kucḧa kaurī saukā ū.",null],[4,14,"तैबै भी तुमुऐ भौलौ किऔ आ कि मैरै दु:खा दी मुं आइलै रौऐ ई।","taibai bhī tumuai bhaulau kiau ā ki mairai du:khā dī muṁ āilai rauai ī.",null],[4,15,"ओ फिलिप्पिऊ, तुमै आपू भी ज़ाणा ई कि खुशी रै संदेशा रै परच़ारा रै शुरु दी, ज़ैबै हाऊं मकिदुनिया कु डैऔ थौ, तैबै तुमु छ़ाड़ियौ और कासी खुंबल़ीऐ निणै दैणै रै बारै दी मेरी मज़द नाईं की।","ō philippiū, tumai āpū bhī zāṇā ī ki khuśī rai saṁdēśā rai parac̈ārā rai śuru dī, zaibai hāūṁ makiduniyā ku ḍaiau thau, taibai tumu cḧāṛiyau aura kāsī khuṁbal̈īai niṇai daiṇai rai bārai dī mērī mazada nāīṁ kī.",null],[4,16,"इणै कौरी ज़ैबै हाऊं थिस्सलुनीके दी थौ, तैबै भी तुमुऐ मेरी ज़रुरत पूरी कौरणा लै एकी बारै का पर दुई बारै कुछ़ भेज़ौ थौ।","iṇai kaurī zaibai hāūṁ thissalunīkē dī thau, taibai bhī tumuai mērī zarurata pūrī kauraṇā lai ēkī bārai kā para duī bārai kucḧa bhēzau thau.",null],[4,17,"इणौ नाईं कि हाऊं दाण च़ाहाऊ पर हाऊं इणौ फल़ च़ाहाऊ ज़ो तुमुरै लाभा लै बौड़दै रौआ।","iṇau nāīṁ ki hāūṁ dāṇa c̈āhāū para hāūṁ iṇau phal̈a c̈āhāū zō tumurai lābhā lai bauṛadai rauā.",null],[4,18,"मुंकै सारौ कुछ़ आ, पर भौरी का भी आ; ज़ो च़ीज़ै तुमुऐ इपफ्रदीतुसा रै हाथा कु भेज़ी थी तिऊं निंइंयौ हाऊं ढौटी गो ऊ, सेऊ ता सुखवाल़ी खुशबु, ग्रहण कौरनै रै लायक बलिदान आ, ज़ो परमेश्वरा कै आच़्छ़ी लागा आ।","muṁkai sārau kucḧa ā, para bhaurī kā bhī ā; zō c̈īzai tumuai ipaphradītusā rai hāthā ku bhēzī thī tiūṁ niṁiṁyau hāūṁ ḍhauṭī gō ū, sēū tā sukhavāl̈ī khuśabu, grahaṇa kauranai rai lāyaka balidāna ā, zō paramēśvarā kai āc̈cḧī lāgā ā.",null],[4,19,"मैरौ परमेश्वर भी आपणै तेस धना रै अनुसार ज़ो महिमा समेत मसीह यीशु दी आ, तुमारी हर एक ज़रुरत पूरी कौरा आ।","mairau paramēśvara bhī āpaṇai tēsa dhanā rai anusāra zō mahimā samēta masīha yīśu dī ā, tumārī hara ēka zarurata pūrī kaurā ā.",null],[4,20,"आमारौ परमेश्वर और बाबा री महीमा सौदा-सौदा औन्दी रौआ। आमीन।","āmārau paramēśvara aura bābā rī mahīmā saudā-saudā aundī rauā. āmīna.",null],[4,21,"हर एक पवित्र लोगु लै, ज़ो यीशु मसीहा दी आ ढाल कौरौ। ज़ो भाई मुं आइलै आ, तुमुलै ढ़ाल कौरा ई।","hara ēka pavitra lōgu lai, zō yīśu masīhā dī ā ḍhāla kaurau. zō bhāī muṁ āilai ā, tumulai ṛhāla kaurā ī.",null],[4,22,"सौबी पवित्र लोग, ज़ुरुरी कौरै ज़ो कैसरा रै घौरा रै ई, तुमु लै ढाल कौरा ई","saubī pavitra lōga, zururī kaurai zō kaisarā rai ghaurā rai ī, tumu lai ḍhāla kaurā ī",null],[4,23,"आमारै प्रभु यीशु री बौड़ी दया तुमारी आत्मा आइलै रौआ।","āmārai prabhu yīśu rī bauṛī dayā tumārī ātmā āilai rauā.",null]],"cdh":[[1,1,"मिन्जो इस गल्ल रा भरोस्सा है कि जिनी है तुसां अन्दर भला कम्म सुरू कित्तेरा है, तिनी है ई तिस जो यीशु मसीह जी रे दिन तांई पूरा करणा ।","minjō isa galla rā bharōssā hai ki jinī hai tusāṁ andara bhalā kamma surū kittērā hai, tinī hai ī tisa jō yīśu masīha jī rē dina tāṁī pūrā karaṇā .",null],[1,2,"ठीक होणा कि मैं तुसा सबनी तांई इदेह्ई सोच रख्खां, किजो कि तुसी मेरे मनां अन्दर आई बसेरे हिन्, ते मेरी कैद अन्दर ते खुसखबरी तांई जवाब ते सबूत दैणे अन्दर तुसी सारे मेरे कने अनुग्रह अन्दर हिस्सेदार हिन्","ṭhīka hōṇā ki maiṁ tusā sabanī tāṁī idēhī sōca rakhkhāṁ, kijō ki tusī mērē manāṁ andara āī basērē hin, tē mērī kaida andara tē khusakhabarī tāṁī javāba tē sabūta daiṇē andara tusī sārē mērē kanē anugraha andara hissēdāra hin",null],[1,3,"इस अन्दर परमेश्वर मेरे गवाह् हिन् कि मैं मसीह यीशु जी साह्ई दाह् करी के तुसां सबनी जह्णेयाँ री चाह् करदा रेह्याँ।","isa andara paramēśvara mērē gavāh hin ki maiṁ masīha yīśu jī sāhī dāh karī kē tusāṁ sabanī jahṇēyām̐ rī cāh karadā rēhyām̐.",null],[1,4,"मैं ऐ प्रार्थना करदा कि तुसां रा प्यार ज्ञान ते हर तरिक्के रे सबर समेत होर बी बधदा जाओ,","maiṁ ai prārthanā karadā ki tusāṁ rā pyāra jñāna tē hara tarikkē rē sabara samēta hōra bī badhadā jāō,",null],[1,5,"इत्ते तांई कि तुसी खरी रा खरी गल्लां जो खरी जाणी करी, ते मसीह जी आणे रे दिन तांई सच्चे बणी रैह्यो, ते ठोक्कर मत खान्दे ;","ittē tāṁī ki tusī kharī rā kharī gallāṁ jō kharī jāṇī karī, tē masīha jī āṇē rē dina tāṁī saccē baṇī raihyō, tē ṭhōkkara mata khāndē ;",null],[1,6,"ते तिस धार्मिकता रे फळा कने जेह्ड़े यीशु मसीह जी रे जरिए हुन्दे, भरपूर हुन्दे जाओ जिस कने परमेश्वर री महिमा अते स्तुति हुन्दी रेह्यो।","tē tisa dhārmikatā rē phaḷā kanē jēhṛē yīśu masīha jī rē jariē hundē, bharapūra hundē jāō jisa kanē paramēśvara rī mahimā atē stuti hundī rēhyō.",null],[1,7,"ओ मेरे भाईयों मैं चाह्न्दा कि तुसां जो ऐ पता लगी जाओ कि मेरे कने जेह्ड़ा होएरा है, तिस कने खुसखबरी री ई बढ़ोतरी होएरी है।","ō mērē bhāīyōṁ maiṁ cāhndā ki tusāṁ jō ai patā lagī jāō ki mērē kanē jēhṛā hōērā hai, tisa kanē khusakhabarī rī ī baṛhōtarī hōērī hai.",null],[1,8,"इत्ते तक कि राजे रे राजभवन री सारी पलटन ते बाकी सबनी मह्णुआं अन्दर पता लगी गेया कि मैं मसीह जी तांई कैद है;","ittē taka ki rājē rē rājabhavana rī sārī palaṭana tē bākī sabanī mahṇuāṁ andara patā lagī gēyā ki maiṁ masīha jī tāṁī kaida hai;",null],[1,9,"ते प्रभू अन्दर जेह्ड़े भ्याळ हिन्, तिन्हा बिच रा जादातर मेरे कैद होणे री वजह् कने, हिम्मत बह्न्नी करी परमेश्वर रा वचन बेधड़क सुनाणे री होर बी हिम्मत करदे।","tē prabhū andara jēhṛē bhyāḷa hin, tinhā bica rā jādātara mērē kaida hōṇē rī vajah kanē, himmata bahnnī karī paramēśvara rā vacana bēdhaṛaka sunāṇē rī hōra bī himmata karadē.",null],[1,10,"किछ ता ड़ाह् ते लड़ाई री वजह् कने मसीह जी रा प्रचार करदे ते किछ खरे मना कने।","kicha tā ṛāh tē laṛāī rī vajah kanē masīha jī rā pracāra karadē tē kicha kharē manā kanē.",null],[1,11,"केई जह्णे ता ऐ जाणी करी कि मैं खुसखबरी तांई जवाब दैणे तांई ठैह्राया गेरा है, प्यार कने परचार करदे।","kēī jahṇē tā ai jāṇī karī ki maiṁ khusakhabarī tāṁī javāba daiṇē tāṁī ṭhaihrāyā gērā hai, pyāra kanē paracāra karadē.",null],[1,12,"ते केई जह्णे ता सीधाई कने नी अपण खलाफ होई करी मसीह जी री कथा सुणान्दे,ऐ सोच्ची करी कि मेरी कैद अन्दर मेरे तांई कह्ळा पैदा करन।","tē kēī jahṇē tā sīdhāī kanē nī apaṇa khalāpha hōī karī masīha jī rī kathā suṇāndē,ai sōccī karī ki mērī kaida andara mērē tāṁī kahḷā paidā karana.",null],[1,13,"ता कै होया ? सिरफ ऐ ई कि हर तरह् कने, चाह्ए भान्ने कने चाह्ए सच्चाई कने, मसीह जी री कथा सुणाई जान्दी, ते मैं इधेरे तांई खुस है अते खुस रैह्णा बी है।","tā kai hōyā ? sirapha ai ī ki hara tarah kanē, cāhē bhānnē kanē cāhē saccāī kanē, masīha jī rī kathā suṇāī jāndī, tē maiṁ idhērē tāṁī khusa hai atē khusa raihṇā bī hai.",null],[1,14,"किजो कि मिन्जो पता है कि तुसां री प्राथना रे जरिए, ते यीशु मसीह जी री आत्मा रे दान रे जरिए, इसेरा बदला मेरा उद्धार होणा।","kijō ki minjō patā hai ki tusāṁ rī prāthanā rē jariē, tē yīśu masīha jī rī ātmā rē dāna rē jariē, isērā badalā mērā uddhāra hōṇā.",null],[1,15,"मैं ता ऐ ई दिल का लालसा ते आस रखदा कि मैं कुस्की गल्ल अन्दर सरमिन्दा नां होआं, अपण जिह्याँ मेरी प्रबल हिम्मत री वजह् कने मसीह जी री बड़ाई मेरे जिस्म रे जरिए हमेसा हुन्दी आएरी है, तिह्याँ ई अवे बी हो, चाह्ए मैं जीन्दा रेह्याँ या मरी जां।","maiṁ tā ai ī dila kā lālasā tē āsa rakhadā ki maiṁ kuskī galla andara saramindā nāṁ hōāṁ, apaṇa jihyām̐ mērī prabala himmata rī vajah kanē masīha jī rī baṛāī mērē jisma rē jariē hamēsā hundī āērī hai, tihyām̐ ī avē bī hō, cāhē maiṁ jīndā rēhyām̐ yā marī jāṁ.",null],[1,16,"किजो कि मेरे तांई जीन्दे रैह्णा मसीह है, ते मरी जाणा फाएदा है।","kijō ki mērē tāṁī jīndē raihṇā masīha hai, tē marī jāṇā phāēdā hai.",null],[1,17,"पर अगर सरीर अन्दर जीन्दे रैह्णा ई मेरे कम्म तांई फाएदेमन्द है ता मैं नी जाणदा कि कुस जो चुणां।","para agara sarīra andara jīndē raihṇā ī mērē kamma tāṁī phāēdēmanda hai tā maiṁ nī jāṇadā ki kusa jō cuṇāṁ.",null],[1,18,"किजो कि मैं दोन्नां रे मन्झाट्टे अधर अन्दर लटके रा है; मरजी ता बोलदी कि कूच करी के मसीह जी रा जाई रेह्याँ, किजो कि ऐ बड़ा ई खरा है,","kijō ki maiṁ dōnnāṁ rē manjhāṭṭē adhara andara laṭakē rā hai; marajī tā bōladī ki kūca karī kē masīha jī rā jāī rēhyām̐, kijō ki ai baṛā ī kharā hai,",null],[1,19,"अपण सरीर अन्दर रैह्णा तुसा री वजह् कने होर बी जरूरी है।","apaṇa sarīra andara raihṇā tusā rī vajah kanē hōra bī jarūrī hai.",null],[1,20,"इधेरे तांई कि मिन्जो इसेरा भरोस्सा है तांई ता मिन्जो पता है कि मैं जीन्दे रैह्णा है, अपण तुसा सबनी जह्णेयाँ रे कन्ने रैह्णा जिस कने तुसी भरोस्से अन्दर पक्के हुन्दे जाओ ते तिस अन्दर खुस्स रेह्यो।","idhērē tāṁī ki minjō isērā bharōssā hai tāṁī tā minjō patā hai ki maiṁ jīndē raihṇā hai, apaṇa tusā sabanī jahṇēyām̐ rē kannē raihṇā jisa kanē tusī bharōssē andara pakkē hundē jāō tē tisa andara khussa rēhyō.",null],[1,21,"ते जेह्ड़ा घमण्ड़ तुसी मेरे बारे अन्दर करदे, से मेरे फिरी तुसां का ईणे री वजह् कने मसीह यीशु जी अन्दर जादा बधि जाओ।","tē jēhṛā ghamaṇṛa tusī mērē bārē andara karadē, sē mērē phirī tusāṁ kā īṇē rī vajah kanē masīha yīśu jī andara jādā badhi jāō.",null],[1,22,"सिरफ इतणा करो कि तुसा रा चाल-चलन मसीह जी री खुसखबरी रे जोग्गा होए कि चाह्ए मैं तुसां जो आई करी दिख्खां, चाह्ए नी बी ईय्याँ, तुसां रे बारे अन्दर एह् ई सुणां कि तुसी इक ई आत्मा अन्दर पक्के हिन्, ते इक मन होई करी खुसखबरी रे भरोस्से तांई मैह्नत करदे रैह्न्दे,","sirapha itaṇā karō ki tusā rā cāla-calana masīha jī rī khusakhabarī rē jōggā hōē ki cāhē maiṁ tusāṁ jō āī karī dikhkhāṁ, cāhē nī bī īyyām̐, tusāṁ rē bārē andara ēh ī suṇāṁ ki tusī ika ī ātmā andara pakkē hin, tē ika mana hōī karī khusakhabarī rē bharōssē tāṁī maihnata karadē raihndē,",null],[1,23,"ते कुस्की बी गल्ल अन्दर दुस्मणां का ड़रदे नी। ऐ तिन्हा तांई विनाश री साफ-सुथरी निसानी है, अपण तुसां तांई उद्धार री अते एह् परमेश्वर रे पास्से का है।","tē kuskī bī galla andara dusmaṇāṁ kā ṛaradē nī. ai tinhā tāṁī vināśa rī sāpha-sutharī nisānī hai, apaṇa tusāṁ tāṁī uddhāra rī atē ēh paramēśvara rē pāssē kā hai.",null],[1,24,"किजो कि मसीह जी री वजह् कने तुसा पर ऐ अनुग्रह् होया कि नां सिरफ तिन्हा पर भरोस्सा करो अपण तिन्हा तांई दुख बी सेह्यो;","kijō ki masīha jī rī vajah kanē tusā para ai anugrah hōyā ki nāṁ sirapha tinhā para bharōssā karō apaṇa tinhā tāṁī dukha bī sēhyō;",null],[1,25,"ते तुसां जो तदेह्ई ई मैह्नत करणा पैणी, जदेह्ई तुसा ने मिन्जो करदे दिख्खेरा है, ते अब्बे बी सुणदे कि मैं तिह्याँ ई करदा।","tē tusāṁ jō tadēhī ī maihnata karaṇā paiṇī, jadēhī tusā nē minjō karadē dikhkhērā hai, tē abbē bī suṇadē ki maiṁ tihyām̐ ī karadā.",null],[1,26,"ते प्रभु यीशु बिच कुछ सान्ति ,कने प्याुर ते होसला आत्मा रा मिलण ते कुछ करुणा कने दया है ।","tē prabhu yīśu bica kucha sānti ,kanē pyāura tē hōsalā ātmā rā milaṇa tē kucha karuṇā kanē dayā hai .",null],[1,27,"ते मेरी खुशी पुरी करो इक मन रियो इको इ प्यार ते इको इ चित इको इ मनसा रखो ।","tē mērī khuśī purī karō ika mana riyō ikō i pyāra tē ikō i cita ikō i manasā rakhō .",null],[1,28,"विरोध या झुटी बडाई तिकर किछ मत करो पर दीनता कने इक दुजे जो अपणे का खरा समझो।","virōdha yā jhuṭī baḍāī tikara kicha mata karō para dīnatā kanē ika dujē jō apaṇē kā kharā samajhō.",null],[1,29,"हर बन्दे जो अपणे वारे अन्दर इ नी पर दुसरे रे वारे अन्दर बी सोचणा चाऐदा ।","hara bandē jō apaṇē vārē andara i nī para dusarē rē vārē andara bī sōcaṇā cāaidā .",null],[1,30,"जिदेया प्रभु यीशु जी रा स्वभाव थिया तदेह्या तुसां रा बी स्वभाव हो ।","jidēyā prabhu yīśu jī rā svabhāva thiyā tadēhyā tusāṁ rā bī svabhāva hō .",null],[2,1,"ते प्रभु यीशु बिच कुछ सान्ति ,कने प्‍यार ते होसला आत्मा रा मिलण ते कुछ करुणा कने दया है ।","tē prabhu yīśu bica kucha sānti ,kanē pyāra tē hōsalā ātmā rā milaṇa tē kucha karuṇā kanē dayā hai .",null],[2,2,"ते मेरी खुशी पुरी करोइक मन रियो इको इ प्यार ते इको इ चित इको इ मनसा रखो ।","tē mērī khuśī purī karōika mana riyō ikō i pyāra tē ikō i cita ikō i manasā rakhō .",null],[2,3,"विरोध या झुटी बडाई तिकर किछ मत करो पर दीनता कने इक दुजे जो अपणे का खरा समझो।","virōdha yā jhuṭī baḍāī tikara kicha mata karō para dīnatā kanē ika dujē jō apaṇē kā kharā samajhō.",null],[2,4,"हर बन्‍दे जो अपणे वारे अन्दर इ नी पर दुसरे रे वारे अन्दर बी सोचणा चाऐदा ।","hara bandē jō apaṇē vārē andara i nī para dusarē rē vārē andara bī sōcaṇā cāaidā .",null],[2,5,"जदेया प्रभु यीशु मसीह रा स्वभाव थिया तदेया तुसां रा बी हो।","jadēyā prabhu yīśu masīha rā svabhāva thiyā tadēyā tusāṁ rā bī hō.",null],[2,6,"जिसने परमेश्वर दा रुप होई के बी तिन्हा ने परमेश्वर दे समान अपणे आप जो नी समझेया ते कने तिस जो अपणे का रखणे री चीज नी समझी ।","jisanē paramēśvara dā rupa hōī kē bī tinhā nē paramēśvara dē samāna apaṇē āpa jō nī samajhēyā tē kanē tisa jō apaṇē kā rakhaṇē rī cīja nī samajhī .",null],[2,7,"पर अपणे आप जो शून्य करी लितेया कने तिन्हा ने दास रा रुप धारण करी लिया ते आम मणु सिई बणी गे ।","para apaṇē āpa jō śūnya karī litēyā kanē tinhā nē dāsa rā rupa dhāraṇa karī liyā tē āma maṇu siī baṇī gē .",null],[2,8,"ते मणु रे रुप बिच प्रकट होई के अपणे आप जो दीन कित्तेया इतणे तिक्‍कर कि से इतणी गल मनणे वाळे रे तिन्हा ने क्रूस री मोत जो बी सांई लई ।","tē maṇu rē rupa bica prakaṭa hōī kē apaṇē āpa jō dīna kittēyā itaṇē tikkara ki sē itaṇī gala manaṇē vāḷē rē tinhā nē krūsa rī mōta jō bī sāṁī laī .",null],[2,9,"इसेरे कारण परमेश्वर ने तिन्हा जो सबनी का बड्डा समझेया कने तिन्हा जो से ना दित्तेया जेडा सबनी ना का अच्‍छा है, ते जेडे स्‍वर्ग अन्दर हिन ,धरती पर ते का हेठे से सारे जणे प्रभु यीशु जी रे अगे झुकण ।","isērē kāraṇa paramēśvara nē tinhā jō sabanī kā baḍḍā samajhēyā kanē tinhā jō sē nā dittēyā jēḍā sabanī nā kā acchā hai, tē jēḍē svarga andara hina ,dharatī para tē kā hēṭhē sē sārē jaṇē prabhu yīśu jī rē agē jhukaṇa .",null],[2,10,"ते जेडे स्वर्ग अन्दर हिन् ,धरती पुर ते का हेठे से सारे जणी प्रभु यीशु जी रे अगे झुकन ।","tē jēḍē svarga andara hin ,dharatī pura tē kā hēṭhē sē sārē jaṇī prabhu yīśu jī rē agē jhukana .",null],[2,11,"ते पिता परमेश्वर री महिमा तिकर सारे जणे ये मनी लैण कि प्रभु यीशु जी ही प्रभु हिन । संसार बीच लोई सई चमको","tē pitā paramēśvara rī mahimā tikara sārē jaṇē yē manī laiṇa ki prabhu yīśu jī hī prabhu hina . saṁsāra bīca lōī saī camakō",null],[2,12,"इधेरे तांई मेरे प्यारेओ जियां तुसां पैल्ले का इ गल्ल मन्दे आए तियें इ अबे बी ना कि मेरे कने रैणे कने इ नि पर मेरे का दूर रहणे पर बी डरदे ते कमदे होए अपणे दया रा कम पुरा करदे जाओ ।","idhērē tāṁī mērē pyārēō jiyāṁ tusāṁ paillē kā i galla mandē āē tiyēṁ i abē bī nā ki mērē kanē raiṇē kanē i ni para mērē kā dūra rahaṇē para bī ḍaradē tē kamadē hōē apaṇē dayā rā kama purā karadē jāō .",null],[2,13,"किजो कि परमेश्वर ने इ अपणी मर्जी कने तुसां रे मन बिच ऐ गल पाई कि तुसां री इच्छा ते कम करणे रा प्रभाव पाया ।","kijō ki paramēśvara nē i apaṇī marjī kanē tusāṁ rē mana bica ai gala pāī ki tusāṁ rī icchā tē kama karaṇē rā prabhāva pāyā .",null],[2,14,"सारे कम बगैर कुडकुडाए बिना कुसी विवाद रे करो ।","sārē kama bagaira kuḍakuḍāē binā kusī vivāda rē karō .",null],[2,15,"ताकी तुसां निर्दोष भोळे होई के ,टेढे ते नी मऩणे वाळे लोकाँ बिच परमेश्वर रे निष्कलंक बच्चे बणी रियो जिन्हेरे बीच तुसां जिन्दगी रा बचन लई के लोई सई नजरी आन्दे ।","tākī tusāṁ nirdōṣa bhōḷē hōī kē ,ṭēḍhē tē nī maṉaṇē vāḷē lōkām̐ bica paramēśvara rē niṣkalaṁka baccē baṇī riyō jinhērē bīca tusāṁ jindagī rā bacana laī kē lōī saī najarī āndē .",null],[2,16,"ते जिस वक्त प्रभु यीशु जी रोज आण ता मेरे का घमन्ड रा कारण हो की मेरा दौडणा ते मेहन्त करणा ईयाँ नी गया।","tē jisa vakta prabhu yīśu jī rōja āṇa tā mērē kā ghamanḍa rā kāraṇa hō kī mērā dauḍaṇā tē mēhanta karaṇā īyām̐ nī gayā.",null],[2,17,"अगर मिन्जो तुसां रे विश्वास रुपी बलिदान तिकर अपणा खून देणा पे ता बी मैं खुशी है ,ते कने मैं तुसा सबनी कने खुशी मनादा ।","agara minjō tusāṁ rē viśvāsa rupī balidāna tikara apaṇā khūna dēṇā pē tā bī maiṁ khuśī hai ,tē kanē maiṁ tusā sabanī kanē khuśī manādā .",null],[2,18,"ते तुसां बी खुशी रियो ते मेरे कने खुशी मनाओ । तीमुथियुस कने इपफ्रदीतुस","tē tusāṁ bī khuśī riyō tē mērē kanē khuśī manāō . tīmuthiyusa kanē ipaphradītusa",null],[2,19,"मिन्‍जो आसा है कि मै तिमुथियुस जो तोळे इ तुसां का भेजां ताकी तुसां रा हाल चाल जाणी के मिन्जो शान्ती मिले ।","minjō āsā hai ki mai timuthiyusa jō tōḷē i tusāṁ kā bhējāṁ tākī tusāṁ rā hāla cāla jāṇī kē minjō śāntī milē .",null],[2,20,"किजो की मेरे का ऐसे स्भाव रा कोइ नी है कि से खरे मन कने तुसां री चिन्ता करे ।","kijō kī mērē kā aisē sbhāva rā kōi nī hai ki sē kharē mana kanē tusāṁ rī cintā karē .",null],[2,21,"किजो की सारे जण अपणे लालच री खोज बिच हिन ना की प्रभु यीशु री ।","kijō kī sārē jaṇa apaṇē lālaca rī khōja bica hina nā kī prabhu yīśu rī .",null],[2,22,"तिस जो ता तुसां सबनी जण ने जाणी लेया कि जियां पुञ बाबे कने करदा तियें तिस ने सुसमाचार फैलाणे अन्दर मेरे कने मेहनत किती है ।","tisa jō tā tusāṁ sabanī jaṇa nē jāṇī lēyā ki jiyāṁ puña bābē kanē karadā tiyēṁ tisa nē susamācāra phailāṇē andara mērē kanē mēhanata kitī hai .",null],[2,23,"इधेरे तांई जियां इ मिन्जो पता लगगां कि मेरी अवे क्या हालत है उसी वक्त मै तसियो तोळे भैजी दिगां ।","idhērē tāṁī jiyāṁ i minjō patā lagagāṁ ki mērī avē kyā hālata hai usī vakta mai tasiyō tōḷē bhaijī digāṁ .",null],[2,24,"ते मिन्जो प्रभु जी अन्दर भरोसा है कि मै अपु बी तोळे आणा ।","tē minjō prabhu jī andara bharōsā hai ki mai apu bī tōḷē āṇā .",null],[2,25,"पर मैं इपफ्रितुस जेडा मेरा भाई ते कने कम करणे वाळ ते लडने वाळा ते तुसा जो खबर देणे वाळा , मेरी सेवा करणे वाळा से मैं तुसां का भेजणा जरुरी समझेया ।","para maiṁ ipaphritusa jēḍā mērā bhāī tē kanē kama karaṇē vāḷa tē laḍanē vāḷā tē tusā jō khabara dēṇē vāḷā , mērī sēvā karaṇē vāḷā sē maiṁ tusāṁ kā bhējaṇā jarurī samajhēyā .",null],[2,26,"किजो की तिन्हेरा मन तुसां सबनी कने लगी रे रा ए इस कारण से बेचैन थिया किजो कि तुसां सबनी ने मेरी बीमारी रा हाल जाणेया था ।","kijō kī tinhērā mana tusāṁ sabanī kanē lagī rē rā ē isa kāraṇa sē bēcaina thiyā kijō ki tusāṁ sabanī nē mērī bīmārī rā hāla jāṇēyā thā .",null],[2,27,"पक्का से मरने वाळा था पर तिस जो परमेश्वर ने बचाई लेया ते मिन्जो बी की","pakkā sē maranē vāḷā thā para tisa jō paramēśvara nē bacāī lēyā tē minjō bī kī",null],[2,28,"इधरे तांई मैं तिस जो भेजणे री तोळ किती कि तुसां खुस हो जाओ ते मेरा दुख बी घटी जाओ ।","idharē tāṁī maiṁ tisa jō bhējaṇē rī tōḷa kitī ki tusāṁ khusa hō jāō tē mērā dukha bī ghaṭī jāō .",null],[2,29,"इधेरे तिकर तुसा उसकने बडी खुशी कने मिलणा ते ऐसे मणु रा आदर करेया करणा ।","idhērē tikara tusā usakanē baḍī khuśī kanē milaṇā tē aisē maṇu rā ādara karēyā karaṇā .",null],[2,30,"किजो कि से यीशु जी रे कम तिकर अपणे प्राण जो खतरे बिच पाई के मरणे वाळ इ था ताकी जेडी कमी सेवा अनदर तुसा रे पासे का हुई तिस जो पुरा करी सको ।","kijō ki sē yīśu jī rē kama tikara apaṇē prāṇa jō khatarē bica pāī kē maraṇē vāḷa i thā tākī jēḍī kamī sēvā anadara tusā rē pāsē kā huī tisa jō purā karī sakō .",null],[3,1,"जोश रे बारे जे बोला ता मैं कलीसिया जो तंग करणे वाळा, नियम रे कम्म रे साह्ब कने बेकसुर थिय्या।","jōśa rē bārē jē bōlā tā maiṁ kalīsiyā jō taṁga karaṇē vāḷā, niyama rē kamma rē sāhba kanē bēkasura thiyyā.",null],[3,2,"अपण तां जे मेरा फायदा थिय्या, अज्ज उस्सी जो ई मसीह बिच अपणा नुक्सान समझदा।","apaṇa tāṁ jē mērā phāyadā thiyyā, ajja ussī jō ī masīha bica apaṇā nuksāna samajhadā.",null],[3,3,"इस का बड्डी गल्ल एह् कि मैं अपणे प्रभु यीशु जी रे ज्ञान री महानता री वजह कने सब गल्लां जो घटिया समझदा थिय्या। उसेरे तांई मैं सब किच्छ छड्डी दित्तेया अत्ते मैं सब जो नफरत रे लायक चीज समझणे लग्गेया ताकि मिंजो मसीह मिल्ली जाओ।","isa kā baḍḍī galla ēh ki maiṁ apaṇē prabhu yīśu jī rē jñāna rī mahānatā rī vajaha kanē saba gallāṁ jō ghaṭiyā samajhadā thiyyā. usērē tāṁī maiṁ saba kiccha chaḍḍī dittēyā attē maiṁ saba jō napharata rē lāyaka cīja samajhaṇē laggēyā tāki miṁjō masīha millī jāō.",null],[3,4,"अत्ते मसीह बिच ई मिंजो तोपेया जाये, मेरी धार्मिकता री वजह कने नी जे नियमां पर टिकी री है, बल्कि उस धार्मिकता कने जे मसीह पर विश्वास करणे री वजह कने परमेश्वर का मिलदी अत्ते जिसेरा अधार विश्वास है।","attē masīha bica ī miṁjō tōpēyā jāyē, mērī dhārmikatā rī vajaha kanē nī jē niyamāṁ para ṭikī rī hai, balki usa dhārmikatā kanē jē masīha para viśvāsa karaṇē rī vajaha kanē paramēśvara kā miladī attē jisērā adhāra viśvāsa hai.",null],[3,5,"मैं मसीह जो जानणा चाह्न्दा अत्ते उस सक्ति जो मह्सूस करणा चाह्न्दा जिस कने उन्हेरा पुनरूत्थान होया थिया। मैं उमेरी मुसिबतां रा साझी होणा चाह्न्दा। अत्ते उस्सी रूप जो पाणा चाह्न्दा जिस जो उसने अपणे मरणे जरिये पाया थिय्या।","maiṁ masīha jō jānaṇā cāhndā attē usa sakti jō mahsūsa karaṇā cāhndā jisa kanē unhērā punarūtthāna hōyā thiyā. maiṁ umērī musibatāṁ rā sājhī hōṇā cāhndā. attē ussī rūpa jō pāṇā cāhndā jisa jō usanē apaṇē maraṇē jariyē pāyā thiyyā.",null],[3,6,"इस आस कने कि मैं इस तरिक्के कने मरे रेयां बिच का जिंदा होई जां ते पुनरूत्थान मिल्ली जाओ।","isa āsa kanē ki maiṁ isa tarikkē kanē marē rēyāṁ bica kā jiṁdā hōī jāṁ tē punarūtthāna millī jāō.",null],[3,7,"एह् मतलब नी है कि मिंजो मिल्ली गेया या मैं पूरा सही है। अपण मैं उस मंजिल जो पाणे तांई लगातार कोसिस करेया करदा है जिसेरे तांई यीशु मसीह ने मिंजो पकड़ेया है।","ēh matalaba nī hai ki miṁjō millī gēyā yā maiṁ pūrā sahī hai. apaṇa maiṁ usa maṁjila jō pāṇē tāṁī lagātāra kōsisa karēyā karadā hai jisērē tāṁī yīśu masīha nē miṁjō pakaṛēyā hai.",null],[3,8,"ओ मेरे भाइयों, मेरी एह् सोचदा कि मिंजो से मिल्ली गेया है, अपण गल्ल है कि जे गल्लां पिच्छे रेह्ई गेई, तिन्हा जो भूली करी उस उस मंजिल री तरफ पुजणे तांई लड़दा रैह्न्दा।","ō mērē bhāiyōṁ, mērī ēh sōcadā ki miṁjō sē millī gēyā hai, apaṇa galla hai ki jē gallāṁ picchē rēhī gēī, tinhā jō bhūlī karī usa usa maṁjila rī tarapha pujaṇē tāṁī laṛadā raihndā.",null],[3,9,"उस मंजिल तांई लगातार कोसिस करदा कि से ईनाम मिंजो मिल्लो जिस तांई परमेश्वर ने यीशु मसीह बिच ऊपर सद्देया है।","usa maṁjila tāṁī lagātāra kōsisa karadā ki sē īnāma miṁjō millō jisa tāṁī paramēśvara nē yīśu masīha bica ūpara saddēyā hai.",null],[3,10,"ताकि उन्हा मह्णुआं रा, जे असां बिच का पूरे सही मह्णु बणी गे हिन, ऐई सोच रखन, अपण जे तुसी कुसकी गल्ल जो कुसकी होर ई तरिक्के कने सोचदे हिन ता तुम्हारे तांई उस जो परमेश्वर ने साफ तरिक्के कने दस्सी दैणा।","tāki unhā mahṇuāṁ rā, jē asāṁ bica kā pūrē sahī mahṇu baṇī gē hina, aiī sōca rakhana, apaṇa jē tusī kusakī galla jō kusakī hōra ī tarikkē kanē sōcadē hina tā tumhārē tāṁī usa jō paramēśvara nē sāpha tarikkē kanē dassī daiṇā.",null],[3,11,"जिस सच्च तक असी पुज्जी गेरे हिन, असां जो उस्सी पर चलदे रेह्णा चहिंदा।","jisa sacca taka asī pujjī gērē hina, asāṁ jō ussī para caladē rēhṇā cahiṁdā.",null],[3,12,"ओ मेरे भाइयों, तुसी सब मेरे जदेया चाल-चलन रख्खो। जे उदारण असांं ने तुम्हारे सामणे रख्खेया है, तिसेरे साह्ब कने जे जिंदे, तिन्हा पर ध्यान देयो।","ō mērē bhāiyōṁ, tusī saba mērē jadēyā cāla-calana rakhkhō. jē udāraṇa asāṁṁ nē tumhārē sāmaṇē rakhkhēyā hai, tisērē sāhba kanē jē jiṁdē, tinhā para dhyāna dēyō.",null],[3,13,"किजो कि इदेय बी मह्णु हिन जिन्हेरे बारे मैं तुसां जो घड़ी-घड़ी दस्सेया अत्ते अबे बी रौई-रौई करी तुम्हारे जो दस्सदा कि तिन्हेरा जीण इदेया है कि से मसीह री सूळी रे दुश्मण हिन।","kijō ki idēya bī mahṇu hina jinhērē bārē maiṁ tusāṁ jō ghaṛī-ghaṛī dassēyā attē abē bī rauī-rauī karī tumhārē jō dassadā ki tinhērā jīṇa idēyā hai ki sē masīha rī sūḷī rē duśmaṇa hina.",null],[3,14,"उन्हेरा अंत बिनाश है। उन्हेरा पेट ई परमेश्वर है। अत्ते जिस पर उन्हा जो शर्म आणी चहिंदी, उस पर से फक्कर करदे। तिन्हा जो सिरफ दुनियां री चीजां री फिकर है।","unhērā aṁta bināśa hai. unhērā pēṭa ī paramēśvara hai. attē jisa para unhā jō śarma āṇī cahiṁdī, usa para sē phakkara karadē. tinhā jō sirapha duniyāṁ rī cījāṁ rī phikara hai.",null],[3,15,"अपण म्हारी जन्मभूमि ता स्वर्ग बिच है। तित्ते का ई असी अपणे प्रभु यीशु मसीह रे आणे री भाळ करेया करदे हिन्।","apaṇa mhārī janmabhūmi tā svarga bica hai. tittē kā ī asī apaṇē prabhu yīśu masīha rē āṇē rī bhāḷa karēyā karadē hin.",null],[3,16,"अपणी उस सक्ति कने जिस कने सब चीजां जो से अपणे वस बिच करी सकदा, असा रे कमजोर सरीर जो बदली करी अपणे महिममय सरीर साह्ई बणाई दैणा।","apaṇī usa sakti kanē jisa kanē saba cījāṁ jō sē apaṇē vasa bica karī sakadā, asā rē kamajōra sarīra jō badalī karī apaṇē mahimamaya sarīra sāhī baṇāī daiṇā.",null],[3,17,"ईधेरे तांई,ओ मेरे भाईयों,जिन्हा बिच मेरा दिल लगी रैहन्दा जे मेरी खुशी ते मुकट हिन,ओ प्यारे भाईयों प्रभू बिच इसी तरिक्के कने टिके रेयो।","īdhērē tāṁī,ō mērē bhāīyōṁ,jinhā bica mērā dila lagī raihandā jē mērī khuśī tē mukaṭa hina,ō pyārē bhāīyōṁ prabhū bica isī tarikkē kanē ṭikē rēyō.",null],[3,18,"मै यूओदिया जो बी समझादां ते सुन्तुखे जो बी,कि से प्रभू बिच इक्क मन रेय।","mai yūōdiyā jō bī samajhādāṁ tē suntukhē jō bī,ki sē prabhū bica ikka mana rēya.",null],[3,19,"ओ सच्चे साथी,मै तेरे का मिन्नत करदा कि तू तिन्हा जनानियां री मदद कर,किजो की तिन्हा ने मेरे कने शुभ-भसेख जो फलाणे बिच क्लेमेंस ते मेरे होर साथियां कने मेहनत कित्ती जिन्हेरे नां जिन्दगी री कताब बिच लिख्खे रे हिन।","ō saccē sāthī,mai tērē kā minnata karadā ki tū tinhā janāniyāṁ rī madada kara,kijō kī tinhā nē mērē kanē śubha-bhasēkha jō phalāṇē bica klēmēṁsa tē mērē hōra sāthiyāṁ kanē mēhanata kittī jinhērē nāṁ jindagī rī katāba bica likhkhē rē hina.",null],[3,20,"प्रभू बिच हमेसा खुस रेयो, “मै फिरी बोलदा खुस रेयो।","prabhū bica hamēsā khusa rēyō, “mai phirī bōladā khusa rēyō.",null],[3,21,"तुसां री कोमलता लोक्कां रे सामणे आये। प्रभू नेड़े है।","tusāṁ rī kōmalatā lōkkāṁ rē sāmaṇē āyē. prabhū nēṛē hai.",null],[4,1,"कुसकी बी गल्ल री फिकर मत करो’, अपण हर इक्क गल्ल बिच तुसां री जरुरतां री गल्लां प्रार्थना ते मिन्नतां कने परमेश्वर रे सामणे ले आये जाये।","kusakī bī galla rī phikara mata karō’, apaṇa hara ikka galla bica tusāṁ rī jaruratāṁ rī gallāṁ prārthanā tē minnatāṁ kanē paramēśvara rē sāmaṇē lē āyē jāyē.",null],[4,2,"तां परमेश्वर री सातीं जे सारी समझ का परे है,तुसां रे दिल ते तुसां री गल्लां जो मसीह यीशु जी बिच सभांली करी रखणा।","tāṁ paramēśvara rī sātīṁ jē sārī samajha kā parē hai,tusāṁ rē dila tē tusāṁ rī gallāṁ jō masīha yīśu jī bica sabhāṁlī karī rakhaṇā.",null],[4,3,"ईधेरे तांई ओ भाईयों,जे जे गल्लां सच हिन ते जे गल्लां इज्जत दैणे तांई हिन ते जे गल्लां ठीक हिन,ते जे गल्लां पवित्र हिन, ते जे गल्लां सोह्णि हिन, ते जे जे गल्लां मन जो भाणे वाळी हिन, मतलब जे बी खरी आदत ते तारीफ लायक गल्लां हिन,तिन्हेरे पर मन लाया करो।","īdhērē tāṁī ō bhāīyōṁ,jē jē gallāṁ saca hina tē jē gallāṁ ijjata daiṇē tāṁī hina tē jē gallāṁ ṭhīka hina,tē jē gallāṁ pavitra hina, tē jē gallāṁ sōhṇi hina, tē jē jē gallāṁ mana jō bhāṇē vāḷī hina, matalaba jē bī kharī ādata tē tārīpha lāyaka gallāṁ hina,tinhērē para mana lāyā karō.",null],[4,4,"जे गल्लां तुसी मेरे का सिख्खी ते मन्नी ते सुणी, ते मेरे बिच दिख्खी तिन्हेरे जो ई मन्नेया करो तां परमेश्वर जे सान्ति रा सोत्ता है, ने तुसां कने रैहणा।","jē gallāṁ tusī mērē kā sikhkhī tē mannī tē suṇī, tē mērē bica dikhkhī tinhērē jō ī mannēyā karō tāṁ paramēśvara jē sānti rā sōttā hai, nē tusāṁ kanē raihaṇā.",null],[4,5,"मै प्रभू बिच बड़ा खुस है, कि अवे इन्ने दिनां बाद तुसां जो मेरे बारे बिच फिरी होणा लगे री है’, पक्का इ तुसां जो पैल्ले बी इसेरा ध्यान थिया अपण तुसां जो इसेरा मोक्का नी मिल्लेया।","mai prabhū bica baṛā khusa hai, ki avē innē dināṁ bāda tusāṁ jō mērē bārē bica phirī hōṇā lagē rī hai’, pakkā i tusāṁ jō paillē bī isērā dhyāna thiyā apaṇa tusāṁ jō isērā mōkkā nī millēyā.",null],[4,6,"ए नी कि मै अपणी घाटे री वजह कने इय्यां बोल्लेया करदा है’,किजो कि मै सिख्खे रा है कि जिस हाल बिच मै है तिस बिच इ खुस रेयां।","ē nī ki mai apaṇī ghāṭē rī vajaha kanē iyyāṁ bōllēyā karadā hai’,kijō ki mai sikhkhē rā hai ki jisa hāla bica mai hai tisa bica i khusa rēyāṁ.",null],[4,7,"मै छोटा होणा बी जाणदा ते बधणा बी जाणदा’, हर इक्क गल्ल ते सारी गल्लां बिच रजणा, भुक्खा रैहणा ते घटणा बधणा सिक्खे रा है।","mai chōṭā hōṇā bī jāṇadā tē badhaṇā bī jāṇadā’, hara ikka galla tē sārī gallāṁ bica rajaṇā, bhukkhā raihaṇā tē ghaṭaṇā badhaṇā sikkhē rā hai.",null],[4,8,"जे मिन्जो ताकत दिदें तिस बिच मै सब किछ करी सकदा।","jē minjō tākata didēṁ tisa bica mai saba kicha karī sakadā.",null],[4,9,"तां बी तुसां ने खरा कित्तेया कि मेरे दुख बिच मेरे कने सामिल होए।","tāṁ bī tusāṁ nē kharā kittēyā ki mērē dukha bica mērē kanē sāmila hōē.",null],[4,10,"ओ फिलीप्पियों तुसी अप्पु ई जाणदे कि शुभ-भसेख री सुरुआत बिच जां मै मकिदुनिया का निकळेया तां तुसां जो छड्डि करी कुसकी होर मडंली ने लैणे-दैणे बिच मेरी मदद नी कित्ती।","ō philīppiyōṁ tusī appu ī jāṇadē ki śubha-bhasēkha rī suruāta bica jāṁ mai makiduniyā kā nikaḷēyā tāṁ tusāṁ jō chaḍḍi karī kusakī hōra maḍaṁlī nē laiṇē-daiṇē bica mērī madada nī kittī.",null],[4,11,"इसी तरिक्के कने जां मै थिस्लुनिके बिच थिया तां बी तुसां ने मेरे घाटे जो पुरा करणे तांई इक्क बारी क्या अपण दो बारी किछ भेज्जेया थिया।","isī tarikkē kanē jāṁ mai thislunikē bica thiyā tāṁ bī tusāṁ nē mērē ghāṭē jō purā karaṇē tāṁī ikka bārī kyā apaṇa dō bārī kicha bhējjēyā thiyā.",null],[4,12,"ए नी कि मै दान चाह्दां अपण मै एदेया फळ चाह्दां जे तुसां रे फैदे तिकर बदधा जाए।","ē nī ki mai dāna cāhdāṁ apaṇa mai ēdēyā phaḷa cāhdāṁ jē tusāṁ rē phaidē tikara badadhā jāē.",null],[4,13,"किजोकी मेरे जो से सारी चिजां मिली गी, मेरे का जरुरत री हर चीज है किजो कि इपफ्रुदितुस रे हत्था का भेजि री सारी चिजां मेरे जो मिली गे री हिन,इक्क ग्रहण करणे जोग्ग","kijōkī mērē jō sē sārī cijāṁ milī gī, mērē kā jarurata rī hara cīja hai kijō ki ipaphruditusa rē hatthā kā bhēji rī sārī cijāṁ mērē jō milī gē rī hina,ikka grahaṇa karaṇē jōgga",null],[4,14,"मेरा परमेश्वर बी जे अपणे तिस धन रे हसाब कने महीमा कने मसीह यीशु जी बिच है,तुसां री हर जरुरत जो पुरा करणा।","mērā paramēśvara bī jē apaṇē tisa dhana rē hasāba kanē mahīmā kanē masīha yīśu jī bica hai,tusāṁ rī hara jarurata jō purā karaṇā.",null],[4,15,"असां रे परमेश्वर ते पिता री महीमा हमेसा-हमेसा तिकर हुदीं रेय, आमीन!","asāṁ rē paramēśvara tē pitā rī mahīmā hamēsā-hamēsā tikara hudīṁ rēya, āmīna!",null],[4,16,"हर इक्क पवित्र म्हणु जे मसीह बिच है,नमस्कार करो,जे भाई मेरे कने तुसां जो नमस्कार बोलदे।","hara ikka pavitra mhaṇu jē masīha bica hai,namaskāra karō,jē bhāī mērē kanē tusāṁ jō namaskāra bōladē.",null],[4,17,"सारे पवित्र लोक,खास तौर पर जे कैसर रे घराने रे हिन तुसां जो नमस्कार बोलदे हिन।","sārē pavitra lōka,khāsa taura para jē kaisara rē gharānē rē hina tusāṁ jō namaskāra bōladē hina.",null],[4,18,"असां रे प्रभु यीशु मसीह रा अनुग्रह तुसां री आत्मा कने हुदां रेह्।","asāṁ rē prabhu yīśu masīha rā anugraha tusāṁ rī ātmā kanē hudāṁ rēh.",null],[4,19,"मेरा परमेश्वर बी जे अपणे तिस धन रे हसाब कने महीमा कने मसीह यीशु जी बिच है,तुसां री हर जरुरत जो पुरा करणा।","mērā paramēśvara bī jē apaṇē tisa dhana rē hasāba kanē mahīmā kanē masīha yīśu jī bica hai,tusāṁ rī hara jarurata jō purā karaṇā.",null],[4,20,"असां रे परमेश्वर ते पिता री महीमा हमेसा-हमेसा तिक्कर हुदीं रेय, आमीन!","asāṁ rē paramēśvara tē pitā rī mahīmā hamēsā-hamēsā tikkara hudīṁ rēya, āmīna!",null],[4,21,"हर इक्क पवित्र म्हणु जे मसीह बिच है,नमस्कार करो,जे भाई मेरे कने तुसां जो नमस्कार बोलदे।","hara ikka pavitra mhaṇu jē masīha bica hai,namaskāra karō,jē bhāī mērē kanē tusāṁ jō namaskāra bōladē.",null],[4,22,"सारे पवित्र लोक,खास तौर पर जे कैसर रे घराने रे हिन तुसां जो नमस्कार बोलदे हिन।","sārē pavitra lōka,khāsa taura para jē kaisara rē gharānē rē hina tusāṁ jō namaskāra bōladē hina.",null],[4,23,"असां रे प्रभु यीशु मसीह रा अनुग्रह तुसां री आत्मा कने हुदां रेह्।","asāṁ rē prabhu yīśu masīha rā anugraha tusāṁ rī ātmā kanē hudāṁ rēh.",null]],"gbk":[[1,1,"मसीह यीशु रै दास पौलुस अतै तिमुथियुस री तरफा थऊं सबी पवित्र मणु रै नां मन्ज जेड़ै मसीह यीशु रै नां सितै फिलिप्पी मन्ज रैहन्दैै हिन्न अध्य्क्षा अतै सेवका समेत।","masīha yīśu rai dāsa paulusa atai timuthiyusa rī taraphā thaūṁ sabī pavitra maṇu rai nāṁ manja jēṛai masīha yīśu rai nāṁ sitai philippī manja raihandaiai hinna adhykṣā atai sēvakā samēta.",null],[1,2,"ईन्दै पिता प्रमात्मां अतै प्रभु यीशु मसीह री तरफा थऊं तुसु जो अनुग्रह अतै शान्ति मुळदी रेय्आ।","īndai pitā pramātmāṁ atai prabhu yīśu masīha rī taraphā thaūṁ tusu jō anugraha atai śānti muḷadī rēyā.",null],[1,3,"अऊँ जैहणै-जैहणै तुसु जो याद करदा, तैहणैं-तैहणैं अपणै प्रमात्मैं रा धन्या‍वाद करदा।","aūm̐ jaihaṇai-jaihaṇai tusu jō yāda karadā, taihaṇaiṁ-taihaṇaiṁ apaṇai pramātmaiṁ rā dhanyāvāda karadā.",null],[1,4,"अतै जैहणै भी तुसु सबी तांईं बिनती करदा रा सदा खुशी सितै बिनती करदा।","atai jaihaṇai bhī tusu sabī tāṁīṁ binatī karadā rā sadā khuśī sitai binatī karadā.",null],[1,5,"ऐत तांईं, कि तुसै पैहलै धैड़ै थऊं लेई करी अज्जा तिकर सुसमांचार जो फैलाणैं तांईं मिन्जो सोगी-सोगी रैह।","aita tāṁīṁ, ki tusai paihalai dhaiṛai thaūṁ lēī karī ajjā tikara susamāṁcāra jō phailāṇaiṁ tāṁīṁ minjō sōgī-sōgī raiha.",null],[1,6,"अतै मिन्जो ऐसा गप्पा रा भरोसा हा कि जिनी तुसु मन्ज खरा कम सुरू करूरा हा, तैस ही ऐस कमां जो यीशु मसीह रै तैस धैड़ै तिकर पूरा करनां।","atai minjō aisā gappā rā bharōsā hā ki jinī tusu manja kharā kama surū karūrā hā, taisa hī aisa kamāṁ jō yīśu masīha rai taisa dhaiṛai tikara pūrā karanāṁ.",null],[1,7,"एह ठीक हा कि, अऊँ तुसु सबी तांईं इन्हां विचार करूं क्जोकि तुसै मेरै मनां मन्ज‍ ईच्ची बसुरै हिन्न अतै मेरी कैदा मन्ज अतै सुसमांचार तांईं उतर अतै सबूत दीणैं मन्ज तुसै सब मिन्जो सोगी अनुग्रह सितै सहभागी हिन्न।","ēha ṭhīka hā ki, aūm̐ tusu sabī tāṁīṁ inhāṁ vicāra karūṁ kjōki tusai mērai manāṁ manja īccī basurai hinna atai mērī kaidā manja atai susamāṁcāra tāṁīṁ utara atai sabūta dīṇaiṁ manja tusai saba minjō sōgī anugraha sitai sahabhāgī hinna.",null],[1,8,"ऐत मन्ज प्रमात्मां मेरा गवाह हा, कि अऊँ मसीह यीशु सांईं कम करी के तुसु सबी जो चाहन्दा।","aita manja pramātmāṁ mērā gavāha hā, ki aūm̐ masīha yīśu sāṁīṁ kama karī kē tusu sabī jō cāhandā.",null],[1,9,"अतै अऊँ एह प्रार्थना करदा कि, तुन्दा प्यार, ज्ञान अतै सबी किस्मां री अक्ल सितै होर भी अग्गो बढ़दा गच्छा।","atai aūm̐ ēha prārthanā karadā ki, tundā pyāra, jñāna atai sabī kismāṁ rī akla sitai hōra bhī aggō baṛhadā gacchā.",null],[1,10,"एठी तिकर कि तुसै खरी थऊं खरी गप्पा जो प्यारा जाणां अतै मसीह रै धैड़ै तिकर सच्चै बणी रेय्आ अतै ठोकर मत खा।","ēṭhī tikara ki tusai kharī thaūṁ kharī gappā jō pyārā jāṇāṁ atai masīha rai dhaiṛai tikara saccai baṇī rēyā atai ṭhōkara mata khā.",null],[1,11,"अतै तैस धार्मिकता रै फळा सितै जैडा कि यीशु मसीह री बजहा थऊं भुन्दा, भरपुर भुन्दै गच्छा जैत थऊं प्रमात्मैं री महीमां अतै स्तुति भुन्दी रेय्आ।","atai taisa dhārmikatā rai phaḷā sitai jaiḍā ki yīśu masīha rī bajahā thaūṁ bhundā, bharapura bhundai gacchā jaita thaūṁ pramātmaiṁ rī mahīmāṁ atai stuti bhundī rēyā.",null],[1,12,"मेरेओ भाईओ अऊँ चाहन्दा कि तुसै एह जाणी लेय्आ कि मिन्जो पुर जैड़ी बीतुरी हा तैत सितै सूसमांचारा री ही बढ़ोतरी भछूरी हा।","mērēō bhāīō aūm̐ cāhandā ki tusai ēha jāṇī lēyā ki minjō pura jaiṛī bīturī hā taita sitai sūsamāṁcārā rī hī baṛhōtarī bhachūrī hā.",null],[1,13,"एठी तिकर कि राजा कैसर री सारी फौज अतै बाकी मणु जो भी एह पता लगी गो हा कि अऊँ मसीह यीशु तांईं कैदा मन्ज हा।","ēṭhī tikara ki rājā kaisara rī sārī phauja atai bākī maṇu jō bhī ēha patā lagī gō hā ki aūm̐ masīha yīśu tāṁīṁ kaidā manja hā.",null],[1,14,"अतै प्रभु मन्ज जेड़ै भाई हिन्न तिआं मन्ज ज्यादातर मेरै कैद भूणैं री बजहा थऊं, हिम्मता सितै प्रमात्मैं रा वचन हुणांणैं री होर भी हिम्मत करदै हिन्न ।","atai prabhu manja jēṛai bhāī hinna tiāṁ manja jyādātara mērai kaida bhūṇaiṁ rī bajahā thaūṁ, himmatā sitai pramātmaiṁ rā vacana huṇāṁṇaiṁ rī hōra bhī himmata karadai hinna .",null],[1,15,"कतूणैं ता डाह अतै झगड़ै री बजहा थऊं मसीह रा प्रचार करदै हिन्न अतै कतूनै भली मनसा सितै।","katūṇaiṁ tā ḍāha atai jhagaṛai rī bajahā thaūṁ masīha rā pracāra karadai hinna atai katūnai bhalī manasā sitai.",null],[1,16,"कैई ता एह जाणी करी कि अऊँ सूसमांचारा तांईं उतर दीणैं जो ठरोऊरा अतै प्यारा सितै प्रचार करदै हिन्न।","kaiī tā ēha jāṇī karī ki aūm̐ sūsamāṁcārā tāṁīṁ utara dīṇaiṁ jō ṭharōūrā atai pyārā sitai pracāra karadai hinna.",null],[1,17,"अतै कैई ता सिधै ना पर विरोधा सितै मसीह रा दृष्टान्त हुणांदै हिन्न, एह समझी करी कि मेरी कैदा मन्ज मिन्जो तांईं कळेश पैदा करन।","atai kaiī tā sidhai nā para virōdhā sitai masīha rā dr̥ṣṭānta huṇāṁdai hinna, ēha samajhī karī ki mērī kaidā manja minjō tāṁīṁ kaḷēśa paidā karana.",null],[1,18,"ता कै भुआ? मात्र एह कि हर किस्मां सितै चांऐं भानैं सितै ही सैई, चांऐं सच्चाई सितै, मसीह रा दृष्टान्त हुणांई गाहन्दा हा अतै अऊँ ऐत थऊं खुश हा अतै खुश रैहन्दै रैहणां।","tā kai bhuā? mātra ēha ki hara kismāṁ sitai cāṁaiṁ bhānaiṁ sitai hī saiī, cāṁaiṁ saccāī sitai, masīha rā dr̥ṣṭānta huṇāṁī gāhandā hā atai aūm̐ aita thaūṁ khuśa hā atai khuśa raihandai raihaṇāṁ.",null],[1,19,"क्जोकि अऊँ जाणदा, कि तुन्दी बिनती सितै अतै यीशु मसीह री आत्मां रै दाना सितै ठेरा प्रतिफळ मेरा उद्वार भूणां।","kjōki aūm̐ jāṇadā, ki tundī binatī sitai atai yīśu masīha rī ātmāṁ rai dānā sitai ṭhērā pratiphaḷa mērā udvāra bhūṇāṁ.",null],[1,20,"अऊँ ता दिला थऊं एह ही लालसा अतै आशा रखदा, कि अऊँ कस्सी गप्पा मन्ज लज्जित ना भुच्छू्, पर जिआं मेरै जोसीलै हौंसलै सितै मसीह री बड़ाई मेरी देह री बजहा सितै हमेशा भुन्दी रैई हा, तिआं अबै भी भोआ चांऐं अऊँ जिन्दा रैऊ या मरी गच्छूं ।","aūm̐ tā dilā thaūṁ ēha hī lālasā atai āśā rakhadā, ki aūm̐ kassī gappā manja lajjita nā bhucchū, para jiāṁ mērai jōsīlai hauṁsalai sitai masīha rī baṛāī mērī dēha rī bajahā sitai hamēśā bhundī raiī hā, tiāṁ abai bhī bhōā cāṁaiṁ aūm̐ jindā raiū yā marī gacchūṁ .",null],[1,21,"क्जोकि मिन्जो तांईं जिन्दा रैहणां मसीह हा अतै मरी गाहणां फाईदा हा।","kjōki minjō tāṁīṁ jindā raihaṇāṁ masīha hā atai marī gāhaṇāṁ phāīdā hā.",null],[1,22,"पर जे जिस्मां मन्ज जिन्दा रैहणां ही मेरै कमां तांईं फाईदैमन्द‍ हा ता अऊँ ना जाणदा कि कसेरा चुनाव करू।","para jē jismāṁ manja jindā raihaṇāṁ hī mērai kamāṁ tāṁīṁ phāīdaimanda hā tā aūm̐ nā jāṇadā ki kasērā cunāva karū.",null],[1,23,"क्जो कि अऊँ ता दोनों रै मन्जै लटकुरा, दिल ता करदा कि खिट लाई करी यीशु मसीह बल्लै गिच्ची रैऊ, क्जो कि एह ता बड़ा ही बांका।","kjō ki aūm̐ tā dōnōṁ rai manjai laṭakurā, dila tā karadā ki khiṭa lāī karī yīśu masīha ballai giccī raiū, kjō ki ēha tā baṛā hī bāṁkā.",null],[1,24,"पर जिस्मां मन्ज रैहणां तुन्दी बजहा थऊं होर भी जरूरी हा।","para jismāṁ manja raihaṇāṁ tundī bajahā thaūṁ hōra bhī jarūrī hā.",null],[1,25,"अतै एह कि मिन्जो‍ भरोसा हा अतै अऊँ जाणदा कि मूँ जिन्दै रैहणां बल्कि तुसु सबी सोगी रैहणां जैत थऊं तुसै वस्वासा मन्ज होर भी पक्कै भुन्दै गाहन अतै ऐसा गप्पा मन्ज खुश रेय्आ।","atai ēha ki minjō bharōsā hā atai aūm̐ jāṇadā ki mūm̐ jindai raihaṇāṁ balki tusu sabī sōgī raihaṇāṁ jaita thaūṁ tusai vasvāsā manja hōra bhī pakkai bhundai gāhana atai aisā gappā manja khuśa rēyā.",null],[1,26,"अतै जैडा घमण्ड तुसै मेरै बारै मन्ज करदै हिन्न‍, सो मेरै फिरी तुसु बल्लै हट्टी ईणैं थऊं मसीह यीशु मन्ज होर भी बढ़दा गच्छा।","atai jaiḍā ghamaṇḍa tusai mērai bārai manja karadai hinna, sō mērai phirī tusu ballai haṭṭī īṇaiṁ thaūṁ masīha yīśu manja hōra bhī baṛhadā gacchā.",null],[1,27,"तुणां करा कि तुन्दा चाल चलन मसीह यीशु रै सूसमांचारा रै मुताबक भोआ, चाहे अऊँ इच्ची करी हैरू चाहे ना हेरू, तुन्दै बारै मन्ज बस एह हुणुं कि तुसै अक्की ही आत्मां मन्ज टिकुरै हिन्न अतै अक्क मन भुच्ची करी सुसमांचारा तांईं मेहनत करदै हिन्न।","tuṇāṁ karā ki tundā cāla calana masīha yīśu rai sūsamāṁcārā rai mutābaka bhōā, cāhē aūm̐ iccī karī hairū cāhē nā hērū, tundai bārai manja basa ēha huṇuṁ ki tusai akkī hī ātmāṁ manja ṭikurai hinna atai akka mana bhuccī karī susamāṁcārā tāṁīṁ mēhanata karadai hinna.",null],[1,28,"अतै कस्सी गप्पा मन्ज विरोधी थऊं ना डरदै अतै एह तिआं तांईं विनाशा री साफ नशाणी हा, पर तुसु तांईं उद्वारा रा अतै एह प्रमात्मैं री तरफा थऊं हा।","atai kassī gappā manja virōdhī thaūṁ nā ḍaradai atai ēha tiāṁ tāṁīṁ vināśā rī sāpha naśāṇī hā, para tusu tāṁīṁ udvārā rā atai ēha pramātmaiṁ rī taraphā thaūṁ hā.",null],[1,29,"क्जों कि मसीह री बजहा थऊं तुसु पुर अनुग्रह भुआ हा कि ना मात्र तैस पुर वस्वास करा बल्कि तैस तांईं दुख भी झेला।","kjōṁ ki masīha rī bajahā thaūṁ tusu pura anugraha bhuā hā ki nā mātra taisa pura vasvāsa karā balki taisa tāṁīṁ dukha bhī jhēlā.",null],[1,30,"अतै तुसु जो तिनी मेहनत भी करनी हा जिआं कि तुसै मिन्जो करदै हैरुरा हा अतै अबै भी हुणदै हिन्न कि अऊँ तिआं ही करदा हा।","atai tusu jō tinī mēhanata bhī karanī hā jiāṁ ki tusai minjō karadai hairurā hā atai abai bhī huṇadai hinna ki aūm̐ tiāṁ hī karadā hā.",null],[2,1,"ता जे मसीह मन्ज कुछ शान्ति अतै प्यारा सितै ढाढ़स अतै आत्मां री सहभागिता अतै कुछ करूणा दया हा।","tā jē masīha manja kucha śānti atai pyārā sitai ḍhāṛhasa atai ātmāṁ rī sahabhāgitā atai kucha karūṇā dayā hā.",null],[2,2,"ता मेरी एह खुशी पूरी करा कि अक्क‍ मन रेय्आ अतै अक्क ही प्यार, अक्क‍ ही चित अतै अक्क ही मनसा रखा।","tā mērī ēha khuśī pūrī karā ki akka mana rēyā atai akka hī pyāra, akka hī cita atai akka hī manasā rakhā.",null],[2,3,"विरोध अतै झूठी प्रसंसा तांईँ कुछ मत करा पर दीन मनां सितै अक्की दुऐ जो अप्पु थऊं खरा समझा।","virōdha atai jhūṭhī prasaṁsā tāṁīm̐ kucha mata karā para dīna manāṁ sitai akkī duai jō appu thaūṁ kharā samajhā.",null],[2,4,"हर कोई अपणै ही बारै मन्ज ना पर दुऐ रै बारै मन्ज भी चिन्द करा।","hara kōī apaṇai hī bārai manja nā para duai rai bārai manja bhī cinda karā.",null],[2,5,"जिनां मसीह यीशु रा सभाव हा तुन्दा सभाव भी तिनां भोआ।","jināṁ masīha yīśu rā sabhāva hā tundā sabhāva bhī tināṁ bhōā.",null],[2,6,"यीशुऐ प्रमात्मैं रै बराबर भूणैं रै बाबजूद भी प्रमात्मैं रै बराबर भूणैं जो अपणै वशा मन्ज रखणैं री चीज ना समझू।","yīśuai pramātmaiṁ rai barābara bhūṇaiṁ rai bābajūda bhī pramātmaiṁ rai barābara bhūṇaiṁ jō apaṇai vaśā manja rakhaṇaiṁ rī cīja nā samajhū.",null],[2,7,"बल्कि अपणै आपा जो तूणां जीरो करी दिता कि दासा सांईं बणी गो अतै मणु रै बराबर भुच्ची गो।","balki apaṇai āpā jō tūṇāṁ jīrō karī ditā ki dāsā sāṁīṁ baṇī gō atai maṇu rai barābara bhuccī gō.",null],[2,8,"अतै मणु रै रूपा मन्‍ज प्रकट भुच्‍ची करी अपणै आपा जो दीन करू अतै तूणै तिकर हुक्‍म मनणैं बाळा रैऊ कि सब दुख सेहन्‍दा-सेहन्‍दा क्रुस पुर मौती जो गळै लाई लैऊँ।","atai maṇu rai rūpā manja prakaṭa bhuccī karī apaṇai āpā jō dīna karū atai tūṇai tikara hukma manaṇaiṁ bāḷā raiū ki saba dukha sēhandā-sēhandā krusa pura mautī jō gaḷai lāī laiūm̐.",null],[2,9,"ऐत तांईं पिता परमेश्‍वरै तैसिओ महान बल्‍लु अतै तैस जो सो नां दिता जैडा कि सबी नां थंऊँ महान हा।","aita tāṁīṁ pitā paramēśvarai taisiō mahāna ballu atai taisa jō sō nāṁ ditā jaiḍā ki sabī nāṁ thaṁūm̐ mahāna hā.",null],[2,10,"अतै जैडा कि स्‍वर्गा मन्‍ज रैहन्‍दै हिन्‍न या धरती पुर रैहन्‍दै हिन्‍न अतै धरती रै थल्‍लै रैहन्‍दै हिन्‍न सो सब यीशु रै नां मन्‍ज अपणा हैर झुकान।","atai jaiḍā ki svargā manja raihandai hinna yā dharatī pura raihandai hinna atai dharatī rai thallai raihandai hinna sō saba yīśu rai nāṁ manja apaṇā haira jhukāna.",null],[2,11,"अतै प्रमात्‍मैं री महिमां तांईं हर अक्‍क जीभ अंगीकार करी लेय्आ कि यीशु ही प्रभु हा।","atai pramātmaiṁ rī mahimāṁ tāṁīṁ hara akka jībha aṁgīkāra karī lēyā ki yīśu hī prabhu hā.",null],[2,12,"ता हे मेरेओ प्‍यारओँ जिआं कि तुसै हमेशा हुक्‍म मन्‍दै आऐ हिन्‍न, तिआं ही अबै ना कि मिन्‍जो सोगी रैई करी पर मिन्‍जो थऊं दूर रैई करी भी प्रमात्‍मैं थऊं डरदै अतै कम्‍मदै अपणै-अपणै उद्वार रा कम पूरा करदै गच्‍छा।","tā hē mērēō pyāraōm̐ jiāṁ ki tusai hamēśā hukma mandai āai hinna, tiāṁ hī abai nā ki minjō sōgī raiī karī para minjō thaūṁ dūra raiī karī bhī pramātmaiṁ thaūṁ ḍaradai atai kammadai apaṇai-apaṇai udvāra rā kama pūrā karadai gacchā.",null],[2,13,"क्‍जो कि प्रमात्‍मां ही हा जिनी अपणी ईच्‍छा रै मताबक तुन्‍दै मनां मन्‍ज इच्छा अतै कम दुन्‍नी गप्‍पा रा तुसु पुर असर करनै रा जोर पऊ।","kjō ki pramātmāṁ hī hā jinī apaṇī īcchā rai matābaka tundai manāṁ manja icchā atai kama dunnī gappā rā tusu pura asara karanai rā jōra paū.",null],[2,14,"सब कम बिना कुड़कुड़ करदै अतै बिना विवाद करदै करू करा।","saba kama binā kuṛakuṛa karadai atai binā vivāda karadai karū karā.",null],[2,15,"तांजे तुसै निर्दोष अतै भोळै-भाळै भुच्‍ची करी टेढ़े अतै हठीलै मणु मन्‍ज प्रमात्‍मे री निष्‍कलंक औलाद बणी रैहण क्‍जोकि तुसै जिन्दगी रा वचन लैई करी ऐसा दुनियां मन्‍ज इआं हिन्‍न जिआं कि जग-मग करदै दिये।","tāṁjē tusai nirdōṣa atai bhōḷai-bhāḷai bhuccī karī ṭēṛhē atai haṭhīlai maṇu manja pramātmē rī niṣkalaṁka aulāda baṇī raihaṇa kjōki tusai jindagī rā vacana laiī karī aisā duniyāṁ manja iāṁ hinna jiāṁ ki jaga-maga karadai diyē.",null],[2,16,"तांजे मसीह यीशु रै धैड़ै मन्‍ज एह मेरा घमण्‍ड़ करनै री बजहा भोआ कि मेरी दौड़ अतै मेहन्‍त व्‍यर्थ ना भुई।","tāṁjē masīha yīśu rai dhaiṛai manja ēha mērā ghamaṇṛa karanai rī bajahā bhōā ki mērī dauṛa atai mēhanta vyartha nā bhuī.",null],[2,17,"अतै जे मिन्‍जो तुन्‍दै वस्‍वास रै बलिदान अतै सेवा तांईं अपणां खून भी दीणां पेय्आ ता भी अऊँ खुश हा अतै तुसु सबी सोगी खुशी मन्‍दा।","atai jē minjō tundai vasvāsa rai balidāna atai sēvā tāṁīṁ apaṇāṁ khūna bhī dīṇāṁ pēyā tā bhī aūm̐ khuśa hā atai tusu sabī sōgī khuśī mandā.",null],[2,18,"तिआं ही तुसै भी खुश भून अतै मिन्‍जो सोगी खुश भोआ।","tiāṁ hī tusai bhī khuśa bhūna atai minjō sōgī khuśa bhōā.",null],[2,19,"मिन्‍जो यीशु मसीह पुर आश हा, कि मूँ तिमुथियुस जो तुसु बल्‍लै जरूर भेजणा, तांजे तुन्‍दी दशा जो हुणी करी मिन्‍जो शान्‍ति मुळा।","minjō yīśu masīha pura āśa hā, ki mūm̐ timuthiyusa jō tusu ballai jarūra bhējaṇā, tāṁjē tundī daśā jō huṇī karī minjō śānti muḷā.",null],[2,20,"क्जोकि असु मन्ज कसी रा भी इना स्‍भाव निआं कि सो साफ मनां सितै तुन्‍दी चिन्‍द करा।","kjōki asu manja kasī rā bhī inā sbhāva niāṁ ki sō sāpha manāṁ sitai tundī cinda karā.",null],[2,21,"क्‍जोकि सब अपणै-अपणै स्‍वार्था मन्‍ज रैहन्‍दै हिन्‍न, ना कि यीशु मसीह रै।","kjōki saba apaṇai-apaṇai svārthā manja raihandai hinna, nā ki yīśu masīha rai.",null],[2,22,"पर तुसै तैस जो परखी अतै जाणी भी लैऊ हा, कि जिआं पिता पुत्रा सोगी कम करदा तिआं ही तिनी असु सोगी सूसमांचार जो फैलाणैं री मेहनत करीआ।","para tusai taisa jō parakhī atai jāṇī bhī laiū hā, ki jiāṁ pitā putrā sōgī kama karadā tiāṁ hī tinī asu sōgī sūsamāṁcāra jō phailāṇaiṁ rī mēhanata karīā.",null],[2,23,"ता अऊँ आश करदा, कि जिआं हि मिन्‍जो पता लगला कि मेरी दशा किनी भूणी हा तिआं ही अऊँ तैस जो भेजी दिला।","tā aūm̐ āśa karadā, ki jiāṁ hi minjō patā lagalā ki mērī daśā kinī bhūṇī hā tiāṁ hī aūm̐ taisa jō bhējī dilā.",null],[2,24,"अतै मिन्‍जो प्रभु पर भरोसा कि मूँ भी जैतूणैं जल्दी भुच्ची सका तैतूणैं जल्दी चली ईणां।","atai minjō prabhu para bharōsā ki mūm̐ bhī jaitūṇaiṁ jaldī bhuccī sakā taitūṇaiṁ jaldī calī īṇāṁ.",null],[2,25,"पर मैंईं इपफ्रदीतुस जो जैडा कि मेरा वसवासी भाई हा अतै सोगी कम करनै बाळा अतै वसवास री लड़ाई लड़नै बाळा अतै तुन्‍दा दूत अतै जरूरी गप्‍पा मन्‍ज मेरी सेवा टैहल करनै बाळा भी हा जो तुसु बलै भैजणां जरूरी समझू।","para maiṁīṁ ipaphradītusa jō jaiḍā ki mērā vasavāsī bhāī hā atai sōgī kama karanai bāḷā atai vasavāsa rī laṛāī laṛanai bāḷā atai tundā dūta atai jarūrī gappā manja mērī sēvā ṭaihala karanai bāḷā bhī hā jō tusu balai bhaijaṇāṁ jarūrī samajhū.",null],[2,26,"क्‍जो कि तसेरा मन तुसु सबी मन्‍ज लगुरा थू, ऐत तांईं सो व्‍याकुल रैहन्‍दा थू क्‍जोकि तुसै तसेरी बिमारी रै बारै मन्‍ज हुणुरा थू।","kjō ki tasērā mana tusu sabī manja lagurā thū, aita tāṁīṁ sō vyākula raihandā thū kjōki tusai tasērī bimārī rai bārai manja huṇurā thū.",null],[2,27,"अतै सो तूणां बमार थू कि मरनै बाळा थू पर प्रमात्‍मे तैस पुर दया करी अतै तैस पुर ही ना बल्‍कि मिन्‍जो पुर भी कि मिन्‍जो दुखा पुर होर दुखा ना भोआ।","atai sō tūṇāṁ bamāra thū ki maranai bāḷā thū para pramātmē taisa pura dayā karī atai taisa pura hī nā balki minjō pura bhī ki minjō dukhā pura hōra dukhā nā bhōā.",null],[2,28,"ऐत तांईं मैंईं तैस जो भेजणैं रा होर भी कोशिश करी कि तुसै तैस सितै मुळी करी खुश भून अतै मेरा भी दुख घट भुच्‍ची गच्‍छा।","aita tāṁīṁ maiṁīṁ taisa jō bhējaṇaiṁ rā hōra bhī kōśiśa karī ki tusai taisa sitai muḷī karī khuśa bhūna atai mērā bhī dukha ghaṭa bhuccī gacchā.",null],[2,29,"ऐत तांईं प्रभु यीशु रै नां सितै तुसै तैस सोगी खुशि सितै मुळै क्‍जोकि इनै-जिनै रा आदर-मान करू करै।","aita tāṁīṁ prabhu yīśu rai nāṁ sitai tusai taisa sōgī khuśi sitai muḷai kjōki inai-jinai rā ādara-māna karū karai.",null],[2,30,"क्‍जोकि सो ही यीशु मसीह तांईं अपणै प्राणां जो मुसिकला मन्‍ज फसाई करी मौती रै नेड़ै पुज्‍जी गछूरा थू, तांजे जैड़ी कमी तुसु थऊं मेरी सेवा मन्‍ज भछूरी हा, तैसा जो पूरी करा","kjōki sō hī yīśu masīha tāṁīṁ apaṇai prāṇāṁ jō musikalā manja phasāī karī mautī rai nēṛai pujjī gachūrā thū, tāṁjē jaiṛī kamī tusu thaūṁ mērī sēvā manja bhachūrī hā, taisā jō pūrī karā",null],[3,1,"अखीरा मन्‍ज, मेरेओ भाईओ प्रभु मन्‍ज खुश रेय्आ। सो ही गप्‍पा तुसु जो घड़ी-घड़ी लिखणैं थऊं मिन्‍जो कोई कष्‍ट ना भुन्‍दा अतै ऐत मन्‍ज तुन्‍दी हिफाजत हा।","akhīrā manja, mērēō bhāīō prabhu manja khuśa rēyā. sō hī gappā tusu jō ghaṛī-ghaṛī likhaṇaiṁ thaūṁ minjō kōī kaṣṭa nā bhundā atai aita manja tundī hiphājata hā.",null],[3,2,"कुत्रा थऊं चौकनें रेय्आ, बुरै कमां करनै बाळै थऊं चौकस रेय्आ, तिआं थऊं भी चौकनें रेय्आ जेड़ै कि झुठी गप्‍पा जो फैलान्‍दै हिन्‍न।","kutrā thaūṁ caukanēṁ rēyā, burai kamāṁ karanai bāḷai thaūṁ caukasa rēyā, tiāṁ thaūṁ bhī caukanēṁ rēyā jēṛai ki jhuṭhī gappā jō phailāndai hinna.",null],[3,3,"क्‍जोकि असै इआं हिन्‍न जिआं कि इन्‍दा खतनां भछूरा अतै प्रमात्‍में री आत्‍मां री अगुवाई सितै उपासनां करदै हिन्‍न अतै मसीह यीशु पुर घमण्‍ड़ करदै हिन्‍न अतै जिस्‍मां पुर भरोसा ना रखदै हिन्‍न।","kjōki asai iāṁ hinna jiāṁ ki indā khatanāṁ bhachūrā atai pramātmēṁ rī ātmāṁ rī aguvāī sitai upāsanāṁ karadai hinna atai masīha yīśu pura ghamaṇṛa karadai hinna atai jismāṁ pura bharōsā nā rakhadai hinna.",null],[3,4,"पर अऊँ ता जिस्‍मां पुर भी भरोसा रखी सकदा जे कसी जो जिस्‍मां पुर भरोसा रखणैं रा विचार भोआ ता अऊँ तैस थऊं भी ज्‍यादा रखी सकदा।","para aūm̐ tā jismāṁ pura bhī bharōsā rakhī sakadā jē kasī jō jismāṁ pura bharōsā rakhaṇaiṁ rā vicāra bhōā tā aūm̐ taisa thaūṁ bhī jyādā rakhī sakadā.",null],[3,5,"मेरा अठुऐं धैड़ै खतनां भुआ, इस्‍त्राएल रै वंश अतै अऊँ बिन्‍यामीन गोत्रा रा हा, इब्रानी रा इब्रानी, जे कोई व्‍यवस्‍था रै बारै मन्‍ज कोई पुछा ता फरीसी हा।","mērā aṭhuaiṁ dhaiṛai khatanāṁ bhuā, istrāēla rai vaṁśa atai aūm̐ binyāmīna gōtrā rā hā, ibrānī rā ibrānī, jē kōī vyavasthā rai bārai manja kōī puchā tā pharīsī hā.",null],[3,6,"जे जोश रै बारै मन्‍ज कोई पुछा ता सबी थऊं ज्‍यादा कलीसिया जो सताणैं बाळा अतै जे कोई व्‍यवस्‍था री धार्मिकता रै बारै मन्‍ज कोई बल्‍ला ता निर्दोष थू।","jē jōśa rai bārai manja kōī puchā tā sabī thaūṁ jyādā kalīsiyā jō satāṇaiṁ bāḷā atai jē kōī vyavasthā rī dhārmikatā rai bārai manja kōī ballā tā nirdōṣa thū.",null],[3,7,"पर जैड़ी-जैड़ी गप्‍पा मेरै फाईदै री थी तिआं जो ही मैंई मसीह री बजहा थऊं हानि समझी लैई।","para jaiṛī-jaiṛī gappā mērai phāīdai rī thī tiāṁ jō hī maiṁī masīha rī bajahā thaūṁ hāni samajhī laiī.",null],[3,8,"पर अऊँ अपणै मसीह यीशु री बेसकीमती पछैणां री बजहा सितै सबी गप्‍पा जो हानि समझदा: जठेरी बजहा थऊं मैंईं सबी चीजा री हानि झेली अतै तिआं सबी जो कूड़ा समझदा जैत थऊं अऊँ मसीह जो पाई लैऊं।","para aūm̐ apaṇai masīha yīśu rī bēsakīmatī pachaiṇāṁ rī bajahā sitai sabī gappā jō hāni samajhadā: jaṭhērī bajahā thaūṁ maiṁīṁ sabī cījā rī hāni jhēlī atai tiāṁ sabī jō kūṛā samajhadā jaita thaūṁ aūm̐ masīha jō pāī laiūṁ.",null],[3,9,"अतै तैत मन्‍ज अऊँ मुळा ना कि अपणी तैसा धार्मिकता सितै जैड़ी कि व्‍यवस्‍था थऊं हा पर तैसा धार्मिकता सितै जैड़ी कि मसीह पुर विश्‍वास करनै री बजहा थऊं हा अतै प्रमात्‍मा री तरफा थऊं विश्‍वास करनै पुर मुळदी हा।","atai taita manja aūm̐ muḷā nā ki apaṇī taisā dhārmikatā sitai jaiṛī ki vyavasthā thaūṁ hā para taisā dhārmikatā sitai jaiṛī ki masīha pura viśvāsa karanai rī bajahā thaūṁ hā atai pramātmā rī taraphā thaūṁ viśvāsa karanai pura muḷadī hā.",null],[3,10,"अतै अऊँ तैस जो अतै तसेरी मौती जो जितणैं री सामर्थ जो अतै तैस सोगी सबी दुखा मन्‍ज सामल भूणैं रै मर्म जो जाणूँ अतै तसेरी मौती सांईं मौत हासल करू।","atai aūm̐ taisa jō atai tasērī mautī jō jitaṇaiṁ rī sāmartha jō atai taisa sōgī sabī dukhā manja sāmala bhūṇaiṁ rai marma jō jāṇūm̐ atai tasērī mautī sāṁīṁ mauta hāsala karū.",null],[3,11,"तांजे अऊँ कसी भी तरीकै थऊं मरुरै थऊं जी भूणैं रै पद तिकर पुजी सकूं।","tāṁjē aūm̐ kasī bhī tarīkai thaūṁ marurai thaūṁ jī bhūṇaiṁ rai pada tikara pujī sakūṁ.",null],[3,12,"एह मतलब निआं कि अऊँ हासिल करी चुकुरा या सिद्व भुच्‍ची चुकुरा पर तैसा चीजा जो हासिल करनै तांईं दौड़ लोऊरी हा जैत तांईं यीशुऐ मिन्‍जो पकड़ुरा थू।","ēha matalaba niāṁ ki aūm̐ hāsila karī cukurā yā sidva bhuccī cukurā para taisā cījā jō hāsila karanai tāṁīṁ dauṛa lōūrī hā jaita tāṁīṁ yīśuai minjō pakaṛurā thū.",null],[3,13,"मेरेओ भाईओ, मेरी भावना एह निआं कि मैंई एह पकड़ी लैऊरा, पर अऊँ मात्र एह अक्‍क कम करदा कि जैड़ी गप्‍पा पिच्‍चो रैई गई तिआं जो भुल्‍ली करी अग्‍गो री गप्‍पा तांईं चलदा गाहन्‍दा।","mērēō bhāīō, mērī bhāvanā ēha niāṁ ki maiṁī ēha pakaṛī laiūrā, para aūm̐ mātra ēha akka kama karadā ki jaiṛī gappā piccō raiī gaī tiāṁ jō bhullī karī aggō rī gappā tāṁīṁ caladā gāhandā.",null],[3,14,"मनां मन्‍ज अपणै मकसदा जो सोची करी दौड़ लोऊरी हा ताकि सो ईनाम पंऊ जैत तांईं प्रमात्‍में मिन्‍जो मसीह यीशु मन्‍ज उपर हैदुरा।","manāṁ manja apaṇai makasadā jō sōcī karī dauṛa lōūrī hā tāki sō īnāma paṁū jaita tāṁīṁ pramātmēṁ minjō masīha yīśu manja upara haidurā.",null],[3,15,"ता असु मन्‍ज जेड़ै भी सिद्व हिन्‍न सो एह हि विचार रखन अतै जे कसी गप्‍पा मन्‍ज तुन्‍दा होर विचार भोआ ता प्रमात्‍में तैत जो भी तुसु पुर प्रकट करी दिणां।","tā asu manja jēṛai bhī sidva hinna sō ēha hi vicāra rakhana atai jē kasī gappā manja tundā hōra vicāra bhōā tā pramātmēṁ taita jō bhī tusu pura prakaṭa karī diṇāṁ.",null],[3,16,"ता जेठी तिकर असै पुज्जु‍रै हिन्‍न तठेरै मताबक ही असै चलन।","tā jēṭhī tikara asai pujjurai hinna taṭhērai matābaka hī asai calana.",null],[3,17,"मेरेओ भाईओ तुसै सब मिलीकरी मिन्‍जो सांईं ही चाल चला अतै तिआं जो हमेशा याद रखा जेडै कि ऐसा रीति पुर चलदै हिन्‍न जठेरा नमूनां तुसै असु मन्‍ज हेरदै हिन्‍न।","mērēō bhāīō tusai saba milīkarī minjō sāṁīṁ hī cāla calā atai tiāṁ jō hamēśā yāda rakhā jēḍai ki aisā rīti pura caladai hinna jaṭhērā namūnāṁ tusai asu manja hēradai hinna.",null],[3,18,"क्‍जोकि मतै सारै इन्‍है चाल चलदै हिन्‍न जिआंरी चर्चा मैई तुसु सोगी कैई बरी करी हा अतै अबै फिरी रोई-रोई करदा कि सो अपणी चाली री बजहा थऊं मसीह यीशु रै क्रुस रै बैरी हिन्‍न।","kjōki matai sārai inhai cāla caladai hinna jiāṁrī carcā maiī tusu sōgī kaiī barī karī hā atai abai phirī rōī-rōī karadā ki sō apaṇī cālī rī bajahā thaūṁ masīha yīśu rai krusa rai bairī hinna.",null],[3,19,"तआंरा अन्‍त विनाश हा, तआंरा प्रमात्‍मां पेट हा, सो अपणी लज्‍जा री गप्‍पा पुर घमण्‍ड़ करदै हिन्‍न अतै धरती री चीजा पुर अपणां मन लाई छड़दै हिन्‍न।","taāṁrā anta vināśa hā, taāṁrā pramātmāṁ pēṭa hā, sō apaṇī lajjā rī gappā pura ghamaṇṛa karadai hinna atai dharatī rī cījā pura apaṇāṁ mana lāī chaṛadai hinna.",null],[3,20,"पर इन्‍दा स्‍वदेश स्‍वर्ग हा अतै असै अक्‍क उद्वारकर्ता प्रभु यीशु मसीह रा तैठी थऊं ईणैं रा रस्‍ता हैरू करदै हिन्‍न।","para indā svadēśa svarga hā atai asai akka udvārakartā prabhu yīśu masīha rā taiṭhī thaūṁ īṇaiṁ rā rastā hairū karadai hinna.",null],[3,21,"सो अपणी शक्‍ति रै तैस असरा री बजहा थऊं सब चीजा जो अपणै बसा मन्‍ज करी सकदा, इन्‍दी दीन-हीन देही रा रूप बदली करी अपणी महीमां री देही रै मताबक बणांईं दीणां।","sō apaṇī śakti rai taisa asarā rī bajahā thaūṁ saba cījā jō apaṇai basā manja karī sakadā, indī dīna-hīna dēhī rā rūpa badalī karī apaṇī mahīmāṁ rī dēhī rai matābaka baṇāṁīṁ dīṇāṁ.",null],[4,1,"ऐत तांईं मेरेओ भाईओ, जैत मन्‍ज मेरा मन लगी रैहन्‍दा जैडा कि मेरी खुशी अतै मुकुट हा, हे मेरेओ भाईओ, प्रभु मन्‍ज ईआं ही टिक्‍की रेय्आ।","aita tāṁīṁ mērēō bhāīō, jaita manja mērā mana lagī raihandā jaiḍā ki mērī khuśī atai mukuṭa hā, hē mērēō bhāīō, prabhu manja īāṁ hī ṭikkī rēyā.",null],[4,2,"अऊँ यूओदिया जो भी समझान्‍दा अतै सुन्‍तुखे जो भी, कि सो प्रभु मन्‍ज मन लाई छड़न।","aūm̐ yūōdiyā jō bhī samajhāndā atai suntukhē jō bhī, ki sō prabhu manja mana lāī chaṛana.",null],[4,3,"अतै मिन्‍जो सोगी सचाई सितै कम करनै बाळैआ अ़ूऊं तिजो सोगी भी बिनती करदा कि, तू तिआं जनानी री मदद कर, क्‍जोकि तिऐं मिन्‍जो सोगी सुसमांचार फैलाणैं मन्‍ज, दुखा: कळेशा मन्‍ज अतै मेरै होरी सहकर्मी सोगी मेहनत करूरी आ, जिआंरै कि नां जिन्दगी री किताबा मन्‍ज लिखुरै हिन्‍न।","atai minjō sōgī sacāī sitai kama karanai bāḷaiā äūūṁ tijō sōgī bhī binatī karadā ki, tū tiāṁ janānī rī madada kara, kjōki tiaiṁ minjō sōgī susamāṁcāra phailāṇaiṁ manja, dukhā: kaḷēśā manja atai mērai hōrī sahakarmī sōgī mēhanata karūrī ā, jiāṁrai ki nāṁ jindagī rī kitābā manja likhurai hinna.",null],[4,4,"प्रभु मन्‍ज हमेशा खुश रेय्आ, अऊँ फिरी बल्‍दा कि खुश रेय्आ।","prabhu manja hamēśā khuśa rēyā, aūm̐ phirī baldā ki khuśa rēyā.",null],[4,5,"तुन्‍दा नर्म दिल सबी पुर प्रकट भोआ क्‍जो कि प्रभु नेड़ै हा।","tundā narma dila sabī pura prakaṭa bhōā kjō ki prabhu nēṛai hā.",null],[4,6,"कसी भी गप्‍पा री चिन्‍द मत करा पर हर अक्‍क गप्‍पा मन्‍ज तुन्‍दी अर्ज, प्रार्थना अतै बिनती सितै धन्‍यावाद प्रमात्‍में रै सामणैं पेस करै गाहन।","kasī bhī gappā rī cinda mata karā para hara akka gappā manja tundī arja, prārthanā atai binatī sitai dhanyāvāda pramātmēṁ rai sāmaṇaiṁ pēsa karai gāhana.",null],[4,7,"ता प्रमात्‍में री शान्‍ति जैड़ी कि समझ थऊं बिलकुल दूर हा, तुन्‍दै दिला अतै विचारा जो मसीह यीशु सम्‍भाळी करी रखा।","tā pramātmēṁ rī śānti jaiṛī ki samajha thaūṁ bilakula dūra hā, tundai dilā atai vicārā jō masīha yīśu sambhāḷī karī rakhā.",null],[4,8,"अखीरा मन्‍ज, हे भाईओ, जैड़ी-जैड़ी गप्‍पा सच्‍च हिन्‍न, जैड़ी-जैड़ी गप्‍पा आदर-मान जोगी हिन्‍न, जैड़ी-जैड़ी गप्‍पा ठीक हिन्‍न, जैड़ी-जैड़ी गप्‍पा पवित्र हिन्‍न, जैड़ी-जैड़ी गप्‍पा सोहणी हिन्‍न, जैड़ी-जैड़ी गप्‍पा मनां जो भान्‍दी हिन्‍न, आखरी, जैड़ी-जैड़ी खरै गुणां बाळी अतै प्रशंसा जोगी हिन्‍न तिआं पुर ही धैन लऊं करा।","akhīrā manja, hē bhāīō, jaiṛī-jaiṛī gappā sacca hinna, jaiṛī-jaiṛī gappā ādara-māna jōgī hinna, jaiṛī-jaiṛī gappā ṭhīka hinna, jaiṛī-jaiṛī gappā pavitra hinna, jaiṛī-jaiṛī gappā sōhaṇī hinna, jaiṛī-jaiṛī gappā manāṁ jō bhāndī hinna, ākharī, jaiṛī-jaiṛī kharai guṇāṁ bāḷī atai praśaṁsā jōgī hinna tiāṁ pura hī dhaina laūṁ karā.",null],[4,9,"जैड़ी गप्‍पा तुसै मिन्‍जो थऊं सिखुरी हिन्‍न अतै मनुरी हिन्‍न अतै हुणुरी हिन्‍न अतै मिन्‍जो मन्‍ज हैरुरी हिन्‍न तिआं जो ही मन्‍नु करा तां प्रमात्‍मां जैडा कि शान्‍ति रा मूल हा तुसु सोगी रैहणां।","jaiṛī gappā tusai minjō thaūṁ sikhurī hinna atai manurī hinna atai huṇurī hinna atai minjō manja hairurī hinna tiāṁ jō hī mannu karā tāṁ pramātmāṁ jaiḍā ki śānti rā mūla hā tusu sōgī raihaṇāṁ.",null],[4,10,"अऊँ प्रभु मन्‍ज बड़ा खुश हा कि अबै ऐतणैं धैड़ै बाद तुन्‍दा विचार मेरै बारै मन्‍ज फिरी जागू हा, जरूर तुसु जो सुरू मन्‍ज भी ठेरा विचार थू, पर तुसु जो मौका नां मुळू।","aūm̐ prabhu manja baṛā khuśa hā ki abai aitaṇaiṁ dhaiṛai bāda tundā vicāra mērai bārai manja phirī jāgū hā, jarūra tusu jō surū manja bhī ṭhērā vicāra thū, para tusu jō maukā nāṁ muḷū.",null],[4,11,"एह ना कि मिन्‍जो बल्‍लै घट हा, क्‍जो कि मैंईं एह सिखुरा कि जैसा भी दशा मन्‍ज अऊँ हा तैत पुर संतोष करूं।","ēha nā ki minjō ballai ghaṭa hā, kjō ki maiṁīṁ ēha sikhurā ki jaisā bhī daśā manja aūm̐ hā taita pura saṁtōṣa karūṁ.",null],[4,12,"अऊँ दीन भूणां भी जांणदा अतै बधणां भी जाणदा, हर अक्‍क गप्‍पा मन्‍ज अतै सबी दशा मन्‍ज तृप्‍त भूणां, भूखा रैहणां अतै मैंईं बधणां-घटणां सिखुरा।","aūm̐ dīna bhūṇāṁ bhī jāṁṇadā atai badhaṇāṁ bhī jāṇadā, hara akka gappā manja atai sabī daśā manja tr̥pta bhūṇāṁ, bhūkhā raihaṇāṁ atai maiṁīṁ badhaṇāṁ-ghaṭaṇāṁ sikhurā.",null],[4,13,"जैडा मिन्‍जो सामर्थ दिन्‍दा तैस मन्‍ज अऊँ सब किछ करी सकदा।","jaiḍā minjō sāmartha dindā taisa manja aūm̐ saba kicha karī sakadā.",null],[4,14,"तांभी तुसै भला करु कि मेरै क्‍लेसा मन्‍ज मिन्‍जो सोगी रैह।","tāṁbhī tusai bhalā karu ki mērai klēsā manja minjō sōgī raiha.",null],[4,15,"अतै हे फिलिप्‍प देश मन्‍ज रैहणै बाळेओ तुसै अप्‍पु ही जाणदै हिन्‍न, कि सुसमांचारा रै बारै मन्‍ज जैहणै मेई मकिदुनिया थऊं कूच करू ता तुसु जो छड़ी करी कसी होरी मण्‍ड़ळी लैण-दीण रै मामलै मन्‍ज मेरी मदद ना करी।","atai hē philippa dēśa manja raihaṇai bāḷēō tusai appu hī jāṇadai hinna, ki susamāṁcārā rai bārai manja jaihaṇai mēī makiduniyā thaūṁ kūca karū tā tusu jō chaṛī karī kasī hōrī maṇṛaḷī laiṇa-dīṇa rai māmalai manja mērī madada nā karī.",null],[4,16,"इन्‍नी साहभै जैहणै अऊँ थिस्‍सलुनीके मन्‍ज थू तां भी तुसै मेरी घटी जो पूरा करनै तांईं अक्‍क बरी कै बल्‍कि दुई बरी कुछ ना कुछ भेज्‍जू थू।","innī sāhabhai jaihaṇai aūm̐ thissalunīkē manja thū tāṁ bhī tusai mērī ghaṭī jō pūrā karanai tāṁīṁ akka barī kai balki duī barī kucha nā kucha bhējjū thū.",null],[4,17,"एह ना कि अऊँ दान चाहन्‍दा पर अऊँ ईनां फळ चाहन्‍दा जैडा कि तुन्‍दै फाईदै तांईं बधदा गच्‍छा।","ēha nā ki aūm̐ dāna cāhandā para aūm̐ īnāṁ phaḷa cāhandā jaiḍā ki tundai phāīdai tāṁīṁ badhadā gacchā.",null],[4,18,"मिन्‍जो बल्‍लै ता सब कुछ हा, बल्‍की उमीदा थऊं भी ज्‍यादा हा: जैड़ी चीजा तुसै इपफ्रुदीतुस रै हथै भेजुरी थी तिआं जो पाई करी अऊँ तृप्‍त भुच्‍ची गो हा, सो ता खुशुबू दार अतै ग्रहण करनै जोगी बलिदान हा जैडा कि प्रमात्‍में जो खरा लगदा।","minjō ballai tā saba kucha hā, balkī umīdā thaūṁ bhī jyādā hā: jaiṛī cījā tusai ipaphrudītusa rai hathai bhējurī thī tiāṁ jō pāī karī aūm̐ tr̥pta bhuccī gō hā, sō tā khuśubū dāra atai grahaṇa karanai jōgī balidāna hā jaiḍā ki pramātmēṁ jō kharā lagadā.",null],[4,19,"अतै मेरा प्रमात्‍मां भी अपणै तैस धनां सितै जैडा कि महिमा सितै मसीह यीशु मन्‍ज हा तुन्‍दी हर अक्‍क घटी जो पूरी करला।","atai mērā pramātmāṁ bhī apaṇai taisa dhanāṁ sitai jaiḍā ki mahimā sitai masīha yīśu manja hā tundī hara akka ghaṭī jō pūrī karalā.",null],[4,20,"इन्‍दै पिता प्रमात्‍में री महिमा जुगा-जुगा तिकर भुन्‍दी रेय्आ। आमीन।","indai pitā pramātmēṁ rī mahimā jugā-jugā tikara bhundī rēyā. āmīna.",null],[4,21,"हर अक्‍क पवित्र मणु जैडा कि मसीह यीशु मन्‍ज हा नमस्‍ते बल्‍ला अतै जेड़ै भाई मिन्‍जो सोगी हिन्‍न, तुसु जो नमस्‍तै बल्‍दै हिन्‍न।","hara akka pavitra maṇu jaiḍā ki masīha yīśu manja hā namastē ballā atai jēṛai bhāī minjō sōgī hinna, tusu jō namastai baldai hinna.",null],[4,22,"सब पवित्र मणु, खास करी जेड़ै राजा कैसर रै घरानै रै हिन्‍न तुसु जो नमस्‍कार बल्‍दै हिन्‍न।","saba pavitra maṇu, khāsa karī jēṛai rājā kaisara rai gharānai rai hinna tusu jō namaskāra baldai hinna.",null],[4,23,"ईन्‍दै प्रभु यीशु मसीह रा अनुग्रह तुन्‍दी आत्‍मां सोगी रेय्आ।","īndai prabhu yīśu masīha rā anugraha tundī ātmāṁ sōgī rēyā.",null]],"guj2017":[[1,1,"ખ્રિસ્ત ઈસુમાં ફિલિપ્પીમાંના સર્વ સંતો, અધ્યક્ષો તથા સેવકો, તે સર્વને ઈસુ ખ્રિસ્તનાં દાસો પાઉલ તથા તિમોથી લખે છે","khrista īsumāṁ philippīmāṁnā sarva saṁtō, adhyakṣō tathā sēvakō, tē sarvanē īsu khristanāṁ dāsō pāula tathā timōthī lakhē chē",null],[1,2,"ઈશ્વર આપણા પિતા તથા પ્રભુ ઈસુ ખ્રિસ્ત તરફથી તમને કૃપા તથા શાંતિ હો.","īśvara āpaṇā pitā tathā prabhu īsu khrista taraphathī tamanē kr̥pā tathā śāṁti hō.",null],[1,3,"પ્રથમ દિવસથી તે આજ સુધી સુવાર્તામાં તમારા સહકારને માટે,","prathama divasathī tē āja sudhī suvārtāmāṁ tamārā sahakāranē māṭē,",null],[1,4,"નિત્ય આનંદ સાથે તમો સર્વને માટે મારી પ્રાર્થનામાં વિનંતિ કરતાં,","nitya ānaṁda sāthē tamō sarvanē māṭē mārī prārthanāmāṁ vinaṁti karatāṁ,",null],[1,5,"જયારે જયારે હું તમને યાદ કરું છું ત્યારે ત્યારે હું મારા ઈશ્વરનો આભાર માનું છું.","jayārē jayārē huṁ tamanē yāda karuṁ chuṁ tyārē tyārē huṁ mārā īśvaranō ābhāra mānuṁ chuṁ.",null],[1,6,"જેમણે તમારામાં સારાં કામની શરૂઆત કરી તે, ઈસુ ખ્રિસ્તનાં દિવસ સુધી, તેને સંપૂર્ણ કરતા જશે, એવો મને ભરોસો છે.","jēmaṇē tamārāmāṁ sārāṁ kāmanī śarūāta karī tē, īsu khristanāṁ divasa sudhī, tēnē saṁpūrṇa karatā jaśē, ēvō manē bharōsō chē.",null],[1,7,"તમો સર્વ વિષે એ પ્રમાણે માનવું મને ઉચિત લાગે છે; કારણ કે મારાં બંધનોમાં અને સુવાર્તાની હિમાયત કરવામાં તથા તેને સાબિત કરવામાં, તમે બધા કૃપામાં મારા સહભાગી હોવાથી, હું તમને મારા હૃદયમાં રાખું છું.","tamō sarva viṣē ē pramāṇē mānavuṁ manē ucita lāgē chē; kāraṇa kē mārāṁ baṁdhanōmāṁ anē suvārtānī himāyata karavāmāṁ tathā tēnē sābita karavāmāṁ, tamē badhā kr̥pāmāṁ mārā sahabhāgī hōvāthī, huṁ tamanē mārā hr̥dayamāṁ rākhuṁ chuṁ.",null],[1,8,"કેમ કે હું ઈસુ ખ્રિસ્તની કરુણાથી તમો સર્વ ઉપર કેટલો બધો પ્રેમ રાખું છું, તે વિષે ઈશ્વર મારા સાક્ષી છે.","kēma kē huṁ īsu khristanī karuṇāthī tamō sarva upara kēṭalō badhō prēma rākhuṁ chuṁ, tē viṣē īśvara mārā sākṣī chē.",null],[1,9,"વળી હું એવી પ્રાર્થના કરું છું કે, જ્ઞાનમાં તથા સર્વ વિવેકબુદ્ધિમાં તમારો પ્રેમ ક્રમે ક્રમે વધતો જાય;","vaḷī huṁ ēvī prārthanā karuṁ chuṁ kē, jñānamāṁ tathā sarva vivēkabuddhimāṁ tamārō prēma kramē kramē vadhatō jāya;",null],[1,10,"જેથી જે શ્રેષ્ઠ છે તે તમે પારખી લો અને એમ તમે ખ્રિસ્તનાં દિવસ સુધી નિષ્કલંક તથા નિર્દોષ થાઓ;","jēthī jē śrēṣṭha chē tē tamē pārakhī lō anē ēma tamē khristanāṁ divasa sudhī niṣkalaṁka tathā nirdōṣa thāō;",null],[1,11,"વળી ઈશ્વરની સ્તુતિ તથા મહિમા વધે તે માટે ઈસુ ખ્રિસ્ત દ્વારા ન્યાયીપણાનાં ફળોથી તમે ભરપૂર થાઓ.","vaḷī īśvaranī stuti tathā mahimā vadhē tē māṭē īsu khrista dvārā nyāyīpaṇānāṁ phaḷōthī tamē bharapūra thāō.",null],[1,12,"ભાઈઓ, મને જે જે દુઃખો પડ્યાં, તે સુવાર્તાને વિઘ્નરૂપ થવાને બદલે તેનો પ્રસાર થવામાં સહાયભૂત થયાં, તે તમે જાણો એવું હું ઇચ્છું છું;","bhāīō, manē jē jē duḥkhō paḍyāṁ, tē suvārtānē vighnarūpa thavānē badalē tēnō prasāra thavāmāṁ sahāyabhūta thayāṁ, tē tamē jāṇō ēvuṁ huṁ icchuṁ chuṁ;",null],[1,13,"કેમ કે ખ્રિસ્તને લીધે મારાં જે બંધનો છે તે આખા રાજયદરબારમાં તથા બીજે બધે સ્થળે પ્રસિદ્ધ થયાં;","kēma kē khristanē līdhē mārāṁ jē baṁdhanō chē tē ākhā rājayadarabāramāṁ tathā bījē badhē sthaḷē prasiddha thayāṁ;",null],[1,14,"અને પ્રભુના સમુદાયના કેટલાક ભાઈઓએ મારાં બંધનોને લીધે વિશ્વાસ રાખીને નિર્ભયપણે ઈશ્વરનું વચન બોલવાની વિશેષ હિંમત રાખી.","anē prabhunā samudāyanā kēṭalāka bhāīōē mārāṁ baṁdhanōnē līdhē viśvāsa rākhīnē nirbhayapaṇē īśvaranuṁ vacana bōlavānī viśēṣa hiṁmata rākhī.",null],[1,15,"કેટલાક તો અદેખાઈ તથા વિરોધથી અને કેટલાક સદ્દભાવથી ખ્રિસ્ત ની સુવાર્તા પ્રગટ કરે છે","kēṭalāka tō adēkhāī tathā virōdhathī anē kēṭalāka saddabhāvathī khrista nī suvārtā pragaṭa karē chē",null],[1,16,"પહેલા તો મારાં બંધનમાં મારા પર વિશેષ સંકટ લાવવાના ઇરાદાથી, શુદ્ધ મનથી નહિ, પણ પક્ષાપક્ષીથી ખ્રિસ્તની વાત પ્રગટ કરે છે;","pahēlā tō mārāṁ baṁdhanamāṁ mārā para viśēṣa saṁkaṭa lāvavānā irādāthī, śuddha manathī nahi, paṇa pakṣāpakṣīthī khristanī vāta pragaṭa karē chē;",null],[1,17,"પણ બીજા, ખ્રિસ્તનાં સુવાર્તા વિષે પ્રત્યુત્તર આપવા માટે હું નિર્મિત થયો છું, એવું જાણીને પ્રેમથી પ્રગટ કરે છે.","paṇa bījā, khristanāṁ suvārtā viṣē pratyuttara āpavā māṭē huṁ nirmita thayō chuṁ, ēvuṁ jāṇīnē prēmathī pragaṭa karē chē.",null],[1,18,"તો એથી શું? દરેક રીતે, ગમે તો દંભથી કે સત્યથી, ખ્રિસ્ત ની વાત પ્રગટ કરવામાં આવે છે; તેથી હું આનંદ પામું છું અને પામીશ.","tō ēthī śuṁ? darēka rītē, gamē tō daṁbhathī kē satyathī, khrista nī vāta pragaṭa karavāmāṁ āvē chē; tēthī huṁ ānaṁda pāmuṁ chuṁ anē pāmīśa.",null],[1,19,"કેમ કે હું જાણું છું કે, તમારી પ્રાર્થનાથી તથા ઈસુ ખ્રિસ્તનાં આત્માની સહાયથી, એ મારા ઉદ્ધારને માટે ઉપયોગી થઈ પડશે, તે હું જાણું છું.","kēma kē huṁ jāṇuṁ chuṁ kē, tamārī prārthanāthī tathā īsu khristanāṁ ātmānī sahāyathī, ē mārā uddhāranē māṭē upayōgī thaī paḍaśē, tē huṁ jāṇuṁ chuṁ.",null],[1,20,"એ પ્રમાણે મને વિશ્વાસ, અપેક્ષા તથા આશા છે કે, હું કોઈ પણ બાબતમાં શરમાઈશ નહિ; પણ પૂરી હિંમતથી, હંમેશ મુજબ હમણાં પણ, ગમે તો જીવનથી કે મૃત્યુથી, મારા શરીરદ્વારા ખ્રિસ્તનાં મહિમાની વૃદ્ધિ કરવામાં આવે.","ē pramāṇē manē viśvāsa, apēkṣā tathā āśā chē kē, huṁ kōī paṇa bābatamāṁ śaramāīśa nahi; paṇa pūrī hiṁmatathī, haṁmēśa mujaba hamaṇāṁ paṇa, gamē tō jīvanathī kē mr̥tyuthī, mārā śarīradvārā khristanāṁ mahimānī vr̥ddhi karavāmāṁ āvē.",null],[1,21,"કેમ કે મારે માટે જીવવું તે ખ્રિસ્ત અને મરવું તે લાભ છે.","kēma kē mārē māṭē jīvavuṁ tē khrista anē maravuṁ tē lābha chē.",null],[1,22,"પણ મનુષ્યદેહમાં જીવવું તે જો મારા કામનું ફળ હોય તો મારે શું પસંદ કરવું, તે હું જાણતો નથી;","paṇa manuṣyadēhamāṁ jīvavuṁ tē jō mārā kāmanuṁ phaḷa hōya tō mārē śuṁ pasaṁda karavuṁ, tē huṁ jāṇatō nathī;",null],[1,23,"કેમ કે આ બે બાબત વચ્ચે હું ગૂંચવણમાં છું દેહમાંથી નીકળવાની તથા ખ્રિસ્તની સાથે રહેવાની મારી ઇચ્છા છે, કેમ કે તે વધારે સારું છે;","kēma kē ā bē bābata vaccē huṁ gūṁcavaṇamāṁ chuṁ dēhamāṁthī nīkaḷavānī tathā khristanī sāthē rahēvānī mārī icchā chē, kēma kē tē vadhārē sāruṁ chē;",null],[1,24,"તોપણ મારે મનુષ્યદેહમાં રહેવું તમારે માટે વધારે અગત્યનું છે.","tōpaṇa mārē manuṣyadēhamāṁ rahēvuṁ tamārē māṭē vadhārē agatyanuṁ chē.",null],[1,25,"મને ભરોસો હોવાથી, હું જાણું છું કે હું રહેવાનો અને તમારા વિશ્વાસની વૃદ્ધિ તથા આનંદને માટે હું તમારાં બધાની સાથે રહેવાનો;","manē bharōsō hōvāthī, huṁ jāṇuṁ chuṁ kē huṁ rahēvānō anē tamārā viśvāsanī vr̥ddhi tathā ānaṁdanē māṭē huṁ tamārāṁ badhānī sāthē rahēvānō;",null],[1,26,"જેથી તમારી પાસે મારા ફરીથી આવવાથી મારા વિષેનો તમારો આનંદ ખ્રિસ્ત ઈસુમાં ઘણો વધી જાય.","jēthī tamārī pāsē mārā pharīthī āvavāthī mārā viṣēnō tamārō ānaṁda khrista īsumāṁ ghaṇō vadhī jāya.",null],[1,27,"માત્ર ખ્રિસ્તની સુવાર્તાને યોગ્ય આચરણ કરો, જેથી ગમે તો હું આવીને તમને જોઉં અથવા દૂર રહું તોપણ તમારા વિષે સાંભળું કે તમે સર્વ એક આત્મામાં સ્થિર રહીને એક જીવથી સુવાર્તાનાં વિશ્વાસને માટે પ્રયત્ન કરો છો.","mātra khristanī suvārtānē yōgya ācaraṇa karō, jēthī gamē tō huṁ āvīnē tamanē jōuṁ athavā dūra rahuṁ tōpaṇa tamārā viṣē sāṁbhaḷuṁ kē tamē sarva ēka ātmāmāṁ sthira rahīnē ēka jīvathī suvārtānāṁ viśvāsanē māṭē prayatna karō chō.",null],[1,28,"અને વિરોધીઓથી જરા પણ ગભરાતા નથી એ તેઓને માટે વિનાશની પ્રત્યક્ષ નિશાની છે, પણ તમને તો ઉદ્ધારની નિશાની છે અને તે વળી ઈશ્વરથી છે.","anē virōdhīōthī jarā paṇa gabharātā nathī ē tēōnē māṭē vināśanī pratyakṣa niśānī chē, paṇa tamanē tō uddhāranī niśānī chē anē tē vaḷī īśvarathī chē.",null],[1,29,"કેમ કે ખ્રિસ્ત પર માત્ર વિશ્વાસ કરવો એટલું જ નહિ, પણ તેમને માટે દુઃખ પણ સહેવું, તેથી ખ્રિસ્તને સારુ આ કૃપાદાન તમને આપવામાં આવ્યું છે;","kēma kē khrista para mātra viśvāsa karavō ēṭaluṁ ja nahi, paṇa tēmanē māṭē duḥkha paṇa sahēvuṁ, tēthī khristanē sāru ā kr̥pādāna tamanē āpavāmāṁ āvyuṁ chē;",null],[1,30,"જેવું યુદ્ધ તમે મારામાં જોયું છે અને હાલ મારામાં થાય છે એ હમણાં તમે સાંભળો છો, તેવું જ તમારામાં પણ છે.","jēvuṁ yuddha tamē mārāmāṁ jōyuṁ chē anē hāla mārāmāṁ thāya chē ē hamaṇāṁ tamē sāṁbhaḷō chō, tēvuṁ ja tamārāmāṁ paṇa chē.",null],[2,1,"માટે જો ખ્રિસ્તમાં કંઈ ઉત્તેજન, જો પ્રેમનો કંઈ દિલાસો, જો પવિત્ર આત્માની કંઈ સંગત, જો કંઈ હૃદયની અનુકંપા તથા કરુણા હોય,","māṭē jō khristamāṁ kaṁī uttējana, jō prēmanō kaṁī dilāsō, jō pavitra ātmānī kaṁī saṁgata, jō kaṁī hr̥dayanī anukaṁpā tathā karuṇā hōya,",null],[2,2,"તો મારો આનંદ એવી રીતે સંપૂર્ણ કરો કે, તમે એક જ મનના થાઓ, એક સરખો પ્રેમ રાખો, એક જીવના તથા એક હૃદયના થાઓ.","tō mārō ānaṁda ēvī rītē saṁpūrṇa karō kē, tamē ēka ja mananā thāō, ēka sarakhō prēma rākhō, ēka jīvanā tathā ēka hr̥dayanā thāō.",null],[2,3,"પક્ષાપક્ષીથી કે મિથ્યાભિમાનથી કશું કરો નહિ, દરેકે નમ્ર ભાવથી પોતાના કરતાં બીજાઓને ઉત્તમ ગણવા.","pakṣāpakṣīthī kē mithyābhimānathī kaśuṁ karō nahi, darēkē namra bhāvathī pōtānā karatāṁ bījāōnē uttama gaṇavā.",null],[2,4,"તમે દરેક માત્ર પોતાના હિત પર જ નહિ, પણ બીજાઓનાં હિત પર પણ લક્ષ રાખો.","tamē darēka mātra pōtānā hita para ja nahi, paṇa bījāōnāṁ hita para paṇa lakṣa rākhō.",null],[2,5,"ખ્રિસ્ત ઈસુનું મન જેવું હતું, તેવું તમે પણ રાખો","khrista īsunuṁ mana jēvuṁ hatuṁ, tēvuṁ tamē paṇa rākhō",null],[2,6,"પોતે ઈશ્વરના રૂપમાં હોવા છતાં, તેમણે ઈશ્વર સમાન હોવાનું પકડી રાખવાને ઇચ્છ્યું નહિ,","pōtē īśvaranā rūpamāṁ hōvā chatāṁ, tēmaṇē īśvara samāna hōvānuṁ pakaḍī rākhavānē icchyuṁ nahi,",null],[2,7,"પણ તેમણે દાસનું રૂપ ધારણ કરીને, એટલે માણસોની સમાનતામાં આવીને પોતાને ખાલી કર્યા;","paṇa tēmaṇē dāsanuṁ rūpa dhāraṇa karīnē, ēṭalē māṇasōnī samānatāmāṁ āvīnē pōtānē khālī karyā;",null],[2,8,"અને માણસના રૂપમાં પ્રગટ થઈને, વધસ્તંભ પરના મરણને આધીન થઈને પોતાને નમ્ર કર્યા.","anē māṇasanā rūpamāṁ pragaṭa thaīnē, vadhastaṁbha paranā maraṇanē ādhīna thaīnē pōtānē namra karyā.",null],[2,9,"તેને કારણે ઈશ્વરે તેમને ઘણાં ઊંચા કર્યા અને સર્વ નામો કરતાં એવું શ્રેષ્ઠ નામ આપ્યું કે,","tēnē kāraṇē īśvarē tēmanē ghaṇāṁ ūṁcā karyā anē sarva nāmō karatāṁ ēvuṁ śrēṣṭha nāma āpyuṁ kē,",null],[2,10,"સ્વર્ગમાંના, પૃથ્વી પરનાં તથા પાતાળમાંનાં સર્વ ઈસુને નામે ઘૂંટણે પડીને નમે;","svargamāṁnā, pr̥thvī paranāṁ tathā pātāḷamāṁnāṁ sarva īsunē nāmē ghūṁṭaṇē paḍīnē namē;",null],[2,11,"અને ઈશ્વરપિતાના મહિમાને અર્થે દરેક જીભ કબૂલ કરે કે ઈસુ ખ્રિસ્ત પ્રભુ છે.","anē īśvarapitānā mahimānē arthē darēka jībha kabūla karē kē īsu khrista prabhu chē.",null],[2,12,"તેથી, મારા પ્રિય ભાઈઓ, તમે જેમ હંમેશા આધીન રહેતા હતા તેમ, કેવળ મારી હાજરીમાં જ નહિ, પણ હવે વિશેષે કરીને મારી ગેરહાજરીમાં પણ તમારો ઉદ્ધાર થાય માટે ભય તથા કંપારીસહિત પ્રયત્ન કરો.","tēthī, mārā priya bhāīō, tamē jēma haṁmēśā ādhīna rahētā hatā tēma, kēvaḷa mārī hājarīmāṁ ja nahi, paṇa havē viśēṣē karīnē mārī gērahājarīmāṁ paṇa tamārō uddhāra thāya māṭē bhaya tathā kaṁpārīsahita prayatna karō.",null],[2,13,"કેમ કે જે પોતાની પ્રસન્નતા પ્રમાણે તમારામાં ઇચ્છવાની તથા પ્રયત્ન કરવાની પ્રેરણા આપે છે, તે તો ઈશ્વર છે.","kēma kē jē pōtānī prasannatā pramāṇē tamārāmāṁ icchavānī tathā prayatna karavānī prēraṇā āpē chē, tē tō īśvara chē.",null],[2,14,"બડબડાટ તથા તકરાર વગર બધું કરો","baḍabaḍāṭa tathā takarāra vagara badhuṁ karō",null],[2,15,"કે, જેથી કુટિલ તથા આડી પ્રજા મધ્યે તમે નિર્દોષ તથા સાલસ, ઈશ્વરનાં નિષ્કલંક સંતાન, જીવનનું વચન પ્રગટ કરીને દુનિયામાં જ્યોતિઓ તરીકે પ્રકાશો.","kē, jēthī kuṭila tathā āḍī prajā madhyē tamē nirdōṣa tathā sālasa, īśvaranāṁ niṣkalaṁka saṁtāna, jīvananuṁ vacana pragaṭa karīnē duniyāmāṁ jyōtiō tarīkē prakāśō.",null],[2,16,"જેથી ખ્રિસ્તનાં સમયમાં મને ગર્વ કરવાનું એવું કારણ મળે કે હું નિરર્થક દોડ્યો નથી અને મેં વ્યર્થ શ્રમ કર્યો નથી.","jēthī khristanāṁ samayamāṁ manē garva karavānuṁ ēvuṁ kāraṇa maḷē kē huṁ nirarthaka dōḍyō nathī anē mēṁ vyartha śrama karyō nathī.",null],[2,17,"પણ જો હું તમારા વિશ્વાસના અર્પણ તથા સેવા પર રેડાવું પડે તોપણ હું આનંદ કરીશ અને તમારી સર્વની સાથે આનંદ કરીશ.","paṇa jō huṁ tamārā viśvāsanā arpaṇa tathā sēvā para rēḍāvuṁ paḍē tōpaṇa huṁ ānaṁda karīśa anē tamārī sarvanī sāthē ānaṁda karīśa.",null],[2,18,"એમ જ તમે પણ મારી સાથે આનંદમાં સહભાગી બનો.","ēma ja tamē paṇa mārī sāthē ānaṁdamāṁ sahabhāgī banō.",null],[2,19,"પણ હું પ્રભુ ઈસુમાં આશા રાખું છું કે, હું તિમોથીને તમારી પાસે વહેલો મોકલીશ, જેથી તમારી ખબર જાણીને મને પણ આનંદ થાય.","paṇa huṁ prabhu īsumāṁ āśā rākhuṁ chuṁ kē, huṁ timōthīnē tamārī pāsē vahēlō mōkalīśa, jēthī tamārī khabara jāṇīnē manē paṇa ānaṁda thāya.",null],[2,20,"કેમ કે તમારી સંભાળ સારી રીતે રાખે તેવો તિમોથી જેવા સારા સ્વભાવવાળો બીજો કોઈ માણસ મારી પાસે નથી.","kēma kē tamārī saṁbhāḷa sārī rītē rākhē tēvō timōthī jēvā sārā svabhāvavāḷō bījō kōī māṇasa mārī pāsē nathī.",null],[2,21,"કેમ કે સર્વ માણસો ખ્રિસ્ત ઈસુની વાત નહિ, પણ પોતાની જ વાત શોધે છે.","kēma kē sarva māṇasō khrista īsunī vāta nahi, paṇa pōtānī ja vāta śōdhē chē.",null],[2,22,"પણ તમને તો અનુભવથી ખાતરી થઈ છે કે જેમ દીકરો પિતાની સાથે કામ કરે, તેમ તેણે સુવાર્તા ના પ્રસાર ને માટે મારી સાથે સેવા કરી.","paṇa tamanē tō anubhavathī khātarī thaī chē kē jēma dīkarō pitānī sāthē kāma karē, tēma tēṇē suvārtā nā prasāra nē māṭē mārī sāthē sēvā karī.",null],[2,23,"એ માટે હું આશા રાખું છું કે, જયારે મારા વિષે શું થવાનું છે તે હું જાણીશ કે તરત હું તેને મોકલી દઈશ;","ē māṭē huṁ āśā rākhuṁ chuṁ kē, jayārē mārā viṣē śuṁ thavānuṁ chē tē huṁ jāṇīśa kē tarata huṁ tēnē mōkalī daīśa;",null],[2,24,"વળી હું પ્રભુમાં ભરોસો રાખું છું કે, હું પોતે પણ વહેલો આવીશ.","vaḷī huṁ prabhumāṁ bharōsō rākhuṁ chuṁ kē, huṁ pōtē paṇa vahēlō āvīśa.",null],[2,25,"તોપણ મારો ભાઈ એપાફ્રોદિતસ, મારી સાથે કામ કરનાર તથા સહયોદ્ધો, તેમ જ તમારો સંદેશવાહક તથા મારી જરૂરિયાત પૂરી પાડનાર છે’ તેને તમારી પાસે મોકલવાની અગત્ય મને જણાઈ;","tōpaṇa mārō bhāī ēpāphrōditasa, mārī sāthē kāma karanāra tathā sahayōddhō, tēma ja tamārō saṁdēśavāhaka tathā mārī jarūriyāta pūrī pāḍanāra chē’ tēnē tamārī pāsē mōkalavānī agatya manē jaṇāī;",null],[2,26,"કારણ કે તે તમો સર્વ પર બહુ પ્રેમ રાખતો હતો અને તે ઘણો ઉદાસ હતો, કેમ કે તમે સાંભળ્યું હતું કે તે બીમાર છે;","kāraṇa kē tē tamō sarva para bahu prēma rākhatō hatō anē tē ghaṇō udāsa hatō, kēma kē tamē sāṁbhaḷyuṁ hatuṁ kē tē bīmāra chē;",null],[2,27,"તે મરણતોલ બીમાર હતો ખરો; પણ ઈશ્વરે તેના પર દયા કરી, કેવળ તેના પર જ નહિ, પણ મારા પર પણ કે, મને શોક ન થાય અને આઘાત ન લાગે.","tē maraṇatōla bīmāra hatō kharō; paṇa īśvarē tēnā para dayā karī, kēvaḷa tēnā para ja nahi, paṇa mārā para paṇa kē, manē śōka na thāya anē āghāta na lāgē.",null],[2,28,"તમે તેને જોઈને ફરીથી ખુશ થાઓ અને મારું દુઃખ પણ ઓછું થાય, માટે મેં ખૂબ ઉતાવળે તેને મોકલ્યો.","tamē tēnē jōīnē pharīthī khuśa thāō anē māruṁ duḥkha paṇa ōchuṁ thāya, māṭē mēṁ khūba utāvaḷē tēnē mōkalyō.",null],[2,29,"માટે તમે પૂર્ણ આનંદથી પ્રભુને નામે તેનો આદરસત્કાર કરો; અને એવાઓને માનયોગ્ય ગણો;","māṭē tamē pūrṇa ānaṁdathī prabhunē nāmē tēnō ādarasatkāra karō; anē ēvāōnē mānayōgya gaṇō;",null],[2,30,"કેમ કે ખ્રિસ્તનાં કામને માટે તે મરણની નજીક આવી ગયો અને મારે અર્થે તમારી સેવામાં જે અધૂરું હતું તે સંપૂર્ણ કરવાને તેણે પોતાનો જીવ જોખમમાં નાખ્યો.","kēma kē khristanāṁ kāmanē māṭē tē maraṇanī najīka āvī gayō anē mārē arthē tamārī sēvāmāṁ jē adhūruṁ hatuṁ tē saṁpūrṇa karavānē tēṇē pōtānō jīva jōkhamamāṁ nākhyō.",null],[3,1,"છેવટે મારા ભાઈઓ, પ્રભુમાં આનંદ કરો. તમને એકની એક જ વાતો લખતાં મને કંટાળો આવતો નથી; કારણ કે તે તમારા રક્ષણને માટે છે.","chēvaṭē mārā bhāīō, prabhumāṁ ānaṁda karō. tamanē ēkanī ēka ja vātō lakhatāṁ manē kaṁṭāḷō āvatō nathī; kāraṇa kē tē tamārā rakṣaṇanē māṭē chē.",null],[3,2,"કૂતરાઓ જેવા લોકોથી, દુષ્કૃત્યો કરનારાઓથી અને વ્યર્થ સુન્નતથી સાવધ રહો.","kūtarāō jēvā lōkōthī, duṣkr̥tyō karanārāōthī anē vyartha sunnatathī sāvadha rahō.",null],[3,3,"કેમ કે આપણે ઈશ્વરના આત્માથી સેવા કરનારા, ખ્રિસ્ત ઈસુમાં ગર્વ કરનારા તથા દેહ પર ભરોસો ન રાખનારા, સાચા સુન્નતી છીએ.","kēma kē āpaṇē īśvaranā ātmāthī sēvā karanārā, khrista īsumāṁ garva karanārā tathā dēha para bharōsō na rākhanārā, sācā sunnatī chīē.",null],[3,4,"તોપણ દેહ પર ભરોસો રાખવાનું મારી પાસે કારણ છે; જો બીજો કોઈ ધારે કે તેને દેહ પર ભરોસો રાખવાનું કારણ છે, તો મને તેના કરતા વિશેષ છે;","tōpaṇa dēha para bharōsō rākhavānuṁ mārī pāsē kāraṇa chē; jō bījō kōī dhārē kē tēnē dēha para bharōsō rākhavānuṁ kāraṇa chē, tō manē tēnā karatā viśēṣa chē;",null],[3,5,"આઠમે દિવસે સુન્નત પામેલો, ઇઝરાયલના સંતાનનો, બિન્યામીનના કુળનો, હિબ્રૂઓનો હિબ્રૂ, નિયમશાસ્ત્ર સંબંધી ફરોશી.","āṭhamē divasē sunnata pāmēlō, ijharāyalanā saṁtānanō, binyāmīnanā kuḷanō, hibrūōnō hibrū, niyamaśāstra saṁbaṁdhī pharōśī.",null],[3,6,"ધર્મના આવેશ સંબંધી વિશ્વાસી સમુદાયને સતાવનાર, નિયમશાસ્ત્રના ન્યાયીપણા સંબંધી નિર્દોષ.","dharmanā āvēśa saṁbaṁdhī viśvāsī samudāyanē satāvanāra, niyamaśāstranā nyāyīpaṇā saṁbaṁdhī nirdōṣa.",null],[3,7,"છતાં પણ જે બાબતો મને ઉપયોગી હતી, તે મેં ખ્રિસ્તને સારું હાનિકારક જેવી માની.","chatāṁ paṇa jē bābatō manē upayōgī hatī, tē mēṁ khristanē sāruṁ hānikāraka jēvī mānī.",null],[3,8,"વાસ્તવમાં, ખ્રિસ્ત ઈસુ મારા પ્રભુના જ્ઞાનની ઉત્તમતાને લીધે, હું એ બધાને હાનિ જ ગણું છું; એને લીધે મેં બધાનું નુકસાન સહન કર્યું અને તેઓને કચરો ગણું છું, કે જેથી હું ખ્રિસ્તને પ્રાપ્ત કરું,","vāstavamāṁ, khrista īsu mārā prabhunā jñānanī uttamatānē līdhē, huṁ ē badhānē hāni ja gaṇuṁ chuṁ; ēnē līdhē mēṁ badhānuṁ nukasāna sahana karyuṁ anē tēōnē kacarō gaṇuṁ chuṁ, kē jēthī huṁ khristanē prāpta karuṁ,",null],[3,9,"અને તેમની સાથે મળી એકરૂપ થાઉં અને નિયમશાસ્ત્રથી મારું જે ન્યાયીપણું છે તે નહિ, પણ ખ્રિસ્તનાં વિશ્વાસદ્વારા ઈશ્વરથી જે ન્યાયીપણું વિશ્વાસથી પ્રાપ્ત થાય છે, તે મારું થાય;","anē tēmanī sāthē maḷī ēkarūpa thāuṁ anē niyamaśāstrathī māruṁ jē nyāyīpaṇuṁ chē tē nahi, paṇa khristanāṁ viśvāsadvārā īśvarathī jē nyāyīpaṇuṁ viśvāsathī prāpta thāya chē, tē māruṁ thāya;",null],[3,10,"એ માટે કે હું તેમને તથા મૃત્યુમાંથી તેમના મરણોત્થાનના પરાક્રમને સમજું તથા તેમના દુઃખોમાં સહભાગી થાઉં; એટલે કે તેમના મૃત્યુને અનુરૂપ થાઉં,","ē māṭē kē huṁ tēmanē tathā mr̥tyumāṁthī tēmanā maraṇōtthānanā parākramanē samajuṁ tathā tēmanā duḥkhōmāṁ sahabhāgī thāuṁ; ēṭalē kē tēmanā mr̥tyunē anurūpa thāuṁ,",null],[3,11,"કે હું કોઈ પણ રીતે મૃત્યુ પામેલાંઓના મરણોત્થાનને પહોંચું.","kē huṁ kōī paṇa rītē mr̥tyu pāmēlāṁōnā maraṇōtthānanē pahōṁcuṁ.",null],[3,12,"હજી સુધી હું બધું સંપાદન કરી ચૂક્યો કે સંપૂર્ણ થયો છું એમ નહિ, પણ હું સતત આગળ ધસું છું, કે જે હેતુથી ખ્રિસ્તે મને તેડી લીધો છે તેને સિદ્ધ કરું.","hajī sudhī huṁ badhuṁ saṁpādana karī cūkyō kē saṁpūrṇa thayō chuṁ ēma nahi, paṇa huṁ satata āgaḷa dhasuṁ chuṁ, kē jē hētuthī khristē manē tēḍī līdhō chē tēnē siddha karuṁ.",null],[3,13,"ભાઈઓ, મેં સિદ્ધ કરી લીધું છે એમ હું ગણતો નથી, પણ એક કામ હું કરું છું કે, જે પાછળ છે તેને વીસરીને તથા જે આગળ છે તેની તરફ ઘસીને,","bhāīō, mēṁ siddha karī līdhuṁ chē ēma huṁ gaṇatō nathī, paṇa ēka kāma huṁ karuṁ chuṁ kē, jē pāchaḷa chē tēnē vīsarīnē tathā jē āgaḷa chē tēnī tarapha ghasīnē,",null],[3,14,"ખ્રિસ્ત ઈસુમાં ઈશ્વરના સ્વર્ગીય આમંત્રણના ઇનામને વાસ્તે, ધ્યેય તરફ આગળ વધું છું.","khrista īsumāṁ īśvaranā svargīya āmaṁtraṇanā ināmanē vāstē, dhyēya tarapha āgaḷa vadhuṁ chuṁ.",null],[3,15,"માટે આપણામાંના જેટલાં પૂર્ણ છે, તેટલાંએ એવી જ મનોવૃત્તિ રાખવી; જો કોઈ બાબત વિષે તમે બીજી મનોવૃત્તિ રાખો, તો ઈશ્વર એ બાબત પણ તમને પ્રગટ કરશે.","māṭē āpaṇāmāṁnā jēṭalāṁ pūrṇa chē, tēṭalāṁē ēvī ja manōvr̥tti rākhavī; jō kōī bābata viṣē tamē bījī manōvr̥tti rākhō, tō īśvara ē bābata paṇa tamanē pragaṭa karaśē.",null],[3,16,"તોપણ જે કક્ષા સુધી આપણે પહોંચ્યા છીએ, તે જ ધોરણે આપણે ચાલવું જોઈએ.","tōpaṇa jē kakṣā sudhī āpaṇē pahōṁcyā chīē, tē ja dhōraṇē āpaṇē cālavuṁ jōīē.",null],[3,17,"ભાઈઓ, મને અનુસરો, અમે જે નમૂનો તમને આપીએ છીએ તે પ્રમાણે જેઓ ચાલે છે તેઓ પર લક્ષ રાખો.","bhāīō, manē anusarō, amē jē namūnō tamanē āpīē chīē tē pramāṇē jēō cālē chē tēō para lakṣa rākhō.",null],[3,18,"કેમ કે ઘણાં એવી રીતે વર્તનારા છે, કે જેઓ વિષે મેં તમને વારંવાર કહ્યું, અને હમણાં પણ રડતાં રડતાં કહું છું કે, ‘તેઓ ખ્રિસ્તનાં વધસ્તંભના શત્રુઓ છે.","kēma kē ghaṇāṁ ēvī rītē vartanārā chē, kē jēō viṣē mēṁ tamanē vāraṁvāra kahyuṁ, anē hamaṇāṁ paṇa raḍatāṁ raḍatāṁ kahuṁ chuṁ kē, ‘tēō khristanāṁ vadhastaṁbhanā śatruō chē.",null],[3,19,"વિનાશ તેઓનો અંત, પેટ તેઓનો દેવ અને નિર્લજ્જતા તેઓનું ગૌરવ છે, તેઓ સાંસારિક વાતો પર ચિત્ત લગાડે છે.","vināśa tēōnō aṁta, pēṭa tēōnō dēva anē nirlajjatā tēōnuṁ gaurava chē, tēō sāṁsārika vātō para citta lagāḍē chē.",null],[3,20,"પણ આપણા માટે તો, ‘આપણી નાગરિકતા સ્વર્ગમાં છે, ત્યાંથી પણ આપણે ઉદ્ધારકર્તા એટલે પ્રભુ ઈસુ ખ્રિસ્તની રાહ જોઈએ છીએ.","paṇa āpaṇā māṭē tō, ‘āpaṇī nāgarikatā svargamāṁ chē, tyāṁthī paṇa āpaṇē uddhārakartā ēṭalē prabhu īsu khristanī rāha jōīē chīē.",null],[3,21,"તે, જે સામર્થ્યથી બધાને પોતાને આધીન કરી શકે છે, તે પ્રમાણે આપણી દીનાવસ્થામાંનાં શરીરને એવું રૂપાંતર કરશે, કે તે તેમના મહિમાવાન શરીરનાં જેવું થાય.’”","tē, jē sāmarthyathī badhānē pōtānē ādhīna karī śakē chē, tē pramāṇē āpaṇī dīnāvasthāmāṁnāṁ śarīranē ēvuṁ rūpāṁtara karaśē, kē tē tēmanā mahimāvāna śarīranāṁ jēvuṁ thāya.’”",null],[4,1,"એ માટે, મારા પ્રિય અને જેમને ઝંખું છું તેવા ભાઈઓ, મારા આનંદ તથા મુગટરૂપ, તેવી જ રીતે પ્રભુ પ્રત્યેના વિશ્વાસમાં સ્થિર રહો, મારા પ્રિય ભાઈઓ.","ē māṭē, mārā priya anē jēmanē jhaṁkhuṁ chuṁ tēvā bhāīō, mārā ānaṁda tathā mugaṭarūpa, tēvī ja rītē prabhu pratyēnā viśvāsamāṁ sthira rahō, mārā priya bhāīō.",null],[4,2,"યુઓદિયાને બોધ કરું છું તથા સુન્તેખેને બોધ કરું છું કે એ, તેઓ બંને પ્રભુમાં એક ચિત્તની થાય.","yuōdiyānē bōdha karuṁ chuṁ tathā suntēkhēnē bōdha karuṁ chuṁ kē ē, tēō baṁnē prabhumāṁ ēka cittanī thāya.",null],[4,3,"વળી મારા ખરા જોડીદાર, હું તને વિનંતી કરું છું કે તું એ બહેનોની મદદ કરજે, કારણ કે તેઓએ મારી સાથે તથા કલેમેન્ટની સાથે તથા બીજા મારા સહ કાર્યકર્તાઓ જેઓનાં નામ જીવનનાં પુસ્તકમાં છે તેઓની સાથે સુવાર્તા પ્રચારના કાર્યમાં પુષ્કળ મહેનત કરી છે.","vaḷī mārā kharā jōḍīdāra, huṁ tanē vinaṁtī karuṁ chuṁ kē tuṁ ē bahēnōnī madada karajē, kāraṇa kē tēōē mārī sāthē tathā kalēmēnṭanī sāthē tathā bījā mārā saha kāryakartāō jēōnāṁ nāma jīvananāṁ pustakamāṁ chē tēōnī sāthē suvārtā pracāranā kāryamāṁ puṣkaḷa mahēnata karī chē.",null],[4,4,"પ્રભુમાં સદા આનંદ કરો; હું ફરીથી કહું છું, કે આનંદ કરો.","prabhumāṁ sadā ānaṁda karō; huṁ pharīthī kahuṁ chuṁ, kē ānaṁda karō.",null],[4,5,"તમારી સહનશીલતા સર્વ માણસોના જાણવામાં આવે. કેમ કે પ્રભુનું આગમન નજીક છે.","tamārī sahanaśīlatā sarva māṇasōnā jāṇavāmāṁ āvē. kēma kē prabhunuṁ āgamana najīka chē.",null],[4,6,"કશાની ચિંતા કરો નહિ; પણ સર્વ વિષે પ્રાર્થના તથા વિનંતીઓ વડે આભારરસ્તુતિ સહિત, તમારી અરજો ઈશ્વરને જણાવો.","kaśānī ciṁtā karō nahi; paṇa sarva viṣē prārthanā tathā vinaṁtīō vaḍē ābhārarastuti sahita, tamārī arajō īśvaranē jaṇāvō.",null],[4,7,"ઈશ્વરની શાંતિ જે સર્વ સમજશક્તિની બહાર છે, તે ખ્રિસ્ત ઈસુમાં તમારાં હૃદયોની તથા મનોની સંભાળ રાખશે.","īśvaranī śāṁti jē sarva samajaśaktinī bahāra chē, tē khrista īsumāṁ tamārāṁ hr̥dayōnī tathā manōnī saṁbhāḷa rākhaśē.",null],[4,8,"છેવટે, ભાઈઓ, જે કંઈ સત્ય, જે કંઈ સન્માનપાત્ર, જે કંઈ ઉચિત, જે કંઈ શુદ્ધ, જે કંઈ પ્રેમપાત્ર, જે કંઈ સુકીર્તિમાન છે તથા જો કોઈ સદગુણ, જો કોઈ પ્રશંસા હોય, તો આ બાબતોનો વિચાર કરો.","chēvaṭē, bhāīō, jē kaṁī satya, jē kaṁī sanmānapātra, jē kaṁī ucita, jē kaṁī śuddha, jē kaṁī prēmapātra, jē kaṁī sukīrtimāna chē tathā jō kōī sadaguṇa, jō kōī praśaṁsā hōya, tō ā bābatōnō vicāra karō.",null],[4,9,"જે તમે શીખ્યા તથા પામ્યા તથા સાંભળ્યું તથા મારામાં જોયું તેવું બધું કરો; અને શાંતિનો ઈશ્વર તમારી સાથે રહેશે.","jē tamē śīkhyā tathā pāmyā tathā sāṁbhaḷyuṁ tathā mārāmāṁ jōyuṁ tēvuṁ badhuṁ karō; anē śāṁtinō īśvara tamārī sāthē rahēśē.",null],[4,10,"મેં પ્રભુમાં પુષ્કળ આનંદ કર્યો, કારણ કે મારા વિષેની તમારી ચિંતા આખરે ફરીથી તાજી થઈ છે; તે બાબતોમાં તમે ચિંતા તો કરતા હતા. પણ મને સહાય કરવાનો તમને પ્રસંગ મળ્યો નહિ.","mēṁ prabhumāṁ puṣkaḷa ānaṁda karyō, kāraṇa kē mārā viṣēnī tamārī ciṁtā ākharē pharīthī tājī thaī chē; tē bābatōmāṁ tamē ciṁtā tō karatā hatā. paṇa manē sahāya karavānō tamanē prasaṁga maḷyō nahi.",null],[4,11,"હું તંગીને લીધે બોલું છું એમ નહિ, કેમ કે જે અવસ્થામાં હું છું, તેમાં સંતોષી રહેવાને હું શીખ્યો છું.","huṁ taṁgīnē līdhē bōluṁ chuṁ ēma nahi, kēma kē jē avasthāmāṁ huṁ chuṁ, tēmāṁ saṁtōṣī rahēvānē huṁ śīkhyō chuṁ.",null],[4,12,"ગરીબીમાં કેવી રીતે જીવવું એ પણ હું જાણું છું તથા સમૃદ્ધિમાં પણ કેવી રીતે જીવવું એ પણ હું જાણું છું; દરેકપ્રકારે તથા સર્વમાં તૃપ્તિમાં તથા ભૂખમાં, પુષ્કળતામાં અને તંગીમાં રહેવાને હું શીખ્યો છું.","garībīmāṁ kēvī rītē jīvavuṁ ē paṇa huṁ jāṇuṁ chuṁ tathā samr̥ddhimāṁ paṇa kēvī rītē jīvavuṁ ē paṇa huṁ jāṇuṁ chuṁ; darēkaprakārē tathā sarvamāṁ tr̥ptimāṁ tathā bhūkhamāṁ, puṣkaḷatāmāṁ anē taṁgīmāṁ rahēvānē huṁ śīkhyō chuṁ.",null],[4,13,"જે મને સામર્થ્ય આપે છે તેમની સહાયથી હું બધું કરી શકું છું.","jē manē sāmarthya āpē chē tēmanī sahāyathī huṁ badhuṁ karī śakuṁ chuṁ.",null],[4,14,"તોપણ તમે મારા સંકટમાં મને મદદ કરી તે સારુ કર્યું.","tōpaṇa tamē mārā saṁkaṭamāṁ manē madada karī tē sāru karyuṁ.",null],[4,15,"ઓ, ફિલિપ્પીઓ, તમે જાણો છો કે, સુવાર્તાનાં આરંભમાં, જયારે હું મકદોનિયામાંથી રવાના થયો, ત્યારે આપવા-લેવાની બાબતમાં એકલા તમારા વિના બીજાકોઈ વિશ્વાસી સમુદાયે ભાગ લીધો નહોતો.","ō, philippīō, tamē jāṇō chō kē, suvārtānāṁ āraṁbhamāṁ, jayārē huṁ makadōniyāmāṁthī ravānā thayō, tyārē āpavā-lēvānī bābatamāṁ ēkalā tamārā vinā bījākōī viśvāsī samudāyē bhāga līdhō nahōtō.",null],[4,16,"કેમ કે થેસ્સાલોનિકામાં પણ અનેક વાર મારે જે જે જોઈતું હતું તે બધું તમે મને મોકલી આપ્યું હતું.","kēma kē thēssālōnikāmāṁ paṇa anēka vāra mārē jē jē jōītuṁ hatuṁ tē badhuṁ tamē manē mōkalī āpyuṁ hatuṁ.",null],[4,17,"હું કંઈ દાન માગું છું એમ નહિ, પણ તમારા હિતમાં ઘણાં ફળ મળે એ માગું છું.","huṁ kaṁī dāna māguṁ chuṁ ēma nahi, paṇa tamārā hitamāṁ ghaṇāṁ phaḷa maḷē ē māguṁ chuṁ.",null],[4,18,"મારી પાસે સર્વ ચીજવસ્તુઓ છે; અને તે પણ પુષ્કળ છે. તમારાં દાન એપાફ્રોદિતસની મારફતે મને મળ્યા છે તેથી હું સમૃદ્ધ છું. તે તો સુગંધીદાર ધૂપ ઈશ્વરને પ્રિય માન્ય અર્પણ છે.","mārī pāsē sarva cījavastuō chē; anē tē paṇa puṣkaḷa chē. tamārāṁ dāna ēpāphrōditasanī māraphatē manē maḷyā chē tēthī huṁ samr̥ddha chuṁ. tē tō sugaṁdhīdāra dhūpa īśvaranē priya mānya arpaṇa chē.",null],[4,19,"મારો ઈશ્વર પોતાના મહિમાની સંપત પ્રમાણે તમારી સર્વ ગરજ ખ્રિસ્ત ઈસુમાં પૂરી પાડશે.","mārō īśvara pōtānā mahimānī saṁpata pramāṇē tamārī sarva garaja khrista īsumāṁ pūrī pāḍaśē.",null],[4,20,"આપણા ઈશ્વરને તથા પિતાને સદાસર્વકાળ સુધી મહિમા હો. આમીન.","āpaṇā īśvaranē tathā pitānē sadāsarvakāḷa sudhī mahimā hō. āmīna.",null],[4,21,"ખ્રિસ્ત ઈસુમાં સર્વ સંતોને સલામ કહેજો, મારી સાથે જે ભાઈઓ છે તેઓ તમને સલામ કહે છે.","khrista īsumāṁ sarva saṁtōnē salāma kahējō, mārī sāthē jē bhāīō chē tēō tamanē salāma kahē chē.",null],[4,22,"સર્વ સંતો, વિશેષે જે કાઈસારનાં ઘરનાં છે, તેઓ તમને સલામ કહે છે.","sarva saṁtō, viśēṣē jē kāīsāranāṁ gharanāṁ chē, tēō tamanē salāma kahē chē.",null],[4,23,"આપણા પ્રભુ ઈસુ ખ્રિસ્તની કૃપા તમારા આત્માની સાથે હો. આમીન.","āpaṇā prabhu īsu khristanī kr̥pā tamārā ātmānī sāthē hō. āmīna.",null]],"kanirv":[[1,1,"ಕ್ರಿಸ್ತ ಯೇಸುವಿನ ದಾಸರಾದ ಪೌಲ ಮತ್ತು ತಿಮೊಥೆಯರು, ಫಿಲಿಪ್ಪಿಯದಲ್ಲಿ ಕ್ರಿಸ್ತ ಯೇಸುವಿನ ಮೂಲಕ ದೇವಜನರಾಗಿರುವವರೆಲ್ಲರಿಗೂ ಮತ್ತು ಅವರೊಂದಿಗಿರುವ ಸಭಾಧ್ಯಕ್ಷರಿಗೂ ಹಾಗೂ ಸಭಾಸೇವಕರಿಗೂ ಬರೆಯುವುದೇನೆಂದರೆ,","krista yēsuvina dāsarāda paula mattu timotheyaru, philippiyadalli krista yēsuvina mūlaka dēvajanarāgiruvavarellarigū mattu avaroṁdigiruva sabhādhyakṣarigū hāgū sabhāsēvakarigū bareyuvudēneṁdare,",null],[1,2,"ನಮ್ಮ ತಂದೆಯಾದ ದೇವರಿಂದಲೂ, ಕರ್ತನಾದ ಯೇಸು ಕ್ರಿಸ್ತನಿಂದಲೂ ನಿಮಗೆ ಕೃಪೆಯೂ, ಶಾಂತಿಯೂ ಲಭಿಸಲಿ.","namma taṁdeyāda dēvariṁdalū, kartanāda yēsu kristaniṁdalū nimage kr̥peyū, śāṁtiyū labhisali.",null],[1,3,"ನಾನು ನಿಮ್ಮನ್ನು ನೆನಪಿಸಿಕೊಳ್ಳುವಾಗೆಲ್ಲಾ ನನ್ನ ದೇವರಿಗೆ ಸ್ತೋತ್ರಸಲ್ಲಿಸುತ್ತೇನೆ, ನಾನು ನಿಮಗಾಗಿ ದೇವರನ್ನು ಪ್ರಾರ್ಥಿಸುವ ಎಲ್ಲಾ ಸಮಯಗಳಲ್ಲಿಯೂ ಸಂತೋಷದಿಂದಲೇ ಪ್ರಾರ್ಥಿಸುವವನಾಗಿದ್ದೇನೆ.","nānu nimmannu nenapisikoḷḷuvāgellā nanna dēvarige stōtrasallisuttēne, nānu nimagāgi dēvarannu prārthisuva ellā samayagaḷalliyū saṁtōṣadiṁdalē prārthisuvavanāgiddēne.",4],[1,5,"ನೀವು ಮೊದಲಿನಿಂದ ಇಂದಿನವರೆಗೂ ಸುವಾರ್ತಾಪ್ರಚಾರದಲ್ಲಿ ಸಹಕಾರಿಗಳಾಗಿದ್ದೀರೆಂದು ನನ್ನ ದೇವರಿಗೆ ಕೃತಜ್ಞತಾಸ್ತುತಿ ಮಾಡುತ್ತೇನೆ.","nīvu modaliniṁda iṁdinavaregū suvārtāpracāradalli sahakārigaḷāgiddīreṁdu nanna dēvarige kr̥tajñatāstuti māḍuttēne.",null],[1,6,"ಈ ಒಳ್ಳೆಯ ಕೆಲಸವನ್ನು ನಿಮ್ಮಲ್ಲಿ ಪ್ರಾರಂಭಿಸಿದಾತನು ಅದನ್ನು ನಡಿಸಿಕೊಂಡು ಯೇಸು ಕ್ರಿಸ್ತನು ಬರುವ ದಿನದೊಳಗಾಗಿ ಪೂರ್ಣತೆಗೆ ತರುವನೆಂದು ನನಗೆ ಭರವಸವುಂಟು.","ī oḷḷeya kelasavannu nimmalli prāraṁbhisidātanu adannu naḍisikoṁḍu yēsu kristanu baruva dinadoḷagāgi pūrṇatege taruvaneṁdu nanage bharavasavuṁṭu.",null],[1,7,"ನಿಮ್ಮೆಲ್ಲರನ್ನು ಕುರಿತು ನನಗೆ ಹೀಗನ್ನಿಸುವುದು ಸೂಕ್ತವೇ ಸರಿ. ನಾನು ಬಂಧನದಲ್ಲಿರುವಾಗಲೂ, ಸುವಾರ್ತೆಯ ಕುರಿತಾದ ವಾದ-ಪ್ರತಿವಾದಗಳಲ್ಲಿಯು ನೀವೆಲ್ಲರೂ ನನ್ನೊಂದಿಗೆ ದೇವರ ಕೃಪೆಯಲ್ಲಿ ಪಾಲುಗಾರರಾಗಿದ್ದೀರೆಂದು ನಿಮ್ಮನ್ನು ನನ್ನ ಹೃದಯದಲ್ಲಿರಿಸಿಕೊಂಡಿದ್ದೇನೆ.","nimmellarannu kuritu nanage hīgannisuvudu sūktavē sari. nānu baṁdhanadalliruvāgalū, suvārteya kuritāda vāda-prativādagaḷalliyu nīvellarū nannoṁdige dēvara kr̥peyalli pālugārarāgiddīreṁdu nimmannu nanna hr̥dayadallirisikoṁḍiddēne.",null],[1,8,"ಕ್ರಿಸ್ತ ಯೇಸುವಿಗಿರುವಂಥ ಕನಿಕರದಿಂದ ನಿಮ್ಮೆಲ್ಲರಿಗೋಸ್ಕರ ಎಷ್ಟೋ ಹಂಬಲಿಸುತ್ತೇನೆ. ಇದಕ್ಕೆ ದೇವರೇ ಸಾಕ್ಷಿ.","krista yēsuvigiruvaṁtha kanikaradiṁda nimmellarigōskara eṣṭō haṁbalisuttēne. idakke dēvarē sākṣi.",null],[1,9,"ಮತ್ತು ನಿಮ್ಮ ಪ್ರೀತಿಯು ಇನ್ನೂ ಅಧಿಕವಾಗಿ ಹೆಚ್ಚುತ್ತಾ ಪೂರ್ಣ ಜ್ಞಾನ ವಿವೇಕಗಳಿಂದ ಕೂಡಿರಬೇಕೆಂದು ನಾನು ನಿಮಗೋಸ್ಕರ ಪ್ರಾರ್ಥಿಸುತ್ತೇನೆ.","mattu nimma prītiyu innū adhikavāgi heccuttā pūrṇa jñāna vivēkagaḷiṁda kūḍirabēkeṁdu nānu nimagōskara prārthisuttēne.",null],[1,10,"ಹೀಗೆ ಉತ್ತಮ ಕಾರ್ಯಗಳು ಯಾವವೆಂಬುದನ್ನು ನೀವು ವಿವೇಚಿಸುವವರಾಗಬೇಕೆಂತಲೂ ಹಾಗೂ ಕ್ರಿಸ್ತನು ಬರುವ ದಿನದಲ್ಲಿ ನೀವು ಸರಳರಾಗಿಯೂ, ನಿರ್ಮಲರಾಗಿಯೂ,","hīge uttama kāryagaḷu yāvaveṁbudannu nīvu vivēcisuvavarāgabēkeṁtalū hāgū kristanu baruva dinadalli nīvu saraḷarāgiyū, nirmalarāgiyū,",null],[1,11,"ಯೇಸು ಕ್ರಿಸ್ತನ ಮೂಲಕವಾಗಿರುವ ನೀತಿಯೆಂಬ ಫಲದಿಂದ ತುಂಬಿದವರಾಗಿಯೂ ಇರಬೇಕೆಂದು ದೇವರಿಗೆ ಘನತೆಯನ್ನೂ ಸ್ತೋತ್ರವನ್ನೂ ಸಲ್ಲಿಸಬೇಕೆಂತಲೂ ಬೇಡಿಕೊಳ್ಳುತ್ತೇನೆ.","yēsu kristana mūlakavāgiruva nītiyeṁba phaladiṁda tuṁbidavarāgiyū irabēkeṁdu dēvarige ghanateyannū stōtravannū sallisabēkeṁtalū bēḍikoḷḷuttēne.",null],[1,12,"ಸಹೋದರರೇ, ನನಗೆ ಸಂಭವಿಸಿರುವಂಥವುಗಳೆಲ್ಲವೂ ಸುವಾರ್ತೆಯ ಪ್ರಸಾರಣೆಗೆ ಸಹಾಯವಾಯಿತೆಂದು ನೀವು ತಿಳಿಯಬೇಕೆಂಬುದಾಗಿ ಅಪೇಕ್ಷಿಸುತ್ತೇನೆ.","sahōdararē, nanage saṁbhavisiruvaṁthavugaḷellavū suvārteya prasāraṇege sahāyavāyiteṁdu nīvu tiḷiyabēkeṁbudāgi apēkṣisuttēne.",null],[1,13,"ಹೇಗೆಂದರೆ ನನ್ನ ಸೆರೆವಾಸವು ಕ್ರಿಸ್ತನ ನಿಮಿತ್ತವೇ ಎಂದು ಅರಮನೆಯ ಕಾವಲುಗಾರರೆಲ್ಲರಿಗೂ ಹಾಗೂ ಉಳಿದವರೆಲ್ಲರಿಗೂ ತಿಳಿಯಲ್ಪಟ್ಟಿತು.","hēgeṁdare nanna serevāsavu kristana nimittavē eṁdu aramaneya kāvalugārarellarigū hāgū uḷidavarellarigū tiḷiyalpaṭṭitu.",null],[1,14,"ಇದಲ್ಲದೆ ಸಹೋದರರಲ್ಲಿ ಬಹಳ ಜನರು ನನ್ನ ಬಂಧನದಿಂದಲೇ ಕರ್ತನಲ್ಲಿ ಭರವಸವುಳ್ಳವರಾಗಿ ದೇವರ ವಾಕ್ಯವನ್ನು ನಿರ್ಭಯದಿಂದ ಹೇಳುವುದಕ್ಕೆ ಇನ್ನೂ ಹೆಚ್ಚು ಧೈರ್ಯಹೊಂದಿದ್ದಾರೆ.","idallade sahōdararalli bahaḷa janaru nanna baṁdhanadiṁdalē kartanalli bharavasavuḷḷavarāgi dēvara vākyavannu nirbhayadiṁda hēḷuvudakke innū heccu dhairyahoṁdiddāre.",null],[1,15,"ಕೆಲವರು ಹೊಟ್ಟೆಕಿಚ್ಚುಪಟ್ಟು ಭೇದ ಹುಟ್ಟಿಸಬೇಕೆಂಬ ಮನಸ್ಸಿನಿಂದ ಮತ್ತು ಬೇರೆ ಕೆಲವರು ಒಳ್ಳೆಯ ಭಾವದಿಂದ ಕ್ರಿಸ್ತನನ್ನು ಪ್ರಚುರಪಡಿಸುತ್ತಾರೆ.","kelavaru hoṭṭekiccupaṭṭu bhēda huṭṭisabēkeṁba manassiniṁda mattu bēre kelavaru oḷḷeya bhāvadiṁda kristanannu pracurapaḍisuttāre.",null],[1,16,"ಇವರಂತೂ ನಾನು ಸುವಾರ್ತೆಯ ವಿಷಯದಲ್ಲಿ ಉತ್ತರ ಹೇಳುವುದಕ್ಕಾಗಿ ಇಲ್ಲಿ ಹಾಕಲ್ಪಟ್ಟಿದ್ದೆನೆಂದು ತಿಳಿದು ಪ್ರೀತಿಯಿಂದ ಪ್ರಸಿದ್ಧಿಪಡಿಸುತ್ತಿದ್ದಾರೆ.","ivaraṁtū nānu suvārteya viṣayadalli uttara hēḷuvudakkāgi illi hākalpaṭṭiddeneṁdu tiḷidu prītiyiṁda prasiddhipaḍisuttiddāre.",null],[1,17,"ಆ ಬೇರೆ ತರದವರಾದರೋ ನಾನು ಬೇಡಿಯಿಂದ ಬಂಧಿತನಾಗಿರುವಾಗಲೂ ನನಗೆ ಸಂಕಟವನ್ನು ಹೆಚ್ಚಿಸಬೇಕೆಂದು ಯೋಚಿಸಿ, ಪ್ರಾಮಾಣಿಕವಲ್ಲದ ಸ್ವಾರ್ಥ ಉದ್ದೇಶದಿಂದ ಕ್ರಿಸ್ತನನ್ನು ಪ್ರಸಿದ್ಧಿಪಡಿಸುತ್ತಾರೆ.","ā bēre taradavarādarō nānu bēḍiyiṁda baṁdhitanāgiruvāgalū nanage saṁkaṭavannu heccisabēkeṁdu yōcisi, prāmāṇikavallada svārtha uddēśadiṁda kristanannu prasiddhipaḍisuttāre.",null],[1,18,"ಹೇಗಾದರೇನು? ಯಾವ ರೀತಿಯಿಂದಾದರೂ ಸರಿಯೇ ಕಪಟದಿಂದಾಗಲಿ ಅಥವಾ ಸತ್ಯದಿಂದಾಗಲಿ ಕ್ರಿಸ್ತನನ್ನು ಪ್ರಸಿದ್ಧಿಪಡಿಸುವುದುಂಟು, ಇದಕ್ಕೆ ನಾನು ಸಂತೋಷಿಸುತ್ತೇನೆ, ಮುಂದೆಯೂ ಸಂತೋಷಿಸುವೆನು.","hēgādarēnu? yāva rītiyiṁdādarū sariyē kapaṭadiṁdāgali athavā satyadiṁdāgali kristanannu prasiddhipaḍisuvuduṁṭu, idakke nānu saṁtōṣisuttēne, muṁdeyū saṁtōṣisuvenu.",null],[1,19,"ಯಾಕೆಂದರೆ ನಿಮ್ಮ ವಿಜ್ಞಾಪನೆಯಿಂದಲೂ ಮತ್ತು ಯೇಸು ಕ್ರಿಸ್ತನ ಆತ್ಮನ ಸಹಾಯದಿಂದಲೂ ಇದು ನನ್ನ ಬಿಡುಗಡೆಗೆ ಅನುಕೂಲವಾಗುವುದೆಂದು ಬಲ್ಲೆನು.","yākeṁdare nimma vijñāpaneyiṁdalū mattu yēsu kristana ātmana sahāyadiṁdalū idu nanna biḍugaḍege anukūlavāguvudeṁdu ballenu.",null],[1,20,"ಹೇಗೆಂದರೆ ನಾನು ಯಾವ ವಿಷಯದಲ್ಲಾದರೂ ನಾಚಿಕೆಪಡದೆ ಎಂದಿನಂತೆ ಈಗಲೂ ಸಹ ತುಂಬಾ ಧೈರ್ಯದಿಂದಿರುವುದರಿಂದ ಬದುಕಿದರೂ ಸರಿಯೇ ಅಥವಾ ಸತ್ತರೂ ಸರಿಯೇ ನನ್ನ ಶರೀರದ ಮೂಲಕ ಕ್ರಿಸ್ತನಿಗೆ ಮಹಿಮೆಯುಂಟಾಗಬೇಕೆಂದು ನನ್ನ ಬಹು ಅಭಿಲಾಷೆಯಾಗಿದೆ, ಹಾಗೆಯೇ ಆಗುವುದೆಂಬ ಭರವಸೆವುಂಟು.","hēgeṁdare nānu yāva viṣayadallādarū nācikepaḍade eṁdinaṁte īgalū saha tuṁbā dhairyadiṁdiruvudariṁda badukidarū sariyē athavā sattarū sariyē nanna śarīrada mūlaka kristanige mahimeyuṁṭāgabēkeṁdu nanna bahu abhilāṣeyāgide, hāgeyē āguvudeṁba bharavasevuṁṭu.",null],[1,21,"ನನಗಂತೂ ಬದುಕುವುದೆಂದರೆ ಕ್ರಿಸ್ತನೇ, ಸಾಯುವುದು ಲಾಭವೇ.","nanagaṁtū badukuvudeṁdare kristanē, sāyuvudu lābhavē.",null],[1,22,"ಶರೀರದಲ್ಲಿಯೇ ಬದುಕಬೇಕಾದ್ದಲ್ಲಿ ನನ್ನ ಕೆಲಸಮಾಡಿ ಫಲಹೊಂದಲು ನನಗೆ ಸಾಧ್ಯವಾಗುವುದು. ಹೀಗಿರಲಾಗಿ ನಾನು ಯಾವುದನ್ನಾರಿಸಿಕೊಳ್ಳಬೇಕೆನ್ನುವುದು ನನಗೆ ತಿಳಿಯದು.","śarīradalliyē badukabēkāddalli nanna kelasamāḍi phalahoṁdalu nanage sādhyavāguvudu. hīgiralāgi nānu yāvudannārisikoḷḷabēkennuvudu nanage tiḷiyadu.",null],[1,23,"ಈ ಎರಡರ ನಡುವೆ ಸಿಕ್ಕಿಕೊಂಡಿದ್ದೇನೆ, ಇಲ್ಲಿಂದ ಹೊರಟು ಕ್ರಿಸ್ತನ ಜೊತೆಯಲ್ಲಿರಬೇಕೆಂಬುದೇ ನನ್ನ ಅಭಿಲಾಷೆ, ಅದು ಅತ್ಯುತ್ತಮವಾಗಿದೆ.","ī eraḍara naḍuve sikkikoṁḍiddēne, illiṁda horaṭu kristana joteyallirabēkeṁbudē nanna abhilāṣe, adu atyuttamavāgide.",null],[1,24,"ಆದರೆ ನಾನಿನ್ನೂ ಶರೀರದಲ್ಲಿ ವಾಸಮಾಡಿಕೊಂಡಿರುವುದು ನಿಮಗೋಸ್ಕರ ಬಹು ಅವಶ್ಯಕವಾಗಿದೆ.","ādare nāninnū śarīradalli vāsamāḍikoṁḍiruvudu nimagōskara bahu avaśyakavāgide.",null],[1,25,"ಆದ್ದರಿಂದ ನಿಮಗೆ ಕ್ರಿಸ್ತನಂಬಿಕೆಯಲ್ಲಿ ಅಭಿವೃದ್ಧಿಯೂ ಆನಂದವೂ ಉಂಟಾಗುವುದಕ್ಕೋಸ್ಕರ ನಾನು ಜೀವದಿಂದುಳಿದು ನಿಮ್ಮೆಲ್ಲರ ಬಳಿಯಲ್ಲಿರುವೆನೆಂದು ದೃಢವಾಗಿ ನಂಬಿದ್ದೇನೆ.","āddariṁda nimage kristanaṁbikeyalli abhivr̥ddhiyū ānaṁdavū uṁṭāguvudakkōskara nānu jīvadiṁduḷidu nimmellara baḷiyalliruveneṁdu dr̥ḍhavāgi naṁbiddēne.",null],[1,26,"ಹೀಗೆ ನಾನು ತಿರುಗಿ ನಿಮ್ಮ ಬಳಿಗೆ ಬರುವುದರಿಂದ ನೀವು ಕ್ರಿಸ್ತ ಯೇಸುವಿನ ವಿಷಯವಾಗಿ ಉಲ್ಲಾಸಪಡುವುದಕ್ಕೆ ನನ್ನಿಂದ ಅಧಿಕ ಆಸ್ಪದವಿರುವುದು.","hīge nānu tirugi nimma baḷige baruvudariṁda nīvu krista yēsuvina viṣayavāgi ullāsapaḍuvudakke nanniṁda adhika āspadaviruvudu.",null],[1,27,"ಹೇಗೂ ಕ್ರಿಸ್ತನ ಸುವಾರ್ತೆಗೆ ಯೋಗ್ಯರಾಗಿ ನಡೆದುಕೊಳ್ಳಿರಿ. ಆಗ ನಾನು ಬಂದು ನಿಮ್ಮನ್ನು ನೋಡಿದರೂ ಸರಿಯೇ, ದೂರದಲ್ಲಿದ್ದು ನಿಮ್ಮ ಸುದ್ದಿಯನ್ನು ಕೇಳಿದರೂ ಸರಿಯೇ, ನೀವು ನಿಮ್ಮ ವಿರೋಧಿಗಳಿಗೆ ಯಾವ ವಿಷಯದಲ್ಲಾದರೂ ಹೆದರದೆ ಏಕಮನಸ್ಸಿನಿಂದ ದೃಢವಾಗಿ ನಿಂತು ಸುವಾರ್ತೆಯಲ್ಲಿಟ್ಟ ನಂಬಿಕೆಗೋಸ್ಕರ ಐಕಮತ್ಯದಿಂದ ಹೋರಾಡುವವರಾಗಿದ್ದೀರೆಂದು ನಾನು ತಿಳಿದುಕೊಳ್ಳುವೆನು.","hēgū kristana suvārtege yōgyarāgi naḍedukoḷḷiri. āga nānu baṁdu nimmannu nōḍidarū sariyē, dūradalliddu nimma suddiyannu kēḷidarū sariyē, nīvu nimma virōdhigaḷige yāva viṣayadallādarū hedarade ēkamanassiniṁda dr̥ḍhavāgi niṁtu suvārteyalliṭṭa naṁbikegōskara aikamatyadiṁda hōrāḍuvavarāgiddīreṁdu nānu tiḷidukoḷḷuvenu.",null],[1,28,"ನೀವು ಹೀಗಿರುವುದು ವಿರೋಧಿಗಳ ನಾಶನಕ್ಕೂ, ನಿಮ್ಮ ರಕ್ಷಣೆಗೂ ಒಂದು ಗುರುತಾಗಿದೆ. ಅದು ದೇವರಿಂದಾದ ಮುನ್ಸೂಚನೆಯಾಗಿದೆ.","nīvu hīgiruvudu virōdhigaḷa nāśanakkū, nimma rakṣaṇegū oṁdu gurutāgide. adu dēvariṁdāda munsūcaneyāgide.",null],[1,29,"ಕ್ರಿಸ್ತನ ಮೇಲೆ ನಂಬಿಕೆಯಿಡುವುದು ಮಾತ್ರವಲ್ಲ ಆತನಿಗೋಸ್ಕರ ಬಾಧೆಯನ್ನನುಭವಿಸುವುದು ನಿಮಗೆ ವರವಾಗಿ ದೊರಕಿದೆ.","kristana mēle naṁbikeyiḍuvudu mātravalla ātanigōskara bādheyannanubhavisuvudu nimage varavāgi dorakide.",null],[1,30,"ಹೀಗೆ ನೀವು ನನ್ನಲ್ಲಿ ಕಂಡಂಥ ಮತ್ತು ಈಗ ನನ್ನ ಕುರಿತಾಗಿ ಕೇಳುವಂಥ ಅದೇ ಹೋರಾಟವು ನಿಮಗೂ ಉಂಟು.","hīge nīvu nannalli kaṁḍaṁtha mattu īga nanna kuritāgi kēḷuvaṁtha adē hōrāṭavu nimagū uṁṭu.",null],[2,1,"ಕ್ರಿಸ್ತನಿಂದ ಪ್ರೋತ್ಸಾಹ, ಪ್ರೀತಿಯ ಸಾಂತ್ವನ, ಪವಿತ್ರಾತ್ಮನ ಅನ್ಯೋನ್ಯತೆ, ಕಾರುಣ್ಯದಯಾರಸಗಳು ಉಂಟಾಗುವುದಾದರೆ,","kristaniṁda prōtsāha, prītiya sāṁtvana, pavitrātmana anyōnyate, kāruṇyadayārasagaḷu uṁṭāguvudādare,",null],[2,2,"ನೀವೆಲ್ಲರು ಒಂದೇ ಮನಸ್ಸುವುಳ್ಳವರಾಗಿ, ಒಂದೇ ಪ್ರೀತಿಯುಳ್ಳವರಾಗಿ, ಅನ್ಯೋನ್ಯಭಾವವುಳ್ಳವರಾಗಿ ಹಾಗೂ ಒಂದೇ ಗುರಿಯಿಟ್ಟುಕೊಂಡವರಾಗಿ ನನ್ನ ಸಂತೋಷವನ್ನು ಪರಿಪೂರ್ಣಮಾಡಿರಿ.","nīvellaru oṁdē manassuvuḷḷavarāgi, oṁdē prītiyuḷḷavarāgi, anyōnyabhāvavuḷḷavarāgi hāgū oṁdē guriyiṭṭukoṁḍavarāgi nanna saṁtōṣavannu paripūrṇamāḍiri.",null],[2,3,"ಸ್ವಾರ್ಥದಿಂದಾಗಲಿ, ಒಣ ಹೆಮ್ಮೆಯಿಂದಾಗಲಿ ಯಾವುದನ್ನೂ ಮಾಡದೆ, ಪ್ರತಿಯೊಬ್ಬನು ದೀನಭಾವದಿಂದ ಮತ್ತೊಬ್ಬರನ್ನು ತನಗಿಂತಲೂ ಶ್ರೇಷ್ಠರೆಂದು ಎಣಿಸಲಿ.","svārthadiṁdāgali, oṇa hemmeyiṁdāgali yāvudannū māḍade, pratiyobbanu dīnabhāvadiṁda mattobbarannu tanagiṁtalū śrēṣṭhareṁdu eṇisali.",null],[2,4,"ನಿಮ್ಮಲ್ಲಿ ಪ್ರತಿಯೊಬ್ಬನು ಸ್ವಹಿತವನ್ನು ಮಾತ್ರ ನೋಡದೆ ಪರಹಿತವನ್ನು ಸಹ ನೋಡಲಿ.","nimmalli pratiyobbanu svahitavannu mātra nōḍade parahitavannu saha nōḍali.",null],[2,5,"ಕ್ರಿಸ್ತ ಯೇಸುವಿನಲ್ಲಿದ್ದಂಥ ಮನಸ್ಸು ನಿಮ್ಮಲ್ಲಿಯೂ ಇರಲಿ.","krista yēsuvinalliddaṁtha manassu nimmalliyū irali.",null],[2,6,"ಆತನು ದೇವಸ್ವರೂಪನಾಗಿದ್ದರೂ, ದೇವರಿಗೆ ಸರಿಸಮಾನನಾಗಿರುವನೆಂಬ ಅಮೂಲ್ಯ ಪದವಿಯನ್ನು ಬಿಡಲೊಲ್ಲೆನು ಎಂದೆಣಿಸದೆ,","ātanu dēvasvarūpanāgiddarū, dēvarige sarisamānanāgiruvaneṁba amūlya padaviyannu biḍalollenu eṁdeṇisade,",null],[2,7,"ತನ್ನನ್ನು ಬರಿದು ಮಾಡಿಕೊಂಡು ದಾಸನ ರೂಪವನ್ನು ಧರಿಸಿಕೊಂಡು ಮನುಷ್ಯರಿಗೆ ಸಮನಾದನು. ಮನುಷ್ಯನಾಕಾರದಲ್ಲಿ ಕಾಣಿಸಿಕೊಂಡನು.","tannannu baridu māḍikoṁḍu dāsana rūpavannu dharisikoṁḍu manuṣyarige samanādanu. manuṣyanākāradalli kāṇisikoṁḍanu.",null],[2,8,"ಆತನು ತನ್ನನ್ನು ತಗ್ಗಿಸಿಕೊಂಡು ಮರಣವನ್ನು ಅಂದರೆ ಶಿಲುಬೆಯ ಮರಣವನ್ನಾದರೂ ಹೊಂದುವಷ್ಟು ವಿಧೇಯನಾದನು.","ātanu tannannu taggisikoṁḍu maraṇavannu aṁdare śilubeya maraṇavannādarū hoṁduvaṣṭu vidhēyanādanu.",null],[2,9,"ಈ ಕಾರಣದಿಂದ ದೇವರು ಆತನನ್ನು ಅತ್ಯುನ್ನತ ಸ್ಥಾನಕ್ಕೆ ಏರಿಸಿ, ಎಲ್ಲಾ ಹೆಸರುಗಳಿಗಿಂತ ಶ್ರೇಷ್ಠವಾದ ಹೆಸರನ್ನು ಆತನಿಗೆ ದಯಪಾಲಿಸಿದ್ದಾನೆ.","ī kāraṇadiṁda dēvaru ātanannu atyunnata sthānakke ērisi, ellā hesarugaḷigiṁta śrēṣṭhavāda hesarannu ātanige dayapālisiddāne.",null],[2,10,"ಆದ್ದರಿಂದ ಸ್ವರ್ಗ ಮರ್ತ್ಯ ಪಾತಾಳಗಳಲ್ಲಿರುವವರೆಲ್ಲರೂ ಯೇಸುವಿನ ಹೆಸರಿನಲ್ಲಿ ಮೊಣಕಾಲೂರಿ ಅಡ್ಡಬಿದ್ದು,","āddariṁda svarga martya pātāḷagaḷalliruvavarellarū yēsuvina hesarinalli moṇakālūri aḍḍabiddu,",null],[2,11,"ತಂದೆಯಾದ ದೇವರ ಮಹಿಮೆಗಾಗಿ ಪ್ರತಿಯೊಂದು ನಾಲಿಗೆಯು ಯೇಸು ಕ್ರಿಸ್ತನನ್ನು ಕರ್ತನೆಂದು ಅರಿಕೆಮಾಡುವುದು.","taṁdeyāda dēvara mahimegāgi pratiyoṁdu nāligeyu yēsu kristanannu kartaneṁdu arikemāḍuvudu.",null],[2,12,"ಹೀಗಿರುವಲ್ಲಿ ನನ್ನ ಪ್ರಿಯರೇ, ನೀವು ನನ್ನ ಮಾತನ್ನು ಯಾವಾಗಲೂ ಅನುಸರಿಸಿದಂತೆ ಈಗಲೂ ಅನುಸರಿಸಿರಿ. ನಾನು ನಿಮ್ಮಲ್ಲಿರುವಾಗ ಮಾತ್ರವಲ್ಲದೆ, ನಾನಿಲ್ಲದಿರುವಾಗಲೂ ಬಹು ಹೆಚ್ಚಾಗಿ ಮನೋಭೀತಿಯಿಂದ ನಡುಗುವವರಾಗಿ ನಿಮ್ಮ ನಿಮ್ಮ ರಕ್ಷಣೆಯನ್ನು ಸಾಧಿಸಿಕೊಳ್ಳಿರಿ.","hīgiruvalli nanna priyarē, nīvu nanna mātannu yāvāgalū anusarisidaṁte īgalū anusarisiri. nānu nimmalliruvāga mātravallade, nānilladiruvāgalū bahu heccāgi manōbhītiyiṁda naḍuguvavarāgi nimma nimma rakṣaṇeyannu sādhisikoḷḷiri.",null],[2,13,"ಯಾಕೆಂದರೆ ದೇವರೇ ತನ್ನ ಸುಚಿತ್ತವನ್ನು ನೆರವೇರಿಸಬೇಕೆಂದು ನಿಮ್ಮಲ್ಲಿ ಉದ್ದೇಶವನ್ನೂ ಮತ್ತು ಪ್ರಯತ್ನವನ್ನೂ ಉಂಟುಮಾಡುವವನಾಗಿದ್ದಾನೆ.","yākeṁdare dēvarē tanna sucittavannu neravērisabēkeṁdu nimmalli uddēśavannū mattu prayatnavannū uṁṭumāḍuvavanāgiddāne.",null],[2,14,"ಗೊಣಗುಟ್ಟದೆಯೂ, ವಿವಾದಗಳಿಲ್ಲದೆಯೂ ಎಲ್ಲವನ್ನು ಮಾಡಿರಿ.","goṇaguṭṭadeyū, vivādagaḷilladeyū ellavannu māḍiri.",null],[2,15,"ಹೀಗೆ ನೀವು ನಿರ್ದೋಷಿಗಳೂ ಹಾಗೂ ಯಥಾರ್ಥಮನಸ್ಸುಳ್ಳವರೂ ಆಗಿದ್ದು ವಕ್ರಬುದ್ಧಿಯುಳ್ಳ ಮೂರ್ಖ ಜಾತಿಯ ಮಧ್ಯದಲ್ಲಿ ದೇವರ ನಿಷ್ಕಳಂಕರಾದ ಮಕ್ಕಳಾಗಿರುವಿರಿ.","hīge nīvu nirdōṣigaḷū hāgū yathārthamanassuḷḷavarū āgiddu vakrabuddhiyuḷḷa mūrkha jātiya madhyadalli dēvara niṣkaḷaṁkarāda makkaḷāgiruviri.",null],[2,16,"ಇವರೊಳಗೆ ನೀವು ಸರ್ವರಿಗೂ ಜೀವದಾಯಕ ವಾಕ್ಯವನ್ನು ತೋರಿಸಿಕೊಡುವವರಾಗಿದ್ದು, ಲೋಕದೊಳಗೆ ಹೊಳೆಯುವ ನಕ್ಷತ್ರಗಳಂತೆ ಕಾಣಿಸುತ್ತೀರಿ. ನೀವು ಹೀಗೆ ನಡೆದರೆ ನಾನು ಸುವಾರ್ತೆಗಾಗಿ ಓಡಿದ ಓಟವು ವ್ಯರ್ಥವಲ್ಲ, ನಾನು ಪ್ರಯಾಸಪಟ್ಟದ್ದೂ ವ್ಯರ್ಥವಲ್ಲ ಎಂಬ ಹೊಗಳಿಕೆಯು ಕ್ರಿಸ್ತನ ದಿನದಲ್ಲಿ ನನಗೆ ಉಂಟಾಗುವುದು.","ivaroḷage nīvu sarvarigū jīvadāyaka vākyavannu tōrisikoḍuvavarāgiddu, lōkadoḷage hoḷeyuva nakṣatragaḷaṁte kāṇisuttīri. nīvu hīge naḍedare nānu suvārtegāgi ōḍida ōṭavu vyarthavalla, nānu prayāsapaṭṭaddū vyarthavalla eṁba hogaḷikeyu kristana dinadalli nanage uṁṭāguvudu.",null],[2,17,"ನಿಮ್ಮ ನಂಬಿಕೆಯೆಂಬ ಯಜ್ಞವನ್ನು ದೇವರಿಗರ್ಪಿಸುವ ಸೇವೆಯಲ್ಲಿ ನಾನೇ ಪಾನದ್ರವ್ಯವಾಗಿ ಅರ್ಪಿತವಾಗಬೇಕಾದರೂ ನನಗೆ ಸಂತೋಷವೇ, ನಿಮ್ಮೆಲ್ಲರೊಂದಿಗೂ ಸಂತೋಷ ಪಡುತ್ತೇನೆ.","nimma naṁbikeyeṁba yajñavannu dēvarigarpisuva sēveyalli nānē pānadravyavāgi arpitavāgabēkādarū nanage saṁtōṣavē, nimmellaroṁdigū saṁtōṣa paḍuttēne.",null],[2,18,"ಹಾಗೆಯೇ ನೀವೂ ಸಂತೋಷಿಸಿರಿ, ನನ್ನೊಂದಿಗೆ ಸಂತೋಷಪಡಿರಿ.","hāgeyē nīvū saṁtōṣisiri, nannoṁdige saṁtōṣapaḍiri.",null],[2,19,"ಆದರೆ ನಾನು ತಿಮೊಥೆಯನನ್ನು ಬೇಗನೆ ನಿಮ್ಮ ಬಳಿಗೆ ಕಳುಹಿಸಬೇಕೆಂದು ಕರ್ತನಾದ ಯೇಸುವಿನಲ್ಲಿ ನಿರೀಕ್ಷಿಸುತ್ತೇನೆ. ಅವನ ಮುಖಾಂತರ ನಿಮ್ಮ ಸಂಗತಿಗಳನ್ನು ತಿಳಿದು ನಾನೂ ಆದರಣೆ ಹೊಂದಿದೆನು.","ādare nānu timotheyanannu bēgane nimma baḷige kaḷuhisabēkeṁdu kartanāda yēsuvinalli nirīkṣisuttēne. avana mukhāṁtara nimma saṁgatigaḷannu tiḷidu nānū ādaraṇe hoṁdidenu.",null],[2,20,"ಅವನ ಹಾಗೆ ನಿಮ್ಮ ಯೋಗಕ್ಷೇಮವನ್ನು ಕುರಿತು ಯಥಾರ್ಥವಾಗಿ ಚಿಂತಿಸುವವರು ನನ್ನ ಬಳಿಯಲ್ಲಿ ಬೇರೆ ಯಾರೂ ಇಲ್ಲ.","avana hāge nimma yōgakṣēmavannu kuritu yathārthavāgi ciṁtisuvavaru nanna baḷiyalli bēre yārū illa.",null],[2,21,"ಎಲ್ಲರೂ ಸ್ವಕಾರ್ಯಗಳ ಮೇಲೆ ಮನಸ್ಸಿಡುತ್ತಾರೆಯೇ ಹೊರತು ಯೇಸು ಕ್ರಿಸ್ತನ ಕಾರ್ಯಗಳ ಮೇಲೆ ಮನಸ್ಸಿಡುವುದಿಲ್ಲ.","ellarū svakāryagaḷa mēle manassiḍuttāreyē horatu yēsu kristana kāryagaḷa mēle manassiḍuvudilla.",null],[2,22,"ಆದರೆ ತಿಮೊಥೆಯನ ಯೋಗ್ಯತೆಯನ್ನು ನೀವು ತಿಳಿದುಕೊಂಡಿದ್ದೀರಿ. ಮಗನು ತಂದೆಗೆ ಹೇಗೋ ಹಾಗೆಯೇ ಅವನು ನನ್ನ ಜೊತೆಯಲ್ಲಿ ಸುವಾರ್ತಾಪ್ರಚಾರಕ್ಕಾಗಿ ಸೇವೆಮಾಡಿದನೆಂಬುದು ನಿಮಗೆ ಗೊತ್ತುಂಟು.","ādare timotheyana yōgyateyannu nīvu tiḷidukoṁḍiddīri. maganu taṁdege hēgō hāgeyē avanu nanna joteyalli suvārtāpracārakkāgi sēvemāḍidaneṁbudu nimage gottuṁṭu.",null],[2,23,"ಆದ್ದರಿಂದ ನನ್ನ ವಿಷಯವು ಹೇಗಾಗುವುದೋ ಅದನ್ನು ತಿಳಿದ ಕೂಡಲೆ ಅವನನ್ನೇ ಕಳುಹಿಸುವುದಕ್ಕೆ ಬಯಸುತ್ತೇನೆ.","āddariṁda nanna viṣayavu hēgāguvudō adannu tiḷida kūḍale avanannē kaḷuhisuvudakke bayasuttēne.",null],[2,24,"ಇದಲ್ಲದೆ ನಾನು ಸಹ ಬೇಗನೆ ಬರುವೆನೆಂದು ಕರ್ತನಲ್ಲಿ ದೃಢವಾಗಿ ನಂಬಿದ್ದೇನೆ.","idallade nānu saha bēgane baruveneṁdu kartanalli dr̥ḍhavāgi naṁbiddēne.",null],[2,25,"ನನ್ನ ಕೊರತೆಯನ್ನು ನೀಗುವುದಕ್ಕೆ ನೀವು ಕಳುಹಿಸಿದಂಥ, ನನ್ನ ಸಹೋದರನೂ, ಜೊತೆಸೇವಕನೂ, ಸಹಸೇನಾನಿಯೂ ಆಗಿರುವಂಥ ಎಪಫ್ರೊದೀತನನ್ನು ನಿಮ್ಮ ಬಳಿಗೆ ಕಳುಹಿಸುವುದು ಅವಶ್ಯವೆಂದು ಭಾವಿಸಿದ್ದೇನೆ.","nanna korateyannu nīguvudakke nīvu kaḷuhisidaṁtha, nanna sahōdaranū, jotesēvakanū, sahasēnāniyū āgiruvaṁtha epaphrodītanannu nimma baḷige kaḷuhisuvudu avaśyaveṁdu bhāvisiddēne.",null],[2,26,"ಅವನು ನಿಮ್ಮೆಲ್ಲರನ್ನು ಕುರಿತು ಹಂಬಲಿಸುತ್ತಿದ್ದನು ಮತ್ತು ತಾನು ಅಸ್ವಸ್ಥನಾಗಿದ್ದ ಸುದ್ದಿಯನ್ನು ನೀವು ಕೇಳಿದ್ದರಿಂದ ಅವನು ನೊಂದುಕೊಂಡನು.","avanu nimmellarannu kuritu haṁbalisuttiddanu mattu tānu asvasthanāgidda suddiyannu nīvu kēḷiddariṁda avanu noṁdukoṁḍanu.",null],[2,27,"ಅವನು ರೋಗದಲ್ಲಿ ಬಿದ್ದು ಸಾಯುವ ಹಾಗಿದ್ದನೆಂಬುದು ನಿಜವೇ, ಆದರೆ ದೇವರು ಅವನನ್ನು ಕರುಣಿಸಿದನು. ಅವನನ್ನು ಮಾತ್ರವಲ್ಲದೆ ನನಗೆ ದುಃಖದ ಮೇಲೆ ದುಃಖವು ಬಾರದಂತೆ ನನ್ನನ್ನೂ ಕರುಣಿಸಿದನು.","avanu rōgadalli biddu sāyuva hāgiddaneṁbudu nijavē, ādare dēvaru avanannu karuṇisidanu. avanannu mātravallade nanage duḥkhada mēle duḥkhavu bāradaṁte nannannū karuṇisidanu.",null],[2,28,"ಆದ್ದರಿಂದ ನೀವು ಅವನನ್ನು ನೋಡಿ ತಿರುಗಿ ಸಂತೋಷಪಡಬೇಕೆಂತಲೂ ನನ್ನ ದುಃಖ ಕಡಿಮೆಯಾಗಬೇಕೆಂತಲೂ ನಾನು ಅವನನ್ನು ಅತಿ ತವಕದಿಂದ ಕಳುಹಿಸಿದ್ದೇನೆ.","āddariṁda nīvu avanannu nōḍi tirugi saṁtōṣapaḍabēkeṁtalū nanna duḥkha kaḍimeyāgabēkeṁtalū nānu avanannu ati tavakadiṁda kaḷuhisiddēne.",null],[2,29,"ಹೀಗಿರಲಾಗಿ ನೀವೇ ನನಗೆ ಮಾಡಬೇಕೆಂದಿರುವ ಉಪಚಾರದಲ್ಲಿ ಕೊರತೆಯಾದದ್ದನ್ನು ತುಂಬುವುದಕ್ಕಾಗಿ ಅವನು ಜೀವದ ಆಸೆಯನ್ನು ತೊರೆದು ಕ್ರಿಸ್ತನ ಸೇವೆಯ ನಿಮಿತ್ತ ಸಾಯುವ ಸ್ಥಿತಿಯಲ್ಲಿದುದ್ದರಿಂದ ನೀವು ಅವನನ್ನು ಪೂರ್ಣ ಸಂತೋಷದಿಂದ ಕರ್ತನ ಹೆಸರಿನಲ್ಲಿ ಸೇರಿಸಿಕೊಳ್ಳಿರಿ. ಅಂಥವರನ್ನು ಮಾನ್ಯರೆಂದೆಣಿಸಿರಿ.","hīgiralāgi nīvē nanage māḍabēkeṁdiruva upacāradalli korateyādaddannu tuṁbuvudakkāgi avanu jīvada āseyannu toredu kristana sēveya nimitta sāyuva sthitiyalliduddariṁda nīvu avanannu pūrṇa saṁtōṣadiṁda kartana hesarinalli sērisikoḷḷiri. aṁthavarannu mānyareṁdeṇisiri.",30],[3,1,"ಕಡೆಯದಾಗಿ ನನ್ನ ಸಹೋದರರೇ, ಕರ್ತನಲ್ಲಿ ಸಂತೋಷಪಡಿರಿ. ಮೊದಲು ತಿಳಿಸಿದ ಅದೇ ಮಾತುಗಳನ್ನು ಪುನಃ ನಿಮಗೆ ಬರೆಯುವುದಕ್ಕೆ ನನಗೇನೂ ಬೇಸರವಿಲ್ಲ, ಅವುಗಳು ನಿಮ್ಮನ್ನು ಭದ್ರಪಡಿಸುವವು.","kaḍeyadāgi nanna sahōdararē, kartanalli saṁtōṣapaḍiri. modalu tiḷisida adē mātugaḷannu punaḥ nimage bareyuvudakke nanagēnū bēsaravilla, avugaḷu nimmannu bhadrapaḍisuvavu.",null],[3,2,"ಆ ನಾಯಿಗಳಿಗೆ ಎಚ್ಚರವಾಗಿರಿ, ದುಷ್ಕರ್ಮಿಗಳಿಗೆ ಎಚ್ಚರಿಕೆಯಾಗಿರಿ. ಸುನ್ನತಿಯೆಂದು ಹೇಳಿಕೊಂಡು ಅಂಗಚ್ಛೇದನ ಮಾಡುವವರಿಂದ ಎಚ್ಚರಿಕೆಯಾಗಿರಿ.","ā nāyigaḷige eccaravāgiri, duṣkarmigaḷige eccarikeyāgiri. sunnatiyeṁdu hēḷikoṁḍu aṁgacchēdana māḍuvavariṁda eccarikeyāgiri.",null],[3,3,"ನಿಜವಾದ ಸುನ್ನತಿಯವರು ಯಾರೆಂದರೆ, ದೇವರಾತ್ಮನಿಂದ ಪ್ರೇರಿತರಾಗಿ ಆರಾಧಿಸುವವರೂ, ಕ್ರಿಸ್ತ ಯೇಸುವಿನಲ್ಲಿ ಹರ್ಷಗೊಳ್ಳುವವರೂ, ಶರೀರಸಂಬಂಧವಾದವುಗಳಲ್ಲಿ ಭರವಸವಿಲ್ಲದವರೂ ಆಗಿರುವ ನಾವುಗಳೇ.","nijavāda sunnatiyavaru yāreṁdare, dēvarātmaniṁda prēritarāgi ārādhisuvavarū, krista yēsuvinalli harṣagoḷḷuvavarū, śarīrasaṁbaṁdhavādavugaḷalli bharavasavilladavarū āgiruva nāvugaḷē.",null],[3,4,"ನಾನಾದರೋ ಶರೀರಸಂಬಂಧವಾದವುಗಳಲ್ಲಿ ಭರವಸವಿಡುವುದಕ್ಕೂ ಆಸ್ಪದವಿದೆ. ಬೇರೆ ಯಾವನಾದರೂ ಶರೀರಸಂಬಂಧವಾದವುಗಳಲ್ಲಿ ಭರವಸವಿಡಬಹುದೆಂದು ಯೋಚಿಸುವುದಾದರೆ ನಾನು ಅವನಿಗಿಂತಲೂ ಹೆಚ್ಚಾಗಿ ಹಾಗೆ ಯೋಚಿಸಬಹುದು.","nānādarō śarīrasaṁbaṁdhavādavugaḷalli bharavasaviḍuvudakkū āspadavide. bēre yāvanādarū śarīrasaṁbaṁdhavādavugaḷalli bharavasaviḍabahudeṁdu yōcisuvudādare nānu avanigiṁtalū heccāgi hāge yōcisabahudu.",null],[3,5,"ಹುಟ್ಟಿದ ಎಂಟನೆಯ ದಿನದಲ್ಲಿ ನನಗೆ ಸುನ್ನತಿಯಾಯಿತು, ನಾನು ಇಸ್ರಾಯೇಲ್ ವಂಶದವನು, ಬೆನ್ಯಾಮೀನನ ಕುಲದವನು, ಇಬ್ರಿಯರಿಂದ ಹುಟ್ಟಿದ ಇಬ್ರಿಯನು, ಧರ್ಮಶಾಸ್ತ್ರಗಳ ದೃಷ್ಟಿಯಿಂದ ನೋಡಿದರೆ ನಾನು ಫರಿಸಾಯನು,","huṭṭida eṁṭaneya dinadalli nanage sunnatiyāyitu, nānu isrāyēl vaṁśadavanu, benyāmīnana kuladavanu, ibriyariṁda huṭṭida ibriyanu, dharmaśāstragaḷa dr̥ṣṭiyiṁda nōḍidare nānu pharisāyanu,",null],[3,6,"ಮತಾಸಕ್ತಿಯನ್ನು ನೋಡಿದರೆ ನಾನು ಕ್ರೈಸ್ತ ಸಭೆಯ ಹಿಂಸಕನು, ಧರ್ಮಶಾಸ್ತ್ರದಲ್ಲಿ ಹೇಳಿರುವ ನೀತಿಯನ್ನು ನೋಡಿದರೆ ನಾನು ನಿರ್ದೋಷಿ.","matāsaktiyannu nōḍidare nānu kraista sabheya hiṁsakanu, dharmaśāstradalli hēḷiruva nītiyannu nōḍidare nānu nirdōṣi.",null],[3,7,"ಆದರೆ, ನನಗೆ ಲಾಭವಾಗಿದ್ದಂಥವುಗಳನ್ನು ಕ್ರಿಸ್ತನ ನಿಮಿತ್ತ ನಷ್ಟವೆಂದೆಣಿಸಿದ್ದೇನೆ.","ādare, nanage lābhavāgiddaṁthavugaḷannu kristana nimitta naṣṭaveṁdeṇisiddēne.",null],[3,8,"ಇಷ್ಟೇ ಅಲ್ಲದೆ, ನನ್ನ ಕರ್ತನಾದ ಕ್ರಿಸ್ತಯೇಸುವನ್ನರಿಯುವುದೇ ಅತಿ ಶ್ರೇಷ್ಠವಾದದ್ದೆಂದು ತಿಳಿದು ನಾನು ಎಲ್ಲವನ್ನು ನಷ್ಟವೆಂದೆಣಿಸುತ್ತೇನೆ. ಆತನ ನಿಮಿತ್ತ ನಾನು ಎಲ್ಲವನ್ನೂ ಕಳೆದುಕೊಂಡು ಅವುಗಳನ್ನು ಕಸವೆಂದೆಣಿಸುತ್ತೇನೆ.","iṣṭē allade, nanna kartanāda kristayēsuvannariyuvudē ati śrēṣṭhavādaddeṁdu tiḷidu nānu ellavannu naṣṭaveṁdeṇisuttēne. ātana nimitta nānu ellavannū kaḷedukoṁḍu avugaḷannu kasaveṁdeṇisuttēne.",null],[3,9,"ಇದರಲ್ಲಿ ನನ್ನ ಉದ್ದೇಶವೇನೆಂದರೆ, ನಾನು ಕ್ರಿಸ್ತನನ್ನು ಸಂಪಾದಿಸಿಕೊಂಡು, ಧರ್ಮಶಾಸ್ತ್ರದ ಫಲವಾಗಿರುವ ಸ್ವನೀತಿಯನ್ನಲ್ಲ, ಕ್ರಿಸ್ತನನ್ನು ನಂಬುವುದರಿಂದ ದೊರಕುವಂಥ ಅಂದರೆ ಕ್ರಿಸ್ತನ ಮೇಲಣ ನಂಬಿಕೆಯ ಆಧಾರದಿಂದ ದೇವರು ಕೊಡುವಂಥ ನೀತಿಯನ್ನೇ ಹೊಂದಿ ಕ್ರಿಸ್ತನಲ್ಲಿರುವವನಾಗಿರಬೇಕೆಂಬುದೇ.","idaralli nanna uddēśavēneṁdare, nānu kristanannu saṁpādisikoṁḍu, dharmaśāstrada phalavāgiruva svanītiyannalla, kristanannu naṁbuvudariṁda dorakuvaṁtha aṁdare kristana mēlaṇa naṁbikeya ādhāradiṁda dēvaru koḍuvaṁtha nītiyannē hoṁdi kristanalliruvavanāgirabēkeṁbudē.",null],[3,10,"ಆತನನ್ನೂ ಆತನ ಪುನರುತ್ಥಾನದಲ್ಲಿರುವ ಶಕ್ತಿಯನ್ನೂ, ಆತನ ಬಾಧೆಗಳಲ್ಲಿ ಪಾಲುಗಾರನಾಗಿರುವ ಪದವಿಯನ್ನೂ ತಿಳಿದುಕೊಂಡು ಆತನ ಮರಣದ ವಿಷಯದಲ್ಲಿ ಆತನಂತೆ ರೂಪಾಂತರಗೊಳ್ಳಬೇಕೆಂಬುದೇ ನನ್ನ ಬಯಕೆಯಾಗಿದೆ.","ātanannū ātana punarutthānadalliruva śaktiyannū, ātana bādhegaḷalli pālugāranāgiruva padaviyannū tiḷidukoṁḍu ātana maraṇada viṣayadalli ātanaṁte rūpāṁtaragoḷḷabēkeṁbudē nanna bayakeyāgide.",null],[3,11,"ಹೀಗಾದರೆ ಸತ್ತವರಲ್ಲಿ ಕೆಲವರಿಗೆ ಆಗುವ ಪುನರುತ್ಥಾನದ ಅನುಭವ ನನಗೂ ಆದೀತು.","hīgādare sattavaralli kelavarige āguva punarutthānada anubhava nanagū ādītu.",null],[3,12,"ಇಷ್ಟರೊಳಗೆ ನಾನಿದೆಲ್ಲವನ್ನೂ ಪಡಕೊಂಡು ಪರಿಪೂರ್ಣತೆಗೆ ಬಂದವನೆಂದು ಹೇಳುವುದಿಲ್ಲ. ಆದರೆ ನಾನು ಯಾವುದನ್ನು ಹೊಂದುವುದಕ್ಕಾಗಿ ಕ್ರಿಸ್ತ ಯೇಸುವು ನನ್ನನ್ನು ಹಿಡಿದುಕೊಂಡನೋ ಅದನ್ನು ಹೊಂದುವುದಕ್ಕೋಸ್ಕರ ಪ್ರಯತ್ನಿಸುತ್ತಾ ಇದ್ದೇನೆ.","iṣṭaroḷage nānidellavannū paḍakoṁḍu paripūrṇatege baṁdavaneṁdu hēḷuvudilla. ādare nānu yāvudannu hoṁduvudakkāgi krista yēsuvu nannannu hiḍidukoṁḍanō adannu hoṁduvudakkōskara prayatnisuttā iddēne.",null],[3,13,"ಸಹೋದರರೇ, ನಾನಂತೂ ಪಡೆದುಕೊಂಡವನೆಂದು ನನ್ನನ್ನು ಈ ವರೆಗೂ ಎಣಿಸಿಕೊಳ್ಳುವುದಿಲ್ಲ. ಆದರೆ ಒಂದು, ನಾನು ಹಿಂದಿನ ಸಂಗತಿಗಳನ್ನು ಮರೆತುಬಿಟ್ಟು ಮುಂದಿನವುಗಳನ್ನು ಹಿಡಿಯುವುದಕ್ಕಾಗಿ ಎದೆಬೊಗ್ಗಿದವನಾಗಿ,","sahōdararē, nānaṁtū paḍedukoṁḍavaneṁdu nannannu ī varegū eṇisikoḷḷuvudilla. ādare oṁdu, nānu hiṁdina saṁgatigaḷannu maretubiṭṭu muṁdinavugaḷannu hiḍiyuvudakkāgi edeboggidavanāgi,",null],[3,14,"ದೇವರು ಕ್ರಿಸ್ತನ ಮೂಲಕವಾಗಿ ನಮ್ಮನ್ನು ಮೇಲಕ್ಕೆ ಕರೆದು ನಮ್ಮ ಮುಂದೆ ಇಟ್ಟಿರುವ ಬಿರುದನ್ನು ಹೊಂದುವ ಗುರಿಯನ್ನು ತಲುಪಲೆಂದು ಓಡುತ್ತಾ ಇದ್ದೇನೆ.","dēvaru kristana mūlakavāgi nammannu mēlakke karedu namma muṁde iṭṭiruva birudannu hoṁduva guriyannu talupaleṁdu ōḍuttā iddēne.",null],[3,15,"ನಮ್ಮಲ್ಲಿ ಪ್ರವೀಣರಾದವರೆಲ್ಲರೂ ಈ ವಿಷಯದಲ್ಲಿ ಇದೇ ಅಭಿಪ್ರಾಯವುಳ್ಳವರಾಗಿರಿ. ಮತ್ತು ಯಾವುದಾದರೂ ಒಂದು ವಿಷಯದಲ್ಲಿ ನೀವು ಬೇರೆ ಅಭಿಪ್ರಾಯವುಳ್ಳವರಾಗಿದ್ದರೆ ಅದನ್ನು ದೇವರು ನಿಮಗೆ ತೋರಿಸಿಕೊಡುವನು.","nammalli pravīṇarādavarellarū ī viṣayadalli idē abhiprāyavuḷḷavarāgiri. mattu yāvudādarū oṁdu viṣayadalli nīvu bēre abhiprāyavuḷḷavarāgiddare adannu dēvaru nimage tōrisikoḍuvanu.",null],[3,16,"ಅಂತೂ, ನಾವು ಯಾವ ಸೂತ್ರವನ್ನನುಸರಿಸಿ ಇಲ್ಲಿಯ ವರೆಗೆ ಬಂದೆವೋ ಅದನ್ನೇ ಅನುಸರಿಸಿ ನಡೆಯೋಣ.","aṁtū, nāvu yāva sūtravannanusarisi illiya varege baṁdevō adannē anusarisi naḍeyōṇa.",null],[3,17,"ಸಹೋದರರೇ, ನೀವೆಲ್ಲರು ನನ್ನೊಂದಿಗೆ ಸೇರಿ ನನ್ನನ್ನು ಅನುಸರಿಸುವವರಾಗಿರಿ ಮತ್ತು ನಾವು ತೋರಿಸಿದ ಮಾದರಿಯ ಪ್ರಕಾರ ನಡೆದುಕೊಳ್ಳುವವರನ್ನು ಲಕ್ಷ್ಯಕ್ಕೆ ತಂದುಕೊಳ್ಳಿರಿ.","sahōdararē, nīvellaru nannoṁdige sēri nannannu anusarisuvavarāgiri mattu nāvu tōrisida mādariya prakāra naḍedukoḷḷuvavarannu lakṣyakke taṁdukoḷḷiri.",null],[3,18,"ಯಾಕೆಂದರೆ ಅನೇಕರು ಕ್ರಿಸ್ತನ ಶಿಲುಬೆಗೆ ವಿರೋಧಿಗಳಾಗಿ ನಡೆಯುತ್ತಾರೆ. ಅವರ ವಿಷಯದಲ್ಲಿ ನಿಮಗೆ ಎಷ್ಟೋ ಸಾರಿ ಹೇಳಿದೆನು, ಈಗಲೂ ಅಳುತ್ತಾ ಹೇಳುತ್ತೇನೆ.","yākeṁdare anēkaru kristana śilubege virōdhigaḷāgi naḍeyuttāre. avara viṣayadalli nimage eṣṭō sāri hēḷidenu, īgalū aḷuttā hēḷuttēne.",null],[3,19,"ನಾಶನವೇ ಅವರ ಅಂತ್ಯಾವಸ್ಥೆ, ಹೊಟ್ಟೆಯೇ ಅವರ ದೇವರು, ನಾಚಿಕೆಪಡಿಸುವ ಕೆಲಸಗಳಲ್ಲಿಯೇ ಅವರಿಗೆ ಘನತೆ, ಅವರು ಪ್ರಪಂಚದ ಕಾರ್ಯಗಳ ಕುರಿತು ಚಿಂತಿಸುವವರು.","nāśanavē avara aṁtyāvasthe, hoṭṭeyē avara dēvaru, nācikepaḍisuva kelasagaḷalliyē avarige ghanate, avaru prapaṁcada kāryagaḷa kuritu ciṁtisuvavaru.",null],[3,20,"ನಾವಾದರೋ ಪರಲೋಕದ ಪ್ರಜೆಗಳು, ಕರ್ತನಾದ ಯೇಸು ಕ್ರಿಸ್ತನು ಅಲ್ಲಿಂದಲೇ ರಕ್ಷಕನಾಗಿ ಬರುವುದನ್ನು ಎದುರುನೋಡುತ್ತಾ ಇದ್ದೇವೆ.","nāvādarō paralōkada prajegaḷu, kartanāda yēsu kristanu alliṁdalē rakṣakanāgi baruvudannu edurunōḍuttā iddēve.",null],[3,21,"ಆತನು ಎಲ್ಲವನ್ನೂ ತನಗೆ ಅಧೀನಮಾಡಿಕೊಳ್ಳಲಾಗುವ ಪರಾಕ್ರಮವನ್ನು ಹೊಂದಿದವನಾಗಿ ದೀನಾವಸ್ಥೆಯುಳ್ಳ ನಮ್ಮ ದೇಹವನ್ನು ಪ್ರಭಾವವುಳ್ಳ ತನ್ನ ದೇಹದಂತೆ ರೂಪಾಂತರಪಡಿಸುವನು.","ātanu ellavannū tanage adhīnamāḍikoḷḷalāguva parākramavannu hoṁdidavanāgi dīnāvastheyuḷḷa namma dēhavannu prabhāvavuḷḷa tanna dēhadaṁte rūpāṁtarapaḍisuvanu.",null],[4,1,"ಹೀಗಿರಲಾಗಿ, ನನ್ನ ಸಹೋದರರೇ ಅತಿ ಪ್ರಿಯರೇ, ಹಾಗೂ ಆಪ್ತರೇ, ನನಗೆ ಸಂತೋಷವೂ ಕಿರೀಟವೂ ಆಗಿರುವವರೇ, ನಾನು ಹೇಳಿದಂತೆ ಕರ್ತನಲ್ಲಿ ದೃಢವಾಗಿ ನಿಲ್ಲಿರಿ, ಪ್ರಿಯರೇ.","hīgiralāgi, nanna sahōdararē ati priyarē, hāgū āptarē, nanage saṁtōṣavū kirīṭavū āgiruvavarē, nānu hēḷidaṁte kartanalli dr̥ḍhavāgi nilliri, priyarē.",null],[4,2,"ಕರ್ತನಲ್ಲಿ ಒಂದೇ ಮನಸ್ಸುಳ್ಳವರಾಗಿರಿ ಎಂದು ಯುವೊದ್ಯಳನ್ನೂ ಹಾಗೂ ಸಂತುಕೆಯನ್ನೂ ಬೇಡಿಕೊಳ್ಳುತ್ತೇನೆ.","kartanalli oṁdē manassuḷḷavarāgiri eṁdu yuvodyaḷannū hāgū saṁtukeyannū bēḍikoḷḷuttēne.",null],[4,3,"ನನ್ನ ನಿಜವಾದ ಜೊತೆ ಸೇವಕನೇ, ಆ ಸ್ತ್ರೀಯರಿಗೆ ಸಹಾಯಕನಾಗಿರಬೇಕೆಂದು ನಿನ್ನನ್ನೂ ಕೇಳಿಕೊಳ್ಳುತ್ತೇನೆ. ಅವರು ಕ್ಲೇಮೆನ್ಸ್ ಮುಂತಾದ ನನ್ನ ಜೊತೆಕೆಲಸದವರ ಸಹಿತವಾಗಿ ನನ್ನ ಜೊತೆ ಸುವಾರ್ತೆಗೋಸ್ಕರ ಪ್ರಯಾಸಪಟ್ಟವರು. ಅವರವರ ಹೆಸರುಗಳು ಜೀವಬಾಧ್ಯರ ಪಟ್ಟಿಯಲ್ಲಿ ಬರೆದಿವೆ.","nanna nijavāda jote sēvakanē, ā strīyarige sahāyakanāgirabēkeṁdu ninnannū kēḷikoḷḷuttēne. avaru klēmens muṁtāda nanna jotekelasadavara sahitavāgi nanna jote suvārtegōskara prayāsapaṭṭavaru. avaravara hesarugaḷu jīvabādhyara paṭṭiyalli baredive.",null],[4,4,"ಯಾವಾಗಲೂ ಕರ್ತನಲ್ಲಿ ಸಂತೋಷಿಸಿರಿ, ಸಂತೋಷಪಡಿರಿ ಎಂದು ಪುನಃ ಹೇಳುತ್ತೇನೆ.","yāvāgalū kartanalli saṁtōṣisiri, saṁtōṣapaḍiri eṁdu punaḥ hēḷuttēne.",null],[4,5,"ನಿಮ್ಮ ಸೈರಣೆಯು ಎಲ್ಲಾ ಮನುಷ್ಯರಿಗೆ ಗೊತ್ತಾಗಲಿ, ಕರ್ತನು ಹತ್ತಿರವಾಗಿದ್ದಾನೆ.","nimma sairaṇeyu ellā manuṣyarige gottāgali, kartanu hattiravāgiddāne.",null],[4,6,"ಯಾವ ಸಂಬಂಧವಾಗಿಯೂ ಚಿಂತೆಮಾಡದೆ ಸರ್ವವಿಷಯಗಳಲ್ಲಿ ದೇವರ ಮುಂದೆ ಕೃತಜ್ಞತಾಸ್ತುತಿಯನ್ನೂ ಪ್ರಾರ್ಥನೆ ವಿಜ್ಞಾಪನೆಗಳನ್ನೂ ಮಾಡುತ್ತಾ ನಿಮಗೆ ಬೇಕಾದದ್ದನ್ನು ಕರ್ತನಿಗೆ ತಿಳಿಯಪಡಿಸಿರಿ.","yāva saṁbaṁdhavāgiyū ciṁtemāḍade sarvaviṣayagaḷalli dēvara muṁde kr̥tajñatāstutiyannū prārthane vijñāpanegaḷannū māḍuttā nimage bēkādaddannu kartanige tiḷiyapaḍisiri.",null],[4,7,"ಆಗ ಎಲ್ಲಾ ಗ್ರಹಿಕೆಯನ್ನು ಮೀರುವ ದೇವರ ಶಾಂತಿಯು ನಿಮ್ಮ ಹೃದಯಗಳನ್ನೂ, ಯೋಚನೆಗಳನ್ನೂ ಕ್ರಿಸ್ತ ಯೇಸುವಿನಲ್ಲಿ ಕಾಪಾಡುವುದು.","āga ellā grahikeyannu mīruva dēvara śāṁtiyu nimma hr̥dayagaḷannū, yōcanegaḷannū krista yēsuvinalli kāpāḍuvudu.",null],[4,8,"ಕಡೆಯದಾಗಿ, ಸಹೋದರರೇ, ಯಾವುದು ಸತ್ಯವೂ, ಮಾನ್ಯವೂ, ನ್ಯಾಯವೂ, ಶುದ್ಧವೂ, ಪ್ರೀತಿಕರವೂ, ಮನೋಹರವೂ ಆಗಿದೆಯೋ, ಯಾವುದು ಸದ್ಗುಣವಾಗಿದೆಯೋ, ಯಾವುದು ಕೀರ್ತಿಗೆ ಯೋಗ್ಯವೋ, ಅವೆಲ್ಲವುಗಳ ಬಗ್ಗೆ ಚಿಂತಿಸುವವರಾಗಿರಿ.","kaḍeyadāgi, sahōdararē, yāvudu satyavū, mānyavū, nyāyavū, śuddhavū, prītikaravū, manōharavū āgideyō, yāvudu sadguṇavāgideyō, yāvudu kīrtige yōgyavō, avellavugaḷa bagge ciṁtisuvavarāgiri.",null],[4,9,"ನೀವು ಯಾವುದನ್ನು ನನ್ನಿಂದ ಕಲಿತು ಹೊಂದಿದ್ದೀರೋ, ಮತ್ತು ಯಾವುದನ್ನು ನನ್ನಲ್ಲಿ ಕೇಳಿ ಕಂಡಿರುವಿರೋ ಅದನ್ನೇ ಮಾಡುತ್ತಾ ಬನ್ನಿರಿ. ಹೀಗೆ ಮಾಡಿದರೆ ಶಾಂತಿದಾಯಕನಾದ ದೇವರು ನಿಮ್ಮೊಂದಿಗಿರುವನು.","nīvu yāvudannu nanniṁda kalitu hoṁdiddīrō, mattu yāvudannu nannalli kēḷi kaṁḍiruvirō adannē māḍuttā banniri. hīge māḍidare śāṁtidāyakanāda dēvaru nimmoṁdigiruvanu.",null],[4,10,"ನನ್ನ ವಿಷಯದಲ್ಲಿ ನಿಮಗಿರುವ ಕಾಳಜಿಯು ಇಷ್ಟು ದಿನಗಳಾದ ಮೇಲೆ ಪುನಃ ಚಿಗುರಿದಕ್ಕೆ ನಾನು ಕರ್ತನಲ್ಲಿ ಹೆಚ್ಚಾಗಿ ಸಂತೋಷಪಡುತ್ತೇನೆ. ಇಂಥ ಯೋಚನೆ ನಿಮ್ಮಲ್ಲಿ ಈ ಮೊದಲೇ ಇದ್ದಿದ್ದರೂ, ಸಹಾಯ ಮಾಡುವುದಕ್ಕೆ ಸರಿಯಾದ ಸಂದರ್ಭ ಒದಗಿ ಬಂದಿರಲಿಲ್ಲ.","nanna viṣayadalli nimagiruva kāḷajiyu iṣṭu dinagaḷāda mēle punaḥ ciguridakke nānu kartanalli heccāgi saṁtōṣapaḍuttēne. iṁtha yōcane nimmalli ī modalē iddiddarū, sahāya māḍuvudakke sariyāda saṁdarbha odagi baṁdiralilla.",null],[4,11,"ನನ್ನ ಅಗತ್ಯಗಳ ಕುರಿತಾಗಿ ನಾನು ಇದನ್ನು ಹೇಳುತ್ತಿಲ್ಲ, ನಾನಂತೂ ಇದ್ದ ಸ್ಥಿತಿಯಲ್ಲಿಯೇ ಸಂತೃಪ್ತನಾಗಿರುವುದನ್ನು ಕಲಿತುಕೊಂಡಿದ್ದೇನೆ.","nanna agatyagaḷa kuritāgi nānu idannu hēḷuttilla, nānaṁtū idda sthitiyalliyē saṁtr̥ptanāgiruvudannu kalitukoṁḍiddēne.",null],[4,12,"ಬಡವನಾಗಿರಲೂ ಬಲ್ಲೆನು, ಸಮೃದ್ಧಿಯುಳ್ಳವನಾಗಿರಲೂ ಬಲ್ಲೆನು. ನಾನು ತೃಪ್ತನಾಗಿದ್ದರೂ, ಹಸಿದವನಾಗಿದ್ದರೂ, ಸಮೃದ್ಧಿಯುಳ್ಳವನಾದರೂ, ಕೊರತೆಯುಳ್ಳವನಾದರೂ ಯಾವ ತರದ ಸ್ಥಿತಿಯಲ್ಲಿರುವವನಾದರೂ ಅದರ ಗುಟ್ಟು ನನಗೆ ತಿಳಿದಿದೆ.","baḍavanāgiralū ballenu, samr̥ddhiyuḷḷavanāgiralū ballenu. nānu tr̥ptanāgiddarū, hasidavanāgiddarū, samr̥ddhiyuḷḷavanādarū, korateyuḷḷavanādarū yāva tarada sthitiyalliruvavanādarū adara guṭṭu nanage tiḷidide.",null],[4,13,"ನನ್ನನ್ನು ಬಲಪಡಿಸುವವನ ಮುಖಾಂತರ ನಾನು ಎಲ್ಲವನ್ನೂ ಮಾಡಲು ಶಕ್ತನಾಗಿದ್ದೇನೆ.","nannannu balapaḍisuvavana mukhāṁtara nānu ellavannū māḍalu śaktanāgiddēne.",null],[4,14,"ಹೀಗಿದ್ದರೂ ನೀವು ನನ್ನ ಸಂಕಟದಲ್ಲಿ ಸಹಭಾಗಿಗಳಾಗಿದ್ದದ್ದು ಒಳ್ಳೆಯದಾಯಿತು.","hīgiddarū nīvu nanna saṁkaṭadalli sahabhāgigaḷāgiddaddu oḷḷeyadāyitu.",null],[4,15,"ಫಿಲಿಪ್ಪಿಯವರೇ, ನಾನು ಪ್ರಾರಂಭದಲ್ಲಿ ನಿಮ್ಮಲ್ಲಿ ಸುವಾರ್ತೆಯನ್ನು ಸಾರಿ, ಮಕೆದೋನ್ಯದಿಂದ ಹೊರಟುಹೋದಾಗ ಕೊಡುವ, ಕೊಳ್ಳುವ ವಿಷಯದಲ್ಲಿ ನಿಮ್ಮ ಹೊರತು ಬೇರೆ ಯಾವ ಸಭೆಯೂ ನನಗೆ ಬೆಂಬಲಿಸಲ್ಲಿಲ್ಲವೆಂಬುದನ್ನು ನೀವೂ ಬಲ್ಲಿರಿ.","philippiyavarē, nānu prāraṁbhadalli nimmalli suvārteyannu sāri, makedōnyadiṁda horaṭuhōdāga koḍuva, koḷḷuva viṣayadalli nimma horatu bēre yāva sabheyū nanage beṁbalisallillaveṁbudannu nīvū balliri.",null],[4,16,"ನಾನು ಥೆಸಲೋನಿಕದಲ್ಲಿದ್ದಾಗಲೂ ನೀವು ಒಂದೆರಡು ಸಾರಿ ನನ್ನ ಕೊರತೆಯನ್ನು ನೀಗಿಸುವುದಕ್ಕೆ ಸಹಾಯವನ್ನು ಕೊಟ್ಟುಕಳುಹಿಸಿದಿರಲ್ಲಾ.","nānu thesalōnikadalliddāgalū nīvu oṁderaḍu sāri nanna korateyannu nīgisuvudakke sahāyavannu koṭṭukaḷuhisidirallā.",null],[4,17,"ನಾನು ನಿಮ್ಮಿಂದ ದಾನವನ್ನು ಅಪೇಕ್ಷಿಸುವುದಿಲ್ಲ, ನಿಮ್ಮ ಲೆಕ್ಕಕ್ಕೆ ಸಮೃದ್ಧಿಯುಂಟಾಗುವ ಫಲವನ್ನೇ ಅಪೇಕ್ಷಿಸುತ್ತೇನೆ.","nānu nimmiṁda dānavannu apēkṣisuvudilla, nimma lekkakke samr̥ddhiyuṁṭāguva phalavannē apēkṣisuttēne.",null],[4,18,"ಬೇಕಾದದ್ದೆಲ್ಲಾ ನನಗುಂಟು, ಸಮೃದ್ಧಿಹೊಂದಿದ್ದೇನೆ. ಎಪಫ್ರೊದೀತನ ಕೈಯಿಂದ ನೀವು ಕೊಟ್ಟು ಕಳುಹಿಸಿದ್ದು ನನಗೆ ತಲುಪಲಾಗಿ ನಾನು ತುಂಬಿತುಳುಕಿದವನಾಗಿದ್ದೇನೆ. ಅದು ದೇವರಿಗೆ ಮೆಚ್ಚಿಕೆಯಾದದ್ದು, ಸುಗಂಧವಾಸನೆಯೇ, ಇಷ್ಟ ಯಜ್ಞವೇ.","bēkādaddellā nanaguṁṭu, samr̥ddhihoṁdiddēne. epaphrodītana kaiyiṁda nīvu koṭṭu kaḷuhisiddu nanage talupalāgi nānu tuṁbituḷukidavanāgiddēne. adu dēvarige meccikeyādaddu, sugaṁdhavāsaneyē, iṣṭa yajñavē.",null],[4,19,"ನನ್ನ ದೇವರು ಕ್ರಿಸ್ತ ಯೇಸುವಿನ ಮೂಲಕ ತನ್ನ ಪ್ರಭಾವದ ಐಶ್ವರ್ಯಕ್ಕೆ ತಕ್ಕ ಹಾಗೆ ನಿಮ್ಮ ಪ್ರತಿಯೊಂದು ಕೊರತೆಗಳನ್ನೂ ನೀಗಿಸುವನು.","nanna dēvaru krista yēsuvina mūlaka tanna prabhāvada aiśvaryakke takka hāge nimma pratiyoṁdu korategaḷannū nīgisuvanu.",null],[4,20,"ನಮ್ಮ ತಂದೆಯಾದ ದೇವರಿಗೆ ಯುಗಯುಗಾಂತರಗಳಲ್ಲಿಯೂ ಮಹಿಮೆಯುಂಟಾಗಲಿ. ಆಮೆನ್‍.","namma taṁdeyāda dēvarige yugayugāṁtaragaḷalliyū mahimeyuṁṭāgali. āmen.",null],[4,21,"ಕ್ರಿಸ್ತ ಯೇಸುವಿನಲ್ಲಿರುವ ಪ್ರತಿಯೊಬ್ಬ ಭಕ್ತರಿಗೂ ನನ್ನ ವಂದನೆಯನ್ನು ಹೇಳಿರಿ. ನನ್ನ ಜೊತೆಯಲ್ಲಿರುವ ಸಹೋದರರು ನಿಮ್ಮನ್ನು ವಂದಿಸುತ್ತಾರೆ.","krista yēsuvinalliruva pratiyobba bhaktarigū nanna vaṁdaneyannu hēḷiri. nanna joteyalliruva sahōdararu nimmannu vaṁdisuttāre.",null],[4,22,"ಇಲ್ಲಿರುವ ದೇವಜನರೆಲ್ಲರು ನಿಮ್ಮನ್ನು ವಂದಿಸುತ್ತಾರೆ. ವಿಶೇಷವಾಗಿ ಕೈಸರನ ಅರಮನೆಗೆ ಸೇರಿದವರು ನಿಮಗೆ ವಂದನೆಗಳನ್ನು ತಿಳಿಸಿದ್ದಾರೆ.","illiruva dēvajanarellaru nimmannu vaṁdisuttāre. viśēṣavāgi kaisarana aramanege sēridavaru nimage vaṁdanegaḷannu tiḷisiddāre.",null],[4,23,"ಕರ್ತನಾದ ಯೇಸು ಕ್ರಿಸ್ತನ ಕೃಪೆಯು ನಿಮ್ಮ ಆತ್ಮದೊಂದಿಗೆ ಇರಲಿ.","kartanāda yēsu kristana kr̥peyu nimma ātmadoṁdige irali.",null]],"kfx":[[1,1,"मसीह यीशु रे दास पौलुस होर तीमुथियुसे री तरफा ना सेभी पवित्र लोका रे नाँ, जूण मसीह ना होईया फिलीपी ना रोहा सी, अध्यक्ष होर सेवका समेत l","masīha yīśu rē dāsa paulusa hōra tīmuthiyusē rī taraphā nā sēbhī pavitra lōkā rē nām̐, jūṇa masīha nā hōīyā philīpī nā rōhā sī, adhyakṣa hōra sēvakā samēta l",null],[1,2,"आसारे बापू परमेश्वर होर प्रभु यीशु मसीह री तरफा ना तुसा बे अनुग्रह होर शान्ति मिलदी रोहे l","āsārē bāpū paramēśvara hōra prabhu yīśu masīha rī taraphā nā tusā bē anugraha hōra śānti miladī rōhē l",null],[1,3,"हाँऊ जेबे-जेबे तुसा बे याद केरा सा, ता तेबे-तेबे परमेश्वरा रा धन्यावाद केरा सा l","hām̐ū jēbē-jēbē tusā bē yāda kērā sā, tā tēbē-tēbē paramēśvarā rā dhanyāvāda kērā sā l",null],[1,4,"होर जेबे भी तुसा सेभी री तेंइये प्रार्थना केरा सा, होर हमेशा खुश होईया प्रार्थना केरा सा l","hōra jēbē bhī tusā sēbhī rī tēṁiyē prārthanā kērā sā, hōra hamēśā khuśa hōīyā prārthanā kērā sā l",null],[1,5,"किबैकि, कि तुसे पहले रोजा ना लेइया ओज़ा तक सुसमाचार बोंडणै ना मेरे साथी रोहे सी l","kibaiki, ki tusē pahalē rōjā nā lēiyā ōzā taka susamācāra bōṁḍaṇai nā mērē sāthī rōhē sī l",null],[1,6,"होर मुम्बे एसा गल्ला रा बशाह सा, कि जूणी ऐ तुसा मौन्झे शोभला कौम शुरू केरू सा, तेई सो यीशु मसीह रे धियाड़े तक पुरा केरना l","hōra mumbē ēsā gallā rā baśāha sā, ki jūṇī ai tusā maunjhē śōbhalā kauma śurū kērū sā, tēī sō yīśu masīha rē dhiyāṛē taka purā kēranā l",null],[1,7,"सही सा, कि हाँऊ तुसा सेभी रे तेंइए एण्डा विचार केरणु किबैकि तुसे मेरे मना ना बसेदें सी, मेरी कैदा ना होर सुस्माचारा रे तेंइए जबाब होर सबूत देणै ना तुसे सेभ मुं सेंघे अनुग्रह ना सहभागी सी l","sahī sā, ki hām̐ū tusā sēbhī rē tēṁiē ēṇḍā vicāra kēraṇu kibaiki tusē mērē manā nā basēdēṁ sī, mērī kaidā nā hōra susmācārā rē tēṁiē jabāba hōra sabūta dēṇai nā tusē sēbha muṁ sēṁghē anugraha nā sahabhāgī sī l",null],[1,8,"एता ना परमेश्वर मेरा गवाह सा, कि हाँऊ मसीह यीशु री तरह बशाह केरिया तुसा सेभी री इच्छा केरा सा l","ētā nā paramēśvara mērā gavāha sā, ki hām̐ū masīha yīśu rī taraha baśāha kēriyā tusā sēbhī rī icchā kērā sā l",null],[1,9,"होर हाँऊ ऐ प्रार्थना केरा सा, कि तुसारा प्यार, ज्ञान होर सेभी साही ना दिमाग भी बढ़दा रोहे l","hōra hām̐ū ai prārthanā kērā sā, ki tusārā pyāra, jñāna hōra sēbhī sāhī nā dimāga bhī baṛhadā rōhē l",null],[1,10,"ओखे तेंई कि तुसे शोभली ना शोभली गला बे प्रिय मना, होर मसीह रे धियाड़े तक सच्चे बणीया रोहा, होर ठोकर मता खांदे l","ōkhē tēṁī ki tusē śōbhalī nā śōbhalī galā bē priya manā, hōra masīha rē dhiyāṛē taka saccē baṇīyā rōhā, hōra ṭhōkara matā khāṁdē l",null],[1,11,"होर तेसा धार्मिकता रे फला ना जूण यीशु मसीह री बजह ना होआ सा, भौरदे जात, जूणी ना परमेश्वरे री महिमा होर स्तुति होंदी रोहे l","hōra tēsā dhārmikatā rē phalā nā jūṇa yīśu masīha rī bajaha nā hōā sā, bhauradē jāta, jūṇī nā paramēśvarē rī mahimā hōra stuti hōṁdī rōhē l",null],[1,12,"ओ भाइयो, हाँऊ तुसा बै दसणा चाहा सा, कि जे मुं पांधे बीती सा, तेसा बजह ना सुस्माचार ऐ बढ़ु साl","ō bhāiyō, hām̐ū tusā bai dasaṇā cāhā sā, ki jē muṁ pāṁdhē bītī sā, tēsā bajaha nā susmācāra ai baṛhu sāl",null],[1,13,"ओखे तक कि केसरी राज्य री सारी सेना होर बाकी सारे लोका ना ऐ ता प्रगट हुआ सा, कि हाँऊ मसीह री तेंइए कैद सा l","ōkhē taka ki kēsarī rājya rī sārī sēnā hōra bākī sārē lōkā nā ai tā pragaṭa huā sā, ki hām̐ū masīha rī tēṁiē kaida sā l",null],[1,14,"होर प्रभु ना जूण भाई सा, तिन्हा मौन्झे बोहु मेरे कैद होणे री बजह ना, हिम्मता सेंघे, परमेश्वरा रा वचन बेधड़क शनाणै री होर भी हिम्मत केरा सी l","hōra prabhu nā jūṇa bhāī sā, tinhā maunjhē bōhu mērē kaida hōṇē rī bajaha nā, himmatā sēṁghē, paramēśvarā rā vacana bēdhaṛaka śanāṇai rī hōra bhī himmata kērā sī l",null],[1,15,"केतरे ता जलन,होर झगड़े री बजह ना मसीह रा प्रचार केरा सी, होर केतरे शोभले मना ना l","kētarē tā jalana,hōra jhagaṛē rī bajaha nā masīha rā pracāra kērā sī, hōra kētarē śōbhalē manā nā l",null],[1,16,"एका ता ऐ सोचिया कि हाँऊ सुस्माचारा रा जबाब देणे री तक ठहराऊ सा, प्यारा सेंघे प्रचार केरा सा l","ēkā tā ai sōciyā ki hām̐ū susmācārā rā jabāba dēṇē rī taka ṭhaharāū sā, pyārā sēṁghē pracāra kērā sā l",null],[1,17,"होर कई एक ता सच्चे मने नेई पर विरोध केरिया मसीह री काहाणी शणा सी, ऐ सोचिया कि जेबे हाँऊ जेला ना सा ता मुम्बे होर कष्ट मिलला ll","hōra kaī ēka tā saccē manē nēī para virōdha kēriyā masīha rī kāhāṇī śaṇā sī, ai sōciyā ki jēbē hām̐ū jēlā nā sā tā mumbē hōra kaṣṭa milalā ll",null],[1,18,"तेबे कि हुआ? सिर्फ ऐ, कि हर तरह ना चाहे बहाने ना, चाहे सच्चाई ना, मसीह री कहाणी शणाईया सा, होर हाँऊ एता ना खुश सा, होर मुं खुश रोहणा भी l","tēbē ki huā? sirpha ai, ki hara taraha nā cāhē bahānē nā, cāhē saccāī nā, masīha rī kahāṇī śaṇāīyā sā, hōra hām̐ū ētā nā khuśa sā, hōra muṁ khuśa rōhaṇā bhī l",null],[1,19,"किबैकि मुम्बे पता सा, कि तुसे री प्रार्थना री बजह ना, होर यीशु मसीह रे पवित्र आत्मा री दाना री बजह ना, एता रा प्रतिफल मेरा उद्धार होला l","kibaiki mumbē patā sā, ki tusē rī prārthanā rī bajaha nā, hōra yīśu masīha rē pavitra ātmā rī dānā rī bajaha nā, ētā rā pratiphala mērā uddhāra hōlā l",null],[1,20,"हाँऊ ता दिला ना इच्छा होर आशा रखा सा, कि मुम्बे कोई गला ना शर्म नी लोड़ी हुई, पर मेरी बडी हिम्मते री बजह ना मसीह री तारीफ़ मेरे शरीरा ना होंदी रोहे l","hām̐ū tā dilā nā icchā hōra āśā rakhā sā, ki mumbē kōī galā nā śarma nī lōṛī huī, para mērī baḍī himmatē rī bajaha nā masīha rī tārīfa mērē śarīrā nā hōṁdī rōhē l",null],[1,21,"किबैकि मेरे तेंइए ज़िंदा रोहणा मसीह सा, होर मौरना फायदा सा l","kibaiki mērē tēṁiē ziṁdā rōhaṇā masīha sā, hōra mauranā phāyadā sā l",null],[1,22,"होर अगर शरीरा ना ज़िंदा रोहणा ऐ मेरे कौमा री तेंइए फ़ायदा सा, ता मुम्बे नी पता हाँऊ कुणी बे छांटणुl","hōra agara śarīrā nā ziṁdā rōhaṇā ai mērē kaumā rī tēṁiē fāyadā sā, tā mumbē nī patā hām̐ū kuṇī bē chāṁṭaṇul",null],[1,23,"हाँऊ ता दुई मौन्झे औधा लटकू सा, जिऊ ता केरा सा कि ओखे ना मसीह आगे जानू, किबैकि सो बोहु शोभला सा l","hām̐ū tā duī maunjhē audhā laṭakū sā, jiū tā kērā sā ki ōkhē nā masīha āgē jānū, kibaiki sō bōhu śōbhalā sā l",null],[1,24,"पर शरीरा ना तुसा री तेंइऐ रोहणा होर भी जरूरी साl","para śarīrā nā tusā rī tēṁiai rōhaṇā hōra bhī jarūrī sāl",null],[1,25,"तेबैता ता मुम्बे एता रा बशाह सा, होर मुम्बे पता सा कि मुं जिन्दे रोहणा, बल्कि तुसा सेंघे रोहणा कि तुसे बशाह ना बढ़दे रोहा होर तेई ना खुश रोहा l","tēbaitā tā mumbē ētā rā baśāha sā, hōra mumbē patā sā ki muṁ jindē rōhaṇā, balki tusā sēṁghē rōhaṇā ki tusē baśāha nā baṛhadē rōhā hōra tēī nā khuśa rōhā l",null],[1,26,"होर जूण घमण्ड तुसे मेरे बारे ना करा सी, सो मेरे तुसा आगे भी ऐणै पांधे होर भी लोड़ी बढ़ु l","hōra jūṇa ghamaṇḍa tusē mērē bārē nā karā sī, sō mērē tusā āgē bhī aiṇai pāṁdhē hōra bhī lōṛī baṛhu l",null],[1,27,"सिर्फ ऐतरा केरा कि तुसा रा चाल-चलन मसीह रे सुसमाचारा रे योग्य हो, चाहे हाँऊ ऐजिया हेरणु, चाहे नेई भी ऐनु, तुसा रे बारे ना ऐ शुणनु, कि तुसे एकी ऐ आत्मा ना मजबूत सी, होर एक मन होईया सुसमाचारा रे बशाह री तेंइए मेहनत केरा सी l","sirpha aitarā kērā ki tusā rā cāla-calana masīha rē susamācārā rē yōgya hō, cāhē hām̐ū aijiyā hēraṇu, cāhē nēī bhī ainu, tusā rē bārē nā ai śuṇanu, ki tusē ēkī ai ātmā nā majabūta sī, hōra ēka mana hōīyā susamācārā rē baśāha rī tēṁiē mēhanata kērā sī l",null],[1,28,"होर कोई भी गला न दुश्मना ना नी डोरदे? ऐ तिन्हा री तेंइए विनाशा री निशाणी सा, होर तुसा री तेंइए उद्धारे री, होर ऐ परमेश्वरा री तरफा ना सा l","hōra kōī bhī galā na duśmanā nā nī ḍōradē? ai tinhā rī tēṁiē vināśā rī niśāṇī sā, hōra tusā rī tēṁiē uddhārē rī, hōra ai paramēśvarā rī taraphā nā sā l",null],[1,29,"किबैकि मसीह री बजह ना तुसा पांधे ऐ अनुग्रह हुआ सा, कि ना सिर्फ तेई पांधे बशाह रखा, बल्कि पर तेई री तेंइये दुःख भी चक्का l","kibaiki masīha rī bajaha nā tusā pāṁdhē ai anugraha huā sā, ki nā sirpha tēī pāṁdhē baśāha rakhā, balki para tēī rī tēṁiyē duḥkha bhī cakkā l",null],[1,30,"होर तुसा बे तेन्ढी ऐ मेहनत केरनी सा, जेण्डा तुसे हाँऊ केरदा हेरू सा, होर ऐबे भी शुणा सी कि हाँऊ हाज़ी भी तेंडा ऐ कौम केरा सा l","hōra tusā bē tēnḍhī ai mēhanata kēranī sā, jēṇḍā tusē hām̐ū kēradā hērū sā, hōra aibē bhī śuṇā sī ki hām̐ū hāzī bhī tēṁḍā ai kauma kērā sā l",null],[2,1,"होर अगर मसीह न किच्छ शान्ति, होर प्यारा न बशाह होर आत्मा री हिस्सेदारी, होर किच्छ करुणा होर दया सा l","hōra agara masīha na kiccha śānti, hōra pyārā na baśāha hōra ātmā rī hissēdārī, hōra kiccha karuṇā hōra dayā sā l",null],[2,2,"ता ऐबे मेरी ऐ ख़ुशी पूरी केरा कि एक मन होईया रोहा होर ऐके प्यार, एक चित, होर एक विचार रखा l","tā aibē mērī ai k͟huśī pūrī kērā ki ēka mana hōīyā rōhā hōra aikē pyāra, ēka cita, hōra ēka vicāra rakhā l",null],[2,3,"विरोध होर झूठी तारिफा री तेंइए किच्छ मता केरदे पर दीनता न एकी-दूजे बे आपु न बड़िया समझा l","virōdha hōra jhūṭhī tāriphā rī tēṁiē kiccha matā kēradē para dīnatā na ēkī-dūjē bē āpu na baṛiyā samajhā l",null],[2,4,"हर एक आपणै बारे न नेई, पर दूजे रे बारे न भी चिन्ता फ़िक्र केरला l","hara ēka āpaṇai bārē na nēī, para dūjē rē bārē na bhī cintā fikra kēralā l",null],[2,5,"जेंडा मसीह यीशु रा स्वभाव ती तेंडा ऐ तुसा रा भी स्वभाव हो l","jēṁḍā masīha yīśu rā svabhāva tī tēṁḍā ai tusā rā bhī svabhāva hō l",null],[2,6,"जूणीऐ परमेश्वरा रे बराबर होईया भी परमेश्वरा रे बराबर होणे बे आपु आगे रखणै री चीज नेई बुझी l","jūṇīai paramēśvarā rē barābara hōīyā bhī paramēśvarā rē barābara hōṇē bē āpu āgē rakhaṇai rī cīja nēī bujhī l",null],[2,7,"बल्कि आपणै आपा बे ऐन्डा शून्य केरू, होर दासा रा रूप धारण केरू, होर माँणहु रे बराबर हुआ l","balki āpaṇai āpā bē ainḍā śūnya kērū, hōra dāsā rā rūpa dhāraṇa kērū, hōra mām̐ṇahu rē barābara huā l",null],[2,8,"होर माँणहु रै रूपा ना प्रगट होईया, आपणै आपा बे दीन केरू, होर ओखे तक आज्ञाकारी रोहू, कि क्रूसा री मौत भी सहन केरी l","hōra mām̐ṇahu rai rūpā nā pragaṭa hōīyā, āpaṇai āpā bē dīna kērū, hōra ōkhē taka ājñākārī rōhū, ki krūsā rī mauta bhī sahana kērī l",null],[2,9,"ऐसा बजह न परमेशवरे सौ सेभी न महान भी केरू, होर तेई बे सौ नाँ धिना जूण सेभी नाँ न उत्तम सा l","aisā bajaha na paramēśavarē sau sēbhī na mahāna bhī kērū, hōra tēī bē sau nām̐ dhinā jūṇa sēbhī nām̐ na uttama sā l",null],[2,10,"कि जूण स्वर्गा न होर धौरती पांधे होर जूण धौरती न बुने सी, ते सेभ यीशु रै नाँ पांधे घुटने टेकले l","ki jūṇa svargā na hōra dhauratī pāṁdhē hōra jūṇa dhauratī na bunē sī, tē sēbha yīśu rai nām̐ pāṁdhē ghuṭanē ṭēkalē l",null],[2,11,"होर परमेशवरे री महिमा री तेंइए हर एक जीभ स्वीकार केरना कि यीशु मसीह ऐ प्रभु सा l","hōra paramēśavarē rī mahimā rī tēṁiē hara ēka jībha svīkāra kēranā ki yīśu masīha ai prabhu sā l",null],[2,12,"ऐबे ओ मेरे प्यारो, जेंडे तुस्से हमेशा हुक्म मन्दे आए सी, तेंडै ऐबे ना सिर्फ मेरे सामणै बल्कि ख़ास केरिया मेरे दूर हौंदे भी डोरदे होर कोम्दे आपणै-आपणै उध्दारा रै कौमा बे पुरा केरा l","aibē ō mērē pyārō, jēṁḍē tussē hamēśā hukma mandē āē sī, tēṁḍai aibē nā sirpha mērē sāmaṇai balki k͟hāsa kēriyā mērē dūra hauṁdē bhī ḍōradē hōra kōmdē āpaṇai-āpaṇai udhdārā rai kaumā bē purā kērā l",null],[2,13,"किबैकि परमेश्वर ऐ सा जूणीऐ आपणी शोभली इच्छा सेंघे तुस्सा रे मना न इच्छा होर कौम, दुई गला रे केरने रा प्रभाव भौरु सा l","kibaiki paramēśvara ai sā jūṇīai āpaṇī śōbhalī icchā sēṁghē tussā rē manā na icchā hōra kauma, duī galā rē kēranē rā prabhāva bhauru sā l",null],[2,14,"सेभ कौम बिना कुड़कुड़ाऐ होर बिना बहस केरीया केरै केरा l","sēbha kauma binā kuṛakuṛāai hōra binā bahasa kērīyā kērai kērā l",null],[2,15,"ताकि तुस्से निर्दोष होर भोले होइया टेड़े होर हठीले लोक मौन्झे परमेश्वरा री निष्कलंक सन्तान बणीया रोहा, (जूणी मौन्झे तुस्से जीवना रा वचन लेइया भौकदे दीउये बराबर ऐई संसारा ना हेरिया सी l","tāki tussē nirdōṣa hōra bhōlē hōiyā ṭēṛē hōra haṭhīlē lōka maunjhē paramēśvarā rī niṣkalaṁka santāna baṇīyā rōhā, (jūṇī maunjhē tussē jīvanā rā vacana lēiyā bhaukadē dīuyē barābara aiī saṁsārā nā hēriyā sī l",null],[2,16,"कि मसीह ऐणै रे धियाड़े ना मुम्बे घमण्ड केरने री बजह हो, कि ना मेरा दौड़ना होर ना मेरी मेहनत बेकार नौठा l","ki masīha aiṇai rē dhiyāṛē nā mumbē ghamaṇḍa kēranē rī bajaha hō, ki nā mērā dauṛanā hōra nā mērī mēhanata bēkāra nauṭhā l",null],[2,17,"होर अगर मुम्बे बशाह रे बलिदाना ना होर सेवा ना आपणा खून भी बहाणा पौड़ू ता तेबे भी हाँऊ खुश सा, होर तुसा सेभी सेंघे ख़ुशी मना सा l","hōra agara mumbē baśāha rē balidānā nā hōra sēvā nā āpaṇā khūna bhī bahāṇā pauṛū tā tēbē bhī hām̐ū khuśa sā, hōra tusā sēbhī sēṁghē k͟huśī manā sā l",null],[2,18,"होर तेंडै तुसे भी खुश रोहा, होर मुं सेंघे ख़ुशी मणात l","hōra tēṁḍai tusē bhī khuśa rōhā, hōra muṁ sēṁghē k͟huśī maṇāta l",null],[2,19,"मुम्बे प्रभु यीशु ना आश सा, कि हाँऊ तीमुथियुसा बे बडी छेके तुसा आगे भेजणु, ताकि तुसा रा हाल शुणीया मुम्बे शान्ति मिलली l","mumbē prabhu yīśu nā āśa sā, ki hām̐ū tīmuthiyusā bē baḍī chēkē tusā āgē bhējaṇu, tāki tusā rā hāla śuṇīyā mumbē śānti milalī l",null],[2,20,"किबैकि मुं आगे एन्डे स्वभावा रा कोई नी आथी, जूण शुद्ध मने तुसा री चिंता केरला l","kibaiki muṁ āgē ēnḍē svabhāvā rā kōī nī āthī, jūṇa śuddha manē tusā rī ciṁtā kēralā l",null],[2,21,"किबैकि सेभ आपणै स्वार्था री खोजा ना रोहा सी, ना कि यीशु मसीह री l","kibaiki sēbha āpaṇai svārthā rī khōjā nā rōhā sī, nā ki yīśu masīha rī l",null],[2,22,"पर सो ता तुसे प्रेखु होर जाणु सा, कि जेंडा बेटा बापु सेंघे केरा सा, तेंडा ऐ तेइए सुसमाचार बोंडणै ना मेरी मज्द केरी सा l","para sō tā tusē prēkhu hōra jāṇu sā, ki jēṁḍā bēṭā bāpu sēṁghē kērā sā, tēṁḍā ai tēiē susamācāra bōṁḍaṇai nā mērī majda kērī sā l",null],[2,23,"ऐबे मुम्बे बशाह सा, कि जेंडे मुम्बे पता लागला कि मेरी कि दशा सा, ता तेंडै मुं सो भेजणा l","aibē mumbē baśāha sā, ki jēṁḍē mumbē patā lāgalā ki mērī ki daśā sā, tā tēṁḍai muṁ sō bhējaṇā l",null],[2,24,"होर मुम्बे प्रभु ना बशाह सा, कि मुं आपु भी छेके ऐणा l","hōra mumbē prabhu nā baśāha sā, ki muṁ āpu bhī chēkē aiṇā l",null],[2,25,"पर मैं इपफ्रु दीतुस जूण मेरा भाई सा, होर सेंघी होर सेंघे रोह्णु आ होर तुसा रा दूत, होर जरूरी गल्ला मुं सेंघे रोह्णु आ सा, तुसा आगे भेजणा जरूरी सोचु l","para maiṁ ipaphru dītusa jūṇa mērā bhāī sā, hōra sēṁghī hōra sēṁghē rōhṇu ā hōra tusā rā dūta, hōra jarūrī gallā muṁ sēṁghē rōhṇu ā sā, tusā āgē bhējaṇā jarūrī sōcu l",null],[2,26,"किबैकि तेइरा मन तुसा सेभी ना लागा ती, तेबैता सो चिन्ता ना रोहा ती, किबैकि तुसे तेइरी बमारी रा हाल शुणु ती l","kibaiki tēirā mana tusā sēbhī nā lāgā tī, tēbaitā sō cintā nā rōhā tī, kibaiki tusē tēirī bamārī rā hāla śuṇu tī l",null],[2,27,"सो सचिये बिमार ता हुआ ती, ओखे तक कि मौरने पांधे ती, पर परमेश्वरे तेई पांधे दया केरी, होर सिर्फ तेई पांधे केले नेई, पर मुं पांधे भी, कि मुम्बे दुखा पांधे दुःख नी लोड़ी हुआ l","sō saciyē bimāra tā huā tī, ōkhē taka ki mauranē pāṁdhē tī, para paramēśvarē tēī pāṁdhē dayā kērī, hōra sirpha tēī pāṁdhē kēlē nēī, para muṁ pāṁdhē bhī, ki mumbē dukhā pāṁdhē duḥkha nī lōṛī huā l",null],[2,28,"तेबैता मैं तेई भेजणै री पूरी कोशिश केरी कि तुसे भी तेई सेंघे मिलिया ख़ुशी मना होर मेरा भी दुःख कम होलाl","tēbaitā maiṁ tēī bhējaṇai rī pūrī kōśiśa kērī ki tusē bhī tēī sēṁghē miliyā k͟huśī manā hōra mērā bhī duḥkha kama hōlāl",null],[2,29,"होर ऐबे तुसे तेई सेंघे प्रभु ना होईया बड़ी ख़ुशी सेंघे मिलित, होर एण्डै रा आदर केरिये केरा l","hōra aibē tusē tēī sēṁghē prabhu nā hōīyā baṛī k͟huśī sēṁghē milita, hōra ēṇḍai rā ādara kēriyē kērā l",null],[2,30,"किबैकि सो मसीह रे कौमा री तेंइए आपणै प्राण भी मुशकला ना पाइया मौरनु आ ती, ताकि जे कमी-घटी तुसारी तरफा ना मेरी सेवा ना हुई सा, तेसा कमी बे पूरी केरे l","kibaiki sō masīha rē kaumā rī tēṁiē āpaṇai prāṇa bhī muśakalā nā pāiyā mauranu ā tī, tāki jē kamī-ghaṭī tusārī taraphā nā mērī sēvā nā huī sā, tēsā kamī bē pūrī kērē l",null],[3,1,"निदान, ओ मेरे भाइयो, प्रभु ना खुश रोहा, सो ऐ गल्ला फिरि भी लिखणै ना मुम्बे ता कोई कष्ट नेई होन्दा, होर एता ना तुसा री भलाई सा l","nidāna, ō mērē bhāiyō, prabhu nā khuśa rōhā, sō ai gallā phiri bhī likhaṇai nā mumbē tā kōī kaṣṭa nēī hōndā, hōra ētā nā tusā rī bhalāī sā l",null],[3,2,"इन्हा कुते ना सावधान रोहा, तिन्हा बुरे कौम केरनु आए ना सावधान रोहा, तिन्हा लड़ाई झगड़ा केरणु आए ना सावधान रोहा l","inhā kutē nā sāvadhāna rōhā, tinhā burē kauma kēranu āē nā sāvadhāna rōhā, tinhā laṛāī jhagaṛā kēraṇu āē nā sāvadhāna rōhā l",null],[3,3,"किबैकि खतने आए ता आसे सी, जूण परमेश्वरे री आत्मा री अगुवाई ना उपासना केरा सी, होर मसीह यीशु पांधे घमण्ड केरा सी, होर शरीरा पांधे बशाह नेई रखदे l","kibaiki khatanē āē tā āsē sī, jūṇa paramēśvarē rī ātmā rī aguvāī nā upāsanā kērā sī, hōra masīha yīśu pāṁdhē ghamaṇḍa kērā sī, hōra śarīrā pāṁdhē baśāha nēī rakhadē l",null],[3,4,"पर हाँऊ ता शरीरा पांधे भी बशाह केरी सका सा, अगर कोई होरी बे भी शरीरा पांधे बशाह रखणै रा विचार सा, ता हाँऊ तेई ना भी जादा बशाह रखी सका सा l","para hām̐ū tā śarīrā pāṁdhē bhī baśāha kērī sakā sā, agara kōī hōrī bē bhī śarīrā pāṁdhē baśāha rakhaṇai rā vicāra sā, tā hām̐ū tēī nā bhī jādā baśāha rakhī sakā sā l",null],[3,5,"ओठुए रोज मेरा खतना हुआ, इसराईला रे वंश होर विन्यामिना रे गोत्रा रा सा, इब्रानी रा इब्रानी सा, व्यवस्था रे बारे ना बोला ता हाँऊ फरीसी सा l","ōṭhuē rōja mērā khatanā huā, isarāīlā rē vaṁśa hōra vinyāminā rē gōtrā rā sā, ibrānī rā ibrānī sā, vyavasthā rē bārē nā bōlā tā hām̐ū pharīsī sā l",null],[3,6,"जोशा रे बारे ना बोला ता कलीसिया बे दुःख देणु आ, होर व्यवस्था री धार्मिकता ना बोला ता निर्दोष ती l","jōśā rē bārē nā bōlā tā kalīsiyā bē duḥkha dēṇu ā, hōra vyavasthā rī dhārmikatā nā bōlā tā nirdōṣa tī l",null],[3,7,"पर जूण-जूण गल्ला मेरे फ़ायदे री ती, सो ऐ मैं मसीह री बजह ना नुक्सान देणु आई बुझी l","para jūṇa-jūṇa gallā mērē fāyadē rī tī, sō ai maiṁ masīha rī bajaha nā nuksāna dēṇu āī bujhī l",null],[3,8,"बल्कि हाँऊ आपणै प्र्र्भु यीशु री ज्ञाने री उतमता री बजह ना सेभी गल्ला बे बेकार बुझा सा, जूणी री बजह ना मैं सेभी गल्ला ना नुकसान चकु, होर तिन्हा गल्ला बे कूड़ा बुझा सा, जूणी री बजह ना हाँऊ मसीह बे प्राप्त केरणु l","balki hām̐ū āpaṇai prrbhu yīśu rī jñānē rī utamatā rī bajaha nā sēbhī gallā bē bēkāra bujhā sā, jūṇī rī bajaha nā maiṁ sēbhī gallā nā nukasāna caku, hōra tinhā gallā bē kūṛā bujhā sā, jūṇī rī bajaha nā hām̐ū masīha bē prāpta kēraṇu l",null],[3,9,"होर तेई ना बणीया रोहणु, ना कि आपणी तेसा धार्मिकता सेंघे, जूण व्यवस्था ना सा, बल्कि तेसा धर्मिकता सेंघे जूण मसीह ना बशाह केरने री बजह ना सा, होर परमेश्वरा पांधे बशाह केरने री बजह ना मिला सा l","hōra tēī nā baṇīyā rōhaṇu, nā ki āpaṇī tēsā dhārmikatā sēṁghē, jūṇa vyavasthā nā sā, balki tēsā dharmikatā sēṁghē jūṇa masīha nā baśāha kēranē rī bajaha nā sā, hōra paramēśvarā pāṁdhē baśāha kēranē rī bajaha nā milā sā l",null],[3,10,"होर हाँऊ तेइबे होर तेई री मृत्युंजय री सामर्था बे, होर तेई सेंघे दुःखा ना सहभागी होणै री तकलिफा बे जाणनु, होर तेइरी मौती री समानता बे प्राप्त केरणु l","hōra hām̐ū tēibē hōra tēī rī mr̥tyuṁjaya rī sāmarthā bē, hōra tēī sēṁghē duḥkhā nā sahabhāgī hōṇai rī takaliphā bē jāṇanu, hōra tēirī mautī rī samānatā bē prāpta kēraṇu l",null],[3,11,"ताकि हाँऊ कोई भी तरीके ना मुंऐदें न जिन्दे होणे री जगह तकर पूजणु l","tāki hām̐ū kōī bhī tarīkē nā muṁaidēṁ na jindē hōṇē rī jagaha takara pūjaṇu l",null],[3,12,"ऐ मतलब नेई, कि मुम्बे मिलु, या सिद्ध हुआ सा, पर तेसा चिजा बे ढोकणै री तेंइए दौड्दा लागा सा, जूणी री तेंइए मसीह यीशुऐ हाँऊ ढोकू ती l","ai matalaba nēī, ki mumbē milu, yā siddha huā sā, para tēsā cijā bē ḍhōkaṇai rī tēṁiē dauḍdā lāgā sā, jūṇī rī tēṁiē masīha yīśuai hām̐ū ḍhōkū tī l",null],[3,13,"ओ भाइयो, मेरी इच्छा ऐ नेई कि मैं ढोकू, सिर्फ एक ऐ कौम केरा सा, कि जूण गल्ला पीछे बिती, तिन्हा बे छौड़िया, आगली गल्ला धीरे बढ़िया,","ō bhāiyō, mērī icchā ai nēī ki maiṁ ḍhōkū, sirpha ēka ai kauma kērā sā, ki jūṇa gallā pīchē bitī, tinhā bē chauṛiyā, āgalī gallā dhīrē baṛhiyā,",null],[3,14,"नशाणै धिरे बे दौड़ लानू, ताकि सो ईनाम पानु, जूण री तेंइए परमेशवरे हाँऊ मसीह यीशु ना झाँऊ शादू सा l","naśāṇai dhirē bē dauṛa lānū, tāki sō īnāma pānu, jūṇa rī tēṁiē paramēśavarē hām̐ū masīha yīśu nā jhām̐ū śādū sā l",null],[3,15,"तैबै आसा मौन्झे जेतरे शुद्ध सी, ऐ विचार रखे, होर आगर कोई गल्ला ना तुसा रा कोई होर विचार होला, ता परमेश्वरा सो भी तुसा पांधे प्रगट केरना l","taibai āsā maunjhē jētarē śuddha sī, ai vicāra rakhē, hōra āgara kōī gallā nā tusā rā kōī hōra vicāra hōlā, tā paramēśvarā sō bhī tusā pāṁdhē pragaṭa kēranā l",null],[3,16,"ऐबे जोखे तकर आसे पूजे सी, एता अनुसार होण्डदे रोहले l","aibē jōkhē takara āsē pūjē sī, ētā anusāra hōṇḍadē rōhalē l",null],[3,17,"ओ भाइयो, तुसे सेभ मिलिया मुं सेंई चाल चला, होर तिन्हा बे पछियाणीया रखा, जूण एण्डी रीती पांधे चला सी जूणी रा उदाहरण तुसे आसा न हेरा सी l","ō bhāiyō, tusē sēbha miliyā muṁ sēṁī cāla calā, hōra tinhā bē pachiyāṇīyā rakhā, jūṇa ēṇḍī rītī pāṁdhē calā sī jūṇī rā udāharaṇa tusē āsā na hērā sī l",null],[3,18,"किबैकि बोहु लोका एंडी चाल चला सी, जूणी री चर्चा मैं तुसा सेंघे घड़ी-घड़ी केरी सा, हाज़ी भी रौई-रौइया बोला सा, कि ते आपणी चाल-चलना ना मसीह रे दुश्मन सी l","kibaiki bōhu lōkā ēṁḍī cāla calā sī, jūṇī rī carcā maiṁ tusā sēṁghē ghaṛī-ghaṛī kērī sā, hāzī bhī rauī-rauiyā bōlā sā, ki tē āpaṇī cāla-calanā nā masīha rē duśmana sī l",null],[3,19,"तिन्हा रा अंत विनाश सा, तिन्हा रा ईश्वर पेट सा, ते आपणी शर्मा री गल्ला पांधे घमण्ड केरा सी, होर एसा धौरती री चिजा पांधे मन लाईया रखा सी l","tinhā rā aṁta vināśa sā, tinhā rā īśvara pēṭa sā, tē āpaṇī śarmā rī gallā pāṁdhē ghamaṇḍa kērā sī, hōra ēsā dhauratī rī cijā pāṁdhē mana lāīyā rakhā sī l",null],[3,20,"पर आसा रा देश ता स्वर्गा ना सा, होर आसे प्रभु यीशु रे स्वर्गा ना ऐणै री बाट जोहा सी l","para āsā rā dēśa tā svargā nā sā, hōra āsē prabhu yīśu rē svargā nā aiṇai rī bāṭa jōhā sī l",null],[3,21,"तेई आपणी शक्ति रे तेई प्रभावा री बजह ना जूणी री बजह ना सो सारी चिजा बे आपणै वशा ना केरी सका सा, आसा रे दीन-हिन शरीरा रा रूप बदलिया आपणी महिमा रे शरीरा रे अनुकूल बणाई देला l","tēī āpaṇī śakti rē tēī prabhāvā rī bajaha nā jūṇī rī bajaha nā sō sārī cijā bē āpaṇai vaśā nā kērī sakā sā, āsā rē dīna-hina śarīrā rā rūpa badaliyā āpaṇī mahimā rē śarīrā rē anukūla baṇāī dēlā l",null],[4,1,"तेबे ता ओ मेरे प्यारे भाइयो, जूणी लोका ना मेरा जिऊ लागी रोहा सा जूण मेरी ख़ुशी होर मेरे मुक्ट सी, ओ मेरे प्यारे भाइयो, प्रभु ना एण्डी तरहे बणीया रोहा l","tēbē tā ō mērē pyārē bhāiyō, jūṇī lōkā nā mērā jiū lāgī rōhā sā jūṇa mērī k͟huśī hōra mērē mukṭa sī, ō mērē pyārē bhāiyō, prabhu nā ēṇḍī tarahē baṇīyā rōhā l",null],[4,2,"हाँऊ युओदिया बे भी समझा सा, सुन्तुखे बे भी, कि प्रभु ना एक मन रोहा l","hām̐ū yuōdiyā bē bhī samajhā sā, suntukhē bē bhī, ki prabhu nā ēka mana rōhā l",null],[4,3,"होर हे सच्चे सेंघी, हाँऊ तो ना प्रार्थना केरा सा, कि तू तिन्हा बेटड़ी री मजद केर, किबैकि इन्हें मुं सेंघे सुसमाचार फेलाणै ना, क्लेमेंस होर मेरे तिन्ह सेंघी सेंघे मेहनत केरी सा, जूणी रे नाँ जीवने री कताबा ना लिखे सी l","hōra hē saccē sēṁghī, hām̐ū tō nā prārthanā kērā sā, ki tū tinhā bēṭaṛī rī majada kēra, kibaiki inhēṁ muṁ sēṁghē susamācāra phēlāṇai nā, klēmēṁsa hōra mērē tinha sēṁghī sēṁghē mēhanata kērī sā, jūṇī rē nām̐ jīvanē rī katābā nā likhē sī l",null],[4,4,"प्रभु ना हमेशा खुश रोहा, हाँऊ भी बोला सा खुश रोहा l","prabhu nā hamēśā khuśa rōhā, hām̐ū bhī bōlā sā khuśa rōhā l",null],[4,5,"तुसे री कोमलता सेभी माँणहु पांधे प्रगट हो, प्रभु नेड़े सा l","tusē rī kōmalatā sēbhī mām̐ṇahu pāṁdhē pragaṭa hō, prabhu nēṛē sā l",null],[4,6,"कोई भी गला री फिकर मता केरदे, पर हर गल्ला न तुसा रे निवेदन, प्रार्थना होर विनती री बजह ना धन्यवाद सेंघे परमेश्वरा सामणै उपस्थित केरी लोड़ी l","kōī bhī galā rī phikara matā kēradē, para hara gallā na tusā rē nivēdana, prārthanā hōra vinatī rī bajaha nā dhanyavāda sēṁghē paramēśvarā sāmaṇai upasthita kērī lōṛī l",null],[4,7,"तेबे परमेशवरे री शान्ति जूण समझा ना बाहरे सा, तुसा रे दिला ना होर तुसा रे विचारा बे मसीह यीशु ना सुरक्षित रखली l","tēbē paramēśavarē rī śānti jūṇa samajhā nā bāharē sā, tusā rē dilā nā hōra tusā rē vicārā bē masīha yīśu nā surakṣita rakhalī l",null],[4,8,"निदान ओ भाइयो, जूण-जूण गल्ला सच्ची, होर जूण-जूण गल्ला आदरारे योग्या सा, होर जे-जे गल्ला उचित सी, होर जे-जे गल्ला पवित्र सी, होर जे-जे गल्ला सुहावनी सी, होर जे- जे गल्ला सुहावनी सा, होर जे-जे गल्ला मना बे शोभली लगा सी, होर जूण सद्गुण होर प्रशंसा री गल्ला सी, सिर्फ तिन्हा पान्धे ध्यान देआ केरा l","nidāna ō bhāiyō, jūṇa-jūṇa gallā saccī, hōra jūṇa-jūṇa gallā ādarārē yōgyā sā, hōra jē-jē gallā ucita sī, hōra jē-jē gallā pavitra sī, hōra jē-jē gallā suhāvanī sī, hōra jē- jē gallā suhāvanī sā, hōra jē-jē gallā manā bē śōbhalī lagā sī, hōra jūṇa sadguṇa hōra praśaṁsā rī gallā sī, sirpha tinhā pāndhē dhyāna dēā kērā l",null],[4,9,"जूण गल्ला तुसे मुं ना सीखी, होर ग्रहण केरी सा, होर शुणी, होर मुं ना हेरि सा, तिन्हा रा पालन केरै केरा, तेबे परमेश्वरा जूण शान्ति रा सोता सा, तेई तुसा सेंघे रोहणा l","jūṇa gallā tusē muṁ nā sīkhī, hōra grahaṇa kērī sā, hōra śuṇī, hōra muṁ nā hēri sā, tinhā rā pālana kērai kērā, tēbē paramēśvarā jūṇa śānti rā sōtā sā, tēī tusā sēṁghē rōhaṇā l",null],[4,10,"हाँऊ प्रभु ना बड़ा खुश सा कि तुसा रा विचार मेरे बारे ना एतरे रोज़ा बाद भी बदलुआ सा, तुसा बे पक्का पहले भी ऐ विचार ती, पर तुसा बे मौका नेई मिलु l","hām̐ū prabhu nā baṛā khuśa sā ki tusā rā vicāra mērē bārē nā ētarē rōzā bāda bhī badaluā sā, tusā bē pakkā pahalē bhī ai vicāra tī, para tusā bē maukā nēī milu l",null],[4,11,"ऐ नेई कि हाँऊ आपणी कमी री बजह ना ऐ बोला सा, किबैकि मैं ऐ सिखु सा कि जूणी दशा ना सा, होर एता ना संतोष केरा सा l","ai nēī ki hām̐ū āpaṇī kamī rī bajaha nā ai bōlā sā, kibaiki maiṁ ai sikhu sā ki jūṇī daśā nā sā, hōra ētā nā saṁtōṣa kērā sā l",null],[4,12,"हाँऊ दीन होणा भी जाणा सा, होर बढ़ना भी जाणा सा, हर गल्ला ना होर हर दशा ना मैं रोजणा, भूखे रोहणा, होर बढ़ना-घटणा सिखु सा l","hām̐ū dīna hōṇā bhī jāṇā sā, hōra baṛhanā bhī jāṇā sā, hara gallā nā hōra hara daśā nā maiṁ rōjaṇā, bhūkhē rōhaṇā, hōra baṛhanā-ghaṭaṇā sikhu sā l",null],[4,13,"जूण मुम्बे सेभी गल्ला ना सामर्थ देआ सा, तेई ना हाँऊ सेभ किच्छ केरी सका सा l","jūṇa mumbē sēbhī gallā nā sāmartha dēā sā, tēī nā hām̐ū sēbha kiccha kērī sakā sā l",null],[4,14,"तेबे भी तुसे भला केरू, कि मेरे दुखा ना मेरे सेंघी बणैl","tēbē bhī tusē bhalā kērū, ki mērē dukhā nā mērē sēṁghī baṇail",null],[4,15,"होर ओ फिलिप्पियो, तुसा बे आपु भी पता सा कि सुस्माचारा रे शुरुआता ना जेबे हाँऊ मकिदुनिया ना नौठा ता तेबे तुसा","hōra ō philippiyō, tusā bē āpu bhī patā sā ki susmācārā rē śuruātā nā jēbē hām̐ū makiduniyā nā nauṭhā tā tēbē tusā",null],[4,16,"एण्ढी तरहे जेबे हाँऊ थिस्सलुनिके ना ती, तेबे भी तुसे एकी बार नेई बल्कि दुई बारी मुम्बे किच्छ भेजू ती","ēṇḍhī tarahē jēbē hām̐ū thissalunikē nā tī, tēbē bhī tusē ēkī bāra nēī balki duī bārī mumbē kiccha bhējū tī",null],[4,17,"ऐ नेई कि हाँऊ दान चाह सा, पर हाँऊ एक एण्डा फ़ोळ चाह सा, जूण तुसा रे फ़ायदे री तेंइए बढ़दा रोहे l","ai nēī ki hām̐ū dāna cāha sā, para hām̐ū ēka ēṇḍā fōḷa cāha sā, jūṇa tusā rē fāyadē rī tēṁiē baṛhadā rōhē l",null],[4,18,"मुं आगे सेभ किच्छ सा, जूण चिजा तुसे इपफ्रुदितुसा रे हौथा ना भेजी ती, तिन्हा बे पाइया हाँऊ तृप्त हुआ, सो ता सुगंध होर ग्रहण केरन योग्या बलिदान सा, जूण परमेश्वरा बे शोभला लागा सा","muṁ āgē sēbha kiccha sā, jūṇa cijā tusē ipaphruditusā rē hauthā nā bhējī tī, tinhā bē pāiyā hām̐ū tr̥pta huā, sō tā sugaṁdha hōra grahaṇa kērana yōgyā balidāna sā, jūṇa paramēśvarā bē śōbhalā lāgā sā",null],[4,19,"होर मेरा परमेश्वर भी आपणै तेई धना रे अनुसार जूण मसीह यीशु ना सा, तुसा री हर घटी कमी बे पुरा केरला l","hōra mērā paramēśvara bhī āpaṇai tēī dhanā rē anusāra jūṇa masīha yīśu nā sā, tusā rī hara ghaṭī kamī bē purā kēralā l",null],[4,20,"आसा रे बापू होर परमेशवरे री महिमा हमेशा होंदी रोहेl आमीन l","āsā rē bāpū hōra paramēśavarē rī mahimā hamēśā hōṁdī rōhēl āmīna l",null],[4,21,"हर पवित्र माँणहु बे जूण मसीह यीशु ना सा, नमस्ते बोला, जूणा भाई लोका मुं सेंघे सी तिन्हे भी नमस्ते लाई सा l","hara pavitra mām̐ṇahu bē jūṇa masīha yīśu nā sā, namastē bōlā, jūṇā bhāī lōkā muṁ sēṁghē sī tinhē bhī namastē lāī sā l",null],[4,22,"सेभ पवित्र लोका जूण केसरे रे घराने रे सी, तुसा सेभी बे नमस्ते बोला सी l","sēbha pavitra lōkā jūṇa kēsarē rē gharānē rē sī, tusā sēbhī bē namastē bōlā sī l",null],[4,23,"आसा रे प्रभु यीशु रा अनुग्रह तुसा री आत्मा ना होन्दा रोहे l","āsā rē prabhu yīśu rā anugraha tusā rī ātmā nā hōndā rōhē l",null]],"kfx-outer":[[1,1,"मसीह यीशूए दास पौलुस और तीमुथियुसे तरफा का सोभी पबित्र लोगे नांओंऐं ज़ुंण मसीह यीशू दी फिलिप्पि देशा दी रहा, मुखिऐ और सेबका संघी लोळी,","masīha yīśūē dāsa paulusa aura tīmuthiyusē taraphā kā sōbhī pabitra lōgē nāṁōṁaiṁ zuṁṇa masīha yīśū dī philippi dēśā dī rahā, mukhiai aura sēbakā saṁghī lōḷī,",null],[1,2,"म्हारै पिता परमेश्वर और प्रभू यीशू मसीहे तरफा का तम्हां लै अनुग्रह, शांती हंदी रही।","mhārai pitā paramēśvara aura prabhū yīśū masīhē taraphā kā tamhāṁ lai anugraha, śāṁtī haṁdī rahī.",null],[1,3,"ज़ेभै-ज़ेभै हूँ तम्हां आद करा, तेभै-तेभै करा हूँ तम्हां लै परमेश्वरो धन्यबाद।","zēbhai-zēbhai hūm̐ tamhāṁ āda karā, tēbhai-tēbhai karā hūm̐ tamhāṁ lai paramēśvarō dhanyabāda.",null],[1,4,"और ज़ेभै बी तम्हां लै हूँ प्राथणां बिनती करा, ता हूँ करा हर बगत आनंद और खुशी संघै एही अरज़","aura zēbhai bī tamhāṁ lai hūm̐ prāthaṇāṁ binatī karā, tā hūm̐ karā hara bagata ānaṁda aura khuśī saṁghai ēhī araza",null],[1,5,"कि तम्हैं आसा पैहलै ओर्ही आझ़़ तैणीं सुसमाच़ारा फैलाऊंणा लै मूंह संघै मेरै सैहभागी।","ki tamhaiṁ āsā paihalai ōrhī ājḧä taiṇīṁ susamāc̈ārā phailāūṁṇā lai mūṁha saṁghai mērai saihabhāgī.",null],[1,6,"और मूँह आसा एसा गल्लो भरोसअ कि ज़ुंणीं तम्हां दी बधिया काम करनअ शुरू किय, तेऊई करनअ सह यीशूमसीहे धैळी तैणीं पूरअ।","aura mūm̐ha āsā ēsā gallō bharōsaa ki zuṁṇīṁ tamhāṁ dī badhiyā kāma karanaa śurū kiya, tēūī karanaa saha yīśūmasīhē dhaiḷī taiṇīṁ pūraa.",null],[1,7,"ठीक आसा कि हूँ तम्हां लै इहय बच़ार करूँ, किल्हैकि तम्हैं आसा मेरै मनै बस्सै दै और मेरी कैदा दी और सुसमाच़ारा लै ज़बाब और प्रमांण दैणा लै मूँह संघै अनुग्रहा दी सैहभागी।","ṭhīka āsā ki hūm̐ tamhāṁ lai ihaya bac̈āra karūm̐, kilhaiki tamhaiṁ āsā mērai manai bassai dai aura mērī kaidā dī aura susamāc̈ārā lai zabāba aura pramāṁṇa daiṇā lai mūm̐ha saṁghai anugrahā dī saihabhāgī.",null],[1,8,"एता दी आसा परमेश्वर मेरअ गुआह कि हूँ मसीह यीशू ज़िहअ प्यार करी करै करा थारी लालसा।","ētā dī āsā paramēśvara mēraa guāha ki hūm̐ masīha yīśū zihaa pyāra karī karai karā thārī lālasā.",null],[1,9,"और हूँ करा एही प्राथणां कि थारअ प्रेंम और ज्ञान और सोभी प्रकारे बिबेका संघी होर बी बढदअ लागे।","aura hūm̐ karā ēhī prāthaṇāṁ ki thāraa prēṁma aura jñāna aura sōbhī prakārē bibēkā saṁghī hōra bī baḍhadaa lāgē.",null],[1,10,"इधी तैणीं कि तम्हैं उत्तम से उत्तम गल्ला प्यारी ज़ाणें, और मसीहे धैळी तैणीं रहै सच्च़ै बणीं, और तम्हैं कधि ठोह्ळ नां खाए।","idhī taiṇīṁ ki tamhaiṁ uttama sē uttama gallā pyārī zāṇēṁ, aura masīhē dhaiḷī taiṇīṁ rahai sacc̈ai baṇīṁ, aura tamhaiṁ kadhi ṭhōhḷa nāṁ khāē.",null],[1,11,"और तेऊ धार्मिकते फळा करै ज़ुंण प्रभू यीशू मसीह करै ह्आ, तेता करै ह्आ भरपूर, ज़ेता करै परमेश्वरे महिमां और स्तुति हंदी रहे।","aura tēū dhārmikatē phaḷā karai zuṁṇa prabhū yīśū masīha karai hā, tētā karai hā bharapūra, zētā karai paramēśvarē mahimāṁ aura stuti haṁdī rahē.",null],[1,12,"हे भाईयो, हूँ च़ाहा इहय कि तम्हां का लोळी थोघ लागअ कि मुल्है ज़ुंण बितअ, तेता करै हुई सुसमाच़ारे ही बढोतरी।","hē bhāīyō, hūm̐ c̈āhā ihaya ki tamhāṁ kā lōḷī thōgha lāgaa ki mulhai zuṁṇa bitaa, tētā karai huī susamāc̈ārē hī baḍhōtarī.",null],[1,13,"इधी तैणीं कि कैसरे राईसीए सारी पळटण और बाकी सोभी लोगा दी ग्अ अह प्रगट ह्ई कि हूँ आसा मसीहे तैणीं कैद।","idhī taiṇīṁ ki kaisarē rāīsīē sārī paḷaṭaṇa aura bākī sōbhī lōgā dī ga aha pragaṭa hī ki hūm̐ āsā masīhē taiṇīṁ kaida.",null],[1,14,"और प्रभू दी ज़ुंण भाई आसा, तिन्नां मांझ़ै बडै भारी मेरै कैद हणें कारण, हिम्मत बाह्नी करै नधड़क परमेश्वरे बच़ना शणांऊंणें हिम्मत करा।","aura prabhū dī zuṁṇa bhāī āsā, tinnāṁ māṁjḧai baḍai bhārī mērai kaida haṇēṁ kāraṇa, himmata bāhnī karai nadhaṛaka paramēśvarē bac̈anā śaṇāṁūṁṇēṁ himmata karā.",null],[1,15,"कई लोग ता करा डाह और झ़गळे बज़ह मसीहो प्रच़ार और कई करा भली मनसा दी।","kaī lōga tā karā ḍāha aura jḧagaḷē bazaha masīhō prac̈āra aura kaī karā bhalī manasā dī.",null],[1,16,"कई ता इहय ज़ाणीं करै कि हूँ आसा सुसमाच़ारा लै ज़बाबा दैणां लै डाहअ द, तिंयां करा बडै प्रेंमा संघै प्रच़ार।","kaī tā ihaya zāṇīṁ karai ki hūm̐ āsā susamāc̈ārā lai zabābā daiṇāṁ lai ḍāhaa da, tiṁyāṁ karā baḍai prēṁmā saṁghai prac̈āra.",null],[1,17,"पर कई ता ईहै बी आसा ज़ुंण सिधै मनैं ता नांईंं पर बिरोध करी करै शणांऊंआ मसीहे कथैया, इहय सोच़ी करै कि मेरी कैदा दी तिंयांं मुल्है क्लेश पैदा करे।","para kaī tā īhai bī āsā zuṁṇa sidhai manaiṁ tā nāṁīṁṁ para birōdha karī karai śaṇāṁūṁā masīhē kathaiyā, ihaya sōc̈ī karai ki mērī kaidā dī tiṁyāṁṁ mulhai klēśa paidā karē.",null],[1,18,"तै किज़ै हुअ? सिधअ इहय कि, हर प्रकारै, च़ाहे सह किज़ू भानै दी होए, च़ाहे सच्च़ाई दी, मसीहे कथैआ आसा शणांऊंदै लागै दै, और हूँ ह्आ एता करै खुश, और मूँह खुश रहणअ बी।","tai kizai hua? sidhaa ihaya ki, hara prakārai, c̈āhē saha kizū bhānai dī hōē, c̈āhē sacc̈āī dī, masīhē kathaiā āsā śaṇāṁūṁdai lāgai dai, aura hūm̐ hā ētā karai khuśa, aura mūm̐ha khuśa rahaṇaa bī.",null],[1,19,"किल्हैकि मुखा आसा थोघ कि, थारी प्राथणां बिनती करै और प्रभू यीशू मसीहे आत्में दाना करै हणअ एतो प्रतिफल मेरअ उद्धार ई।","kilhaiki mukhā āsā thōgha ki, thārī prāthaṇāṁ binatī karai aura prabhū yīśū masīhē ātmēṁ dānā karai haṇaa ētō pratiphala mēraa uddhāra ī.",null],[1,20,"हूँ डाहा दिला का एही लालसा और आशा कि हूँ किछ़ी गल्ला लै शरमिंदअ नां होए, पर ज़ेही मंऐं प्रबल साहस डाही करै हमेशा मेरी देही करै मसीहे बड़ाई हंदी रही, तेही ई ऐबै बी, च़ाहे हूँ जिंऊंदअ रहूँ या मरूँ।","hūm̐ ḍāhā dilā kā ēhī lālasā aura āśā ki hūm̐ kicḧī gallā lai śaramiṁdaa nāṁ hōē, para zēhī maṁaiṁ prabala sāhasa ḍāhī karai hamēśā mērī dēhī karai masīhē baṛāī haṁdī rahī, tēhī ī aibai bī, c̈āhē hūm̐ jiṁūṁdaa rahūm̐ yā marūm̐.",null],[1,21,"किल्हैकि मुल्है आसा ज़िऊंदअ रहणअ मसीह और मरनअ आसा मुल्है नफअ।","kilhaiki mulhai āsā ziūṁdaa rahaṇaa masīha aura maranaa āsā mulhai naphaa.",null],[1,22,"पर ज़ै शरीरा दी ज़िऊंदै रहणअ ई मेरै कामां लै लाभकारी आसा, तै निं मुखा पतअ कि हूँ किज़ै च़ुनू।","para zai śarīrā dī ziūṁdai rahaṇaa ī mērai kāmāṁ lai lābhakārī āsā, tai niṁ mukhā pataa ki hūm̐ kizai c̈unū.",null],[1,23,"किल्हैकि हूँ आसा दुही बिच़ै आधा-आधी लटकअ द, ज़िऊ ता च़ाहा इहय कि एऊ संसारा छ़ाडी मसीहा सेटा लै नाशूं, किल्हैकि सह आसा शोभलअ।","kilhaiki hūm̐ āsā duhī bic̈ai ādhā-ādhī laṭakaa da, ziū tā c̈āhā ihaya ki ēū saṁsārā cḧāḍī masīhā sēṭā lai nāśūṁ, kilhaiki saha āsā śōbhalaa.",null],[1,24,"पर शरीरा दी रहणअ आसा थारी तैणीं होर बी ज़रूरी।","para śarīrā dī rahaṇaa āsā thārī taiṇīṁ hōra bī zarūrī.",null],[1,25,"मूँह आसा एसा गल्लो भरोसअ, और मुखा एसा गल्लो थोघ बी आसा कि हूँ रहणअ ज़िऊंदअ, और रहणअ बी तम्हांई संघै, ज़ेता करै तम्हैं विश्वासा दी मज़बूत होए और तेताई दी खुश रहे।","mūm̐ha āsā ēsā gallō bharōsaa, aura mukhā ēsā gallō thōgha bī āsā ki hūm̐ rahaṇaa ziūṁdaa, aura rahaṇaa bī tamhāṁī saṁghai, zētā karai tamhaiṁ viśvāsā dī mazabūta hōē aura tētāī dī khuśa rahē.",null],[1,26,"और ज़ुंण घमंड तम्हैं मेरै बारै करा, सह लोळी मेरै तम्हां सेटा लै भी एछणैं करै बढअ।","aura zuṁṇa ghamaṁḍa tamhaiṁ mērai bārai karā, saha lōḷī mērai tamhāṁ sēṭā lai bhī ēchaṇaiṁ karai baḍhaa.",null],[1,27,"सिधअ एतरअ करा कि थारअ च़ाल च़लण लोळी मसीहे सुसमाच़ारा जोगी हुअ, च़ाहे हूँ तम्हां सेटा एछी करै भाळूं, च़ाहे नां बी एछूं, पर थारै बारै लोळी मूँह इहय शुळणां लै भेटअ कि तम्हैं आसा एकी आत्मा दी स्थिर, और एक मन ह्ई करै सुसमाच़ारे विश्वासा लै आसा मैन्था करदै लागै दै।","sidhaa ētaraa karā ki thāraa c̈āla c̈alaṇa lōḷī masīhē susamāc̈ārā jōgī hua, c̈āhē hūm̐ tamhāṁ sēṭā ēchī karai bhāḷūṁ, c̈āhē nāṁ bī ēchūṁ, para thārai bārai lōḷī mūm̐ha ihaya śuḷaṇāṁ lai bhēṭaa ki tamhaiṁ āsā ēkī ātmā dī sthira, aura ēka mana hī karai susamāc̈ārē viśvāsā lai āsā mainthā karadai lāgai dai.",null],[1,28,"और किछ़ी गल्ला लै निं बिरोधी का डरदै? और अह आसा तिन्नां लै बिनाशो च़िन्ह। पर तम्हां लै आसा उद्धार, और अह आसा परमेश्वरे तरफा का।","aura kicḧī gallā lai niṁ birōdhī kā ḍaradai? aura aha āsā tinnāṁ lai bināśō c̈inha. para tamhāṁ lai āsā uddhāra, aura aha āsā paramēśvarē taraphā kā.",null],[1,29,"किल्हैकि मसीहे कारण आसा तम्हां लै इहय अनुग्रह हुअ द कि नां सिधअ तेऊ दी विश्वास करा, पर तेऊ लै च़का दुख बी","kilhaiki masīhē kāraṇa āsā tamhāṁ lai ihaya anugraha hua da ki nāṁ sidhaa tēū dī viśvāsa karā, para tēū lai c̈akā dukha bī",null],[1,30,"और तम्हां आसा तेही मैंन्थ बी करना लै, ज़िहअ तम्हैं हूँ करदअ भाळअ, और ऐबै बी शुंणा कि हूँ करा तिहअई।","aura tamhāṁ āsā tēhī maiṁntha bī karanā lai, zihaa tamhaiṁ hūm̐ karadaa bhāḷaa, aura aibai bī śuṁṇā ki hūm̐ karā tihaaī.",null],[2,1,"तै ऐबै, ज़ै मसीह दी धख शांती, प्रेंम ढाढस और आत्मां दी सैहभागिता, करूणा और दैया आसा,","tai aibai, zai masīha dī dhakha śāṁtī, prēṁma ḍhāḍhasa aura ātmāṁ dī saihabhāgitā, karūṇā aura daiyā āsā,",null],[2,2,"तै करा मेरी एसा खुशी पूरी कि एक मन रहा और एकैई प्रेंम, एक च़ित, और एक ही मनसा डाहा।","tai karā mērī ēsā khuśī pūrī ki ēka mana rahā aura ēkaiī prēṁma, ēka c̈ita, aura ēka hī manasā ḍāhā.",null],[2,3,"बिरोध और झ़ुठी बड़ाई लै निं किछ़ै करा पर दीन मनै एकी दुजै समझ़ा आप्पू का बधिया।","birōdha aura jḧuṭhī baṛāī lai niṁ kicḧai karā para dīna manai ēkī dujai samajḧā āppū kā badhiyā.",null],[2,4,"हेरेक ज़ह्णअ निं सिधै आपणैं फाईदे पर दुजेए फाईदे बी करा चिंता।","hērēka zahṇaa niṁ sidhai āpaṇaiṁ phāīdē para dujēē phāīdē bī karā ciṁtā.",null],[2,5,"ज़िहअ मसीहो स्वभाव त, तिहअई लोळी थारअ स्वभाव बी हुअ।","zihaa masīhō svabhāva ta, tihaaī lōḷī thāraa svabhāva bī hua.",null],[2,6,"ज़ुंणीं परमेश्वरे स्वरूपा दी ह्ई करै बी परेश्बरा ज़िहअ हणअ निं आपणैं बशा दी डाहणैं च़ीज समझ़ी।","zuṁṇīṁ paramēśvarē svarūpā dī hī karai bī parēśbarā zihaa haṇaa niṁ āpaṇaiṁ baśā dī ḍāhaṇaiṁ c̈īja samajḧī.",null],[2,7,"पर आपणैं आप हुअ इहय शुन्य कि दासो रूप किय धारण और आप्पू बणअ आंम माह्णूं ज़िहअ।","para āpaṇaiṁ āpa hua ihaya śunya ki dāsō rūpa kiya dhāraṇa aura āppū baṇaa āṁma māhṇūṁ zihaa.",null],[2,8,"और माह्णूंए रूपै प्रगट ह्ई करै हुअ दीन, और ईधी तैणीं आज्ञाकारी रहअ कि मौत, हां, क्रूसे मौत बी की सैहन।","aura māhṇūṁē rūpai pragaṭa hī karai hua dīna, aura īdhī taiṇīṁ ājñākārī rahaa ki mauta, hāṁ, krūsē mauta bī kī saihana.",null],[2,9,"तैहीता परमेश्वरै सह सोभी का महान किय, और तेऊ लै दैनअ अह नांअ ज़ुंण सोभी नांओंआ का श्रेष्ठ आसा।","taihītā paramēśvarai saha sōbhī kā mahāna kiya, aura tēū lai dainaa aha nāṁa zuṁṇa sōbhī nāṁōṁā kā śrēṣṭha āsā.",null],[2,10,"कि ज़ुंण स्बर्गै और पृथूई दी और ज़ुंण पृथूई हेठै आसा, तिंयांं सोभै प्रभू यीशूए नांओंऐ ज़ाह्नू टेके।","ki zuṁṇa sbargai aura pr̥thūī dī aura zuṁṇa pr̥thūī hēṭhai āsā, tiṁyāṁṁ sōbhai prabhū yīśūē nāṁōṁai zāhnū ṭēkē.",null],[2,11,"और पिता परमेश्वरे महिमा लै हरेक ज़िभ एसा गल्ला मने़ं कि यीशू मसीह ई आसा प्रभू।","aura pitā paramēśvarē mahimā lai harēka zibha ēsā gallā manē̈ṁ ki yīśū masīha ī āsā prabhū.",null],[2,12,"तैहीता, हे मेरै प्यारो, ज़िहै तम्हैं हमेशा आज्ञा मंदी आसा आऐ दै, तिहैई ऐबै बी, सिधअ मूँह संघै रहंदी निं पर खासकर ऐबै मेरै दूर रहणैं का बी डरदी-कांबदी आपणैं-आपणैं उद्धारे कामां रहा पूरै करदै लागी।","taihītā, hē mērai pyārō, zihai tamhaiṁ hamēśā ājñā maṁdī āsā āai dai, tihaiī aibai bī, sidhaa mūm̐ha saṁghai rahaṁdī niṁ para khāsakara aibai mērai dūra rahaṇaiṁ kā bī ḍaradī-kāṁbadī āpaṇaiṁ-āpaṇaiṁ uddhārē kāmāṁ rahā pūrai karadai lāgī.",null],[2,13,"किल्हैकि परमेश्वर ई आसा ज़ुंणीं आपणीं सुइछा करै थारै मनैं इछा और काम, दुहै गल्ला करनेओ प्रभाव पाअ।","kilhaiki paramēśvara ī āsā zuṁṇīṁ āpaṇīṁ suichā karai thārai manaiṁ ichā aura kāma, duhai gallā karanēō prabhāva pāa.",null],[2,14,"सोभै काम करा बिणा कुड़कुड़ाए और बिणां कोई बिबाद करी।","sōbhai kāma karā biṇā kuṛakuṛāē aura biṇāṁ kōī bibāda karī.",null],[2,15,"ताकि तम्हैं निर्दोष और भोळै ह्ई करै टेढै और हठीलै लोगा बिच़ै परमेश्वरे निष्कलंक संतान बणीं रहे। (ज़सा बिच़ै तम्हैं ज़िऊणेंओ बच़न ल्ई एऊ संसारा दी ज़ळदै सदीऐ ज़िहै धेछिए)।","tāki tamhaiṁ nirdōṣa aura bhōḷai hī karai ṭēḍhai aura haṭhīlai lōgā bic̈ai paramēśvarē niṣkalaṁka saṁtāna baṇīṁ rahē. (zasā bic̈ai tamhaiṁ ziūṇēṁō bac̈ana lī ēū saṁsārā dī zaḷadai sadīai zihai dhēchiē).",null],[2,16,"कि मसीहे धेळी मुल्है बी तम्हैं घमंड करने कारण होए कि नां मेरअ अह ठुह्रनअ और नां मेरी अह मैंन्थ बेकार हुई।","ki masīhē dhēḷī mulhai bī tamhaiṁ ghamaṁḍa karanē kāraṇa hōē ki nāṁ mēraa aha ṭhuhranaa aura nāṁ mērī aha maiṁntha bēkāra huī.",null],[2,17,"और ज़ै मूँह थारै विश्वासे बलिदान और सेऊआ संघै आपणअ खून बी बहाऊणअ पळे, तैबी बी आसा हूँ खुश, और तम्हां सोभी संघै मनाऊआं हूँ खुशी।","aura zai mūm̐ha thārai viśvāsē balidāna aura sēūā saṁghai āpaṇaa khūna bī bahāūṇaa paḷē, taibī bī āsā hūm̐ khuśa, aura tamhāṁ sōbhī saṁghai manāūāṁ hūm̐ khuśī.",null],[2,18,"तिहैई रहा तम्हैं बी खुश, और मूँह संघै मनाऊंआ खुशी आनंद।","tihaiī rahā tamhaiṁ bī khuśa, aura mūm̐ha saṁghai manāūṁā khuśī ānaṁda.",null],[2,19,"मूँह आसा प्रभू यीशू दी आशा कि तिमुथियुस भेज़णअ मूँह तम्हां सेटा लै एभी, ताकि थारै हाल-च़ाल ज़ाणीं करै मूँबी शांती भेटे।","mūm̐ha āsā prabhū yīśū dī āśā ki timuthiyusa bhēzaṇaa mūm̐ha tamhāṁ sēṭā lai ēbhī, tāki thārai hāla-c̈āla zāṇīṁ karai mūm̐bī śāṁtī bhēṭē.",null],[2,20,"किल्हैकि मुखा निं ईहै स्वभावो कोहै आथी ज़ुंण शुध मना करै थारी चिंता फिकर करे।","kilhaiki mukhā niṁ īhai svabhāvō kōhai āthī zuṁṇa śudha manā karai thārī ciṁtā phikara karē.",null],[2,21,"किल्हैकि सोभै ह्आ आपणैं स्बार्था लोळै लागैदै, नां कि प्रभू यीशू लोळै।","kilhaiki sōbhai hā āpaṇaiṁ sbārthā lōḷai lāgaidai, nāṁ ki prabhū yīśū lōḷai.",null],[2,22,"पर सह आसा तम्हैं परखी बी हेरअ द और तम्हां का इहय थोघ बी आसा कि ज़िहअ शोहरू बाप्पू संघै करा, तेही मैंन्थ की तेऊ मूँह संघै सुसमाच़ारा फैलाऊणा लै।","para saha āsā tamhaiṁ parakhī bī hēraa da aura tamhāṁ kā ihaya thōgha bī āsā ki zihaa śōharū bāppū saṁghai karā, tēhī maiṁntha kī tēū mūm̐ha saṁghai susamāc̈ārā phailāūṇā lai.",null],[2,23,"मूँह आसा एही आशा कि ज़िहअ ई मूखा थोघ लागे कि आजू मेरी किज़ै दशा हणीं, तिहअ ई भेज़णअ मूँह अह नढैउऐ।","mūm̐ha āsā ēhī āśā ki zihaa ī mūkhā thōgha lāgē ki ājū mērī kizai daśā haṇīṁ, tihaa ī bhēzaṇaa mūm̐ha aha naḍhaiuai.",null],[2,24,"और मूँह आसा प्रभू दी भरोसअ कि आप्पू बी एछणअ हूँ तम्हां सेटा लै छ़ेकै।","aura mūm̐ha āsā prabhū dī bharōsaa ki āppū bī ēchaṇaa hūm̐ tamhāṁ sēṭā lai cḧēkai.",null],[2,25,"पर मंऐं समझ़अ इपफ्रदीतुस तम्हां सेटा लै भेज़णअ ज़रूरी, ज़ुंण मेरअ भाई, सैहकर्मीं और साथी जोधअ और थारअ दूत आसा और ज़रूरी गल्ला लै मेरी सेऊआ टैहल करनैआळअ आसा।","para maṁaiṁ samajḧaa ipaphradītusa tamhāṁ sēṭā lai bhēzaṇaa zarūrī, zuṁṇa mēraa bhāī, saihakarmīṁ aura sāthī jōdhaa aura thāraa dūta āsā aura zarūrī gallā lai mērī sēūā ṭaihala karanaiāḷaa āsā.",null],[2,26,"किल्हैकि तेऊओ मन त तम्हां सोभी सेटा लागअ द, और एऊई कारणैं रहा त अह बड़अ बेचैन ज़िहअ, किल्हैकि तम्हैं त एऊए बमारीओ हाल शुणअ द।","kilhaiki tēūō mana ta tamhāṁ sōbhī sēṭā lāgaa da, aura ēūī kāraṇaiṁ rahā ta aha baṛaa bēcaina zihaa, kilhaiki tamhaiṁ ta ēūē bamārīō hāla śuṇaa da.",null],[2,27,"अह सच़ी बमार ता हुअ त, ईधी तैणीं कि सह ग्अ त मरी, पर परमेश्वरै की तेऊ लै दैया, पर सिधी तेऊलै ई निं पर मुल्है बी की दैया कि मुल्है शोगा परैंदै शोग नां होए।","aha sac̈ī bamāra tā hua ta, īdhī taiṇīṁ ki saha ga ta marī, para paramēśvarai kī tēū lai daiyā, para sidhī tēūlai ī niṁ para mulhai bī kī daiyā ki mulhai śōgā paraiṁdai śōga nāṁ hōē.",null],[2,28,"तैहीता मंऐं तेऊ भेज़णेंए कोशिश की कि तम्हैं तेऊ का भी मिली करै खुशी होए और मेरअ शोग बी घटे।","taihītā maṁaiṁ tēū bhēzaṇēṁē kōśiśa kī ki tamhaiṁ tēū kā bhī milī karai khuśī hōē aura mēraa śōga bī ghaṭē.",null],[2,29,"तैही करै तम्हैं बी प्रभू दी तेऊ संघै बडै आनंद और खुशी दी भेंट, और इंना ईहैओ करनअ आदरमान।","taihī karai tamhaiṁ bī prabhū dī tēū saṁghai baḍai ānaṁda aura khuśī dī bhēṁṭa, aura iṁnā īhaiō karanaa ādaramāna.",null],[2,30,"किल्हैकि अह पुजअ त मसीहे कामां लै आपणैं प्राणा खातरै दी पाई मौता बिलकुल नेळ, ताकि ज़ुंण कामी पेशी थारी तरफा का मेरी सेऊआ दी हूई, तेसा पूरी करे।","kilhaiki aha pujaa ta masīhē kāmāṁ lai āpaṇaiṁ prāṇā khātarai dī pāī mautā bilakula nēḷa, tāki zuṁṇa kāmī pēśī thārī taraphā kā mērī sēūā dī hūī, tēsā pūrī karē.",null],[3,1,"इहय करै, हे भाईयो, प्रभू दी रहा आनंदित, इन्नांईं गल्ला भी-भी लिखणा लै निं मूँह कोई बी कष्‌ट हंदअ और एताई दी आसा थारअ कुशल मंगल।","ihaya karai, hē bhāīyō, prabhū dī rahā ānaṁdita, innāṁīṁ gallā bhī-bhī likhaṇā lai niṁ mūm̐ha kōī bī kaṣṭa haṁdaa aura ētāī dī āsā thāraa kuśala maṁgala.",null],[3,2,"तिन्नां कुत्तै का रहा चतान, और इन्नां बूरै कामां करनैआळै का बी रहा चतैन, तिन्नां काटणैं फणाटणैं आळै का बी रहा चतैन।","tinnāṁ kuttai kā rahā catāna, aura innāṁ būrai kāmāṁ karanaiāḷai kā bī rahā cataina, tinnāṁ kāṭaṇaiṁ phaṇāṭaṇaiṁ āḷai kā bī rahā cataina.",null],[3,3,"किल्हैकि खतनैआळै आसा हाम्हैं ई, ज़ुंण परमेश्वरे आत्में अगुआई करै उपासना करा, और मसीह यीशू दी घमंड बी करा, और आपणैं शरीरो भरोसअ निं डाहंदै।","kilhaiki khatanaiāḷai āsā hāmhaiṁ ī, zuṁṇa paramēśvarē ātmēṁ aguāī karai upāsanā karā, aura masīha yīśū dī ghamaṁḍa bī karā, aura āpaṇaiṁ śarīrō bharōsaa niṁ ḍāhaṁdai.",null],[3,4,"पर हूँ सका शरीरा दी बी भरोसअ डाही, ज़ै कसा शरीरा दी भरोसै करनैओ बच़ार होए, ता हूँ सका तेऊ का बढकर करी।","para hūm̐ sakā śarīrā dī bī bharōsaa ḍāhī, zai kasā śarīrā dī bharōsai karanaiō bac̈āra hōē, tā hūm̐ sakā tēū kā baḍhakara karī.",null],[3,5,"आठूऐ धैळै हुअ मेरअ खतनअ इस्त्राईलै खांनदानिं का और बिन्यामीने गोत्रा का आसा हूँ; ईब्रानीओं आसा हूँ ईब्रानी; व्यवस्थे साबै जै कुंण बोले ता हूँ आसा फरीसी।","āṭhūai dhaiḷai hua mēraa khatanaa istrāīlai khāṁnadāniṁ kā aura binyāmīnē gōtrā kā āsā hūm̐; ībrānīōṁ āsā hūm̐ ībrānī; vyavasthē sābai jai kuṁṇa bōlē tā hūm̐ āsā pharīsī.",null],[3,6,"उत्साहे साबै ज़ै कुंण बोले ता तै आसा हूँ कलीसिया सताऊणैं और क्लेश दैणैं आळअ, और व्यवस्थे धार्मिकते बारै ज़ै कुंण बोले ता तै थिय हूँ बिलकुल निर्दोष।","utsāhē sābai zai kuṁṇa bōlē tā tai āsā hūm̐ kalīsiyā satāūṇaiṁ aura klēśa daiṇaiṁ āḷaa, aura vyavasthē dhārmikatē bārai zai kuṁṇa bōlē tā tai thiya hūm̐ bilakula nirdōṣa.",null],[3,7,"पर ज़ुंण-ज़ुंण गल्ला मेरै फाईदै लै ती, तिंयांई समझ़ी मंऐं मसीहे कारण आप्पू लै हानिं।","para zuṁṇa-zuṁṇa gallā mērai phāīdai lai tī, tiṁyāṁī samajḧī maṁaiṁ masīhē kāraṇa āppū lai hāniṁ.",null],[3,8,"पर हूँ समझ़ा एसाई गल्ला उत्तम कि लोग बछ़ैणें मूँह प्रभू यीशूए नांओऐ ई। ज़ेते बज़ह मंऐं इन्नां सोभी गले हानिं च़की, और हूँ समझ़ा इंना गल्ला कूळअ-कवाळ, ताकि हूँ मसीह प्राप्त करी सकूँ।","para hūm̐ samajḧā ēsāī gallā uttama ki lōga bacḧaiṇēṁ mūm̐ha prabhū yīśūē nāṁōai ī. zētē bazaha maṁaiṁ innāṁ sōbhī galē hāniṁ c̈akī, aura hūm̐ samajḧā iṁnā gallā kūḷaa-kavāḷa, tāki hūm̐ masīha prāpta karī sakūm̐.",null],[3,9,"और तेथै ई भेटूँ, नां कि आपणीं तेसा धार्मिकता संघै, ज़ुंण व्यवस्था करै आसा, पर तेसा धार्मिकता संघै ज़ुंण मसीह दी विश्वास करनै करे आसा, और परमेश्वरा का बिश्‍बास करी करै भेटा।","aura tēthai ī bhēṭūm̐, nāṁ ki āpaṇīṁ tēsā dhārmikatā saṁghai, zuṁṇa vyavasthā karai āsā, para tēsā dhārmikatā saṁghai zuṁṇa masīha dī viśvāsa karanai karē āsā, aura paramēśvarā kā biśbāsa karī karai bhēṭā.",null],[3,10,"और हूँ तेता और तेते मृत्यँजय सामरर्था, और तेऊ संघै दुखी हणें मह्रमां समझ़ूं और तेऊए मौते समानता प्राप्त करी सकूँ।","aura hūm̐ tētā aura tētē mr̥tyam̐jaya sāmararthā, aura tēū saṁghai dukhī haṇēṁ mahramāṁ samajḧūṁ aura tēūē mautē samānatā prāpta karī sakūm̐.",null],[3,11,"ताकि हूँ केऊ बी तरिकै करै मूँऐं दै मांझ़ै ज़िऊंणेए पदा दी पुजूँ।","tāki hūm̐ kēū bī tarikai karai mūm̐aiṁ dai māṁjḧai ziūṁṇēē padā dī pujūm̐.",null],[3,12,"एतो निं इहय मतलब आथी कि मूँह मुकअ अह भेटी, या हूँ मुकअ सिध ह्ई, पर एऊ पदार्था ढाकणा लै आसा हूँ ठुह्रदअ लागअ द; ज़ेते तैणीं मसीह यीशू हूँ ढाकअ त।","ētō niṁ ihaya matalaba āthī ki mūm̐ha mukaa aha bhēṭī, yā hūm̐ mukaa sidha hī, para ēū padārthā ḍhākaṇā lai āsā hūm̐ ṭhuhradaa lāgaa da; zētē taiṇīṁ masīha yīśū hūm̐ ḍhākaa ta.",null],[3,13,"हे भाईयो, मेरी भावना निं एही आथी कि हूँ मुकअ ढाकी; पर सिधअ एक काम करा हूँ इहय कि ज़ुंण गल्ला पिछ़ू आसा छ़ुटी ग्ई दी, तिन्नां बिसरी करै बढा हूँ आजू लै,","hē bhāīyō, mērī bhāvanā niṁ ēhī āthī ki hūm̐ mukaa ḍhākī; para sidhaa ēka kāma karā hūm̐ ihaya ki zuṁṇa gallā picḧū āsā cḧuṭī gī dī, tinnāṁ bisarī karai baḍhā hūm̐ ājū lai,",null],[3,14,"और नशाणैं बाखा लै रहा हूँ ठुह्रदअ लागी, ताकि हूँ तेते नाम पाऊं ज़ेता लै हूँ मसीह यीशू दी उझै आसा शादअ द।","aura naśāṇaiṁ bākhā lai rahā hūm̐ ṭhuhradaa lāgī, tāki hūm̐ tētē nāma pāūṁ zētā lai hūm̐ masīha yīśū dī ujhai āsā śādaa da.",null],[3,15,"ता, हाम्हां मांझ़ै ज़ेतरै लोग सिध आसा, तिंयां डाहै इहय ई बच़ार, और ज़ै थारअ किज़ी गल्ला लै किज़ै होर बच़ार होए, ता परमेश्वरा हेरनअ सबी तम्हां दी प्रगट करी।","tā, hāmhāṁ māṁjḧai zētarai lōga sidha āsā, tiṁyāṁ ḍāhai ihaya ī bac̈āra, aura zai thāraa kizī gallā lai kizai hōra bac̈āra hōē, tā paramēśvarā hēranaa sabī tamhāṁ dī pragaṭa karī.",null],[3,16,"इधी तैणीं आसा हाम्हैं पुजै दै और एऊई साबै रहणअ हांढदै लागी।","idhī taiṇīṁ āsā hāmhaiṁ pujai dai aura ēūī sābai rahaṇaa hāṁḍhadai lāgī.",null],[3,17,"हे भाईयो, तम्हैं सोभै च़ला मिलीकरै मूँह जेही च़ाल, और तिन्नां डाहा बछ़ैणीं ज़ुंण एऊ साबै च़ला, ज़सरअ उदहारण तम्हां मूँह दी भेटा।","hē bhāīyō, tamhaiṁ sōbhai c̈alā milīkarai mūm̐ha jēhī c̈āla, aura tinnāṁ ḍāhā bacḧaiṇīṁ zuṁṇa ēū sābai c̈alā, zasaraa udahāraṇa tamhāṁ mūm̐ha dī bhēṭā.",null],[3,18,"किल्हैकि कई च़ला एही च़ाल, ज़ेते च़रचा मंऐं तम्हां का कई बारी आसा की दी और एभै बी बोला हूँ लेरा लाई- लाईकरै तम्हां लै कि तिंयां आसा आपणैं च़ाल-च़लणा करै मसीहे क्रूसे बैरी।","kilhaiki kaī c̈alā ēhī c̈āla, zētē c̈aracā maṁaiṁ tamhāṁ kā kaī bārī āsā kī dī aura ēbhai bī bōlā hūm̐ lērā lāī- lāīkarai tamhāṁ lai ki tiṁyāṁ āsā āpaṇaiṁ c̈āla-c̈alaṇā karai masīhē krūsē bairī.",null],[3,19,"तिंनो अंत आसा बिनाश, तिंनो ईश्बर आसा पेट, और तिंयां करा आपणीं लज्ज़ाऊणें गल्ला दी बी घमंड, और संसारे च़िज़ा दी डाहा मन लाई।","tiṁnō aṁta āsā bināśa, tiṁnō īśbara āsā pēṭa, aura tiṁyāṁ karā āpaṇīṁ lajzāūṇēṁ gallā dī bī ghamaṁḍa, aura saṁsārē c̈izā dī ḍāhā mana lāī.",null],[3,20,"पर म्हारअ स्बदेश आसा स्बर्ग; और हाम्हैं आसा उद्धारकर्ता प्रभू यीशू तिधा का एछदै न्हैळै भाळै लागै दै।","para mhāraa sbadēśa āsā sbarga; aura hāmhaiṁ āsā uddhārakartā prabhū yīśū tidhā kā ēchadai nhaiḷai bhāḷai lāgai dai.",null],[3,21,"सह सका आपणीं शगतीए तेऊ प्रभावा करै, ज़ेता करै सह सोभी च़िज़ा आपणैं बशै करी सका, म्हारी दीन–हीन देहीओ रूप बदळी करै आपणीं महिंमे देहीए साबै बणांईं।","saha sakā āpaṇīṁ śagatīē tēū prabhāvā karai, zētā karai saha sōbhī c̈izā āpaṇaiṁ baśai karī sakā, mhārī dīna–hīna dēhīō rūpa badaḷī karai āpaṇīṁ mahiṁmē dēhīē sābai baṇāṁīṁ.",null],[4,1,"तैहीता हे भाईयो, ज़ेथ दी मेरअ ज़िऊ लागी रहा, ज़ुंण मेरअ आनंद और मुकुट होए, हे प्रिय भाईयो, प्रभू दी रहा एऊई साबै स्थिर।","taihītā hē bhāīyō, zētha dī mēraa ziū lāgī rahā, zuṁṇa mēraa ānaṁda aura mukuṭa hōē, hē priya bhāīyō, prabhū dī rahā ēūī sābai sthira.",null],[4,2,"हूँ समझ़ाऊआ यूओदिआ बी, और सन्तुखे बी कि तिन्नां लै बोला हूँ प्रभू दी रहा एक मन ह्ई करै।","hūm̐ samajḧāūā yūōdiā bī, aura santukhē bī ki tinnāṁ lai bōlā hūm̐ prabhū dī rahā ēka mana hī karai.",null],[4,3,"और हे सच्च़ै सैहकर्मीं हूँ करा ताखा अरज़ कि तूह कर तिन्नां स्त्रीए सहायता, किल्हैकि तिन्नैं आसा मूँह संघै सुसमाच़ारा फैलाऊणैं दी, क्लेमेंस और मेरै तिन्नां होरी संघा काम करनै आळै संघी आसा बडी मैंन्थ की दी, ज़सरै नांअ ज़िंदगीए कताबा दी आसा लिखै दै।","aura hē sacc̈ai saihakarmīṁ hūm̐ karā tākhā araza ki tūha kara tinnāṁ strīē sahāyatā, kilhaiki tinnaiṁ āsā mūm̐ha saṁghai susamāc̈ārā phailāūṇaiṁ dī, klēmēṁsa aura mērai tinnāṁ hōrī saṁghā kāma karanai āḷai saṁghī āsā baḍī maiṁntha kī dī, zasarai nāṁa ziṁdagīē katābā dī āsā likhai dai.",null],[4,4,"प्रभू दी रहा सदा आनंदित; भी-भी बोला हूँ आनंदित रहा।","prabhū dī rahā sadā ānaṁdita; bhī-bhī bōlā hūm̐ ānaṁdita rahā.",null],[4,5,"थारी कोमलता लोळी सोभी मांह्णूं दी प्रगट हुई, प्रभू आसा नेळ।","thārī kōmalatā lōḷī sōbhī māṁhṇūṁ dī pragaṭa huī, prabhū āsā nēḷa.",null],[4,6,"किछ़ू गल्लो हैळअ फिकर निं करी, पर हरेकी गल्ला दी करनीं थारै प्राथणा निबेदन और बिनती, धन्यबाद संघै परमेश्वरा सेटा पेश।","kicḧū gallō haiḷaa phikara niṁ karī, para harēkī gallā dī karanīṁ thārai prāthaṇā nibēdana aura binatī, dhanyabāda saṁghai paramēśvarā sēṭā pēśa.",null],[4,7,"तैबै हणीं परमेश्वरे शांती, ज़ुंण समझ़ म्हारी समझा का बिलकुल बागै आसा, और थारै दिल और थारै बच़ार डाहणैं मसीह यीशू दी सुरक्षित।","taibai haṇīṁ paramēśvarē śāṁtī, zuṁṇa samajḧa mhārī samajhā kā bilakula bāgai āsā, aura thārai dila aura thārai bac̈āra ḍāhaṇaiṁ masīha yīśū dī surakṣita.",null],[4,8,"एते तैणीं, हे भाईयो, ज़ुंण-ज़ुंण गल्ला सच्च़ी आसा, और ज़ुंण-ज़ुंण गल्ला आदर करनै जोगी आसा, और ज़ुंण-ज़ुंण गल्ला ठीक आसा, और ज़ुंण-ज़ुंण गल्ला पबित्र आसा, और ज़ुंण-ज़ुंण गल्ला सुहाबणीं आसा, औ ज़ुंण-ज़ुंण गल्ला मनैं भाऊणैं आळी आसा, एते तैणीं, ज़ुंण-ज़ुंण गल्ला सदगुण और प्रशंसा करनै जोगी आसा, तिन्नां दी ही दैआ धैन।","ētē taiṇīṁ, hē bhāīyō, zuṁṇa-zuṁṇa gallā sacc̈ī āsā, aura zuṁṇa-zuṁṇa gallā ādara karanai jōgī āsā, aura zuṁṇa-zuṁṇa gallā ṭhīka āsā, aura zuṁṇa-zuṁṇa gallā pabitra āsā, aura zuṁṇa-zuṁṇa gallā suhābaṇīṁ āsā, au zuṁṇa-zuṁṇa gallā manaiṁ bhāūṇaiṁ āḷī āsā, ētē taiṇīṁ, zuṁṇa-zuṁṇa gallā sadaguṇa aura praśaṁsā karanai jōgī āsā, tinnāṁ dī hī daiā dhaina.",null],[4,9,"ज़ुंण गल्ला तम्हैं मुखा शिखळी, और ग्रहण की, और शुंणीं, और मूँह दी भाळी, तिंनो ई करा पाळण, तै रहणअ परमेश्वर ज़ुंण शांतीओ सोबळ आसा, तम्हां संघै।","zuṁṇa gallā tamhaiṁ mukhā śikhaḷī, aura grahaṇa kī, aura śuṁṇīṁ, aura mūm̐ha dī bhāḷī, tiṁnō ī karā pāḷaṇa, tai rahaṇaa paramēśvara zuṁṇa śāṁtīō sōbaḷa āsā, tamhāṁ saṁghai.",null],[4,10,"हूँ आसा प्रभू दी आनंद और खुश कि एतरै धैळै बाद थारअ बच़ार मेरै बारै ज़ागअ भी; ज़रूर तम्हां पैहलै बी त एतो बच़ार, पर तम्हां निं मौकअ भेटअ।","hūm̐ āsā prabhū dī ānaṁda aura khuśa ki ētarai dhaiḷai bāda thāraa bac̈āra mērai bārai zāgaa bhī; zarūra tamhāṁ paihalai bī ta ētō bac̈āra, para tamhāṁ niṁ maukaa bhēṭaa.",null],[4,11,"इहय निं कि हूँ बोला एसा गल्ला आपणीं कामीं पेशीए कारण, किल्हैकि मंऐं आसा शिखळअ द कि ज़ेसा दशा दी हूँ आसा, तेथै रहणअ संतुष्ट।","ihaya niṁ ki hūm̐ bōlā ēsā gallā āpaṇīṁ kāmīṁ pēśīē kāraṇa, kilhaiki maṁaiṁ āsā śikhaḷaa da ki zēsā daśā dī hūm̐ āsā, tēthai rahaṇaa saṁtuṣṭa.",null],[4,12,"हूँ ज़ाणा दीन हणअ बी और बढणअ बी, हरेकी गल्ला और सोभी दशा दी तृप्त हणअ, भुख्खै रहणअ, और बढणअ-घटणअ आसा म्ऐं शिखळअ द।","hūm̐ zāṇā dīna haṇaa bī aura baḍhaṇaa bī, harēkī gallā aura sōbhī daśā dī tr̥pta haṇaa, bhukhkhai rahaṇaa, aura baḍhaṇaa-ghaṭaṇaa āsā maiṁ śikhaḷaa da.",null],[4,13,"ज़ुंण मुल्है सामर्थ दैआ तेऊ दी सका हूँ सोभ किछ़ करी।","zuṁṇa mulhai sāmartha daiā tēū dī sakā hūm̐ sōbha kicḧa karī.",null],[4,14,"तैबी बी किय तम्हैं भलअ कि मेरै क्लैशा दी बी हुऐ तम्हैं सैहभागी।","taibī bī kiya tamhaiṁ bhalaa ki mērai klaiśā dī bī huai tamhaiṁ saihabhāgī.",null],[4,15,"और हे फिलिप्पिओ, तम्हां का आसा थोघ कि सुसमाच़ार प्रच़ारे शुरुआता दी ज़धू हूँ मकिदुनियां का च़लअ तधू निं तम्हां छ़ाडी होरी कोही मण्डळी लैणैं-दैणेंए बारै मेरी मदद की।","aura hē philippiō, tamhāṁ kā āsā thōgha ki susamāc̈āra prac̈ārē śuruātā dī zadhū hūm̐ makiduniyāṁ kā c̈alaa tadhū niṁ tamhāṁ cḧāḍī hōrī kōhī maṇḍaḷī laiṇaiṁ-daiṇēṁē bārai mērī madada kī.",null],[4,16,"इहयई करै ज़धू हूँ थिस्सलुनिके थिय, तधू बी भेज़अ किछ़ तम्हैं मेरी कमी घटी पुरी करना लै। एकी बारी निं पर दूई बारी पै भेज़अ त तम्हैं मुल्है धन।","ihayaī karai zadhū hūm̐ thissalunikē thiya, tadhū bī bhēzaa kicḧa tamhaiṁ mērī kamī ghaṭī purī karanā lai. ēkī bārī niṁ para dūī bārī pai bhēzaa ta tamhaiṁ mulhai dhana.",null],[4,17,"इहय निं कि हूँ च़ाहा दान, पर हूँ च़ाहा इहय फळ ज़ुंण थारै फाईदै लै बढदअ रहे।","ihaya niṁ ki hūm̐ c̈āhā dāna, para hūm̐ c̈āhā ihaya phaḷa zuṁṇa thārai phāīdai lai baḍhadaa rahē.",null],[4,18,"मुखा आसा सोभै गल्ला, बोले ता खासअ बी आसा, ज़ुंण च़िज़ा तम्हैं इपफ्रूदीतुसे हाथै भेज़ी ती तिन्नां भेटी करै हुअ हूँ भरपूर, सह ता सुगंध और ग्रहण करनै जोगी बलिदान आसा, ज़ुंण परमेश्वरा भाऊंआ।","mukhā āsā sōbhai gallā, bōlē tā khāsaa bī āsā, zuṁṇa c̈izā tamhaiṁ ipaphrūdītusē hāthai bhēzī tī tinnāṁ bhēṭī karai hua hūm̐ bharapūra, saha tā sugaṁdha aura grahaṇa karanai jōgī balidāna āsā, zuṁṇa paramēśvarā bhāūṁā.",null],[4,19,"और मेरअ परमेश्वर बी आपणैं तेऊ धने साबै ज़ुंण महिंमा संघी मसीह यीशू दी आसा, तेऊ करनी थारी हरेक कामी घटी पूरी।","aura mēraa paramēśvara bī āpaṇaiṁ tēū dhanē sābai zuṁṇa mahiṁmā saṁghī masīha yīśū dī āsā, tēū karanī thārī harēka kāmī ghaṭī pūrī.",null],[4,20,"म्हारै प्रभू और पिता परमेश्वरे महिंमा लोळी जुगै-जुगै हंदी रही॥","mhārai prabhū aura pitā paramēśvarē mahiṁmā lōḷī jugai-jugai haṁdī rahī..",null],[4,21,"हरेकी पबित्र माह्णूं ज़ुंण यीशू मसीहा दी आसा, तिन्नां लै बोलै नमस्कार और राज़ी-बाज़ी दैए, ज़ुंण भाई मूँह संघै आसा, तिंयां बी बोला तम्हां लै नमस्कार और राज़ी-बाज़ी।","harēkī pabitra māhṇūṁ zuṁṇa yīśū masīhā dī āsā, tinnāṁ lai bōlai namaskāra aura rāzī-bāzī daiē, zuṁṇa bhāī mūm̐ha saṁghai āsā, tiṁyāṁ bī bōlā tamhāṁ lai namaskāra aura rāzī-bāzī.",null],[4,22,"सोभै पबित्र लोग, खासकर ज़ुंण कैसरे घरानै का आसा, तिंयां बी बोला तम्हां लै नमस्कार और राज़ी-बाज़ी।","sōbhai pabitra lōga, khāsakara zuṁṇa kaisarē gharānai kā āsā, tiṁyāṁ bī bōlā tamhāṁ lai namaskāra aura rāzī-bāzī.",null],[4,23,"म्हारै प्रभू यीशू मसीहो अनुग्रह लोळी थारी आत्मां संघै रहअ।","mhārai prabhū yīśū masīhō anugraha lōḷī thārī ātmāṁ saṁghai rahaa.",null]],"mal":[[1,1,"ക്രിസ്തുയേശുവിൻ്റെ ദാസന്മാരായ പൗലൊസും തിമൊഥെയൊസും ഫിലിപ്പിയിൽ ക്രിസ്തുയേശുവിലുള്ള സകലവിശുദ്ധന്മാർക്കും അദ്ധ്യക്ഷന്മാർക്കും ശുശ്രൂഷകന്മാർക്കും കൂടെ എഴുതുന്നത്:","kristuyēśuvinṟe dāsanmārāya paulosuṁ timotheyosuṁ philippiyil kristuyēśuviluḷḷa sakalaviśuddhanmārkkuṁ addhyakṣanmārkkuṁ śuśrūṣakanmārkkuṁ kūṭe eḻutunnat:",null],[1,2,"നമ്മുടെ പിതാവായ ദൈവത്തിങ്കൽനിന്നും കർത്താവായ യേശുക്രിസ്തുവിങ്കൽ നിന്നും നിങ്ങൾക്ക് കൃപയും സമാധാനവും ഉണ്ടാകട്ടെ.","nammuṭe pitāvāya daivattiṅkalninnuṁ karttāvāya yēśukristuviṅkal ninnuṁ niṅṅaḷkk kr̥payuṁ samādhānavuṁ uṇṭākaṭṭe.",null],[1,3,"നിങ്ങളിൽ നല്ല പ്രവൃത്തിയെ ആരംഭിച്ചവൻ യേശുക്രിസ്തുവിന്‍റെ നാളോളം അതിനെ തികയ്ക്കും എന്നു ഞാൻ ഉറച്ച്,","niṅṅaḷil nalla pravr̥ttiye āraṁbhiccavan yēśukristuvinṟe nāḷōḷaṁ atine tikaykkuṁ ennu ñān uṟacc,",null],[1,4,"ഒന്നാം നാൾമുതൽ ഇതുവരെയും സുവിശേഷഘോഷണത്തിൽ നിങ്ങൾക്കുള്ള കൂട്ടായ്മ നിമിത്തം,","onnāṁ nāḷmutal ituvareyuṁ suviśēṣaghōṣaṇattil niṅṅaḷkkuḷḷa kūṭṭāyma nimittaṁ,",null],[1,5,"നിങ്ങൾക്ക് എല്ലാവർക്കുംവേണ്ടി കഴിക്കുന്ന സകല പ്രാർത്ഥനയിലും എപ്പോഴും സന്തോഷത്തോടെ പ്രാർത്ഥിച്ച്,","niṅṅaḷkk ellāvarkkuṁvēṇṭi kaḻikkunna sakala prārtthanayiluṁ eppōḻuṁ santōṣattōṭe prārtthicc,",null],[1,6,"നിങ്ങളെ ഓർക്കുമ്പോൾ ഒക്കെയും എന്‍റെ ദൈവത്തിന് ഞാൻ സ്തോത്രം ചെയ്യുന്നു.","niṅṅaḷe ōrkkumpōḷ okkeyuṁ enṟe daivattin ñān stōtraṁ ceyyunnu.",null],[1,7,"എന്‍റെ ബന്ധനങ്ങളിലും സുവിശേഷത്തിന്‍റെ പ്രതിവാദത്തിലും സ്ഥിരീകരണത്തിലും, കൃപയിൽ എനിക്ക് കൂട്ടാളികളായ നിങ്ങളെ ഒക്കെയും ഞാൻ എന്‍റെ ഹൃദയത്തിൽ വഹിച്ചിരിക്കുകകൊണ്ട് നിങ്ങളെ എല്ലാവരെയും കുറിച്ച് അങ്ങനെ വിചാരിക്കുന്നത് എനിക്ക് ന്യായമല്ലോ.","enṟe bandhanaṅṅaḷiluṁ suviśēṣattinṟe prativādattiluṁ sthirīkaraṇattiluṁ, kr̥payil enikk kūṭṭāḷikaḷāya niṅṅaḷe okkeyuṁ ñān enṟe hr̥dayattil vahiccirikkukakoṇṭ niṅṅaḷe ellāvareyuṁ kuṟicc aṅṅane vicārikkunnat enikk nyāyamallō.",null],[1,8,"ക്രിസ്തുയേശുവിൻ്റെ ആർദ്രതയോടെ ഞാൻ നിങ്ങളെ എല്ലാവരെയും കാണുവാൻ എത്ര വാഞ്ചിക്കുന്നു എന്നതിന് ദൈവം സാക്ഷി.","kristuyēśuvinṟe ārdratayōṭe ñān niṅṅaḷe ellāvareyuṁ kāṇuvān etra vāñcikkunnu ennatin daivaṁ sākṣi.",null],[1,9,"നിങ്ങളുടെ സ്നേഹം മേല്ക്കുമേൽ ജ്ഞാനത്തിലും സകലവിവേചനത്തിലും വർദ്ധിച്ചു വന്നിട്ട്","niṅṅaḷuṭe snēhaṁ mēlkkumēl jñānattiluṁ sakalavivēcanattiluṁ varddhiccu vanniṭṭ",null],[1,10,"ക്രിസ്തുവിന്‍റെ നാളിലേക്ക് നിഷ്കളങ്കരും കുറ്റമില്ലാത്തവരുമായി, നിങ്ങൾ ഉത്തമമായത് അംഗീകരിച്ച്,","kristuvinṟe nāḷilēkk niṣkaḷaṅkaruṁ kuṟṟamillāttavarumāyi, niṅṅaḷ uttamamāyat aṁgīkaricc,",null],[1,11,"ദൈവത്തിന്‍റെ മഹത്വത്തിനും പുകഴ്ചയ്ക്കുമായിട്ട് യേശുക്രിസ്തുവിനാൽ നീതിഫലങ്ങൾ നിറഞ്ഞവരാകുവാൻ ഞാൻ പ്രാർത്ഥിക്കുന്നു.","daivattinṟe mahatvattinuṁ pukaḻcaykkumāyiṭṭ yēśukristuvināl nītiphalaṅṅaḷ niṟaññavarākuvān ñān prārtthikkunnu.",null],[1,12,"സഹോദരന്മാരേ, എനിക്ക് ഭവിച്ചത് സുവിശേഷത്തിന്‍റെ അഭിവൃദ്ധിക്ക് കാരണമായിത്തീർന്നു എന്നു നിങ്ങൾ ഇപ്പോൾ അറിയുവാൻ ഞാൻ ഇച്ഛിക്കുന്നു.","sahōdaranmārē, enikk bhaviccat suviśēṣattinṟe abhivr̥ddhikk kāraṇamāyittīrnnu ennu niṅṅaḷ ippōḷ aṟiyuvān ñān icchikkunnu.",null],[1,13,"അതുകൊണ്ട് എന്‍റെ ബന്ധനങ്ങൾ ക്രിസ്തു നിമിത്തമാകുന്നു എന്നു അകമ്പടിപട്ടാളത്തിൽ ഒക്കെയും ശേഷം എല്ലാവർക്കും തെളിവായി വരികയും","atukoṇṭ enṟe bandhanaṅṅaḷ kristu nimittamākunnu ennu akampaṭipaṭṭāḷattil okkeyuṁ śēṣaṁ ellāvarkkuṁ teḷivāyi varikayuṁ",null],[1,14,"സഹോദരന്മാർ മിക്കപേരും എന്‍റെ ബന്ധനങ്ങളാൽ കർത്താവിൽ ധൈര്യംപൂണ്ട് ദൈവത്തിന്‍റെ വചനം ഭയംകൂടാതെ അധികമായി പ്രസ്താവിക്കുവാൻ ധൈര്യത്തോടെ ഇരിക്കുകയും ചെയ്യുന്നു.","sahōdaranmār mikkapēruṁ enṟe bandhanaṅṅaḷāl karttāvil dhairyaṁpūṇṭ daivattinṟe vacanaṁ bhayaṁkūṭāte adhikamāyi prastāvikkuvān dhairyattōṭe irikkukayuṁ ceyyunnu.",null],[1,15,"ചിലർ ക്രിസ്തുവിനെ പ്രസംഗിക്കുന്നത് അസൂയയും പിണക്കവും നിമിത്തമാണ്;","cilar kristuvine prasaṁgikkunnat asūyayuṁ piṇakkavuṁ nimittamāṇ;",null],[1,16,"ചിലരോ നല്ല മനസ്സോടെ തന്നെ. അവർ സുവിശേഷത്തിന്‍റെ പ്രതിവാദത്തിനായി എന്നെ നിയമിച്ചിരിക്കുന്നു എന്നു അറിഞ്ഞിട്ട് അത് സ്നേഹത്തിൽനിന്ന് ചെയ്യുന്നു.","cilarō nalla manassōṭe tanne. avar suviśēṣattinṟe prativādattināyi enne niyamiccirikkunnu ennu aṟiññiṭṭ at snēhattilninn ceyyunnu.",null],[1,17,"എന്നാൽ മറ്റവരോ, എന്‍റെ ബന്ധനങ്ങളിൽ എനിക്ക് പ്രയാസം വരുത്തുവാൻ ഭാവിച്ചുകൊണ്ട് നിർമ്മലതയോടെയല്ല, സ്വാർത്ഥതയിൽ നിന്നത്രേ ക്രിസ്തുവിനെ പ്രസംഗിക്കുന്നത്.","ennāl maṟṟavarō, enṟe bandhanaṅṅaḷil enikk prayāsaṁ varuttuvān bhāviccukoṇṭ nirmmalatayōṭeyalla, svārtthatayil ninnatrē kristuvine prasaṁgikkunnat.",null],[1,18,"പിന്നെ എന്ത്? അഭിനയമായിട്ടോ സത്യമായിട്ടോ ഏതുവിധമായാലും ക്രിസ്തുവിനെ അത്രേ പ്രസംഗിക്കുന്നത്. ഇതിൽ ഞാൻ സന്തോഷിക്കുന്നു; ഇനിയും സന്തോഷിക്കും.","pinne ent? abhinayamāyiṭṭō satyamāyiṭṭō ētuvidhamāyāluṁ kristuvine atrē prasaṁgikkunnat. itil ñān santōṣikkunnu; iniyuṁ santōṣikkuṁ.",null],[1,19,"എന്തെന്നാൽ നിങ്ങളുടെ പ്രാർത്ഥനയാലും യേശുക്രിസ്തുവിന്‍റെ ആത്മാവിന്‍റെ സഹായത്താലും അത് എനിക്ക് വിടുതലായിത്തീരും എന്നു ഞാൻ അറിയുന്നു.","entennāl niṅṅaḷuṭe prārtthanayāluṁ yēśukristuvinṟe ātmāvinṟe sahāyattāluṁ at enikk viṭutalāyittīruṁ ennu ñān aṟiyunnu.",null],[1,20,"ഒന്നിലും ഞാൻ ലജ്ജിച്ചുപോകയില്ല എന്നത് എന്‍റെ ദൃഢമായ പ്രതീക്ഷയും പ്രത്യാശയും ആകുന്നു. എന്നാൽ എപ്പോഴും എന്നപോലെ ഇപ്പോഴും പൂർണ്ണ ധൈര്യത്തോടുകൂടെ ജീവനാൽ ആകട്ടെ മരണത്താൽ ആകട്ടെ ക്രിസ്തു എന്‍റെ ശരീരത്തിൽ മഹിമപ്പെടും.","onniluṁ ñān lajjiccupōkayilla ennat enṟe dr̥ḍhamāya pratīkṣayuṁ pratyāśayuṁ ākunnu. ennāl eppōḻuṁ ennapōle ippōḻuṁ pūrṇṇa dhairyattōṭukūṭe jīvanāl ākaṭṭe maraṇattāl ākaṭṭe kristu enṟe śarīrattil mahimappeṭuṁ.",null],[1,21,"എന്തെന്നാൽ എനിക്ക് ജീവിക്കുന്നത് ക്രിസ്തുവും മരിക്കുന്നത് ലാഭവും ആകുന്നു.","entennāl enikk jīvikkunnat kristuvuṁ marikkunnat lābhavuṁ ākunnu.",null],[1,22,"എന്നാൽ ജഡത്തിൽ ജീവിക്കുന്നു എങ്കിൽ അത് ഫലകരമായ എന്‍റെ വേലയ്ക്കു വേണ്ടിത്തന്നെ; എങ്കിലും ഏത് തിരഞ്ഞെടുക്കേണം എന്നു ഞാൻ അറിയുന്നില്ല.","ennāl jaḍattil jīvikkunnu eṅkil at phalakaramāya enṟe vēlaykku vēṇṭittanne; eṅkiluṁ ēt tiraññeṭukkēṇaṁ ennu ñān aṟiyunnilla.",null],[1,23,"എന്നാൽ ഇവ രണ്ടിനാലും ഞാൻ ഞെരുങ്ങുന്നു; വിട്ടുപിരിഞ്ഞ് ക്രിസ്തുവിനോടുകൂടെ ഇരിക്കുവാൻ എനിക്ക് ആഗ്രഹമുണ്ട്; അത് അത്യുത്തമമല്ലോ.","ennāl iva raṇṭināluṁ ñān ñeruṅṅunnu; viṭṭupiriññ kristuvinōṭukūṭe irikkuvān enikk āgrahamuṇṭ; at atyuttamamallō.",null],[1,24,"എങ്കിലും ഞാൻ ശരീരത്തിൽ ഇരിക്കുന്നത് നിങ്ങൾ നിമിത്തം ഏറെ ആവശ്യം.","eṅkiluṁ ñān śarīrattil irikkunnat niṅṅaḷ nimittaṁ ēṟe āvaśyaṁ.",null],[1,25,"ഇതിനെക്കുറിച്ച് ഉറച്ചുകൊണ്ട് നിങ്ങളുടെ വിശ്വാസത്തിന്‍റെ അഭിവൃദ്ധിക്കും സന്തോഷത്തിനുമായിത്തന്നെ ഞാൻ ജീവനോടിരിക്കും എന്നും നിങ്ങളോട് എല്ലാവരോടുംകൂടെ ഇരിക്കും എന്നും അറിയുന്നു.","itinekkuṟicc uṟaccukoṇṭ niṅṅaḷuṭe viśvāsattinṟe abhivr̥ddhikkuṁ santōṣattinumāyittanne ñān jīvanōṭirikkuṁ ennuṁ niṅṅaḷōṭ ellāvarōṭuṁkūṭe irikkuṁ ennuṁ aṟiyunnu.",null],[1,26,"അങ്ങനെ ഞാൻ നിങ്ങളുടെ അടുക്കൽ മടങ്ങിവരുന്നതിനാൽ, എന്നിലുള്ള നിങ്ങളുടെ പ്രശംസ ക്രിസ്തുയേശുവിൽ വർദ്ധിക്കുവാൻ ഇടയാകും.","aṅṅane ñān niṅṅaḷuṭe aṭukkal maṭaṅṅivarunnatināl, enniluḷḷa niṅṅaḷuṭe praśaṁsa kristuyēśuvil varddhikkuvān iṭayākuṁ.",null],[1,27,"ഞാൻ നിങ്ങളെ വന്ന് കണ്ടിട്ടോ, ദൂരത്തിരുന്നോ, നിങ്ങൾ ഏകാത്മാവിൽ ഉറച്ചുനിന്ന്, ഏകമനസ്സോടെ സുവിശേഷത്തിന്‍റെ വിശ്വാസത്തിനായി ഒന്നിച്ച് പോരാട്ടം കഴിക്കുന്നു എന്നു നിങ്ങളേക്കുറിച്ച് കേൾക്കേണ്ടതിന്, ക്രിസ്തുവിന്‍റെ സുവിശേഷത്തിന് യോഗ്യമാംവണ്ണം മാത്രം പെരുമാറുവിൻ.","ñān niṅṅaḷe vann kaṇṭiṭṭō, dūrattirunnō, niṅṅaḷ ēkātmāvil uṟaccuninn, ēkamanassōṭe suviśēṣattinṟe viśvāsattināyi onnicc pōrāṭṭaṁ kaḻikkunnu ennu niṅṅaḷēkkuṟicc kēḷkkēṇṭatin, kristuvinṟe suviśēṣattin yōgyamāṁvaṇṇaṁ mātraṁ perumāṟuvin.",null],[1,28,"നിങ്ങളെ എതിർക്കുന്നവരാൽ ഒന്നിലും ഭയപ്പെടേണ്ട; ഇത് അവരുടെ നാശത്തിനും നിങ്ങളുടെ രക്ഷയ്ക്കും ഒരു അടയാളമാകുന്നു;","niṅṅaḷe etirkkunnavarāl onniluṁ bhayappeṭēṇṭa; it avaruṭe nāśattinuṁ niṅṅaḷuṭe rakṣaykkuṁ oru aṭayāḷamākunnu;",null],[1,29,"അത് ദൈവത്തിൽ നിന്നുള്ളതാകുന്നു. എന്തെന്നാൽ, അവനിൽ വിശ്വസിക്കുവാൻ മാത്രമല്ല, അവനുവേണ്ടി കഷ്ടം അനുഭവിക്കുവാനും കൂടെ ഇത് നിങ്ങൾക്ക് ക്രിസ്തുനിമിത്തം അനുവദിച്ചിരിക്കുന്നു.","at daivattil ninnuḷḷatākunnu. entennāl, avanil viśvasikkuvān mātramalla, avanuvēṇṭi kaṣṭaṁ anubhavikkuvānuṁ kūṭe it niṅṅaḷkk kristunimittaṁ anuvadiccirikkunnu.",null],[1,30,"അങ്ങനെ നിങ്ങൾ എന്നിൽ കണ്ടതും ഇപ്പോൾ എന്നെക്കുറിച്ച് കേൾക്കുന്നതുമായ അതേ പോരാട്ടം നിങ്ങൾക്കും ഉണ്ടല്ലോ.","aṅṅane niṅṅaḷ ennil kaṇṭatuṁ ippōḷ ennekkuṟicc kēḷkkunnatumāya atē pōrāṭṭaṁ niṅṅaḷkkuṁ uṇṭallō.",null],[2,1,"അതുകൊണ്ട് ക്രിസ്തുവിൽ വല്ല പ്രബോധനവും ഉണ്ടെങ്കിൽ, സ്നേഹത്തിൻ്റെ വല്ല ആശ്വാസവും ഉണ്ടെങ്കിൽ, ആത്മാവിന്‍റെ വല്ല കൂട്ടായ്മയും ഉണ്ടെങ്കിൽ, വല്ല ആർദ്രതയും മനസ്സലിവും ഉണ്ടെങ്കിൽ,","atukoṇṭ kristuvil valla prabōdhanavuṁ uṇṭeṅkil, snēhattinṟe valla āśvāsavuṁ uṇṭeṅkil, ātmāvinṟe valla kūṭṭāymayuṁ uṇṭeṅkil, valla ārdratayuṁ manassalivuṁ uṇṭeṅkil,",null],[2,2,"നിങ്ങൾ ഏകമനസ്സുള്ളവരായി ഏകസ്നേഹം പൂണ്ട് ആത്മാവിൽ ഐകമത്യപ്പെട്ട് ഏക ഉദ്ദേശ്യമുള്ളവരായി എന്‍റെ സന്തോഷം പൂർണ്ണമാക്കുവിൻ.","niṅṅaḷ ēkamanassuḷḷavarāyi ēkasnēhaṁ pūṇṭ ātmāvil aikamatyappeṭṭ ēka uddēśyamuḷḷavarāyi enṟe santōṣaṁ pūrṇṇamākkuvin.",null],[2,3,"സ്വാർത്ഥതയാലോ ദുരഭിമാനത്താലോ ഒന്നും ചെയ്യാതെ, താഴ്മയോടെ ഓരോരുത്തൻ മറ്റുള്ളവരെ തന്നെക്കാൾ ശ്രേഷ്ഠൻ എന്നു എണ്ണിക്കൊള്ളുവിൻ.","svārtthatayālō durabhimānattālō onnuṁ ceyyāte, tāḻmayōṭe ōrōruttan maṟṟuḷḷavare tannekkāḷ śrēṣṭhan ennu eṇṇikkoḷḷuvin.",null],[2,4,"ഓരോരുത്തൻ സ്വന്ത താല്പര്യങ്ങളല്ല, എന്നാൽ മറ്റുള്ളവൻ്റെ താല്പര്യം കൂടെ നോക്കേണം.","ōrōruttan svanta tālparyaṅṅaḷalla, ennāl maṟṟuḷḷavanṟe tālparyaṁ kūṭe nōkkēṇaṁ.",null],[2,5,"ക്രിസ്തുയേശുവിലുള്ള മനോഭാവം തന്നെ നിങ്ങളിലും ഉണ്ടായിരിക്കട്ടെ.","kristuyēśuviluḷḷa manōbhāvaṁ tanne niṅṅaḷiluṁ uṇṭāyirikkaṭṭe.",null],[2,6,"അവൻ ദൈവരൂപത്തിൽ ഇരിക്കെ, ദൈവത്തോടുള്ള സമത്വം മുറുകെ പിടിച്ചുകൊള്ളേണം എന്നു വിചാരിക്കാതെ,","avan daivarūpattil irikke, daivattōṭuḷḷa samatvaṁ muṟuke piṭiccukoḷḷēṇaṁ ennu vicārikkāte,",null],[2,7,"തന്നെത്താൻ ശൂന്യമാക്കി, ദാസരൂപം എടുത്ത്, മനുഷ്യസാദൃശ്യത്തിലായി, വേഷത്തിൽ മനുഷ്യനായി കാണപ്പെട്ടു,","tannettān śūnyamākki, dāsarūpaṁ eṭutt, manuṣyasādr̥śyattilāyi, vēṣattil manuṣyanāyi kāṇappeṭṭu,",null],[2,8,"തന്നെത്താൻ താഴ്ത്തി മരണത്തോളം ക്രൂശിലെ മരണത്തോളം തന്നെ, അനുസരണമുള്ളവനായിത്തീർന്നു.","tannettān tāḻtti maraṇattōḷaṁ krūśile maraṇattōḷaṁ tanne, anusaraṇamuḷḷavanāyittīrnnu.",null],[2,9,"അതുകൊണ്ട് ദൈവവും അവനെ ഏറ്റവും ഉയർത്തുകയും സകലനാമത്തിനും മേലായ നാമം നൽകുകയും ചെയ്തു;","atukoṇṭ daivavuṁ avane ēṟṟavuṁ uyarttukayuṁ sakalanāmattinuṁ mēlāya nāmaṁ nalkukayuṁ ceytu;",null],[2,10,"അങ്ങനെ യേശുവിന്‍റെ നാമത്തിങ്കൽ സ്വർല്ലോകരുടെയും ഭൂലോകരുടെയും അധോലോകരുടെയും മുഴങ്കാൽ ഒക്കെയും മടങ്ങുകയും","aṅṅane yēśuvinṟe nāmattiṅkal svarllōkaruṭeyuṁ bhūlōkaruṭeyuṁ adhōlōkaruṭeyuṁ muḻaṅkāl okkeyuṁ maṭaṅṅukayuṁ",null],[2,11,"എല്ലാ നാവും “യേശുക്രിസ്തു ആകുന്നു കർത്താവ്” എന്നു പിതാവായ ദൈവത്തിന്‍റെ മഹത്വത്തിനായി ഏറ്റുപറയുകയും ചെയ്യും.","ellā nāvuṁ “yēśukristu ākunnu karttāv” ennu pitāvāya daivattinṟe mahatvattināyi ēṟṟupaṟayukayuṁ ceyyuṁ.",null],[2,12,"അതുകൊണ്ട്, പ്രിയമുള്ളവരേ, നിങ്ങൾ എല്ലായ്‌പ്പോഴും അനുസരിച്ചതുപോലെ എന്‍റെ സാന്നിദ്ധ്യത്തിൽ മാത്രമല്ല, എന്‍റെ അസാന്നിദ്ധ്യത്തിലും ഏറ്റവും അധികമായി ഭയത്തോടും വിറയലോടുംകൂടെ നിങ്ങളുടെ രക്ഷയ്ക്കായി പ്രവർത്തിക്കുവിൻ.","atukoṇṭ, priyamuḷḷavarē, niṅṅaḷ ellāyppōḻuṁ anusariccatupōle enṟe sānniddhyattil mātramalla, enṟe asānniddhyattiluṁ ēṟṟavuṁ adhikamāyi bhayattōṭuṁ viṟayalōṭuṁkūṭe niṅṅaḷuṭe rakṣaykkāyi pravarttikkuvin.",null],[2,13,"എന്തെന്നാൽ, തന്‍റെ പ്രസാദത്തിനുവേണ്ടി ഇച്ഛിക്കുവാനും പ്രവർത്തിക്കുവാനുമായി നിങ്ങളിൽ ദൈവമാണ് പ്രവർത്തിക്കുന്നത്.","entennāl, tanṟe prasādattinuvēṇṭi icchikkuvānuṁ pravarttikkuvānumāyi niṅṅaḷil daivamāṇ pravarttikkunnat.",null],[2,14,"വക്രവും വഴിപിഴച്ചതുമായ തലമുറയുടെ നടുവിൽ, നിങ്ങൾ അനിന്ദ്യരും പരമാർത്ഥികളുമായ, ദൈവത്തിന്‍റെ നിഷ്കളങ്കമക്കളും ആകേണ്ടതിന്, എല്ലാം പിറുപിറുപ്പും വാദവും കൂടാതെ ചെയ്യുവിൻ.","vakravuṁ vaḻipiḻaccatumāya talamuṟayuṭe naṭuvil, niṅṅaḷ anindyaruṁ paramārtthikaḷumāya, daivattinṟe niṣkaḷaṅkamakkaḷuṁ ākēṇṭatin, ellāṁ piṟupiṟuppuṁ vādavuṁ kūṭāte ceyyuvin.",null],[2,15,"അവരുടെ ഇടയിൽ നിങ്ങൾ ജീവന്‍റെ വചനം മുറുകെപ്പിടിച്ചുകൊണ്ട് ലോകത്തിൽ ജ്യോതിസ്സുകളെപ്പോലെ പ്രകാശിക്കുന്നു.","avaruṭe iṭayil niṅṅaḷ jīvanṟe vacanaṁ muṟukeppiṭiccukoṇṭ lōkattil jyōtissukaḷeppōle prakāśikkunnu.",null],[2,16,"അങ്ങനെ ഞാൻ ഓടിയതോ അദ്ധ്വാനിച്ചതോ വെറുതെയായില്ല എന്നു ക്രിസ്തുവിന്‍റെ നാളിൽ എനിക്ക് പ്രശംസിക്കുവാൻ കാരണമാകും.","aṅṅane ñān ōṭiyatō addhvāniccatō veṟuteyāyilla ennu kristuvinṟe nāḷil enikk praśaṁsikkuvān kāraṇamākuṁ.",null],[2,17,"എന്നാൽ നിങ്ങളുടെ വിശ്വാസത്തിന്‍റെ യാഗത്തിലും ശുശ്രൂഷയിലും പാനീയയാഗമായി എന്നെ ഒഴിക്കേണ്ടിവന്നാലും ഞാൻ സന്തോഷിക്കും; നിങ്ങളോട് എല്ലാവരോടുംകൂടെ സന്തോഷിക്കും.","ennāl niṅṅaḷuṭe viśvāsattinṟe yāgattiluṁ śuśrūṣayiluṁ pānīyayāgamāyi enne oḻikkēṇṭivannāluṁ ñān santōṣikkuṁ; niṅṅaḷōṭ ellāvarōṭuṁkūṭe santōṣikkuṁ.",null],[2,18,"അങ്ങനെ തന്നെ നിങ്ങളും സന്തോഷിക്കുവിൻ; എന്നോടുകൂടെ സന്തോഷിക്കുവിൻ.","aṅṅane tanne niṅṅaḷuṁ santōṣikkuvin; ennōṭukūṭe santōṣikkuvin.",null],[2,19,"എന്നാൽ നിങ്ങളുടെ അവസ്ഥ അറിഞ്ഞിട്ട് ഞാൻ ഉന്മേഷവാനാകേണ്ടതിന്, തിമൊഥെയൊസിനെ വേഗത്തിൽ അങ്ങോട്ട് അയയ്ക്കാം എന്നു കർത്താവായ യേശുവിൽ ആശിക്കുന്നു.","ennāl niṅṅaḷuṭe avastha aṟiññiṭṭ ñān unmēṣavānākēṇṭatin, timotheyosine vēgattil aṅṅōṭṭ ayaykkāṁ ennu karttāvāya yēśuvil āśikkunnu.",null],[2,20,"എന്തുകൊണ്ടെന്നാൽ നിങ്ങൾക്കുവേണ്ടി പരമാർത്ഥമായി കരുതുവാൻ അവനെപ്പോലെ എനിക്ക് മറ്റാരുമില്ല.","entukoṇṭennāl niṅṅaḷkkuvēṇṭi paramārtthamāyi karutuvān avaneppōle enikk maṟṟārumilla.",null],[2,21,"യേശുക്രിസ്തുവിന്‍റെ കാര്യമല്ല സ്വന്ത കാര്യമല്ലോ എല്ലാവരും നോക്കുന്നത്.","yēśukristuvinṟe kāryamalla svanta kāryamallō ellāvaruṁ nōkkunnat.",null],[2,22,"എന്നാൽ ഒരു മകൻ തന്‍റെ അപ്പനെ ശുശ്രൂഷിക്കുന്നതുപോലെ, എന്നോടുകൂടെ സുവിശേഷഘോഷണത്തിൽ സേവചെയ്ത് അവൻ യോഗ്യനെന്ന് തെളിയിച്ചത് നിങ്ങൾ അറിയുന്നുവല്ലോ.","ennāl oru makan tanṟe appane śuśrūṣikkunnatupōle, ennōṭukūṭe suviśēṣaghōṣaṇattil sēvaceyt avan yōgyanenn teḷiyiccat niṅṅaḷ aṟiyunnuvallō.",null],[2,23,"ആകയാൽ എന്‍റെ കാര്യം എങ്ങനെ ആകും എന്നു അറിയുന്ന ഉടനെ ഞാൻ അവനെ അയക്കുവാൻ ആശിക്കുന്നു.","ākayāl enṟe kāryaṁ eṅṅane ākuṁ ennu aṟiyunna uṭane ñān avane ayakkuvān āśikkunnu.",null],[2,24,"എന്നിരുന്നാലും ഞാൻ വേഗം വരും എന്നു കർത്താവിൽ ഉറച്ചിരിക്കുന്നു.","ennirunnāluṁ ñān vēgaṁ varuṁ ennu karttāvil uṟaccirikkunnu.",null],[2,25,"എന്നാൽ എന്‍റെ സഹോദരനും കൂട്ടുവേലക്കാരനും സഹഭടനും നിങ്ങളുടെ ദൂതനും എന്‍റെ ആവശ്യത്തിൽ ശുശ്രൂഷിച്ചവനുമായ എപ്പഫ്രൊദിത്തൊസിനെ നിങ്ങളുടെ അടുക്കൽ അയയ്ക്കുന്നത് അനിവാര്യം എന്നു എനിക്ക് തോന്നി.","ennāl enṟe sahōdaranuṁ kūṭṭuvēlakkāranuṁ sahabhaṭanuṁ niṅṅaḷuṭe dūtanuṁ enṟe āvaśyattil śuśrūṣiccavanumāya eppaphrodittosine niṅṅaḷuṭe aṭukkal ayaykkunnat anivāryaṁ ennu enikk tōnni.",null],[2,26,"എന്തുകൊണ്ടെന്നാൽ, അവൻ നിങ്ങളോട് എല്ലാവരോടുംകൂടെ ഇരിക്കുവാൻ വാഞ്ചിച്ചും, താൻ രോഗിയായി കിടന്നു എന്നു നിങ്ങൾ കേട്ടതുകൊണ്ട് വ്യസനിച്ചുമിരുന്നു.","entukoṇṭennāl, avan niṅṅaḷōṭ ellāvarōṭuṁkūṭe irikkuvān vāñciccuṁ, tān rōgiyāyi kiṭannu ennu niṅṅaḷ kēṭṭatukoṇṭ vyasaniccumirunnu.",null],[2,27,"അവൻ രോഗംപിടിച്ച് മരിക്കാറായിരുന്നു സത്യം; എങ്കിലും ദൈവം അവനോട് കരുണചെയ്തു; അവനോട് മാത്രമല്ല, എനിക്ക് ദുഃഖത്തിന്മേൽ ദുഃഖം വരാതിരിക്കുവാൻ എന്നോടും കരുണചെയ്തു.","avan rōgaṁpiṭicc marikkāṟāyirunnu satyaṁ; eṅkiluṁ daivaṁ avanōṭ karuṇaceytu; avanōṭ mātramalla, enikk duḥkhattinmēl duḥkhaṁ varātirikkuvān ennōṭuṁ karuṇaceytu.",null],[2,28,"ആകയാൽ നിങ്ങൾ അവനെ വീണ്ടും കാണുമ്പോൾ സന്തോഷിക്കുവാനും, എനിക്ക് ദുഃഖം കുറയുവാനും ഞാൻ അവനെ അധികം താല്പര്യത്തോടെ അയച്ചിരിക്കുന്നു.","ākayāl niṅṅaḷ avane vīṇṭuṁ kāṇumpōḷ santōṣikkuvānuṁ, enikk duḥkhaṁ kuṟayuvānuṁ ñān avane adhikaṁ tālparyattōṭe ayaccirikkunnu.",null],[2,29,"കർത്താവിൽ അവനെ പൂർണ്ണസന്തോഷത്തോടെ സ്വീകരിക്കുവിൻ; ഇങ്ങനെയുള്ളവരെ ബഹുമാനിതരായി കരുതുവിൻ.","karttāvil avane pūrṇṇasantōṣattōṭe svīkarikkuvin; iṅṅaneyuḷḷavare bahumānitarāyi karutuvin.",null],[2,30,"എന്തെന്നാൽ എനിക്ക് വേണ്ടിയുള്ള നിങ്ങളുടെ ശുശ്രൂഷയിലുള്ള കുറവ് തീർക്കുവാനായി അവൻ തന്‍റെ പ്രാണനെ അപകടത്തിലാക്കി, ക്രിസ്തുവിന്‍റെ വേലനിമിത്തം മരണത്തോളം ആയി.","entennāl enikk vēṇṭiyuḷḷa niṅṅaḷuṭe śuśrūṣayiluḷḷa kuṟav tīrkkuvānāyi avan tanṟe prāṇane apakaṭattilākki, kristuvinṟe vēlanimittaṁ maraṇattōḷaṁ āyi.",null],[3,1,"ഒടുവിൽ എന്‍റെ സഹോദരന്മാരേ, കർത്താവിൽ സന്തോഷിക്കുവിൻ. അതേ കാര്യം നിങ്ങൾക്ക് പിന്നെയും എഴുതുന്നതിൽ എനിക്ക് മടുപ്പില്ല; അത് നിങ്ങൾക്ക് സംരക്ഷണം ആകുന്നു.","oṭuvil enṟe sahōdaranmārē, karttāvil santōṣikkuvin. atē kāryaṁ niṅṅaḷkk pinneyuṁ eḻutunnatil enikk maṭuppilla; at niṅṅaḷkk saṁrakṣaṇaṁ ākunnu.",null],[3,2,"നായ്ക്കളെ സൂക്ഷിക്കുവിൻ; ദുഷ്ടവേലക്കാരെ സൂക്ഷിക്കുവിൻ; അംഗച്ഛേദനക്കാരെ സൂക്ഷിക്കുവിൻ.","nāykkaḷe sūkṣikkuvin; duṣṭavēlakkāre sūkṣikkuvin; aṁgacchēdanakkāre sūkṣikkuvin.",null],[3,3,"എന്തെന്നാൽ നാമല്ലോ സത്യപരിച്ഛേദനക്കാർ; ദൈവാത്മാവിൽ ആരാധിക്കുകയും ക്രിസ്തുയേശുവിൽ പ്രശംസിക്കുകയും ജഡത്തിൽ ആശ്രയിക്കാതിരിക്കുകയും ചെയ്യുന്ന നാം തന്നെ.","entennāl nāmallō satyaparicchēdanakkār; daivātmāvil ārādhikkukayuṁ kristuyēśuvil praśaṁsikkukayuṁ jaḍattil āśrayikkātirikkukayuṁ ceyyunna nāṁ tanne.",null],[3,4,"എന്നിരുന്നാലും, എനിക്ക് ജഡത്തിലും ആശ്രയിക്കുവാൻ വകയുണ്ട്; മറ്റാർക്കെങ്കിലും ജഡത്തിൽ ആശ്രയിക്കാം എന്നു തോന്നിയാൽ എനിക്ക് അധികം.","ennirunnāluṁ, enikk jaḍattiluṁ āśrayikkuvān vakayuṇṭ; maṟṟārkkeṅkiluṁ jaḍattil āśrayikkāṁ ennu tōnniyāl enikk adhikaṁ.",null],[3,5,"എട്ടാം നാളിൽ പരിച്ഛേദന ഏറ്റവൻ; യിസ്രായേൽ ജാതിക്കാരൻ; ബെന്യാമീൻ ഗോത്രക്കാരൻ; എബ്രായരിൽനിന്ന് ജനിച്ച എബ്രായൻ; ന്യായപ്രമാണം സംബന്ധിച്ച് പരീശൻ;","eṭṭāṁ nāḷil paricchēdana ēṟṟavan; yisrāyēl jātikkāran; benyāmīn gōtrakkāran; ebrāyarilninn janicca ebrāyan; nyāyapramāṇaṁ saṁbandhicc parīśan;",null],[3,6,"ശുഷ്കാന്തി സംബന്ധിച്ച് സഭയെ ഉപദ്രവിച്ചവൻ; ന്യായപ്രമാണത്തിലെ നീതി സംബന്ധിച്ച് അനിന്ദ്യൻ.","śuṣkānti saṁbandhicc sabhaye upadraviccavan; nyāyapramāṇattile nīti saṁbandhicc anindyan.",null],[3,7,"എങ്കിലും എനിക്ക് ലാഭമായിരുന്നത് ഒക്കെയും ഞാൻ ക്രിസ്തുനിമിത്തം നഷ്ടം എന്നു എണ്ണിയിരിക്കുന്നു.","eṅkiluṁ enikk lābhamāyirunnat okkeyuṁ ñān kristunimittaṁ naṣṭaṁ ennu eṇṇiyirikkunnu.",null],[3,8,"അത്രയുമല്ല, എന്‍റെ കർത്താവായ ക്രിസ്തുയേശുവിനെക്കുറിച്ചുള്ള പരിജ്ഞാനത്തിന്‍റെ ശ്രേഷ്ഠതനിമിത്തം ഞാൻ ഇപ്പോഴും എല്ലാം നഷ്ടം എന്നു എണ്ണുന്നു. അവനുവേണ്ടി ഞാൻ എല്ലാ നഷ്ടവും അനുഭവിക്കുകയും, ക്രിസ്തുവിനെ നേടേണ്ടതിനും,","atrayumalla, enṟe karttāvāya kristuyēśuvinekkuṟiccuḷḷa parijñānattinṟe śrēṣṭhatanimittaṁ ñān ippōḻuṁ ellāṁ naṣṭaṁ ennu eṇṇunnu. avanuvēṇṭi ñān ellā naṣṭavuṁ anubhavikkukayuṁ, kristuvine nēṭēṇṭatinuṁ,",null],[3,9,"ന്യായപ്രമാണത്തിൽനിന്നുള്ള എന്‍റെ സ്വന്തനീതിയല്ല, പ്രത്യുത, ക്രിസ്തുവിലുള്ള വിശ്വാസംമൂലം, ദൈവം വിശ്വാസത്തിന്‍റെ അടിസ്ഥാനത്തിൽ നൽകുന്ന നീതി തന്നെ ലഭിച്ച്,","nyāyapramāṇattilninnuḷḷa enṟe svantanītiyalla, pratyuta, kristuviluḷḷa viśvāsaṁmūlaṁ, daivaṁ viśvāsattinṟe aṭisthānattil nalkunna nīti tanne labhicc,",null],[3,10,"അവനിൽ ഇരിക്കേണ്ടതിനും, അവന്‍റെ മരണത്തിനോട് അനുരൂപപ്പെട്ടിട്ട് അവനെയും അവന്‍റെ പുനരുത്ഥാനത്തിൻ്റെ ശക്തിയെയും","avanil irikkēṇṭatinuṁ, avanṟe maraṇattinōṭ anurūpappeṭṭiṭṭ avaneyuṁ avanṟe punarutthānattinṟe śaktiyeyuṁ",null],[3,11,"അവന്‍റെ കഷ്ടാനുഭവങ്ങളുടെ കൂട്ടായ്മയെയും അറിയേണ്ടതിനും, അങ്ങനെ വല്ലവിധേനയും മരിച്ചവരുടെ ഇടയിൽനിന്നുള്ള പുനരുത്ഥാനം ഞാൻ പ്രാപിക്കേണ്ടതിനും തന്നെ സകലവും ചവറായി കണക്കാക്കുകയും ചെയ്യുന്നു.","avanṟe kaṣṭānubhavaṅṅaḷuṭe kūṭṭāymayeyuṁ aṟiyēṇṭatinuṁ, aṅṅane vallavidhēnayuṁ mariccavaruṭe iṭayilninnuḷḷa punarutthānaṁ ñān prāpikkēṇṭatinuṁ tanne sakalavuṁ cavaṟāyi kaṇakkākkukayuṁ ceyyunnu.",null],[3,12,"ഇവ ലഭിച്ചുകഴിഞ്ഞു എന്നോ തികഞ്ഞവനായി എന്നോ അല്ല, ഞാൻ ക്രിസ്തുയേശുവിനാൽ പിടിക്കപ്പെട്ടിരിക്കുന്നതുകൊണ്ട് എനിക്കും അത് പിടിക്കാമോ എന്നുവച്ച് പിന്തുടരുന്നതേയുള്ളു.","iva labhiccukaḻiññu ennō tikaññavanāyi ennō alla, ñān kristuyēśuvināl piṭikkappeṭṭirikkunnatukoṇṭ enikkuṁ at piṭikkāmō ennuvacc pintuṭarunnatēyuḷḷu.",null],[3,13,"സഹോദരന്മാരേ, ഞാൻ അത് പിടിച്ചിരിക്കുന്നു എന്നു നിരൂപിക്കുന്നില്ല.","sahōdaranmārē, ñān at piṭiccirikkunnu ennu nirūpikkunnilla.",null],[3,14,"എന്നാൽ ഒന്ന് ഞാൻ ചെയ്യുന്നു: പിമ്പിലുള്ളത് മറന്നും മുമ്പിലുള്ളതിനായി ആഞ്ഞുംകൊണ്ട്, ക്രിസ്തുയേശുവിൽ ദൈവത്തിന്‍റെ പരമവിളിയുടെ പ്രതിഫലത്തിനായി ലക്ഷ്യത്തിലേക്ക് ഓടുന്നു.","ennāl onn ñān ceyyunnu: pimpiluḷḷat maṟannuṁ mumpiluḷḷatināyi āññuṁkoṇṭ, kristuyēśuvil daivattinṟe paramaviḷiyuṭe pratiphalattināyi lakṣyattilēkk ōṭunnu.",null],[3,15,"നമ്മിൽ തികഞ്ഞവർക്ക് ഒക്കെയും ഈ മനോഭാവം ഉണ്ടാകട്ടെ; വല്ലതിലും നിങ്ങൾക്ക് വേറെ വിധമായി ചിന്തിച്ചാൽ ദൈവം അതും നിങ്ങൾക്ക് വെളിപ്പെടുത്തിത്തരും.","nammil tikaññavarkk okkeyuṁ ī manōbhāvaṁ uṇṭākaṭṭe; vallatiluṁ niṅṅaḷkk vēṟe vidhamāyi cinticcāl daivaṁ atuṁ niṅṅaḷkk veḷippeṭuttittaruṁ.",null],[3,16,"എന്നിരുന്നാലും നാം പ്രാപിച്ചിരിക്കുന്നതനുസരിച്ചു തന്നെ നടക്കുക.","ennirunnāluṁ nāṁ prāpiccirikkunnatanusariccu tanne naṭakkuka.",null],[3,17,"സഹോദരന്മാരേ, എന്നെ അനുകരിക്കുന്നതിൽ ചേരുക; ഞങ്ങൾ നിങ്ങൾക്ക് കാണിച്ച മാതൃകപ്രകാരം നടക്കുന്നവരെയും ശ്രദ്ധിച്ചുകൊള്ളുവിൻ.","sahōdaranmārē, enne anukarikkunnatil cēruka; ñaṅṅaḷ niṅṅaḷkk kāṇicca mātr̥kaprakāraṁ naṭakkunnavareyuṁ śraddhiccukoḷḷuvin.",null],[3,18,"എന്തെന്നാൽ, ഞാൻ പലപ്പോഴും നിങ്ങളോട് പറഞ്ഞതുപോലെ അനേകർ ക്രിസ്തുവിന്‍റെ ക്രൂശിൻ്റെ ശത്രുക്കളായിരിക്കുന്നു എന്നു ഇപ്പോൾ കരഞ്ഞുംകൊണ്ട് പറയുന്നു.","entennāl, ñān palappōḻuṁ niṅṅaḷōṭ paṟaññatupōle anēkar kristuvinṟe krūśinṟe śatrukkaḷāyirikkunnu ennu ippōḷ karaññuṁkoṇṭ paṟayunnu.",null],[3,19,"അവരുടെ അവസാനം നാശം; അവരുടെ ദൈവം വയറ്; ലജ്ജയായതിൽ അവർക്ക് മാനം തോന്നുന്നു; അവരുടെ മനസ്സ് ഭൂമിയിലുള്ള കാര്യങ്ങളിലാകുന്നു.","avaruṭe avasānaṁ nāśaṁ; avaruṭe daivaṁ vayaṟ; lajjayāyatil avarkk mānaṁ tōnnunnu; avaruṭe manass bhūmiyiluḷḷa kāryaṅṅaḷilākunnu.",null],[3,20,"നമ്മുടെ പൗരത്വമോ സ്വർഗ്ഗത്തിൽ ആകുന്നു; കർത്താവായ യേശുക്രിസ്തു എന്ന രക്ഷിതാവ് അവിടെനിന്നും വരുമെന്ന് നാം താല്പര്യത്തോടെ കാത്തിരിക്കുന്നു.","nammuṭe pauratvamō svarggattil ākunnu; karttāvāya yēśukristu enna rakṣitāv aviṭeninnuṁ varumenn nāṁ tālparyattōṭe kāttirikkunnu.",null],[3,21,"സകലവും തനിക്കു കീഴ്പെടുത്തുവാനും കഴിയുന്ന തന്‍റെ വ്യാപാരശക്തികൊണ്ട്, നമ്മുടെ താഴ്മയുള്ള ശരീരത്തെ, തന്‍റെ മഹത്വമുള്ള ശരീരത്തോടനുരൂപമായി അവൻ രൂപാന്തരപ്പെടുത്തും.","sakalavuṁ tanikku kīḻpeṭuttuvānuṁ kaḻiyunna tanṟe vyāpāraśaktikoṇṭ, nammuṭe tāḻmayuḷḷa śarīratte, tanṟe mahatvamuḷḷa śarīrattōṭanurūpamāyi avan rūpāntarappeṭuttuṁ.",null],[4,1,"അതുകൊണ്ട്, എന്‍റെ പ്രിയരും ഞാൻ കാണുവാൻ ആഗ്രഹിക്കുന്നവരുമായ സഹോദരന്മാരേ, എന്‍റെ സന്തോഷവും കിരീടവുമായുള്ളോരേ, പ്രിയമുള്ളവരേ, ഇങ്ങനെ കർത്താവിൽ ഉറച്ചുനിൽക്കുവിൻ.","atukoṇṭ, enṟe priyaruṁ ñān kāṇuvān āgrahikkunnavarumāya sahōdaranmārē, enṟe santōṣavuṁ kirīṭavumāyuḷḷōrē, priyamuḷḷavarē, iṅṅane karttāvil uṟaccunilkkuvin.",null],[4,2,"കർത്താവിൽ ഒരേ മനസ്സോടെയിരിക്കുവാൻ ഞാൻ യുവൊദ്യയെയോടും സുന്തുകയെയോടും പ്രബോധിപ്പിക്കുന്നു.","karttāvil orē manassōṭeyirikkuvān ñān yuvodyayeyōṭuṁ suntukayeyōṭuṁ prabōdhippikkunnu.",null],[4,3,"സാക്ഷാൽ എന്‍റെ വിശ്വസ്തരായ കൂട്ടുവേലക്കാരേ, ആ സ്ത്രീകളെ സഹായിക്കേണം എന്നു ഞാൻ നിന്നോടും അപേക്ഷിക്കുന്നു; ജീവപുസ്തകത്തിൽ പേരുള്ള ക്ലേമന്ത് മുതലായ എന്‍റെ കൂട്ടുവേലക്കാരോടൊന്നിച്ച്, അവർ എന്നോടുകൂടെ സുവിശേഷഘോഷണത്തിൽ അദ്ധ്വാനിച്ചിരിക്കുന്നു.","sākṣāl enṟe viśvastarāya kūṭṭuvēlakkārē, ā strīkaḷe sahāyikkēṇaṁ ennu ñān ninnōṭuṁ apēkṣikkunnu; jīvapustakattil pēruḷḷa klēmant mutalāya enṟe kūṭṭuvēlakkārōṭonnicc, avar ennōṭukūṭe suviśēṣaghōṣaṇattil addhvāniccirikkunnu.",null],[4,4,"കർത്താവിൽ എപ്പോഴും സന്തോഷിക്കുവിൻ; സന്തോഷിക്കുവിൻ എന്നു ഞാൻ പിന്നെയും പറയുന്നു.","karttāvil eppōḻuṁ santōṣikkuvin; santōṣikkuvin ennu ñān pinneyuṁ paṟayunnu.",null],[4,5,"നിങ്ങളുടെ സൗമ്യത സകല മനുഷ്യരും അറിയട്ടെ; കർത്താവ് വരുവാൻ അടുത്തിരിക്കുന്നു.","niṅṅaḷuṭe saumyata sakala manuṣyaruṁ aṟiyaṭṭe; karttāv varuvān aṭuttirikkunnu.",null],[4,6,"ഒന്നിനേക്കുറിച്ചും വിചാരപ്പെടരുത്; പ്രത്യുത, എല്ലാറ്റിലും പ്രാർത്ഥനയാലും യാചനയാലും നിങ്ങളുടെ അപേക്ഷകൾ സ്തോത്രത്തോടുകൂടെ ദൈവത്തോട് അറിയിക്കട്ടെ.","onninēkkuṟiccuṁ vicārappeṭarut; pratyuta, ellāṟṟiluṁ prārtthanayāluṁ yācanayāluṁ niṅṅaḷuṭe apēkṣakaḷ stōtrattōṭukūṭe daivattōṭ aṟiyikkaṭṭe.",null],[4,7,"എന്നാൽ സകല ബുദ്ധിയെയും കവിയുന്ന ദൈവസമാധാനം നിങ്ങളുടെ ഹൃദയങ്ങളെയും നിനവുകളെയും ക്രിസ്തുയേശുവിങ്കൽ കാക്കും.","ennāl sakala buddhiyeyuṁ kaviyunna daivasamādhānaṁ niṅṅaḷuṭe hr̥dayaṅṅaḷeyuṁ ninavukaḷeyuṁ kristuyēśuviṅkal kākkuṁ.",null],[4,8,"ഒടുവിൽ, സഹോദരന്മാരേ, സത്യമായത് ഒക്കെയും മാന്യമായത് ഒക്കെയും നീതിയായത് ഒക്കെയും നിർമ്മലമായത് ഒക്കെയും ഹൃദ്യമായത് ഒക്കെയും സത്ക്കീർത്തിയായത് ഒക്കെയും സൽഗുണമോ പുകഴ്ചയോ അത് ഒക്കെയും ചിന്തിച്ചുകൊള്ളുവിൻ.","oṭuvil, sahōdaranmārē, satyamāyat okkeyuṁ mānyamāyat okkeyuṁ nītiyāyat okkeyuṁ nirmmalamāyat okkeyuṁ hr̥dyamāyat okkeyuṁ satkkīrttiyāyat okkeyuṁ salguṇamō pukaḻcayō at okkeyuṁ cinticcukoḷḷuvin.",null],[4,9,"എന്നോട് പഠിച്ചും ഗ്രഹിച്ചും കേട്ടും കണ്ടുമുള്ള കാര്യങ്ങൾ പ്രവർത്തിക്കുവിൻ; എന്നാൽ സമാധാനത്തിന്‍റെ ദൈവം നിങ്ങളോടുകൂടെ ഇരിക്കും.","ennōṭ paṭhiccuṁ grahiccuṁ kēṭṭuṁ kaṇṭumuḷḷa kāryaṅṅaḷ pravarttikkuvin; ennāl samādhānattinṟe daivaṁ niṅṅaḷōṭukūṭe irikkuṁ.",null],[4,10,"നിങ്ങൾ പിന്നെയും എനിക്ക് വേണ്ടി വിചാരിക്കുവാൻ തുടങ്ങിയതിനാൽ ഞാൻ കർത്താവിൽ വളരെ സന്തോഷിച്ചു; മുമ്പെ തന്നെ നിങ്ങൾക്ക് വിചാരമുണ്ടായിരുന്നു. എങ്കിലും സഹായിക്കുവാൻ അവസരം കിട്ടിയില്ല.","niṅṅaḷ pinneyuṁ enikk vēṇṭi vicārikkuvān tuṭaṅṅiyatināl ñān karttāvil vaḷare santōṣiccu; mumpe tanne niṅṅaḷkk vicāramuṇṭāyirunnu. eṅkiluṁ sahāyikkuvān avasaraṁ kiṭṭiyilla.",null],[4,11,"ആവശ്യം നിമിത്തമല്ല ഞാൻ പറയുന്നത്; എന്തെന്നാൽ ഏത് സാഹചര്യത്തിലും സംതൃപ്തിയോടിരിക്കുവാൻ ഞാൻ പഠിച്ചിട്ടുണ്ട്.","āvaśyaṁ nimittamalla ñān paṟayunnat; entennāl ēt sāhacaryattiluṁ saṁtr̥ptiyōṭirikkuvān ñān paṭhicciṭṭuṇṭ.",null],[4,12,"താഴ്ചയിൽ എങ്ങനെ ഇരിക്കേണം എന്നും സമൃദ്ധിയിൽ എങ്ങനെ ജീവിക്കണമെന്നും എനിക്കറിയാം; തൃപ്തനായിരിക്കുന്നതിൻ്റെയും വിശന്നിരിക്കുന്നതിൻ്റെയും സമൃദ്ധിയിൽ ഇരിക്കുന്നതിൻ്റെയും ബുദ്ധിമുട്ട് അനുഭവിക്കുന്നതിൻ്റെയും രഹസ്യം എന്തെന്ന് എല്ലാ സാഹചര്യങ്ങളിലും ഞാൻ പഠിച്ചിരിക്കുന്നു.","tāḻcayil eṅṅane irikkēṇaṁ ennuṁ samr̥ddhiyil eṅṅane jīvikkaṇamennuṁ enikkaṟiyāṁ; tr̥ptanāyirikkunnatinṟeyuṁ viśannirikkunnatinṟeyuṁ samr̥ddhiyil irikkunnatinṟeyuṁ buddhimuṭṭ anubhavikkunnatinṟeyuṁ rahasyaṁ entenn ellā sāhacaryaṅṅaḷiluṁ ñān paṭhiccirikkunnu.",null],[4,13,"എന്നെ ശക്തനാക്കുന്നവൻ മുഖാന്തരം എനിക്ക് എല്ലാം ചെയ്യുവാൻ കഴിയും.","enne śaktanākkunnavan mukhāntaraṁ enikk ellāṁ ceyyuvān kaḻiyuṁ.",null],[4,14,"എങ്കിലും എന്‍റെ കഷ്ടതയിൽ നിങ്ങൾ കൂട്ടായ്മ കാണിച്ചത് നന്നായി.","eṅkiluṁ enṟe kaṣṭatayil niṅṅaḷ kūṭṭāyma kāṇiccat nannāyi.",null],[4,15,"ഫിലിപ്പ്യരേ, സുവിശേഷഘോഷണത്തിൻ്റെ ആരംഭത്തിൽ ഞാൻ മക്കെദോന്യയിൽനിന്ന് പുറപ്പെട്ടപ്പോൾ നിങ്ങൾ മാത്രമല്ലാതെ ഒരു സഭയും വരവുചെലവുകാര്യത്തിൽ എന്നോട് കൂട്ടായ്മ കാണിച്ചില്ല എന്നു നിങ്ങളും അറിയുന്നു.","philippyarē, suviśēṣaghōṣaṇattinṟe āraṁbhattil ñān makkedōnyayilninn puṟappeṭṭappōḷ niṅṅaḷ mātramallāte oru sabhayuṁ varavucelavukāryattil ennōṭ kūṭṭāyma kāṇiccilla ennu niṅṅaḷuṁ aṟiyunnu.",null],[4,16,"എന്തെന്നാൽ ഞാൻ തെസ്സലോനീക്യയിൽ ആയിരുന്നപ്പോൾ പോലും എന്‍റെ ആവശ്യങ്ങൾക്ക് നിങ്ങൾ ഒന്നിലധികം തവണ അയച്ചുതന്നുവല്ലോ.","entennāl ñān tessalōnīkyayil āyirunnappōḷ pōluṁ enṟe āvaśyaṅṅaḷkk niṅṅaḷ onniladhikaṁ tavaṇa ayaccutannuvallō.",null],[4,17,"ഞാൻ ദാനം അന്വേഷിക്കുന്നു എന്നല്ല, നിങ്ങളുടെ കണക്കിലേക്ക് ഏറുന്ന പ്രതിഫലം അത്രേ അന്വേഷിക്കുന്നത്.","ñān dānaṁ anvēṣikkunnu ennalla, niṅṅaḷuṭe kaṇakkilēkk ēṟunna pratiphalaṁ atrē anvēṣikkunnat.",null],[4,18,"എന്നാൽ എനിക്ക് വേണ്ടുന്നത് എല്ലാം ഉണ്ട്; സമൃദ്ധിയായുമിരിക്കുന്നു; നിങ്ങൾ അയച്ചുതന്നത് സൗരഭ്യവാസനയായി, ദൈവത്തിന് പ്രസാദമായ ഒരു സ്വീകാര്യയാഗമായി എപ്പഫ്രൊദിത്തൊസിൽനിന്ന് ഞാൻ സ്വീകരിച്ച് തൃപ്തനായിരിക്കുന്നു.","ennāl enikk vēṇṭunnat ellāṁ uṇṭ; samr̥ddhiyāyumirikkunnu; niṅṅaḷ ayaccutannat saurabhyavāsanayāyi, daivattin prasādamāya oru svīkāryayāgamāyi eppaphrodittosilninn ñān svīkaricc tr̥ptanāyirikkunnu.",null],[4,19,"എന്‍റെ ദൈവമോ നിങ്ങളുടെ ആവശ്യങ്ങളൊക്കെയും തന്‍റെ മഹത്വത്തിന്‍റെ ധനത്തിനൊത്തവണ്ണം ക്രിസ്തുയേശുവിൽ നൽകിത്തരും.","enṟe daivamō niṅṅaḷuṭe āvaśyaṅṅaḷokkeyuṁ tanṟe mahatvattinṟe dhanattinottavaṇṇaṁ kristuyēśuvil nalkittaruṁ.",null],[4,20,"ഇപ്പോൾ നമ്മുടെ ദൈവവും പിതാവുമായവന് എന്നെന്നേക്കും മഹത്വം. ആമേൻ.","ippōḷ nammuṭe daivavuṁ pitāvumāyavan ennennēkkuṁ mahatvaṁ. āmēn.",null],[4,21,"ക്രിസ്തുയേശുവിലുള്ള ഓരോ വിശുദ്ധർക്കും വന്ദനം ചെയ്യുവിൻ. എന്നോടുകൂടെയുള്ള സഹോദരന്മാർ നിങ്ങളെ വന്ദനം ചെയ്യുന്നു.","kristuyēśuviluḷḷa ōrō viśuddharkkuṁ vandanaṁ ceyyuvin. ennōṭukūṭeyuḷḷa sahōdaranmār niṅṅaḷe vandanaṁ ceyyunnu.",null],[4,22,"വിശുദ്ധന്മാർ എല്ലാവരും, വിശേഷാൽ കൈസരുടെ കൊട്ടാരത്തിലുള്ളവരും നിങ്ങളെ വന്ദനം ചെയ്യുന്നു.","viśuddhanmār ellāvaruṁ, viśēṣāl kaisaruṭe koṭṭārattiluḷḷavaruṁ niṅṅaḷe vandanaṁ ceyyunnu.",null],[4,23,"കർത്താവായ യേശുക്രിസ്തുവിന്‍റെ കൃപ നിങ്ങളുടെ ആത്മാവിനോടുകൂടെ ഇരിക്കുമാറാകട്ടെ.","karttāvāya yēśukristuvinṟe kr̥pa niṅṅaḷuṭe ātmāvinōṭukūṭe irikkumāṟākaṭṭe.",null]],"mar":[[1,1,"पौल व तीमथ्य, ख्रिस्त येशूचे दास ह्यांच्याकडून; फिलिपै शहरातील ख्रिस्त येशूमध्ये जे पवित्र आहेत, त्या सर्वांना आणि त्यांच्याबरोबर अध्यक्ष व सेवक ह्यास सलाम;","paula va tīmathya, khrista yēśūcē dāsa hyāṁcyākaḍūna; philipai śaharātīla khrista yēśūmadhyē jē pavitra āhēta, tyā sarvāṁnā āṇi tyāṁcyābarōbara adhyakṣa va sēvaka hyāsa salāma;",null],[1,2,"देव आपला पिता व प्रभू येशू ख्रिस्त ह्याच्याद्वारे तुम्हास कृपा व शांती असो.","dēva āpalā pitā va prabhū yēśū khrista hyācyādvārē tumhāsa kr̥pā va śāṁtī asō.",null],[1,3,"मला तुमची जी एकंदर आठवण आहे तिच्यावरून मी आपल्या देवाचे आभार मानतो.","malā tumacī jī ēkaṁdara āṭhavaṇa āhē ticyāvarūna mī āpalyā dēvācē ābhāra mānatō.",null],[1,4,"माझ्या प्रत्येक प्रार्थनेत मी तुमच्यामधील सर्वांसाठी आनंदाने प्रार्थना करतो;","mājhyā pratyēka prārthanēta mī tumacyāmadhīla sarvāṁsāṭhī ānaṁdānē prārthanā karatō;",null],[1,5,"पहिल्या दिवसापासून आतापर्यंत तुमची शुभवर्तमानाच्या प्रसारात जी सहभागिता आहे तिच्यामुळे देवाची उपकारस्तुती करतो.","pahilyā divasāpāsūna ātāparyaṁta tumacī śubhavartamānācyā prasārāta jī sahabhāgitā āhē ticyāmuḷē dēvācī upakārastutī karatō.",null],[1,6,"आणि ज्याने तुमच्यात चांगले काम आरंभले तो ते येशू ख्रिस्ताच्या दिवसापर्यंत पूर्णतेस नेईल हा माझा विश्वास आहे.","āṇi jyānē tumacyāta cāṁgalē kāma āraṁbhalē tō tē yēśū khristācyā divasāparyaṁta pūrṇatēsa nēīla hā mājhā viśvāsa āhē.",null],[1,7,"आणि तुम्हा सर्वांविषयी मला असे वाटणे योग्यच आहे कारण माझ्या बंधनात आणि शुभवर्तमानासंबंधीच्या प्रत्युत्तरात व समर्थनात तुम्ही सर्व माझ्याबरोबर कृपेतील सहभागी असल्यामुळे, मी आपल्या अंतःकरणात, तुम्हास बाळगून आहे.","āṇi tumhā sarvāṁviṣayī malā asē vāṭaṇē yōgyaca āhē kāraṇa mājhyā baṁdhanāta āṇi śubhavartamānāsaṁbaṁdhīcyā pratyuttarāta va samarthanāta tumhī sarva mājhyābarōbara kr̥pētīla sahabhāgī asalyāmuḷē, mī āpalyā aṁtaḥkaraṇāta, tumhāsa bāḷagūna āhē.",null],[1,8,"देव माझा साक्षी आहे की, मला ख्रिस्त येशूच्या कळवळ्यात सर्वांविषयी किती उत्कंठा लागली आहे,","dēva mājhā sākṣī āhē kī, malā khrista yēśūcyā kaḷavaḷyāta sarvāṁviṣayī kitī utkaṁṭhā lāgalī āhē,",null],[1,9,"मी अशी प्रार्थना करतो की, तुमची प्रीती ज्ञानात व पूर्ण सारासार विचारात आणखी अधिकाधिक वाढत जावी,","mī aśī prārthanā karatō kī, tumacī prītī jñānāta va pūrṇa sārāsāra vicārāta āṇakhī adhikādhika vāḍhata jāvī,",null],[1,10,"यासाठी की जे श्रेष्ठ ते तुम्ही पसंत करावे आणि तुम्ही ख्रिस्ताच्या दिवसासाठी निर्मळ व निर्दोष असावे.","yāsāṭhī kī jē śrēṣṭha tē tumhī pasaṁta karāvē āṇi tumhī khristācyā divasāsāṭhī nirmaḷa va nirdōṣa asāvē.",null],[1,11,"आणि देवाचे गौरव व स्तुती व्हावी म्हणून येशू ख्रिस्ताच्या द्वारे जे नीतिमत्त्वाचे फळ त्याने भरून जावे.","āṇi dēvācē gaurava va stutī vhāvī mhaṇūna yēśū khristācyā dvārē jē nītimattvācē phaḷa tyānē bharūna jāvē.",null],[1,12,"माझ्या बंधूंनो, माझ्याविषयी ज्या गोष्टी घडल्या त्यांच्यापासून शुभवर्तमानाला अडथळा न होता त्या तिच्या प्रगतीला साधनीभूत झाल्या हे तुम्ही समजावे अशी माझी इच्छा आहे.","mājhyā baṁdhūṁnō, mājhyāviṣayī jyā gōṣṭī ghaḍalyā tyāṁcyāpāsūna śubhavartamānālā aḍathaḷā na hōtā tyā ticyā pragatīlā sādhanībhūta jhālyā hē tumhī samajāvē aśī mājhī icchā āhē.",null],[1,13,"म्हणजे कैसराच्या हुजुरातीच्या राजवाड्याचे रक्षक व इतर सर्व जणांत, त्यामुळे माझे बंधने ख्रिस्तासंबंधाने आहेत हे सर्वांना प्रसिद्ध झाले;","mhaṇajē kaisarācyā hujurātīcyā rājavāḍyācē rakṣaka va itara sarva jaṇāṁta, tyāmuḷē mājhē baṁdhanē khristāsaṁbaṁdhānē āhēta hē sarvāṁnā prasiddha jhālē;",null],[1,14,"आणि माझ्या बंधनामुळे प्रभूमधील पुष्कळ बंधूंची खातरी होऊन, ते निर्भयपणे वचन सांगण्यात अधिक धीट झाले आहेत.","āṇi mājhyā baṁdhanāmuḷē prabhūmadhīla puṣkaḷa baṁdhūṁcī khātarī hōūna, tē nirbhayapaṇē vacana sāṁgaṇyāta adhika dhīṭa jhālē āhēta.",null],[1,15,"कित्येक मत्सराने व वैरभावानेही ख्रिस्ताची घोषणा करीत आहेत; आणि काही खरोखर सदिच्छेने करीत आहेत.","kityēka matsarānē va vairabhāvānēhī khristācī ghōṣaṇā karīta āhēta; āṇi kāhī kharōkhara sadicchēnē karīta āhēta.",null],[1,16,"मी शुभवर्तमानासंबंधी प्रत्युत्तर देण्यास नेमलेला आहे हे ओळखून ते ती प्रीतीने करतात.","mī śubhavartamānāsaṁbaṁdhī pratyuttara dēṇyāsa nēmalēlā āhē hē ōḷakhūna tē tī prītīnē karatāta.",null],[1,17,"पण इतर आहेत ते माझी बंधने अधिक संकटाची व्हावी अशा इच्छेने तट पाडण्याकरिता दुजाभावाने ख्रिस्ताची घोषणा करतात.","paṇa itara āhēta tē mājhī baṁdhanē adhika saṁkaṭācī vhāvī aśā icchēnē taṭa pāḍaṇyākaritā dujābhāvānē khristācī ghōṣaṇā karatāta.",null],[1,18,"ह्यापासून काय झाले? निमित्ताने असो किंवा खरेपणाने, सर्व प्रकारे ख्रिस्ताची घोषणा होते हेच, ह्यात मी आनंद करतो व करणारच.","hyāpāsūna kāya jhālē? nimittānē asō kiṁvā kharēpaṇānē, sarva prakārē khristācī ghōṣaṇā hōtē hēca, hyāta mī ānaṁda karatō va karaṇāraca.",null],[1,19,"कारण मी जाणतो की हे, तुमच्या प्रार्थनेने व येशू ख्रिस्ताच्या आत्म्याच्या पुरवठ्याने माझ्या उद्धारास कारण होईल.","kāraṇa mī jāṇatō kī hē, tumacyā prārthanēnē va yēśū khristācyā ātmyācyā puravaṭhyānē mājhyā uddhārāsa kāraṇa hōīla.",null],[1,20,"कारण माझी उत्कट अपेक्षा व आशा आहे की, मी कशानेही लाजणार नाही तर पूर्ण धैर्याने, नेहमीप्रमाणे आतादेखील जगण्याने किंवा मरण्याने माझ्या शरीराद्वारे ख्रिस्ताचा महिमा होईल.","kāraṇa mājhī utkaṭa apēkṣā va āśā āhē kī, mī kaśānēhī lājaṇāra nāhī tara pūrṇa dhairyānē, nēhamīpramāṇē ātādēkhīla jagaṇyānē kiṁvā maraṇyānē mājhyā śarīrādvārē khristācā mahimā hōīla.",null],[1,21,"कारण मला तर जगणे हे ख्रिस्त आणि मरणे हे लाभ आहे.","kāraṇa malā tara jagaṇē hē khrista āṇi maraṇē hē lābha āhē.",null],[1,22,"पण जर मी देहात जगणे हे माझ्या कामाचे फळ आहे; तर, कोणते निवडावे हे मला समजत नाही.","paṇa jara mī dēhāta jagaṇē hē mājhyā kāmācē phaḷa āhē; tara, kōṇatē nivaḍāvē hē malā samajata nāhī.",null],[1,23,"कारण मी दोघासंबंधाने पेचात आहे; येथून सुटून जाऊन ख्रिस्ताजवळ असण्याची मला उत्कंठा आहे कारण देहात राहण्यापेक्षा हे अधिक चांगले आहे;","kāraṇa mī dōghāsaṁbaṁdhānē pēcāta āhē; yēthūna suṭūna jāūna khristājavaḷa asaṇyācī malā utkaṁṭhā āhē kāraṇa dēhāta rāhaṇyāpēkṣā hē adhika cāṁgalē āhē;",null],[1,24,"तरीही, मला देहात राहणे हे तुमच्यासाठी अधिक आवश्यक आहे.","tarīhī, malā dēhāta rāhaṇē hē tumacyāsāṭhī adhika āvaśyaka āhē.",null],[1,25,"मला अशी खातरी वाटत असल्यामुळे मी राहणार आहे आणि विश्वासात तुमची प्रगती व आनंद व्हावा म्हणून मी तुम्हा सर्वांजवळ राहणार हे मला ठाऊक आहे.","malā aśī khātarī vāṭata asalyāmuḷē mī rāhaṇāra āhē āṇi viśvāsāta tumacī pragatī va ānaṁda vhāvā mhaṇūna mī tumhā sarvāṁjavaḷa rāhaṇāra hē malā ṭhāūka āhē.",null],[1,26,"हे अशासाठी की तुम्हाकडे माझे पुन्हा येणे झाल्याने माझ्यामुळे ख्रिस्त येशूच्या ठायी अभिमान बाळगण्याचे तुम्हास अधिक कारण व्हावे.","hē aśāsāṭhī kī tumhākaḍē mājhē punhā yēṇē jhālyānē mājhyāmuḷē khrista yēśūcyā ṭhāyī abhimāna bāḷagaṇyācē tumhāsa adhika kāraṇa vhāvē.",null],[1,27,"सांगावयाचे ते इतकेच की ख्रिस्ताच्या शुभवर्तमानास शोभेल असे आचरण ठेवा; म्हणजे मी येऊन तुम्हास भेटलो किंवा मी दूर असलो, तरी मला तुमच्याबाबतीत हे ऐकता यावे की, तुम्ही एकजिवाने राहून शुभवर्तमानाच्या विश्वासासाठी, एकजुटीने लढत स्थिर राहता.","sāṁgāvayācē tē itakēca kī khristācyā śubhavartamānāsa śōbhēla asē ācaraṇa ṭhēvā; mhaṇajē mī yēūna tumhāsa bhēṭalō kiṁvā mī dūra asalō, tarī malā tumacyābābatīta hē aikatā yāvē kī, tumhī ēkajivānē rāhūna śubhavartamānācyā viśvāsāsāṭhī, ēkajuṭīnē laḍhata sthira rāhatā.",null],[1,28,"आणि विरोध करणार्‍या लोकांकडून कशाविषयीही भयभीत झाला नाही, हे त्यांना त्यांच्या नाशाचे पण तुमच्या तारणाचे प्रमाण आहे व हे देवापासून आहे.","āṇi virōdha karaṇāryā lōkāṁkaḍūna kaśāviṣayīhī bhayabhīta jhālā nāhī, hē tyāṁnā tyāṁcyā nāśācē paṇa tumacyā tāraṇācē pramāṇa āhē va hē dēvāpāsūna āhē.",null],[1,29,"कारण त्याच्यावर विश्वास ठेवावा इतकेच केवळ नव्हे, तर ख्रिस्ताच्या वतीने त्याच्याकरता तुम्हास दुःख ही सोसावे अशी कृपा तुमच्यावर झाली आहे.","kāraṇa tyācyāvara viśvāsa ṭhēvāvā itakēca kēvaḷa navhē, tara khristācyā vatīnē tyācyākaratā tumhāsa duḥkha hī sōsāvē aśī kr̥pā tumacyāvara jhālī āhē.",null],[1,30,"मी जे युद्ध केले ते तुम्ही बघितले आहे व मी जे करीत आहे म्हणून ऐकता, तेच तुम्हीही करीत आहात.","mī jē yuddha kēlē tē tumhī baghitalē āhē va mī jē karīta āhē mhaṇūna aikatā, tēca tumhīhī karīta āhāta.",null],[2,1,"ह्यावरून ख्रिस्ताच्या ठायी काही आश्वासन, प्रीतीचे काही सांत्वन, आत्म्याची काही सहभागिता, काही कळवळा व करूणा ही जर आहेत,","hyāvarūna khristācyā ṭhāyī kāhī āśvāsana, prītīcē kāhī sāṁtvana, ātmyācī kāhī sahabhāgitā, kāhī kaḷavaḷā va karūṇā hī jara āhēta,",null],[2,2,"तर तुम्ही समचित्त व्हा, एकमेकांवर सारखीच प्रीती करा आणि एकजीव होऊन एकमनाचे व्हा. अशाप्रकारे माझा आनंद पूर्ण करा.","tara tumhī samacitta vhā, ēkamēkāṁvara sārakhīca prītī karā āṇi ēkajīva hōūna ēkamanācē vhā. aśāprakārē mājhā ānaṁda pūrṇa karā.",null],[2,3,"आणि तुम्ही विरोधाने किंवा पोकळ अभिमानाने काही करू नका, पण मनाच्या लीनतेने आपल्यापेक्षा एकमेकांना मोठे मानावे.","āṇi tumhī virōdhānē kiṁvā pōkaḷa abhimānānē kāhī karū nakā, paṇa manācyā līnatēnē āpalyāpēkṣā ēkamēkāṁnā mōṭhē mānāvē.",null],[2,4,"तुम्ही कोणीही आपलेच हित पाहू नका, तर दुसर्‍यांचेहि पाहा.","tumhī kōṇīhī āpalēca hita pāhū nakā, tara dusaryāṁcēhi pāhā.",null],[2,5,"अशी जी चित्तवृत्ती ख्रिस्त येशूच्या ठायी होती ती तुमच्याठायीही असो.","aśī jī cittavr̥ttī khrista yēśūcyā ṭhāyī hōtī tī tumacyāṭhāyīhī asō.",null],[2,6,"तो देवाच्या स्वरूपाचा असूनही, त्याने आपण देवाच्या बरोबरीचे असणे हा लाभ आहे असे त्याने मानले नाही,","tō dēvācyā svarūpācā asūnahī, tyānē āpaṇa dēvācyā barōbarīcē asaṇē hā lābha āhē asē tyānē mānalē nāhī,",null],[2,7,"तर स्वतःला रिकामे केले, म्हणजे मनुष्याच्या प्रतिरूपाचे होऊन दासाचे स्वरूप धारण केले,","tara svataḥlā rikāmē kēlē, mhaṇajē manuṣyācyā pratirūpācē hōūna dāsācē svarūpa dhāraṇa kēlē,",null],[2,8,"आणि मनुष्य प्रकृतीचे असे प्रकट होऊन त्याने स्वतःला लीन केले आणि त्याने मरण आणि तेही वधस्तंभावरचे मरण सोसले; येथपर्यंत आज्ञापालन करून त्याने स्वतःला लीन केले.","āṇi manuṣya prakr̥tīcē asē prakaṭa hōūna tyānē svataḥlā līna kēlē āṇi tyānē maraṇa āṇi tēhī vadhastaṁbhāvaracē maraṇa sōsalē; yēthaparyaṁta ājñāpālana karūna tyānē svataḥlā līna kēlē.",null],[2,9,"ह्यामुळे देवाने त्यास सर्वांहून उंच केले आहे आणि सर्व नावांहून श्रेष्ठ नाव ते त्यास दिले आहे.","hyāmuḷē dēvānē tyāsa sarvāṁhūna uṁca kēlē āhē āṇi sarva nāvāṁhūna śrēṣṭha nāva tē tyāsa dilē āhē.",null],[2,10,"ह्यात हेतू हा की, स्वर्गात, पृथ्वीवर व पृथ्वीखाली प्रत्येक गुडघा येशूच्या नावाने टेकला जावा,","hyāta hētū hā kī, svargāta, pr̥thvīvara va pr̥thvīkhālī pratyēka guḍaghā yēśūcyā nāvānē ṭēkalā jāvā,",null],[2,11,"आणि हे देवपिताच्या गौरवासाठी प्रत्येक जीभेने येशू ख्रिस्त हा प्रभू आहे असे कबूल करावे.","āṇi hē dēvapitācyā gauravāsāṭhī pratyēka jībhēnē yēśū khrista hā prabhū āhē asē kabūla karāvē.",null],[2,12,"म्हणून माझ्या प्रियांनो, जे तुम्ही सर्वदा आज्ञापालन करीत आला आहा, ते तुम्ही मी जवळ असता केवळ नव्हे तर विषेशकरून आता, म्हणजे मी जवळ नसताही, भीत व कांपत आपले तारण साधून घ्या.","mhaṇūna mājhyā priyāṁnō, jē tumhī sarvadā ājñāpālana karīta ālā āhā, tē tumhī mī javaḷa asatā kēvaḷa navhē tara viṣēśakarūna ātā, mhaṇajē mī javaḷa nasatāhī, bhīta va kāṁpata āpalē tāraṇa sādhūna ghyā.",null],[2,13,"कारण इच्छा करणे आणि कार्य करणे तुमच्या ठायी आपल्या सुयोजनेसाठी साधून देणारा तो देव आहे.","kāraṇa icchā karaṇē āṇi kārya karaṇē tumacyā ṭhāyī āpalyā suyōjanēsāṭhī sādhūna dēṇārā tō dēva āhē.",null],[2,14,"जे काही तुम्ही कराल कुरकुर आणि वादविवाद न करता करा;","jē kāhī tumhī karāla kurakura āṇi vādavivāda na karatā karā;",null],[2,15,"ह्यासाठी की, या कुटिल आणि विपरीत पिढीमध्ये तुम्ही निर्दोष व निरुपद्रवी देवाची निष्कलंक मुले असे व्हावे; त्या लोकांमध्ये तुम्ही जीवनाचे वचन पुढे करून दाखवतांना ज्योतीसारखे जगात दिसता.","hyāsāṭhī kī, yā kuṭila āṇi viparīta piḍhīmadhyē tumhī nirdōṣa va nirupadravī dēvācī niṣkalaṁka mulē asē vhāvē; tyā lōkāṁmadhyē tumhī jīvanācē vacana puḍhē karūna dākhavatāṁnā jyōtīsārakhē jagāta disatā.",null],[2,16,"जीवनाच्या वचनास दृढ धरुन राहा, असे झाले तर माझे धावणे व्यर्थ झाले नाही व माझे श्रमही व्यर्थ झाले नाहीत असा अभिमान मला ख्रिस्ताच्या दिवशी बाळगण्यास कारण होईल.","jīvanācyā vacanāsa dr̥ḍha dharuna rāhā, asē jhālē tara mājhē dhāvaṇē vyartha jhālē nāhī va mājhē śramahī vyartha jhālē nāhīta asā abhimāna malā khristācyā divaśī bāḷagaṇyāsa kāraṇa hōīla.",null],[2,17,"तुमच्या विश्वासाचा यज्ञ व सेवा, होतांना जरी मी अर्पिला जात आहे तरी मी त्याबद्दल आनंद मानतो व तुम्हा सर्वांबरोबर आनंद करतो;","tumacyā viśvāsācā yajña va sēvā, hōtāṁnā jarī mī arpilā jāta āhē tarī mī tyābaddala ānaṁda mānatō va tumhā sarvāṁbarōbara ānaṁda karatō;",null],[2,18,"आणि त्याचाच तुम्हीही आनंद माना व माझ्याबरोबर आनंद करा.","āṇi tyācāca tumhīhī ānaṁda mānā va mājhyābarōbara ānaṁda karā.",null],[2,19,"प्रभू येशूमध्ये मी आशा करतो की, लवकरच मी तीमथ्याला तुमच्याकडे पाठवेन म्हणजे, तुम्हा विषयीच्या गोष्टी जाणून माझे समाधान होईल.","prabhū yēśūmadhyē mī āśā karatō kī, lavakaraca mī tīmathyālā tumacyākaḍē pāṭhavēna mhaṇajē, tumhā viṣayīcyā gōṣṭī jāṇūna mājhē samādhāna hōīla.",null],[2,20,"कारण तुमच्या विषयीच्या गोष्टीची खरी काळजी करील असा, दुसरा कोणी समान वृतीचा माझ्याजवळ नाही;","kāraṇa tumacyā viṣayīcyā gōṣṭīcī kharī kāḷajī karīla asā, dusarā kōṇī samāna vr̥tīcā mājhyājavaḷa nāhī;",null],[2,21,"कारण, सगळे स्वतःच्याच गोष्टी पाहतात, ख्रिस्त येशूच्या पाहत नाहीत.","kāraṇa, sagaḷē svataḥcyāca gōṣṭī pāhatāta, khrista yēśūcyā pāhata nāhīta.",null],[2,22,"पण तुम्ही त्याचे शील हे जाणता की, जसा मुलगा पित्याबरोबर सेवा करतो, तशी त्याने शुभवर्तमानासाठी माझ्याबरोबर सेवा केली.","paṇa tumhī tyācē śīla hē jāṇatā kī, jasā mulagā pityābarōbara sēvā karatō, taśī tyānē śubhavartamānāsāṭhī mājhyābarōbara sēvā kēlī.",null],[2,23,"म्हणून माझे काय होईल ते दिसून येताच, त्यास रवाना करता येईल अशी मी आशा करतो.","mhaṇūna mājhē kāya hōīla tē disūna yētāca, tyāsa ravānā karatā yēīla aśī mī āśā karatō.",null],[2,24,"पण मीही स्वतः लवकरच येईन असा प्रभूमध्ये मला विश्वास आहे.","paṇa mīhī svataḥ lavakaraca yēīna asā prabhūmadhyē malā viśvāsa āhē.",null],[2,25,"तरी मला माझा बंधू आणि सहकारी व सहसैनिक आणि तुमचा प्रेषित आणि माझी गरज भागवून माझी सेवा करणारा एपफ्रदीत ह्याला तुमच्याकडे पाठविण्याचे आवश्यक वाटले.","tarī malā mājhā baṁdhū āṇi sahakārī va sahasainika āṇi tumacā prēṣita āṇi mājhī garaja bhāgavūna mājhī sēvā karaṇārā ēpaphradīta hyālā tumacyākaḍē pāṭhaviṇyācē āvaśyaka vāṭalē.",null],[2,26,"कारण तो आजारी आहे हे तुम्ही ऐकले होते असे त्यास समजल्यावर त्यास तुम्हा सर्वांची हुरहुर लागून तो चिंताक्रांत अस्वस्थ झाला होता;","kāraṇa tō ājārī āhē hē tumhī aikalē hōtē asē tyāsa samajalyāvara tyāsa tumhā sarvāṁcī hurahura lāgūna tō ciṁtākrāṁta asvastha jhālā hōtā;",null],[2,27,"तो खरोखर, मरणाजवळ आला होता पण देवाने त्याच्यावर दया केली आणि केवळ त्याच्यावर नाही तर, मला दुःखावर दुःख होऊ नये म्हणून माझ्यावरही केली.","tō kharōkhara, maraṇājavaḷa ālā hōtā paṇa dēvānē tyācyāvara dayā kēlī āṇi kēvaḷa tyācyāvara nāhī tara, malā duḥkhāvara duḥkha hōū nayē mhaṇūna mājhyāvarahī kēlī.",null],[2,28,"म्हणून, मी त्यास पाठविण्याची अधिक घाई केली, म्हणजे त्यास पुन्हा भेटून तुम्ही आनंद करावा आणि माझे दुःख कमी व्हावे म्हणून हे केले.","mhaṇūna, mī tyāsa pāṭhaviṇyācī adhika ghāī kēlī, mhaṇajē tyāsa punhā bhēṭūna tumhī ānaṁda karāvā āṇi mājhē duḥkha kamī vhāvē mhaṇūna hē kēlē.",null],[2,29,"ह्यावरून पूर्ण आनंदाने तुम्ही त्याचे प्रभूमध्ये स्वागत करा. अशांचा मान राखा.","hyāvarūna pūrṇa ānaṁdānē tumhī tyācē prabhūmadhyē svāgata karā. aśāṁcā māna rākhā.",null],[2,30,"कारण माझी सेवा करण्यांत तुमच्या हातून जी कसूर झाली ती भरून काढावी म्हणून ख्रिस्त सेवेसाठी त्याने स्वतःचा जीव धोक्यात घातला व तो मरता मरता वाचला.","kāraṇa mājhī sēvā karaṇyāṁta tumacyā hātūna jī kasūra jhālī tī bharūna kāḍhāvī mhaṇūna khrista sēvēsāṭhī tyānē svataḥcā jīva dhōkyāta ghātalā va tō maratā maratā vācalā.",null],[3,1,"शेवटी, माझ्या बंधूंनो, प्रभूमध्ये आनंद करा. तुम्हास पुन्हा लिहिण्यास मी कंटाळा करीत नाही, पण ते तुमच्या सुरक्षितपणाचे आहे.","śēvaṭī, mājhyā baṁdhūṁnō, prabhūmadhyē ānaṁda karā. tumhāsa punhā lihiṇyāsa mī kaṁṭāḷā karīta nāhī, paṇa tē tumacyā surakṣitapaṇācē āhē.",null],[3,2,"त्या कुत्र्यांपासून सावध राहा. वाईट काम करणार्‍यांपासून सावध राहा. केवळ दैहिक सुंता झालेल्या लोकांविषयी सावध राहा.","tyā kutryāṁpāsūna sāvadha rāhā. vāīṭa kāma karaṇāryāṁpāsūna sāvadha rāhā. kēvaḷa daihika suṁtā jhālēlyā lōkāṁviṣayī sāvadha rāhā.",null],[3,3,"कारण आपण जे देवाच्या आत्म्याने देवाची उपासना करतो, जे ख्रिस्त येशूविषयी अभिमान बाळगणारे आणि देहावर विश्वास न ठेवणारे ते आपण सुंता झालेलेच आहोत.","kāraṇa āpaṇa jē dēvācyā ātmyānē dēvācī upāsanā karatō, jē khrista yēśūviṣayī abhimāna bāḷagaṇārē āṇi dēhāvara viśvāsa na ṭhēvaṇārē tē āpaṇa suṁtā jhālēlēca āhōta.",null],[3,4,"तरी देहावरही भरंवसा ठेवण्यास मला जागा आहे. आपल्याला देहावर भरंवसा ठेवता येईल असे जर दुसऱ्या कोणाला वाटत असेल तर मला तसे अधिक वाटणार.","tarī dēhāvarahī bharaṁvasā ṭhēvaṇyāsa malā jāgā āhē. āpalyālā dēhāvara bharaṁvasā ṭhēvatā yēīla asē jara dusaṟyā kōṇālā vāṭata asēla tara malā tasē adhika vāṭaṇāra.",null],[3,5,"मी तर आठव्या दिवशी सुंता झालेला, इस्राएल लोकातला, बन्यामीन वंशातला, इब्य्रांचा इब्री, नियमशास्त्रदृष्टीने परूशी;","mī tara āṭhavyā divaśī suṁtā jhālēlā, isrāēla lōkātalā, banyāmīna vaṁśātalā, ibyrāṁcā ibrī, niyamaśāstradr̥ṣṭīnē parūśī;",null],[3,6,"आस्थेविषयी म्हणाल तर मंडळीचा छळ करणारा आणि नियमशास्त्रातील नीतिमत्त्वाविषयी निर्दोष ठरलेला असा आहे.","āsthēviṣayī mhaṇāla tara maṁḍaḷīcā chaḷa karaṇārā āṇi niyamaśāstrātīla nītimattvāviṣayī nirdōṣa ṭharalēlā asā āhē.",null],[3,7,"तरी मला ज्या गोष्टी लाभाच्या होत्या त्या मी ख्रिस्तामुळे हानीच्या अशा समजलो आहे.","tarī malā jyā gōṣṭī lābhācyā hōtyā tyā mī khristāmuḷē hānīcyā aśā samajalō āhē.",null],[3,8,"इतकेच नाही, तर ख्रिस्त येशू माझा प्रभू ह्याच्याविषयीच्या ज्ञानाच्या श्रेष्ठत्वामुळे मी सर्वकाही हानी समजतो. त्याच्यासाठी मी सर्व गोष्टींची हानी सोसली आणि मी त्या केरकचरा लेखतो, ह्यासाठी की, मला ख्रिस्त येशू हा लाभ प्राप्त व्हावा.","itakēca nāhī, tara khrista yēśū mājhā prabhū hyācyāviṣayīcyā jñānācyā śrēṣṭhatvāmuḷē mī sarvakāhī hānī samajatō. tyācyāsāṭhī mī sarva gōṣṭīṁcī hānī sōsalī āṇi mī tyā kērakacarā lēkhatō, hyāsāṭhī kī, malā khrista yēśū hā lābha prāpta vhāvā.",null],[3,9,"आणि मी त्याच्याठायी आढळावे आणि माझे नीतिमत्त्व माझे स्वतःचे नव्हे म्हणजे नियमशास्त्राच्या योगे मिळणारे नीतिमत्त्व नव्हे तर ते ख्रिस्तावरील विश्वासाद्वारे, म्हणजे देवाकडून विश्वासाद्वारे मिळणारे नीतिमत्त्व असे असावे.","āṇi mī tyācyāṭhāyī āḍhaḷāvē āṇi mājhē nītimattva mājhē svataḥcē navhē mhaṇajē niyamaśāstrācyā yōgē miḷaṇārē nītimattva navhē tara tē khristāvarīla viśvāsādvārē, mhaṇajē dēvākaḍūna viśvāsādvārē miḷaṇārē nītimattva asē asāvē.",null],[3,10,"हे अशासाठी आहे की, तो व त्याच्या पुनरुत्थानाचे सामर्थ्याचे व त्याच्या दुःखांची सहभागिता ह्यांची, त्याच्या मरणाशी एकरूप होऊन, मी ओळख करून घ्यावी.","hē aśāsāṭhī āhē kī, tō va tyācyā punarutthānācē sāmarthyācē va tyācyā duḥkhāṁcī sahabhāgitā hyāṁcī, tyācyā maraṇāśī ēkarūpa hōūna, mī ōḷakha karūna ghyāvī.",null],[3,11,"म्हणजे कसेही करून मी मृतांमधून पुनरुत्थान मिळवावे.","mhaṇajē kasēhī karūna mī mr̥tāṁmadhūna punarutthāna miḷavāvē.",null],[3,12,"मी आताच जणू मिळवले आहे किंवा मी आताच पूर्ण झालो आहे असे नाही. पण मी ज्यासाठी ख्रिस्त येशूने मला आपल्या ताब्यात घेतले ते मी आपल्या ताब्यात घ्यावे म्हणून मी त्याच्यामागे लागलो आहे.","mī ātāca jaṇū miḷavalē āhē kiṁvā mī ātāca pūrṇa jhālō āhē asē nāhī. paṇa mī jyāsāṭhī khrista yēśūnē malā āpalyā tābyāta ghētalē tē mī āpalyā tābyāta ghyāvē mhaṇūna mī tyācyāmāgē lāgalō āhē.",null],[3,13,"बंधूंनो, मी ते आपल्या ताब्यात घेतले असे मानीत नाही पण मी हीच एक गोष्ट करतो की, मागील गोष्टी विसरून जाऊन आणि पुढील गोष्टींवर लक्ष लावून,","baṁdhūṁnō, mī tē āpalyā tābyāta ghētalē asē mānīta nāhī paṇa mī hīca ēka gōṣṭa karatō kī, māgīla gōṣṭī visarūna jāūna āṇi puḍhīla gōṣṭīṁvara lakṣa lāvūna,",null],[3,14,"ख्रिस्त येशूच्या ठायी देवाचे जे वरील पाचारण त्या संबंधीचे बक्षिस मिळविण्यासाठी पुढच्या मर्यादेवरील खुणेकडे मी धावतो. हेच एक माझे काम.","khrista yēśūcyā ṭhāyī dēvācē jē varīla pācāraṇa tyā saṁbaṁdhīcē bakṣisa miḷaviṇyāsāṭhī puḍhacyā maryādēvarīla khuṇēkaḍē mī dhāvatō. hēca ēka mājhē kāma.",null],[3,15,"तर जेवढे आपण प्रौढ आहोत, तेवढ्यांनी हीच चित्तवृत्ती ठेवावी आणि तुम्ही एखाद्या गोष्टीविषयी निराळी चित्तवृत्ती ठेवली, तरी देव तेही तुम्हास प्रकट करील.","tara jēvaḍhē āpaṇa prauḍha āhōta, tēvaḍhyāṁnī hīca cittavr̥ttī ṭhēvāvī āṇi tumhī ēkhādyā gōṣṭīviṣayī nirāḷī cittavr̥ttī ṭhēvalī, tarī dēva tēhī tumhāsa prakaṭa karīla.",null],[3,16,"तथापि आपण ज्या विचाराने येथवर मजल मारली तिच्याप्रमाणे पुढे चालावे.","tathāpi āpaṇa jyā vicārānē yēthavara majala māralī ticyāpramāṇē puḍhē cālāvē.",null],[3,17,"बंधूंनो, तुम्ही सर्वजण माझे अनुकरण करणारे व्हा आणि आम्ही तुम्हास कित्ता घालून दिल्याप्रमाणे जे चालतात, त्यांच्याकडे लक्ष द्या.","baṁdhūṁnō, tumhī sarvajaṇa mājhē anukaraṇa karaṇārē vhā āṇi āmhī tumhāsa kittā ghālūna dilyāpramāṇē jē cālatāta, tyāṁcyākaḍē lakṣa dyā.",null],[3,18,"कारण मी तुम्हास, पुष्कळ वेळा, सांगितले आणि आता रडत सांगतो की, पुष्कळजण असे चालतात की, ते ख्रिस्ताच्या वधस्तंभाचे वैरी आहेत.","kāraṇa mī tumhāsa, puṣkaḷa vēḷā, sāṁgitalē āṇi ātā raḍata sāṁgatō kī, puṣkaḷajaṇa asē cālatāta kī, tē khristācyā vadhastaṁbhācē vairī āhēta.",null],[3,19,"नाश हा त्यांचा शेवट, पोट हे त्यांचे दैवत, त्यांचा निर्लज्जपणा हे त्यांचे भुषण आहे, ते जगिक गोष्टींवर चित्त ठेवतात.","nāśa hā tyāṁcā śēvaṭa, pōṭa hē tyāṁcē daivata, tyāṁcā nirlajjapaṇā hē tyāṁcē bhuṣaṇa āhē, tē jagika gōṣṭīṁvara citta ṭhēvatāta.",null],[3,20,"आपले नागरिकत्व तर स्वर्गात आहे; तेथून प्रभू येशू ख्रिस्त हा तारणारा येणार आहे; त्याची आपण वाट पाहत आहोत.","āpalē nāgarikatva tara svargāta āhē; tēthūna prabhū yēśū khrista hā tāraṇārā yēṇāra āhē; tyācī āpaṇa vāṭa pāhata āhōta.",null],[3,21,"ज्या सामर्थ्याने तो सर्वकाही आपल्या स्वाधीन करण्यास समर्थ आहे त्या सामर्थ्यांने तो तुमचे आमचे नीच स्थितीचे शरीर आपल्या गौरवीच्या शरीरासारखे व्हावे म्हणून त्यांचे रूपांतर करील.","jyā sāmarthyānē tō sarvakāhī āpalyā svādhīna karaṇyāsa samartha āhē tyā sāmarthyāṁnē tō tumacē āmacē nīca sthitīcē śarīra āpalyā gauravīcyā śarīrāsārakhē vhāvē mhaṇūna tyāṁcē rūpāṁtara karīla.",null],[4,1,"म्हणून माझ्या प्रियजनहो, मी ज्यांच्यासाठी उत्कंठित आहे ते तुम्ही माझा आनंद व मुकुट आहात म्हणून माझ्या प्रिय बंधूंनो, तुम्ही प्रभूमध्ये तसेच स्थिर राहा.","mhaṇūna mājhyā priyajanahō, mī jyāṁcyāsāṭhī utkaṁṭhita āhē tē tumhī mājhā ānaṁda va mukuṭa āhāta mhaṇūna mājhyā priya baṁdhūṁnō, tumhī prabhūmadhyē tasēca sthira rāhā.",null],[4,2,"मी युवदीयेला विनंती करतो आणि सुंतुखेला विनंती करतो की, तुम्ही प्रभूच्या ठायी एकमनाचे व्हा.","mī yuvadīyēlā vinaṁtī karatō āṇi suṁtukhēlā vinaṁtī karatō kī, tumhī prabhūcyā ṭhāyī ēkamanācē vhā.",null],[4,3,"आणि हे माझ्या खऱ्या सोबत्या पण मी तुलाही विनवितो की, तू या स्त्रियांनी माझ्याबरोबर आणि क्लेमेंत व ज्यांची नावे जीवनाच्या पुस्तकात लिहिलेली आहेत असे माझे सहकारी ह्यांच्याबरोबर शुभवर्तमानाच्या कामी श्रम केले त्यांना साहाय्य कर.","āṇi hē mājhyā khaṟyā sōbatyā paṇa mī tulāhī vinavitō kī, tū yā striyāṁnī mājhyābarōbara āṇi klēmēṁta va jyāṁcī nāvē jīvanācyā pustakāta lihilēlī āhēta asē mājhē sahakārī hyāṁcyābarōbara śubhavartamānācyā kāmī śrama kēlē tyāṁnā sāhāyya kara.",null],[4,4,"प्रभूमध्ये सर्वदा आनंद करा; पुन्हा सांगतो, आनंद करा.","prabhūmadhyē sarvadā ānaṁda karā; punhā sāṁgatō, ānaṁda karā.",null],[4,5,"सर्व लोकांस तुमची सहनशीलता कळून येवो; प्रभू समीप आहे.","sarva lōkāṁsa tumacī sahanaśīlatā kaḷūna yēvō; prabhū samīpa āhē.",null],[4,6,"कशा ही विषयाची काळजी करू नका पण प्रार्थना आणि विनंती करून आभारप्रदर्शनासह आपली मागणी देवाला कळवा;","kaśā hī viṣayācī kāḷajī karū nakā paṇa prārthanā āṇi vinaṁtī karūna ābhārapradarśanāsaha āpalī māgaṇī dēvālā kaḷavā;",null],[4,7,"म्हणजे सर्व बुद्धीसामर्थ्याच्या पलीकडे असलेली देवाची दिलेली शांती तुमची अंतःकरणे व तुमचे विचार ख्रिस्त येशूच्या ठायी राखील.","mhaṇajē sarva buddhīsāmarthyācyā palīkaḍē asalēlī dēvācī dilēlī śāṁtī tumacī aṁtaḥkaraṇē va tumacē vicāra khrista yēśūcyā ṭhāyī rākhīla.",null],[4,8,"बंधूंनो, शेवटी इतके सांगतो की, जे काही खरे आहे, जे काही आदरणीय आहे, जे काही न्याय्य आहे, जे काही शुद्ध आहे, जे काही प्रशंसनीय, जे काही श्रवणीय, जो काही सद्गुण, जी काही स्तुती, त्यावर विचार करा.","baṁdhūṁnō, śēvaṭī itakē sāṁgatō kī, jē kāhī kharē āhē, jē kāhī ādaraṇīya āhē, jē kāhī nyāyya āhē, jē kāhī śuddha āhē, jē kāhī praśaṁsanīya, jē kāhī śravaṇīya, jō kāhī sadguṇa, jī kāhī stutī, tyāvara vicāra karā.",null],[4,9,"माझ्यापासून जे तुम्ही शिकला, जे स्वीकारले व माझे जे ऐकले व पाहिले ते तुम्ही आचरीत राहा आणि शांतीदाता देव तुमच्याबरोबर राहील.","mājhyāpāsūna jē tumhī śikalā, jē svīkāralē va mājhē jē aikalē va pāhilē tē tumhī ācarīta rāhā āṇi śāṁtīdātā dēva tumacyābarōbara rāhīla.",null],[4,10,"मला प्रभूमध्ये फार आनंद झाला. आता तुमची माझ्याविषयीची काळजी पुन्हा जागृत झाली. ही काळजी तुम्ही करीतच होता, पण तुम्हास संधी नव्हती.","malā prabhūmadhyē phāra ānaṁda jhālā. ātā tumacī mājhyāviṣayīcī kāḷajī punhā jāgr̥ta jhālī. hī kāḷajī tumhī karītaca hōtā, paṇa tumhāsa saṁdhī navhatī.",null],[4,11,"मला काही कमी पडल्यामुळे मी बोलत आहे असे नाही, कारण मी असेन त्या स्थितीत संतुष्ट राहण्यास शिकलो आहे.","malā kāhī kamī paḍalyāmuḷē mī bōlata āhē asē nāhī, kāraṇa mī asēna tyā sthitīta saṁtuṣṭa rāhaṇyāsa śikalō āhē.",null],[4,12,"दीन अवस्थेत कसे रहावे हे मी जाणतो आणि विपुलतेत कसे रहावे हेही मी जाणतो; कसेही व कोणत्याही परिस्थितीत, तृप्त होण्यास तसेच उपाशी राहण्यास, विपुलतेत राहण्यास तसेच गरजेत राहण्यास मला शिक्षण मिळाले आहे.","dīna avasthēta kasē rahāvē hē mī jāṇatō āṇi vipulatēta kasē rahāvē hēhī mī jāṇatō; kasēhī va kōṇatyāhī paristhitīta, tr̥pta hōṇyāsa tasēca upāśī rāhaṇyāsa, vipulatēta rāhaṇyāsa tasēca garajēta rāhaṇyāsa malā śikṣaṇa miḷālē āhē.",null],[4,13,"आणि मला जो सामर्थ्य देतो त्याच्याकडून मी सर्वकाही करावयास शक्तीमान आहे.","āṇi malā jō sāmarthya dētō tyācyākaḍūna mī sarvakāhī karāvayāsa śaktīmāna āhē.",null],[4,14,"पण माझ्या दुःखात तुम्ही सहभागी झालात हे तुम्ही चांगले केलेत.","paṇa mājhyā duḥkhāta tumhī sahabhāgī jhālāta hē tumhī cāṁgalē kēlēta.",null],[4,15,"फिलिप्पैकरांनो, तुम्ही जाणता की, शुभवर्तमानाच्या प्रारंभी जेव्हा मी मासेदोनियामधून निघालो, तेव्हा तुमच्याशिवाय कोणतीच मंडळी माझ्याबरोबर देण्याघेण्याच्या बाबतीत माझी भागीदार झाली नाही.","philippaikarāṁnō, tumhī jāṇatā kī, śubhavartamānācyā prāraṁbhī jēvhā mī māsēdōniyāmadhūna nighālō, tēvhā tumacyāśivāya kōṇatīca maṁḍaḷī mājhyābarōbara dēṇyāghēṇyācyā bābatīta mājhī bhāgīdāra jhālī nāhī.",null],[4,16,"मी थेस्सलनीकात होतो तेव्हा तुम्ही एकदाच नाही दुसर्‍यांदाही माझी गरज भागविली.","mī thēssalanīkāta hōtō tēvhā tumhī ēkadāca nāhī dusaryāṁdāhī mājhī garaja bhāgavilī.",null],[4,17,"मी देणगीची अपेक्षा करतो असे नाही पण तुमच्या हिशोबी जमेची बाजू वाढावी अशी इच्छा करतो.","mī dēṇagīcī apēkṣā karatō asē nāhī paṇa tumacyā hiśōbī jamēcī bājū vāḍhāvī aśī icchā karatō.",null],[4,18,"पण माझ्याजवळ सर्वकाही आहे आणि विपुल आहे आणि एपफ्रदीताच्या हाती तुम्ही जे पाठवले ते मिळाल्याने मला भरपूर झाले आहे. ते जणू काय सुगंध, असे देवाला मान्य व संतोषकारक अर्पण असे आहे.","paṇa mājhyājavaḷa sarvakāhī āhē āṇi vipula āhē āṇi ēpaphradītācyā hātī tumhī jē pāṭhavalē tē miḷālyānē malā bharapūra jhālē āhē. tē jaṇū kāya sugaṁdha, asē dēvālā mānya va saṁtōṣakāraka arpaṇa asē āhē.",null],[4,19,"माझा देव आपल्या संपत्यनुरूप तुमची गरज ख्रिस्त येशूच्या ठायी गौरवाच्याद्वारे पुरवील.","mājhā dēva āpalyā saṁpatyanurūpa tumacī garaja khrista yēśūcyā ṭhāyī gauravācyādvārē puravīla.",null],[4,20,"आपला देवपिता ह्याला युगानुयुग गौरव असो. आमेन.","āpalā dēvapitā hyālā yugānuyuga gaurava asō. āmēna.",null],[4,21,"ख्रिस्त येशूतील सर्व पवित्र जनांस सलाम सांगा. माझ्याबरोबरचे बंधू तुम्हास सलाम सांगतात.","khrista yēśūtīla sarva pavitra janāṁsa salāma sāṁgā. mājhyābarōbaracē baṁdhū tumhāsa salāma sāṁgatāta.",null],[4,22,"सर्व पवित्रजन आणि विशेषतः कैसराच्या घरचे तुम्हास सलाम सांगतात.","sarva pavitrajana āṇi viśēṣataḥ kaisarācyā gharacē tumhāsa salāma sāṁgatāta.",null],[4,23,"प्रभू येशू ख्रिस्ताची कृपा तुमच्या आत्म्याबरोबर असो.","prabhū yēśū khristācī kr̥pā tumacyā ātmyābarōbara asō.",null]],"npiulb":[[1,1,"ख्रीष्‍ट येशूका दासहरू पावल र तिमोथीबाट, फिलिप्‍पीमा भएका ख्रीष्‍ट येशूमा अलग गरिएकाहरू सबै, अनि बिशप र डिकनहरूलाई ।","khrīṣṭa yēśūkā dāsaharū pāvala ra timōthībāṭa, philippīmā bhaēkā khrīṣṭa yēśūmā alaga gariēkāharū sabai, ani biśapa ra ḍikanaharūlāī .",null],[1,2,"परमेश्‍वर हाम्रा पिता र प्रभु येशू ख्रीष्‍टबाट तिमीहरूलाई अनुग्रह र शान्ति ।","paramēśvara hāmrā pitā ra prabhu yēśū khrīṣṭabāṭa timīharūlāī anugraha ra śānti .",null],[1,3,"हर समय तिमीहरूको सम्झना गर्दा, म मेरा परमेश्‍वरलाई धन्यवाद दिन्छु ।","hara samaya timīharūkō samjhanā gardā, ma mērā paramēśvaralāī dhanyavāda dinchu .",null],[1,4,"तिमीहरू सबैका निम्ति मेरो हरेक प्रार्थनामा म आनन्दसाथ प्रार्थना गर्दछु ।","timīharū sabaikā nimti mērō harēka prārthanāmā ma ānandasātha prārthanā gardachu .",null],[1,5,"पहिलो दिनदेखि अहिलेसम्म सुसमाचारमा तिमीहरूको सहभागिताको लागि म धन्यवाद दिन्छु ।","pahilō dinadēkhi ahilēsamma susamācāramā timīharūkō sahabhāgitākō lāgi ma dhanyavāda dinchu .",null],[1,6,"म यो कुरामा निश्‍चित छु, कि तिमीहरूमा यो असल कामलाई प्रारम्भ गर्नुहुनेले येशू ख्रीष्‍टको दिनसम्म यसलाई पुरा गर्न निरन्तरता दिनुहुनेछ ।","ma yō kurāmā niścita chu, ki timīharūmā yō asala kāmalāī prārambha garnuhunēlē yēśū khrīṣṭakō dinasamma yasalāī purā garna nirantaratā dinuhunēcha .",null],[1,7,"तिमीहरू सबैका निम्ति मैले यस्तो प्रकारले विचार गर्नु मेरो निम्ति उचित छ, किनकि मैले तिमीहरू सबैलाई मेरो हृदयमा राखेको छु । मेरो कैदमा र सुसमाचारको समर्थन एवम् निश्‍चयता दुवैमा तिमीहरू सबै अनुग्रहमा मेरा साझेदारहरू भएका छौ ।","timīharū sabaikā nimti mailē yastō prakāralē vicāra garnu mērō nimti ucita cha, kinaki mailē timīharū sabailāī mērō hr̥dayamā rākhēkō chu . mērō kaidamā ra susamācārakō samarthana ēvam niścayatā duvaimā timīharū sabai anugrahamā mērā sājhēdāraharū bhaēkā chau .",null],[1,8,"किनकि ख्रीष्‍ट येशूको प्रेमको गहिराइमा म तिमीहरूका निम्ति कति तृष्णा गर्दछु भन्‍ने कुरामा परमेश्‍वर मेरो साक्षी हुनुहुन्छ ।","kinaki khrīṣṭa yēśūkō prēmakō gahirāimā ma timīharūkā nimti kati tr̥ṣṇā gardachu bhannē kurāmā paramēśvara mērō sākṣī hunuhuncha .",null],[1,9,"र मैले यस्तो भन्दै प्रार्थना गरिरहेको छु, कि ज्ञान र सम्पूर्ण समझमा तिमीहरूको प्रेम झनझन प्रशस्त हुँदै जाओस् ।","ra mailē yastō bhandai prārthanā garirahēkō chu, ki jñāna ra sampūrṇa samajhamā timīharūkō prēma jhanajhana praśasta hum̐dai jāōs .",null],[1,10,"म यसको निम्ति प्रार्थना गर्छु, ताकि जे असल छ ती कुराहरू तिमीहरूले पारख गरेर छान्‍न सक । म यसको निम्ति प्रार्थना गर्छु, ताकि तिमीहरू ख्रीष्‍टको दिनमा इमानदार र दोषरहित रहन सक ।","ma yasakō nimti prārthanā garchu, tāki jē asala cha tī kurāharū timīharūlē pārakha garēra chānna saka . ma yasakō nimti prārthanā garchu, tāki timīharū khrīṣṭakō dinamā imānadāra ra dōṣarahita rahana saka .",null],[1,11,"यो यसको निम्ति पनि हो, ताकि परमेश्‍वरको महिमा र प्रशंसाको निम्ति, येशू ख्रीष्‍टद्वारा आउने धार्मिकताको फलद्वारा तिमीहरू भरिन सक ।","yō yasakō nimti pani hō, tāki paramēśvarakō mahimā ra praśaṁsākō nimti, yēśū khrīṣṭadvārā āunē dhārmikatākō phaladvārā timīharū bharina saka .",null],[1,12,"भाइ हो, अब तिमीहरूलाई यो थाहा होस् भन्‍ने म चाहन्छु, कि मलाई भएका यी सबै कुराहरूले सुसमाचारलाई धेरै अगाडि बढाउने काम भएको छ ।","bhāi hō, aba timīharūlāī yō thāhā hōs bhannē ma cāhanchu, ki malāī bhaēkā yī sabai kurāharūlē susamācāralāī dhērai agāḍi baḍhāunē kāma bhaēkō cha .",null],[1,13,"किनकि ख्रीष्‍टमा मेरा साङ्लाहरूका विषयमा महलभरिका सारा रक्षकदेखि अरू सबै मानिसलाई थाहा भएको छ ।","kinaki khrīṣṭamā mērā sāṅlāharūkā viṣayamā mahalabharikā sārā rakṣakadēkhi arū sabai mānisalāī thāhā bhaēkō cha .",null],[1,14,"र परमप्रभुमा भएका धेरै भाइहरू मेरा साङ्लाहरूका कारण निडर भएर वचन बोल्ने आँट गर्न झनै बढी उत्साहित भएका छन् ।","ra paramaprabhumā bhaēkā dhērai bhāiharū mērā sāṅlāharūkā kāraṇa niḍara bhaēra vacana bōlnē ām̐ṭa garna jhanai baḍhī utsāhita bhaēkā chan .",null],[1,15,"कसै-कसैले त ईर्ष्या र बेमेलमा, र अरूहरूले सद्‌भावले पनि ख्रीष्‍टको प्रचार गरेका छन् ।","kasai-kasailē ta īrṣyā ra bēmēlamā, ra arūharūlē sadbhāvalē pani khrīṣṭakō pracāra garēkā chan .",null],[1,16,"प्रेमले ख्रीष्‍टको प्रचार गर्नेहरूले सुसमाचारको समर्थन गरेको कारण मलाई यहाँ राखिएको छ भन्‍ने कुरा जान्दछन् ।","prēmalē khrīṣṭakō pracāra garnēharūlē susamācārakō samarthana garēkō kāraṇa malāī yahām̐ rākhiēkō cha bhannē kurā jāndachan .",null],[1,17,"तर अरूहरूले ख्रीष्‍टको प्रचार स्वार्थ र निष्‍ठाहीन उद्देश्यले गर्दछन् । मेरा यी साङ्लाहरूका अवस्थामा तिनीहरूले मलाई अझै कष्‍ट दिइरहेका छन् भनी तिनीहरू विचार गर्छन् ।","tara arūharūlē khrīṣṭakō pracāra svārtha ra niṣṭhāhīna uddēśyalē gardachan . mērā yī sāṅlāharūkā avasthāmā tinīharūlē malāī ajhai kaṣṭa diirahēkā chan bhanī tinīharū vicāra garchan .",null],[1,18,"त्यसो भए के त ? चाहे बहानामा होस् वा सत्यतामा दुवै तरिकाले ख्रीष्‍टको प्रचार हुन्छ, र म यसैमा रमाउँदछु । हो, म रमाउनेछु ।","tyasō bhaē kē ta ? cāhē bahānāmā hōs vā satyatāmā duvai tarikālē khrīṣṭakō pracāra huncha, ra ma yasaimā ramāum̐dachu . hō, ma ramāunēchu .",null],[1,19,"किनकि मलाई थाहा छ, कि परिणामस्वरूप यसले मेरो निम्ति छुटकारा ल्याउनेछ । तिमीहरूको प्रार्थना र येशू ख्रीष्‍टको आत्माको सहायताको कारण यो हुनेछ ।","kinaki malāī thāhā cha, ki pariṇāmasvarūpa yasalē mērō nimti chuṭakārā lyāunēcha . timīharūkō prārthanā ra yēśū khrīṣṭakō ātmākō sahāyatākō kāraṇa yō hunēcha .",null],[1,20,"मेरो विश्‍वस्त आशा र निश्‍चयताअनुसार, म शर्ममा पर्नेछैनँ । बरु, सारा साहससँगै सधैँ जस्तै र अहिले पनि, चाहे मेरो जीवनद्वारा वा मृत्युद्वारा, ख्रीष्‍ट मेरो शरीरमा उचालिनुहुनेछ भन्‍ने म आशा गर्दछु ।","mērō viśvasta āśā ra niścayatāanusāra, ma śarmamā parnēchainam̐ . baru, sārā sāhasasam̐gai sadhaim̐ jastai ra ahilē pani, cāhē mērō jīvanadvārā vā mr̥tyudvārā, khrīṣṭa mērō śarīramā ucālinuhunēcha bhannē ma āśā gardachu .",null],[1,21,"किनकि मेरो निम्ति जिउनु ख्रीष्‍ट हो, र मर्नु लाभ हो ।","kinaki mērō nimti jiunu khrīṣṭa hō, ra marnu lābha hō .",null],[1,22,"तर शरीरमा जिउनाले मेरो परिश्रमबाट प्रतिफल आउँछ भने, कुन कुरालाई चुन्‍ने भन्‍ने कुरा मलाई थाहा छैन ।","tara śarīramā jiunālē mērō pariśramabāṭa pratiphala āum̐cha bhanē, kuna kurālāī cunnē bhannē kurā malāī thāhā chaina .",null],[1,23,"किनकि मैले चयन गर्नुपर्ने यी दुवै कुराद्वारा म बिचमा परेको छु । म बिदा भएर ख्रीष्‍टसँग हुने इच्छा गर्दछु, जुनचाहिँ झनै असल कुरा हो ।","kinaki mailē cayana garnuparnē yī duvai kurādvārā ma bicamā parēkō chu . ma bidā bhaēra khrīṣṭasam̐ga hunē icchā gardachu, junacāhim̐ jhanai asala kurā hō .",null],[1,24,"तर तिमीहरूका निम्ति शरीरमा रहनुचाहिँ धेरै आवश्यक छ ।","tara timīharūkā nimti śarīramā rahanucāhim̐ dhērai āvaśyaka cha .",null],[1,25,"यस कुरामा म निश्‍चित भएको कारणले म जान्दछु, कि विश्‍वासमा तिमीहरूको प्रगति र आनन्दको निम्ति म तिमीहरू सँग-सँगै रहेर निरन्तरता दिनेछु ।","yasa kurāmā ma niścita bhaēkō kāraṇalē ma jāndachu, ki viśvāsamā timīharūkō pragati ra ānandakō nimti ma timīharū sam̐ga-sam̐gai rahēra nirantaratā dinēchu .",null],[1,26,"परिणामस्वरूप, तिमीहरूकहाँ मेरो पुनः उपस्थितिको कारण तिमीहरूले ख्रीष्‍ट येशूलाई मेरो निम्ति महिमा दिने काम अझ धेरै प्रशस्त हुनेछ ।","pariṇāmasvarūpa, timīharūkahām̐ mērō punaḥ upasthitikō kāraṇa timīharūlē khrīṣṭa yēśūlāī mērō nimti mahimā dinē kāma ajha dhērai praśasta hunēcha .",null],[1,27,"ख्रीष्‍टको सुसमाचारको निम्ति योग्य हुने किसिमले मात्र आफ्नो जीवनयापन गर । चाहे म तिमीहरूलाई भेट्न आऊँ वा म उपस्थित नहोऊँ, यो गर, ताकि तिमीहरू एउटै आत्मामा दृढ भएर खडा भएका छौ भनेर तिमीहरूका विषयमा मैले सुन्‍न पाऊँ । सुसमाचारको विश्‍वासको निम्ति तिमीहरू मिलेर एउटै प्राणको भएर कडा परिश्रम गरिरहेका छौ भनेर सुन्‍ने मेरो चाहना छ ।","khrīṣṭakō susamācārakō nimti yōgya hunē kisimalē mātra āphnō jīvanayāpana gara . cāhē ma timīharūlāī bhēṭna āūm̐ vā ma upasthita nahōūm̐, yō gara, tāki timīharū ēuṭai ātmāmā dr̥ḍha bhaēra khaḍā bhaēkā chau bhanēra timīharūkā viṣayamā mailē sunna pāūm̐ . susamācārakō viśvāsakō nimti timīharū milēra ēuṭai prāṇakō bhaēra kaḍā pariśrama garirahēkā chau bhanēra sunnē mērō cāhanā cha .",null],[1,28,"र तिमीहरूका शत्रुहरूले गरेका कुनै कुराहरूबाट भयभीत नहोओ । यो तिनीहरूका निम्ति तिनीहरूको विनाशको चिह्न हो । तर तिमीहरूका निम्ति यो तिमीहरूको मुक्‍तिको चिह्न हो, र यो परमेश्‍वरबाट आएको हो ।","ra timīharūkā śatruharūlē garēkā kunai kurāharūbāṭa bhayabhīta nahōō . yō tinīharūkā nimti tinīharūkō vināśakō cihna hō . tara timīharūkā nimti yō timīharūkō muktikō cihna hō, ra yō paramēśvarabāṭa āēkō hō .",null],[1,29,"किनकि ख्रीष्‍टको निम्ति यो तिमीहरूलाई दिइएको छ, उहाँमाथि विश्‍वास गर्न मात्र होइन, तर उहाँको निम्ति कष्‍ट भोग्‍न पनि ।","kinaki khrīṣṭakō nimti yō timīharūlāī diiēkō cha, uhām̐māthi viśvāsa garna mātra hōina, tara uhām̐kō nimti kaṣṭa bhōgna pani .",null],[1,30,"किनकि जे तिमीहरूले ममा देख्यौ र अहिले मसँग छ भनी सुन्दछौ, त्यही सङ्घर्ष तिमीहरूसँग छ ।","kinaki jē timīharūlē mamā dēkhyau ra ahilē masam̐ga cha bhanī sundachau, tyahī saṅgharṣa timīharūsam̐ga cha .",null],[2,1,"यसकारण म मान्दछु, कि ख्रीष्‍टमा उत्साह छ । म मान्दछु, कि त्यहाँ आत्माको सङ्गति छ । म मान्दछु, कि उहाँको प्रेमबाट सान्त्वना मिल्दछ । म मान्दछु, कि त्यहाँ स्‍नेही करुणा र सहानुभूति छ ।","yasakāraṇa ma māndachu, ki khrīṣṭamā utsāha cha . ma māndachu, ki tyahām̐ ātmākō saṅgati cha . ma māndachu, ki uhām̐kō prēmabāṭa sāntvanā mildacha . ma māndachu, ki tyahām̐ snēhī karuṇā ra sahānubhūti cha .",null],[2,2,"तिमीहरू एउटै मनका भएर, एउटै प्रेम धारण गरेर, आत्मामा एक भएर, र एउटै उद्देश्य राखेर मेरो आनन्दलाई पुरा गर ।","timīharū ēuṭai manakā bhaēra, ēuṭai prēma dhāraṇa garēra, ātmāmā ēka bhaēra, ra ēuṭai uddēśya rākhēra mērō ānandalāī purā gara .",null],[2,3,"स्वार्थ र रित्तो अहङ्कारमा केही नगर । बरु नम्रतामा आफूलाईभन्दा अरूहरूलाई उच्‍च ठान ।","svārtha ra rittō ahaṅkāramā kēhī nagara . baru namratāmā āphūlāībhandā arūharūlāī ucca ṭhāna .",null],[2,4,"आफ्ना आवश्यकताहरूमा मात्र ध्यान नदेओ, तर अरूहरूका आवश्यकताहरूमा पनि ध्यान लगाओ ।","āphnā āvaśyakatāharūmā mātra dhyāna nadēō, tara arūharūkā āvaśyakatāharūmā pani dhyāna lagāō .",null],[2,5,"त्यही शैलीमा विचार गर, जुन ख्रीष्‍ट येशूमा पनि थियो ।","tyahī śailīmā vicāra gara, juna khrīṣṭa yēśūmā pani thiyō .",null],[2,6,"उहाँ परमेश्‍वरको स्वरूपमा हुनुहुन्थ्यो, तर पनि परमेश्‍वरसँगको आफ्नो बराबरीलाई उहाँले पक्रिराख्‍ने वस्तुझैँ ठान्‍नुभएन ।","uhām̐ paramēśvarakō svarūpamā hunuhunthyō, tara pani paramēśvarasam̐gakō āphnō barābarīlāī uhām̐lē pakrirākhnē vastujhaim̐ ṭhānnubhaēna .",null],[2,7,"बरु, उहाँले आफैँलाई रित्त्याउनुभयो । उहाँले कमराको रूप धारण गर्नुभयो । उहाँ मानिसको स्वरूपमा आउनुभयो । मानिसकै स्वरूपमा उहाँ रहनुभयो ।","baru, uhām̐lē āphaim̐lāī rittyāunubhayō . uhām̐lē kamarākō rūpa dhāraṇa garnubhayō . uhām̐ mānisakō svarūpamā āunubhayō . mānisakai svarūpamā uhām̐ rahanubhayō .",null],[2,8,"उहाँले आफूलाई नम्र तुल्याउनुभयो, र मृत्यु अर्थात् क्रुसको मृत्युसम्मै आज्ञाकारी हुनुभयो ।","uhām̐lē āphūlāī namra tulyāunubhayō, ra mr̥tyu arthāt krusakō mr̥tyusammai ājñākārī hunubhayō .",null],[2,9,"यसकारण, परमेश्‍वरले उहाँलाई अति उच्‍च पार्नुभयो । परमेश्‍वरले उहाँलाई सबै नाउँभन्दा उच्‍च नाउँ दिनुभयो ।","yasakāraṇa, paramēśvaralē uhām̐lāī ati ucca pārnubhayō . paramēśvaralē uhām̐lāī sabai nāum̐bhandā ucca nāum̐ dinubhayō .",null],[2,10,"उहाँले यसो गर्नुभयो, ताकि येशूको नाममा हरेक घुँडाहरू टेकिऊन्ः स्वर्ग, पृथ्वी र पृथ्वीमुनि भएका सबैका घुँडाहरू ।","uhām̐lē yasō garnubhayō, tāki yēśūkō nāmamā harēka ghum̐ḍāharū ṭēkiūnḥ svarga, pr̥thvī ra pr̥thvīmuni bhaēkā sabaikā ghum̐ḍāharū .",null],[2,11,"र उहाँले यो गर्नुभयो, ताकि परमेश्‍वर पिताको महिमाका लागि प्रत्येक जिब्रोले येशू ख्रीष्‍ट नै प्रभु हुनुहुन्छ भनी स्वीकार गरोस् ।","ra uhām̐lē yō garnubhayō, tāki paramēśvara pitākō mahimākā lāgi pratyēka jibrōlē yēśū khrīṣṭa nai prabhu hunuhuncha bhanī svīkāra garōs .",null],[2,12,"यसकारण, मेरा प्रियहरू हो, जसरी तिमीहरूले सधैँ आज्ञापालन गर्ने गरेका छौ, अब मेरो उपस्थितिमा मात्र होइन तर मेरो अनुपस्थितीमा झन् बढी डर र कम्पसाथ आफ्ना मुक्‍तिको काम पुरा गर ।","yasakāraṇa, mērā priyaharū hō, jasarī timīharūlē sadhaim̐ ājñāpālana garnē garēkā chau, aba mērō upasthitimā mātra hōina tara mērō anupasthitīmā jhan baḍhī ḍara ra kampasātha āphnā muktikō kāma purā gara .",null],[2,13,"किनकि परमेश्‍वरको प्रसन्‍नताको निम्ति तिमीहरूलाई दुवै इच्छा र काम गर्न लगाउनलाई तिमीहरूमा काम गर्नुहुने उहाँ नै हुनुहुन्छ ।","kinaki paramēśvarakō prasannatākō nimti timīharūlāī duvai icchā ra kāma garna lagāunalāī timīharūmā kāma garnuhunē uhām̐ nai hunuhuncha .",null],[2,14,"गनगन नगरी र तर्क वितर्कविना सबै कामहरू गर ।","ganagana nagarī ra tarka vitarkavinā sabai kāmaharū gara .",null],[2,15,"यस्तो प्रकारले व्यवहार गर, ताकि तिमीहरू कुनै कलङ्कविना परमेश्‍वरका निर्दोष र इमानदार छोराछोरी हुन सक । यस्तो प्रकारले व्यवहार गर, ताकि तिमीहरू धूर्त र बरालिएका पुस्ताकाबिच यस संसारमा ज्योतिझैँ चम्कन सक ।","yastō prakāralē vyavahāra gara, tāki timīharū kunai kalaṅkavinā paramēśvarakā nirdōṣa ra imānadāra chōrāchōrī huna saka . yastō prakāralē vyavahāra gara, tāki timīharū dhūrta ra barāliēkā pustākābica yasa saṁsāramā jyōtijhaim̐ camkana saka .",null],[2,16,"जीवनको वचनलाई बलियो गरी पक्र ताकि ख्रीष्‍टको दिनमा मसँग महिमा गर्ने कारण होस् । किनभने त्यस दिन म व्यर्थमा दौडिनँ र मेरो परिश्रम व्यर्थको भएन भन्‍ने म जान्‍नेछु ।","jīvanakō vacanalāī baliyō garī pakra tāki khrīṣṭakō dinamā masam̐ga mahimā garnē kāraṇa hōs . kinabhanē tyasa dina ma vyarthamā dauḍinam̐ ra mērō pariśrama vyarthakō bhaēna bhannē ma jānnēchu .",null],[2,17,"तर तिमीहरूको विश्‍वासको त्याग र सेवामा म बलिदानको रूपमा अर्पित हुनुपरे तापनि, म आनन्द मनाउँछु, र म तिमीहरू सबैसँग आनन्दित हुन्छु ।","tara timīharūkō viśvāsakō tyāga ra sēvāmā ma balidānakō rūpamā arpita hunuparē tāpani, ma ānanda manāum̐chu, ra ma timīharū sabaisam̐ga ānandita hunchu .",null],[2,18,"त्यसै गरी, तिमीहरू पनि आनन्दित होओ, र मसँगै आनन्दित होओ ।","tyasai garī, timīharū pani ānandita hōō, ra masam̐gai ānandita hōō .",null],[2,19,"तर तिमोथीलाई तिमीहरूकहाँ छिट्टै पठाउनको निम्ति मैले प्रभु येशूमा आशा राख्दछु, ताकि तिनीबाट तिमीहरूका विषयमा जान्दा म प्रोत्साहित हुन सकूँ ।","tara timōthīlāī timīharūkahām̐ chiṭṭai paṭhāunakō nimti mailē prabhu yēśūmā āśā rākhdachu, tāki tinībāṭa timīharūkā viṣayamā jāndā ma prōtsāhita huna sakūm̐ .",null],[2,20,"किनकि तिनको जस्तै मन भएको, र तिनीजस्तै तिमीहरूका निम्ति साँचो रूपमा उत्सुक हुने मसँग अरू कोही पनि छैन ।","kinaki tinakō jastai mana bhaēkō, ra tinījastai timīharūkā nimti sām̐cō rūpamā utsuka hunē masam̐ga arū kōhī pani chaina .",null],[2,21,"किनकि तिनीहरू सबैले येशू ख्रीष्‍टका कुराहरूभन्दा आफ्नै इच्छाको खोजी गर्दछन् ।","kinaki tinīharū sabailē yēśū khrīṣṭakā kurāharūbhandā āphnai icchākō khōjī gardachan .",null],[2,22,"तर तिमीहरूलाई तिनको योग्यता थाहै छ, किनकि जसरी बालकले आफ्ना पिताको सेवा गर्दछ, त्यसरी नै सुसमाचारमा मलाई तिनले सेवा गरेका छन् ।","tara timīharūlāī tinakō yōgyatā thāhai cha, kinaki jasarī bālakalē āphnā pitākō sēvā gardacha, tyasarī nai susamācāramā malāī tinalē sēvā garēkā chan .",null],[2,23,"यसकारण, मेरो निम्ति के हुनेछ भनेर मैले थाहा पाउनासाथ जति सक्दो चाँडो म तिमोथीलाई तिमीहरूकहाँ पठाउने आशा गर्दछु ।","yasakāraṇa, mērō nimti kē hunēcha bhanēra mailē thāhā pāunāsātha jati sakdō cām̐ḍō ma timōthīlāī timīharūkahām̐ paṭhāunē āśā gardachu .",null],[2,24,"तर म आफैँ तिमीहरूका माझमा छिट्टै आउनेछु भन्‍ने कुरामा प्रभुमा निर्धक्‍क छु ।","tara ma āphaim̐ timīharūkā mājhamā chiṭṭai āunēchu bhannē kurāmā prabhumā nirdhakka chu .",null],[2,25,"तर इपाफ्रोडिटसलाई तिमीहरूकहाँ फिर्ता पठाउन म आवश्यक ठान्दछु । तिनी मेरा भाइ र सहकर्मी र सङ्गी सिपाही, र तिमीहरूका सन्देशवाहक तथा मेरा आवश्यकताहरूका निम्ति सेवक हुन् ।","tara ipāphrōḍiṭasalāī timīharūkahām̐ phirtā paṭhāuna ma āvaśyaka ṭhāndachu . tinī mērā bhāi ra sahakarmī ra saṅgī sipāhī, ra timīharūkā sandēśavāhaka tathā mērā āvaśyakatāharūkā nimti sēvaka hun .",null],[2,26,"किनकि तिनी बिरामी भएको कुरा तिमीहरूले थाहा पाएकाले तिनी धेरै व्याकुल भएका थिए, र तिमीहरूसँग हुनको निम्ति तिनले तृष्णा गरेका थिए ।","kinaki tinī birāmī bhaēkō kurā timīharūlē thāhā pāēkālē tinī dhērai vyākula bhaēkā thiē, ra timīharūsam̐ga hunakō nimti tinalē tr̥ṣṇā garēkā thiē .",null],[2,27,"किनकि तिनी साँच्‍चै यति बिरामी थिए, कि तिनी मरणासन्‍न अवस्थामा पुगेका थिए । तर परमेश्‍वरले तिनीमाथि कृपा गर्नुभयो, र उनमा मात्र नभएर शोकमाथि शोक नथपिओस् भनेर ममाथि पनि दया देखाउनुभयो ।","kinaki tinī sām̐ccai yati birāmī thiē, ki tinī maraṇāsanna avasthāmā pugēkā thiē . tara paramēśvaralē tinīmāthi kr̥pā garnubhayō, ra unamā mātra nabhaēra śōkamāthi śōka nathapiōs bhanēra mamāthi pani dayā dēkhāunubhayō .",null],[2,28,"यसकारण, अझै धेरै उत्सुकतासाथ म तिनलाई तिमीहरूकहाँ पठाउँदै छु, ताकि जब तिमीहरूलेतिनलाई फेरि देख्छौ, तिमीहरू आनन्दित हुन सक र म चिन्ताबाट मुक्‍त हुनेछु ।","yasakāraṇa, ajhai dhērai utsukatāsātha ma tinalāī timīharūkahām̐ paṭhāum̐dai chu, tāki jaba timīharūlētinalāī phēri dēkhchau, timīharū ānandita huna saka ra ma cintābāṭa mukta hunēchu .",null],[2,29,"त्यसैले, सारा आनन्दसाथ प्रभुमा इपाफ्रोडिटसलाई स्वागत गर । तिनीजस्ता मानिसलाई आदर गर ।","tyasailē, sārā ānandasātha prabhumā ipāphrōḍiṭasalāī svāgata gara . tinījastā mānisalāī ādara gara .",null],[2,30,"किनकि ख्रीष्‍टको कार्यको निम्ति तिनी मृत्युको नजिक पुगे । मलाई सेवा पुर्‍याउन र तिमीहरूले मेरो सेवामा गर्न नसकेका कामलाई पुरा गर्न तिनले आफ्नो जीवन जोखिममा पारे ।","kinaki khrīṣṭakō kāryakō nimti tinī mr̥tyukō najika pugē . malāī sēvā puryāuna ra timīharūlē mērō sēvāmā garna nasakēkā kāmalāī purā garna tinalē āphnō jīvana jōkhimamā pārē .",null],[3,1,"अन्त्यमा मेरा भाइहरू हो, परमप्रभुमा आनन्द गर । तिमीहरूलाई बारम्बार एउटै कुरा लेखिरहनु मेरो निम्ति झर्कोलाग्दो कुरो होइन । यी कुराहरूहरूले तिमीहरूलाई सुरक्षित राख्‍नेछन् ।","antyamā mērā bhāiharū hō, paramaprabhumā ānanda gara . timīharūlāī bārambāra ēuṭai kurā lēkhirahanu mērō nimti jharkōlāgdō kurō hōina . yī kurāharūharūlē timīharūlāī surakṣita rākhnēchan .",null],[3,2,"कुकुरहरूदेखि होसियार रहो । खराब काम गर्नेहरूदेखि होसियार रहो । अङ्ग कटाइ गर्नेहरूदेखि होसियार रहो ।","kukuraharūdēkhi hōsiyāra rahō . kharāba kāma garnēharūdēkhi hōsiyāra rahō . aṅga kaṭāi garnēharūdēkhi hōsiyāra rahō .",null],[3,3,"किनकि खतना हामीहरू नै हौँ । हामीहरू नै परमेश्‍वरका आत्माद्वारा आराधना गर्दछौँ । हामीहरू नै ख्रीष्‍ट येशूमा गर्व गर्दछौँ, र शरीरमा कुनै भरोसा राख्दैनौँ ।","kinaki khatanā hāmīharū nai haum̐ . hāmīharū nai paramēśvarakā ātmādvārā ārādhanā gardachaum̐ . hāmīharū nai khrīṣṭa yēśūmā garva gardachaum̐, ra śarīramā kunai bharōsā rākhdainaum̐ .",null],[3,4,"यद्यपि, म आफैँले शरीरमा भरोसा राख्‍न सक्थे । यदि कसैले आफ्नो शरीरमा भरोसा राख्‍ने विचार गर्छ भने, त्योभन्दा बढी म गर्न सक्छु ।","yadyapi, ma āphaim̐lē śarīramā bharōsā rākhna sakthē . yadi kasailē āphnō śarīramā bharōsā rākhnē vicāra garcha bhanē, tyōbhandā baḍhī ma garna sakchu .",null],[3,5,"मेरो आठौँ दिनमा खतना गराइएको थियो, म इस्राएलका मानिसहरूमध्ये एक, बेन्यामीन कुलमा जन्मेको, हिब्रूहरूका हिब्रू हुँ; व्यवस्थाको विषयमा चाहिँ, एक फरिसी ।","mērō āṭhaum̐ dinamā khatanā garāiēkō thiyō, ma isrāēlakā mānisaharūmadhyē ēka, bēnyāmīna kulamā janmēkō, hibrūharūkā hibrū hum̐; vyavasthākō viṣayamā cāhim̐, ēka pharisī .",null],[3,6,"मैले जोसिलो रूपमा मण्डलीलाई सताएँ । व्यवस्थाको धार्मिकताको विषयमा चाहिँ म दोषरहित थिएँ ।","mailē jōsilō rūpamā maṇḍalīlāī satāēm̐ . vyavasthākō dhārmikatākō viṣayamā cāhim̐ ma dōṣarahita thiēm̐ .",null],[3,7,"तर मेरो निम्ति लाभदायक भएका सबै कुराहरू, ख्रीष्‍टको खातिर मैले हानि नै सम्झेको छु ।","tara mērō nimti lābhadāyaka bhaēkā sabai kurāharū, khrīṣṭakō khātira mailē hāni nai samjhēkō chu .",null],[3,8,"वास्तवमा, मेरा प्रभु ख्रीष्‍ट येशूको ज्ञानको श्रेष्‍ठताको कारण अब म सबै कुराहरूलाई हानि नै सम्झन्छु । उहाँको निम्ति मैले सबै कुराहरूलाई त्यागेको छु । मैले ती कुराहरूलाई काम नलाग्‍ने ठान्दछु ताकि मैले ख्रीष्‍टलाई हासिल गर्न सकूँ,","vāstavamā, mērā prabhu khrīṣṭa yēśūkō jñānakō śrēṣṭhatākō kāraṇa aba ma sabai kurāharūlāī hāni nai samjhanchu . uhām̐kō nimti mailē sabai kurāharūlāī tyāgēkō chu . mailē tī kurāharūlāī kāma nalāgnē ṭhāndachu tāki mailē khrīṣṭalāī hāsila garna sakūm̐,",null],[3,9,"र उहाँमा स्थापित हुन सकूँ । व्यवस्थाबाट मैले आफैँले प्राप्‍त गरेको धार्मिकता मसँग छैन । बरु, ख्रीष्‍ट येशूमा विश्‍वासद्वारा प्राप्‍त गरेको धार्मिकता मसँग छ, जुन धार्मिकता विश्‍वासमा आधारित परमेश्‍वरबाट मैले प्राप्‍त गरेको हुँ ।","ra uhām̐mā sthāpita huna sakūm̐ . vyavasthābāṭa mailē āphaim̐lē prāpta garēkō dhārmikatā masam̐ga chaina . baru, khrīṣṭa yēśūmā viśvāsadvārā prāpta garēkō dhārmikatā masam̐ga cha, juna dhārmikatā viśvāsamā ādhārita paramēśvarabāṭa mailē prāpta garēkō hum̐ .",null],[3,10,"यसैकारण, अब म उहाँ र उहाँको पुनरुत्थानको शक्‍तिलाई जान्‍न चाहन्छु र उहाँका कष्‍टहरूमा सहभागी हुन चाहन्छु । उहाँको मृत्युको समरूपतामा म बद्‌लिन चाहन्छु,","yasaikāraṇa, aba ma uhām̐ ra uhām̐kō punarutthānakō śaktilāī jānna cāhanchu ra uhām̐kā kaṣṭaharūmā sahabhāgī huna cāhanchu . uhām̐kō mr̥tyukō samarūpatāmā ma badlina cāhanchu,",null],[3,11,"ताकि मैले मरेकाहरूबाटको पुनरुत्‍थानको कुनै किसिमले अनुभव गर्न सकूँ ।","tāki mailē marēkāharūbāṭakō punarutthānakō kunai kisimalē anubhava garna sakūm̐ .",null],[3,12,"मैले यी सबै कुराहरू प्राप्‍त गरिसकेको छु, वा म पूर्ण भइसकेको छु भन्‍ने कुरा साँचो होइन । तर जे कुराको निम्ति म ख्रीष्‍टद्वारा चुनिएको थिएँ, ती मैले पक्रन सकूँ भनेर म जोड दिन्छु ।","mailē yī sabai kurāharū prāpta garisakēkō chu, vā ma pūrṇa bha:isakēkō chu bhannē kurā sām̐cō hōina . tara jē kurākō nimti ma khrīṣṭadvārā cuniēkō thiēm̐, tī mailē pakrana sakūm̐ bhanēra ma jōḍa dinchu .",null],[3,13,"भाइहरू हो, मैले यी सबै कुराहरू पक्रिसकेको छु भनी म ठान्दिनँ । तर एउटा कुराचाहिँ मैले पक्रन सकेकेछुः म पछाडिका कुराहरूलाई बिर्सेर अगाडिका कुराहरूका निम्ति परिश्रम गर्दछु ।","bhāiharū hō, mailē yī sabai kurāharū pakrisakēkō chu bhanī ma ṭhāndinam̐ . tara ēuṭā kurācāhim̐ mailē pakrana sakēkēchuḥ ma pachāḍikā kurāharūlāī birsēra agāḍikā kurāharūkā nimti pariśrama gardachu .",null],[3,14,"म ख्रीष्‍ट येशूमा परमेश्‍वरको माथिल्लो बोलावटको इनाम जित्‍ने लक्ष्यतर्फ अगाडि बढ्नमा जोड दिन्छु ।","ma khrīṣṭa yēśūmā paramēśvarakō māthillō bōlāvaṭakō ināma jitnē lakṣyatarpha agāḍi baḍhnamā jōḍa dinchu .",null],[3,15,"यसकारण, हामी परिपक्‍व भएकाहरू सबैले यसरी विचार गरौँ । यदि तिमीहरूले कुनै कुरालाई भिन्‍न प्रकारले विचार गर्दछौ भने परमेश्‍वरले ती कुराहरूलाई पनि तिमीहरूका निम्ति प्रकट गर्नुहुनेछ ।","yasakāraṇa, hāmī paripakva bhaēkāharū sabailē yasarī vicāra garaum̐ . yadi timīharūlē kunai kurālāī bhinna prakāralē vicāra gardachau bhanē paramēśvaralē tī kurāharūlāī pani timīharūkā nimti prakaṭa garnuhunēcha .",null],[3,16,"तथापि, हामीले जे प्राप्‍त गरिसकेका छौँ, हामी त्यसमा अडिग रहौँ ।","tathāpi, hāmīlē jē prāpta garisakēkā chaum̐, hāmī tyasamā aḍiga rahaum̐ .",null],[3,17,"भाइहरू हो, मेरो अनुकरण गर्नेहरू होओ । हामीमा तिमीहरूले पाएका उदाहरणअनुसार हिँड्नेहरूलाई ध्यान दिएर हेर ।","bhāiharū hō, mērō anukaraṇa garnēharū hōō . hāmīmā timīharūlē pāēkā udāharaṇaanusāra him̐ḍnēharūlāī dhyāna diēra hēra .",null],[3,18,"ती धेरै व्यक्‍तिहरू जसको विषयमा मैले तिमीहरूलाई बारम्बार बताएको थिएँ, र अहिले आँसुका साथ म बताउँदै छु, कि तिनीहरू ख्रीष्‍टको क्रुसका शत्रुहरूझैँ हिँडिरहेका छन् ।","tī dhērai vyaktiharū jasakō viṣayamā mailē timīharūlāī bārambāra batāēkō thiēm̐, ra ahilē ām̐sukā sātha ma batāum̐dai chu, ki tinīharū khrīṣṭakō krusakā śatruharūjhaim̐ him̐ḍirahēkā chan .",null],[3,19,"तिनीहरूको नतिजा विनाश हो । किनकि तिनीहरूको ईश्‍वर तिनीहरूको पेट हो, र तिनीहरूको शर्ममा तिनीहरूको घमण्ड छ । तिनीहरू सांसारिक कुराहरूका बारेमा विचार गर्दछन् ।","tinīharūkō natijā vināśa hō . kinaki tinīharūkō īśvara tinīharūkō pēṭa hō, ra tinīharūkō śarmamā tinīharūkō ghamaṇḍa cha . tinīharū sāṁsārika kurāharūkā bārēmā vicāra gardachan .",null],[3,20,"तर हाम्रो नागरिकता स्वर्गमा छ, जहाँबाट हामी मुक्‍तिदाता प्रभु येशू ख्रीष्‍टको प्रतीक्षा गर्दछौँ ।","tara hāmrō nāgarikatā svargamā cha, jahām̐bāṭa hāmī muktidātā prabhu yēśū khrīṣṭakō pratīkṣā gardachaum̐ .",null],[3,21,"उहाँले हाम्रो क्षुद्र शरीरलाई उहाँको जस्तै महिमित शरीरमा परिवर्तन गर्नुहुनेछ, जुन शरीर सबै कुराहरू उहाँको अधीनमा ल्याउनको निम्ति उहाँको शक्‍तिद्वारा बनाइएको छ ।","uhām̐lē hāmrō kṣudra śarīralāī uhām̐kō jastai mahimita śarīramā parivartana garnuhunēcha, juna śarīra sabai kurāharū uhām̐kō adhīnamā lyāunakō nimti uhām̐kō śaktidvārā banāiēkō cha .",null],[4,1,"यसकारण मेरा प्रिय भाइहरू हो, जसको म चाहना गर्दछु, मेरो आनन्द र मुकुट, मेरा प्रिय साथीहरू, यस्तै गरी प्रभुमा स्थिर रहो ।","yasakāraṇa mērā priya bhāiharū hō, jasakō ma cāhanā gardachu, mērō ānanda ra mukuṭa, mērā priya sāthīharū, yastai garī prabhumā sthira rahō .",null],[4,2,"म इयोदिया र सुन्तुखेलाई प्रभुमा एउटै मनको हुन निवेदन गर्दछु ।","ma iyōdiyā ra suntukhēlāī prabhumā ēuṭai manakō huna nivēdana gardachu .",null],[4,3,"वास्तवमा, एउटै जुवामा भएको मेरो साँचो सहकर्मी, म तिमीलाई यो पनि बिन्ती गर्छु, कि यी महिलाहरूलाई सहायता गर । किनभने तिनीहरूले म, क्लेमेन्ट र मेरा बाँकी सहकर्मीहरूसँग सुसमाचार प्रचार गर्न परिश्रम गरेका छन्, जसका नामहरू जीवनको पुस्तकमा छन् ।","vāstavamā, ēuṭai juvāmā bhaēkō mērō sām̐cō sahakarmī, ma timīlāī yō pani bintī garchu, ki yī mahilāharūlāī sahāyatā gara . kinabhanē tinīharūlē ma, klēmēnṭa ra mērā bām̐kī sahakarmīharūsam̐ga susamācāra pracāra garna pariśrama garēkā chan, jasakā nāmaharū jīvanakō pustakamā chan .",null],[4,4,"प्रभुमा सधैँ आनन्द गर । म फेरि पनि भन्दछु, आनन्द गर ।","prabhumā sadhaim̐ ānanda gara . ma phēri pani bhandachu, ānanda gara .",null],[4,5,"तिमीहरूको सहनशीलता सबै मानिसहरूलाई थाहा होस् । प्रभु नजिकै हुनुहुन्छ ।","timīharūkō sahanaśīlatā sabai mānisaharūlāī thāhā hōs . prabhu najikai hunuhuncha .",null],[4,6,"कुनै कुरामा चिन्तित नहोओ । बरु, हरेक कुरामा प्रार्थना र नम्र निवेदनद्वारा, र धन्यवादसाथ तिमीहरूका निवेदन परमेश्‍वरमा जाहेर होऊन् ।","kunai kurāmā cintita nahōō . baru, harēka kurāmā prārthanā ra namra nivēdanadvārā, ra dhanyavādasātha timīharūkā nivēdana paramēśvaramā jāhēra hōūn .",null],[4,7,"र हाम्रा सबै समझभन्दा उच्‍च परमेश्‍वरको शान्तिले ख्रीष्‍ट येशूमा तिमीहरूका हृदय र विचारहरूलाई रक्षा गर्नेछ ।","ra hāmrā sabai samajhabhandā ucca paramēśvarakō śāntilē khrīṣṭa yēśūmā timīharūkā hr̥daya ra vicāraharūlāī rakṣā garnēcha .",null],[4,8,"अन्तमा भाइहरू हो, जे कुराहरू सत्य छन्, जे कुराहरू आदरणीय छन्, जे कुराहरू न्यायसङ्गत छन्, जे कुराहरू शुद्ध छन्, जे कुराहरू प्रेमयोग्य छन्, जे कुराहरू असल नामका छन्, यदि केही श्रेष्‍ठता छ र प्रशंसा गरिनुपर्ने केही कुराहरू छन् भने, यी नै कुराहरूका बारेमा विचार गर ।","antamā bhāiharū hō, jē kurāharū satya chan, jē kurāharū ādaraṇīya chan, jē kurāharū nyāyasaṅgata chan, jē kurāharū śuddha chan, jē kurāharū prēmayōgya chan, jē kurāharū asala nāmakā chan, yadi kēhī śrēṣṭhatā cha ra praśaṁsā garinuparnē kēhī kurāharū chan bhanē, yī nai kurāharūkā bārēmā vicāra gara .",null],[4,9,"जुन कुराहरू तिमीहरूले मबाट सिक्यौ र प्राप्‍त गर्‍यौ र मबाट सुन्यौ र ममा देख्यौ, ती कुराहरू गर । र शान्तिका परमेश्‍वर तिमीहरूसँग हुनुहुनेछ ।","juna kurāharū timīharūlē mabāṭa sikyau ra prāpta garyau ra mabāṭa sunyau ra mamā dēkhyau, tī kurāharū gara . ra śāntikā paramēśvara timīharūsam̐ga hunuhunēcha .",null],[4,10,"म प्रभुमा अत्यन्तै आनन्दित छु किनकि अहिले अन्तमा तिमीहरूले म प्रतिको आफ्नो वास्तालाई नयाँ गरेका छौ । तिमीहरूले वास्तवमा पहिला पनि मेरो निम्ति वास्ता गरेका थियौ, तर त्यस समय तिमीहरूसँग मलाई सहायता गर्ने अवसर थिएन ।","ma prabhumā atyantai ānandita chu kinaki ahilē antamā timīharūlē ma pratikō āphnō vāstālāī nayām̐ garēkā chau . timīharūlē vāstavamā pahilā pani mērō nimti vāstā garēkā thiyau, tara tyasa samaya timīharūsam̐ga malāī sahāyatā garnē avasara thiēna .",null],[4,11,"म अहिले आवश्यकतामा परेकोले मैले यो भनिरहेको होइनँ । मैले सबै परिस्थितिहरूमा सन्तुष्‍ट हुन सिकेको छु ।","ma ahilē āvaśyakatāmā parēkōlē mailē yō bhanirahēkō hōinam̐ . mailē sabai paristhitiharūmā santuṣṭa huna sikēkō chu .",null],[4,12,"मलाई गरिबी के हो भन्‍ने कुरा थाहा छ, र मलाई प्रशस्त हुनु भनेको के हो पनि थाहा छ । सबै किसिमले र सबै कुराहरूमा कसरी परिपूर्ण हुनु वा भोकप्यासमा रहनु, र कसरी प्रशस्तता प्राप्‍त गर्नु वा आवश्यकतामा हुनु भन्‍ने कुरा मैले सिकेको छु ।","malāī garibī kē hō bhannē kurā thāhā cha, ra malāī praśasta hunu bhanēkō kē hō pani thāhā cha . sabai kisimalē ra sabai kurāharūmā kasarī paripūrṇa hunu vā bhōkapyāsamā rahanu, ra kasarī praśastatā prāpta garnu vā āvaśyakatāmā hunu bhannē kurā mailē sikēkō chu .",null],[4,13,"जसले मलाई शक्‍ति दिनुहुन्छ, उहाँद्वारा नै म सबै कुराहरू गर्न सक्दछु ।","jasalē malāī śakti dinuhuncha, uhām̐dvārā nai ma sabai kurāharū garna sakdachu .",null],[4,14,"तथापि, तिमीहरूले मेरा कठिन परिस्थितिहरूमा सहभागी भएर असल गर्‍यौ ।","tathāpi, timīharūlē mērā kaṭhina paristhitiharūmā sahabhāgī bhaēra asala garyau .",null],[4,15,"तिमी फिलिप्पीहरू यो जान्दछौ, कि सुसमाचारको सुरुआतमा जब म माकेडोनियाबाट निस्केँ, तिमीहरूबाहेक कुनै मण्डलीले दिने र लिने विषयमा मलाई सहायता गरेनन् ।","timī philippīharū yō jāndachau, ki susamācārakō suruātamā jaba ma mākēḍōniyābāṭa niskēm̐, timīharūbāhēka kunai maṇḍalīlē dinē ra linē viṣayamā malāī sahāyatā garēnan .",null],[4,16,"म थेसलोनिकेमा हुँदा पनि मेरा आवश्यकताहरूका निम्ति तिमीहरूले एक पटकभन्दा धरै सहायता पठायौ ।","ma thēsalōnikēmā hum̐dā pani mērā āvaśyakatāharūkā nimti timīharūlē ēka paṭakabhandā dharai sahāyatā paṭhāyau .",null],[4,17,"मैले उपहार खोजेको भने होइनँ । बरु, म तिमीहरूको हिसाबमा बढ्दै जाने फल खोज्दछु ।","mailē upahāra khōjēkō bhanē hōinam̐ . baru, ma timīharūkō hisābamā baḍhdai jānē phala khōjdachu .",null],[4,18,"मैले सबै कुराहरू प्राप्‍त गरेको छु, र मसँग ती प्रशस्त छन् । म पूर्ण रूपमा भरिएको छु । तिमीहरूले इपाफ्रोडिटससँग पठाएका सामानहरू मैले पाएँ । ती सुगन्धित वासना आउने ग्रहणयोग्य बलिदान हुन् जसले परमेश्‍वरलाई प्रसन्‍न पार्दछ ।","mailē sabai kurāharū prāpta garēkō chu, ra masam̐ga tī praśasta chan . ma pūrṇa rūpamā bhariēkō chu . timīharūlē ipāphrōḍiṭasasam̐ga paṭhāēkā sāmānaharū mailē pāēm̐ . tī sugandhita vāsanā āunē grahaṇayōgya balidāna hun jasalē paramēśvaralāī prasanna pārdacha .",null],[4,19,"र मेरा परमेश्‍वरले ख्रीष्‍ट येशूमा उहाँको महिमाको प्रशस्तताअनुसार तिमीहरूका सबै आवश्यकताहरू पुरा गरिदिनुहुनेछ ।","ra mērā paramēśvaralē khrīṣṭa yēśūmā uhām̐kō mahimākō praśastatāanusāra timīharūkā sabai āvaśyakatāharū purā garidinuhunēcha .",null],[4,20,"अब हाम्रा परमेश्‍वर र पितालाई सदासर्वदा महिमा होस् । आमेन ।","aba hāmrā paramēśvara ra pitālāī sadāsarvadā mahimā hōs . āmēna .",null],[4,21,"ख्रीष्‍ट येशूमा भएका हरेक विश्‍वासीलाई अभिवादन गर । मसँग भएका भाइहरूले तिमीहरूलाई अभिवादन पठाएका छन् ।","khrīṣṭa yēśūmā bhaēkā harēka viśvāsīlāī abhivādana gara . masam̐ga bhaēkā bhāiharūlē timīharūlāī abhivādana paṭhāēkā chan .",null],[4,22,"यहाँ भएका सबै विश्‍वासीहरू, र विशेष गरेर कैसरका घरानाकाहरूले तिमीहरूलाई अभिवादन पठाएका छन् ।","yahām̐ bhaēkā sabai viśvāsīharū, ra viśēṣa garēra kaisarakā gharānākāharūlē timīharūlāī abhivādana paṭhāēkā chan .",null],[4,23,"प्रभु येशू ख्रीष्‍टको अनुग्रह तिमीहरूको आत्मासँग रहोस् । आमेन ।","prabhu yēśū khrīṣṭakō anugraha timīharūkō ātmāsam̐ga rahōs . āmēna .",null]],"ory":[[1,1,"ପାଉଲ ଓ ତୀମଥି, ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କର ଦୁଇ ଦାସ, ଫିଲିପ୍ପୀରେ ଥିବା ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କ ଆଶ୍ରିତ ସମସ୍ତ ସାଧୁଙ୍କ ନିକଟକୁ ପୁଣି, ଅଧ୍ୟକ୍ଷ ଓ ସେବକମାନଙ୍କ ନିକଟକୁ ପତ୍ର;","pāula ō tīmathi, khrīṣṭa yīśuṅkara dui dāsa, philippīrē thibā khrīṣṭa yīśuṅka āśrita samasta sādhuṅka nikaṭaku puṇi, adhẏakṣa ō sēbakamānaṅka nikaṭaku patra;",null],[1,2,"ଆମ୍ଭମାନଙ୍କ ପିତା ଈଶ୍ବର ଓ ପ୍ରଭୁ ଯୀଶୁ ଖ୍ରୀଷ୍ଟଙ୍କଠାରୁ ଅନୁଗ୍ରହ ଓ ଶାନ୍ତି ତୁମ୍ଭମାନଙ୍କ ପ୍ରତି ହେଉ।","āmbhamānaṅka pitā īśbara ō prabhu yīśu khrīṣṭaṅkaṭhāru anugraha ō śānti tumbhamānaṅka prati hēu.",null],[1,3,"ମୁଁ ତୁମ୍ଭମାନଙ୍କୁ ଯେତେ ଥର ସ୍ମରଣ କରେ, ସେତେ ଥର ମୋହର ଈଶ୍ବରଙ୍କୁ ଧନ୍ୟବାଦ ଦେଇଥାଏ।","mum̐ tumbhamānaṅku yētē thara smaraṇa karē, sētē thara mōhara īśbaraṅku dhanẏabāda dēithāē.",null],[1,4,"ପ୍ରଥମ ଦିନଠାରୁ ଆଜି ପର୍ଯ୍ୟନ୍ତ ସୁସମାଚାରର ପକ୍ଷରେ ତୁମ୍ଭମାନଙ୍କ ସହଭାଗିତା ହେତୁ","prathama dinaṭhāru āji paryẏanta susamācārara pakṣarē tumbhamānaṅka sahabhāgitā hētu",null],[1,5,"ତୁମ୍ଭ ସମସ୍ତଙ୍କ ନିମନ୍ତେ ସର୍ବଦା ମୁଁ ମୋହର ପ୍ରତ୍ୟେକ ପ୍ରାର୍ଥନାରେ ଆନନ୍ଦ ସହ ନିବେଦନ କରୁଅଛି","tumbha samastaṅka nimantē sarbadā mum̐ mōhara pratẏēka prārthanārē ānanda saha nibēdana karuachi",null],[1,6,"କାରଣ ଯେ ତୁମ୍ଭମାନଙ୍କ ଅନ୍ତରରେ ଉତ୍ତମ କାର୍ଯ୍ୟ ଆରମ୍ଭ କରିଅଛନ୍ତି, ସେ ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କ ଦିନ ପର୍ଯ୍ୟନ୍ତ ତାହା ସାଧନ କରି ସିଦ୍ଧ କରିବେ, ଏହା ତ ମୁଁ ଦୃଢ଼ରୂପେ ବିଶ୍ୱାସ କରେ;","kāraṇa yē tumbhamānaṅka antararē uttama kāryẏa ārambha kariachanti, sē khrīṣṭa yīśuṅka dina paryẏanta tāhā sādhana kari siddha karibē, ēhā ta mum̐ dr̥ṛharūpē biśvāsa karē;",null],[1,7,"ଆଉ ତୁମ୍ଭ ସମସ୍ତଙ୍କ ବିଷୟରେ ମୋହର ଏପରି ଭାବିବା ଉଚିତ୍, ଯେଣୁ ତୁମ୍ଭେ ସମସ୍ତେ ମୋହର ବନ୍ଧନରେ ଯେପରି, ସୁସମାଚାର ପକ୍ଷ ସମର୍ଥନ ଓ ସେଥିର ସତ୍ୟ ପ୍ରମାଣ କରିବାରେ ସେହିପରି ମୋʼ ସହିତ ଅନୁଗ୍ରହର ସହଭାଗୀ ଅଟ, ଏଥିନିମନ୍ତେ ମୁଁ ତୁମ୍ଭମାନଙ୍କୁ ହୃଦୟରେ ଧାରଣ କରିଅଛି।","āu tumbha samastaṅka biṣaẏarē mōhara ēpari bhābibā ucit, yēṇu tumbhē samastē mōhara bandhanarē yēpari, susamācāra pakṣa samarthana ō sēthira satẏa pramāṇa karibārē sēhipari mō sahita anugrahara sahabhāgī aṭa, ēthinimantē mum̐ tumbhamānaṅku hr̥daẏarē dhāraṇa kariachi.",null],[1,8,"କାରଣ ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କ ସ୍ନେହପୂର୍ଣ୍ଣ କରୁଣାରେ ମୁଁ ତୁମ୍ଭ ସମସ୍ତଙ୍କ ନିମନ୍ତେ କି ପ୍ରକାର ଲାଳାୟିତ, ଏହି ବିଷୟରେ ଈଶ୍ବର ମୋହର ସାକ୍ଷୀ।","kāraṇa khrīṣṭa yīśuṅka snēhapūrṇṇa karuṇārē mum̐ tumbha samastaṅka nimantē ki prakāra lāḷāẏita, ēhi biṣaẏarē īśbara mōhara sākṣī.",null],[1,9,"ପୁଣି, ମୋହର ପ୍ରାର୍ଥନା ଏହି, ତୁମ୍ଭମାନଙ୍କର ପ୍ରେମ, ଜ୍ଞାନ ଓ ସମସ୍ତ ସୂକ୍ଷ୍ମ ବିଚାରରେ ଅଧିକରୁ ଅଧିକ ବୃଦ୍ଧି ପାଉ,","puṇi, mōhara prārthanā ēhi, tumbhamānaṅkara prēma, jñāna ō samasta sūkṣma bicārarē adhikaru adhika br̥ddhi pāu,",null],[1,10,"ଯେପରି ତୁମ୍ଭେମାନେ ଉତ୍କୃଷ୍ଟ ବିଷୟଗୁଡ଼ିକ ସମର୍ଥନ କରିପାର, ପୁଣି, ଈଶ୍ବରଙ୍କ ଗୌରବ ଓ ପ୍ରଶଂସା ଉଦ୍ଦେଶ୍ୟରେ ଯୀଶୁ ଖ୍ରୀଷ୍ଟଙ୍କ ଦ୍ୱାରା ଧାର୍ମିକତାର ଯେଉଁ ଫଳ,","yēpari tumbhēmānē utkr̥ṣṭa biṣaẏaguṛika samarthana karipāra, puṇi, īśbaraṅka gauraba ō praśaṁsā uddēśẏarē yīśu khrīṣṭaṅka dvārā dhārmikatāra yēum̐ phaḷa,",null],[1,11,"ସେଥିରେ ପରିପୂର୍ଣ୍ଣ ହୋଇ ଖ୍ରୀଷ୍ଟଙ୍କ ଦିନରେ ଶୁଦ୍ଧ ଓ ଅନିନ୍ଦନୀୟ ହୁଅ।","sēthirē paripūrṇṇa hōi khrīṣṭaṅka dinarē śuddha ō anindanīẏa hua.",null],[1,12,"ହେ ଭାଇମାନେ, ମୋʼ ପ୍ରତି ଯାହା ଯାହା ଘଟିଅଛି, ସେହିସବୁ ଯେ ବରଂ ସୁସମାଚାର କାର୍ଯ୍ୟର ବୃଦ୍ଧି ନିମନ୍ତେ ହୋଇଅଛି, ଏହା ତୁମ୍ଭମାନଙ୍କୁ ଜଣାଇବାକୁ ମୁଁ ଇଚ୍ଛା କରେ;","hē bhāimānē, mō prati yāhā yāhā ghaṭiachi, sēhisabu yē baraṁ susamācāra kāryẏara br̥ddhi nimantē hōiachi, ēhā tumbhamānaṅku jaṇāibāku mum̐ icchā karē;",null],[1,13,"ଯେଣୁ ମୋହର ବନ୍ଧନ ଯେ ଖ୍ରୀଷ୍ଟଙ୍କ ନିମନ୍ତେ, ଏହା ରାଜପ୍ରାସାଦର ସମୁଦାୟ ସୈନ୍ୟଦଳ ଓ ଅନ୍ୟାନ୍ୟ ସମସ୍ତଙ୍କ ନିକଟରେ ପ୍ରକାଶିତ ହେଲା;","yēṇu mōhara bandhana yē khrīṣṭaṅka nimantē, ēhā rājaprāsādara samudāẏa sainẏadaḷa ō anẏānẏa samastaṅka nikaṭarē prakāśita hēlā;",null],[1,14,"ଆହୁରି ମଧ୍ୟ ଅଧିକାଂଶ ଭାଇମାନେ ମୋହର ବନ୍ଧନ ଦ୍ୱାରା ପ୍ରଭୁଙ୍କଠାରେ ନିର୍ଭର କରି ନିର୍ଭୟରେ ଈଶ୍ବରଙ୍କ ବାକ୍ୟ କହିବା ନିମନ୍ତେ ଅତି ଉତ୍ସୁକଭାବେ ସାହସୀ ହୋଇଅଛନ୍ତି।","āhuri madhẏa adhikāṁśa bhāimānē mōhara bandhana dvārā prabhuṅkaṭhārē nirbhara kari nirbhaẏarē īśbaraṅka bākẏa kahibā nimantē ati utsukabhābē sāhasī hōiachanti.",null],[1,15,"କେହି କେହି ଈର୍ଷା ଓ ବିବାଦ ହେତୁ ଖ୍ରୀଷ୍ଟଙ୍କୁ ପ୍ରଚାର କରୁଅଛନ୍ତି ସତ୍ୟ, କିନ୍ତୁ ଆଉ କେହି କେହି ସତ୍ ଭାବରେ ତାହା କରୁଅଛନ୍ତି;","kēhi kēhi īrṣā ō bibāda hētu khrīṣṭaṅku pracāra karuachanti satẏa, kintu āu kēhi kēhi sat bhābarē tāhā karuachanti;",null],[1,16,"ମୁଁ ଯେ ସୁସମାଚାରର ପକ୍ଷ ସମର୍ଥନ କରିବା ନିମନ୍ତେ ନିଯୁକ୍ତ ରହିଅଛି, ଏହା ଜାଣି ଏକ ପକ୍ଷ ପ୍ରେମ ହେତୁ ତାହା କରନ୍ତି,","mum̐ yē susamācārara pakṣa samarthana karibā nimantē niyukta rahiachi, ēhā jāṇi ēka pakṣa prēma hētu tāhā karanti,",null],[1,17,"କିନ୍ତୁ ଅନ୍ୟ ପକ୍ଷ ମୋହର ବନ୍ଧନରେ ମୋତେ କ୍ଳେଶ ଦେବାକୁ ଭାବି ଅସରଳ ଭାବରେ ସ୍ୱାର୍ଥପରତା ସକାଶେ ଖ୍ରୀଷ୍ଟଙ୍କୁ ପ୍ରଚାର କରନ୍ତି।","kintu anẏa pakṣa mōhara bandhanarē mōtē kḷēśa dēbāku bhābi asaraḷa bhābarē svārthaparatā sakāśē khrīṣṭaṅku pracāra karanti.",null],[1,18,"ସେଥିରେ ବା କଅଣ? କପଟ ଭାବରେ ହେଉ ବା ସତ୍ୟ ଭାବରେ ହେଉ, ଯେକୌଣସି ପ୍ରକାରେ ଖ୍ରୀଷ୍ଟ ପ୍ରଚାରିତ ହେଉଅଛନ୍ତି, ଏଥିରେ ମୁଁ ଆନନ୍ଦ କରୁଅଛି, ହଁ, ଆନନ୍ଦ କରିବି।","sēthirē bā kaaṇa? kapaṭa bhābarē hēu bā satẏa bhābarē hēu, yēkauṇasi prakārē khrīṣṭa pracārita hēuachanti, ēthirē mum̐ ānanda karuachi, ham̐, ānanda karibi.",null],[1,19,"କାରଣ ମୁଁ ଜାଣେ ଯେ, ତୁମ୍ଭମାନଙ୍କ ନିବେଦନ ଓ ଯୀଶୁ ଖ୍ରୀଷ୍ଟଙ୍କ ଆତ୍ମାଙ୍କ ସାହାଯ୍ୟ ଦ୍ୱାରା ଏସବୁ ମୋହର ପରିତ୍ରାଣର ଅନୁକୂଳ ହେବ,","kāraṇa mum̐ jāṇē yē, tumbhamānaṅka nibēdana ō yīśu khrīṣṭaṅka ātmāṅka sāhāyẏa dvārā ēsabu mōhara paritrāṇara anukūḷa hēba,",null],[1,20,"ଏ ସମ୍ବନ୍ଧରେ ମୋହର ଏକାନ୍ତ ଆକାଂକ୍ଷା ଓ ଭରସା ଅଛି ଯେ ମୁଁ କୌଣସି ବିଷୟରେ ଲଜ୍ଜିତ ହେବି ନାହିଁ, କିନ୍ତୁ ସର୍ବଦା ଯେଉଁପରି, ଏବେ ମଧ୍ୟ ସେହିପରି ଅତି ସାହସରେ, ଜୀବନରେ ହେଉ ବା ମରଣରେ ହେଉ, ଖ୍ରୀଷ୍ଟଙ୍କୁ ମୋହର ଶରୀରରେ ମହିମାନ୍ୱିତ କରିବି।","ē sambandharē mōhara ēkānta ākāṁkṣā ō bharasā achi yē mum̐ kauṇasi biṣaẏarē lajjita hēbi nāhim̐, kintu sarbadā yēum̐pari, ēbē madhẏa sēhipari ati sāhasarē, jībanarē hēu bā maraṇarē hēu, khrīṣṭaṅku mōhara śarīrarē mahimānvita karibi.",null],[1,21,"କାରଣ ମୋʼ ପକ୍ଷରେ ଜୀବନଧାରଣ ଖ୍ରୀଷ୍ଟ, ପୁଣି, ମୃତ୍ୟୁଭୋଗ ଲାଭଜନକ।","kāraṇa mō pakṣarē jībanadhāraṇa khrīṣṭa, puṇi, mr̥tẏubhōga lābhajanaka.",null],[1,22,"କିନ୍ତୁ ଶରୀରରେ ଜୀବନଧାରଣ ଯଦି ମୋʼ ପକ୍ଷରେ ଫଳପ୍ରଦ କାର୍ଯ୍ୟ ସାଧନ ହୁଏ, ତେବେ ମୁଁ କଅଣ ପସନ୍ଦ କରିବି, ତାହା ଜାଣେ ନାହିଁ।","kintu śarīrarē jībanadhāraṇa yadi mō pakṣarē phaḷaprada kāryẏa sādhana huē, tēbē mum̐ kaaṇa pasanda karibi, tāhā jāṇē nāhim̐.",null],[1,23,"ମୁଁ ଦୁଇଟି ବିଷୟ ଘେନି ମହା ସମସ୍ୟାରେ ପଡ଼ିଅଛି; ଇହଲୋକରୁ ପ୍ରସ୍ଥାନ କରି ଖ୍ରୀଷ୍ଟଙ୍କ ସହିତ ରହିବାକୁ ମୋହର ଇଚ୍ଛା, କାରଣ ତାହା ଅତୀବ ଶ୍ରେୟସ୍କର;","mum̐ duiṭi biṣaẏa ghēni mahā samasẏārē paṛiachi; ihalōkaru prasthāna kari khrīṣṭaṅka sahita rahibāku mōhara icchā, kāraṇa tāhā atība śrēẏaskara;",null],[1,24,"ମାତ୍ର ଶରୀରରେ ରହିବା ତୁମ୍ଭମାନଙ୍କ ନିମନ୍ତେ ଅଧିକ ଆବଶ୍ୟକ।","mātra śarīrarē rahibā tumbhamānaṅka nimantē adhika ābaśẏaka.",null],[1,25,"ଆଉ ମୁଁ ଦୃଢ଼ରୂପେ ଏହା ଜାଣେ ଯେ, ମୁଁ ରହିବି, ହଁ, ବିଶ୍ୱାସରେ ତୁମ୍ଭମାନଙ୍କର ବୃଦ୍ଧି ଓ ଆନନ୍ଦ ନିମନ୍ତେ ତୁମ୍ଭ ସମସ୍ତଙ୍କ ସହିତ ରହିବି,","āu mum̐ dr̥ṛharūpē ēhā jāṇē yē, mum̐ rahibi, ham̐, biśvāsarē tumbhamānaṅkara br̥ddhi ō ānanda nimantē tumbha samastaṅka sahita rahibi,",null],[1,26,"ଯେପରି ତୁମ୍ଭମାନଙ୍କ ମଧ୍ୟରେ ମୋହର ପୁନର୍ବାର ଉପସ୍ଥିତି ହେତୁ ମୋʼ ଦ୍ୱାରା ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କଠାରେ ତୁମ୍ଭମାନଙ୍କ ଦର୍ପ ଅଧିକ ବୃଦ୍ଧି ପାଇବ।","yēpari tumbhamānaṅka madhẏarē mōhara punarbāra upasthiti hētu mō dvārā khrīṣṭa yīśuṅkaṭhārē tumbhamānaṅka darpa adhika br̥ddhi pāiba.",null],[1,27,"ମୋହର ଏହି ମାତ୍ର ଇଚ୍ଛା, ଖ୍ରୀଷ୍ଟଙ୍କ ସୁସମାଚାରର ଯୋଗ୍ୟ ପ୍ରଜା ସ୍ୱରୂପେ ଆଚରଣ କର, ଯେପରି ମୁଁ ଉପସ୍ଥିତ ହୋଇ ତୁମ୍ଭମାନଙ୍କୁ ଦେଖିଲେ ଅବା ଅନୁପସ୍ଥିତ ଥାଇ ତୁମ୍ଭମାନଙ୍କ ବିଷୟରେ ଶୁଣିଲେ ଜାଣି ପାରିବି ଯେ, ତୁମ୍ଭେମାନେ ଏକ ଆତ୍ମାରେ ସ୍ଥିର ରହି ସୁସମାଚାରର ବିଶ୍ୱାସ ନିମନ୍ତେ ଏକ ପ୍ରାଣରେ ଏକସଙ୍ଗରେ ଉଦ୍ୟମ କରୁଅଛ,","mōhara ēhi mātra icchā, khrīṣṭaṅka susamācārara yōgẏa prajā svarūpē ācaraṇa kara, yēpari mum̐ upasthita hōi tumbhamānaṅku dēkhilē abā anupasthita thāi tumbhamānaṅka biṣaẏarē śuṇilē jāṇi pāribi yē, tumbhēmānē ēka ātmārē sthira rahi susamācārara biśvāsa nimantē ēka prāṇarē ēkasaṅgarē udẏama karuacha,",null],[1,28,"ପୁଣି, କୌଣସି ବିଷୟରେ ବିପକ୍ଷମାନଙ୍କ ଦ୍ୱାରା ତ୍ରାସଯୁକ୍ତ ନୁହଁ; ତାହା ସେମାନଙ୍କ ପକ୍ଷରେ ବିନାଶ, କିନ୍ତୁ ତୁମ୍ଭମାନଙ୍କ ପକ୍ଷରେ ପରିତ୍ରାଣର ଈଶ୍ବରଦତ୍ତ ଏକ ଲକ୍ଷଣ;","puṇi, kauṇasi biṣaẏarē bipakṣamānaṅka dvārā trāsayukta nuham̐; tāhā sēmānaṅka pakṣarē bināśa, kintu tumbhamānaṅka pakṣarē paritrāṇara īśbaradatta ēka lakṣaṇa;",null],[1,29,"କାରଣ ଖ୍ରୀଷ୍ଟଙ୍କଠାରେ କେବଳ ବିଶ୍ୱାସ କରିବା ନିମନ୍ତେ ତୁମ୍ଭମାନଙ୍କୁ ଯେ ଅନୁଗ୍ରହ ଦିଆଯାଇଅଛି, ତାହା ନୁହେଁ, ମାତ୍ର ତାହାଙ୍କ ସକାଶେ ଦୁଃଖଭୋଗ ମଧ୍ୟ କରିବା ନିମନ୍ତେ ତୁମ୍ଭମାନଙ୍କୁ ଅନୁଗ୍ରହ ଦିଆଯାଇଅଛି;","kāraṇa khrīṣṭaṅkaṭhārē kēbaḷa biśvāsa karibā nimantē tumbhamānaṅku yē anugraha diāyāiachi, tāhā nuhēm̐, mātra tāhāṅka sakāśē duḥkhabhōga madhẏa karibā nimantē tumbhamānaṅku anugraha diāyāiachi;",null],[1,30,"ଆଉ ମୋତେ ଯେପରି ଯୁଦ୍ଧ କରିବାର ଦେଖିଥିଲ, ପୁଣି, ବର୍ତ୍ତମାନ କରୁଅଛି ବୋଲି ଶୁଣୁଅଛ, ତୁମ୍ଭେମାନେ ସେହିପରି ଯୁଦ୍ଧ କରୁଅଛ।","āu mōtē yēpari yuddha karibāra dēkhithila, puṇi, barttamāna karuachi bōli śuṇuacha, tumbhēmānē sēhipari yuddha karuacha.",null],[2,1,"ଅତଏବ, ଯଦି ଖ୍ରୀଷ୍ଟଙ୍କ ସହଭାଗିତାରେ କୌଣସି ଉତ୍ସାହ, କୌଣସି ପ୍ରେମପୂର୍ଣ୍ଣ ସାନ୍ତ୍ୱନା, ଆତ୍ମାଙ୍କ କୌଣସି ସହଭାଗିତା, ପୁଣି, କୌଣସି ପ୍ରେମପୂର୍ଣ୍ଣ କରୁଣା ଓ ଦୟା ଥାଏ,","ataēba, yadi khrīṣṭaṅka sahabhāgitārē kauṇasi utsāha, kauṇasi prēmapūrṇṇa sāntvanā, ātmāṅka kauṇasi sahabhāgitā, puṇi, kauṇasi prēmapūrṇṇa karuṇā ō daẏā thāē,",null],[2,2,"ତାହାହେଲେ ତୁମ୍ଭେମାନେ ଏକମନା, ଏକ ପ୍ରେମରେ ପ୍ରେମୀ, ଏକଚିତ୍ତ ଓ ଏକଭାବାପନ୍ନ ହୋଇ ମୋହର ଆନନ୍ଦ ପୂର୍ଣ୍ଣ କର,","tāhāhēlē tumbhēmānē ēkamanā, ēka prēmarē prēmī, ēkacitta ō ēkabhābāpanna hōi mōhara ānanda pūrṇṇa kara,",null],[2,3,"ସ୍ୱାର୍ଥପରତା ଅବା ଅସାର ଗର୍ବ ହେତୁ କିଛି କର ନାହିଁ, ବରଂ ନମ୍ରଚିତ୍ତ ହୋଇ ପ୍ରତ୍ୟେକେ ଅନ୍ୟକୁ ଆପଣାଠାରୁ ଶ୍ରେଷ୍ଠ ମନେ କର;","svārthaparatā abā asāra garba hētu kichi kara nāhim̐, baraṁ namracitta hōi pratẏēkē anẏaku āpaṇāṭhāru śrēṣṭha manē kara;",null],[2,4,"ପ୍ରତି ଜଣ କେବଳ ଆପଣା ବିଷୟରେ ମନୋଯୋଗୀ ନ ହୋଇ ଅନ୍ୟର ବିଷୟରେ ମଧ୍ୟ ମନୋଯୋଗୀ ହୁଅ।","prati jaṇa kēbaḷa āpaṇā biṣaẏarē manōyōgī na hōi anẏara biṣaẏarē madhẏa manōyōgī hua.",null],[2,5,"ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କର ଯେପରି ମନ ଥିଲା, ତୁମ୍ଭମାନଙ୍କର ସେହିପରି ମନ ହେଉ;","khrīṣṭa yīśuṅkara yēpari mana thilā, tumbhamānaṅkara sēhipari mana hēu;",null],[2,6,"ସେ ଈଶ୍ବରରୂପୀ ହେଲେ ହେଁ ଈଶ୍ବରଙ୍କ ସହିତ ସମାନ ହୋଇ ରହିବା ନିଜ ନିମନ୍ତେ ଧରି ରଖିବାର ବିଷୟ ମନେ କଲେ ନାହିଁ,","sē īśbararūpī hēlē hēm̐ īśbaraṅka sahita samāna hōi rahibā nija nimantē dhari rakhibāra biṣaẏa manē kalē nāhim̐,",null],[2,7,"କିନ୍ତୁ ମନୁଷ୍ୟ ସଦୃଶ ହୋଇ ଦାସରୂପ ଧାରଣ କରି ଆପଣାକୁ ଶୂନ୍ୟ କଲେ;","kintu manuṣẏa sadr̥śa hōi dāsarūpa dhāraṇa kari āpaṇāku śūnẏa kalē;",null],[2,8,"ପୁଣି, ମନୁଷ୍ୟ ଭାବରେ ଦେଖାଯାଇ ମୃତ୍ୟୁ ପର୍ଯ୍ୟନ୍ତ, ହଁ, କ୍ରୁଶୀୟ ମୃତ୍ୟୁ ପର୍ଯ୍ୟନ୍ତ ଆଜ୍ଞାବହ ହୋଇ ଆପଣାକୁ ଅବନତ କଲେ।","puṇi, manuṣẏa bhābarē dēkhāyāi mr̥tẏu paryẏanta, ham̐, kruśīẏa mr̥tẏu paryẏanta ājñābaha hōi āpaṇāku abanata kalē.",null],[2,9,"ଏହି କାରଣରୁ ଈଶ୍ବର ତାହାଙ୍କୁ ଅତିଶୟ ଉନ୍ନତ କରିଅଛନ୍ତି, ପୁଣି, ସମସ୍ତ ନାମ ଅପେକ୍ଷା ସର୍ବୋତ୍କୃଷ୍ଟ ନାମ ତାହାଙ୍କୁ ପ୍ରଦାନ କରିଅଛନ୍ତି,","ēhi kāraṇaru īśbara tāhāṅku atiśaẏa unnata kariachanti, puṇi, samasta nāma apēkṣā sarbōtkr̥ṣṭa nāma tāhāṅku pradāna kariachanti,",null],[2,10,"ଯେପରି ସ୍ୱର୍ଗ, ମର୍ତ୍ତ୍ୟ ଓ ପାତାଳରେ ଥିବା ପ୍ରତ୍ୟେକ ଆଣ୍ଠୁ ଯୀଶୁଙ୍କ ନାମରେ ନତ ହେବ,","yēpari svarga, marttẏa ō pātāḷarē thibā pratẏēka āṇṭhu yīśuṅka nāmarē nata hēba,",null],[2,11,"ପୁଣି, ପିତା ଈଶ୍ବରଙ୍କ ଗୌରବ ନିମନ୍ତେ ପ୍ରତ୍ୟେକ ଜିହ୍ୱା ଯୀଶୁ ଖ୍ରୀଷ୍ଟ ପ୍ରଭୁ ବୋଲି ସ୍ୱୀକାର କରିବ।","puṇi, pitā īśbaraṅka gauraba nimantē pratẏēka jihvā yīśu khrīṣṭa prabhu bōli svīkāra kariba.",null],[2,12,"ଅତଏବ, ହେ ମୋହର ପ୍ରିୟମାନେ, ଯେପରି ତୁମ୍ଭେମାନେ ସର୍ବଦା ଆଜ୍ଞାବହ ହୋଇଅଛ, କେବଳ ମୋହର ଉପସ୍ଥିତିରେ କଲା ପରି ନୁହେଁ, କିନ୍ତୁ ବର୍ତ୍ତମାନ ମୋହର ଅନୁପସ୍ଥିତିରେ ଆହୁରି ଅଧିକ ରୂପେ ଭୟ ଓ କମ୍ପ ସହ ଆପଣା ଆପଣା ପରିତ୍ରାଣ ସାଧନ କର,","ataēba, hē mōhara priẏamānē, yēpari tumbhēmānē sarbadā ājñābaha hōiacha, kēbaḷa mōhara upasthitirē kalā pari nuhēm̐, kintu barttamāna mōhara anupasthitirē āhuri adhika rūpē bhaẏa ō kampa saha āpaṇā āpaṇā paritrāṇa sādhana kara,",null],[2,13,"କାରଣ ଇଚ୍ଛା କରିବାକୁ ଓ ସାଧନ କରିବାକୁ ଈଶ୍ବର ଆପଣା ମଙ୍ଗଳମୟ ସଙ୍କଳ୍ପର ସଫଳତା ନିମନ୍ତେ ତୁମ୍ଭମାନଙ୍କ ଅନ୍ତରରେ କାର୍ଯ୍ୟ କରନ୍ତି।","kāraṇa icchā karibāku ō sādhana karibāku īśbara āpaṇā maṅgaḷamaẏa saṅkaḷpara saphaḷatā nimantē tumbhamānaṅka antararē kāryẏa karanti.",null],[2,14,"ବଚସା ଓ ତର୍କବିତର୍କ ବିନା ସମସ୍ତ କାର୍ଯ୍ୟ କର,","bacasā ō tarkabitarka binā samasta kāryẏa kara,",null],[2,15,"ଯେପରି ତୁମ୍ଭେମାନେ ନିର୍ଦ୍ଦୋଷ ଓ ଅମାୟିକ ହୋଇ ଏହି କୁଟିଳ ବିପଥଗାମୀ ବଂଶ ମଧ୍ୟରେ ଈଶ୍ବରଙ୍କ ଅନିନ୍ଦନୀୟ ସନ୍ତାନସନ୍ତତି ହୁଅ; ସେମାନଙ୍କ ମଧ୍ୟରେ ତୁମ୍ଭେମାନେ ଜୀବନର ବାକ୍ୟ ଧରି ଜଗତରେ ଜ୍ୟୋତିଃ ସ୍ୱରୂପ ପ୍ରକାଶ ପାଉଅଛ;","yēpari tumbhēmānē nirddōṣa ō amāẏika hōi ēhi kuṭiḷa bipathagāmī baṁśa madhẏarē īśbaraṅka anindanīẏa santānasantati hua; sēmānaṅka madhẏarē tumbhēmānē jībanara bākẏa dhari jagatarē jẏōtiḥ svarūpa prakāśa pāuacha;",null],[2,16,"ସେଥିରେ ମୁଁ ଯେ ବୃଥାରେ ଦୌଡ଼ି ନାହିଁ କିଅବା ବୃଥାରେ ପରିଶ୍ରମ କରି ନାହିଁ, ସେ ସମ୍ବନ୍ଧରେ ଖ୍ରୀଷ୍ଟଙ୍କ ପୁନରାଗମନ ଦିନରେ ଦର୍ପ କରିପାରିବି।","sēthirē mum̐ yē br̥thārē dauṛi nāhim̐ kiabā br̥thārē pariśrama kari nāhim̐, sē sambandharē khrīṣṭaṅka punarāgamana dinarē darpa karipāribi.",null],[2,17,"ହଁ, ଆଉ ଯଦି ମୋହର ରକ୍ତ ତୁମ୍ଭମାନଙ୍କ ବିଶ୍ୱାସ ସମ୍ବନ୍ଧୀୟ ସେବାରେ ପେୟ ନୈବେଦ୍ୟ ପରି ଢଳା ଯାଏ, ତେବେ ମଧ୍ୟ ମୁଁ ଆନନ୍ଦିତ ଓ ତୁମ୍ଭ ସମସ୍ତଙ୍କ ସହିତ ଉଲ୍ଲସିତ।","ham̐, āu yadi mōhara rakta tumbhamānaṅka biśvāsa sambandhīẏa sēbārē pēẏa naibēdẏa pari ḍhaḷā yāē, tēbē madhẏa mum̐ ānandita ō tumbha samastaṅka sahita ullasita.",null],[2,18,"ଆଉ, ସେହି ପ୍ରକାରେ ତୁମ୍ଭେମାନେ ମଧ୍ୟ ଆନନ୍ଦ କର ଓ ମୋʼ ସହିତ ଉଲ୍ଲାସ କର।","āu, sēhi prakārē tumbhēmānē madhẏa ānanda kara ō mō sahita ullāsa kara.",null],[2,19,"କିନ୍ତୁ ମୁଁ ତୁମ୍ଭମାନଙ୍କ ନିକଟକୁ ତୀମଥିଙ୍କୁ ଶୀଘ୍ର ପଠାଇବି ବୋଲି ପ୍ରଭୁ ଯୀଶୁଙ୍କଠାରେ ଭରସା କରୁଅଛି, ଯେପରି ତୁମ୍ଭମାନଙ୍କ ଅବସ୍ଥା ବିଷୟ ଜାଣି ମୁଁ ମଧ୍ୟ ଉତ୍ସାହିତ ହେବି।","kintu mum̐ tumbhamānaṅka nikaṭaku tīmathiṅku śīghra paṭhāibi bōli prabhu yīśuṅkaṭhārē bharasā karuachi, yēpari tumbhamānaṅka abasthā biṣaẏa jāṇi mum̐ madhẏa utsāhita hēbi.",null],[2,20,"କାରଣ ଯେ ତୁମ୍ଭମାନଙ୍କ ବିଷୟରେ ପ୍ରକୃତରେ ମନୋଯୋଗ କରିବ, ଏପରି ସମଭାବାପନ୍ନ ଲୋକ ତାହାଙ୍କ ବିନା ମୋʼ ନିକଟରେ ଆଉ କେହି ନାହିଁ।","kāraṇa yē tumbhamānaṅka biṣaẏarē prakr̥tarē manōyōga kariba, ēpari samabhābāpanna lōka tāhāṅka binā mō nikaṭarē āu kēhi nāhim̐.",null],[2,21,"ଯେଣୁ ସମସ୍ତେ ଯୀଶୁ ଖ୍ରୀଷ୍ଟଙ୍କ ବିଷୟ ଚେଷ୍ଟା ନ କରି ସ୍ୱାର୍ଥ ଚେଷ୍ଟା କରନ୍ତି।","yēṇu samastē yīśu khrīṣṭaṅka biṣaẏa cēṣṭā na kari svārtha cēṣṭā karanti.",null],[2,22,"ସେ ଯେ ପରୀକ୍ଷାସିଦ୍ଧ ଲୋକ, ଏହା ତୁମ୍ଭେମାନେ ଜାଣ; ପୁତ୍ର ପିତାର ସେବା କଲା ପରି ସେ ତ ସୁସମାଚାର କାର୍ଯ୍ୟରେ ମୋʼ ସହିତ ସେବା କରିଥିଲେ।","sē yē parīkṣāsiddha lōka, ēhā tumbhēmānē jāṇa; putra pitāra sēbā kalā pari sē ta susamācāra kāryẏarē mō sahita sēbā karithilē.",null],[2,23,"ଅତଏବ, ମୋʼ ପ୍ରତି କଅଣ ଘଟିବ, ତାହା ଜାଣିବାମାତ୍ର ତାହାଙ୍କୁ ପଠାଇବି ବୋଲି ଭରସା କରୁଅଛି;","ataēba, mō prati kaaṇa ghaṭiba, tāhā jāṇibāmātra tāhāṅku paṭhāibi bōli bharasā karuachi;",null],[2,24,"କିନ୍ତୁ ମୁଁ ପ୍ରଭୁଙ୍କଠାରେ ବିଶ୍ୱାସ କରୁଅଛି ଯେ, ମୁଁ ନିଜେ ମଧ୍ୟ ଶୀଘ୍ର ଯିବି।","kintu mum̐ prabhuṅkaṭhārē biśvāsa karuachi yē, mum̐ nijē madhẏa śīghra yibi.",null],[2,25,"କିନ୍ତୁ ମୁଁ ମୋହର ଭ୍ରାତା, ସହକର୍ମୀ, ସହସେନା ଓ ମୋହର ଅଭାବ ପୂରଣ ନିମନ୍ତେ ତୁମ୍ଭମାନଙ୍କର ପ୍ରେରିତ ଓ ସେବକ ଏପାଫ୍ରାଦିତଙ୍କୁ ତୁମ୍ଭମାନଙ୍କ ନିକଟକୁ ପଠାଇବା ପାଇଁ ଆବଶ୍ୟକ ମନେ କଲି;","kintu mum̐ mōhara bhrātā, sahakarmī, sahasēnā ō mōhara abhāba pūraṇa nimantē tumbhamānaṅkara prērita ō sēbaka ēpāphrāditaṅku tumbhamānaṅka nikaṭaku paṭhāibā pāim̐ ābaśẏaka manē kali;",null],[2,26,"କାରଣ ସେ ତୁମ୍ଭ ସମସ୍ତଙ୍କୁ ଦେଖିବା ପାଇଁ ଅତ୍ୟନ୍ତ ଇଚ୍ଛୁକ, ପୁଣି, ସେ ପୀଡ଼ିତ ଅଛନ୍ତି ବୋଲି ତୁମ୍ଭେମାନେ ଶୁଣିଥିବାରୁ ଅତ୍ୟନ୍ତ ବ୍ୟଥିତ;","kāraṇa sē tumbha samastaṅku dēkhibā pāim̐ atẏanta icchuka, puṇi, sē pīṛita achanti bōli tumbhēmānē śuṇithibāru atẏanta bẏathita;",null],[2,27,"ହଁ, ସେ ମୃତ୍ୟୁ ସରିକି ପୀଡ଼ିତ ହୋଇଥିଲେ, କିନ୍ତୁ ଈଶ୍ବର ତାହାଙ୍କୁ ଦୟା କଲେ, ଆଉ କେବଳ ତାହାଙ୍କୁ ନୁହେଁ, ମାତ୍ର ଯେପରି ମୋʼ ପ୍ରତି ଦୁଃଖ ଉପରେ ଦୁଃଖ ଘଟିବ ନାହିଁ, ଏଥିପାଇଁ ମୋʼ ଉପରେ ମଧ୍ୟ ଦୟା କଲେ।","ham̐, sē mr̥tẏu sariki pīṛita hōithilē, kintu īśbara tāhāṅku daẏā kalē, āu kēbaḷa tāhāṅku nuhēm̐, mātra yēpari mō prati duḥkha uparē duḥkha ghaṭiba nāhim̐, ēthipāim̐ mō uparē madhẏa daẏā kalē.",null],[2,28,"ଏଣୁ ତୁମ୍ଭେମାନେ ଯେପରି ତାହାଙ୍କୁ ପୁନର୍ବାର ଦେଖି ଆନନ୍ଦ କର ଓ ମୋʼ ଦୁଃଖ ଯେପରି ଊଣା ପଡ଼େ, ଏଥିପାଇଁ ମୁଁ ତାହାଙ୍କୁ ପଠାଇବା ନିମନ୍ତେ ଅଧିକ ଯତ୍ନବାନ ହେଲି।","ēṇu tumbhēmānē yēpari tāhāṅku punarbāra dēkhi ānanda kara ō mō duḥkha yēpari ūṇā paṛē, ēthipāim̐ mum̐ tāhāṅku paṭhāibā nimantē adhika yatnabāna hēli.",null],[2,29,"ଅତଏବ, ପ୍ରଭୁଙ୍କ ହେତୁ ତାହାଙ୍କୁ ଅତି ଆନନ୍ଦରେ ଗ୍ରହଣ କର, ଆଉ ଏହି ପ୍ରକାର ବ୍ୟକ୍ତିମାନଙ୍କୁ ସମାଦର କର;","ataēba, prabhuṅka hētu tāhāṅku ati ānandarē grahaṇa kara, āu ēhi prakāra bẏaktimānaṅku samādara kara;",null],[2,30,"କାରଣ ମୋʼ ପ୍ରତି ତୁମ୍ଭମାନଙ୍କ ସେବାରେ ଯାହା କିଛି ଅଭାବ, ତାହା ପୂରଣ କରିବାକୁ ସେ ଖ୍ରୀଷ୍ଟଙ୍କ କାର୍ଯ୍ୟରେ ଆପଣା ଜୀବନ ବିପଦଗ୍ରସ୍ତ କରି ମୃତପ୍ରାୟ ହୋଇଥିଲେ।","kāraṇa mō prati tumbhamānaṅka sēbārē yāhā kichi abhāba, tāhā pūraṇa karibāku sē khrīṣṭaṅka kāryẏarē āpaṇā jībana bipadagrasta kari mr̥taprāẏa hōithilē.",null],[3,1,"ଅବଶେଷରେ, ହେ ମୋହର ଭାଇମାନେ, ପ୍ରଭୁଙ୍କଠାରେ ଆନନ୍ଦ କର। ଏକ-ପ୍ରକାର କଥା ତୁମ୍ଭମାନଙ୍କ ନିକଟକୁ ଥରକୁଥର ଲେଖିବା ମୋʼ ପ୍ରତି କ୍ଳାନ୍ତିଜନକ ନୁହେଁ, ବରଂ ସେହିସବୁ ତୁମ୍ଭମାନଙ୍କ ନିମନ୍ତେ ନିଷ୍ଠାଜନକ।","abaśēṣarē, hē mōhara bhāimānē, prabhuṅkaṭhārē ānanda kara. ēka-prakāra kathā tumbhamānaṅka nikaṭaku tharakuthara lēkhibā mō prati kḷāntijanaka nuhēm̐, baraṁ sēhisabu tumbhamānaṅka nimantē niṣṭhājanaka.",null],[3,2,"କୁକୁରମାନଙ୍କଠାରୁ ସାବଧାନ, ଦୁଷ୍ଟ କାର୍ଯ୍ୟକାରୀମାନଙ୍କଠାରୁ ସାବଧାନ, ସୁନ୍ନତବାଦୀ ଲୋକମାନଙ୍କଠାରୁ ସାବଧାନ;","kukuramānaṅkaṭhāru sābadhāna, duṣṭa kāryẏakārīmānaṅkaṭhāru sābadhāna, sunnatabādī lōkamānaṅkaṭhāru sābadhāna;",null],[3,3,"କାରଣ ଆମ୍ଭେମାନେ ପ୍ରକୃତରେ ସୁନ୍ନତ ପ୍ରାପ୍ତ, ଆମ୍ଭେମାନେ ଈଶ୍ବରଙ୍କ ଆତ୍ମାରେ ଉପାସନା କରୁ, ପୁଣି, ବାହ୍ୟିକ ବିଷୟ ଉପରେ ନିର୍ଭର ନ କରି ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କଠାରେ ଦର୍ପ କରୁ।","kāraṇa āmbhēmānē prakr̥tarē sunnata prāpta, āmbhēmānē īśbaraṅka ātmārē upāsanā karu, puṇi, bāhẏika biṣaẏa uparē nirbhara na kari khrīṣṭa yīśuṅkaṭhārē darpa karu.",null],[3,4,"ମୁଁ ତ ବାହ୍ୟିକ ବିଷୟ ଉପରେ ମଧ୍ୟ ନିର୍ଭର କରିପାରନ୍ତି; ଯଦି ଅନ୍ୟ କେହି ବାହ୍ୟିକ ବିଷୟ ଉପରେ ନିର୍ଭର କରିପାରେ ବୋଲି ମନେ କରେ, ତେବେ ମୁଁ ଅଧିକ କରିପାରେ;","mum̐ ta bāhẏika biṣaẏa uparē madhẏa nirbhara karipāranti; yadi anẏa kēhi bāhẏika biṣaẏa uparē nirbhara karipārē bōli manē karē, tēbē mum̐ adhika karipārē;",null],[3,5,"ମୁଁ ଅଷ୍ଟମ ଦିନରେ ସୁନ୍ନତ ପ୍ରାପ୍ତ, ଇସ୍ରାଏଲ ବଂଶଜାତ, ବିନ୍ୟାମୀନ୍ ଗୋଷ୍ଠୀୟ, ଏବ୍ରୀୟ-ରକ୍ତଜାତ ଜଣେ ଏବ୍ରୀୟ, ମୋଶାଙ୍କ ବ୍ୟବସ୍ଥା ପାଳନ ସମ୍ବନ୍ଧରେ ଜଣେ ଫାରୂଶୀ,","mum̐ aṣṭama dinarē sunnata prāpta, isrāēla baṁśajāta, binẏāmīn gōṣṭhīẏa, ēbrīẏa-raktajāta jaṇē ēbrīẏa, mōśāṅka bẏabasthā pāḷana sambandharē jaṇē phārūśī,",null],[3,6,"ଉଦ୍‌ଯୋଗ ସମ୍ବନ୍ଧରେ ମଣ୍ଡଳୀର ଜଣେ ତାଡ଼ନାକାରୀ, ପୁଣି, ମୋଶାଙ୍କ ବ୍ୟବସ୍ଥାଗତ ଧାର୍ମିକତା ସମ୍ବନ୍ଧରେ ନିର୍ଦ୍ଦୋଷ ଦେଖାଯାଇଥିଲି।","udyōga sambandharē maṇḍaḷīra jaṇē tāṛanākārī, puṇi, mōśāṅka bẏabasthāgata dhārmikatā sambandharē nirddōṣa dēkhāyāithili.",null],[3,7,"କିନ୍ତୁ ଯାହାସବୁ ମୋʼ ପକ୍ଷରେ ଲାଭଜନକ ଥିଲା, ସେହିସବୁ ମୁଁ ଖ୍ରୀଷ୍ଟଙ୍କ ନିମନ୍ତେ କ୍ଷତିଜନକ ବୋଲି ଗଣ୍ୟ କରିଅଛି।","kintu yāhāsabu mō pakṣarē lābhajanaka thilā, sēhisabu mum̐ khrīṣṭaṅka nimantē kṣatijanaka bōli gaṇẏa kariachi.",null],[3,8,"ହଁ, ପ୍ରକୃତରେ ମୁଁ ମୋହର ପ୍ରଭୁ ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କ ଜ୍ଞାନର ଉତ୍କୃଷ୍ଟତା ନିମନ୍ତେ ସମସ୍ତ ବିଷୟ କ୍ଷତିଜନକ ବୋଲି ଗଣ୍ୟ କରେ; ତାହାଙ୍କ ନିମନ୍ତେ ମୁଁ ସମସ୍ତ ବିଷୟର କ୍ଷତି ସହ୍ୟ କଲି, ପୁଣି, ସେହିସବୁ ଆବର୍ଜନା ସ୍ୱରୂପ ଗଣ୍ୟ କରେ, ଯେପରି ମୁଁ ଖ୍ରୀଷ୍ଟଙ୍କୁ ଲାଭ କରିପାରେ ଓ ତାହାଙ୍କର ବୋଲି ଜଣାଯାଏ,","ham̐, prakr̥tarē mum̐ mōhara prabhu khrīṣṭa yīśuṅka jñānara utkr̥ṣṭatā nimantē samasta biṣaẏa kṣatijanaka bōli gaṇẏa karē; tāhāṅka nimantē mum̐ samasta biṣaẏara kṣati sahẏa kali, puṇi, sēhisabu ābarjanā svarūpa gaṇẏa karē, yēpari mum̐ khrīṣṭaṅku lābha karipārē ō tāhāṅkara bōli jaṇāyāē,",null],[3,9,"ପୁଣି, ମୋଶାଙ୍କ ବ୍ୟବସ୍ଥା ପାଳନ ହେତୁ ନିଜର ଧାର୍ମିକତା ପ୍ରାପ୍ତ ନ ହୋଇ ବରଂ ଯେପରି ଖ୍ରୀଷ୍ଟଙ୍କଠାରେ ବିଶ୍ୱାସ ଦ୍ୱାରା ଈଶ୍ବରଦତ୍ତ ବିଶ୍ୱାସମୂଳକ ଧାର୍ମିକତା ପ୍ରାପ୍ତ ହୁଏ,","puṇi, mōśāṅka bẏabasthā pāḷana hētu nijara dhārmikatā prāpta na hōi baraṁ yēpari khrīṣṭaṅkaṭhārē biśvāsa dvārā īśbaradatta biśvāsamūḷaka dhārmikatā prāpta huē,",null],[3,10,"ଯେପରି ମୁଁ ତାହାଙ୍କୁ, ତାହାଙ୍କ ପୁନରୁତ୍ଥାନର ଶକ୍ତି ଓ ତାହାଙ୍କ ମୃତ୍ୟୁଭୋଗରେ ତାହାଙ୍କ ତୁଲ୍ୟ ହୋଇ ତାହାଙ୍କ ଦୁଃଖଭୋଗର ସହଭାଗିତା ଜ୍ଞାତ ହୁଏ,","yēpari mum̐ tāhāṅku, tāhāṅka punarutthānara śakti ō tāhāṅka mr̥tẏubhōgarē tāhāṅka tulẏa hōi tāhāṅka duḥkhabhōgara sahabhāgitā jñāta huē,",null],[3,11,"ଏବଂ କୌଣସି ପ୍ରକାରେ ମୃତମାନଙ୍କ ମଧ୍ୟରୁ ପୁନରୁତ୍ଥାନ ପ୍ରାପ୍ତ ହୋଇପାରେ।","ēbaṁ kauṇasi prakārē mr̥tamānaṅka madhẏaru punarutthāna prāpta hōipārē.",null],[3,12,"ମୁଁ ଯେ ଏବେ ସେହି ସମସ୍ତ ପ୍ରାପ୍ତ ହୋଇଅଛି ଅବା ସିଦ୍ଧି ଲାଭ କରିଅଛି, ତାହା ନୁହେଁ, କିନ୍ତୁ ମୁଁ ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କ ଦ୍ୱାରା ଧୃତ ହୋଇଥିବାରୁ ତାହା ଧରିବା ପାଇଁ ଦୌଡ଼ୁଅଛି।","mum̐ yē ēbē sēhi samasta prāpta hōiachi abā siddhi lābha kariachi, tāhā nuhēm̐, kintu mum̐ khrīṣṭa yīśuṅka dvārā dhr̥ta hōithibāru tāhā dharibā pāim̐ dauṛuachi.",null],[3,13,"ହେ ଭାଇମାନେ, ମୁଁ ଏପର୍ଯ୍ୟନ୍ତ ତାହା ଧରିଅଛି ବୋଲି ମନେ କରୁ ନାହିଁ, କିନ୍ତୁ ଗୋଟିଏ ବିଷୟ ମୁଁ କରୁଅଛି,","hē bhāimānē, mum̐ ēparyẏanta tāhā dhariachi bōli manē karu nāhim̐, kintu gōṭiē biṣaẏa mum̐ karuachi,",null],[3,14,"ପଶ୍ଚାତ୍‍ ବିଷୟସବୁ ମନରୁ ଦୂର କରି ସମ୍ମୁଖରେ ଥିବା ବିଷୟଗୁଡ଼ିକ ପ୍ରତି ଦୃଷ୍ଟି ରଖି ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କଠାରେ ଈଶ୍ବରଙ୍କ ସ୍ୱର୍ଗୀୟ ଆହ୍ୱାନର ପୁରସ୍କାର ପାଇବା ନିମନ୍ତେ ପ୍ରାଣପଣ କରି ଲକ୍ଷ୍ୟ ସ୍ଥଳକୁ ଦୌଡ଼ୁଅଛି।","paścāt biṣaẏasabu manaru dūra kari sammukharē thibā biṣaẏaguṛika prati dr̥ṣṭi rakhi khrīṣṭa yīśuṅkaṭhārē īśbaraṅka svargīẏa āhvānara puraskāra pāibā nimantē prāṇapaṇa kari lakṣẏa sthaḷaku dauṛuachi.",null],[3,15,"ଅତଏବ, ଆସ, ଆମ୍ଭେମାନେ ଯେତେ ଲୋକ ସିଦ୍ଧ, ଏହିପରି ଭାବ ଧାରଣ କରୁ, ଆଉ ଯଦି କୌଣସି ବିଷୟରେ ତୁମ୍ଭମାନଙ୍କର ଭାବ ଭିନ୍ନ ପ୍ରକାର ଥାଏ, ତେବେ ଏହା ମଧ୍ୟ ଈଶ୍ବର ତୁମ୍ଭମାନଙ୍କ ନିକଟରେ ପ୍ରକାଶ କରିବେ;","ataēba, āsa, āmbhēmānē yētē lōka siddha, ēhipari bhāba dhāraṇa karu, āu yadi kauṇasi biṣaẏarē tumbhamānaṅkara bhāba bhinna prakāra thāē, tēbē ēhā madhẏa īśbara tumbhamānaṅka nikaṭarē prakāśa karibē;",null],[3,16,"କେବଳ, ଆମ୍ଭେମାନେ ଯେତେ ପର୍ଯ୍ୟନ୍ତ ଅଗ୍ରସର ହୋଇଅଛୁ, ସେହି ଅନୁସାରେ ଆଚରଣ କରୁ।","kēbaḷa, āmbhēmānē yētē paryẏanta agrasara hōiachu, sēhi anusārē ācaraṇa karu.",null],[3,17,"ହେ ଭ୍ରାତୃଗଣ, ତୁମ୍ଭେମାନେ ଏକତ୍ର ମିଳି ମୋହର ଅନୁକାରୀ ହୁଅ, ପୁଣି, ଆମ୍ଭମାନଙ୍କଠାରେ ଯେଉଁ ଆଦର୍ଶ ଦେଖୁଅଛ, ଯେଉଁମାନେ ତଦନୁଯାୟୀ ଆଚରଣ କରନ୍ତି, ସେମାନଙ୍କ ପ୍ରତି ଦୃଷ୍ଟି କର।","hē bhrātr̥gaṇa, tumbhēmānē ēkatra miḷi mōhara anukārī hua, puṇi, āmbhamānaṅkaṭhārē yēum̐ ādarśa dēkhuacha, yēum̐mānē tadanuyāẏī ācaraṇa karanti, sēmānaṅka prati dr̥ṣṭi kara.",null],[3,18,"କାରଣ ଏପରି ଅନେକ ଅଛନ୍ତି, ଯେଉଁମାନଙ୍କର ଆଚରଣ ବିଷୟରେ ମୁଁ ତୁମ୍ଭମାନଙ୍କୁ ଥରକୁଥର କହିଅଛି, ଆଉ ବର୍ତ୍ତମାନ ମଧ୍ୟ କାନ୍ଦି କାନ୍ଦି କହୁଅଛି, ସେମାନେ ଖ୍ରୀଷ୍ଟଙ୍କ କ୍ରୁଶର ଶତ୍ରୁ;","kāraṇa ēpari anēka achanti, yēum̐mānaṅkara ācaraṇa biṣaẏarē mum̐ tumbhamānaṅku tharakuthara kahiachi, āu barttamāna madhẏa kāndi kāndi kahuachi, sēmānē khrīṣṭaṅka kruśara śatru;",null],[3,19,"ସେମାନଙ୍କ ପରିଣାମ ବିନାଶ, ଉଦର ସେମାନଙ୍କର ଦେବତା, ସେମାନେ ଆପଣା ଆପଣା ଲଜ୍ଜାକୁ ଦର୍ପର ବିଷୟ ମନେ କରନ୍ତି, ପୁଣି, ପାର୍ଥିବ ବିଷୟଗୁଡ଼ିକରେ ଆସକ୍ତ ଅଟନ୍ତି।","sēmānaṅka pariṇāma bināśa, udara sēmānaṅkara dēbatā, sēmānē āpaṇā āpaṇā lajjāku darpara biṣaẏa manē karanti, puṇi, pārthiba biṣaẏaguṛikarē āsakta aṭanti.",null],[3,20,"ଆମ୍ଭେମାନେ ତ ସ୍ୱର୍ଗର ପ୍ରଜା, ସେ ସ୍ଥାନରୁ ମଧ୍ୟ ଆମ୍ଭେମାନେ ତ୍ରାଣକର୍ତ୍ତା ପ୍ରଭୁ ଯୀଶୁ ଖ୍ରୀଷ୍ଟଙ୍କ ଆଗମନର ଅପେକ୍ଷାରେ ଅଛୁ;","āmbhēmānē ta svargara prajā, sē sthānaru madhẏa āmbhēmānē trāṇakarttā prabhu yīśu khrīṣṭaṅka āgamanara apēkṣārē achu;",null],[3,21,"ସେ ଆପଣାର ଯେଉଁ କାର୍ଯ୍ୟସାଧକ ଶକ୍ତି ଦ୍ୱାରା ସମସ୍ତ ବିଷୟକୁ ନିଜର ବଶୀଭୂତ କରିପାରନ୍ତି, ତଦ୍ୱାରା ଆମ୍ଭମାନଙ୍କର ଛାର ଶରୀରକୁ ରୂପାନ୍ତରିତ କରି ଆପଣାର ଗୌରବମୟ ଶରୀରର ସଦୃଶ କରିବେ।","sē āpaṇāra yēum̐ kāryẏasādhaka śakti dvārā samasta biṣaẏaku nijara baśībhūta karipāranti, tadvārā āmbhamānaṅkara chāra śarīraku rūpāntarita kari āpaṇāra gaurabamaẏa śarīrara sadr̥śa karibē.",null],[4,1,"ଅତଏବ, ହେ ମୋହର ପ୍ରିୟ ଓ ଇଷ୍ଟ, ମୋହର ଆନନ୍ଦ ଓ ମୁକୁଟ ସ୍ୱରୂପ ଭ୍ରାତୃବୃନ୍ଦ, ଏହିପରି ଭାବରେ ପ୍ରଭୁଙ୍କଠାରେ ସ୍ଥିର ହୋଇଥାଅ।","ataēba, hē mōhara priẏa ō iṣṭa, mōhara ānanda ō mukuṭa svarūpa bhrātr̥br̥nda, ēhipari bhābarē prabhuṅkaṭhārē sthira hōithāa.",null],[4,2,"ପ୍ରଭୁଙ୍କଠାରେ ଏକମନା ହେବା ନିମନ୍ତେ ମୁଁ ଇୟଦିଆ ଓ ସୁନ୍ତୁଖୀ ଉଭୟଙ୍କୁ ଅନୁରୋଧ କରୁଅଛି।","prabhuṅkaṭhārē ēkamanā hēbā nimantē mum̐ iẏadiā ō suntukhī ubhaẏaṅku anurōdha karuachi.",null],[4,3,"ପୁଣି, ହେ ପ୍ରକୃତ ସହକାରୀ, ଏହି ମହିଳାମାନଙ୍କୁ ସାହାଯ୍ୟ କରିବା ପାଇଁ ତୁମ୍ଭକୁ ମଧ୍ୟ ନିବେଦନ କରୁଅଛି, କାରଣ ଏମାନେ କ୍ଳେମେନ୍ସ୍ ଓ ମୋହର ଅନ୍ୟ ସହକର୍ମୀମାନଙ୍କ ସଙ୍ଗରେ ସୁସମାଚାର କାର୍ଯ୍ୟରେ ମୋʼ ସହିତ ପରିଶ୍ରମ କରିଅଛନ୍ତି; ସେହି ସହକର୍ମୀମାନଙ୍କର ନାମ ଜୀବନ ପୁସ୍ତକରେ ଅଛି।","puṇi, hē prakr̥ta sahakārī, ēhi mahiḷāmānaṅku sāhāyẏa karibā pāim̐ tumbhaku madhẏa nibēdana karuachi, kāraṇa ēmānē kḷēmēns ō mōhara anẏa sahakarmīmānaṅka saṅgarē susamācāra kāryẏarē mō sahita pariśrama kariachanti; sēhi sahakarmīmānaṅkara nāma jībana pustakarē achi.",null],[4,4,"ସର୍ବଦା ପ୍ରଭୁଙ୍କଠାରେ ଆନନ୍ଦ କର, ପୁନଶ୍ଚ କହୁଅଛି, ଆନନ୍ଦ କର।","sarbadā prabhuṅkaṭhārē ānanda kara, punaśca kahuachi, ānanda kara.",null],[4,5,"ତୁମ୍ଭମାନଙ୍କର ମୃଦୁପଣ ସମସ୍ତ ଲୋକଙ୍କ ନିକଟରେ ପ୍ରକାଶିତ ହେଉ। ପ୍ରଭୁ ନିକଟବର୍ତ୍ତୀ।","tumbhamānaṅkara mr̥dupaṇa samasta lōkaṅka nikaṭarē prakāśita hēu. prabhu nikaṭabarttī.",null],[4,6,"କୌଣସି ବିଷୟରେ ଚିନ୍ତିତ ହୁଅ ନାହିଁ, କିନ୍ତୁ ସମସ୍ତ ବିଷୟରେ ପ୍ରାର୍ଥନା ଓ ବିନତି ଦ୍ୱାରା ଧନ୍ୟବାଦ ସହ ତୁମ୍ଭମାନଙ୍କର ନିବେଦନସବୁ ଈଶ୍ବରଙ୍କ ନିକଟରେ ଜଣାଅ।","kauṇasi biṣaẏarē cintita hua nāhim̐, kintu samasta biṣaẏarē prārthanā ō binati dvārā dhanẏabāda saha tumbhamānaṅkara nibēdanasabu īśbaraṅka nikaṭarē jaṇāa.",null],[4,7,"ସେଥିରେ ସମସ୍ତ ବୋଧର ଅଗମ୍ୟ ଯେ ଈଶ୍ବରଙ୍କ ଶାନ୍ତି, ତାହା ତୁମ୍ଭମାନଙ୍କର ହୃଦୟ ଓ ମନକୁ ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କ ସହଭାଗିତାରେ ସୁରକ୍ଷା କରି ରଖିବ।","sēthirē samasta bōdhara agamẏa yē īśbaraṅka śānti, tāhā tumbhamānaṅkara hr̥daẏa ō manaku khrīṣṭa yīśuṅka sahabhāgitārē surakṣā kari rakhiba.",null],[4,8,"ଅବଶେଷରେ, ହେ ଭ୍ରାତୃଗଣ, ଯାହା ଯାହା ସତ୍ୟ, ଯାହା ଯାହା ଆଦରଣୀୟ, ଯାହା ଯାହା ଯଥାର୍ଥ, ଯାହା ଯାହା ବିଶୁଦ୍ଧ, ଯାହା ଯାହା ପ୍ରିୟ, ଯାହା ଯାହା ସୁଖ୍ୟାତିଯୁକ୍ତ, ଯେକୌଣସି ସଦ୍‍ଗୁଣ ଓ ପ୍ରଶଂସାର ବିଷୟ ଥାଏ, ସେହି ସମସ୍ତ ବିଷୟ ଚିନ୍ତା କର।","abaśēṣarē, hē bhrātr̥gaṇa, yāhā yāhā satẏa, yāhā yāhā ādaraṇīẏa, yāhā yāhā yathārtha, yāhā yāhā biśuddha, yāhā yāhā priẏa, yāhā yāhā sukhẏātiyukta, yēkauṇasi sadguṇa ō praśaṁsāra biṣaẏa thāē, sēhi samasta biṣaẏa cintā kara.",null],[4,9,"ତୁମ୍ଭେମାନେ ଯେ ସମସ୍ତ ବିଷୟ ମୋʼଠାରୁ ଶିଖିଅଛ, ପାଇଅଛ, ଶୁଣିଅଛ ଓ ମୋʼ ଠାରେ ଦେଖିଅଛ, ସେହିସବୁ କର; ସେଥିରେ ଶାନ୍ତିଦାତା ଈଶ୍ବର ତୁମ୍ଭମାନଙ୍କର ସହବର୍ତ୍ତୀ ହେବେ।","tumbhēmānē yē samasta biṣaẏa mōṭhāru śikhiacha, pāiacha, śuṇiacha ō mō ṭhārē dēkhiacha, sēhisabu kara; sēthirē śāntidātā īśbara tumbhamānaṅkara sahabarttī hēbē.",null],[4,10,"ଏବେ ଅବଶେଷରେ ମୋʼ ନିମନ୍ତେ ତୁମ୍ଭମାନଙ୍କର ଚିନ୍ତା ଯେ ପ୍ରକାଶ ହୋଇପାରିଲା, ଏଥିପାଇଁ ମୁଁ ପ୍ରଭୁଙ୍କଠାରେ ମହାନନ୍ଦ କରୁଅଛି; ପ୍ରକୃତରେ ମୋʼ ବିଷୟରେ ତୁମ୍ଭମାନଙ୍କର ଚିନ୍ତା ଥିଲା, କିନ୍ତୁ ସୁଯୋଗ ନ ଥିଲା।","ēbē abaśēṣarē mō nimantē tumbhamānaṅkara cintā yē prakāśa hōipārilā, ēthipāim̐ mum̐ prabhuṅkaṭhārē mahānanda karuachi; prakr̥tarē mō biṣaẏarē tumbhamānaṅkara cintā thilā, kintu suyōga na thilā.",null],[4,11,"ଅଭାବ ହେତୁ ମୁଁ ଯେ ଏହା କହୁଅଛି, ତାହା ନୁହେଁ, କାରଣ ମୁଁ ଯେକୌଣସି ଅବସ୍ଥାରେ ଥାଏ, ସେଥିରେ ସନ୍ତୁଷ୍ଟ ରହିବାକୁ ଶିକ୍ଷା କରିଅଛି।","abhāba hētu mum̐ yē ēhā kahuachi, tāhā nuhēm̐, kāraṇa mum̐ yēkauṇasi abasthārē thāē, sēthirē santuṣṭa rahibāku śikṣā kariachi.",null],[4,12,"ଦୀନତା ଭୋଗ କରି ଜାଣେ ଓ ପ୍ରଚୁରତା ମଧ୍ୟ ଭୋଗ କରି ଜାଣେ; ସର୍ବ ଅବସ୍ଥାରେ ଓ ସର୍ବ ବିଷୟରେ, ପରିତୃପ୍ତ ହେବାରେ ବା କ୍ଷୁଧିତ ରହିବାରେ, ପ୍ରଚୁରତା ଭୋଗ କରିବାରେ କିଅବା ଅଭାବଗ୍ରସ୍ତ ହେବାରେ ମୁଁ ସୁଶିକ୍ଷିତ ହୋଇଛି।","dīnatā bhōga kari jāṇē ō pracuratā madhẏa bhōga kari jāṇē; sarba abasthārē ō sarba biṣaẏarē, paritr̥pta hēbārē bā kṣudhita rahibārē, pracuratā bhōga karibārē kiabā abhābagrasta hēbārē mum̐ suśikṣita hōichi.",null],[4,13,"ମୋହର ଶକ୍ତିଦାତାଙ୍କ ସାହାଯ୍ୟରେ ମୁଁ ସମସ୍ତ କରିପାରେ।","mōhara śaktidātāṅka sāhāyẏarē mum̐ samasta karipārē.",null],[4,14,"ତଥାପି ତୁମ୍ଭେମାନେ ମୋହର କ୍ଳେଶଭୋଗର ସହଭାଗୀ ହେବା ଦ୍ୱାରା ଭଲ କରିଅଛ।","tathāpi tumbhēmānē mōhara kḷēśabhōgara sahabhāgī hēbā dvārā bhala kariacha.",null],[4,15,"ହେ ଫିଲିପ୍ପୀୟମାନେ, ତୁମ୍ଭେମାନେ ମଧ୍ୟ ନିଜେ ଜାଣ ଯେ, ସୁସମାଚାର ପ୍ରଚାର କରିବା ଆରମ୍ଭ ସମୟରେ ଯେତେବେଳେ ମୁଁ ମାକିଦନିଆରୁ ପ୍ରସ୍ଥାନ କଲି, ସେତେବେଳେ ତୁମ୍ଭମାନଙ୍କ ବିନା ଆଉ କୌଣସି ମଣ୍ଡଳୀ ମୋହର ସହଭାଗୀ ହୋଇ ମୋʼ ସହିତ ଦେବା ନେବାର ହିସାବ ରଖି ନ ଥିଲେ।","hē philippīẏamānē, tumbhēmānē madhẏa nijē jāṇa yē, susamācāra pracāra karibā ārambha samaẏarē yētēbēḷē mum̐ mākidaniāru prasthāna kali, sētēbēḷē tumbhamānaṅka binā āu kauṇasi maṇḍaḷī mōhara sahabhāgī hōi mō sahita dēbā nēbāra hisāba rakhi na thilē.",null],[4,16,"କାରଣ ମୁଁ ଥେସଲନୀକୀ ସହରରେ ଥିବା ସମୟରେ ସୁଦ୍ଧା ତୁମ୍ଭେମାନେ ମୋହର ଅଭାବ ମୋଚନ ନିମନ୍ତେ ଥରେ, ହଁ, ଦୁଇ ଥର ଦାନ ପଠାଇଥିଲ।","kāraṇa mum̐ thēsalanīkī sahararē thibā samaẏarē suddhā tumbhēmānē mōhara abhāba mōcana nimantē tharē, ham̐, dui thara dāna paṭhāithila.",null],[4,17,"ଦାନ ସକାଶେ ମୁଁ ଲାଳାୟିତ ନୁହେଁ, ମାତ୍ର ଯେଉଁ ଫଳ ଦ୍ୱାରା ତୁମ୍ଭମାନଙ୍କ ହିସାବର ଜମାପାଖ ଅଧିକରୁ ଅଧିକ ବୃଦ୍ଧି ପାଉଅଛି, ସେଥିସକାଶେ ଲାଳାୟିତ।","dāna sakāśē mum̐ lāḷāẏita nuhēm̐, mātra yēum̐ phaḷa dvārā tumbhamānaṅka hisābara jamāpākha adhikaru adhika br̥ddhi pāuachi, sēthisakāśē lāḷāẏita.",null],[4,18,"ମୁଁ ସବୁ ପାଇଅଛି, ପୁଣି, ମୋହର ପ୍ରଚୁର ଅଛି; ତୁମ୍ଭମାନଙ୍କର ପଠାଇଥିବା ଯେଉଁ ସବୁ ବିଷୟ ଏପାଫ୍ରାଦିତଙ୍କ ପାଖରୁ ପାଇଅଛି, ସେହିସବୁ ମୋʼ ପାଇଁ ଯଥେଷ୍ଟ; ସେହିସବୁ ଈଶ୍ବରଙ୍କ ନିକଟରେ ତୁଷ୍ଟିଜନକ ସୁଗନ୍ଧି ନୈବେଦ୍ୟ ଓ ସୁଗ୍ରାହ୍ୟ ବଳିସ୍ୱରୂପ।","mum̐ sabu pāiachi, puṇi, mōhara pracura achi; tumbhamānaṅkara paṭhāithibā yēum̐ sabu biṣaẏa ēpāphrāditaṅka pākharu pāiachi, sēhisabu mō pāim̐ yathēṣṭa; sēhisabu īśbaraṅka nikaṭarē tuṣṭijanaka sugandhi naibēdẏa ō sugrāhẏa baḷisvarūpa.",null],[4,19,"ପୁଣି, ମୋହର ଈଶ୍ବର ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କଠାରେ ତାହାଙ୍କର ଗୌରବମୟ ଐଶ୍ୱର୍ଯ୍ୟ ଅନୁସାରେ ତୁମ୍ଭମାନଙ୍କର ପ୍ରତ୍ୟେକ ଅଭାବ ପୂରଣ କରିବେ।","puṇi, mōhara īśbara khrīṣṭa yīśuṅkaṭhārē tāhāṅkara gaurabamaẏa aiśvaryẏa anusārē tumbhamānaṅkara pratẏēka abhāba pūraṇa karibē.",null],[4,20,"ଆମ୍ଭମାନଙ୍କର ଈଶ୍ବର ଓ ପିତାଙ୍କ ପ୍ରତି ଯୁଗେ ଯୁଗେ ଗୌରବ ହେଉ। ଆମେନ୍‍।","āmbhamānaṅkara īśbara ō pitāṅka prati yugē yugē gauraba hēu. āmēn.",null],[4,21,"ଖ୍ରୀଷ୍ଟ ଯୀଶୁଙ୍କ ନାମରେ ପ୍ରତ୍ୟେକ ସାଧୁଙ୍କୁ ନମସ୍କାର ଜଣାଅ। ମୋହର ସଙ୍ଗୀ ଭ୍ରାତୃଗଣ ତୁମ୍ଭମାନଙ୍କୁ ନମସ୍କାର ଜଣାଉଅଛନ୍ତି।","khrīṣṭa yīśuṅka nāmarē pratẏēka sādhuṅku namaskāra jaṇāa. mōhara saṅgī bhrātr̥gaṇa tumbhamānaṅku namaskāra jaṇāuachanti.",null],[4,22,"ସାଧୁମାନେ ସମସ୍ତେ, ବିଶେଷରେ ଯେଉଁମାନେ କାଇସରଙ୍କ ପ୍ରାସାଦରେ ଅଛନ୍ତି, ସେମାନେ ତୁମ୍ଭମାନଙ୍କୁ ନମସ୍କାର ଜଣାଉଅଛନ୍ତି।","sādhumānē samastē, biśēṣarē yēum̐mānē kāisaraṅka prāsādarē achanti, sēmānē tumbhamānaṅku namaskāra jaṇāuachanti.",null],[4,23,"ପ୍ରଭୁ ଯୀଶୁ ଖ୍ରୀଷ୍ଟଙ୍କର ଅନୁଗ୍ରହ ତୁମ୍ଭମାନଙ୍କ ଆତ୍ମାର ସହବର୍ତ୍ତୀ ହେଉ।","prabhu yīśu khrīṣṭaṅkara anugraha tumbhamānaṅka ātmāra sahabarttī hēu.",null]],"tam2017":[[1,1,"இயேசுகிறிஸ்துவின் ஊழியக்காரர்களாகிய பவுலும், தீமோத்தேயும், பிலிப்பி பட்டணத்தில் கிறிஸ்து இயேசுவிற்குள்ளான பரிசுத்தவான்கள் அனைவருக்கும், கண்காணிகளுக்கும், உதவிக்காரர்களுக்கும் எழுதுகிறதாவது:","iyēcukiṟistuviṉ ūḻiyakkārarkaḷākiya pavulum, tīmōttēyum, pilippi paṭṭaṇattil kiṟistu iyēcuviṟkuḷḷāṉa paricuttavāṉkaḷ aṉaivarukkum, kaṇkāṇikaḷukkum, utavikkārarkaḷukkum eḻutukiṟatāvatu:",null],[1,2,"நம்முடைய பிதாவாகிய தேவனாலும் கர்த்தராகிய இயேசுகிறிஸ்துவினாலும் உங்களுக்குக் கிருபையும் சமாதானமும் உண்டாவதாக.","nammuṭaiya pitāvākiya tēvaṉālum karttarākiya iyēcukiṟistuviṉālum uṅkaḷukkuk kirupaiyum camātāṉamum uṇṭāvatāka.",null],[1,3,"நற்செய்தி உங்களுக்கு அறிவிக்கப்பட்ட நாள்முதல் இதுவரைக்கும் நீங்கள் எங்களோடு ஊழியத்தில் ஐக்கியப்பட்டிருப்பதால்,","naṟceyti uṅkaḷukku aṟivikkappaṭṭa nāḷmutal ituvaraikkum nīṅkaḷ eṅkaḷōṭu ūḻiyattil aikkiyappaṭṭiruppatāl,",null],[1,4,"நான் பண்ணுகிற ஒவ்வொரு விண்ணப்பத்திலும் உங்கள் அனைவருக்காகவும் எப்பொழுதும் சந்தோஷத்தோடு ஜெபம்பண்ணி,","nāṉ paṇṇukiṟa ovvoru viṇṇappattilum uṅkaḷ aṉaivarukkākavum eppoḻutum cantōṣattōṭu jepampaṇṇi,",null],[1,5,"உங்களில் நல்லசெயல்களைத் தொடங்கினவர் அதை இயேசுகிறிஸ்துவின் நாள்வரை நடத்திவருவார் என்று நம்பி,","uṅkaḷil nallaceyalkaḷait toṭaṅkiṉavar atai iyēcukiṟistuviṉ nāḷvarai naṭattivaruvār eṉṟu nampi,",null],[1,6,"நான் உங்களை நினைக்கும்போதெல்லாம் என் தேவனை ஸ்தோத்திரிக்கிறேன்.","nāṉ uṅkaḷai niṉaikkumpōtellām eṉ tēvaṉai stōttirikkiṟēṉ.",null],[1,7,"என் சிறைச்சாலையின் கட்டுகளிலும், நான் நற்செய்தியைப் போதித்து அதைத் உறுதிப்படுத்திவருகிறதிலும், நீங்கள் அனைவரும் எனக்கு அளிக்கப்பட்ட கிருபையில் பங்குள்ளவர்களானதால், உங்களை என் இருதயத்தில் வைத்துக்கொண்டிருக்கிறபடியினாலே, உங்கள் எல்லோரையும்குறித்து நான் இப்படி நினைக்கிறது எனக்குத் தகுதியாக இருக்கிறது.","eṉ ciṟaiccālaiyiṉ kaṭṭukaḷilum, nāṉ naṟceytiyaip pōtittu atait uṟutippaṭuttivarukiṟatilum, nīṅkaḷ aṉaivarum eṉakku aḷikkappaṭṭa kirupaiyil paṅkuḷḷavarkaḷāṉatāl, uṅkaḷai eṉ irutayattil vaittukkoṇṭirukkiṟapaṭiyiṉālē, uṅkaḷ ellōraiyumkuṟittu nāṉ ippaṭi niṉaikkiṟatu eṉakkut takutiyāka irukkiṟatu.",null],[1,8,"இயேசுகிறிஸ்துவின் உருக்கமான அன்பினாலே உங்களெல்லோரையும் காண எவ்வளவோ ஆவலாக இருக்கிறேன் என்பதற்கு தேவனே எனக்குச் சாட்சி.","iyēcukiṟistuviṉ urukkamāṉa aṉpiṉālē uṅkaḷellōraiyum kāṇa evvaḷavō āvalāka irukkiṟēṉ eṉpataṟku tēvaṉē eṉakkuc cāṭci.",null],[1,9,"மேலும், உத்தமமானவைகளை நீங்கள் ஒப்புக்கொள்ளத்தக்கதாக உங்களுடைய அன்பானது அறிவிலும் எல்லா உணர்விலும் இன்னும் அதிகமதிகமாகப் பெருகவும்,","mēlum, uttamamāṉavaikaḷai nīṅkaḷ oppukkoḷḷattakkatāka uṅkaḷuṭaiya aṉpāṉatu aṟivilum ellā uṇarvilum iṉṉum atikamatikamākap perukavum,",null],[1,10,"தேவனுக்கு மகிமையும் துதியும் உண்டாகும்படி இயேசுகிறிஸ்துவினால் வருகிற நீதியின் கனிகளால் நிறைந்தவர்களாகி,","tēvaṉukku makimaiyum tutiyum uṇṭākumpaṭi iyēcukiṟistuviṉāl varukiṟa nītiyiṉ kaṉikaḷāl niṟaintavarkaḷāki,",null],[1,11,"நீங்கள் கிறிஸ்துவின் நாளுக்கென்று நேர்மையானவர்களும், குற்றம் இல்லாதவர்களுமாக இருக்கவும் வேண்டுதல் செய்கிறேன்.","nīṅkaḷ kiṟistuviṉ nāḷukkeṉṟu nērmaiyāṉavarkaḷum, kuṟṟam illātavarkaḷumāka irukkavum vēṇṭutal ceykiṟēṉ.",null],[1,12,"சகோதரர்களே, எனக்கு சம்பவித்தவைகள் நற்செய்தி பரவுவதற்கு ஏதுவானது என்று நீங்கள் அறிய மனதாயிருக்கிறேன்.","cakōtararkaḷē, eṉakku campavittavaikaḷ naṟceyti paravuvataṟku ētuvāṉatu eṉṟu nīṅkaḷ aṟiya maṉatāyirukkiṟēṉ.",null],[1,13,"அரண்மனையில் உள்ளவர்களுக்கும் மற்ற எல்லோருக்கும் என் கட்டுகள் கிறிஸ்துவிற்குள்ளான கட்டுகள் என்று தெரிந்து,","araṇmaṉaiyil uḷḷavarkaḷukkum maṟṟa ellōrukkum eṉ kaṭṭukaḷ kiṟistuviṟkuḷḷāṉa kaṭṭukaḷ eṉṟu terintu,",null],[1,14,"சகோதரர்களில் அநேகர் என் கட்டுகளாலே கர்த்தருக்குள் தைரியம்கொண்டு பயம் இல்லாமல் திருவசனத்தைச் சொல்லும்படி அதிகமாகத் துணிந்திருக்கிறார்கள்.","cakōtararkaḷil anēkar eṉ kaṭṭukaḷālē karttarukkuḷ tairiyamkoṇṭu payam illāmal tiruvacaṉattaic collumpaṭi atikamākat tuṇintirukkiṟārkaḷ.",null],[1,15,"சிலர் பொறாமையினாலும் விரோதத்தினாலும், சிலர் நல்ல மனதினாலும் கிறிஸ்துவைப் பிரசங்கிக்கிறார்கள்.","cilar poṟāmaiyiṉālum virōtattiṉālum, cilar nalla maṉatiṉālum kiṟistuvaip piracaṅkikkiṟārkaḷ.",null],[1,16,"சிலர் என் கட்டுகளோடு உபத்திரவத்தையும் சேர்க்க நினைத்து, சுத்த மனதோடு கிறிஸ்துவை அறிவிக்காமல், விரோதத்தினாலே அறிவிக்கிறார்கள்.","cilar eṉ kaṭṭukaḷōṭu upattiravattaiyum cērkka niṉaittu, cutta maṉatōṭu kiṟistuvai aṟivikkāmal, virōtattiṉālē aṟivikkiṟārkaḷ.",null],[1,17,"நற்செய்திக்காக நான் உத்தரவுசொல்ல நியமிக்கப்பட்டவன் என்று அறிந்து, சிலர் அன்பினாலே அறிவிக்கிறார்கள்.","naṟceytikkāka nāṉ uttaravucolla niyamikkappaṭṭavaṉ eṉṟu aṟintu, cilar aṉpiṉālē aṟivikkiṟārkaḷ.",null],[1,18,"இதனால் என்ன? ஏமாற்றுவதினாலோ, உண்மையினாலோ, எப்படியாவது, கிறிஸ்து அறிவிக்கப்படுகிறார்; அதனால் சந்தோஷப்படுகிறேன், இனிமேலும் சந்தோஷப்படுவேன்.","itaṉāl eṉṉa? ēmāṟṟuvatiṉālō, uṇmaiyiṉālō, eppaṭiyāvatu, kiṟistu aṟivikkappaṭukiṟār; ataṉāl cantōṣappaṭukiṟēṉ, iṉimēlum cantōṣappaṭuvēṉ.",null],[1,19,"அது உங்களுடைய வேண்டுதலினாலும் இயேசுகிறிஸ்துவினுடைய ஆவியின் உதவியினாலும் எனக்கு இரட்சிப்பாக முடியும் என்று அறிவேன்.","atu uṅkaḷuṭaiya vēṇṭutaliṉālum iyēcukiṟistuviṉuṭaiya āviyiṉ utaviyiṉālum eṉakku iraṭcippāka muṭiyum eṉṟu aṟivēṉ.",null],[1,20,"நான் ஒன்றிலும் வெட்கப்பட்டுப்போகாமல், எப்பொழுதும்போல இப்பொழுதும், மிகுந்த தைரியத்தோடு ஜீவனாலாவது, மரணத்தினாலாவது, கிறிஸ்து என் சரீரத்தினாலே மகிமைப்படுவார் என்று எனக்கு உண்டாயிருக்கிற வாஞ்சைக்கும் நம்பிக்கைக்கும் தகுந்ததாக அப்படி முடியும்.","nāṉ oṉṟilum veṭkappaṭṭuppōkāmal, eppoḻutumpōla ippoḻutum, mikunta tairiyattōṭu jīvaṉālāvatu, maraṇattiṉālāvatu, kiṟistu eṉ carīrattiṉālē makimaippaṭuvār eṉṟu eṉakku uṇṭāyirukkiṟa vāñcaikkum nampikkaikkum takuntatāka appaṭi muṭiyum.",null],[1,21,"கிறிஸ்து எனக்கு ஜீவன், மரணம் எனக்கு ஆதாயம்.","kiṟistu eṉakku jīvaṉ, maraṇam eṉakku ātāyam.",null],[1,22,"ஆனாலும் சரீரத்தில் பிழைத்திருக்கிறதினாலே என் செய்கைக்குப் பலன் கிடைத்திருப்பதால், நான் தெரிந்துகொள்ளவேண்டியது என்னவென்று தெரியாது.","āṉālum carīrattil piḻaittirukkiṟatiṉālē eṉ ceykaikkup palaṉ kiṭaittiruppatāl, nāṉ terintukoḷḷavēṇṭiyatu eṉṉaveṉṟu teriyātu.",null],[1,23,"ஏனென்றால், இந்த இரண்டிற்கும் இடையே நான் நெருக்கப்படுகிறேன்; சரீரத்தைவிட்டுப் பிரிந்து, கிறிஸ்துவோடு இருக்க எனக்கு ஆசை உண்டு, அது அதிக நன்மையாக இருக்கும்;","ēṉeṉṟāl, inta iraṇṭiṟkum iṭaiyē nāṉ nerukkappaṭukiṟēṉ; carīrattaiviṭṭup pirintu, kiṟistuvōṭu irukka eṉakku ācai uṇṭu, atu atika naṉmaiyāka irukkum;",null],[1,24,"அப்படியிருந்தும், நான் சரீரத்தில் வாழ்ந்திருப்பது உங்களுக்கு அதிக அவசியம்.","appaṭiyiruntum, nāṉ carīrattil vāḻntiruppatu uṅkaḷukku atika avaciyam.",null],[1,25,"இந்த நிச்சயத்தைக்கொண்டிருந்து, நான் மீண்டும் உங்களிடம் வருகிறதினால் என்னைக்குறித்து உங்களுடைய மகிழ்ச்சி கிறிஸ்து இயேசுவிற்குள் பெருகுவதற்காக,","inta niccayattaikkoṇṭiruntu, nāṉ mīṇṭum uṅkaḷiṭam varukiṟatiṉāl eṉṉaikkuṟittu uṅkaḷuṭaiya makiḻcci kiṟistu iyēcuviṟkuḷ perukuvataṟkāka,",null],[1,26,"உங்களுடைய விசுவாசத்தின் வளர்ச்சிக்காகவும் சந்தோஷத்திற்காகவும் நான் பிழைத்து, உங்கள் அனைவரோடும் இருப்பேன் என்று அறிந்திருக்கிறேன்.","uṅkaḷuṭaiya vicuvācattiṉ vaḷarccikkākavum cantōṣattiṟkākavum nāṉ piḻaittu, uṅkaḷ aṉaivarōṭum iruppēṉ eṉṟu aṟintirukkiṟēṉ.",null],[1,27,"நான் வந்து உங்களைப் பார்த்தாலும், நான் வராமலிருந்தாலும், நீங்கள் ஒரே ஆவியிலே உறுதியாக நின்று, ஒரே ஆத்துமாவினாலே நற்செய்தியின் விசுவாசத்திற்காகப் போராடி, எதிர்க்கிறவர்களால் ஒன்றுக்கும் பயப்படாமல் இருக்கிறீர்கள் என்று உங்களைக்குறித்து நான் கேள்விப்படும்படி, எந்தவிதத்திலும் நீங்கள் கிறிஸ்துவின் நற்செய்திற்குத் தகுதியானவர்களாக நடந்துகொள்ளுங்கள்.","nāṉ vantu uṅkaḷaip pārttālum, nāṉ varāmaliruntālum, nīṅkaḷ orē āviyilē uṟutiyāka niṉṟu, orē āttumāviṉālē naṟceytiyiṉ vicuvācattiṟkākap pōrāṭi, etirkkiṟavarkaḷāl oṉṟukkum payappaṭāmal irukkiṟīrkaḷ eṉṟu uṅkaḷaikkuṟittu nāṉ kēḷvippaṭumpaṭi, entavitattilum nīṅkaḷ kiṟistuviṉ naṟceytiṟkut takutiyāṉavarkaḷāka naṭantukoḷḷuṅkaḷ.",null],[1,28,"நீங்கள் பயப்படாமலிருக்கிறது அவர்கள் கெட்டுப்போகிறதற்கும், நீங்கள் இரட்சிக்கப்படுகிறதற்கும் அடையாளமாக இருக்கிறது; இதுவும் தேவனுடைய செயலே.","nīṅkaḷ payappaṭāmalirukkiṟatu avarkaḷ keṭṭuppōkiṟataṟkum, nīṅkaḷ iraṭcikkappaṭukiṟataṟkum aṭaiyāḷamāka irukkiṟatu; ituvum tēvaṉuṭaiya ceyalē.",null],[1,29,"ஏனென்றால், கிறிஸ்துவை விசுவாசிக்கிறதற்குமட்டும் இல்லை, அவருக்காகப் பாடுகள்படுகிறதற்கும் உங்களுக்கு கொடுக்கப்பட்டிருக்கிறது.","ēṉeṉṟāl, kiṟistuvai vicuvācikkiṟataṟkumaṭṭum illai, avarukkākap pāṭukaḷpaṭukiṟataṟkum uṅkaḷukku koṭukkappaṭṭirukkiṟatu.",null],[1,30,"நீங்கள் என்னிடம் பார்த்ததும் எனக்கு உண்டென்று இப்பொழுது கேள்விப்படுகிறதுமான போராட்டமே உங்களுக்கும் உண்டு.","nīṅkaḷ eṉṉiṭam pārttatum eṉakku uṇṭeṉṟu ippoḻutu kēḷvippaṭukiṟatumāṉa pōrāṭṭamē uṅkaḷukkum uṇṭu.",null],[2,1,"ஆகவே, கிறிஸ்துவிற்குள் எந்தவொரு ஆறுதலும், அன்பினாலே எந்தவொரு தேறுதலும், ஆவியின் எந்தவொரு ஐக்கியமும், எந்தவொரு உருக்கமான பரிவும் இரக்கங்களும் உண்டானால்,","ākavē, kiṟistuviṟkuḷ entavoru āṟutalum, aṉpiṉālē entavoru tēṟutalum, āviyiṉ entavoru aikkiyamum, entavoru urukkamāṉa parivum irakkaṅkaḷum uṇṭāṉāl,",null],[2,2,"நீங்கள் ஒரே சிந்தையும் ஒரே அன்பும் உள்ளவர்களாக இருந்து, இசைந்த ஆத்துமாக்களாக ஒன்றையே சிந்தித்து, என் சந்தோஷத்தை நிறைவாக்குங்கள்.","nīṅkaḷ orē cintaiyum orē aṉpum uḷḷavarkaḷāka iruntu, icainta āttumākkaḷāka oṉṟaiyē cintittu, eṉ cantōṣattai niṟaivākkuṅkaḷ.",null],[2,3,"ஒன்றையும் சுயநலத்தினாலோ, வீண்பெருமையினாலோ செய்யாமல், மனத்தாழ்மையினாலே ஒருவரையொருவர் உங்களைவிட மேன்மையானவர்களாக நினைக்கவேண்டும்.","oṉṟaiyum cuyanalattiṉālō, vīṇperumaiyiṉālō ceyyāmal, maṉattāḻmaiyiṉālē oruvaraiyoruvar uṅkaḷaiviṭa mēṉmaiyāṉavarkaḷāka niṉaikkavēṇṭum.",null],[2,4,"அவனவன் தன்னுடைய காரியங்களை மட்டுமல்ல, மற்றவர்களுடைய காரியங்களிலும் உதவிசெய்யவேண்டும்.","avaṉavaṉ taṉṉuṭaiya kāriyaṅkaḷai maṭṭumalla, maṟṟavarkaḷuṭaiya kāriyaṅkaḷilum utaviceyyavēṇṭum.",null],[2,5,"கிறிஸ்து இயேசுவில் இருந்த சிந்தையே உங்களுக்கும் இருக்கவேண்டும்;","kiṟistu iyēcuvil irunta cintaiyē uṅkaḷukkum irukkavēṇṭum;",null],[2,6,"அவர் தேவனுடைய உருவமாக இருந்தும், தேவனுக்குச் சமமாக இருப்பதைக் கொள்ளையாடின பொருளாக நினைக்காமல்,","avar tēvaṉuṭaiya uruvamāka iruntum, tēvaṉukkuc camamāka iruppataik koḷḷaiyāṭiṉa poruḷāka niṉaikkāmal,",null],[2,7,"தம்மைத்தாமே வெறுமையாக்கி, அடிமையின் உருவமெடுத்து, மனிதனின் சாயல் ஆனார்.","tammaittāmē veṟumaiyākki, aṭimaiyiṉ uruvameṭuttu, maṉitaṉiṉ cāyal āṉār.",null],[2,8,"அவர் மனித உருவமாக வெளிப்பட்டு, மரணம்வரைக்கும், அதாவது சிலுவையின் மரணம்வரைக்கும் கீழ்ப்படிந்தவராகி, தம்மைத்தாமே தாழ்த்தினார்.","avar maṉita uruvamāka veḷippaṭṭu, maraṇamvaraikkum, atāvatu ciluvaiyiṉ maraṇamvaraikkum kīḻppaṭintavarāki, tammaittāmē tāḻttiṉār.",null],[2,9,"ஆகவே, தேவன் எல்லாவற்றிற்கும் மேலாக அவரை உயர்த்தி,","ākavē, tēvaṉ ellāvaṟṟiṟkum mēlāka avarai uyartti,",null],[2,10,"இயேசுவின் நாமத்தில் வானத்தில் உள்ளவைகளும், பூமியில் உள்ளவைகளும், பூமியின் கீழ் உள்ளவைகளுடைய முழங்கால்கள் எல்லாம் முடங்கும்படிக்கும்,","iyēcuviṉ nāmattil vāṉattil uḷḷavaikaḷum, pūmiyil uḷḷavaikaḷum, pūmiyiṉ kīḻ uḷḷavaikaḷuṭaiya muḻaṅkālkaḷ ellām muṭaṅkumpaṭikkum,",null],[2,11,"பிதாவாகிய தேவனுக்கு மகிமையாக இயேசுகிறிஸ்துவே கர்த்தர் என்று நாக்குகளெல்லாம் அறிக்கைபண்ணுவதற்கும், எல்லா நாமத்திற்கும் மேலான நாமத்தை அவருக்குத் தந்தருளினார்.","pitāvākiya tēvaṉukku makimaiyāka iyēcukiṟistuvē karttar eṉṟu nākkukaḷellām aṟikkaipaṇṇuvataṟkum, ellā nāmattiṟkum mēlāṉa nāmattai avarukkut tantaruḷiṉār.",null],[2,12,"ஆகவே, எனக்குப் பிரியமானவர்களே, நீங்கள் எப்பொழுதும் கீழ்ப்படிகிறபடியே, நான் உங்களுக்கு அருகில் இருக்கும்பொழுது மட்டுமில்லை, நான் தூரத்தில் இருக்கும்பொழுதும், அதிக பயத்தோடும் நடுக்கத்தோடும் உங்களுடைய இரட்சிப்பு நிறைவேறப் பிரயாசப்படுங்கள்.","ākavē, eṉakkup piriyamāṉavarkaḷē, nīṅkaḷ eppoḻutum kīḻppaṭikiṟapaṭiyē, nāṉ uṅkaḷukku arukil irukkumpoḻutu maṭṭumillai, nāṉ tūrattil irukkumpoḻutum, atika payattōṭum naṭukkattōṭum uṅkaḷuṭaiya iraṭcippu niṟaivēṟap pirayācappaṭuṅkaḷ.",null],[2,13,"ஏனென்றால், தேவனே தம்முடைய தயவுள்ள விருப்பத்தின்படி விருப்பத்தையும் செய்கையையும் உங்களில் உண்டாக்குகிறவராக இருக்கிறார்.","ēṉeṉṟāl, tēvaṉē tammuṭaiya tayavuḷḷa viruppattiṉpaṭi viruppattaiyum ceykaiyaiyum uṅkaḷil uṇṭākkukiṟavarāka irukkiṟār.",null],[2,14,"நான் வீணாக ஓடினதும் வீணாகப் பிரயாசப்பட்டதும் இல்லை என்கிற மகிழ்ச்சி கிறிஸ்துவின் நாளில் எனக்கு உண்டாயிருப்பதற்கு, ஜீவவசனத்தைப் பிடித்துக்கொண்டு, உலகத்திலே சுடர்களைப்போலப் பிரகாசிக்கிற நீங்கள்,","nāṉ vīṇāka ōṭiṉatum vīṇākap pirayācappaṭṭatum illai eṉkiṟa makiḻcci kiṟistuviṉ nāḷil eṉakku uṇṭāyiruppataṟku, jīvavacaṉattaip piṭittukkoṇṭu, ulakattilē cuṭarkaḷaippōlap pirakācikkiṟa nīṅkaḷ,",null],[2,15,"கோணலும் மாறுபாடுமான வம்சத்தின் நடுவிலே குற்றம் இல்லாதவர்களும் கபடு இல்லாதவர்களும், தேவனுடைய மாசற்ற பிள்ளைகளாக இருப்பதற்கு,","kōṇalum māṟupāṭumāṉa vamcattiṉ naṭuvilē kuṟṟam illātavarkaḷum kapaṭu illātavarkaḷum, tēvaṉuṭaiya mācaṟṟa piḷḷaikaḷāka iruppataṟku,",null],[2,16,"எல்லாவற்றையும் முறுமுறுப்பு இல்லாமலும் வாக்குவாதம் இல்லாமலும் செய்யுங்கள்.","ellāvaṟṟaiyum muṟumuṟuppu illāmalum vākkuvātam illāmalum ceyyuṅkaḷ.",null],[2,17,"மேலும், உங்களுடைய விசுவாசமாகிய பலியின்மேலும் ஊழியத்தின்மேலும் நான் பானபலியாக வார்க்கப்பட்டுப் போனாலும், நான் மகிழ்ந்து, உங்கள் அனைவரோடும் சேர்ந்து சந்தோஷப்படுவேன்.","mēlum, uṅkaḷuṭaiya vicuvācamākiya paliyiṉmēlum ūḻiyattiṉmēlum nāṉ pāṉapaliyāka vārkkappaṭṭup pōṉālum, nāṉ makiḻntu, uṅkaḷ aṉaivarōṭum cērntu cantōṣappaṭuvēṉ.",null],[2,18,"இதினால் நீங்களும் மகிழ்ந்து, என்னோடு சேர்ந்து சந்தோஷப்படுங்கள்.","itiṉāl nīṅkaḷum makiḻntu, eṉṉōṭu cērntu cantōṣappaṭuṅkaḷ.",null],[2,19,"அன்றியும், நானும் உங்களுடைய செய்திகளைத் தெரிந்து மன ஆறுதல் அடைவதற்குச் சீக்கிரமாகத் தீமோத்தேயுவை உங்களிடம் அனுப்பலாம் என்று கர்த்தராகிய இயேசுவிற்குள் நம்பியிருக்கிறேன்.","aṉṟiyum, nāṉum uṅkaḷuṭaiya ceytikaḷait terintu maṉa āṟutal aṭaivataṟkuc cīkkiramākat tīmōttēyuvai uṅkaḷiṭam aṉuppalām eṉṟu karttarākiya iyēcuviṟkuḷ nampiyirukkiṟēṉ.",null],[2,20,"ஆகவே, உங்களுடைய காரியங்களை உண்மையாகக் கவனிப்பதற்கு என்னைப்போல மனதுள்ளவன் அவனைத்தவிர வேறுயாரும் என்னிடம் இல்லை.","ākavē, uṅkaḷuṭaiya kāriyaṅkaḷai uṇmaiyākak kavaṉippataṟku eṉṉaippōla maṉatuḷḷavaṉ avaṉaittavira vēṟuyārum eṉṉiṭam illai.",null],[2,21,"மற்ற எல்லோரும் கிறிஸ்து இயேசுவிற்குரியவைகளைத் தேடாமல், தங்களுக்குரியவைகளையே தேடுகிறார்கள்.","maṟṟa ellōrum kiṟistu iyēcuviṟkuriyavaikaḷait tēṭāmal, taṅkaḷukkuriyavaikaḷaiyē tēṭukiṟārkaḷ.",null],[2,22,"தகப்பனுக்குப் பிள்ளை ஊழியம் செய்வதுபோல, அவன் என்னோடு சேர்ந்து நற்செய்திக்காக ஊழியம் செய்தான் என்று அவனுடைய உத்தமகுணத்தை அறிந்திருக்கிறீர்கள்.","takappaṉukkup piḷḷai ūḻiyam ceyvatupōla, avaṉ eṉṉōṭu cērntu naṟceytikkāka ūḻiyam ceytāṉ eṉṟu avaṉuṭaiya uttamakuṇattai aṟintirukkiṟīrkaḷ.",null],[2,23,"ஆகவே, என் காரியங்கள் எப்படி நடக்கும் என்று நான் அறிந்தவுடனே அவனை அனுப்பலாம் என்று நினைத்திருக்கிறேன்.","ākavē, eṉ kāriyaṅkaḷ eppaṭi naṭakkum eṉṟu nāṉ aṟintavuṭaṉē avaṉai aṉuppalām eṉṟu niṉaittirukkiṟēṉ.",null],[2,24,"அன்றியும் நானே சீக்கிரத்தில் வருவேன் என்று கர்த்தருக்குள் விசுவாசமாக இருக்கிறேன்.","aṉṟiyum nāṉē cīkkirattil varuvēṉ eṉṟu karttarukkuḷ vicuvācamāka irukkiṟēṉ.",null],[2,25,"மேலும், என் சகோதரனும், உடன்வேலைக்காரனும், கிறிஸ்துவின் படைவீரனும், உங்களுடைய தூதுவனாகவும், என்னுடைய குறைவில் உதவி செய்தவனுமான எப்பாப்பிரோதீத்துவை உங்களிடம் அனுப்பவேண்டும் என்று நினைத்தேன்.","mēlum, eṉ cakōtaraṉum, uṭaṉvēlaikkāraṉum, kiṟistuviṉ paṭaivīraṉum, uṅkaḷuṭaiya tūtuvaṉākavum, eṉṉuṭaiya kuṟaivil utavi ceytavaṉumāṉa eppāppirōtīttuvai uṅkaḷiṭam aṉuppavēṇṭum eṉṟu niṉaittēṉ.",null],[2,26,"அவன் உங்கள் எல்லோர்மேலும் வாஞ்சையுள்ளவனும், தான் வியாதிப்பட்டதை நீங்கள் கேள்விப்பட்டதினாலே அதிக மனச்சோர்வு அடைந்தவனாகவும் இருக்கிறான்.","avaṉ uṅkaḷ ellōrmēlum vāñcaiyuḷḷavaṉum, tāṉ viyātippaṭṭatai nīṅkaḷ kēḷvippaṭṭatiṉālē atika maṉaccōrvu aṭaintavaṉākavum irukkiṟāṉ.",null],[2,27,"அவன் வியாதிப்பட்டு மரணத்திற்கு அருகில் இருந்தது உண்மைதான். ஆனாலும், தேவன் அவனுக்கு இரங்கினார்; அவனுக்கு இரங்கினதுமட்டுமல்லாமல், துக்கத்தின்மேல் துக்கம் எனக்கு உண்டாகாதபடி, எனக்கும் இரங்கினார்.","avaṉ viyātippaṭṭu maraṇattiṟku arukil iruntatu uṇmaitāṉ. āṉālum, tēvaṉ avaṉukku iraṅkiṉār; avaṉukku iraṅkiṉatumaṭṭumallāmal, tukkattiṉmēl tukkam eṉakku uṇṭākātapaṭi, eṉakkum iraṅkiṉār.",null],[2,28,"ஆகவே, நீங்கள் அவனை மீண்டும் பார்த்து சந்தோஷப்படவும், என் துக்கம் குறையவும், அவனை சீக்கிரமாக அனுப்பினேன்.","ākavē, nīṅkaḷ avaṉai mīṇṭum pārttu cantōṣappaṭavum, eṉ tukkam kuṟaiyavum, avaṉai cīkkiramāka aṉuppiṉēṉ.",null],[2,29,"ஆனபடியால் நீங்கள் கர்த்தருக்குள் அதிகமான சந்தோஷத்தோடு அவனை ஏற்றுக்கொண்டு, இப்படிப்பட்டவர்களைக் கனம்பண்ணுங்கள்.","āṉapaṭiyāl nīṅkaḷ karttarukkuḷ atikamāṉa cantōṣattōṭu avaṉai ēṟṟukkoṇṭu, ippaṭippaṭṭavarkaḷaik kaṉampaṇṇuṅkaḷ.",null],[2,30,"ஏனென்றால், நீங்கள் எனக்குச் செய்யவேண்டிய ஊழியத்திலே உங்களுடைய குறைவை நிறைவாக்குவதற்கு, அவன் தன் உயிரையும் பெரிதாக நினைக்காமல், கிறிஸ்துவின் ஊழியத்திற்காக மரணத்திற்கு அருகில் இருந்தான்.","ēṉeṉṟāl, nīṅkaḷ eṉakkuc ceyyavēṇṭiya ūḻiyattilē uṅkaḷuṭaiya kuṟaivai niṟaivākkuvataṟku, avaṉ taṉ uyiraiyum peritāka niṉaikkāmal, kiṟistuviṉ ūḻiyattiṟkāka maraṇattiṟku arukil iruntāṉ.",null],[3,1,"மேலும், என் சகோதரர்களே, கர்த்தருக்குள் சந்தோஷப்படுங்கள். எழுதினவைகளையே மீண்டும் எழுதுவது எனக்கு வருத்தம் இல்லை, அது உங்களுக்கு நலமாக இருக்கும்.","mēlum, eṉ cakōtararkaḷē, karttarukkuḷ cantōṣappaṭuṅkaḷ. eḻutiṉavaikaḷaiyē mīṇṭum eḻutuvatu eṉakku varuttam illai, atu uṅkaḷukku nalamāka irukkum.",null],[3,2,"நாய்களுக்கு எச்சரிக்கையாக இருங்கள், பொல்லாத வேலையாட்களுக்கு எச்சரிக்கையாக இருங்கள். விருத்தசேதனக்காரர்களுக்கு எச்சரிக்கையாக இருங்கள்.","nāykaḷukku eccarikkaiyāka iruṅkaḷ, pollāta vēlaiyāṭkaḷukku eccarikkaiyāka iruṅkaḷ. viruttacētaṉakkārarkaḷukku eccarikkaiyāka iruṅkaḷ.",null],[3,3,"ஏனென்றால், சரீரத்தின்மேல் நம்பிக்கையாக இல்லாமல், ஆவியினாலே தேவனுக்கு ஆராதனைசெய்து, கிறிஸ்து இயேசுவிற்குள் மேன்மைபாராட்டுகிற நாமே விருத்தசேதனமுள்ளவர்கள்.","ēṉeṉṟāl, carīrattiṉmēl nampikkaiyāka illāmal, āviyiṉālē tēvaṉukku ārātaṉaiceytu, kiṟistu iyēcuviṟkuḷ mēṉmaipārāṭṭukiṟa nāmē viruttacētaṉamuḷḷavarkaḷ.",null],[3,4,"சரீரத்தின்மேல் நம்பிக்கை வைக்கவேண்டுமானால் நானும் வைக்கலாம்; வேறொருவன் சரீரத்தின்மேல் நம்பிக்கையாக இருக்க நினைத்தால் நான் அதைவிட அதிகமாக அப்படிச் செய்யலாம்.","carīrattiṉmēl nampikkai vaikkavēṇṭumāṉāl nāṉum vaikkalām; vēṟoruvaṉ carīrattiṉmēl nampikkaiyāka irukka niṉaittāl nāṉ ataiviṭa atikamāka appaṭic ceyyalām.",null],[3,5,"நான் எட்டாம்நாளில் விருத்தசேதனம்பண்ணப்பட்டவன், இஸ்ரவேல் வம்சத்தைச் சேர்ந்தவன், பென்யமீன் கோத்திரத்தைச் சேர்ந்தவன், எபிரெயரில் பிறந்த எபிரெயன், நியாயப்பிரமாணத்தின்படி பரிசேயன்;","nāṉ eṭṭāmnāḷil viruttacētaṉampaṇṇappaṭṭavaṉ, isravēl vamcattaic cērntavaṉ, peṉyamīṉ kōttirattaic cērntavaṉ, epireyaril piṟanta epireyaṉ, niyāyappiramāṇattiṉpaṭi paricēyaṉ;",null],[3,6,"பக்திவைராக்கியத்தின்படி சபையைத் துன்பப்படுத்தினவன், நியாயப்பிரமாணத்தின் நீதியின்படி குற்றஞ்சாட்டப்படாதவன்.","paktivairākkiyattiṉpaṭi capaiyait tuṉpappaṭuttiṉavaṉ, niyāyappiramāṇattiṉ nītiyiṉpaṭi kuṟṟañcāṭṭappaṭātavaṉ.",null],[3,7,"ஆனாலும், எனக்கு இலாபமாக இருந்தவைகள் எவைகளோ, அவைகளைக் கிறிஸ்துவுக்காக நஷ்டம் என்று நினைத்தேன்.","āṉālum, eṉakku ilāpamāka iruntavaikaḷ evaikaḷō, avaikaḷaik kiṟistuvukkāka naṣṭam eṉṟu niṉaittēṉ.",null],[3,8,"அதுமட்டும் இல்லை, என் கர்த்தராகிய கிறிஸ்து இயேசுவை அறிகிற அறிவின் மேன்மைக்காக எல்லாவற்றையும் நஷ்டம் என்று நினைத்துக்கொண்டிருக்கிறேன்.","atumaṭṭum illai, eṉ karttarākiya kiṟistu iyēcuvai aṟikiṟa aṟiviṉ mēṉmaikkāka ellāvaṟṟaiyum naṣṭam eṉṟu niṉaittukkoṇṭirukkiṟēṉ.",null],[3,9,"நான் கிறிஸ்துவை ஆதாயப்படுத்திக்கொள்வதற்காக, நியாயப்பிரமாணத்தினால் வருகிற சுயநீதியை உடையவனாக இல்லாமல், கிறிஸ்துவின்மேல் உள்ள விசுவாசத்தினால் வருகிறதும், விசுவாசம் மூலமாக தேவனால் உண்டாயிருக்கிறதுமான நீதியை உடையவனாக இருந்து, கிறிஸ்துவிற்குள் இருக்கிறவன் என்று தெரியும்படிக்கும்,","nāṉ kiṟistuvai ātāyappaṭuttikkoḷvataṟkāka, niyāyappiramāṇattiṉāl varukiṟa cuyanītiyai uṭaiyavaṉāka illāmal, kiṟistuviṉmēl uḷḷa vicuvācattiṉāl varukiṟatum, vicuvācam mūlamāka tēvaṉāl uṇṭāyirukkiṟatumāṉa nītiyai uṭaiyavaṉāka iruntu, kiṟistuviṟkuḷ irukkiṟavaṉ eṉṟu teriyumpaṭikkum,",null],[3,10,"இப்படி நான் அவரையும் அவருடைய உயிர்த்தெழுதலின் வல்லமையையும், அவருடைய பாடுகளின் ஐக்கியத்தையும் தெரிந்துகொள்வதற்கும், அவருடைய மரணத்திற்கு இணையான மரணத்திற்குள்ளாகி, எப்படியாவது நான் மரித்தோரிலிருந்து உயிரோடு எழுந்திருப்பதற்குத் தகுதியாவதற்கும்,","ippaṭi nāṉ avaraiyum avaruṭaiya uyirtteḻutaliṉ vallamaiyaiyum, avaruṭaiya pāṭukaḷiṉ aikkiyattaiyum terintukoḷvataṟkum, avaruṭaiya maraṇattiṟku iṇaiyāṉa maraṇattiṟkuḷḷāki, eppaṭiyāvatu nāṉ marittōriliruntu uyirōṭu eḻuntiruppataṟkut takutiyāvataṟkum,",null],[3,11,"அவருக்காக எல்லாவற்றையும் நஷ்டமென்றும் குப்பையென்றும் நினைக்கிறேன்.","avarukkāka ellāvaṟṟaiyum naṣṭameṉṟum kuppaiyeṉṟum niṉaikkiṟēṉ.",null],[3,12,"நான் பெற்றுக்கொண்டேன் அல்லது முழுவதும் தேறினவனானேன் என்று நினைக்காமல், கிறிஸ்து இயேசுவினால் நான் எதற்காகப் பிடிக்கப்பட்டேனோ அதை நான் பிடித்துக்கொள்வதற்காக ஆசையாகத் தொடருகிறேன்.","nāṉ peṟṟukkoṇṭēṉ allatu muḻuvatum tēṟiṉavaṉāṉēṉ eṉṟu niṉaikkāmal, kiṟistu iyēcuviṉāl nāṉ etaṟkākap piṭikkappaṭṭēṉō atai nāṉ piṭittukkoḷvataṟkāka ācaiyākat toṭarukiṟēṉ.",null],[3,13,"சகோதரர்களே, அதைப் பிடித்துக்கொண்டேன் என்று நான் நினைக்கிறதில்லை; ஒன்று செய்கிறேன், கடந்தவைகளை மறந்து, வருகிறவைகளைத் தேடி,","cakōtararkaḷē, ataip piṭittukkoṇṭēṉ eṉṟu nāṉ niṉaikkiṟatillai; oṉṟu ceykiṟēṉ, kaṭantavaikaḷai maṟantu, varukiṟavaikaḷait tēṭi,",null],[3,14,"கிறிஸ்து இயேசுவிற்குள் தேவன் அழைத்த பரம அழைப்பின் பந்தயப்பொருளுக்காக இலக்கை நோக்கித் தொடருகிறேன்.","kiṟistu iyēcuviṟkuḷ tēvaṉ aḻaitta parama aḻaippiṉ pantayapporuḷukkāka ilakkai nōkkit toṭarukiṟēṉ.",null],[3,15,"ஆகவே, நம்மில் தேறினவர்கள் எல்லோரும் இந்தச் சிந்தையாகவே இருக்கவேண்டும்; எந்தக் காரியத்திலாவது நீங்கள் வேறு சிந்தையாக இருந்தால், அதையும் தேவன் உங்களுக்கு வெளிப்படுத்துவார்.","ākavē, nammil tēṟiṉavarkaḷ ellōrum intac cintaiyākavē irukkavēṇṭum; entak kāriyattilāvatu nīṅkaḷ vēṟu cintaiyāka iruntāl, ataiyum tēvaṉ uṅkaḷukku veḷippaṭuttuvār.",null],[3,16,"ஆனாலும் நாம் எதுவரைக்கும் தேறியிருக்கிறோமோ, அதுமுதல் ஒரே ஒழுங்காக நடந்துகொண்டு, ஒரே சிந்தையாக இருப்போமாக.","āṉālum nām etuvaraikkum tēṟiyirukkiṟōmō, atumutal orē oḻuṅkāka naṭantukoṇṭu, orē cintaiyāka iruppōmāka.",null],[3,17,"சகோதரர்களே, நீங்கள் என்னோடு பின்பற்றுகிறவர்களாகி, நாங்கள் உங்களுக்கு வழிகாட்டுகிறபடி நடக்கிறவர்களை மாதிரியாக நோக்கிப் பாருங்கள்.","cakōtararkaḷē, nīṅkaḷ eṉṉōṭu piṉpaṟṟukiṟavarkaḷāki, nāṅkaḷ uṅkaḷukku vaḻikāṭṭukiṟapaṭi naṭakkiṟavarkaḷai mātiriyāka nōkkip pāruṅkaḷ.",null],[3,18,"ஏனென்றால், அநேகர் வேறுவிதமாக நடக்கிறார்கள்; அவர்கள் கிறிஸ்துவின் சிலுவைக்குப் பகைவர்களென்று உங்களுக்கு அநேகமுறைச் சொன்னேன், இப்பொழுது கண்ணீரோடும் சொல்லுகிறேன்.","ēṉeṉṟāl, anēkar vēṟuvitamāka naṭakkiṟārkaḷ; avarkaḷ kiṟistuviṉ ciluvaikkup pakaivarkaḷeṉṟu uṅkaḷukku anēkamuṟaic coṉṉēṉ, ippoḻutu kaṇṇīrōṭum collukiṟēṉ.",null],[3,19,"அவர்களுடைய முடிவு அழிவு, அவர்களுடைய தேவன் வயிறு, அவர்களுடைய மகிமை அவர்களுடைய வெட்கமே, அவர்கள் பூமிக்குரியவைகளைச் சிந்திக்கிறார்கள்.","avarkaḷuṭaiya muṭivu aḻivu, avarkaḷuṭaiya tēvaṉ vayiṟu, avarkaḷuṭaiya makimai avarkaḷuṭaiya veṭkamē, avarkaḷ pūmikkuriyavaikaḷaic cintikkiṟārkaḷ.",null],[3,20,"நம்முடைய குடியிருப்போ பரலோகத்தில் இருக்கிறது, அங்கேயிருந்து கர்த்தராகிய இயேசுகிறிஸ்து என்னும் இரட்சகர் வருவதற்காக எதிர்பார்த்துக்கொண்டிருக்கிறோம்.","nammuṭaiya kuṭiyiruppō paralōkattil irukkiṟatu, aṅkēyiruntu karttarākiya iyēcukiṟistu eṉṉum iraṭcakar varuvataṟkāka etirpārttukkoṇṭirukkiṟōm.",null],[3,21,"அவர் எல்லாவற்றையும் தமக்குக் கீழ்ப்படுத்திக்கொள்வதற்கு தம்முடைய வல்லமையான செயலின்படி, நம்முடைய அற்பமான சரீரத்தை அவருடைய மகிமையான சரீரத்திற்கு ஒப்பாக மறுரூபப்படுத்துவார்.","avar ellāvaṟṟaiyum tamakkuk kīḻppaṭuttikkoḷvataṟku tammuṭaiya vallamaiyāṉa ceyaliṉpaṭi, nammuṭaiya aṟpamāṉa carīrattai avaruṭaiya makimaiyāṉa carīrattiṟku oppāka maṟurūpappaṭuttuvār.",null],[4,1,"ஆகவே, எனக்குப் பிரியமும் வாஞ்சையுமான சகோதரர்களே, எனக்குச் சந்தோஷமும் கிரீடமுமானவர்களே, பிரியமானவர்களே, இப்படியே கர்த்தருக்குள் நிலைத்து நில்லுங்கள்.","ākavē, eṉakkup piriyamum vāñcaiyumāṉa cakōtararkaḷē, eṉakkuc cantōṣamum kirīṭamumāṉavarkaḷē, piriyamāṉavarkaḷē, ippaṭiyē karttarukkuḷ nilaittu nilluṅkaḷ.",null],[4,2,"கர்த்தருக்குள் ஒரே சிந்தையாக இருக்க எயோதியாளுக்கும் சிந்திகேயாளுக்கும் புத்திசொல்லுகிறேன்.","karttarukkuḷ orē cintaiyāka irukka eyōtiyāḷukkum cintikēyāḷukkum putticollukiṟēṉ.",null],[4,3,"அன்றியும், என் உத்தம கூட்டாளியே, அவர்களுக்கு உதவியாக இருக்கும்படி உன்னையும் வேண்டிக்கொள்ளுகிறேன்; அவர்கள் கிலேமெந்தோடும் மற்ற என் உடன்வேலையாட்களோடும் நற்செய்தியை அறிவிப்பதில் என்னோடு அதிகமாக உழைத்தார்கள், அவர்களுடைய பெயர்கள் ஜீவபுத்தகத்தில் இருக்கிறது.","aṉṟiyum, eṉ uttama kūṭṭāḷiyē, avarkaḷukku utaviyāka irukkumpaṭi uṉṉaiyum vēṇṭikkoḷḷukiṟēṉ; avarkaḷ kilēmentōṭum maṟṟa eṉ uṭaṉvēlaiyāṭkaḷōṭum naṟceytiyai aṟivippatil eṉṉōṭu atikamāka uḻaittārkaḷ, avarkaḷuṭaiya peyarkaḷ jīvaputtakattil irukkiṟatu.",null],[4,4,"கர்த்தருக்குள் எப்பொழுதும் சந்தோஷமாக இருங்கள்; சந்தோஷமாக இருங்கள் என்று மீண்டும் சொல்லுகிறேன்.","karttarukkuḷ eppoḻutum cantōṣamāka iruṅkaḷ; cantōṣamāka iruṅkaḷ eṉṟu mīṇṭum collukiṟēṉ.",null],[4,5,"உங்களுடைய சாந்தகுணம் எல்லா மனிதர்களுக்கும் தெரிந்திருப்பதாக. கர்த்தர் அருகில் இருக்கிறார்.","uṅkaḷuṭaiya cāntakuṇam ellā maṉitarkaḷukkum terintiruppatāka. karttar arukil irukkiṟār.",null],[4,6,"நீங்கள் எதைக்குறித்தும் கவலைப்படாமல், எல்லாவற்றையும்குறித்து உங்களுடைய விண்ணப்பங்களை ஸ்தோத்திரத்துடன் ஜெபத்தினாலும் வேண்டுதலினாலும் தேவனுக்குத் தெரியப்படுத்துங்கள்.","nīṅkaḷ etaikkuṟittum kavalaippaṭāmal, ellāvaṟṟaiyumkuṟittu uṅkaḷuṭaiya viṇṇappaṅkaḷai stōttirattuṭaṉ jepattiṉālum vēṇṭutaliṉālum tēvaṉukkut teriyappaṭuttuṅkaḷ.",null],[4,7,"அப்பொழுது, எல்லாப் புத்திக்கும் மேலான தேவசமாதானம் உங்களுடைய இருதயங்களையும் உங்களுடைய சிந்தைகளையும் கிறிஸ்து இயேசுவிற்குள்ளாகக் காத்துக்கொள்ளும்.","appoḻutu, ellāp puttikkum mēlāṉa tēvacamātāṉam uṅkaḷuṭaiya irutayaṅkaḷaiyum uṅkaḷuṭaiya cintaikaḷaiyum kiṟistu iyēcuviṟkuḷḷākak kāttukkoḷḷum.",null],[4,8,"கடைசியாக, சகோதரர்களே, உண்மையுள்ளவைகள் எவைகளோ, ஒழுக்கமுள்ளவைகள் எவைகளோ, நீதியுள்ளவைகள் எவைகளோ, கற்புள்ளவைகள் எவைகளோ, அன்புள்ளவைகள் எவைகளோ, நற்பெயர் உள்ளவைகள் எவைகளோ, புண்ணியம் எதுவோ, புகழ் எதுவோ அவைகளையே சிந்தித்துக்கொண்டிருங்கள்.","kaṭaiciyāka, cakōtararkaḷē, uṇmaiyuḷḷavaikaḷ evaikaḷō, oḻukkamuḷḷavaikaḷ evaikaḷō, nītiyuḷḷavaikaḷ evaikaḷō, kaṟpuḷḷavaikaḷ evaikaḷō, aṉpuḷḷavaikaḷ evaikaḷō, naṟpeyar uḷḷavaikaḷ evaikaḷō, puṇṇiyam etuvō, pukaḻ etuvō avaikaḷaiyē cintittukkoṇṭiruṅkaḷ.",null],[4,9,"நீங்கள் என்னிடம் கற்றுக்கொண்டவைகளும், பெற்றுக்கொண்டவைகளும், கேட்டவைகளும், பார்த்தவைகளும் எவைகளோ, அவைகளையே செய்யுங்கள்; அப்பொழுது சமாதானத்தின் தேவன் உங்களோடு இருப்பார்.","nīṅkaḷ eṉṉiṭam kaṟṟukkoṇṭavaikaḷum, peṟṟukkoṇṭavaikaḷum, kēṭṭavaikaḷum, pārttavaikaḷum evaikaḷō, avaikaḷaiyē ceyyuṅkaḷ; appoḻutu camātāṉattiṉ tēvaṉ uṅkaḷōṭu iruppār.",null],[4,10,"என்னை விசாரிப்பதற்கு நீங்கள் இப்பொழுது மீண்டும் அக்கறை கொண்டதினாலே கர்த்தருக்குள் மிகவும் சந்தோஷப்பட்டேன்; முன்னமே இப்படிச் செய்ய நினைத்தீர்கள், ஆனால் உதவிசெய்ய உங்களுக்கு வாய்ப்பு கிடைக்கவில்லை.","eṉṉai vicārippataṟku nīṅkaḷ ippoḻutu mīṇṭum akkaṟai koṇṭatiṉālē karttarukkuḷ mikavum cantōṣappaṭṭēṉ; muṉṉamē ippaṭic ceyya niṉaittīrkaḷ, āṉāl utaviceyya uṅkaḷukku vāyppu kiṭaikkavillai.",null],[4,11,"என் குறைகளினால் நான் இப்படிச் சொல்லவில்லை; ஏனென்றால், நான் எந்த நிலைமையில் இருந்தாலும் மனதிருப்தியாக இருக்கக் கற்றுக்கொண்டேன்.","eṉ kuṟaikaḷiṉāl nāṉ ippaṭic collavillai; ēṉeṉṟāl, nāṉ enta nilaimaiyil iruntālum maṉatiruptiyāka irukkak kaṟṟukkoṇṭēṉ.",null],[4,12,"தாழ்ந்திருக்கவும் எனக்குத் தெரியும், வாழ்ந்திருக்கவும் எனக்குத் தெரியும்; எந்த இடத்திலும் எல்லாவற்றிலும் திருப்தியாக இருக்கவும், பட்டினியாக இருக்கவும், பரிபூரணமடையவும், குறைவுபடவும் கற்றுக்கொண்டேன்.","tāḻntirukkavum eṉakkut teriyum, vāḻntirukkavum eṉakkut teriyum; enta iṭattilum ellāvaṟṟilum tiruptiyāka irukkavum, paṭṭiṉiyāka irukkavum, paripūraṇamaṭaiyavum, kuṟaivupaṭavum kaṟṟukkoṇṭēṉ.",null],[4,13,"என்னைப் பெலப்படுத்துகிற கிறிஸ்துவினாலே எல்லாவற்றையும் செய்ய எனக்குப் பெலன் உண்டு.","eṉṉaip pelappaṭuttukiṟa kiṟistuviṉālē ellāvaṟṟaiyum ceyya eṉakkup pelaṉ uṇṭu.",null],[4,14,"ஆனாலும் நீங்கள் என் உபத்திரவத்தில் என்னோடு பங்குகொண்டது நலமாக இருக்கிறது.","āṉālum nīṅkaḷ eṉ upattiravattil eṉṉōṭu paṅkukoṇṭatu nalamāka irukkiṟatu.",null],[4,15,"மேலும், பிலிப்பியரே, நற்செய்தி ஊழியத்தின் ஆரம்பத்திலே நான் மக்கெதோனியாவிலிருந்து புறப்பட்டபோது, உங்களைத்தவிர வேறு எந்த சபையும் எனக்குப் பணம் கொடுத்து உதவிசெய்யவில்லை என்று உங்களுக்குத் தெரியும்.","mēlum, pilippiyarē, naṟceyti ūḻiyattiṉ ārampattilē nāṉ makketōṉiyāviliruntu puṟappaṭṭapōtu, uṅkaḷaittavira vēṟu enta capaiyum eṉakkup paṇam koṭuttu utaviceyyavillai eṉṟu uṅkaḷukkut teriyum.",null],[4,16,"நான் தெசலோனிக்கேயில் இருந்தபோதும், என் குறைவுகளில் உதவிசெய்ய நீங்கள் பலமுறை பணம் அனுப்பி உதவி செய்தீர்கள்.","nāṉ tecalōṉikkēyil iruntapōtum, eṉ kuṟaivukaḷil utaviceyya nīṅkaḷ palamuṟai paṇam aṉuppi utavi ceytīrkaḷ.",null],[4,17,"உங்களுடைய உதவிகளை நான் தேடாமல், உங்களுடைய உதவிகளால் உங்களுக்கு வரும் பலன் பெருகுவதையே பார்க்க விரும்புகிறேன்.","uṅkaḷuṭaiya utavikaḷai nāṉ tēṭāmal, uṅkaḷuṭaiya utavikaḷāl uṅkaḷukku varum palaṉ perukuvataiyē pārkka virumpukiṟēṉ.",null],[4,18,"எல்லாம் எனக்குக் கிடைத்தது, பரிபூரணமும் உண்டாயிருக்கிறது; உங்களால் அனுப்பப்பட்டவைகளை தேவனுக்குச் சுகந்த வாசனையாகவும், பிரியமான பலியாகவும் எப்பாப்பிரோதீத்துவின் கைகளினால் பெற்றுக்கொண்டதினால் நான் திருப்தியடைந்திருக்கிறேன்.","ellām eṉakkuk kiṭaittatu, paripūraṇamum uṇṭāyirukkiṟatu; uṅkaḷāl aṉuppappaṭṭavaikaḷai tēvaṉukkuc cukanta vācaṉaiyākavum, piriyamāṉa paliyākavum eppāppirōtīttuviṉ kaikaḷiṉāl peṟṟukkoṇṭatiṉāl nāṉ tiruptiyaṭaintirukkiṟēṉ.",null],[4,19,"என் தேவன் தம்முடைய ஐசுவரியத்தின்படி உங்களுடைய குறைகளையெல்லாம் கிறிஸ்து இயேசுவிற்குள் மகிமையிலே நிறைவாக்குவார்.","eṉ tēvaṉ tammuṭaiya aicuvariyattiṉpaṭi uṅkaḷuṭaiya kuṟaikaḷaiyellām kiṟistu iyēcuviṟkuḷ makimaiyilē niṟaivākkuvār.",null],[4,20,"நம்முடைய பிதாவாகிய தேவனுக்கு என்றென்றைக்கும் மகிமை உண்டாவதாக. ஆமென்.","nammuṭaiya pitāvākiya tēvaṉukku eṉṟeṉṟaikkum makimai uṇṭāvatāka. āmeṉ.",null],[4,21,"கிறிஸ்து இயேசுவிற்குள்ளான பரிசுத்தவான்கள் எல்லோருக்கும் வாழ்த்துதல் சொல்லுங்கள். என்னோடு இருக்கிற சகோதரர்கள் உங்களுக்கு வாழ்த்துதல் சொல்லுகிறார்கள்.","kiṟistu iyēcuviṟkuḷḷāṉa paricuttavāṉkaḷ ellōrukkum vāḻttutal colluṅkaḷ. eṉṉōṭu irukkiṟa cakōtararkaḷ uṅkaḷukku vāḻttutal collukiṟārkaḷ.",null],[4,22,"பரிசுத்தவான்கள் அனைவரும், விசேஷமாக இராயனுடைய அரண்மனையில் உள்ளவர்களும் உங்களுக்கு வாழ்த்துதல் சொல்லுகிறார்கள்.","paricuttavāṉkaḷ aṉaivarum, vicēṣamāka irāyaṉuṭaiya araṇmaṉaiyil uḷḷavarkaḷum uṅkaḷukku vāḻttutal collukiṟārkaḷ.",null],[4,23,"நமது கர்த்தராகிய இயேசுகிறிஸ்துவினுடைய கிருபை உங்கள் அனைவரோடும் இருப்பதாக. ஆமென்.","namatu karttarākiya iyēcukiṟistuviṉuṭaiya kirupai uṅkaḷ aṉaivarōṭum iruppatāka. āmeṉ.",null]],"tel2017":[[1,1,"ఫిలిప్పీ పట్టణంలో క్రీస్తు యేసుకు చెందిన పరిశుద్ధులందరికీ సంఘ నాయకులకూ పరిచారకులకూ క్రీస్తు యేసు దాసులైన పౌలు, తిమోతి రాస్తున్న సంగతులు.","philippī paṭṭaṇaṁlō krīstu yēsuku ceṁdina pariśuddhulaṁdarikī saṁgha nāyakulakū paricārakulakū krīstu yēsu dāsulaina paulu, timōti rāstunna saṁgatulu.",null],[1,2,"మన తండ్రి దేవుని నుండీ ప్రభువైన యేసు క్రీస్తు నుండీ మీకు కృపా, శాంతీ కలుగు గాక.","mana taṁḍri dēvuni nuṁḍī prabhuvaina yēsu krīstu nuṁḍī mīku kr̥pā, śāṁtī kalugu gāka.",null],[1,3,"నేను మిమ్మల్ని ఎప్పుడు గుర్తుకు తెచ్చుకున్నా నా దేవునికి వందనాలు చెబుతాను.","nēnu mimmalni eppuḍu gurtuku teccukunnā nā dēvuniki vaṁdanālu cebutānu.",null],[1,4,"మీ కోసం నేను ప్రార్థించే ప్రతిసారీ అది ఆనందభరితమైన ప్రార్థనే.","mī kōsaṁ nēnu prārthiṁcē pratisārī adi ānaṁdabharitamaina prārthanē.",null],[1,5,"సువార్త విషయంలో మొదటి రోజు నుంచి ఇప్పటి వరకూ మీ సహవాసానికి వందనాలు.","suvārta viṣayaṁlō modaṭi rōju nuṁci ippaṭi varakū mī sahavāsāniki vaṁdanālu.",null],[1,6,"మీలో ఈ మంచి పని మొదలు పెట్టినవాడు యేసు క్రీస్తు తిరిగి వచ్చే రోజు వరకూ ఆ పని కొనసాగించి పూర్తి చేస్తాడు. ఇది నా గట్టి నమ్మకం.","mīlō ī maṁci pani modalu peṭṭinavāḍu yēsu krīstu tirigi vaccē rōju varakū ā pani konasāgiṁci pūrti cēstāḍu. idi nā gaṭṭi nammakaṁ.",null],[1,7,"మిమ్మల్ని గురించి నేనిలా భావించడం సబబే. ఎందుకంటే మీరు నా హృదయంలో ఉన్నారు. నేను ఖైదులో ఉన్నప్పుడూ, నేను సువార్త పక్షంగా వాదిస్తూ నిరూపిస్తున్నపుడు మీరంతా ఈ కృపలో నాతో పాలివారుగా ఉన్నారు.","mimmalni guriṁci nēnilā bhāviṁcaḍaṁ sababē. eṁdukaṁṭē mīru nā hr̥dayaṁlō unnāru. nēnu khaidulō unnappuḍū, nēnu suvārta pakṣaṁgā vādistū nirūpistunnapuḍu mīraṁtā ī kr̥palō nātō pālivārugā unnāru.",null],[1,8,"క్రీస్తు యేసు ప్రేమ లోతుల్లో నుంచి, మీ కోసం నేనెంత తపిస్తున్నానో దేవుడే నాకు సాక్షి.","krīstu yēsu prēma lōtullō nuṁci, mī kōsaṁ nēneṁta tapistunnānō dēvuḍē nāku sākṣi.",null],[1,9,"మీ ప్రేమ జ్ఞానంతో, సంపూర్ణ వివేచనతో అంతకంతకూ వృద్ధి చెందుతూ ఉండాలని నేను ప్రార్థిస్తున్నాను.","mī prēma jñānaṁtō, saṁpūrṇa vivēcanatō aṁtakaṁtakū vr̥ddhi ceṁdutū uṁḍālani nēnu prārthistunnānu.",null],[1,10,"దేవునికి మహిమ, స్తుతి కలిగేలా మీరు శ్రేష్ఠమైన విషయాలను పరీక్షించి తెలుసుకుని, యేసు క్రీస్తు ద్వారా కలిగే నీతిఫలాలతో నిండి, క్రీస్తు వచ్చే రోజు వరకూ యథార్థంగా నిర్దోషంగా ఉండాలన్నదే నా ప్రార్థన","dēvuniki mahima, stuti kaligēlā mīru śrēṣṭhamaina viṣayālanu parīkṣiṁci telusukuni, yēsu krīstu dvārā kaligē nītiphalālatō niṁḍi, krīstu vaccē rōju varakū yathārthaṁgā nirdōṣaṁgā uṁḍālannadē nā prārthana",null],[1,11,"అంతేకాక దేవునికి మహిమ, స్తుతి కలిగేలా, మీరు యేసు క్రీస్తు ద్వారా కలిగే నీతి ఫలాలతో నిండి ఉండాలి.","aṁtēkāka dēvuniki mahima, stuti kaligēlā, mīru yēsu krīstu dvārā kaligē nīti phalālatō niṁḍi uṁḍāli.",null],[1,12,"సోదరులారా, నాకు సంభవించినవి సువార్త మరి ఎక్కువగా వ్యాపించడానికే అని మీరు తెలుసుకోవాలని ఇప్పుడు కోరుతున్నాను.","sōdarulārā, nāku saṁbhaviṁcinavi suvārta mari ekkuvagā vyāpiṁcaḍānikē ani mīru telusukōvālani ippuḍu kōrutunnānu.",null],[1,13,"ఎలాగంటే, నా సంకెళ్ళు క్రీస్తు కోసమే కలిగాయని రాజ భవనం కావలి వారికీ తక్కిన వారందరికీ తెలిసిపోయింది.","elāgaṁṭē, nā saṁkeḷḷu krīstu kōsamē kaligāyani rāja bhavanaṁ kāvali vārikī takkina vāraṁdarikī telisipōyiṁdi.",null],[1,14,"అంతేకాక, ప్రభువులోని సోదరుల్లో ఎక్కువమంది నా బంధకాలను బట్టి స్థిర విశ్వాసం కలిగి, నిర్భయంగా దేవుని వాక్కు ప్రకటించడానికి ఎక్కువ ధైర్యం తెచ్చుకున్నారు.","aṁtēkāka, prabhuvulōni sōdarullō ekkuvamaṁdi nā baṁdhakālanu baṭṭi sthira viśvāsaṁ kaligi, nirbhayaṁgā dēvuni vākku prakaṭiṁcaḍāniki ekkuva dhairyaṁ teccukunnāru.",null],[1,15,"కొంతమంది అసూయతో కలహబుద్ధితో, మరి కొంతమంది మంచి ఉద్దేశంతో క్రీస్తును ప్రకటిస్తున్నారు.","koṁtamaṁdi asūyatō kalahabuddhitō, mari koṁtamaṁdi maṁci uddēśaṁtō krīstunu prakaṭistunnāru.",null],[1,16,"ప్రేమతో క్రీస్తును ప్రకటించేవారికి నేను సువార్త పక్షాన వాదించడానికి నియామకం పొందానని తెలుసు.","prēmatō krīstunu prakaṭiṁcēvāriki nēnu suvārta pakṣāna vādiṁcaḍāniki niyāmakaṁ poṁdānani telusu.",null],[1,17,"అయితే మిగతా వారు బంధకాల్లో ఉన్న నాకు మరింత బాధ కలిగించాలని శుద్ధ మనసుతో కాక కక్షతో క్రీస్తును ప్రకటిస్తున్నారు.","ayitē migatā vāru baṁdhakāllō unna nāku mariṁta bādha kaligiṁcālani śuddha manasutō kāka kakṣatō krīstunu prakaṭistunnāru.",null],[1,18,"అయితేనేం? కపటంతో గానీ సత్యంతో గాని, ఎలాగైనా క్రీస్తును ప్రకటించడం మాత్రం జరుగుతూ ఉంది. అందుకు నేను ఆనందిస్తున్నాను. ఇక ముందు కూడా ఆనందిస్తాను.","ayitēnēṁ? kapaṭaṁtō gānī satyaṁtō gāni, elāgainā krīstunu prakaṭiṁcaḍaṁ mātraṁ jarugutū uṁdi. aṁduku nēnu ānaṁdistunnānu. ika muṁdu kūḍā ānaṁdistānu.",null],[1,19,"మీ ప్రార్థనల వలన, యేసు క్రీస్తు ఆత్మసాయం వలన, నా విడుదల కోసం ఇదంతా జరుగుతూ ఉందని నాకు తెలుసు.","mī prārthanala valana, yēsu krīstu ātmasāyaṁ valana, nā viḍudala kōsaṁ idaṁtā jarugutū uṁdani nāku telusu.",null],[1,20,"నేను ఏ విషయంలోనైనా సిగ్గుపాలు కానని నాకు నిబ్బరమైన ఆశాభావం ఉంది. అయితే, ఎప్పటిలాగానే ఇప్పుడు కూడా నా జీవితం వలన గానీ, చావు వలన గానీ క్రీస్తును నా శరీరంతో ఘనపరుస్తాను అనే ధైర్యం ఉంది.","nēnu ē viṣayaṁlōnainā siggupālu kānani nāku nibbaramaina āśābhāvaṁ uṁdi. ayitē, eppaṭilāgānē ippuḍu kūḍā nā jīvitaṁ valana gānī, cāvu valana gānī krīstunu nā śarīraṁtō ghanaparustānu anē dhairyaṁ uṁdi.",null],[1,21,"నావరకైతే బతకడం క్రీస్తే, మరి చావడం లాభమే.","nāvarakaitē batakaḍaṁ krīstē, mari cāvaḍaṁ lābhamē.",null],[1,22,"అయినా శరీరంలో నేనింకా బతుకుతూ నా ప్రయాసకు ఫలితం ఉంటే, అప్పుడు నేనేం కోరుకోవాలో నాకు తెలియడం లేదు.","ayinā śarīraṁlō nēniṁkā batukutū nā prayāsaku phalitaṁ uṁṭē, appuḍu nēnēṁ kōrukōvālō nāku teliyaḍaṁ lēdu.",null],[1,23,"ఈ రెండింటి మధ్య ఇరుక్కుపోయాను. నేను లోకాన్ని విడిచి క్రీస్తుతోనే ఉండిపోవాలని నా కోరిక. అన్నిటికంటే అదే ఉత్తమం.","ī reṁḍiṁṭi madhya irukkupōyānu. nēnu lōkānni viḍici krīstutōnē uṁḍipōvālani nā kōrika. anniṭikaṁṭē adē uttamaṁ.",null],[1,24,"అయినా నేను శరీరంతో ఉండడం మీకోసం మరింత అవసరం.","ayinā nēnu śarīraṁtō uṁḍaḍaṁ mīkōsaṁ mariṁta avasaraṁ.",null],[1,25,"తద్వారా, నేను మీ దగ్గరికి తిరిగి రావడంవల్ల క్రీస్తు యేసులో నన్ను బట్టి మీరు గర్వ పడతారు. మీరు విశ్వాసంలో అభివృద్ధి, ఆనందం పొందడానికి నేను జీవిస్తూ మీ అందరితో ఉంటానని నాకు గట్టి నమ్మకం ఉంది.","tadvārā, nēnu mī daggariki tirigi rāvaḍaṁvalla krīstu yēsulō nannu baṭṭi mīru garva paḍatāru. mīru viśvāsaṁlō abhivr̥ddhi, ānaṁdaṁ poṁdaḍāniki nēnu jīvistū mī aṁdaritō uṁṭānani nāku gaṭṭi nammakaṁ uṁdi.",26],[1,27,"నేను మిమ్మల్ని చూడడానికి వచ్చినా, రాకపోయినా, అందరూ కలిసికట్టుగా సువార్త విశ్వాసం పక్షంగా పోరాడుతూ, ఏక భావంతో నిలిచి ఉన్నారని నేను మిమ్మల్ని గురించి వినేలా, మీరు క్రీస్తు సువార్తకు తగినట్టుగా ప్రవర్తించండి.","nēnu mimmalni cūḍaḍāniki vaccinā, rākapōyinā, aṁdarū kalisikaṭṭugā suvārta viśvāsaṁ pakṣaṁgā pōrāḍutū, ēka bhāvaṁtō nilici unnārani nēnu mimmalni guriṁci vinēlā, mīru krīstu suvārtaku taginaṭṭugā pravartiṁcaṁḍi.",null],[1,28,"మిమ్మల్ని ఎదిరించే వారికి ఏ విషయంలోనూ భయపడవద్దు. మీ ధైర్యం వారికి నాశనం, మీకు రక్షణ కలుగుతాయని తెలిపే సూచన. ఇది దేవుని వలన కలిగే విడుదల.","mimmalni ediriṁcē vāriki ē viṣayaṁlōnū bhayapaḍavaddu. mī dhairyaṁ vāriki nāśanaṁ, mīku rakṣaṇa kalugutāyani telipē sūcana. idi dēvuni valana kaligē viḍudala.",null],[1,29,"గతంలో నేను సాగించిన పోరాటాన్ని చూసారు. దాన్ని గురించి వింటున్నారు. మీరు కూడా అదే పోరాటంలో ఉన్నారు. కాబట్టి దేవుడు మీకు కేవలం క్రీస్తును విశ్వసించే అవకాశమే కాకుండా, ఆయన కోసం కష్టాలు అనుభవించే అవకాశం కూడా కలిగించాడు.","gataṁlō nēnu sāgiṁcina pōrāṭānni cūsāru. dānni guriṁci viṁṭunnāru. mīru kūḍā adē pōrāṭaṁlō unnāru. kābaṭṭi dēvuḍu mīku kēvalaṁ krīstunu viśvasiṁcē avakāśamē kākuṁḍā, āyana kōsaṁ kaṣṭālu anubhaviṁcē avakāśaṁ kūḍā kaligiṁcāḍu.",30],[2,1,"క్రీస్తులో ఎలాంటి ప్రోత్సాహం గానీ, ప్రేమ ద్వారా ఎలాంటి ఆదరణ గానీ, దేవుని ఆత్మతో ఎలాంటి సహవాసం గానీ, సున్నితమైన ఎలాంటి కనికరం, వాత్సల్యం గానీ ఉన్నట్టయితే,","krīstulō elāṁṭi prōtsāhaṁ gānī, prēma dvārā elāṁṭi ādaraṇa gānī, dēvuni ātmatō elāṁṭi sahavāsaṁ gānī, sunnitamaina elāṁṭi kanikaraṁ, vātsalyaṁ gānī unnaṭṭayitē,",null],[2,2,"మీరంతా ఒకే మనసు, ఒకే విధమైన ప్రేమ, ఆత్మలో సహవాసం ఒకే ఉద్దేశం కలిగిఉండి నా ఆనందాన్ని సంపూర్ణం చేయండి.","mīraṁtā okē manasu, okē vidhamaina prēma, ātmalō sahavāsaṁ okē uddēśaṁ kaligiuṁḍi nā ānaṁdānni saṁpūrṇaṁ cēyaṁḍi.",null],[2,3,"స్వార్ధంతో గానీ వృథాతిశయంతో గానీ ఏమీ చేయవద్దు. వినయమైన మనసుతో ఇతరులను మీకంటే యోగ్యులుగా ఎంచుకోండి.","svārdhaṁtō gānī vr̥thātiśayaṁtō gānī ēmī cēyavaddu. vinayamaina manasutō itarulanu mīkaṁṭē yōgyulugā eṁcukōṁḍi.",null],[2,4,"మీలో ప్రతివాడూ తన సొంత అవసరాలే కాకుండా ఇతరుల అవసరాలను కూడా పట్టించుకోవాలి.","mīlō prativāḍū tana soṁta avasarālē kākuṁḍā itarula avasarālanu kūḍā paṭṭiṁcukōvāli.",null],[2,5,"క్రీస్తు యేసుకున్న ఇలాంటి ప్రవృత్తినే మీరూ కలిగి ఉండండి.","krīstu yēsukunna ilāṁṭi pravr̥ttinē mīrū kaligi uṁḍaṁḍi.",null],[2,6,"ఆయన దేవుని స్వరూపం కలిగినవాడు. దేవునితో తన సమానత్వాన్ని విడిచిపెట్ట లేనిదిగా ఎంచుకోలేదు.","āyana dēvuni svarūpaṁ kaliginavāḍu. dēvunitō tana samānatvānni viḍicipeṭṭa lēnidigā eṁcukōlēdu.",null],[2,7,"అయితే, దానికి ప్రతిగా తనను తాను ఖాళీ చేసుకున్నాడు. బానిస రూపం తీసుకున్నాడు. మానవుల పోలికలో కనిపించాడు. ఆకారంలో ఆయన మనిషిగా కనిపించాడు.","ayitē, dāniki pratigā tananu tānu khāḷī cēsukunnāḍu. bānisa rūpaṁ tīsukunnāḍu. mānavula pōlikalō kanipiṁcāḍu. ākāraṁlō āyana maniṣigā kanipiṁcāḍu.",null],[2,8,"చావు దాకా, అంటే, సిలువ మీద చావుకైనా సరే, తనను తాను తగ్గించుకుని, లోబడ్డాడు.","cāvu dākā, aṁṭē, siluva mīda cāvukainā sarē, tananu tānu taggiṁcukuni, lōbaḍḍāḍu.",null],[2,9,"అందుచేత పరలోకంలోనూ, భూమి మీదా, భూమి కిందా ఉన్న ప్రతి ఒక్కరి మోకాలు యేసు నామంలో వంగేలా, ప్రతి నాలుక తండ్రి అయిన దేవుని మహిమ కోసం యేసు క్రీస్తును ప్రభువుగా అంగీకరించేలా, దేవుడు ఆయనను ఎంతో ఉన్నతంగా హెచ్చించి, అందరికంటే ఉన్నతమైన నామాన్ని ఆయనకు ఇచ్చాడు.","aṁducēta paralōkaṁlōnū, bhūmi mīdā, bhūmi kiṁdā unna prati okkari mōkālu yēsu nāmaṁlō vaṁgēlā, prati nāluka taṁḍri ayina dēvuni mahima kōsaṁ yēsu krīstunu prabhuvugā aṁgīkariṁcēlā, dēvuḍu āyananu eṁtō unnataṁgā hecciṁci, aṁdarikaṁṭē unnatamaina nāmānni āyanaku iccāḍu.",11],[2,12,"నా ప్రియ సహ విశ్వాసులారా, మీరెప్పుడూ లోబడుతున్నట్టుగానే, నేను మీ దగ్గర ఉన్నప్పుడు మాత్రమే కాకుండా, మరి ఎక్కువగా మీతో లేనప్పుడు, భయభక్తులతో మీ సొంత రక్షణను కొనసాగించుకోండి.","nā priya saha viśvāsulārā, mīreppuḍū lōbaḍutunnaṭṭugānē, nēnu mī daggara unnappuḍu mātramē kākuṁḍā, mari ekkuvagā mītō lēnappuḍu, bhayabhaktulatō mī soṁta rakṣaṇanu konasāgiṁcukōṁḍi.",null],[2,13,"ఎందుకంటే దేవుడే మీరు తనకిష్టమైన ఉద్దేశాన్ని నెరవేర్చటానికి కావలసిన సంకల్పాన్ని, కార్యసిద్ధిని కలుగజేయడానికి మీలో పని చేస్తూ ఉన్నాడు.","eṁdukaṁṭē dēvuḍē mīru tanakiṣṭamaina uddēśānni neravērcaṭāniki kāvalasina saṁkalpānni, kāryasiddhini kalugajēyaḍāniki mīlō pani cēstū unnāḍu.",null],[2,14,"మీరు చేసేవన్నీ, ఫిర్యాదులూ వాదాలూ లేకుండా చేయండి.","mīru cēsēvannī, phiryādulū vādālū lēkuṁḍā cēyaṁḍi.",null],[2,15,"దానివలన మీరు కుటిలమైన వక్రమైన ఈ తరం ప్రజల మధ్య నిర్దోషులు, నిందారహితులు, నిష్కళంకులైన దేవుని కుమారులుగా, లోకంలో దీపాలుగా వెలుగుతుంటారు.","dānivalana mīru kuṭilamaina vakramaina ī taraṁ prajala madhya nirdōṣulu, niṁdārahitulu, niṣkaḷaṁkulaina dēvuni kumārulugā, lōkaṁlō dīpālugā velugutuṁṭāru.",null],[2,16,"జీవవాక్యాన్ని గట్టిగా పట్టుకోండి. అప్పుడు క్రీస్తు తిరిగి వచ్చే రోజున నేను వ్యర్థంగా పరుగెత్తలేదనీ నా పని వృధా కాలేదనీ నాకు తెలుస్తుంది. గొప్పగా చెప్పుకోడానికి నాకొక కారణం ఉంటుంది.","jīvavākyānni gaṭṭigā paṭṭukōṁḍi. appuḍu krīstu tirigi vaccē rōjuna nēnu vyarthaṁgā parugettalēdanī nā pani vr̥dhā kālēdanī nāku telustuṁdi. goppagā ceppukōḍāniki nākoka kāraṇaṁ uṁṭuṁdi.",null],[2,17,"మీ విశ్వాస బలిదాన పరిచర్యలో నేను పానార్పణగా పోయబడినా, నేను సంతోషిస్తూ మీ అందరితో ఆనందిస్తాను.","mī viśvāsa balidāna paricaryalō nēnu pānārpaṇagā pōyabaḍinā, nēnu saṁtōṣistū mī aṁdaritō ānaṁdistānu.",null],[2,18,"అలాగే మీరు కూడా సంతోషిస్తూ నాతోబాటు ఆనందించండి.","alāgē mīru kūḍā saṁtōṣistū nātōbāṭu ānaṁdiṁcaṁḍi.",null],[2,19,"మీరెలా ఉన్నారో తెలుసుకుని నాకు ప్రోత్సాహం కలిగేలా, ప్రభు యేసు చిత్తమైతే త్వరలో తిమోతిని మీ దగ్గరికి పంపాలనుకుంటున్నాను.","mīrelā unnārō telusukuni nāku prōtsāhaṁ kaligēlā, prabhu yēsu cittamaitē tvaralō timōtini mī daggariki paṁpālanukuṁṭunnānu.",null],[2,20,"తిమోతి లాగా మీ గురించి అంతగా పట్టించుకొనే వాడు నాకెవరూ లేరు.","timōti lāgā mī guriṁci aṁtagā paṭṭiṁcukonē vāḍu nākevarū lēru.",null],[2,21,"మిగతా వారంతా తమ సొంత పనుల్నే చూసుకుంటున్నారు గాని, యేసు క్రీస్తు విషయాలు చూడడం లేదు.","migatā vāraṁtā tama soṁta panulnē cūsukuṁṭunnāru gāni, yēsu krīstu viṣayālu cūḍaḍaṁ lēdu.",null],[2,22,"తిమోతి తనను తాను రుజువు చేసుకున్నాడు. ఎందుకంటే, తండ్రికి కొడుకు ఎలా సేవ చేస్తాడో అలాగే అతడు నాతో కూడ సువార్త ప్రచారంలో సేవ చేశాడని మీకు తెలుసు.","timōti tananu tānu rujuvu cēsukunnāḍu. eṁdukaṁṭē, taṁḍriki koḍuku elā sēva cēstāḍō alāgē ataḍu nātō kūḍa suvārta pracāraṁlō sēva cēśāḍani mīku telusu.",null],[2,23,"అందుచేత నాకు ఏం జరగబోతున్నదో తెలిసిన వెంటనే అతన్ని పంపాలనుకుంటున్నాను.","aṁducēta nāku ēṁ jaragabōtunnadō telisina veṁṭanē atanni paṁpālanukuṁṭunnānu.",null],[2,24,"నేను త్వరలో వస్తానని ప్రభువునుబట్టి నమ్ముతున్నాను.","nēnu tvaralō vastānani prabhuvunubaṭṭi nammutunnānu.",null],[2,25,"నా సోదరుడు, జతపని వాడు, సాటి యోధుడు, మీ ప్రతినిధి, నాకు అవసరమైనప్పుడు సేవ చేసే వాడు అయిన ఎపఫ్రొదితును మీ దగ్గరికి పంపడం అవసరమనుకున్నాను.","nā sōdaruḍu, jatapani vāḍu, sāṭi yōdhuḍu, mī pratinidhi, nāku avasaramainappuḍu sēva cēsē vāḍu ayina epaphroditunu mī daggariki paṁpaḍaṁ avasaramanukunnānu.",null],[2,26,"అతడు జబ్బు పడ్డాడని మీకు తెలిసింది కాబట్టి అతడు మీ అందరితో ఉండాలని చాలా బెంగగా ఉన్నాడు.","ataḍu jabbu paḍḍāḍani mīku telisiṁdi kābaṭṭi ataḍu mī aṁdaritō uṁḍālani cālā beṁgagā unnāḍu.",null],[2,27,"అతడు చావుకు దగ్గరగా వెళ్ళాడు, కానీ దేవుడు అతని మీద జాలి చూపించాడు. అతని మీదే కాదు, దుఃఖం వెంట దుఃఖం కలగకుండా నా మీద కూడా జాలి చూపాడు.","ataḍu cāvuku daggaragā veḷḷāḍu, kānī dēvuḍu atani mīda jāli cūpiṁcāḍu. atani mīdē kādu, duḥkhaṁ veṁṭa duḥkhaṁ kalagakuṁḍā nā mīda kūḍā jāli cūpāḍu.",null],[2,28,"కాబట్టి మీరు అతన్ని మళ్ళీ చూసి సంతోషించేలా, నా విచారం తగ్గేలా అతన్ని త్వరపెట్టి పంపుతున్నాను.","kābaṭṭi mīru atanni maḷḷī cūsi saṁtōṣiṁcēlā, nā vicāraṁ taggēlā atanni tvarapeṭṭi paṁputunnānu.",null],[2,29,"ఎపఫ్రొదితును పూర్ణానందంతో ప్రభువు పేరిట చేర్చుకోండి. అలాంటి వారిని గౌరవంగా చూడండి.","epaphroditunu pūrṇānaṁdaṁtō prabhuvu pēriṭa cērcukōṁḍi. alāṁṭi vārini gauravaṁgā cūḍaṁḍi.",null],[2,30,"ఎందుకంటే అతడు క్రీస్తు పనిలో దాదాపు చావును ఎదుర్కొన్నాడు. నాకు సేవ చేయడానికీ మీరు తీర్చలేకపోయిన నా అవసరాలను మీ బదులు తీర్చడానికి, అతడు తన ప్రాణం సైతం లెక్కచేయలేదు.","eṁdukaṁṭē ataḍu krīstu panilō dādāpu cāvunu edurkonnāḍu. nāku sēva cēyaḍānikī mīru tīrcalēkapōyina nā avasarālanu mī badulu tīrcaḍāniki, ataḍu tana prāṇaṁ saitaṁ lekkacēyalēdu.",null],[3,1,"చివరిగా, నా సోదరులారా, ప్రభువులో ఆనందించండి. ఈ విషయాలనే మీకు మరలా రాయడం నాకేమీ సమస్య కాదు. మీకది క్షేమకరం.","civarigā, nā sōdarulārā, prabhuvulō ānaṁdiṁcaṁḍi. ī viṣayālanē mīku maralā rāyaḍaṁ nākēmī samasya kādu. mīkadi kṣēmakaraṁ.",null],[3,2,"కుక్కల విషయం జాగ్రత్త. చెడు పనులు చేసే వారి విషయం జాగ్రత్త. ఛేదించే ఆచారం పాటించే వారి విషయం జాగ్రత్త.","kukkala viṣayaṁ jāgratta. ceḍu panulu cēsē vāri viṣayaṁ jāgratta. chēdiṁcē ācāraṁ pāṭiṁcē vāri viṣayaṁ jāgratta.",null],[3,3,"ఎందుకంటే, మనం దేవుని ఆత్మతో ఆరాధిస్తూ శరీరం మీద నమ్మకం పెట్టుకోకుండా క్రీస్తు యేసులో అతిశయిస్తున్నాము. మనమే అసలైన సున్నతి పొందిన వాళ్ళం.","eṁdukaṁṭē, manaṁ dēvuni ātmatō ārādhistū śarīraṁ mīda nammakaṁ peṭṭukōkuṁḍā krīstu yēsulō atiśayistunnāmu. manamē asalaina sunnati poṁdina vāḷḷaṁ.",null],[3,4,"చెప్పాలంటే, వాస్తవంగా నేనే శరీరాన్ని ఆధారం చేసుకోగలను. ఎవరైనా శరీరాన్ని ఆధారం చేసుకోవాలనుకుంటే నేను మరి ఎక్కువగా చేసుకోగలను.","ceppālaṁṭē, vāstavaṁgā nēnē śarīrānni ādhāraṁ cēsukōgalanu. evarainā śarīrānni ādhāraṁ cēsukōvālanukuṁṭē nēnu mari ekkuvagā cēsukōgalanu.",null],[3,5,"ఎనిమిదవ రోజున సున్నతి పొందాను. ఇశ్రాయేలు జాతిలో పుట్టాను. బెన్యామీను గోత్రానికి చెందిన వాణ్ణి. హెబ్రీయుల్లో హెబ్రీయుణ్ణి. ధర్మశాస్త్రం విషయంలో పరిసయ్యుణ్ణి.","enimidava rōjuna sunnati poṁdānu. iśrāyēlu jātilō puṭṭānu. benyāmīnu gōtrāniki ceṁdina vāṇṇi. hebrīyullō hebrīyuṇṇi. dharmaśāstraṁ viṣayaṁlō parisayyuṇṇi.",null],[3,6,"క్రైస్తవ సంఘాన్ని తీవ్రంగా హింసించాను. ధర్మశాస్త్ర సంబంధమైన నీతి విషయంలో నిందారహితుడిని.","kraistava saṁghānni tīvraṁgā hiṁsiṁcānu. dharmaśāstra saṁbaṁdhamaina nīti viṣayaṁlō niṁdārahituḍini.",null],[3,7,"అయినా ఏవేవి నాకు లాభంగా ఉండేవో వాటిని క్రీస్తు కోసం పనికిరానివిగా ఎంచాను.","ayinā ēvēvi nāku lābhaṁgā uṁḍēvō vāṭini krīstu kōsaṁ panikirānivigā eṁcānu.",null],[3,8,"వాస్తవంగా ఇప్పుడు మిగతా వాటన్నిటినీ నష్టంగా ఎంచుతున్నాను ఎందుకంటే నా ప్రభువైన యేసు క్రీస్తును ఎరగడమే ఎంతో శ్రేష్ఠమైన విషయం. ఆయనను బట్టి మిగతా వాటన్నిటినీ ఇష్టపూర్వకంగా తిరస్కరించాను. క్రీస్తును సంపాదించటానికి వాటిని చెత్తతో సమానంగా ఎంచాను.","vāstavaṁgā ippuḍu migatā vāṭanniṭinī naṣṭaṁgā eṁcutunnānu eṁdukaṁṭē nā prabhuvaina yēsu krīstunu eragaḍamē eṁtō śrēṣṭhamaina viṣayaṁ. āyananu baṭṭi migatā vāṭanniṭinī iṣṭapūrvakaṁgā tiraskariṁcānu. krīstunu saṁpādiṁcaṭāniki vāṭini cettatō samānaṁgā eṁcānu.",null],[3,9,"ధర్మశాస్త్రమూలమైన నా స్వనీతిగాక, క్రీస్తులోని విశ్వాసమూలమైన నీతికి బదులుగా, అంటే విశ్వాసాన్ని బట్టి దేవుడు అనుగ్రహించే నీతిగలవాడనై ఆయనలో కనపడేలా అలా చేశాను.","dharmaśāstramūlamaina nā svanītigāka, krīstulōni viśvāsamūlamaina nītiki badulugā, aṁṭē viśvāsānni baṭṭi dēvuḍu anugrahiṁcē nītigalavāḍanai āyanalō kanapaḍēlā alā cēśānu.",null],[3,10,"ఆయనను ఎరగడం అనే నీతిన్యాయాలు, ఆయన పునరుత్థాన శక్తి, ఆయన పొందిన హింసల్లో సహానుభవం, క్రీస్తు మూలంగా ఆయన మరణం పోలికలోకి మార్పు చెందడం కోసం, ఏ విధంగానైనా చనిపోయిన వారిలో నుండి నాకు పునరుత్థానం కలగాలని, కోరుతున్నాను.","āyananu eragaḍaṁ anē nītinyāyālu, āyana punarutthāna śakti, āyana poṁdina hiṁsallō sahānubhavaṁ, krīstu mūlaṁgā āyana maraṇaṁ pōlikalōki mārpu ceṁdaḍaṁ kōsaṁ, ē vidhaṁgānainā canipōyina vārilō nuṁḍi nāku punarutthānaṁ kalagālani, kōrutunnānu.",11],[3,12,"వీటన్నిటినీ ఇంకా నేను పొందలేదు కాబట్టి నేనింకా సంపూర్ణుణ్ణి కాదు. క్రీస్తు నన్ను దేనికోసమైతే పట్టుకున్నాడో దాన్ని నేను కూడా సొంతం చేసుకోవాలని నేనింకా ప్రయత్నిస్తూనే ఉన్నాను.","vīṭanniṭinī iṁkā nēnu poṁdalēdu kābaṭṭi nēniṁkā saṁpūrṇuṇṇi kādu. krīstu nannu dēnikōsamaitē paṭṭukunnāḍō dānni nēnu kūḍā soṁtaṁ cēsukōvālani nēniṁkā prayatnistūnē unnānu.",null],[3,13,"సోదరులారా, దాన్ని నేను ఇప్పటికే సాధించానని అనడం లేదు. అయితే ఒకటి మాత్రం చేస్తున్నాను. గతంలో జరిగిన దాన్ని మరచిపోయి, ముందున్న వాటి కోసం ప్రయాస పడుతున్నాను.","sōdarulārā, dānni nēnu ippaṭikē sādhiṁcānani anaḍaṁ lēdu. ayitē okaṭi mātraṁ cēstunnānu. gataṁlō jarigina dānni maracipōyi, muṁdunna vāṭi kōsaṁ prayāsa paḍutunnānu.",null],[3,14,"క్రీస్తు యేసులో దేవుని ఉన్నతమైన పిలుపుకు సంబంధించిన బహుమతి కోసం గురి దగ్గరకే పరుగెత్తుతూ ఉన్నాను.","krīstu yēsulō dēvuni unnatamaina pilupuku saṁbaṁdhiṁcina bahumati kōsaṁ guri daggarakē parugettutū unnānu.",null],[3,15,"కాబట్టి విశ్వాసంలో దృఢంగా ఉన్న విశ్వాసులమైన మనం, అలానే ఆలోచించాలని ప్రోత్సహిస్తున్నాను. మరి ఏ విషయం గురించి అయినా, మీరు వేరొక విధంగా ఆలోచిస్తుంటే దేవుడు దాన్ని కూడా మీకు స్పష్టం చేస్తాడు.","kābaṭṭi viśvāsaṁlō dr̥ḍhaṁgā unna viśvāsulamaina manaṁ, alānē ālōciṁcālani prōtsahistunnānu. mari ē viṣayaṁ guriṁci ayinā, mīru vēroka vidhaṁgā ālōcistuṁṭē dēvuḍu dānni kūḍā mīku spaṣṭaṁ cēstāḍu.",null],[3,16,"ఏమైనా సరే, మనం ఇప్పటికే పొందిన అదే సత్యానికి అనుగుణంగా మనమంతా నడుచుకొందాము.","ēmainā sarē, manaṁ ippaṭikē poṁdina adē satyāniki anuguṇaṁgā manamaṁtā naḍucukoṁdāmu.",null],[3,17,"సోదరులారా, మీరు నన్ను పోలి ప్రవర్తించండి. మమ్మల్ని ఆదర్శంగా తీసుకుని నడుచుకునే వారిని జాగ్రత్తగా గమనించండి.","sōdarulārā, mīru nannu pōli pravartiṁcaṁḍi. mammalni ādarśaṁgā tīsukuni naḍucukunē vārini jāgrattagā gamaniṁcaṁḍi.",null],[3,18,"చాలా మంది క్రీస్తు సిలువకు శత్రువులుగా నడుచుకుంటున్నారు. వీరిని గురించి మీతో చాలా సార్లు చెప్పాను. ఇప్పుడు కూడా దుఃఖంతో చెబుతున్నాను.","cālā maṁdi krīstu siluvaku śatruvulugā naḍucukuṁṭunnāru. vīrini guriṁci mītō cālā sārlu ceppānu. ippuḍu kūḍā duḥkhaṁtō cebutunnānu.",null],[3,19,"నాశనమే వారి అంతం. వారి కడుపే వారి దేవుడు. వారు తాము సిగ్గుపడవలసిన వాటినే గొప్పగా చెప్పుకుంటున్నారు. లౌకిక విషయాల మీదే వారు మనసు ఉంచుతారు.","nāśanamē vāri aṁtaṁ. vāri kaḍupē vāri dēvuḍu. vāru tāmu siggupaḍavalasina vāṭinē goppagā ceppukuṁṭunnāru. laukika viṣayāla mīdē vāru manasu uṁcutāru.",null],[3,20,"ఎందుకంటే మనం అయితే పరలోక పౌరులం. మన రక్షకుడైన యేసు క్రీస్తు ప్రభువు అక్కడ నుండే భూమి మీదికి వస్తాడని ఎదురు చూస్తూ ఉన్నాం.","eṁdukaṁṭē manaṁ ayitē paralōka paurulaṁ. mana rakṣakuḍaina yēsu krīstu prabhuvu akkaḍa nuṁḍē bhūmi mīdiki vastāḍani eduru cūstū unnāṁ.",null],[3,21,"సమస్తాన్నీ ఏ శక్తితో ఆయన నియంత్రిస్తున్నాడో అదే శక్తితో మన బలహీనమైన దేహాలను తన మహిమగల దేహంలాగా మార్చి వేస్తాడు.","samastānnī ē śaktitō āyana niyaṁtristunnāḍō adē śaktitō mana balahīnamaina dēhālanu tana mahimagala dēhaṁlāgā mārci vēstāḍu.",null],[4,1,"కాబట్టి నా ప్రియ సోదరులారా, మీరంటే నాకెంతో ఇష్టం. మిమ్మల్ని చూడాలని చాలా ఆశగా ఉంది. నా ఆనందం, నా కిరీటంగా ఉన్న నా ప్రియ మిత్రులారా, ప్రభువులో స్థిరంగా ఉండండి.","kābaṭṭi nā priya sōdarulārā, mīraṁṭē nākeṁtō iṣṭaṁ. mimmalni cūḍālani cālā āśagā uṁdi. nā ānaṁdaṁ, nā kirīṭaṁgā unna nā priya mitrulārā, prabhuvulō sthiraṁgā uṁḍaṁḍi.",null],[4,2,"ప్రభువులో మనసు కలిసి ఉండమని యువొదియను, సుంటుకేను బ్రతిమాలుతున్నాను.","prabhuvulō manasu kalisi uṁḍamani yuvodiyanu, suṁṭukēnu bratimālutunnānu.",null],[4,3,"అవును, నా నిజ సహకారీ, నిన్ను కూడా అడుగుతున్నాను. ఆ స్త్రీలు క్లెమెంతుతో, నా మిగతా సహకారులతో సువార్త పనిలో నాతో ప్రయాసపడ్డారు కాబట్టి వారికి సహాయం చెయ్యి. వారి పేర్లు జీవ గ్రంథంలో రాసి ఉన్నాయి.","avunu, nā nija sahakārī, ninnu kūḍā aḍugutunnānu. ā strīlu klemeṁtutō, nā migatā sahakārulatō suvārta panilō nātō prayāsapaḍḍāru kābaṭṭi vāriki sahāyaṁ ceyyi. vāri pērlu jīva graṁthaṁlō rāsi unnāyi.",null],[4,4,"ఎప్పుడూ ప్రభువులో ఆనందించండి. మళ్ళీ చెబుతాను, ఆనందించండి.","eppuḍū prabhuvulō ānaṁdiṁcaṁḍi. maḷḷī cebutānu, ānaṁdiṁcaṁḍi.",null],[4,5,"మీ సహనం అందరికీ తెలియాలి. ప్రభువు దగ్గరగా ఉన్నాడు.","mī sahanaṁ aṁdarikī teliyāli. prabhuvu daggaragā unnāḍu.",null],[4,6,"దేన్ని గూర్చీ చింతపడవద్దు. ప్రతి విషయంలోను ప్రార్థన విజ్ఞాపనలతో కృతజ్ఞతాపూర్వకంగా మీ విన్నపాలు దేవునికి తెలియజేయండి.","dēnni gūrcī ciṁtapaḍavaddu. prati viṣayaṁlōnu prārthana vijñāpanalatō kr̥tajñatāpūrvakaṁgā mī vinnapālu dēvuniki teliyajēyaṁḍi.",null],[4,7,"అప్పుడు సమస్త జ్ఞానానికీ మించిన దేవుని శాంతి, యేసు క్రీస్తులో మీ హృదయాలకూ మీ ఆలోచనలకూ కావలి ఉంటుంది.","appuḍu samasta jñānānikī miṁcina dēvuni śāṁti, yēsu krīstulō mī hr̥dayālakū mī ālōcanalakū kāvali uṁṭuṁdi.",null],[4,8,"చివరికి, సోదరులారా, ఏవి వాస్తవమో ఏవి గౌరవించదగినవో ఏవి న్యాయమైనవో ఏవి పవిత్రమైనవో ఏవి రమ్యమైనవో ఏవి మంచి పేరు గలవో ఏవి నైతికంగా మంచివో మెచ్చుకోదగినవో అలాంటి వాటిని గురించే తలపోస్తూ ఉండండి.","civariki, sōdarulārā, ēvi vāstavamō ēvi gauraviṁcadaginavō ēvi nyāyamainavō ēvi pavitramainavō ēvi ramyamainavō ēvi maṁci pēru galavō ēvi naitikaṁgā maṁcivō meccukōdaginavō alāṁṭi vāṭini guriṁcē talapōstū uṁḍaṁḍi.",null],[4,9,"మీరు నా దగ్గర ఏవి నేర్చుకుని అంగీకరించారో నాలో ఉన్నట్టుగా ఏవి విన్నారో ఏవి చూచారో, వాటిని చేయండి. అప్పుడు శాంతికి కర్త అయిన దేవుడు మీకు తోడుగా ఉంటాడు.","mīru nā daggara ēvi nērcukuni aṁgīkariṁcārō nālō unnaṭṭugā ēvi vinnārō ēvi cūcārō, vāṭini cēyaṁḍi. appuḍu śāṁtiki karta ayina dēvuḍu mīku tōḍugā uṁṭāḍu.",null],[4,10,"నా గురించి మీరు ఇప్పటికైనా మళ్ళీ శ్రద్ధ వహించారని ప్రభువులో చాలా సంతోషించాను. గతంలో మీరు నా గురించి ఆలోచించారు గానీ మీకు సరైన అవకాశం దొరకలేదు.","nā guriṁci mīru ippaṭikainā maḷḷī śraddha vahiṁcārani prabhuvulō cālā saṁtōṣiṁcānu. gataṁlō mīru nā guriṁci ālōciṁcāru gānī mīku saraina avakāśaṁ dorakalēdu.",null],[4,11,"నాకేదో అవసరం ఉందని నేనిలా చెప్పడం లేదు. నేను ఏ పరిస్థితిలో ఉన్నా సరే, ఆ పరిస్థితిలో సంతృప్తి కలిగి ఉండడం నేర్చుకున్నాను.","nākēdō avasaraṁ uṁdani nēnilā ceppaḍaṁ lēdu. nēnu ē paristhitilō unnā sarē, ā paristhitilō saṁtr̥pti kaligi uṁḍaḍaṁ nērcukunnānu.",null],[4,12,"అవసరంలో బతకడం తెలుసు, సంపన్న స్థితిలో బతకడం తెలుసు. ప్రతి విషయంలో అన్ని పరిస్థితుల్లో కడుపు నిండి ఉండడానికీ ఆకలితో ఉండడానికీ సమృద్ధి కలిగి ఉండడం, లేమిలో ఉండడం నేర్చుకున్నాను.","avasaraṁlō batakaḍaṁ telusu, saṁpanna sthitilō batakaḍaṁ telusu. prati viṣayaṁlō anni paristhitullō kaḍupu niṁḍi uṁḍaḍānikī ākalitō uṁḍaḍānikī samr̥ddhi kaligi uṁḍaḍaṁ, lēmilō uṁḍaḍaṁ nērcukunnānu.",null],[4,13,"నన్ను బలపరచే వాడి ద్వారా నేను సమస్తాన్నీ చేయగలను.","nannu balaparacē vāḍi dvārā nēnu samastānnī cēyagalanu.",null],[4,14,"అయినా నా కష్టాలు పంచుకోవడంలో మీరు మంచి పని చేశారు.","ayinā nā kaṣṭālu paṁcukōvaḍaṁlō mīru maṁci pani cēśāru.",null],[4,15,"ఫిలిప్పీయులారా, నేను సువార్త బోధించడం మొదలుపెట్టి మాసిదోనియ నుంచి బయలుదేరినప్పుడు మీ సంఘమొక్కటే నాకు సహాయం చేసి నన్ను ఆదుకున్నది. ఈ సంగతి మీకే తెలుసు.","philippīyulārā, nēnu suvārta bōdhiṁcaḍaṁ modalupeṭṭi māsidōniya nuṁci bayaludērinappuḍu mī saṁghamokkaṭē nāku sahāyaṁ cēsi nannu ādukunnadi. ī saṁgati mīkē telusu.",null],[4,16,"ఎందుకంటే తెస్సలోనికలో కూడా మీరు మాటిమాటికీ నా అవసరం తీర్చడానికి సహాయం చేశారు.","eṁdukaṁṭē tessalōnikalō kūḍā mīru māṭimāṭikī nā avasaraṁ tīrcaḍāniki sahāyaṁ cēśāru.",null],[4,17,"నేను బహుమానాన్ని ఆశించి ఇలా చెప్పడం లేదు, మీకు ప్రతిఫలం అధికం కావాలని ఆశిస్తూ చెబుతున్నాను.","nēnu bahumānānni āśiṁci ilā ceppaḍaṁ lēdu, mīku pratiphalaṁ adhikaṁ kāvālani āśistū cebutunnānu.",null],[4,18,"నాకు అన్నీ సమృద్ధిగా ఉన్నాయి. మీరు పంపిన వస్తువులు ఎపఫ్రొదితు ద్వారా అందాయి. నాకు ఏమీ కొదువ లేదు. అవి ఇంపైన సువాసనగా, దేవునికి ఇష్టమైన అర్పణగా ఉన్నాయి.","nāku annī samr̥ddhigā unnāyi. mīru paṁpina vastuvulu epaphroditu dvārā aṁdāyi. nāku ēmī koduva lēdu. avi iṁpaina suvāsanagā, dēvuniki iṣṭamaina arpaṇagā unnāyi.",null],[4,19,"కాగా నా దేవుడు తన ఐశ్వర్యంతో క్రీస్తు యేసు మహిమలో మీ ప్రతి అవసరాన్నీ తీరుస్తాడు.","kāgā nā dēvuḍu tana aiśvaryaṁtō krīstu yēsu mahimalō mī prati avasarānnī tīrustāḍu.",null],[4,20,"ఇప్పుడు మన తండ్రి అయిన దేవునికి ఎప్పటికీ మహిమ కలుగు గాక. ఆమేన్‌.","ippuḍu mana taṁḍri ayina dēvuniki eppaṭikī mahima kalugu gāka. āmēn.",null],[4,21,"పవిత్రులందరికీ క్రీస్తు యేసులో అభివందనాలు చెప్పండి. నాతో పాటు ఉన్న సోదరులంతా మీకు అభివందనాలు చెబుతున్నారు.","pavitrulaṁdarikī krīstu yēsulō abhivaṁdanālu ceppaṁḍi. nātō pāṭu unna sōdarulaṁtā mīku abhivaṁdanālu cebutunnāru.",null],[4,22,"పవిత్రులంతా, ముఖ్యంగా సీజర్ చక్రవర్తి ఇంట్లో ఉన్న పవిత్రులు మీకు అభివందనాలు చెబుతున్నారు.","pavitrulaṁtā, mukhyaṁgā sījar cakravarti iṁṭlō unna pavitrulu mīku abhivaṁdanālu cebutunnāru.",null],[4,23,"ప్రభువైన యేసు క్రీస్తు కృప మీ ఆత్మతో ఉండు గాక.","prabhuvaina yēsu krīstu kr̥pa mī ātmatō uṁḍu gāka.",null]],"urdoucv":[[1,1,"یہ خط پَولُسؔ اَور تِیمُتھِیُس کی طرف سے جو المسیح یِسوعؔ کے خادِم ہیں،","y̰ḥ kẖṭ pawlusؔ ạawr tiy̰mutʱiy̰us ḵy̰ ṭrf sai jw ạlmsy̰ḥ y̰iswʿؔ ḵai kẖạdim ḥỹ̰,",null],[1,2,"ہمارے خُدا باپ اَور خُداوؔند یِسوعؔ المسیح کی طرف سے تُمہیں فضل اَور اِطمینان حاصل ہوتا رہے۔","ḥmạrai kẖudạ bạp ạawr kẖudạwؔnd y̰iswʿؔ ạlmsy̰ḥ ḵy̰ ṭrf sai tumḥỹ̰ fḍl ạawr ạiṭmy̰nạn ḥạṣl ḥwtạ rḥai.",null],[1,3,"میں جَب کبھی تُمہیں یاد کرتا ہُوں تو اَپنے خُدا کا شُکر اَدا کرتا ہُوں۔","mỹ̰ jab ḵbʱy̰ tumḥỹ̰ y̰ạd ḵrtạ ḥū̃ tw ạapnai kẖudạ ḵạ sẖuḵr ạadạ ḵrtạ ḥū̃.",null],[1,4,"اَور اَپنی ہر ایک دعا میں جو تمہارے لیٔے کرتا ہوں ہمیشہ خُوشی کے ساتھ تُم سَب کے لئے مِنّت کرتا ہُوں۔","ạawr ạapny̰ ḥr ạy̰ḵ dʿạ mỹ̰ jw tmḥạrai lỷ̰ai ḵrtạ ḥw̃ ḥmy̰sẖḥ kẖūsẖy̰ ḵai sạtʱ tum sab ḵai lỷai miñt ḵrtạ ḥū̃.",null],[1,5,"اِس لیٔے کہ تُم پہلے دِن سے آج تک خُوشخبری پھیلانے میں شریک رہے ہو،","ạis lỷ̰ai ḵḥ tum pḥlai din sai ậj tḵ kẖūsẖkẖbry̰ pʱy̰lạnai mỹ̰ sẖry̰ḵ rḥai ḥw,",null],[1,6,"اَور مُجھے اِس بات کا یقین ہے کہ خُدا، جِس نے تُم لوگوں میں اَپنا نیک کام شروع کیا ہے وہ اُسے المسیح یِسوعؔ کی واپسی کے دِن تک پُورا کر دے گا۔","ạawr mujʱai ạis bạt ḵạ y̰qy̰n ḥai ḵḥ kẖudạ, jis nai tum lwgw̃ mỹ̰ ạapnạ ny̰ḵ ḵạm sẖrwʿ ḵy̰ạ ḥai wḥ ạusai ạlmsy̰ḥ y̰iswʿؔ ḵy̰ wạpsy̰ ḵai din tḵ pūrạ ḵr dai gạ.",null],[1,7,"میرا تُم سَب کی بابت یہ خیال کرنا مُناسب ہے، کیونکہ تُم ہمیشہ میرے دِل میں رہتے ہو، نہ صِرف اِس وقت جَب کہ میں زنجیروں میں قَید ہُوں بَلکہ اُس وقت بھی جَب مَیں خُوشخبری کی جَوابدہی اَور ثبوت کے عَمل میں، تُم سَب میرے ساتھ خُدا کے فضل میں شریک رہے ہو۔","my̰rạ tum sab ḵy̰ bạbt y̰ḥ kẖy̰ạl ḵrnạ munạsb ḥai, ḵy̰wnḵḥ tum ḥmy̰sẖḥ my̰rai dil mỹ̰ rḥtai ḥw, nḥ ṣirf ạis wqt jab ḵḥ mỹ̰ znjy̰rw̃ mỹ̰ qay̰d ḥū̃ balḵḥ ạus wqt bʱy̰ jab maỹ̰ kẖūsẖkẖbry̰ ḵy̰ jawạbdḥy̰ ạawr tẖbwt ḵai ʿaml mỹ̰, tum sab my̰rai sạtʱ kẖudạ ḵai fḍl mỹ̰ sẖry̰ḵ rḥai ḥw.",null],[1,8,"خُدا گواہ ہے کہ میرے دِل میں تمہارے لیٔے المسیح یِسوعؔ کی سِی مَحَبّت ہے اَور مَیں تمہارا کِس قدر مُشتاق ہُوں۔","kẖudạ gwạḥ ḥai ḵḥ my̰rai dil mỹ̰ tmḥạrai lỷ̰ai ạlmsy̰ḥ y̰iswʿؔ ḵy̰ siy̰ maḥab̃t ḥai ạawr maỹ̰ tmḥạrạ ḵis qdr musẖtạq ḥū̃.",null],[1,9,"میری دعا ہے کہ تُم اَپنی مَحَبّت میں خُوب ترقّی کرو اَور تمہارا علم اَور رُوحانی تجربہ بھی بڑھتا چلا جائے،","my̰ry̰ dʿạ ḥai ḵḥ tum ạapny̰ maḥab̃t mỹ̰ kẖūb trq̃y̰ ḵrw ạawr tmḥạrạ ʿlm ạawr rūḥạny̰ tjrbḥ bʱy̰ bṛʱtạ cẖlạ jạỷai,",null],[1,10,"تاکہ تُمہیں مَعلُوم ہو سکے کہ کون سِی بات سَب سے اَچھّی ہے، اَور تُم المسیح کے واپسی کے دِن تک صَاف دِل اَور بے عیب رہو،","tạḵḥ tumḥỹ̰ maʿlūm ḥw sḵai ḵḥ ḵwn siy̰ bạt sab sai ạacẖʱ̃y̰ ḥai, ạawr tum ạlmsy̰ḥ ḵai wạpsy̰ ḵai din tḵ ṣāf dil ạawr bai ʿy̰b rḥw,",null],[1,11,"اَور یِسوعؔ المسیح کے وسیلہ سے راستبازی کے پھل سے بھرے رہو، تاکہ خُدا کا جلال ظاہر ہو اَور اُس کی سِتائش ہوتی رہے۔","ạawr y̰iswʿؔ ạlmsy̰ḥ ḵai wsy̰lḥ sai rạstbạzy̰ ḵai pʱl sai bʱrai rḥw, tạḵḥ kẖudạ ḵạ jlạl ẓạḥr ḥw ạawr ạus ḵy̰ sitạỷsẖ ḥwty̰ rḥai.",null],[1,12,"اَے بھائیو اَور بہنوں! میری خواہش ہے کہ تُمہیں یہ بات مَعلُوم ہو جائے کہ جو کچھ مُجھ پر گُزرا ہے وہ خُوشخبری کی ترقّی کا باعث ہُواہے۔","ạaai bʱạỷy̰w ạawr bḥnw̃! my̰ry̰ kẖwạḥsẖ ḥai ḵḥ tumḥỹ̰ y̰ḥ bạt maʿlūm ḥw jạỷai ḵḥ jw ḵcẖʱ mujʱ pr guzrạ ḥai wḥ kẖūsẖkẖbry̰ ḵy̰ trq̃y̰ ḵạ bạʿtẖ ḥūạḥai.",null],[1,13,"یہاں تک کہ شاہی محل کے تمام سپاہیوں اَور یہاں کے سَب لوگوں میں یہ بات مشہُور ہو گئی ہے کہ میں المسیح کے خادِم ہونے کی خاطِر قَید میں ہُوں۔","y̰ḥạ̃ tḵ ḵḥ sẖạḥy̰ mḥl ḵai tmạm spạḥy̰w̃ ạawr y̰ḥạ̃ ḵai sab lwgw̃ mỹ̰ y̰ḥ bạt msẖḥūr ḥw gỷy̰ ḥai ḵḥ mỹ̰ ạlmsy̰ḥ ḵai kẖạdim ḥwnai ḵy̰ kẖạṭir qay̰d mỹ̰ ḥū̃.",null],[1,14,"میرے قَید ہونے سے کیٔی بھایٔی اَور بہن جو خُداوؔند پر ایمان رکھتے ہیں، دِلیر ہو گیٔے ہیں، یہاں تک کہ وہ بے خوف ہوکر خُدا کا کلام سُنانے کی جُرأت کرنے لگے ہیں۔","my̰rai qay̰d ḥwnai sai ḵỷ̰y̰ bʱạỷ̰y̰ ạawr bḥn jw kẖudạwؔnd pr ạy̰mạn rḵʱtai ḥỹ̰, dily̰r ḥw gỷ̰ai ḥỹ̰, y̰ḥạ̃ tḵ ḵḥ wḥ bai kẖwf ḥwḵr kẖudạ ḵạ ḵlạm sunạnai ḵy̰ jurạ̉t ḵrnai lgai ḥỹ̰.",null],[1,15,"بعض تو حَسد اَور جھگڑے کی وجہ سے المسیح کی مُنادی کرتے ہیں، بعض نیک نیّتی سے۔","bʿḍ tw ḥasd ạawr jʱgṛai ḵy̰ wjḥ sai ạlmsy̰ḥ ḵy̰ munạdy̰ ḵrtai ḥỹ̰, bʿḍ ny̰ḵ nỹ̰ty̰ sai.",null],[1,16,"جو مَحَبّت کی وجہ سے مُنادی کرتے ہیں، وہ جانتے ہیں کہ خُدا نے مُجھے خُوشخبری کی حمایت کرنے کے لیٔے مُقرّر کیا ہے۔","jw maḥab̃t ḵy̰ wjḥ sai munạdy̰ ḵrtai ḥỹ̰, wḥ jạntai ḥỹ̰ ḵḥ kẖudạ nai mujʱai kẖūsẖkẖbry̰ ḵy̰ ḥmạy̰t ḵrnai ḵai lỷ̰ai muqr̃r ḵy̰ạ ḥai.",null],[1,17,"لیکن دُوسرے اِس مُعاملہ میں صَاف دِل نہیں ہیں، بَلکہ مُجھ سے حَسد کی وجہ سے المسیح کی مُنادی کرتے ہیں، تاکہ قَید میں بھی مُجھے رنج پہُنچائیں۔","ly̰ḵn dūsrai ạis muʿạmlḥ mỹ̰ ṣāf dil nḥỹ̰ ḥỹ̰, balḵḥ mujʱ sai ḥasd ḵy̰ wjḥ sai ạlmsy̰ḥ ḵy̰ munạdy̰ ḵrtai ḥỹ̰, tạḵḥ qay̰d mỹ̰ bʱy̰ mujʱai rnj pḥuncẖạỷỹ̰.",null],[1,18,"پس کیا ہُوا؟ اُن کی نیّت بُری ہو یا نیک، المسیح کی خُوشخبری تو سُنایٔی جاتی ہے۔ میں اِسی بات سے خُوش ہُوں۔ ہاں، اَور مَیں خُوش رہُوں گا۔","ps ḵy̰ạ ḥūạ? ạun ḵy̰ nỹ̰t bury̰ ḥw y̰ạ ny̰ḵ, ạlmsy̰ḥ ḵy̰ kẖūsẖkẖbry̰ tw sunạỷ̰y̰ jạty̰ ḥai. mỹ̰ ạisy̰ bạt sai kẖūsẖ ḥū̃. ḥạ̃, ạawr maỹ̰ kẖūsẖ rḥū̃ gạ.",null],[1,19,"کیونکہ مَیں جانتا ہُوں کہ تمہاری دعا اَور یِسوعؔ المسیح کے پاک رُوح کے لُطف و کرم کی وجہ سے مُجھے نَجات ملے گی۔","ḵy̰wnḵḥ maỹ̰ jạntạ ḥū̃ ḵḥ tmḥạry̰ dʿạ ạawr y̰iswʿؔ ạlmsy̰ḥ ḵai pạḵ rūḥ ḵai luṭf w ḵrm ḵy̰ wjḥ sai mujʱai najạt mlai gy̰.",null],[1,20,"میری دِلی خواہش اَور اُمّید یہ ہے کہ مُجھے کسی بات میں بھی شرمندگی کا مُنہ نہ دیکھنا پڑے، بَلکہ جَیسے میں ہمیشہ بڑی دِلیری سے المسیح کا جلال اَپنے جِسم سے ظاہر کرتا رہا ہوں وَیسے ہی کرتا رہُوں گا، خواہ میں زندہ رہُوں یا مَر جاؤں۔","my̰ry̰ dily̰ kẖwạḥsẖ ạawr ạum̃y̰d y̰ḥ ḥai ḵḥ mujʱai ḵsy̰ bạt mỹ̰ bʱy̰ sẖrmndgy̰ ḵạ munḥ nḥ dy̰ḵʱnạ pṛai, balḵḥ jay̰sai mỹ̰ ḥmy̰sẖḥ bṛy̰ dily̰ry̰ sai ạlmsy̰ḥ ḵạ jlạl ạapnai jism sai ẓạḥr ḵrtạ rḥạ ḥw̃ way̰sai ḥy̰ ḵrtạ rḥū̃ gạ, kẖwạḥ mỹ̰ zndḥ rḥū̃ y̰ạ mar jạw̉̃.",null],[1,21,"کیونکہ زندہ رہنا میرے لیٔے المسیح ہے، اَور مرنا نفع۔","ḵy̰wnḵḥ zndḥ rḥnạ my̰rai lỷ̰ai ạlmsy̰ḥ ḥai, ạawr mrnạ nfʿ.",null],[1,22,"لیکن اگر میرا جِسمانی طور پر زندہ رہنا، میرے کام کے لیٔے زِیادہ مفید ہے۔ میں کیا پسند کروں؟ میں نہیں جانتا۔","ly̰ḵn ạgr my̰rạ jismạny̰ ṭwr pr zndḥ rḥnạ, my̰rai ḵạm ḵai lỷ̰ai ziy̰ạdḥ mfy̰d ḥai. mỹ̰ ḵy̰ạ psnd ḵrw̃? mỹ̰ nḥỹ̰ jạntạ.",null],[1,23,"میں بڑی کَشمکش میں مُبتلا ہُوں: جی تو چاہتاہے کہ دُنیا کو خیرباد کہہ کر المسیح کے پاس جا رہُوں، کیونکہ یہ زِیادہ بہتر ہے؛","mỹ̰ bṛy̰ ḵasẖmḵsẖ mỹ̰ mubtlạ ḥū̃: jy̰ tw cẖạḥtạḥai ḵḥ duny̰ạ ḵw kẖy̰rbạd ḵḥḥ ḵr ạlmsy̰ḥ ḵai pạs jạ rḥū̃, ḵy̰wnḵḥ y̰ḥ ziy̰ạdḥ bḥtr ḥai;",null],[1,24,"پھر بھی میرا جِسمانی طور پر زندہ رہنا تمہارے لیٔے زِیادہ ضروُری ہے۔","pʱr bʱy̰ my̰rạ jismạny̰ ṭwr pr zndḥ rḥnạ tmḥạrai lỷ̰ai ziy̰ạdḥ ḍrwury̰ ḥai.",null],[1,25,"چنانچہ مُجھے اِس بات کا بڑا یقین ہے کہ میں زندہ رہُوں گا، بَلکہ تُم سَب کے ساتھ رہُوں گا تاکہ تُم ایمان میں ترقّی کرو اَور خُوش رہو،","cẖnạncẖḥ mujʱai ạis bạt ḵạ bṛạ y̰qy̰n ḥai ḵḥ mỹ̰ zndḥ rḥū̃ gạ, balḵḥ tum sab ḵai sạtʱ rḥū̃ gạ tạḵḥ tum ạy̰mạn mỹ̰ trq̃y̰ ḵrw ạawr kẖūsẖ rḥw,",null],[1,26,"اَور جَب مَیں تمہارے پاس پھر آؤں تو المسیح یِسوعؔ میں ہونے کی وجہ سے وہ فخر جو تُم مُجھ پر کرتے ہو، اَور بھی زِیادہ ہو جائے گا۔","ạawr jab maỹ̰ tmḥạrai pạs pʱr ậw̉̃ tw ạlmsy̰ḥ y̰iswʿؔ mỹ̰ ḥwnai ḵy̰ wjḥ sai wḥ fkẖr jw tum mujʱ pr ḵrtai ḥw, ạawr bʱy̰ ziy̰ạdḥ ḥw jạỷai gạ.",null],[1,27,"کچھ بھی ہو، اِتنا ضروُر کرو کہ تمہارا چال چلن المسیح کی خُوشخبری کے لائق ہو۔ تاکہ، خواہ میں تُمہیں دیکھنے آؤں یا نہ آؤں، یہ ضروُر سُن سکوں کہ تُم ایک رُوح میں قائِم ہو، اَور ایک جان ہوکر کوشش کر رہے ہو کہ لوگ خُوشخبری پر ایمان لائیں","ḵcẖʱ bʱy̰ ḥw, ạitnạ ḍrwur ḵrw ḵḥ tmḥạrạ cẖạl cẖln ạlmsy̰ḥ ḵy̰ kẖūsẖkẖbry̰ ḵai lạỷq ḥw. tạḵḥ, kẖwạḥ mỹ̰ tumḥỹ̰ dy̰ḵʱnai ậw̉̃ y̰ạ nḥ ậw̉̃, y̰ḥ ḍrwur sun sḵw̃ ḵḥ tum ạy̰ḵ rūḥ mỹ̰ qạyỉm ḥw, ạawr ạy̰ḵ jạn ḥwḵr ḵwsẖsẖ ḵr rḥai ḥw ḵḥ lwg kẖūsẖkẖbry̰ pr ạy̰mạn lạỷỹ̰",null],[1,28,"اَور یہ بھی کہ تُم کسی بات میں بھی اَپنے مُخالفوں سے خوفزدہ نہیں ہوتے۔ یہ اُن کے لیٔے تو ہلاکت کا، لیکن تمہارے لیٔے نَجات کا نِشان ہے اَور یہ خُدا کی طرف سے ہے۔","ạawr y̰ḥ bʱy̰ ḵḥ tum ḵsy̰ bạt mỹ̰ bʱy̰ ạapnai mukẖạlfw̃ sai kẖwfzdḥ nḥỹ̰ ḥwtai. y̰ḥ ạun ḵai lỷ̰ai tw ḥlạḵt ḵạ, ly̰ḵn tmḥạrai lỷ̰ai najạt ḵạ nisẖạn ḥai ạawr y̰ḥ kẖudạ ḵy̰ ṭrf sai ḥai.",null],[1,29,"کیونکہ المسیح کی خاطِر تُم پر یہ فضل ہُوا کہ نہ فقط خُداوؔند پر ایمان لاؤ، بَلکہ خُداوؔند کی خاطِر دُکھ بھی سہو،","ḵy̰wnḵḥ ạlmsy̰ḥ ḵy̰ kẖạṭir tum pr y̰ḥ fḍl ḥūạ ḵḥ nḥ fqṭ kẖudạwؔnd pr ạy̰mạn lạw̉, balḵḥ kẖudạwؔnd ḵy̰ kẖạṭir duḵʱ bʱy̰ sḥw,",null],[1,30,"تُم بھی اُسی طرح جدّوجہد کرتے رہو جِس طرح تُم نے مُجھے کرتے دیکھا تھا، اَور اَب بھی سُنتے ہو کہ میں اَب تک اُسی میں مصروف ہُوں۔","tum bʱy̰ ạusy̰ ṭrḥ jd̃wjḥd ḵrtai rḥw jis ṭrḥ tum nai mujʱai ḵrtai dy̰ḵʱạ tʱạ, ạawr ạab bʱy̰ suntai ḥw ḵḥ mỹ̰ ạab tḵ ạusy̰ mỹ̰ mṣrwf ḥū̃.",null],[2,1,"پس اگر المسیح میں تُم میں تسلّی اَور مَحَبّت سے حوصلہ، اَور پاک رُوح کی رِفاقت میں رحمدلی اَور ہمدردی پائی جاتی ہے،","ps ạgr ạlmsy̰ḥ mỹ̰ tum mỹ̰ tsl̃y̰ ạawr maḥab̃t sai ḥwṣlḥ, ạawr pạḵ rūḥ ḵy̰ rifạqt mỹ̰ rḥmdly̰ ạawr ḥmdrdy̰ pạỷy̰ jạty̰ ḥai,",null],[2,2,"تو میری یہ خُوشی پُوری کر دو کہ یکدل رہو، یکساں مَحَبّت رکھو، ایک جان ہو اَور ہم خیال رہو۔","tw my̰ry̰ y̰ḥ kẖūsẖy̰ pūry̰ ḵr dw ḵḥ y̰ḵdl rḥw, y̰ḵsạ̃ maḥab̃t rḵʱw, ạy̰ḵ jạn ḥw ạawr ḥm kẖy̰ạl rḥw.",null],[2,3,"تِفرقہ اَور فُضول فخر کے باعث کچھ نہ کرو۔ بَلکہ، فروتن ہوکر ایک شخص دُوسرے شخص کو اَپنے سے بہتر سمجھے۔","tifrqḥ ạawr fuḍwl fkẖr ḵai bạʿtẖ ḵcẖʱ nḥ ḵrw. balḵḥ, frwtn ḥwḵr ạy̰ḵ sẖkẖṣ dūsrai sẖkẖṣ ḵw ạapnai sai bḥtr smjʱai.",null],[2,4,"ہر ایک صِرف اَپنے مفاد کا نہیں بَلکہ دُوسروں کے مفاد کا بھی خیال رکھے۔","ḥr ạy̰ḵ ṣirf ạapnai mfạd ḵạ nḥỹ̰ balḵḥ dūsrw̃ ḵai mfạd ḵạ bʱy̰ kẖy̰ạl rḵʱai.",null],[2,5,"تمہارا مِزاج بھی وَیسا ہی ہو، جَیسا المسیح یِسوعؔ کا تھا:","tmḥạrạ mizạj bʱy̰ way̰sạ ḥy̰ ḥw, jay̰sạ ạlmsy̰ḥ y̰iswʿؔ ḵạ tʱạ:",null],[2,6,"اگرچہ وہ خُدا کی صورت پر تھے، پھر بھی یِسوعؔ نے خُدا کی برابری کو اَپنے قبضہ میں رکھنے کی چیز نہ سمجھا؛","ạgrcẖḥ wḥ kẖudạ ḵy̰ ṣwrt pr tʱai, pʱr bʱy̰ y̰iswʿؔ nai kẖudạ ḵy̰ brạbry̰ ḵw ạapnai qbḍḥ mỹ̰ rḵʱnai ḵy̰ cẖy̰z nḥ smjʱạ;",null],[2,7,"بَلکہ اَپنے آپ کو خالی کر دیا، اَور غُلام کی صورت اِختیار کرکے، اِنسانوں کے مُشابہ ہو گئے۔","balḵḥ ạapnai ập ḵw kẖạly̰ ḵr dy̰ạ, ạawr gẖulạm ḵy̰ ṣwrt ạikẖty̰ạr ḵrḵai, ạinsạnw̃ ḵai musẖạbḥ ḥw gỷai.",null],[2,8,"یِسوعؔ نے اِنسانی شکل میں ظاہر ہوکر، اَپنے آپ کو فروتن کر دیا اَور موت بَلکہ صلیبی موت تک فرمانبردار رہے!","y̰iswʿؔ nai ạinsạny̰ sẖḵl mỹ̰ ẓạḥr ḥwḵr, ạapnai ập ḵw frwtn ḵr dy̰ạ ạawr mwt balḵḥ ṣly̰by̰ mwt tḵ frmạnbrdạr rḥai!",null],[2,9,"اِس لیٔے خُدا نے یِسوعؔ کو نہایت ہی اُونچا درجہ دیا، اَور یِسوعؔ کو وہ نام عطا فرمایا جو ہر نام سے اعلیٰ ہے،","ạis lỷ̰ai kẖudạ nai y̰iswʿؔ ḵw nḥạy̰t ḥy̰ ạūncẖạ drjḥ dy̰ạ, ạawr y̰iswʿؔ ḵw wḥ nạm ʿṭạ frmạy̰ạ jw ḥr nạm sai ạʿly̰ ḥai,",null],[2,10,"تاکہ یِسوعؔ کے نام پر ہر کویٔی گھٹنوں کے بَل جُھک جائے، چاہے وہ آسمان پر ہو، چاہے زمین پر، چاہے زمین کے نیچے۔","tạḵḥ y̰iswʿؔ ḵai nạm pr ḥr ḵwỷ̰y̰ gʱṭnw̃ ḵai bal juʱḵ jạỷai, cẖạḥai wḥ ậsmạn pr ḥw, cẖạḥai zmy̰n pr, cẖạḥai zmy̰n ḵai ny̰cẖai.",null],[2,11,"اَور ہر ایک زبان خُدا باپ کے جلال کے لیٔے اقرار کرے، کہ یِسوعؔ المسیح ہی خُداوؔند ہیں۔","ạawr ḥr ạy̰ḵ zbạn kẖudạ bạp ḵai jlạl ḵai lỷ̰ai ạqrạr ḵrai, ḵḥ y̰iswʿؔ ạlmsy̰ḥ ḥy̰ kẖudạwؔnd ḥỹ̰.",null],[2,12,"پس اَے میرے عزیزو! جِس طرح تُم نے میری مَوجُودگی میں ہمیشہ میری فرمانبرداری کی ہے، اُسی طرح اَب میری غَیر مَوجُودگی میں بھی خُوب ڈرتے اَور کانپتے ہویٔے اَپنی نَجات کے کام کو جاری رکھو،","ps ạaai my̰rai ʿzy̰zw! jis ṭrḥ tum nai my̰ry̰ mawjūdgy̰ mỹ̰ ḥmy̰sẖḥ my̰ry̰ frmạnbrdạry̰ ḵy̰ ḥai, ạusy̰ ṭrḥ ạab my̰ry̰ gẖay̰r mawjūdgy̰ mỹ̰ bʱy̰ kẖūb ḍrtai ạawr ḵạnptai ḥwỷ̰ai ạapny̰ najạt ḵai ḵạm ḵw jạry̰ rḵʱw,",null],[2,13,"کیونکہ وہ خُدا ہی ہے جو تُم میں نیّت اَور عَمل دونوں کو پیدا کرتا ہے تاکہ اُس کا نیک اِرادہ پُورا ہو سکے۔","ḵy̰wnḵḥ wḥ kẖudạ ḥy̰ ḥai jw tum mỹ̰ nỹ̰t ạawr ʿaml dwnw̃ ḵw py̰dạ ḵrtạ ḥai tạḵḥ ạus ḵạ ny̰ḵ ạirạdḥ pūrạ ḥw sḵai.",null],[2,14,"اَور سَب کام کسی شکایت اَور حُجّت کے بغیر ہی کر لیا کرو،","ạawr sab ḵạm ḵsy̰ sẖḵạy̰t ạawr ḥuj̃t ḵai bgẖy̰r ḥy̰ ḵr ly̰ạ ḵrw,",null],[2,15,"تاکہ تُم بے عیب اَور پاک ہوکر بداخلاق اَور گُمراہ لوگوں کے درمیان، ”خُدا کے بے نُقص فرزندوں کی طرح اِس جہاں میں زندگی گُزارو۔“ تاکہ اُن میں تُم آسمان کے سِتاروں کی مانند چمکو","tạḵḥ tum bai ʿy̰b ạawr pạḵ ḥwḵr bdạkẖlạq ạawr gumrạḥ lwgw̃ ḵai drmy̰ạn, ”kẖudạ ḵai bai nuqṣ frzndw̃ ḵy̰ ṭrḥ ạis jḥạ̃ mỹ̰ zndgy̰ guzạrw.“ tạḵḥ ạun mỹ̰ tum ậsmạn ḵai sitạrw̃ ḵy̰ mạnnd cẖmḵw",null],[2,16,"اَور زندگی کا کلام پیش کرتے ہو تاکہ المسیح کے لوٹنے کے دِن مُجھے فخر ہو کہ نہ تو میری دَوڑ دھوپ فُضول گئی اَور نہ محنت بے فائدہ رہی۔","ạawr zndgy̰ ḵạ ḵlạm py̰sẖ ḵrtai ḥw tạḵḥ ạlmsy̰ḥ ḵai lwṭnai ḵai din mujʱai fkẖr ḥw ḵḥ nḥ tw my̰ry̰ dawṛ dʱwp fuḍwl gỷy̰ ạawr nḥ mḥnt bai fạỷdḥ rḥy̰.",null],[2,17,"اگر تمہارے ایمان اَور تمہاری خدمت کی قُربانی کے ساتھ مُجھے بھی اَپنی جان کی قُربانی دینا پڑے تو مُجھے خُوشی ہوگی، اَور مَیں تُم سَب کی خُوشی میں شریک ہو سکوں گا۔","ạgr tmḥạrai ạy̰mạn ạawr tmḥạry̰ kẖdmt ḵy̰ qurbạny̰ ḵai sạtʱ mujʱai bʱy̰ ạapny̰ jạn ḵy̰ qurbạny̰ dy̰nạ pṛai tw mujʱai kẖūsẖy̰ ḥwgy̰, ạawr maỹ̰ tum sab ḵy̰ kẖūsẖy̰ mỹ̰ sẖry̰ḵ ḥw sḵw̃ gạ.",null],[2,18,"اِسی طرح تُمہیں بھی خُوش ہوکر میری خُوشی میں شریک ہونا چاہئے۔","ạisy̰ ṭrḥ tumḥỹ̰ bʱy̰ kẖūsẖ ḥwḵr my̰ry̰ kẖūsẖy̰ mỹ̰ sẖry̰ḵ ḥwnạ cẖạḥỷai.",null],[2,19,"مُجھے خُداوؔند یِسوعؔ میں اُمّید ہے کہ میں تِیمُتھِیُس کو جلد ہی تمہارے پاس روانہ کر دُوں، تاکہ اُس سے تمہاری خیریت کی خبر سُن کر مُجھے بھی اِطمینان حاصل ہو۔","mujʱai kẖudạwؔnd y̰iswʿؔ mỹ̰ ạum̃y̰d ḥai ḵḥ mỹ̰ tiy̰mutʱiy̰us ḵw jld ḥy̰ tmḥạrai pạs rwạnḥ ḵr dū̃, tạḵḥ ạus sai tmḥạry̰ kẖy̰ry̰t ḵy̰ kẖbr sun ḵr mujʱai bʱy̰ ạiṭmy̰nạn ḥạṣl ḥw.",null],[2,20,"کیونکہ اُس کے علاوہ یہاں میرا کویٔی اَور ہم خیال نہیں جو سچّے دِل سے تمہارے لیٔے فِکرمند ہو۔","ḵy̰wnḵḥ ạus ḵai ʿlạwḥ y̰ḥạ̃ my̰rạ ḵwỷ̰y̰ ạawr ḥm kẖy̰ạl nḥỹ̰ jw scẖ̃ai dil sai tmḥạrai lỷ̰ai fiḵrmnd ḥw.",null],[2,21,"کیونکہ دُوسرے سبھی اَپنی اَپنی باتوں کی فکر میں ہیں، نہ کہ یِسوعؔ المسیح کی۔","ḵy̰wnḵḥ dūsrai sbʱy̰ ạapny̰ ạapny̰ bạtw̃ ḵy̰ fḵr mỹ̰ ḥỹ̰, nḥ ḵḥ y̰iswʿؔ ạlmsy̰ḥ ḵy̰.",null],[2,22,"لیکن تُم تِیمُتھِیُس کے کِردار سے واقف ہو کہ کِس طرح اُس نے ایک بیٹے کی طرح میرے ساتھ مِل کر خُوشخبری کی مُنادی کی خدمت اَنجام دی ہے۔","ly̰ḵn tum tiy̰mutʱiy̰us ḵai ḵirdạr sai wạqf ḥw ḵḥ ḵis ṭrḥ ạus nai ạy̰ḵ by̰ṭai ḵy̰ ṭrḥ my̰rai sạtʱ mil ḵr kẖūsẖkẖbry̰ ḵy̰ munạdy̰ ḵy̰ kẖdmt ạanjạm dy̰ ḥai.",null],[2,23,"پس، میں اُمّید کرتا ہُوں کہ جِتنی جلدی میری صورت حال واضح ہو جائے گی، میں اُسے تمہارے پاس بھیج دُوں گا۔","ps, mỹ̰ ạum̃y̰d ḵrtạ ḥū̃ ḵḥ jitny̰ jldy̰ my̰ry̰ ṣwrt ḥạl wạḍḥ ḥw jạỷai gy̰, mỹ̰ ạusai tmḥạrai pạs bʱy̰j dū̃ gạ.",null],[2,24,"بَلکہ مُجھے خُداوؔند پر بھروسا ہے کہ میں خُود بھی جلد ہی آ جاؤں گا۔","balḵḥ mujʱai kẖudạwؔnd pr bʱrwsạ ḥai ḵḥ mỹ̰ kẖūd bʱy̰ jld ḥy̰ ậ jạw̉̃ gạ.",null],[2,25,"لیکن مَیں نے اِپفرُدِتُسؔ کو تمہارے پاس بھیجنا ضروُری سمجھا، وہ میرا مسیحی بھایٔی، ہم خدمت اَور میری طرح المسیح کا سپاہی ہے، وہ تمہارا قاصِد ہے، جسے تُم نے میری ضروُرتیں پُوری کرنے کے لیٔے بھیجا تھا۔","ly̰ḵn maỹ̰ nai ạipfruditusؔ ḵw tmḥạrai pạs bʱy̰jnạ ḍrwury̰ smjʱạ, wḥ my̰rạ msy̰ḥy̰ bʱạỷ̰y̰, ḥm kẖdmt ạawr my̰ry̰ ṭrḥ ạlmsy̰ḥ ḵạ spạḥy̰ ḥai, wḥ tmḥạrạ qạṣid ḥai, jsai tum nai my̰ry̰ ḍrwurtỹ̰ pūry̰ ḵrnai ḵai lỷ̰ai bʱy̰jạ tʱạ.",null],[2,26,"وہ تُم سَب کا مُشتاق ہے اَور بے قرار بھی ہے کیونکہ تُم نے اُس کی بیماری کا حال سُنا تھا۔","wḥ tum sab ḵạ musẖtạq ḥai ạawr bai qrạr bʱy̰ ḥai ḵy̰wnḵḥ tum nai ạus ḵy̰ by̰mạry̰ ḵạ ḥạl sunạ tʱạ.",null],[2,27,"بے شک وہ اَپنی بیماری سے، مَرنے کے قریب تھا۔ لیکن خُدا نے اُس پر رحم کیا، اَور نہ صِرف اُس پر بَلکہ مُجھ پر بھی، تاکہ مُجھے غم پر غم نہ ہو۔","bai sẖḵ wḥ ạapny̰ by̰mạry̰ sai, marnai ḵai qry̰b tʱạ. ly̰ḵn kẖudạ nai ạus pr rḥm ḵy̰ạ, ạawr nḥ ṣirf ạus pr balḵḥ mujʱ pr bʱy̰, tạḵḥ mujʱai gẖm pr gẖm nḥ ḥw.",null],[2,28,"اِس لیٔے مُجھے خیال آیا کہ اُسے جلد اَز جلد روانہ کر دُوں، تاکہ جَب تُم اُسے پھر سے دیکھو تو خُوش ہو جاؤ اَور میری بےقراری بھی کم ہو جائے۔","ạis lỷ̰ai mujʱai kẖy̰ạl ậy̰ạ ḵḥ ạusai jld ạaz jld rwạnḥ ḵr dū̃, tạḵḥ jab tum ạusai pʱr sai dy̰ḵʱw tw kẖūsẖ ḥw jạw̉ ạawr my̰ry̰ baiqrạry̰ bʱy̰ ḵm ḥw jạỷai.",null],[2,29,"پس تُم اُس کا خُداوؔند میں اَپنا بھایٔی سمجھ کر گرم جوشی سے اِستِقبال کرنا، اَور اَیسے لوگوں کا اِحترام کرنا لازِم ہے،","ps tum ạus ḵạ kẖudạwؔnd mỹ̰ ạapnạ bʱạỷ̰y̰ smjʱ ḵr grm jwsẖy̰ sai ạistiqbạl ḵrnạ, ạawr ạay̰sai lwgw̃ ḵạ ạiḥtrạm ḵrnạ lạzim ḥai,",null],[2,30,"کیونکہ وہ المسیح کی خدمت کی خاطِر مَرنے کے قریب ہو گیا تھا۔ اَور اُس نے اَپنی جان کو خطرہ میں ڈال دیا تاکہ میری خدمت میں جو کمی تمہاری وجہ سے ہوئی وہ اُسے پُورا کر دے۔","ḵy̰wnḵḥ wḥ ạlmsy̰ḥ ḵy̰ kẖdmt ḵy̰ kẖạṭir marnai ḵai qry̰b ḥw gy̰ạ tʱạ. ạawr ạus nai ạapny̰ jạn ḵw kẖṭrḥ mỹ̰ ḍạl dy̰ạ tạḵḥ my̰ry̰ kẖdmt mỹ̰ jw ḵmy̰ tmḥạry̰ wjḥ sai ḥwỷy̰ wḥ ạusai pūrạ ḵr dai.",null],[3,1,"غرض، میرے بھائیو اَور بہنوں، خُداوؔند میں خُوش رہو! تُمہیں ایک ہی بات دوبارہ لکھنے میں مُجھے تو کچھ دِقّت نہیں، اَور تمہاری اِس میں حِفاظت ہے۔","gẖrḍ, my̰rai bʱạỷy̰w ạawr bḥnw̃, kẖudạwؔnd mỹ̰ kẖūsẖ rḥw! tumḥỹ̰ ạy̰ḵ ḥy̰ bạt dwbạrḥ lḵʱnai mỹ̰ mujʱai tw ḵcẖʱ diq̃t nḥỹ̰, ạawr tmḥạry̰ ạis mỹ̰ ḥifạẓt ḥai.",null],[3,2,"اُن کُتّوں سے خبردار رہو، اُن بدکرداروں سے اَور اُن سے جو ختنہ کروانے پر زور دیتے ہیں۔","ạun ḵut̃w̃ sai kẖbrdạr rḥw, ạun bdḵrdạrw̃ sai ạawr ạun sai jw kẖtnḥ ḵrwạnai pr zwr dy̰tai ḥỹ̰.",null],[3,3,"کیونکہ مختون تو ہم ہیں، جو خُدا کے رُوح کی ہدایت سے اُس کی عبادت کرتے ہیں، اَور المسیح یِسوعؔ پر فخر کرتے ہیں اَور جِسم پر بھروسا نہیں کرتے","ḵy̰wnḵḥ mkẖtwn tw ḥm ḥỹ̰, jw kẖudạ ḵai rūḥ ḵy̰ ḥdạy̰t sai ạus ḵy̰ ʿbạdt ḵrtai ḥỹ̰, ạawr ạlmsy̰ḥ y̰iswʿؔ pr fkẖr ḵrtai ḥỹ̰ ạawr jism pr bʱrwsạ nḥỹ̰ ḵrtai",null],[3,4,"اگرچہ میں تو جِسم پر بھروسا کر سَکتا ہُوں۔ لیکن اگر کویٔی جِسم پر بھروسا کرنے کا خیال کر سَکتا ہے، تو میں اُس سے بھی زِیادہ کر سَکتا ہُوں:","ạgrcẖḥ mỹ̰ tw jism pr bʱrwsạ ḵr saḵtạ ḥū̃. ly̰ḵn ạgr ḵwỷ̰y̰ jism pr bʱrwsạ ḵrnai ḵạ kẖy̰ạl ḵr saḵtạ ḥai, tw mỹ̰ ạus sai bʱy̰ ziy̰ạdḥ ḵr saḵtạ ḥū̃:",null],[3,5,"میری پیدائش کے سات دِن بعد آٹھویں دِن میرا ختنہ ہُوا، میں اِسرائیلی قوم اَور بِنیامین کے قبیلہ سے ہُوں، عِبرانیوں کا عِبرانی؛ شَریعت کے اِعتبار سے، میں ایک فرِیسی ہُوں؛","my̰ry̰ py̰dạỷsẖ ḵai sạt din bʿd ậṭʱwỹ̰ din my̰rạ kẖtnḥ ḥūạ, mỹ̰ ạisrạỷy̰ly̰ qwm ạawr biny̰ạmy̰n ḵai qby̰lḥ sai ḥū̃, ʿibrạny̰w̃ ḵạ ʿibrạny̰; sẖary̰ʿt ḵai ạiʿtbạr sai, mỹ̰ ạy̰ḵ friy̰sy̰ ḥū̃;",null],[3,6,"جوش کے اِعتبار سے، جماعت کا ستانے والا؛ شَریعت کی راستبازی کے اِعتبار سے، بے عیب۔","jwsẖ ḵai ạiʿtbạr sai, jmạʿt ḵạ stạnai wạlạ; sẖary̰ʿt ḵy̰ rạstbạzy̰ ḵai ạiʿtbạr sai, bai ʿy̰b.",null],[3,7,"لیکن جو کچھ میرے لیٔے نفع کا باعث تھا، مَیں نے اُسے المسیح کی خاطِر نُقصان سمجھ لیا ہے۔","ly̰ḵn jw ḵcẖʱ my̰rai lỷ̰ai nfʿ ḵạ bạʿtẖ tʱạ, maỹ̰ nai ạusai ạlmsy̰ḥ ḵy̰ kẖạṭir nuqṣạn smjʱ ly̰ạ ḥai.",null],[3,8,"بَلکہ میں اَپنے خُداوؔند المسیح یِسوعؔ کی پہچان کو اَپنی بڑی خُوبی سمجھتا ہُوں، جِن کی خاطِر مَیں نے دُوسری تمام چیزوں کا نُقصان اُٹھایا۔ اَور اُن چیزوں کو کُوڑا سمجھتا ہُوں، تاکہ المسیح کو حاصل کرلُوں","balḵḥ mỹ̰ ạapnai kẖudạwؔnd ạlmsy̰ḥ y̰iswʿؔ ḵy̰ pḥcẖạn ḵw ạapny̰ bṛy̰ kẖūby̰ smjʱtạ ḥū̃, jin ḵy̰ kẖạṭir maỹ̰ nai dūsry̰ tmạm cẖy̰zw̃ ḵạ nuqṣạn ạuṭʱạy̰ạ. ạawr ạun cẖy̰zw̃ ḵw ḵūṛạ smjʱtạ ḥū̃, tạḵḥ ạlmsy̰ḥ ḵw ḥạṣl ḵrlū̃",null],[3,9,"اَور المسیح میں پایا جاؤں، لیکن اَپنی شَریعت والی راستبازی کے ساتھ نہیں، بَلکہ اُس راستبازی کے ساتھ جو المسیح پر ایمان لانے سے حاصل ہوتی ہے۔ یہ راستبازی خُدا کی طرف سے ہے اَور ایمان کی بُنیاد پر مَبنی ہے۔","ạawr ạlmsy̰ḥ mỹ̰ pạy̰ạ jạw̉̃, ly̰ḵn ạapny̰ sẖary̰ʿt wạly̰ rạstbạzy̰ ḵai sạtʱ nḥỹ̰, balḵḥ ạus rạstbạzy̰ ḵai sạtʱ jw ạlmsy̰ḥ pr ạy̰mạn lạnai sai ḥạṣl ḥwty̰ ḥai. y̰ḥ rạstbạzy̰ kẖudạ ḵy̰ ṭrf sai ḥai ạawr ạy̰mạn ḵy̰ buny̰ạd pr mabny̰ ḥai.",null],[3,10,"میں یہی چاہتا ہُوں کہ المسیح کو اَور اُن کے جی اُٹھنے کی قُدرت کو جانوں، المسیح کے ساتھ دُکھوں میں شریک ہونے کا تجربہ حاصل کروں، اَور المسیح کی موت سے مُشابَہت پیدا کرلُوں،","mỹ̰ y̰ḥy̰ cẖạḥtạ ḥū̃ ḵḥ ạlmsy̰ḥ ḵw ạawr ạun ḵai jy̰ ạuṭʱnai ḵy̰ qudrt ḵw jạnw̃, ạlmsy̰ḥ ḵai sạtʱ duḵʱw̃ mỹ̰ sẖry̰ḵ ḥwnai ḵạ tjrbḥ ḥạṣl ḵrw̃, ạawr ạlmsy̰ḥ ḵy̰ mwt sai musẖạbaḥt py̰dạ ḵrlū̃,",null],[3,11,"تاکہ کسی طرح مُردوں میں سے جی اُٹھنے کے درجہ تک جا پہُنچوں۔","tạḵḥ ḵsy̰ ṭrḥ murdw̃ mỹ̰ sai jy̰ ạuṭʱnai ḵai drjḥ tḵ jạ pḥuncẖw̃.",null],[3,12,"اِس کا مطلب یہ نہیں کہ میں اُس مقصد کو پاچُکا ہُوں یا کامِل ہو چُکا ہُوں، بَلکہ میں اُس مقصد کو پانے کے لیٔے دَوڑا چلا جا رہا ہُوں جِس کے لیٔے المسیح یِسوعؔ نے مُجھے پکڑا تھا۔","ạis ḵạ mṭlb y̰ḥ nḥỹ̰ ḵḥ mỹ̰ ạus mqṣd ḵw pạcẖuḵạ ḥū̃ y̰ạ ḵạmil ḥw cẖuḵạ ḥū̃, balḵḥ mỹ̰ ạus mqṣd ḵw pạnai ḵai lỷ̰ai dawṛạ cẖlạ jạ rḥạ ḥū̃ jis ḵai lỷ̰ai ạlmsy̰ḥ y̰iswʿؔ nai mujʱai pḵṛạ tʱạ.",null],[3,13,"اَے میرے بھائیو اَور بہنوں! میرا یہ گمان نہیں کہ میں اُسے پاچُکا ہُوں۔ بَلکہ صِرف یہ کہہ سَکتا ہُوں: جو چیزیں پیچھے رہ گئی ہیں اُنہیں بھُول کر آگے کی چیزوں کی طرف بڑھتا جا رہا ہُوں،","ạaai my̰rai bʱạỷy̰w ạawr bḥnw̃! my̰rạ y̰ḥ gmạn nḥỹ̰ ḵḥ mỹ̰ ạusai pạcẖuḵạ ḥū̃. balḵḥ ṣirf y̰ḥ ḵḥḥ saḵtạ ḥū̃: jw cẖy̰zỹ̰ py̰cẖʱai rḥ gỷy̰ ḥỹ̰ ạunḥỹ̰ bʱūl ḵr ậgai ḵy̰ cẖy̰zw̃ ḵy̰ ṭrf bṛʱtạ jạ rḥạ ḥū̃,",null],[3,14,"اَور تیزی سے نِشانہ کی جانِب دَوڑا چلا جاتا ہُوں تاکہ وہ اِنعام حاصل کرلُوں جِس کے لیٔے خُدا نے مُجھے المسیح یِسوعؔ میں اُوپر آسمان پر بُلایا ہے۔","ạawr ty̰zy̰ sai nisẖạnḥ ḵy̰ jạnib dawṛạ cẖlạ jạtạ ḥū̃ tạḵḥ wḥ ạinʿạm ḥạṣl ḵrlū̃ jis ḵai lỷ̰ai kẖudạ nai mujʱai ạlmsy̰ḥ y̰iswʿؔ mỹ̰ ạūpr ậsmạn pr bulạy̰ạ ḥai.",null],[3,15,"لہٰذا، ہم میں سے جتنے رُوحانی طور پر بالغ ہیں، یہی خیال رکھیں۔ اَور اگر تمہارا کسی اَور قِسم کا خیال ہو، تو خُدا اُسے بھی تُم پر ظاہر کر دے گا۔","lḥdẖạ, ḥm mỹ̰ sai jtnai rūḥạny̰ ṭwr pr bạlgẖ ḥỹ̰, y̰ḥy̰ kẖy̰ạl rḵʱỹ̰. ạawr ạgr tmḥạrạ ḵsy̰ ạawr qism ḵạ kẖy̰ạl ḥw, tw kẖudạ ạusai bʱy̰ tum pr ẓạḥr ḵr dai gạ.",null],[3,16,"بہرحال جہاں تک ہم پہُنچ چُکے ہیں اُسی کے مُطابق چلتے جایٔیں۔","bḥrḥạl jḥạ̃ tḵ ḥm pḥuncẖ cẖuḵai ḥỹ̰ ạusy̰ ḵai muṭạbq cẖltai jạỷ̰ỹ̰.",null],[3,17,"اَے بھائیو اَور بہنوں! تُم سَب میرے نقش قدم پر چلو، اَور اُن لوگوں پر غور کرو جو ہمارے دئیے ہویٔے نمونہ پر چلتے ہیں۔","ạaai bʱạỷy̰w ạawr bḥnw̃! tum sab my̰rai nqsẖ qdm pr cẖlw, ạawr ạun lwgw̃ pr gẖwr ḵrw jw ḥmạrai dỷy̰ai ḥwỷ̰ai nmwnḥ pr cẖltai ḥỹ̰.",null],[3,18,"کیونکہ، بہت سے اَیسے ہیں جِن کا ذِکر میں بارہا کر چُکا ہُوں اَور اَب بھی تُم سے رو رو کر کہتا ہُوں، بہت سے لوگ اَپنے چال چلن سے المسیح کی صلیب کے دُشمن بَن کر جیتے ہیں۔","ḵy̰wnḵḥ, bḥt sai ạay̰sai ḥỹ̰ jin ḵạ dẖiḵr mỹ̰ bạrḥạ ḵr cẖuḵạ ḥū̃ ạawr ạab bʱy̰ tum sai rw rw ḵr ḵḥtạ ḥū̃, bḥt sai lwg ạapnai cẖạl cẖln sai ạlmsy̰ḥ ḵy̰ ṣly̰b ḵai dusẖmn ban ḵr jy̰tai ḥỹ̰.",null],[3,19,"اُن کا اَنجام ہلاکت ہے، اُن کا پیٹ ہی اُن کا خُدا ہے، وہ اَپنی اُن باتوں پرجو شرم کا باعث ہیں فخر کرتے ہیں۔ اَور دُنیوی چیزوں کے خیال میں لگے رہتے ہیں۔","ạun ḵạ ạanjạm ḥlạḵt ḥai, ạun ḵạ py̰ṭ ḥy̰ ạun ḵạ kẖudạ ḥai, wḥ ạapny̰ ạun bạtw̃ prjw sẖrm ḵạ bạʿtẖ ḥỹ̰ fkẖr ḵrtai ḥỹ̰. ạawr duny̰wy̰ cẖy̰zw̃ ḵai kẖy̰ạl mỹ̰ lgai rḥtai ḥỹ̰.",null],[3,20,"مگر ہمارا وطن آسمان پر ہے۔ اَور ہم اَپنے مُنجّی خُداوؔند یِسوعؔ المسیح کے وہاں سے، واپس آنے کے اِنتظار میں ہیں،","mgr ḥmạrạ wṭn ậsmạn pr ḥai. ạawr ḥm ạapnai munj̃y̰ kẖudạwؔnd y̰iswʿؔ ạlmsy̰ḥ ḵai wḥạ̃ sai, wạps ậnai ḵai ạintẓạr mỹ̰ ḥỹ̰,",null],[3,21,"المسیح اَپنی قُوّت سے ساری چیزوں کو اَپنے تابع کر سکتے ہیں، اِسی قُوّت کی تاثیر سے وہ ہمارے فانی بَدن کی شکل بدل کر اَپنے جلالی بَدن کی مانند بنا دیں گے۔","ạlmsy̰ḥ ạapny̰ qū̃t sai sạry̰ cẖy̰zw̃ ḵw ạapnai tạbʿ ḵr sḵtai ḥỹ̰, ạisy̰ qū̃t ḵy̰ tạtẖy̰r sai wḥ ḥmạrai fạny̰ badn ḵy̰ sẖḵl bdl ḵr ạapnai jlạly̰ badn ḵy̰ mạnnd bnạ dỹ̰ gai.",null],[4,1,"اِس لیٔے میرے عزیز بھائیو اَور بہنو، جِن کا میں مُشتاق ہُوں، اَور تُم جو میری خُوشی اَور میرا تاج ہو، اَے میرے عزیزو، خُداوؔند میں اِسی طرح قائِم رہو!","ạis lỷ̰ai my̰rai ʿzy̰z bʱạỷy̰w ạawr bḥnw, jin ḵạ mỹ̰ musẖtạq ḥū̃, ạawr tum jw my̰ry̰ kẖūsẖy̰ ạawr my̰rạ tạj ḥw, ạaai my̰rai ʿzy̰zw, kẖudạwؔnd mỹ̰ ạisy̰ ṭrḥ qạyỉm rḥw!",null],[4,2,"یُوؤدیہؔ اَور سُنتؔخے دونوں خواتین کو میری نصیحت یہ ہے کہ وہ خُداوؔند میں یکدل ہوکر رہیں۔","y̰ūw̉dy̰ḥؔ ạawr suntؔkẖai dwnw̃ kẖwạty̰n ḵw my̰ry̰ nṣy̰ḥt y̰ḥ ḥai ḵḥ wḥ kẖudạwؔnd mỹ̰ y̰ḵdl ḥwḵr rḥỹ̰.",null],[4,3,"اَور میرے سچّے ہم خدمت! میں تُم سے بھی درخواست کرتا ہُوں کہ اِن دونوں خواتین کی مدد کرو، کیونکہ اُنہُوں نے کلیمینت اَور میرے باقی ہم خدمتوں سمیت، میرے ساتھ خُوشخبری پھیلانے میں بڑی محنت کی، اِن سَب کے نام کِتاب حیات میں درج ہیں۔","ạawr my̰rai scẖ̃ai ḥm kẖdmt! mỹ̰ tum sai bʱy̰ drkẖwạst ḵrtạ ḥū̃ ḵḥ ạin dwnw̃ kẖwạty̰n ḵy̰ mdd ḵrw, ḵy̰wnḵḥ ạunḥū̃ nai ḵly̰my̰nt ạawr my̰rai bạqy̰ ḥm kẖdmtw̃ smy̰t, my̰rai sạtʱ kẖūsẖkẖbry̰ pʱy̰lạnai mỹ̰ bṛy̰ mḥnt ḵy̰, ạin sab ḵai nạm ḵitạb ḥy̰ạt mỹ̰ drj ḥỹ̰.",null],[4,4,"خُداوؔند میں ہر وقت خُوش رہو، میں پھر کہتا ہُوں: خُوش رہو!","kẖudạwؔnd mỹ̰ ḥr wqt kẖūsẖ rḥw, mỹ̰ pʱr ḵḥtạ ḥū̃: kẖūsẖ rḥw!",null],[4,5,"تمہاری نرم مِزاجی سَب لوگوں پر ظاہر ہو۔ خُداوؔند جلد واپس لَوٹنے والے ہیں۔","tmḥạry̰ nrm mizạjy̰ sab lwgw̃ pr ẓạḥr ḥw. kẖudạwؔnd jld wạps lawṭnai wạlai ḥỹ̰.",null],[4,6,"کسی بات کی فکر نہ کرو، اَور اَپنی سَب دعاؤں میں خُدا کے سامنے اَپنی ضروُرتیں، اَور مَنّتیں شُکر گُزاری کے ساتھ خُدا کے سامنے پیش کیا کرو۔","ḵsy̰ bạt ḵy̰ fḵr nḥ ḵrw, ạawr ạapny̰ sab dʿạw̉̃ mỹ̰ kẖudạ ḵai sạmnai ạapny̰ ḍrwurtỹ̰, ạawr mañtỹ̰ sẖuḵr guzạry̰ ḵai sạtʱ kẖudạ ḵai sạmnai py̰sẖ ḵy̰ạ ḵrw.",null],[4,7,"تَب خُدا کا وہ اِطمینان حاصل ہوگا، جو اِنسان کی سمجھ سے بالکُل باہر ہے، اَورجو تمہارے دِلوں اَور خَیالوں کو المسیح یِسوعؔ میں محفوظ رکھےگا۔","tab kẖudạ ḵạ wḥ ạiṭmy̰nạn ḥạṣl ḥwgạ, jw ạinsạn ḵy̰ smjʱ sai bạlḵul bạḥr ḥai, ạawrjw tmḥạrai dilw̃ ạawr kẖay̰ạlw̃ ḵw ạlmsy̰ḥ y̰iswʿؔ mỹ̰ mḥfwẓ rḵʱaigạ.",null],[4,8,"غرض، اَے میرے بھائیو اَور بہنوں! جِتنی باتیں سچ ہیں، لائق ہیں، مُناسب ہیں، پاک ہیں، دلکش ہیں اَور پسندِیدہ ہیں یعنی جو اَچھّی اَور قابل تعریف ہیں، اُن ہی باتوں پر غور کیا کرو۔","gẖrḍ, ạaai my̰rai bʱạỷy̰w ạawr bḥnw̃! jitny̰ bạtỹ̰ scẖ ḥỹ̰, lạỷq ḥỹ̰, munạsb ḥỹ̰, pạḵ ḥỹ̰, dlḵsẖ ḥỹ̰ ạawr psndiy̰dḥ ḥỹ̰ y̰ʿny̰ jw ạacẖʱ̃y̰ ạawr qạbl tʿry̰f ḥỹ̰, ạun ḥy̰ bạtw̃ pr gẖwr ḵy̰ạ ḵrw.",null],[4,9,"جو باتوں کو تُم نے مُجھ سے سیکھا یا حاصل کیا یا سُنا ہے یا مُجھ میں دیکھا بھی ہے، اُن پر عَمل کرتے رہوگے۔ تو خُدا جو اِطمینان کا چشمہ ہے تمہارے ساتھ رہے گا۔","jw bạtw̃ ḵw tum nai mujʱ sai sy̰ḵʱạ y̰ạ ḥạṣl ḵy̰ạ y̰ạ sunạ ḥai y̰ạ mujʱ mỹ̰ dy̰ḵʱạ bʱy̰ ḥai, ạun pr ʿaml ḵrtai rḥwgai. tw kẖudạ jw ạiṭmy̰nạn ḵạ cẖsẖmḥ ḥai tmḥạrai sạtʱ rḥai gạ.",null],[4,10,"مَیں خُداوؔند میں بہت خُوش ہُوں کہ اِتنی مُدّت کے بعد تُمہیں پھر سے میری مدد کرنے کا خیال آیا۔ بے شک، پہلے بھی تُمہیں میرا خیال تھا، مگر تُمہیں اُسے ظاہر کرنے کا موقع نہ مِلا تھا۔","maỹ̰ kẖudạwؔnd mỹ̰ bḥt kẖūsẖ ḥū̃ ḵḥ ạitny̰ mud̃t ḵai bʿd tumḥỹ̰ pʱr sai my̰ry̰ mdd ḵrnai ḵạ kẖy̰ạl ậy̰ạ. bai sẖḵ, pḥlai bʱy̰ tumḥỹ̰ my̰rạ kẖy̰ạl tʱạ, mgr tumḥỹ̰ ạusai ẓạḥr ḵrnai ḵạ mwqʿ nḥ milạ tʱạ.",null],[4,11,"میں یہ اِس لئے نہیں کہہ رہا ہُوں کہ مُحتاج ہُوں، کیونکہ مَیں نے کسی بھی حالات میں راضی رہنا سیکھ لیا ہے۔","mỹ̰ y̰ḥ ạis lỷai nḥỹ̰ ḵḥḥ rḥạ ḥū̃ ḵḥ muḥtạj ḥū̃, ḵy̰wnḵḥ maỹ̰ nai ḵsy̰ bʱy̰ ḥạlạt mỹ̰ rạḍy̰ rḥnạ sy̰ḵʱ ly̰ạ ḥai.",null],[4,12,"مَیں نے ناداری اَور فراوانی کے دِن بھی دیکھے ہیں، چاہے فاقہ کشی ہو یا آسودگی اَور کثرت ہو یا قِلّت ہر حالت میں مطمئن رہنا سیکھ لیا ہے۔","maỹ̰ nai nạdạry̰ ạawr frạwạny̰ ḵai din bʱy̰ dy̰ḵʱai ḥỹ̰, cẖạḥai fạqḥ ḵsẖy̰ ḥw y̰ạ ậswdgy̰ ạawr ḵtẖrt ḥw y̰ạ qil̃t ḥr ḥạlt mỹ̰ mṭmỷn rḥnạ sy̰ḵʱ ly̰ạ ḥai.",null],[4,13,"جو مُجھے طاقت بخشتا ہے اُس کی مدد سے میں سَب کچھ کر سَکتا ہُوں۔","jw mujʱai ṭạqt bkẖsẖtạ ḥai ạus ḵy̰ mdd sai mỹ̰ sab ḵcẖʱ ḵr saḵtạ ḥū̃.",null],[4,14,"تو بھی تُم نے اَچھّا کیا کہ میری مُصیبت میں شریک ہویٔے۔","tw bʱy̰ tum nai ạacẖʱ̃ạ ḵy̰ạ ḵḥ my̰ry̰ muṣy̰bt mỹ̰ sẖry̰ḵ ḥwỷ̰ai.",null],[4,15,"اَے اہلِ فِلپّی! تُم اَچھّی طرح جانتے ہو کہ شروع شروع میں جَب مَیں خُوشخبری سُناتا ہُوا، صُوبہ مَکِدُنیہؔ سے روانہ ہُوا تھا، تو تمہارے سِوا کسی جماعت نے لینے دینے کے مُعاملہ میں، میری مدد نہ کی؛","ạaai ạḥli filp̃y̰! tum ạacẖʱ̃y̰ ṭrḥ jạntai ḥw ḵḥ sẖrwʿ sẖrwʿ mỹ̰ jab maỹ̰ kẖūsẖkẖbry̰ sunạtạ ḥūạ, ṣūbḥ maḵiduny̰ḥؔ sai rwạnḥ ḥūạ tʱạ, tw tmḥạrai siwạ ḵsy̰ jmạʿt nai ly̰nai dy̰nai ḵai muʿạmlḥ mỹ̰, my̰ry̰ mdd nḥ ḵy̰;",null],[4,16,"جَب مَیں تھِسلُنِیکے شہر میں تھا، تو تُم نے میری ضرورتوں کو پُورا کرنے کے لیٔے ایک دفعہ نہیں بَلکہ دو دفعہ کچھ بھیجا تھا۔","jab maỹ̰ tʱisluniy̰ḵai sẖḥr mỹ̰ tʱạ, tw tum nai my̰ry̰ ḍrwrtw̃ ḵw pūrạ ḵrnai ḵai lỷ̰ai ạy̰ḵ dfʿḥ nḥỹ̰ balḵḥ dw dfʿḥ ḵcẖʱ bʱy̰jạ tʱạ.",null],[4,17,"یہ نہیں کہ میں تمہاری بھیجی ہُوئی رقم کا مُشتاق ہُوں؛ بَلکہ اَیسے اِنعام کی خواہش کرتا ہوں، جِس سے آپ کی رُوحانی برکتوں میں اِضافہ ہو جائے۔","y̰ḥ nḥỹ̰ ḵḥ mỹ̰ tmḥạry̰ bʱy̰jy̰ ḥūỷy̰ rqm ḵạ musẖtạq ḥū̃; balḵḥ ạay̰sai ạinʿạm ḵy̰ kẖwạḥsẖ ḵrtạ ḥw̃, jis sai ập ḵy̰ rūḥạny̰ brḵtw̃ mỹ̰ ạiḍạfḥ ḥw jạỷai.",null],[4,18,"میرے پاس سَب کچھ ہے بَلکہ کثرت سے ہے۔ تمہارے بھیجے ہویٔے تحفے اِپفرُدِتُسؔ کے ہاتھ سے مُجھے مِل گیٔے ہیں، اَور مَیں اَور بھی آسُودہ ہو گیا ہُوں۔ یہ خُوشبو اَور قُربانی اَیسی ہے، جو خُدا کی نظر میں پسندِیدہ ہے۔","my̰rai pạs sab ḵcẖʱ ḥai balḵḥ ḵtẖrt sai ḥai. tmḥạrai bʱy̰jai ḥwỷ̰ai tḥfai ạipfruditusؔ ḵai ḥạtʱ sai mujʱai mil gỷ̰ai ḥỹ̰, ạawr maỹ̰ ạawr bʱy̰ ậsūdḥ ḥw gy̰ạ ḥū̃. y̰ḥ kẖūsẖbw ạawr qurbạny̰ ạay̰sy̰ ḥai, jw kẖudạ ḵy̰ nẓr mỹ̰ psndiy̰dḥ ḥai.",null],[4,19,"میرا خُدا، المسیح یِسوعؔ کے ذریعہ اَپنے جلال کی دولت سے تمہاری تمام ضروُرتیں پُوری کر دے گا۔","my̰rạ kẖudạ, ạlmsy̰ḥ y̰iswʿؔ ḵai dẖry̰ʿḥ ạapnai jlạl ḵy̰ dwlt sai tmḥạry̰ tmạm ḍrwurtỹ̰ pūry̰ ḵr dai gạ.",null],[4,20,"ہمارے خُدا اَور باپ کی تمجید ہمیشہ تک ہوتی رہے۔ آمین۔","ḥmạrai kẖudạ ạawr bạp ḵy̰ tmjy̰d ḥmy̰sẖḥ tḵ ḥwty̰ rḥai. ậmy̰n.",null],[4,21,"ہر ایک مُقدّس سے المسیح یِسوعؔ میں سلام کہو۔ جو مسیحی بھایٔی اَور بہن میرے ساتھ ہیں، تُمہیں سلام کہتے ہیں۔","ḥr ạy̰ḵ muqd̃s sai ạlmsy̰ḥ y̰iswʿؔ mỹ̰ slạm ḵḥw. jw msy̰ḥy̰ bʱạỷ̰y̰ ạawr bḥn my̰rai sạtʱ ḥỹ̰, tumḥỹ̰ slạm ḵḥtai ḥỹ̰.",null],[4,22,"خُدا کے تمام مُقدّسین، خصوصاً تمام اہلِ ایمان جو قَیصؔر کے محل والوں میں سے ہیں، تُمہیں سلام کہتے ہیں۔","kẖudạ ḵai tmạm muqd̃sy̰n, kẖṣwṣạaⁿ tmạm ạḥli ạy̰mạn jw qay̰ṣؔr ḵai mḥl wạlw̃ mỹ̰ sai ḥỹ̰, tumḥỹ̰ slạm ḵḥtai ḥỹ̰.",null],[4,23,"خُداوؔند یِسوعؔ المسیح کا فضل تمہاری سَب کی رُوح کے ساتھ ہوتا رہے۔ آمین۔","kẖudạwؔnd y̰iswʿؔ ạlmsy̰ḥ ḵạ fḍl tmḥạry̰ sab ḵy̰ rūḥ ḵai sạtʱ ḥwtạ rḥai. ậmy̰n.",null]]}};
